	["{npc:1694}, beside him"] = "{npc:1694}, vedle něj",
	["{npc:1698}: blacksmiths only"] = "{npc:1698}: jen kováři",
	["{npc:1699}: Camping 101 asks you to learn it; below ground"] = "{npc:1699}: Camping 101 chce, aby ses to naučil; pod zemí",
	["{npc:1702} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1702} ho vezme, až budeš mít dovednost {skill:202} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:1702}, beside {npc:5392}"] = "{npc:1702}, vedle {npc:5392}",
	["{npc:2326} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2326} ho vezme, až budeš mít dovednost {skill:129} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:257446}, inside {area:77}"] = "{npc:257446}, uvnitř {area:77}",
