}
t.guides["forever/alliance/human/01-elwynn-forest"] = {
	["\"Auntie\" Bernice Stonefield"] = "\"Auntie\" Bernice Stonefield",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Zpět k {npc:6122}. Použij {item:6928} ve vyvolávacím kruhu ve sklepě {object:2164} a poraz voidwalkera, kterého přivolá.",
	["Back to {zone:1429}"] = "Zpět do {zone:1429}",
	["Billy plays in the {area:64}, east of the mine."] = "Billy si hraje v {area:64}, východně od dolu.",
	["Chunks of Boar Meat"] = "Chunks of Boar Meat",
	["Class trainer"] = "Trenér povolání",
	["Crystal Kelp Fronds"] = "Crystal Kelp Fronds",
	["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "Defias Rogue Wizards táboří na březích {area:86}; dropují i Red Linen Bandanas. {object:56} leží v murločí vesnici na severovýchodním břehu.\nPozor: Rogue Wizards sesílají z dálky a s nimi po břehu chodí {npc:6866} (10): tahej je po jednom.",
	["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Defias Thugs táboří na mýtině východně od opatství a podél východní strany údolí.",
	["Druid trainer"] = "Trenér druidů",
	["Follow the hills south to the tower, on the road west."] = "Jdi po kopcích na jih k věži, u cesty na západ.",
	["Follow the hills south to the tower."] = "Jdi po kopcích na jih k věži.",
	["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Jdi po stezce na sever k dolu. Před ním se hemží Kobold Workers; {object:83763} může dropnout každý kobold v údolí.",
	["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Jdi po silnici na východ kolem {area:91} k mostu. Dokonči Prowlers a Young Forest Bears kolem řeky jižně od něj.",
	["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Jdi po silnici na sever od {area:87} do {zone:1453}. {npc:5497} stojí ve Wizard's Sanctum, věži {object:2101}; dá ti láhev pro vodopád {quest:1861}.",
	["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Jdi po silnici na sever od {area:87} do {zone:1453}. {npc:6122} čeká ve sklepě {object:2164} v {object:2101}.",
	["Follow the road south out of the valley to {area:87}. {npc:240} stands outside the smithy on the west side of the road, {npc:241} by the road south of it, and {npc:295} and {npc:253} in the Lion's Pride Inn across the road."] = "Jdi po silnici na jih z údolí do {area:87}. {npc:240} stojí před kovárnou na západní straně silnice, {npc:241} u silnice jižně od ní a {npc:295} a {npc:253} v Lion's Pride Inn přes silnici.",
	["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Jdi po silnici na jih z {area:87} k {area:64}. {npc:251} čeká u domu.",
	["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "Jdi po silnici na jih k {area:120}, cestou do {zone:1436}. {npc:963} stojí před kasárnami; {npc:955} stojí uvnitř. {quest:91738} má jen tehdy, když neseš {item:247824}: promluv s ním a jde to rovnou k odevzdání.",
	["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Jdi po silnici na západ zpátky do {area:87}; {npc:6306} stojí na břehu jezera před městem. {npc:377} (kněží), {npc:328} (mágové) a {npc:917} (rogue) stojí nahoře v hostinci: jdi po schodech uvnitř, šipka patra nerozliší.",
	["Fun with Elementals: {npc:248464}"] = "Fun with Elementals: {npc:248464}",
	["He stands by the river west of the farm."] = "Stojí u řeky západně od farmy.",
	["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Vyjdi zpátky přes {area:87} a jdi po silnici na východ k {area:62}. {npc:881} (level 9) stojí u statku.",
	["Head east out of {area:87} along the lake shore. {npc:383} stands on the shore north-east of town."] = "Vyjdi z {area:87} na východ podél břehu jezera. {npc:383} stojí na břehu severovýchodně od města.",
	["Heal and fortify {npc:12423}"] = "Vyléč a posil {npc:12423}",
	["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "Pokud jsi vynechal {quest:91740}, grinduj tady do levelu 8.85, ať držíš plán trasy.",
	["If you skipped {quest:91752}, grind here to level 5.48 to stay on the route's plan."] = "Pokud jsi vynechal {quest:91752}, grinduj tady do levelu 5.48, ať držíš plán trasy.",
	["If you skipped {quest:91752}, grind here to level 5.77 to stay on the route's plan."] = "Pokud jsi vynechal {quest:91752}, grinduj tady do levelu 5.77, ať držíš plán trasy.",
	["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "Pokud jsi vynechal {quest:91775}, grinduj tady do levelu 8.39, ať držíš plán trasy.",
	["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Opusť {zone:1453} hlavní bránou. Vodopád pro {quest:1861} je jihozápadně od bran, po cestě na západ do {zone:1436}: naplň {item:7207} u jeho paty.",
	["Level 5.48"] = "Level 5.48",
	["Level 5.77"] = "Level 5.77",
	["Level 8.39"] = "Level 8.39",
	["Level 8.85"] = "Level 8.85",
	["Lost Books: Kobold Miners and Tunnelers"] = "Ztracené knihy: Kobold Miners a Tunnelers",
	["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "Mágové: {npc:198}, trenér mágů, stojí v Abbey nahoře: jdi po schodech uvnitř, šipka patra nerozliší.",
	["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Murloci a Murloc Streamrunners drží východní břeh; Junk Piles leží v jejich táboře. Pozor: murloci stojí blízko u sebe, takže v boji snadno stáhneš dva tři naráz: tahej je po jednom z okraje tábora a nehoň žádného do další skupiny.",
	["Painted Gnoll Armbands"] = "Painted Gnoll Armbands",
	["Red Burlap Bandanas"] = "Red Burlap Bandanas",
	["Red Linen Bandanas"] = "Red Linen Bandanas",
	["Subdue the voidwalker"] = "Podmaň si voidwalkera",
	["Tame {npc:1922}"] = "Ochoč {npc:1922}",
	["Tame {npc:524}"] = "Ochoč {npc:524}",
	["Tame {npc:822}"] = "Ochoč {npc:822}",
	["The Defias camp"] = "Tábor Defias",
	["The Fishing Traps sit along the west shore of the lake."] = "Fishing Traps jsou podél západního břehu jezera.",
	["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Bedny s hroznovým vínem leží na vinicích za Defias. {npc:103} čeká u chaty na východním konci údolí.",
	["The gnoll camps"] = "Tábory gnollů",
	["The kobold camp"] = "Tábor koboldů",
	["The lake shore"] = "Břeh jezera",
	["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "Důl je jihozápadně od táborů gnollů. U vchodu leží {item:247816}; tunely drží Kobold Geomancers.\nPozor: {npc:471} (7–10), Mine Spiders (7–9) a {npc:248474} (7) jsou elite hluboko v dole: pulluj koboldy po jednom u vchodu a když přijde elite, ustup ven; s kamarádem to jde snáz.",
	["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "Důl je západně od vinic. Obě patra plní Kobold Miners a Tunnelers; obrázkovou knihu drží ve spodních tunelech {npc:248464}, pojmenovaný kobold. {npc:248464} je elite: doporučuje se skupina.",
	["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too.\nCareful: {npc:276180}, a level 11 rare murloc, walks the river by {npc:261}' bridge, east of the Prowlers' woods: leave him be."] = "Chaluhy dropují murloci na východním břehu. Skinneři: lesem mezi jezerem a {area:91} se potulují Gray Forest Wolves; kůže dávají i Prowlers dál na východě.\nPozor: Řekou u mostu {npc:261} chodí {npc:276180}, rare murlok levelu 11, východně od lesa s Prowlers: nech ho být.",
	["The vineyards and {npc:103}"] = "Vinice a {npc:103}",
	["The {area:88}"] = "{area:88}",
	["The {area:91}"] = "{area:91}",
	["The {quest:91736}"] = "{quest:91736}",
	["Walk into the mine"] = "Vejdi do dolu",
	["Walk through the mine"] = "Projdi dolem",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Když už jsi tady: nauč se Staves u {npc:11867} ({object:2096}, 10 silver); při levelování má hůl víc kouzelných statů než jednoručka.",
	["grind on {npc:113}"] = "grinduj na {npc:113}",
	["grind on {npc:1922}"] = "grinduj na {npc:1922}",
	["grind on {npc:40}"] = "grinduj na {npc:40}",
	["grind on {npc:80}"] = "grinduj na {npc:80}",
	["{area:18}: kill these as you meet them"] = "{area:18}: zabíjej je, jak na ně narazíš",
	["{area:34}: kill these as you meet them"] = "{area:34}: zabíjej je, jak na ně narazíš",
	["{area:54}: kill these as you meet them"] = "{area:54}: zabíjej je, jak na ně narazíš",
	["{area:64}: kill these as you meet them"] = "{area:64}: zabíjej je, jak na ně narazíš",
	["{item:981}; below ground"] = "{item:981}; pod zemí",
	["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423} klečí zraněný u stromu na západním břehu {area:18}, mezi Fishing Traps. Sešli na něj {spell:613} (Rank 2), pak {spell:1243}: Rank 1 {spell:613} se nepočítá. Jakmile zaberou obě kouzla, odejde a vrátí se zhruba za 3 minuty.",
	["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430} vaří v kuchyni hostince. {npc:377} (kněží), {npc:328} (mágové) a {npc:917} (rogue) stojí nahoře v hostinci: vyjdi po schodech uvnitř, šipka nerozezná patra.",
	["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430}: Camping 101 chce, aby ses to naučil; pod zemí",
	["{npc:1632} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1632} ho vezme, až budeš mít dovednost {skill:165} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, vedle {npc:6306}",
	["{npc:1651} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1651} ho vezme, až budeš mít dovednost {skill:356} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: ochoč ho pomocí {item:15908}",
	["{npc:197}, inside"] = "{npc:197}, uvnitř",
	["{npc:2329} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2329} ho vezme, až budeš mít dovednost {skill:129} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:253}, inside"] = "{npc:253}, uvnitř",
	["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399} táboří severovýchodně od hostince. Když máš naučenou profesi, nabízí i její Camping 101, který si vezme její trenér: skinning, leatherworking a rybaření na břehu jezera, {skill:129} a blacksmithing v {area:87}.",
	["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}: pro {npc:1632} na břehu jezera",
	["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}: pro {npc:1651} na břehu jezera",
	["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}: pro {npc:2329} v Lion's Pride Inn",
	["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}: pro {npc:514} v kovárně v {area:87}",
	["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}: pro {npc:6306} na břehu jezera",
	["{npc:278}, inside"] = "{npc:278}, uvnitř",
	["{npc:279} in {zone:1453} takes it (02-westfall)"] = "Převezme ho {npc:279} v {zone:1453} (02-westfall)",
	["{npc:295}, inside"] = "{npc:295}, uvnitř",
	["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: vezme ho {npc:5497} v {zone:1453}",
	["{npc:375}, the priest trainer"] = "{npc:375}, trenér kněží",
	["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, trenér kněží: převezme ho {npc:377} v {area:87}",
	["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377} (kněží), {npc:328} (mágové) a {npc:917} (rogue) stojí nahoře v hostinci: jdi po schodech uvnitř, šipka patra nerozliší.",
	["{npc:377}, upstairs"] = "{npc:377}, nahoře",
	["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, nahoře: {item:16605}",
	["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}: vyleč {npc:12423} v {area:18}",
	["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377}: vezme ho {npc:376} v {zone:1453}",
	["{npc:459}, outside the Abbey"] = "{npc:459}, před Abbey",
	["{npc:476} walks around {area:54}: look inside the circle on the map"] = "{npc:476} chodí po {area:54}: hledej uvnitř kruhu na mapě",
	["{npc:514} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:514} ho vezme, až budeš mít dovednost {skill:164} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:514}, at the smithy across the road"] = "{npc:514}, v kovárně přes cestu",
	["{npc:514}, at the smithy beside Dughan: {npc:1416} in {zone:1453} takes it (02-westfall)"] = "{npc:514}, v kovárně vedle Dughana: převezme ho {npc:1416} v {zone:1453} (02-westfall)",
	["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: ochoč ho pomocí {item:15908}",
	["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: vezme ho {npc:6122} v {zone:1453}",
	["{npc:6306} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6306} ho vezme, až budeš mít dovednost {skill:393} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:6306}, inside"] = "{npc:6306}, uvnitř",
	["{npc:80} walks around {area:34}: look inside the circle on the map"] = "{npc:80} chodí po {area:34}: hledej uvnitř kruhu na mapě",
	["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: ochoč ho pomocí {item:15908}",
	["{npc:823}, at the Abbey steps"] = "{npc:823}, u schodů opatství",
	["{npc:823}, back at the Abbey steps"] = "{npc:823}, zpátky u schodů opatství",
	["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894} prodává Shiny Red Apples pro {quest:91736}. Počítají se i jablka lootnutá z koboldů a beden: nákup se odškrtne sám, jakmile máš čtyři.",
	["{npc:911}, the warrior trainer; inside"] = "{npc:911}, trenér warriorů; uvnitř",
	["{npc:915}, the rogue trainer"] = "{npc:915}, trenér rogue",
	["{npc:925}, the paladin trainer"] = "{npc:925}, trenér paladinů",
	["{npc:952}, upstairs"] = "{npc:952}, nahoře",
	["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955}: chce tvůj {item:247824}; uvnitř",
	["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}: pro {npc:234} v {area:108}",
	["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855} roste na polích kolem vinic a statku Stonefield; Stonetusk Boars kolem nich dávají krev.\nStonetusk Boars se pasou mezi vinicemi a statkem.",
	["{quest:76}'s entrance"] = "Vchod do {quest:76}",
	["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it.\nCareful: {npc:248464} (6), a kobold deep in the mine, is elite, and {npc:79} (10, rare) walks the tunnels: pull the kobolds one at a time."] = "{quest:87} je uvnitř {area:57}, ne na kopci nad ním: vejdi ústím a drž se vlevo až dozadu na dno dolu; po schodech nahoru nechoď. Defias Bandits kolem vinic občas dropnou {item:1972}: klikni na něj pravým.\nPozor: {npc:248464} (6), kobold hluboko v dole, je elite a {npc:79} (10, rare) chodí po tunelech: tahej koboldy po jednom.",
	["{quest:91733} and {npc:330}"] = "{quest:91733} a {npc:330}",
	["{zone:1429}: kill these as you meet them"] = "{zone:1429}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/alliance/nightelf/01-teldrassil"] = {
	["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sit u táboráku {npc:265811}, dokud nedostaneš {spell:1229451}",
	["Back at {area:256}"] = "Zpět v {area:256}",
	["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "Zpět z městské brány a na východ po cestě: {quest:1683} stojí jižně od ní, u {area:736}. Jeho roh přines zpět {quest:1684}.",
	["Back to the moonwell."] = "Zpět k moonwell.",
	["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Zpět na vrchol {area:256}. {object:654846} leží vedle něj.",
	["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "Zpět nahoru k {npc:3567} s hotovými webwoody a mechem {npc:272116}.",
	["Befouled Webwoods"] = "Befouled Webwoods",
	["Below ground"] = "Pod zemí",
	["Bloodfeather harpies"] = "Harpyje Bloodfeather",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn {area:493}'s flight path from {npc:10897}, south of the lake, for later trips. Then {npc:11800} in {area:2361} flies Druids straight to {area:702} from her gossip: hers is no flight path to learn. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. {npc:11802} je v {area:2361}; {quest:5929} sedí v lesích na severozápadě. Na pozdější cesty se nauč letovou trasu {area:493} od {npc:10897} jižně od jezera. Pak tě {npc:11800} v {area:2361} z rozhovoru přepraví rovnou do {area:702}: její let není letová trasa k naučení. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Crawler Legs: the Tide Crawlers"] = "Crawler Legs: Tide Crawlers",
	["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Každý Dazalarův quest ti dá {item:15908}: použij ji na zvíře, které jmenuje, pak mu hůl přines zpět do {area:186}. Webwood Lurkers lezou kolem vesnice, Nightsaber Stalkers a Strigid Screechers se toulají v lesích jižně od ní.",
	["East along the road to {area:186}."] = "Na východ po cestě do {area:186}.",
	["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Eskortuj {npc:275744} ven z mohyly; hlášení vezme {npc:2081} v {area:186}.",
	["Fandral in {zone:1457} takes it"] = "Fandral v {zone:1457} ho vezme",
	["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Fel Cones leží pod stromy všude kolem {area:186} a {npc:2150}: posbírej je cestou na východ a předej je {npc:2150} na cestě k {npc:7234}.",
	["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "Jen pro rybáře: {npc:10216} stojí na molu. Jeho {item:12238} se chytá přímo z mola.",
	["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Leť zpátky do {area:702} od {npc:3841}, předej {item:16263} {npc:10118} na molu, pak leť zpátky do {area:442}.",
	["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "Leť ještě jednou do {area:702} a vyjeď portálem nahoru k {npc:4217}, pak leť zpátky do {area:442}.",
	["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Jdi po silnici na jihozápad z {area:188}. {npc:2150} sedí vedle ní kousek východně od {area:186}.",
	["Follow the road west into {zone:1457} and use the {item:279378} at the inn on the {area:1659} and at the tunnel mouth below {area:3425} for the last two owls. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092}, {npc:7999}, {npc:7313} and {npc:8396} are in the Temple of the Moon at the south end."] = "Jdi po silnici na západ do {zone:1457} a pro poslední dvě sovy použij {item:279378} u hostince na {area:1659} a u ústí tunelu pod {area:3425}. {npc:4241} stojí na {area:1659} hned za vstupem do města. {npc:3516} je v {area:1658} na severním konci města, {quest:922} kousek jižně od něj; {npc:4092}, {npc:7999}, {npc:7313} a {npc:8396} jsou v Temple of the Moon na jižním konci.",
	["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Gnarlpine Ambushers se schovávají podél silnice západně od {area:258}.",
	["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Gnarlpine Mystics a {npc:7234} táboří severovýchodně od {area:260}. {npc:7234} dropuje {item:8049}: otevři ho, uvnitř je klenot.\nPozor: {npc:7234} čeká u ohně s mystiky kolem sebe, takže pullnout ho bez addů je těžké.",
	["Gnarlpine Shamans"] = "Gnarlpine Shamans",
	["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Vrať se dolů do {area:702} a leť do {area:442}. {object:177525} stojí v kopcích kousek východně od vesnice: použij tam {item:15208}, poraz Lunaclawa a promluv s {npc:12144}.",
	["Grells"] = "Grellové",
	["Grells (level 2-3) carry {item:3297} in the woods west of the tree, by the totems. The {npc:1989} further north are level 3-4: the Grells by the totems are enough."] = "Grellové (level 2–3) nosí {item:3297} v lese západně od stromu, u totemů. {npc:1989} dál na sever jsou level 3–4: Grellové u totemů stačí.",
	["Heal and fortify {npc:12429}"] = "Vyléč a posil {npc:12429}",
	["Into {zone:1457}"] = "Do {zone:1457}",
	["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Opusť {area:188} stezkou jihovýchodně od {area:256}: {npc:6780} stojí vedle ní, tam kde klesá k cestě do {area:186}.",
	["Level 12 spells while you're in the Temple of the Moon: the priest trainers stand beside {npc:11401}."] = "Kouzla na level 12, když jsi v Temple of the Moon: trenéři kněží stojí vedle {npc:11401}.",
	["Level 12 spells while you're in the {area:1658}: the hunter, rogue and druid trainers all stand in it."] = "Kouzla na level 12, když jsi v {area:1658}: trenéři hunterů, rogue a druidů stojí všichni v ní.",
	["Level 12 spells while you're on the {area:1660}: the warrior trainers stand beside {quest:1684}."] = "Kouzla na level 12, když jsi na {area:1660}: trenéři warriorů stojí vedle {quest:1684}.",
	["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "Mangy Nightsabers a Thistle Boars se toulají severně od {area:256}, cestou k jeskyni. {npc:1994} sedí hluboko uvnitř. {npc:8584} čeká mezi stromy západně od vchodu do jeskyně.",
	["Nightsabers"] = "Nightsabers",
	["Portal to {quest:940}"] = "Portál do {quest:940}",
	["Priest trainer"] = "Trenér kněží",
	["South-west of the barrow. The moonwell sits by the pools."] = "Jihozápadně od mohyly. Měsíční studna je u jezírek.",
	["Speak with the {quest:5929}"] = "Promluv s {quest:5929}",
	["Take the antidote from {npc:8583} at the foot of {area:256} only now, on the way down: it lasts five minutes. {npc:8584} waits north-west, by the cave: go straight on to him."] = "Protijed si od {npc:8583} u úpatí {area:256} vezmi až teď, cestou dolů: vydrží pět minut. {npc:8584} čeká na severozápadě, u jeskyně: jdi rovnou k němu.",
	["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "Vezmi portál dolů do {area:702}. {npc:10118} stojí na molu, {npc:3838} u hipogryfů. Jakmile máš {quest:6342}, promluv znovu s {npc:3838} a vyber let do {area:442}: je zdarma a přistane vedle {npc:4200}. Pokud se místo toho otevře mapa letů, zavři ji a promluv s ním znovu se stisknutým Shiftem.",
	["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Jdi znovu po cestě na severozápad z {area:186}; pořád leží vedle ní, na cestě do {zone:1457}.",
	["The Bloodfeather harpies nest on the slopes west and north of the glade. {quest:938}, an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "Harpyje Bloodfeather hnízdí na svazích západně a severně od mýtiny. {quest:938}, zraněná šavlozubá kočka, leží mezi nimi u západní stěny mýtiny: doveď ji zpátky k Sentinel Arynia u měsíční studny, než jí vyprší čas.\nPozor: Harpyje stojí natěsno, takže se do boje často přidají další. Mezi nimi jsou i casteři.",
	["The grells west of the tree"] = "Grellové západně od stromu",
	["The moonwell"] = "Měsíční studna",
	["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "Měsíční studna je uprostřed mýtiny. {object:6752} roste na jejím severním konci.",
	["The moonwell sits north of {area:256}."] = "Měsíční studna leží severně od {area:256}.",
	["The road to {zone:1457}"] = "Cesta do {zone:1457}",
	["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "Silnice na západ do {area:264} vede přes {area:186}: cestou předej {npc:3567} klenot.",
	["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "Trenéři stojí nahoře uvnitř {area:256}, podél rampy, která se vine stromem: {npc:3593} a {npc:3594} v prvním patře, {npc:3595} nad nimi, {npc:3596} a {npc:3597} úplně nahoře. Šipka patra nerozliší.",
	["The {area:265}"] = "{area:265}",
	["The {area:478}"] = "{area:478}",
	["The {object:177525}"] = "{object:177525}",
	["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Tide Crawlers lezou po pobřeží pod vesnicí; {quest:983} stojí na pláži kousek jižně od doků. Darkshore Threshers plavou na mělčině. {object:175207} leží na pobřeží kousek jižně od vesnice.",
	["Upstairs"] = "Nahoře",
	["Use the {item:18152} at the moonwell"] = "Použij {item:18152} u měsíční studny",
	["Use the {item:5185} at the moonwell"] = "Použij {item:5185} u měsíční studny",
	["Use the {item:5619} at the moonwell"] = "Použij {item:5619} u měsíční studny",
	["Use the {item:5621} at the moonwell"] = "Použij {item:5621} u měsíční studny",
	["Walk Lynessa out and keep her alive"] = "Doprovoď Lynessu ven a udrž ji naživu",
	["Warrior trainer"] = "Trenér warriorů",
	["Webwood Lurkers"] = "Webwood Lurkers",
	["Webwood Spiders; below ground"] = "Webwood Spiders; pod zemí",
	["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "Na západ po silnici k městu. Shayla chodí po tomhle úseku silnice, od šipky na jihozápad k zatáčce zhruba na 38,54 a zpět: když u šipky není, jdi po silnici na jihozápad. Každý furbolg Gnarlpine dropuje tesáky: počítají se ti ze zálohy na téhle silnici, z mohyly i z {area:261}.",
	["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors.\nCareful: {npc:272116}, a level 12 elite, prowls the east edge of the Befouled Webwoods north-west of {area:186}: if you are alone, keep clear of the webwoods and go round him."] = "Od pavučinových lesů na západ k {area:265}, pak podél něj na sever na mýtinu: timberlingové podél břehů dropují Mossy Tumors.\nPozor: {npc:272116}, elite na levelu 12, se plíží po východním okraji Befouled Webwoods severozápadně od {area:186}: když jsi sám, drž se od pavučinových lesů dál a obejdi ho.",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Když už jsi tady: nauč se Staves u {npc:11866} ({area:1660}, 10 silver); u zbraně na blízko huntera jde hlavně o staty a obouručky jich mají nejvíc.",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Když už jsi tady: nauč se Staves u {npc:11866} ({area:1660}, 10 silver); při levelování má hůl víc kouzelných statů než jednoručka.",
	["{area:1658} trainers"] = "Trenéři v {area:1658}",
	["{area:186} again"] = "{area:186} znovu",
	["{area:188}: kill these as you meet them"] = "{area:188}: zabíjej je, jak na ně narazíš",
	["{area:258}'s mouth"] = "Vchod do {area:258}",
	["{area:262}'s entrance"] = "Vchod do {area:262}",
	["{area:736}, outside the barrow"] = "{area:736}, před mohylou",
	["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159} od {npc:6736} pro {npc:6094}",
	["{item:8049}, from {npc:7234}"] = "{item:8049}, od {npc:7234}",
	["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}, v Temple of the Moon: Starshards",
	["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429} klečí zraněná na skalách na severním okraji {area:259}, cestou zpět do {area:186}, bez značky questu nad hlavou. Sešli na ni {spell:613} (Rank 2), pak {spell:1243}: Rank 1 {spell:613} se nepočítá. Jakmile zaberou obě kouzla, odběhne a vrátí se zhruba za 5 minut.",
	["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: ochoč ho pomocí {item:15908}",
	["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: ochoč ho pomocí {item:15908}",
	["{npc:2038}; below ground"] = "{npc:2038}; pod zemí",
	["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: ochoč ho pomocí {item:15908}",
	["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: vezme ho {quest:922} v {zone:1457}",
