	["{npc:8583}, east of the tree"] = "{npc:8583}, východně od stromu",
	["{object:126158}; inside"] = "{object:126158}; uvnitř",
	["{object:654846}, upstairs"] = "{object:654846}, nahoře",
	["{object:673378}, just west of the moonwell"] = "{object:673378}, kousek západně od měsíční studny",
	["{quest:1684} stands on the {area:1660}, just inside the city."] = "{quest:1684} stojí na {area:1660}, kousek za vstupem do města.",
	["{quest:2520}, standing in the temple's central fountain"] = "{quest:2520}, stojí v centrální fontáně chrámu",
	["{quest:917} and the antidote"] = "{quest:917} a protijed",
	["{quest:938}, by the west wall"] = "{quest:938}, u západní zdi",
	["{quest:940}: kill these as you meet them"] = "{quest:940}: zabíjej je, jak na ně narazíš",
