t.guides["forever/alliance/nightelf/02-darkshore"] = {
	["Back north to {area:447}: the flame burns in the south of the ruins."] = "Zpět na sever do {area:447}: plamen hoří na jihu ruin.",
	["Back north-east into the mountains to the crystal."] = "Zpět na severovýchod do hor ke krystalu.",
	["Bears and the Blackwood camp"] = "Medvědi a tábor Blackwood",
	["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}.\nCareful: the Windtalkers (13-14) cast from range and the furbolgs stand in pairs: pull them one at a time."] = "Blackwood Pathfinders a Windtalkers drží tábor jihovýchodně od {area:442}.\nPozor: Windtalkers (13–14) sesílají z dálky a furbolgové stojí ve dvojicích: tahej je po jednom.",
	["Blackwood furbolgs"] = "Furbolgové Blackwood",
	["Boat to {area:17203}"] = "Loď do {area:17203}",
	["Class trainer"] = "Trenér povolání",
	["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Vyšplhej do východních hor východně od {area:447}; {object:175524} sedí na římse.",
	["Crawler Legs: the Tide Crawlers"] = "Crawler Legs: Tide Crawlers",
	["Druid trainer"] = "Trenér druidů",
	["Fill the tube at the moonwell in the village"] = "Naplň zkumavku u měsíční studny ve vesnici",
	["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Jdi podél pobřeží na jih kolem {area:447}: jeden {quest:4728} leží na břehu západně od Grove, další dál na jih blízko {area:450}. Další tři ostatky leží dál na jihozápadě mezi Greymist Oracles a Tidehunters (18–20): návod je nechává na poslední okruh, až budeš blíž jejich levelu.",
	["Grell Earrings"] = "Grell Earrings",
	["Highborne Relics"] = "Highborne Relics",
	["Rabid Thistle Bears roam the hills south of {area:442}: use {item:7586} on one to capture it. Then walk up to the furbolg camp just east of them: nothing to kill yet."] = "Rabid Thistle Bears se potulují po kopcích jižně od {area:442}: použij na jednoho {item:7586} a chyť ho. Pak dojdi k furbolgímu táboru kousek na východ od nich: zatím tam nic nezabíjej.",
	["Read the {object:17188}"] = "Přečti {object:17188}",
	["Read the {object:17189}"] = "Přečti {object:17189}",
	["The red crystal"] = "Červený krystal",
	["The skeletal turtle"] = "Kostlivá želva",
	["The southern beaches"] = "Jižní pláže",
	["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Tide Crawlers lezou po pobřeží pod vesnicí; {quest:983} stojí na pláži kousek jižně od doků. Darkshore Threshers plavou na mělčině. {object:175207} leží na pobřeží kousek jižně od vesnice.",
	["Up the stairs in her shop: leave the shipment at the {object:460004}"] = "Nahoru po schodech v jejím obchodě: zásilku nech u {object:460004}",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Když už jsi tady: nauč se Swords u {npc:11867} ({object:2096}, 10 silver); s mečem v hlavní ruce rogue levluje spolehlivě.",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Když už jsi tady: nauč se {spell:202} u {npc:11867} ({object:2096}, 10 silver); s obouručkami warrior levluje nejrychleji.",
	["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289} na pláži západně od doků; pod vodou",
	["{npc:1646} stands in {object:2098}, west of the {object:2096}: his compass is in his old house in {zone:1436}, on the way."] = "{npc:1646} stojí v {object:2098}, západně od {object:2096}: jeho kompas je v jeho starém domě v {zone:1436}, po cestě.",
	["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} stojí na severním okraji ruin. Straší v nich Cursed, Writhing a {npc:2178}; mezi nimi chodí duch {npc:3667}, sova {npc:270196} krouží východně od nich. Obě desky leží v ruinách; {quest:4722} leží na břehu západně od nich.",
	["{npc:3649}, north end of the village"] = "{npc:3649}, severní konec vesnice",
	["{npc:3666}, upstairs in the inn"] = "{npc:3666}, nahoře v hostinci",
	["{npc:483}, in her cheese shop"] = "{npc:483}, ve svém obchodě se sýry",
	["{zone:1453} flight master"] = "letový mistr {zone:1453}",
}
t.guides["forever/alliance/skyborne/01-zephras-isle"] = {
	["\"Badwind\" Bennic, below ground"] = "\"Badwind\" Bennic, pod zemí",
	["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit u táboráku {npc:263664}, dokud nedostaneš {spell:1229451}",
	["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Al'Aketh Stormchasers a Footsoldiers táboří kousek severně od {npc:257944} a dropují dědictví; Shrieklings západně od ní dropují pera a drápy; {item:265105} roste podél potoka západně od ní.",
	["Back east out of the den to the grove."] = "Zpět na východ z doupěte do háje.",
	["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "Zpět v {quest:92529}: vesnici plní Stormcallers a {npc:251662}, Stormcallers nesou ukradené zásoby a {npc:251966} stojí na jejím jižním konci.",
	["Back to the Hermit"] = "Zpět k Poustevníkovi",
	["Back to {area:16622}"] = "Zpět do {area:16622}",
	["Back to {npc:252800} at the farmhouse."] = "Zpět k {npc:252800} na statek.",
	["Bandit Highwaymen"] = "Bandit Highwaymen",
	["Below ground"] = "Pod zemí",
	["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "Bolvar Fordragon stojí v trůnním sále {object:2117} na severním konci města. Pak odejdi hlavní branou do {zone:1436}.",
	["Cast {spell:1259705} at the {object:460002}"] = "Sešli {spell:1259705} u {object:460002}",
	["Class trainer"] = "Trenér povolání",
	["Desperate times"] = "Zoufalé časy",
	["Druid trainer"] = "Trenér druidů",
	["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Probojuj se na sever k {area:16629}. Přístup drží Guardians, Spiritcallers a Blademasters; {npc:253576} čeká u dveří svatyně, {npc:253590} uvnitř vnitřní svatyně.",
	["Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "Fillionův tábor je severozápadně od něj a Shriekling Matriarchs hnízdí kousek západně od tábora.",
	["Find {npc:258130}"] = "Najdi {npc:258130}",
	["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Jdi po silnici na jih do {area:16624}. {npc:263664} táboří u ohně západně od vesnice; {npc:251523} a {npc:251903} stojí uprostřed ní.",
	["For {npc:234} at {area:108}"] = "Pro {npc:234} v {area:108}",
	["Head north into {area:16631}. {npc:257944} camps in its east."] = "Jdi na sever do {area:16631}. {npc:257944} táboří na jeho východě.",
	["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them.\nThe Novice Seers practise in the clearing west of Shen'dar, on the way back to the village."] = "Jdi na severozápad k hnízdům hipogryfů na západních útesech. {item:263493} leží kolem hnízd; mezi nimi hlídkuje Matriarch.\nNovice Seers cvičí na mýtině západně od Shen'dar, cestou zpět do vesnice.",
	["Heal the injured druids in the Nightfang Den"] = "Vyléč zraněné druidy v Nightfang Den",
	["Highlands Bandits"] = "Highlands Bandits",
	["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Opusť {zone:1453} hlavní bránou. Vodopád pro {quest:1861} je jihozápadně od bran, po cestě na západ do {zone:1436}: naplň {item:7207} u jeho paty.",
	["Leave {zone:2521} to {zone:1416}"] = "Z {zone:2521} do {zone:1416}",
	["Level 14 spells while you're in {zone:1453}: warriors and rogues train in {object:2100}, hunters in the {object:28027}, mages in the Wizard's Sanctum of the {object:2101}. Druids train with {npc:5504} below."] = "Kouzla na level 14, když jsi v {zone:1453}: warrioři a rogue se učí v {object:2100}, hunteři v {object:28027}, mágové ve Wizard's Sanctum v {object:2101}. Druidi se učí u {npc:5504} dole.",
	["Level 14 spells while you're with {npc:5504}."] = "Kouzla na level 14, když jsi u {npc:5504}.",
	["Level 4 spells"] = "Kouzla na level 4",
	["Listen to {npc:252448}'s story"] = "Poslechni si příběh {npc:252448}",
	["Listen to {npc:257554}"] = "Poslechni si {npc:257554}",
	["Lorthuna waits up on the {area:16630}, east of the shrine: take the Portal to {area:16630} in the inner sanctum, beside Valennia, and cross the heights east to {npc:252475}. When she falls, the {object:617084} beside her takes you back to town."] = "Lorthuna čeká nahoře na {area:16630}, východně od svatyně: vezmi Portal to {area:16630} ve vnitřní svatyni vedle Valennie a přejdi výšiny na východ k {npc:252475}. Až padne, {object:617084} vedle ní tě vezme zpátky do města.",
	["Meet {npc:253844} at the gate"] = "Setkej se s {npc:253844} u brány",
	["Paladin trainer"] = "Trenér paladinů",
	["Portal to {area:16630}"] = "Portál do {area:16630}",
	["Prideclaws and Galestriders"] = "Prideclaws a Galestriders",
	["Prideclaws and Galestriders roam the grasslands around the village. Galestriders drop both the eggs and the meat: most players get the eggs from the ones just west of the village."] = "Prideclaws a Galestriders se potulují po travnatých pláních kolem vesnice. Galestrideři dropují vejce i maso: většina hráčů bere vejce z těch kousek na západ od vesnice.",
	["Priest trainer"] = "Trenér kněží",
	["Raw Windstones and the {npc:251404}"] = "Raw Windstones a {npc:251404}",
	["Standing our ground"] = "Držíme pozice",
	["Tame it with the {item:15908}"] = "Ochoč ho pomocí {item:15908}",
	["Tame {npc:250874}"] = "Ochoč {npc:250874}",
	["Tame {npc:251707}"] = "Ochoč {npc:251707}",
	["Tame {npc:254588}"] = "Ochoč {npc:254588}",
	["Tell {npc:252800} you're ready"] = "Řekni {npc:252800}, že jsi připraven",
	["The Bandit Highwaymen hold the hills north of the farm."] = "Bandit Highwaymen drží kopce severně od farmy.",
	["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp.\nCareful: the bandits stand in close groups and players often died in this camp: pull them one at a time from the edge."] = "Highlands Bandits táboří severovýchodně od vesnice. „Badwind“ Bennic čeká na nejsevernějším konci jejich tábora.\nPozor: banditi stojí v těsných skupinách a hráči v tomhle táboře často umírali: taháš je po jednom z okraje.",
	["The class trainers stand together in the grove"] = "Trenéři tříd stojí spolu v háji",
	["The dead cultist"] = "Mrtvý kultista",
	["The eastern watchtower"] = "Východní strážní věž",
	["The missing scholar"] = "Ztracený učenec",
	["The road to {area:16638}"] = "Cesta do {area:16638}",
	["The {area:16629}"] = "{area:16629}",
	["The {item:254871}"] = "{item:254871}",
	["The {object:581822}"] = "{object:581822}",
	["Underwater"] = "Pod vodou",
	["Upstairs"] = "Nahoře",
	["Valennia asks you to hear out both leaders: {npc:252475} of the Alliance and {npc:251968} of the Horde. {npc:251968}'s name shows red to you, but she talks to you all the same, and the quest needs both."] = "Valennia tě žádá, abys vyslechl oba vůdce: {npc:252475} z Aliance a {npc:251968} z Hordy. Jméno {npc:251968} se ti ukazuje červeně, ale mluví s tebou stejně a quest potřebuje oba.",
	["Village quests"] = "Questy ve vesnici",
	["Warlock trainer"] = "Trenér warlocků",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Když už jsi tady: nauč se Staves u {npc:11867} ({object:2096}, 10 silver); u zbraně na blízko huntera jde hlavně o staty a obouručky jich mají nejvíc.",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Když už jsi tady: nauč se Swords u {npc:11867} ({object:2096}, 10 silver); s mečem v hlavní ruce rogue levluje spolehlivě.",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Když už jsi tady: nauč se {spell:202} u {npc:11867} ({object:2096}, 10 silver); s obouručkami warrior levluje nejrychleji.",
	["{area:16622} turn-ins"] = "Odevzdání v {area:16622}",
	["{area:16622}: kill these as you meet them"] = "{area:16622}: zabíjej je, jak na ně narazíš",
