	["{item:252665}; below ground"] = "{item:252665}; pod zemí",
	["{item:257107}; below ground"] = "{item:257107}; pod zemí",
	["{npc:1646} stands in {object:2098}, on the way from the Keep to the main gate: his compass is in his old house in {zone:1436}, on the way."] = "{npc:1646} stojí v {object:2098}, cestou z pevnosti k hlavní bráně: jeho kompas je v jeho starém domě v {zone:1436}, po cestě.",
	["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
