	["{zone:1453} flight master"] = "letový mistr {zone:1453}",
}
t.guides["forever/class/druid/aquatic-form"] = {
	["At the {area:2362}"] = "U {area:2362}",
	["Back through {area:1637} to the zeppelin towers outside its main gate: the zeppelin to the {zone:1458} lands in {zone:1420}, and {zone:1421} is south of the {zone:1458}."] = "Zpět přes {area:1637} k věžím zeppelinů před hlavní branou: zeppelin do {zone:1458} přistává v {zone:1420} a {zone:1421} je jižně od {zone:1458}.",
	["Cast {spell:18960} to get here: {npc:11802} stands upstairs in the building beside where you land. {quest:28} runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until {npc:11799} has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "Sem se dostaneš přes {spell:18960}: {npc:11802} stojí nahoře v budově vedle místa přistání. {quest:28} běží na třicetiminutovém časovači: jakmile ho přijmeš, žádný teleport ani Hearthstone, dokud ho nemá {npc:11799}. Šest Bauble Containers (vázy) leží v úzkých prohlubních hluboko na dně {area:656} pod {area:2361}, často u bublajících trhlin ({object:177524} uprostřed jezera ti doplní dech); každá se vrátí tři minuty po otevření a berou je i jiní druidi. Než se vynoříš, zkontroluj, že máš {item:15877} v taškách: pět minut po lootnutí zmizí. Doplav s ní rovnou k {area:2362} na severozápadním břehu, použij ji v areálu svatyně a promluv s {npc:11799} u stromu.",
	["Cast {spell:18960} to get here: {npc:11802} stands upstairs in the building beside where you land. {quest:29} runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until {npc:11799} has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "Sem se dostaneš přes {spell:18960}: {npc:11802} stojí nahoře v budově vedle místa přistání. {quest:29} běží na třicetiminutovém časovači: jakmile ho přijmeš, žádný teleport ani Hearthstone, dokud ho nemá {npc:11799}. Šest Bauble Containers (vázy) leží v úzkých prohlubních hluboko na dně {area:656} pod {area:2361}, často u bublajících trhlin ({object:177524} uprostřed jezera ti doplní dech); každá se vrátí tři minuty po otevření a berou je i jiní druidi. Než se vynoříš, zkontroluj, že máš {item:15877} v taškách: pět minut po lootnutí zmizí. Doplav s ní rovnou k {area:2362} na severozápadním břehu, použij ji v areálu svatyně a promluv s {npc:11799} u stromu.",
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards {npc:11800}, in the middle of {area:2361}, flies druids straight to {area:702}."] = "Sešli {spell:18960}. S oběma polovinami v taškách si stoupni k {area:2362} na severozápadním břehu a spoj je pomocí {item:15883}, pak znovu sešli {spell:18960} (funguje i uvnitř {zone:1450}) a přistaneš u {npc:11802}. Stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší. Potom {npc:11800} uprostřed {area:2361} přepraví druidy rovnou do {area:702}.",
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:11798} flies druids to {area:1638}."] = "Sešli {spell:18960}. S oběma polovinami v taškách si stoupni k {area:2362} na severozápadním břehu a spoj je pomocí {item:15883}, pak znovu sešli {spell:18960} (funguje i uvnitř {zone:1450}) a přistaneš u {npc:11802}. Stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší. {npc:11798} vozí druidy do {area:1638}.",
	["Fly from {area:2361} to {area:442}. The {object:177792} lies far out on the sea floor off the north coast, between tall rocks west of where the {area:456} reaches the sea: it cannot be seen from the east side of the rocks. Watch your breath and the Darkshore Threshers; fight above water."] = "Leť z {area:2361} do {area:442}. {object:177792} leží daleko na mořském dně u severního pobřeží, mezi vysokými skalami západně od místa, kde {area:456} ústí do moře: z východní strany skal není vidět. Hlídej si dech a Darkshore Threshers; bojuj nad hladinou.",
	["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Head west to the coast: the {object:177790} lies far out on the sea floor beside a bubbling fissure (air), west of a sunken anchor. Sharks roam here; do not swim on past the wreck beyond it, the deep water brings fatigue."] = "Vezmi loď z {area:442} do {zone:1453} a leť do {area:108}. Jdi na západ k pobřeží: {object:177790} leží daleko na mořském dně vedle bublající pukliny (vzduch), západně od potopené kotvy. Plavou tu žraloci; neplav dál za vrak, v hluboké vodě přichází únava.",
	["Take the portal up to {npc:4217} in the {area:1658}. {quest:31}: swim fast and breathe underwater."] = "Vezmi portál nahoru k {npc:4217} v {area:1658}. {quest:31}: rychle plavat a dýchat pod vodou.",
	["Take the portal up to {npc:4217} in the {area:1658}. {quest:5061}: swim fast and breathe underwater."] = "Vezmi portál nahoru k {npc:4217} v {area:1658}. {quest:5061}: rychle plavat a dýchat pod vodou.",
	["Take {npc:11798}'s flight to {area:1638} and fly on to {area:1637}. The {object:177794} lies underwater in the {area:382} pond, a short walk out of {area:1637}'s west gate, in front of a wooden wall. The Venture Co. there are quick to join a fight: come in from the west to avoid most of them."] = "Leť letem od {npc:11798} do {area:1638} a dál do {area:1637}. {object:177794} leží pod vodou v rybníku {area:382}, kousek od západní brány {area:1637}, před dřevěnou stěnou. Venture Co. se tam rychle přidávají do boje: přijď od západu, ať se většině vyhneš.",
	["{item:15877}, from a {object:177785} in the lake"] = "{item:15877} z {object:177785} v jezeře",
	["{item:15882}, from the {object:177790}"] = "{item:15882}, od {object:177790}",
	["{item:15882}, from the {object:177844}"] = "{item:15882}, od {object:177844}",
	["{item:15883}, from the {object:177792}"] = "{item:15883}, od {object:177792}",
	["{item:15883}, from the {object:177794}"] = "{item:15883}, od {object:177794}",
	["{item:15885}: join the halves at the shrine"] = "{item:15885}: spoj poloviny u svatyně",
	["{npc:3033} stands in the druids' hut on {area:1639}."] = "{npc:3033} stojí v druidské chýši na {area:1639}.",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. Skyborne: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up."] = "{npc:4217} stojí nahoře v budově druidů v {area:1658}. Skyborne: sešli {spell:18960} a vezmi let od {npc:11800} uprostřed {area:2361} (druidy vozí do {area:702}, letovou trasu nepotřebuješ), pak portálem nahoru.",
}
t.guides["forever/class/druid/bear-form"] = {
	["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "Na 10 tě zastihne volání druidů: {npc:3064} v {area:222} nebo {npc:6746} v {zone:1456} (dopis {npc:6929} v {zone:1454} funguje taky). Kterýkoli z nich tě pošle k {npc:3033} na {area:1639} v {zone:1456}.",
	["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "Na 10 tě zastihne volání druidů: {npc:3602} v {area:186}, Denatharion v {zone:1457} nebo Theridran v {zone:1453}. Kterýkoli z nich tě pošle k {npc:4217} v Cenarion Enclave v Darnassu.",
	["Back to {npc:255853} by the falls."] = "Zpět k {npc:255853} u vodopádů.",
	["Back to {npc:3033} on {area:1639}."] = "Zpět k {npc:3033} na {area:1639}.",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, in {area:2361}. Learn the {area:493} flight path while you are here ({npc:12740} for the Horde, south-west of the lake; {npc:10897} for the Alliance, south of it)."] = "Sešli {spell:18960}: přistaneš vedle budovy, kde nahoře stojí {npc:11802}, v {area:2361}. Když už jsi tady, nauč se letovou trasu {area:493} ({npc:12740} pro Hordu, jihozápadně od jezera; {npc:10897} pro Alianci, jižně od něj).",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, past the armor vendor. The {quest:5929} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {area:493} flight path ({npc:10897}, south of the lake) for later, then take {npc:11800}'s flight from the middle of {area:2361}: she flies druids straight to {area:702}, no flight path needed. Take the portal up to {zone:1457}."] = "Sešli {spell:18960}: přistaneš vedle budovy, kde nahoře stojí {npc:11802}, za obchodníkem se zbrojí. {quest:5929} sedí v lesích na severozápadě. Promluv s ním a projdi všechna jeho slova (co představuje, síla těla, síla srdce, pak požádej o požehnání): rozhovor je cíl, žádný boj. Splývá se zemí, nemá značku questu a slabě modrošedě září u skupiny tří stromů: z {area:2361} jdi na západ podél úpatí severních hor, mezerou mezi stromy a kopci. Pokud tam {npc:11802} po návratu není, vyjdi ven a znovu sešli {spell:18960}. Na později se nauč letovou trasu {area:493} ({npc:10897} jižně od jezera), pak leť s {npc:11800} ze středu {area:2361}: druidy vozí rovnou do {area:702}, letová trasa není potřeba. Portálem nahoru do {zone:1457}.",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs. The {quest:5930} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {quest:5922} flight path ({npc:12740}, south-west of the lake); {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Sešli {spell:18960}: přistaneš vedle budovy, kde nahoře stojí {npc:11802}. {quest:5930} sedí v lesích na severozápadě. Promluv s ním a projdi všechna jeho slova (co představuje, síla těla, síla srdce, pak požádej o požehnání): rozhovor je cíl, žádný boj. Splývá se zemí, nemá značku questu a slabě modrošedě září u skupiny tří stromů: z {area:2361} jdi na západ podél úpatí severních hor, mezerou mezi stromy a kopci. Pokud tam {npc:11802} po návratu není, vyjdi ven a znovu sešli {spell:18960}. Nauč se letovou trasu {quest:5922} ({npc:12740}, jihozápadně od jezera); {npc:11798} v {area:2361} vozí druidy do {area:1638}.",
	["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Leť zpátky do {area:702} a vyjeď portálem nahoru k {npc:4217}.",
	["Fly from {area:702} to {area:442}. The {object:177525} stands inside the nearest moonkin cave east of the village: the northern of two small rock-pile caves where the {area:442} road meets the main north-south road. Moonkin (level 11-13) stand outside, the cave is empty: slip past them. Use the {item:15208} by the stone: Lunaclaw (level 12-13) walks in towards you and stays three minutes. Kill her, then speak to the {npc:12144} that appears and ask for the strength of her body and heart: the talk is the credit. Another druid's Lunaclaw gives you the spirit too."] = "Leť z {area:702} do {area:442}. {object:177525} stojí v nejbližší jeskyni moonkinů východně od vesnice: v severnější ze dvou malých jeskyní v hromadách kamení, kde se cesta z {area:442} potkává s hlavní severojižní silnicí. Moonkini (level 11–13) stojí venku, jeskyně je prázdná: proklouzni kolem nich. U kamene použij {item:15208}: Lunaclaw (level 12–13) přijde k tobě a zůstane tři minuty. Zabij ji, pak promluv s {npc:12144}, který se objeví, a požádej o sílu jejího těla a srdce: kredit dá ten rozhovor. Ducha ti dá i Lunaclaw jiného druida.",
	["Speak with the {quest:5929}"] = "Promluv s {quest:5929}",
	["Speak with the {quest:5930}"] = "Promluv s {quest:5930}",
	["The {object:177525}"] = "{object:177525}",
	["{npc:255853} and {npc:258443}"] = "{npc:255853} a {npc:258443}",
	["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459} stojí vedle {npc:259084} a Skyborne Portal západně od {area:279}, kde přistává skycutter ze {zone:2521}. Stejný quest nabízí i {npc:2543}.",
	["{npc:3033} stands in the druids' hut on {area:1639}, over the rope bridges east of the lifts. He teaches you {spell:18960} with the quest (it stays in your spellbook, Balance tab)."] = "{npc:3033} stojí v druidské chýši na {area:1639}, za provazovými mosty východně od výtahů. S questem tě naučí {spell:18960} (zůstane ti ve spellbooku, záložka Balance).",
	["{npc:3033} trains druids in the druids' hut on {area:1639}, over the rope bridges east of the lifts. He teaches you {spell:18960} with the next quest (it stays in your spellbook, Balance tab)."] = "{npc:3033} trénuje druidy v druidské chýši na {area:1639}, za provazovými mosty východně od výtahů. S dalším questem tě naučí {spell:18960} (zůstane ti ve spellbooku, záložka Balance).",
	["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222}; dopisy od Paly i Gryshky vedou na stejné místo",
	["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186}; dopisy od Denathariona i Theridrana vedou na stejné místo",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. He teaches you {spell:18960} with the quest (it stays in your spellbook, Balance tab)."] = "{npc:4217} stojí nahoře v budově druidů v {area:1658}. S questem tě naučí {spell:18960} (zůstane ti ve spellbooku, záložka Balance).",
	["{spell:5487} and {area:493}"] = "{spell:5487} a {area:493}",
}
t.guides["forever/class/druid/bloodpetal-poison"] = {
	["A five-player dungeon: needs a group of five, about level 50-55. Horde: fly to {area:75}; Alliance: fly to {area:1438} in the {zone:1419} and ride north. {area:1477} stands in the middle of the {area:74} in the {zone:1435}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. {npc:8580} (level 50 elite, {spell:12887} and {spell:6524}) only appears when the six serpent statues on the balcony ring above the altar pit are clicked in order: South, North, South-west, South-east, North-west, North-east (each turns green when right; a wrong order fails). Clear the trash by each statue and the pit below first; jumping down into the water is the quick way down, but a knockback near the edge can kill. The {item:22444} always drops."] = "Dungeon pro pět hráčů: potřebuje skupinu pěti, asi level 50–55. Horda: leť do {area:75}; Aliance: leť do {area:1438} v {zone:1419} a jeď na sever. {area:1477} stojí uprostřed {area:74} v {zone:1435}: vyjdi po schodech na jižní straně ruiny, skoč do zatopené síně, proplav dolů a sleduj schody a chodby dolů k portálu. {npc:8580} (level 50 elite, {spell:12887} a {spell:6524}) se objeví, jen když klikneš na šest hadích soch v kruhu balkonu nad oltářní jámou v pořadí: jih, sever, jihozápad, jihovýchod, severozápad, severovýchod (každá zezelená, když je to správně; špatné pořadí selže). Nejdřív vybij trash u každé sochy a v jámě pod nimi; skok dolů do vody je rychlá cesta dolů, ale odhození u okraje může zabít. {item:22444} padá vždy.",
	["Any {npc:6498} counts, the Ironhide and Tyrant Devilsaurs too. They are elite (level 54-55), hit with {spell:14099} and outrun travel form. Grouping up is encouraged, but a druid can do it alone: Hibernate or {spell:339} it from range, stab it with the {item:22432} (the barb does not break {spell:2637}), then leave. The credit counts the moment the barb lands, even if you die after. The arrow points at the plain Devilsaurs of the west and north; an {npc:6499} roams the middle of the crater's south, nearer {npc:9619}."] = "Počítá se kterýkoli {npc:6498}, i Ironhide a Tyrant Devilsaurs. Jsou elitní (level 54–55), bijí {spell:14099} a předběhnou travel form. Doporučuje se skupina, ale druid to zvládne sám: uspi ho Hibernate nebo {spell:339} z dálky, bodni ho {item:22432} (osten neruší {spell:2637}) a odejdi. Zásluha se počítá ve chvíli, kdy osten zasáhne, i když potom zemřeš. Šipka ukazuje na obyčejné Devilsaury na západě a severu; {npc:6499} se toulá středem jihu kráteru, blíž k {npc:9619}.",
	["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "Zpět k {npc:9619} do jihovýchodního rohu {zone:1449}.",
	["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer ({npc:3033}, {npc:4217} or Theridran in {zone:1453}) offers the same quest."] = "Sešli {spell:18960}. {npc:12042} stojí v {area:2361}; stejný quest nabízí trenér tvého povolání ({npc:3033}, {npc:4217} nebo Theridran v {zone:1453}).",
	["Eight of each. The Gorishi Wasps and Stingers (level 51-52) in and around the {area:540}, the hive in the south-west of the crater, drop a sting about one kill in seven; the wasps share spawn points with the other bugs, so kill whatever stands near you to make room for more wasps (respawn five minutes). The bugs' {spell:8137} makes you take more physical damage for 30 minutes; Workers call for help when hurt. The Bloodpetal Sprouts grow all over the crater (around {area:541} and the western half): open them, about every other one gives a {item:22434}, back in three to five minutes."] = "Osm od každého. Gorishi Wasps a Stingers (level 51–52) v {area:540} a kolem, úlu na jihozápadě kráteru, dropují žihadlo zhruba jedno zabití ze sedmi; vosy sdílejí místa spawnu s ostatním hmyzem, tak zabíjej, co stojí kolem, ať udělají místo dalším vosám (obnova pět minut). {spell:8137} hmyzu ti na 30 minut zvýší přijaté fyzické poškození; Workers při zranění volají o pomoc. Bloodpetal Sprouts rostou po celém kráteru (kolem {area:541} a v západní polovině): otevírej je, zhruba každý druhý dá {item:22434}, obnova za tři až pět minut.",
	["Experience in Un'Goro at 50 and two healing potions; the Classic item choice may be gone in Forever."] = "Zkušenosti v Un'Goro na 50 a dva léčivé lektvary; výběr předmětu z Classicu ve Foreveru možná chybí.",
	["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "Leť do {area:976}, jeď na západ k dlouhé rampě dolů do {zone:1449}: {npc:9619} táboří na jejím úpatí, v jihovýchodním rohu kráteru.",
	["Gorishi Stings and {item:22434}"] = "Gorishi Stings a {item:22434}",
	["Stab a {npc:6498} with the {item:22432}"] = "Bodni {npc:6498} pomocí {item:22432}",
	["The {area:1417}"] = "{area:1417}",
	["{npc:9619}: the old item choice may be gone, count on the experience"] = "{npc:9619}: stará volba předmětu možná zmizela, počítej se zkušenostmi",
}
t.guides["forever/class/druid/cat-form"] = {
	["Back to {npc:11802}"] = "Zpět do {npc:11802}",
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960} a přistaneš u {npc:11802} v {area:2361} (quest pro Skyborne na Zephras Isle nikdo nebere), pak leť s {npc:11798} do {area:1638}. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11800}'s flight to {area:702}: she stands in the middle of {area:2361} and flies druids there, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960} a přistaneš u {npc:11802} v {area:2361} (quest pro Skyborne na Zephras Isle nikdo nebere), pak leť s {npc:11800} do {area:702}: stojí uprostřed {area:2361} a druidy tam vozí, letová trasa není potřeba. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. {npc:11802} stojí nahoře ve své budově v {area:2361}: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. No {area:493} flight path yet? Learn it from {npc:10897}, south of the lake: the flight master in {area:2361} flies only Druids, from her gossip, and has none to learn."] = "Sešli {spell:18960}. {npc:11802} stojí nahoře ve své budově v {area:2361}: jdi nahoru uvnitř, šipka patra nerozliší. Ještě nemáš letovou trasu {area:493}? Nauč se ji od {npc:10897} jižně od jezera: letová mistryně v {area:2361} vozí jen druidy z rozhovoru a žádnou trasu k naučení nemá.",
	["Take the portal up to {npc:4217}, upstairs in the {area:1658}: he teaches you {spell:768}."] = "Vezmi portál nahoru k {npc:4217}, v patře {area:1658}: naučí tě {spell:768}.",
	["The relics of the Barrow Dens"] = "Relikvie z Barrow Dens",
	["The {area:2363}"] = "{area:2363}",
	["{npc:3033} on {area:1639} teaches you {spell:768}."] = "{npc:3033} na {area:1639} tě naučí {spell:768}.",
	["{npc:3033} stands in the druids' hut on {area:1639}. No {spell:1066} yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the {spell:1066} guide) is in the same {area:493}."] = "{npc:3033} stojí v druidské chýši na {area:1639}. Ještě nemáš {spell:1066}? Vezmi si od něj i A Lesson to Learn: taky vede k {npc:11802} a jeho Trial of the Lake (návod na {spell:1066}) je ve stejném {area:493}.",
	["{npc:4217} stands in the {area:1658}. Skyborne far from {zone:1457}: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No {spell:1066} yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the {spell:1066} guide) is in the same {area:493}."] = "{npc:4217} stojí v {area:1658}. Skyborne daleko od {zone:1457}: sešli {spell:18960} a vezmi let od {npc:11800} uprostřed {area:2361} (druidy vozí do {area:702}, letovou trasu nepotřebuješ), pak portálem nahoru. Ještě nemáš {spell:1066}? Vezmi si od něj i A Lesson to Learn: taky vede k {npc:11802} a jeho Trial of the Lake (návod na {spell:1066}) je ve stejném {area:493}.",
}
t.guides["forever/class/druid/cure-poison"] = {
	["Back in {area:442}, at the north end of the village."] = "Zpět v {area:442}, na severním konci vesnice.",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960} a zastav se u {npc:11802}, pak leť s {npc:11798} do {area:1638}. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed) and the portal up to {zone:1457}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960} a zastav se u {npc:11802}, pak leť s {npc:11800} ze středu {area:2361} (druidy vozí do {area:702}, letová trasa není potřeba) a portálem nahoru do {zone:1457}. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15842}. {npc:11798} flies druids to {area:1638}; fly on to the Crossroads from there."] = "Sešli {spell:18960}: {npc:11802} stojí nahoře v budově vedle tebe. Dá ti {item:15842}. {npc:11798} vozí druidy do {area:1638}; odtud leť dál do Crossroads.",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15844}. Then fly to {area:442} (learn the {zone:1450} flight path at Sindrayl first if you have not)."] = "Sešli {spell:18960}: {npc:11802} stojí nahoře v budově vedle tebe. Dá ti {item:15844}. Pak leť do {area:442} (pokud ji nemáš, nejdřív se u Sindrayl nauč letovou trasu {zone:1450}).",
	["Every {npc:3234} (level 14-15) drops a horn, but they are few and wander: search the far north near the {area:382} and the oases, above all the {area:388} south-east of the Crossroads. They charge from range and stomp. Herbalists find {item:2449} all over the northern {zone:1413}."] = "Každý {npc:3234} (level 14–15) dropne roh, ale je jich málo a toulají se: hledej na dalekém severu u {area:382} a oáz, hlavně {area:388} jihovýchodně od Crossroads. Útočí náporem z dálky a dupou. Bylinkáři najdou {item:2449} po celém severním {zone:1413}.",
	["From the Crossroads head north to {area:384} and climb to the bubbling {object:19464} on its summit. Burning Blade cultists camp around it: pull them one or two at a time. Stand in the water and use the {item:15842}: three Burning Blade Toxicologists (level 13-14, curses and warlock spells) appear and attack. You need not kill them: once the sampler is full, run."] = "Z Crossroads zamiř na sever k {area:384} a vyšplhej k bublajícímu {object:19464} na jeho vrcholu. Kolem táboří kultisté Burning Blade: tahej je po jednom nebo po dvou. Stoupni si do vody a použij {item:15842}: objeví se tři Burning Blade Toxicologists (level 13–14, kletby a warlockova kouzla) a zaútočí. Zabíjet je nemusíš: jakmile je vzorkovač plný, utíkej.",
	["He hands you the {item:15826}: ten doses, one per gazelle."] = "Dá ti {item:15826}: deset dávek, jednu na každou gazelu.",
	["Head north-east from {area:442} to {area:445}. Stand at the cave mouth at the top of the waterfall, not in the river below, and use the {item:15844} (not the {item:12350} of another quest). Naga line the climb, a caster waits on the far bank, and filling the sampler calls two more (a Wave Rider and a Toxicologist, level 15): clear the way first and be ready to fight."] = "Z {area:442} jdi na severovýchod do {area:445}. Stoupni si u ústí jeskyně nahoře u vodopádu, ne do řeky pod ním, a použij {item:15844} (ne {item:12350} z jiného questu). Cestu nahoru lemují nagy, na protějším břehu čeká caster a naplnění vzorkovače přivolá další dva (Wave Rider a Toxicologist, level 15): nejdřív si vyčisti cestu a buď připravený bojovat.",
	["Use the {item:15826} on Sickly Gazelles"] = "Použij {item:15826} na Sickly Gazelles",
	["Use the {item:15826} on living Sickly Gazelles (level 3): they graze on both sides of the road north of the Crossroads up to the {zone:1440} border, north-west of the Crossroads and west of {area:392}. Druid trick: root a gazelle with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time, so five gazelles can do. Lost a dose? Abandon and retake the quest from {npc:3448} for a fresh salve."] = "Použij {item:15826} na živé Sickly Gazelles (level 3): pasou se po obou stranách silnice severně od Crossroads až k hranici {zone:1440}, severozápadně od Crossroads a západně od {area:392}. Druidí trik: znehybni gazelu pomocí {spell:339}, nanes mast dřív, než kořeny tiknou, a zabití kořeny se započítá podruhé, takže stačí pět gazel. Přišel jsi o dávku? Zruš quest a vezmi si ho znovu od {npc:3448}, dostaneš novou mast.",
	["Use the {item:15826} on living {npc:12298} (level 5, a green cloud over them): they roam {zone:1439} from the {area:456} to the {zone:1440} border, many around the Blackwood furbolg camp north-east of {area:442}. Druid trick: root a deer with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time. Lost a dose on a deer that did not count? Abandon the quest and take it again from {npc:3702} for a fresh salve."] = "Použij {item:15826} na živé {npc:12298} (level 5, nad nimi zelený mrak): toulají se po {zone:1439} od {area:456} až k hranici {zone:1440}, hodně jich je kolem tábora furbolgů Blackwood severovýchodně od {area:442}. Druidí trik: znehybni jelena pomocí {spell:339}, nanes mast dřív, než kořeny tiknou, a zabití kořeny se započítá podruhé. Přišel jsi o dávku na jelena, který se nezapočítal? Zruš quest a vezmi si ho znovu od {npc:3702}, dostaneš novou mast.",
	["Use the {item:15826} on {npc:12298}"] = "Použij {item:15826} na {npc:12298}",
	["{item:15842}, standing in the pool"] = "{item:15842}, stoj v jezírku",
	["{item:15844}, at the cave mouth"] = "{item:15844} u vchodu do jeskyně",
	["{item:15851} and {item:2449}"] = "{item:15851} a {item:2449}",
	["{npc:3033} on {area:1639} teaches you {spell:8946}."] = "{npc:3033} na {area:1639} tě naučí {spell:8946}.",
	["{npc:3033} stands in the druids' hut on {area:1639}; {npc:262560}, the Skyborne druid trainer where the airship from Zephras Isle lands in northern {zone:1412}, gives the same quest. No {skill:182}? {npc:3490} at the Crossroads sells {item:2449} later, or buy five on the Auction House now."] = "{npc:3033} stojí v druidské chýši na {area:1639}; stejný quest dává {npc:262560}, druidský trenér Skyborne tam, kde v severní {zone:1412} přistává vzducholoď ze Zephras Isle. Nemáš {skill:182}? {npc:3490} na Crossroads prodává {item:2449} později, nebo si teď kup pět v aukci.",
	["{npc:3033}, or {npc:262560} in northern {zone:1412}"] = "{npc:3033}, nebo {npc:262560} v severní {zone:1412}",
	["{npc:3448} stands in the Crossroads. No {skill:182}? {npc:3490}, a few steps away by the wind rider master, sells {item:2449} for 80 copper each, three at a time until he restocks."] = "{npc:3448} stojí na Crossroads. Nemáš {skill:182}? {npc:3490}, pár kroků odsud u mistra wind riderů, prodává {item:2449} po 80 copper, po třech, než doplní zásoby.",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217} stojí nahoře v budově druidů v {area:1658}. Nemáš {skill:182}? Nejdřív si kup pět {item:2449} v aukci: později je budeš potřebovat.",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}; {npc:270459} by the Skyborne Portal does not give this quest. Cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217} stojí nahoře v budově druidů v {area:1658}; {npc:270459} u Skyborne Portal tenhle quest nedává. Sešli {spell:18960} a vezmi let od {npc:11800} uprostřed {area:2361} (druidy vozí do {area:702}, letovou trasu nepotřebuješ), pak portálem nahoru. Nemáš {skill:182}? Nejdřív si kup pět {item:2449} v aukci: později je budeš potřebovat.",
	["{npc:4217}, upstairs in the {area:1658}, teaches you {spell:8946}."] = "{npc:4217}, nahoře v {area:1658}, tě naučí {spell:8946}.",
}
t.guides["forever/class/hunter/rhokdelar"] = {
	["Back to the Ancients"] = "Zpět k Pradávným",
	["Before the demons"] = "Před démony",
	["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, stands in southern {zone:1447}, returns only every two to four days and drops it nearly every kill. The elite Cobalt dragonkin in and around {area:2245}, the cave south of {area:2255} in {zone:1452}, drop it about once in 200 kills; Manaclaw there a little more often. Skip the rest of this guide if you do not want the quiver."] = "Hastatův toulec vyžaduje {item:18704}. {npc:6109}, world boss pro raid, stojí v jižní části {zone:1447}, vrací se jen jednou za dva až čtyři dny a dropuje ho skoro při každém zabití. Elite dragonkin Cobalt v {area:2245} a okolí, jeskyni jižně od {area:2255} v {zone:1452}, ho dropují zhruba jednou za 200 zabití; Manaclaw tam o něco častěji. Pokud toulec nechceš, zbytek návodu přeskoč.",
	["Rhok'delar and Lok'delar"] = "Rhok'delar a Lok'delar",
	["The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring a {item:9224} ({skill:171} or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. {spell:19878}, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head."] = "Ti čtyři démoni jsou elite levelu 60 přestrojení za přátelské poutníky; promluv s jedním, řekni mu, že víš, co je zač, a promění se do démonské podoby. Každého bojuj sám: žádný pet (propusť ho), žádný heal, buff ani útok od jiného hráče, jakmile boj začne, jinak tě démon nazve zbabělcem a zmizí a na jeho návrat čekáš 3 hodiny (stejně tak po jeho smrti). Buffy a lektvary před pullem jsou v pořádku a kamarád může stát opodál a zabíjet potulné monstra nebo nepřátelské hráče, dokud se nedotkne démona ani tebe. Přines {item:9224} ({skill:171} nebo aukce), Major Mana Potions na dlouhé kitování a pokud můžeš, zbraň na blízko s enchantem Demonslaying. {spell:19878} od trenéra ti ukáže přestrojené démony na minimapě. Ve skupině nastav loot na free for all, abys mohl vylootovat hlavu.",
	["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "Řetězec epického luku pro huntera: v Classicu se z hole a šlachy staly Rhok'delar a Lok'delar (ve Foreveru nepotvrzeno).",
	["The {item:18703}"] = "{item:18703}",
	["Vartrus, Stoma and {npc:14526} are petrified trees on a small island in a ring-shaped lake in {area:1767}, north {zone:1448}. Their spirits only appear when someone carrying the leaf climbs the island's little hill to its east edge. Alliance: fly to {area:1998}; Horde: fly to {area:1997}. Vartrus gives {quest:7636}, Stoma A Proper String, Hastat the quiver; each can be handed in on its own."] = "Vartrus, Stoma a {npc:14526} jsou zkamenělé stromy na ostrůvku v prstencovém jezeře v {area:1767} na severu {zone:1448}. Jejich duchové se ukážou jen tehdy, když někdo s listem vyleze na malý kopec ostrůvku k jeho východnímu okraji. Aliance: leť do {area:1998}; Horda: leť do {area:1997}. Vartrus dává {quest:7636}, Stoma A Proper String, Hastat toulec; každý jde odevzdat samostatně.",
	["{area:2717} is a 40-player raid inside {area:254}. When {npc:12018} yields, the {object:179703} appears; it holds the {item:18703} about half the time, one per kill, so it may take several weeks of raids. Right-click the leaf to start the quest."] = "{area:2717} je raid pro 40 hráčů uvnitř {area:254}. Když se {npc:12018} vzdá, objeví se {object:179703}; asi v polovině případů obsahuje {item:18703}, jeden za zabití, takže to může trvat několik týdnů raidů. Kliknutím pravým na list spustíš quest.",
	["{item:18704}, from {npc:6109}"] = "{item:18704}, od {npc:6109}",
	["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}: v Classicu Lok'delar",
	["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}: toulec, poslední v tomhle návodu",
	["{npc:14527}, a troll with a wolf, walks a long path that starts at the lake in western Un'Goro and can reach the south of the crater; use {spell:19878}. Talk to her and she becomes {npc:14533}, and her wolf Precious a Felstalker. The hardest of the four: Freezing Trap Precious and pull Simone well away from it, or kite Precious away and kill it first, let Simone reset and come back for her alone. Her {spell:421} hits hard, so drain her mana with {spell:3034} (a 15-second cooldown on Forever) and keep her busy; her {spell:23205} cuts your ranged attack power, so finish her in melee. Loot her head before Precious breaks free."] = "{npc:14527}, trollka s vlkem, chodí po dlouhé trase, která začíná u jezera v západním Un'Goro a může dojít až na jih kráteru; použij {spell:19878}. Promluv s ní a změní se v {npc:14533} a její vlk Precious ve Felstalkera. Nejtěžší ze čtyř: dej Precious do Freezing Trap a odtáhni Simone daleko od něj, nebo Precious odkituj a zabij první, nech Simone resetnout a vrať se pro ni samotnou. Její {spell:421} bolí, tak jí vysávej manu pomocí {spell:3034} (ve Forever cooldown 15 sekund) a zaměstnávej ji; její {spell:23205} snižuje tvůj ranged attack power, takže ji dodělej na blízko. Hlavu z ní lootni dřív, než se Precious osvobodí.",
	["{npc:14529}, a human, wanders the western {zone:1428} south of {area:254}. Talk to him and he becomes {npc:14534}, the easiest of the four. Keep {spell:3043} on him the whole fight: while it lasts he barely hurts you. When he goes into {spell:23257}, remove it with {spell:19801} and never stand in melee while it is up; between frenzies you can fight him in melee with {spell:2974} and {spell:2973}. He cannot leave the {zone:1428}, so kite him around the trees if needed."] = "{npc:14529}, člověk, bloudí po západním {zone:1428} jižně od {area:254}. Promluv s ním a změní se v {npc:14534}, nejlehčího ze čtyř. Celý boj na něm drž {spell:3043}: dokud trvá, skoro ti neublíží. Když přejde do {spell:23257}, odstraň to pomocí {spell:19801} a dokud to trvá, nikdy nestůj na blízko; mezi záchvaty s ním můžeš bojovat na blízko s {spell:2974} a {spell:2973}. {zone:1428} nemůže opustit, takže ho v případě potřeby kituj kolem stromů.",
	["{npc:14531}, a tauren, walks a loop in the rocks of northern {zone:1452}, north of {area:2255}. Talk to him and he becomes {npc:14535}. Within 30 yards of him {spell:23298} hits hard: keep your distance and kite him the whole fight, {spell:5118} on, south down the road. {spell:1978} on him adds {spell:23299}, extra Nature damage, so keep it ticking while you run; his {spell:23257} can be removed with {spell:19801}, but distance matters more. It is a long fight: bring mana potions and plan your kiting path."] = "{npc:14531}, tauren, chodí po okruhu ve skalách severního {zone:1452}, severně od {area:2255}. Promluv s ním a změní se v {npc:14535}. Do 30 yardů od něj tvrdě bije {spell:23298}: drž si odstup a celý boj ho kituj, se zapnutým {spell:5118}, po cestě na jih. {spell:1978} na něm přidá {spell:23299}, extra Nature poškození, tak ho během běhu udržuj; jeho {spell:23257} jde odstranit pomocí {spell:19801}, ale důležitější je vzdálenost. Je to dlouhý boj: vezmi si lektvary many a naplánuj si trasu kitování.",
	["{npc:14536}, a gnome, walks around the gates of {area:3428} in the far south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. He enrages with {spell:23272} as he turns: drop a {spell:13809}, {spell:5384}, and he resets without the enrage. {spell:2974} roots him for a long time; while rooted he fears you and sends beetles ({npc:14761}): kill them fast with traps and {spell:2643} before they wear you down."] = "{npc:14536}, gnóm, chodí kolem bran {area:3428} na dalekém jihozápadě {zone:1451}. Promluv s ním a změní se v {npc:14530}. Při otočení se rozzuří s {spell:23272}: polož {spell:13809}, {spell:5384}, a resetne se bez enrage. {spell:2974} ho znehybní na dlouho; zatímco je znehybněný, straší tě a posílá brouky ({npc:14761}): zabíjej je rychle pastmi a {spell:2643}, než tě udolají.",
}
t.guides["forever/class/hunter/taming-the-beast-alliance"] = {
	["At 10 go to {npc:1231}, the hunter trainer at the smithy in {area:131}. {quest:6074} from {npc:5116} in {zone:1455}, {npc:11807} north-west of {area:131} or {npc:5515} in {zone:1453} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Na 10 jdi za {npc:1231}, trenérem lovců u kovárny v {area:131}. Sem vede i {quest:6074} od {npc:5116} v {zone:1455}, {npc:11807} severozápadně od {area:131} nebo {npc:5515} v {zone:1453}, za trochu zkušeností; je to jen rozcestník. Jsi na 10 radši v Elwynnu? Řetěz {npc:251507} v {area:87} učí totéž.",
	["At 10 go to {npc:251507}, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in {area:87}; {npc:258930}, the pet trainer, is beside her. Skyborne: this is for one who left {zone:2521} without taming; it teaches the same."] = "Na 10 jdi za {npc:251507}, trenérkou lovců, která stojí s ostatními trenéry u Lion's Pride Inn v {area:87}; {npc:258930}, trenér petů, je vedle ní. Skyborne: tohle je pro toho, kdo opustil {zone:2521} bez ochočení; učí totéž.",
	["At 10 go to {npc:3601}, the hunter trainer in {area:186}. {quest:6071} from {npc:3596} at {area:256}, {npc:4146} in {zone:1457}, {npc:5515} in {zone:1453}, {npc:5116} in {zone:1455} or {npc:1231} in {area:131} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Na 10 jdi za {npc:3601}, trenérem lovců v {area:186}. Sem vede i {quest:6071} od {npc:3596} v {area:256}, {npc:4146} v {zone:1457}, {npc:5515} v {zone:1453}, {npc:5116} v {zone:1455} nebo {npc:1231} v {area:131}, za trochu zkušeností; je to jen rozcestník. Jsi na 10 radši v Elwynnu? Řetěz {npc:251507} v {area:87} učí totéž.",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "Na 10 tě {npc:254084}, trenér lovců na {zone:2521}, může poslat dál do {area:16638} s {quest:94007}. Je to jen rozcestník: přeskoč ho, pokud už jsi v {area:16638}.",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of {area:87}, east of {area:18}."] = "Nejdřív propusť kance (pravé tlačítko na portrét peta, {spell:2641}): propuštěný cvičný pet se může obrátit proti tobě. Gray Forest Wolves (level 7–8) běhají v lesích východně od {area:87}, východně od {area:18}.",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of {area:131}, more north-west and west of it; the smaller Juvenile Snow Leopards do not count."] = "Nejdřív propusť kance (pravé tlačítko na portrét peta, {spell:2641}): propuštěný cvičný pet se může obrátit proti tobě. Snow Leopards (level 7–8) slídí po svazích jihovýchodně od {area:131}, další severozápadně a západně od něj; menší Juvenile Snow Leopards se nepočítají.",
	["Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of {area:186}."] = "Propusť kočku. Strigid Screechers (level 7–8), sovy, sedí v lesích jižně, jihozápadně a západně od {area:186}.",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "Nejdřív propusť crawlera (pravé tlačítko na portrét peta, {spell:2641}). Ornery Galestriders se pasou v {area:16626}, na polích kousek pěšky západně a jihozápadně od {area:16638}.",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "Propusť galestridera. Vuldren Alphas loví ve stejném {area:16626}, kousek dál na jih.",
	["Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around {area:131}, many south-east of it and more north-west toward {area:77}; their {spell:3130} hits hard, so start at full health."] = "Propusť leoparda. Ice Claw Bears (level 7–8) se toulají po kopcích kolem {area:131}, hodně jihovýchodně od něj a další severozápadně směrem k {area:77}; jejich {spell:3130} tvrdě bije, tak začni s plným zdravím.",
	["Dismiss the spider first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of {area:259}, south of {area:186}; the plain Nightsabers by the village do not count."] = "Nejdřív propusť pavouka (pravé tlačítko na portrét peta, {spell:2641}): propuštěný cvičný pet se může obrátit proti tobě. Nightsaber Stalkers (level 7–8) leží na svahu jižně od {area:259}, jižně od {area:186}; obyčejní Nightsabers u vesnice se nepočítají.",
	["Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town."] = "Propusť vlka. Young Forest Bears (level 8–9) se toulají v lesích kousek jižně od {area:87}, další jihozápadně a jihovýchodně od města.",
	["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "Spokojenost: obličej na rámečku peta. Nespokojený pet dává tři čtvrtiny poškození, spokojený o čtvrtinu víc. Spokojenost pomalu klesá, rychleji, když pet umře; pet, který je dlouho nespokojený, může utéct.",
	["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "Loyalty roste časem a zabitími. Každý rank loyalty zvýší training pointy, které utrácíš v {spell:5149} (level peta krát rank loyalty minus jedna).",
	["Near {area:131}: Snow Leopards (cats, level 7-8) prowl all over {zone:1426}, Scarred Crag Boars (9-10) its east toward {zone:1432}; at 10-11, Mountain Boars roam western {zone:1432}."] = "U {area:131}: Snow Leopards (kočky, level 7–8) slídí po celém {zone:1426}, Scarred Crag Boars (9–10) po jeho východě směrem k {zone:1432}; na 10–11 se Mountain Boars toulají po západním {zone:1432}.",
	["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "U {area:16638}: Vuldren Alphas (level 10), zvíře z tvého posledního cvičného ochočení, loví v {area:16626}; Shriekling Matriarchs (raptoři, level 9) hnízdí kousek západně od {area:16638}; Shadowgale Urseras (medvědi, 10–11) se toulají po severu {zone:2521}.",
	["Near {area:186}: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western {zone:1438}."] = "U {area:186}: Elder Nightsabers (kočky, level 8–9) a Feral Nightsabers (kočky, 10–11) slídí po lesích severozápadního {zone:1438}.",
	["Near {area:87} there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the {zone:1436} border; at 12-13, Young Goretusks (boars) graze the fields of northern {zone:1436}."] = "U {area:87} žádné kočky nejsou: Prowlers (vlci, level 9–10) se toulají po východním Elwynnu, Longsnouts (kanci, 10–11) po jeho dalekém jihozápadě u hranice s {zone:1436}; na 12–13 se Young Goretusks (kanci) pasou na polích severního {zone:1436}.",
	["Pet trainers sell {spell:1853} ranks and resistances. Alliance: {npc:258930} in {area:87}, {npc:2879} by the hunter trainers in {zone:1453}'s {object:28027}, {npc:2878} in {area:131}, {npc:10090} in {zone:1455}'s {object:32390}, Keldas in {area:186}, Silvaria in {zone:1457}' Cenarion Enclave, {npc:254411} in {area:16638}."] = "Trenéři petů prodávají ranky {spell:1853} a odolnosti. Aliance: {npc:258930} v {area:87}, {npc:2879} u trenérů hunterů v {object:28027} v {zone:1453}, {npc:2878} v {area:131}, {npc:10090} v {object:32390} v {zone:1455}, Keldas v {area:186}, Silvaria v Cenarion Enclave v {zone:1457}, {npc:254411} v {area:16638}.",
	["Take the road west from {area:186} to {zone:1457}. {npc:4146} stands inside the {area:1658} with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her."] = "Jdi po cestě na západ z {area:186} do {zone:1457}. {npc:4146} stojí uvnitř {area:1658} s trenéry hunterů; Silvaria, trenérka petů, je nahoře na rampě vedle ní.",
	["Tame a beast of your level to keep"] = "Ochoč si zvíře svého levelu a nech si ho",
	["Tame {npc:1922}"] = "Ochoč {npc:1922}",
	["Tame {npc:250874}"] = "Ochoč {npc:250874}",
	["Tame {npc:251707}"] = "Ochoč {npc:251707}",
	["Tame {npc:254588}"] = "Ochoč {npc:254588}",
	["Tame {npc:524}"] = "Ochoč {npc:524}",
	["Tame {npc:822}"] = "Ochoč {npc:822}",
	["Use the {item:15908} on a living alpha"] = "Použij {item:15908} na živého alfa samce",
	["Use the {item:15908} on a living bear"] = "Použij {item:15908} na živého medvěda",
	["Use the {item:15908} on a living boar"] = "Použij {item:15908} na živého kance",
	["Use the {item:15908} on a living crawler"] = "Použij {item:15908} na živého crawlera",
	["Use the {item:15908} on a living galestrider"] = "Použij {item:15908} na živého galestridera",
	["Use the {item:15908} on a living leopard"] = "Použij {item:15908} na živého leoparda",
	["Use the {item:15908} on a living owl"] = "Použij {item:15908} na živou sovu",
	["Use the {item:15908} on a living spider"] = "Použij {item:15908} na živého pavouka",
	["Use the {item:15908} on a living stalker"] = "Použij {item:15908} na živého stalkera",
	["Use the {item:15908} on a living wolf"] = "Použij {item:15908} na živého vlka",
	["Webwood Lurkers (level 5-6) creep through the woods just north-east, south-west and east of {area:186}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, attacking it or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). Their {spell:1265843} roots you but does not break the channel if you keep still. Keep each rod: it goes back to {npc:3601}."] = "Webwood Lurkers (level 5–6) se plíží lesem kousek severovýchodně, jihozápadně a východně od {area:186}. Jak hůl funguje: zaměř živé zvíře, použij {item:15908} a po celou dobu kouzlení stůj na místě, zatímco tě bije; pohyb, útok na něj nebo pomoc kohokoli jiného to přeruší a stojí to jeden z mála nábojů hole (bez nábojů: znič hůl, zruš quest, vezmi si ho znovu). Jejich {spell:1265843} tě znehybní, ale kouzlení nepřeruší, když stojíš. Každou hůl si nech: vrací se {npc:3601}.",
	["{npc:10090} in {zone:1455}"] = "{npc:10090} v {zone:1455}",
	["{npc:1231} in {area:131}"] = "{npc:1231} v {area:131}",
	["{npc:1231}: the first {item:15908}"] = "{npc:1231}: první {item:15908}",
	["{npc:251507} in {area:87}"] = "{npc:251507} v {area:87}",
	["{npc:251507}: the first {item:15908}"] = "{npc:251507}: první {item:15908}",
	["{npc:252389} in {area:16638}"] = "{npc:252389} v {area:16638}",
	["{npc:252389}: the first {item:15908}"] = "{npc:252389}: první {item:15908}",
	["{npc:3601} in {area:186}"] = "{npc:3601} v {area:186}",
	["{npc:3601}: the first {item:15908}"] = "{npc:3601}: první {item:15908}",
	["{npc:4146} in {zone:1457}"] = "{npc:4146} v {zone:1457}",
	["{quest:6063} (Alliance)"] = "{quest:6063} (Aliance)",
}
t.guides["forever/class/hunter/taming-the-beast-horde"] = {
	["Adult Plainstriders (level 6-7) walk the plains south-west and north-west of {area:222}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). A plainstrider flees at 25% health, so do not damage it first. Keep each rod: it goes back to Yaw."] = "Dospělí Plainstriders (level 6–7) chodí po pláních jihozápadně a severozápadně od {area:222}. Jak hůl funguje: zaměř živé zvíře, použij {item:15908} a po celou dobu kanálu stůj na místě, zatímco tě bije; pohyb, bránění nebo pomoc kohokoli dalšího ho přeruší a stojí jeden z mála nábojů hole (bez nábojů: hůl znič, quest zruš a vezmi znovu). Plainstrider utíká na 25 % zdraví, takže ho předtím nezraňuj. Každou hůl si nech: vrací se Yawovi.",
	["At 10 go to {npc:3065}, who stands at the north edge of {area:222}. {quest:6065} from {npc:3038} in {zone:1456}, {npc:3407} in {zone:1454} or {npc:3171} in {area:362} also leads here, for a little experience; it is only a pointer."] = "Na 10 jdi za {npc:3065}, který stojí na severním okraji {area:222}. Sem vede i {quest:6065} od {npc:3038} v {zone:1456}, {npc:3407} v {zone:1454} nebo {npc:3171} v {area:362}, za trochu zkušeností; je to jen rozcestník.",
	["At 10 go to {npc:3171}, the hunter trainer inside the barracks in {area:362}. If {npc:3407} in {zone:1454}, {npc:11814} in {area:367} or {npc:3038} in {zone:1456} hands you {quest:6068}, take it and hand it to {npc:3171} for a little experience; it is only a pointer, and you can take the first rod without it."] = "Na 10 jdi za {npc:3171}, trenérem lovců v kasárnách v {area:362}. Pokud ti {npc:3407} v {zone:1454}, {npc:11814} v {area:367} nebo {npc:3038} v {zone:1456} dá {quest:6068}, vezmi ho a odevzdej {npc:3171} za trochu zkušeností; je to jen rozcestník a první hůl si vezmeš i bez něj.",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "Na 10 tě {npc:254084}, trenér lovců na {zone:2521}, může poslat dál do {area:16638} s {quest:94007}. Je to jen rozcestník: přeskoč ho, pokud už jsi v {area:16638}.",
	["Dire Mottled Boars (level 6-7) roam just north and west of {area:362}. How the rod works: target a living beast, use the {item:15908} from inside its range and stand still for the whole channel while the beast hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:3171}. The boars charge from 20 yards, so start with the rod, not {spell:75}. The tamed boar becomes your pet for practice. Keep each rod: it goes back to {npc:3171}."] = "Dire Mottled Boars (level 6–7) se toulají kousek severně a západně od {area:362}. Jak hůl funguje: zaměř živé zvíře, použij {item:15908} z jeho dosahu a po celou dobu kanálu stůj na místě, zatímco tě zvíře bije. Pohyb, bránění, heal od někoho jiného nebo útok kohokoli dalšího na zvíře ho přeruší a stojí jeden z mála nábojů hole; když dojdou, hůl znič, quest zruš a vezmi znovu od {npc:3171}. Kanci útočí z 20 yardů, tak začni holí, ne {spell:75}. Ochočený kanec se stane tvým cvičným petem. Každou hůl si nech: vrací se {npc:3171}.",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "Nejdřív propusť crawlera (pravé tlačítko na portrét peta, {spell:2641}). Ornery Galestriders se pasou v {area:16626}, na polích kousek pěšky západně a jihozápadně od {area:16638}.",
	["Dismiss the crawler. Armored Scorpids (level 7-8) crawl the dry plains west and south-west of {area:362}, some just south of the road west out of town; {spell:1494} shows them. Their hits can break the channel: start at full health and keep still."] = "Propusť crawlera. Armored Scorpids (level 7–8) lezou po suchých pláních západně a jihozápadně od {area:362}, někteří kousek jižně od cesty na západ z města; ukáže je {spell:1494}. Jejich údery můžou kanál přerušit: začni s plným zdravím a nehýbej se.",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "Propusť galestridera. Vuldren Alphas loví ve stejném {area:16626}, kousek dál na jih.",
	["Dismiss the plainstrider first (right-click the pet portrait, {spell:2641}): a released practice pet may attack you. Prairie Stalkers (level 7-8) roam the grass north of {area:222}."] = "Nejdřív propusť plainstridera (pravé tlačítko na portrét peta, {spell:2641}): propuštěný cvičný pet může zaútočit. Prairie Stalkers (level 7–8) se toulají v trávě severně od {area:222}.",
	["Dismiss the stalker. Swoops (level 7-9) glide over the plains north-west and north-east of Bloodhoof; the Taloned Swoops do not count. A {npc:2970}'s knockdown breaks the channel, but it lands only once per channel: start the rod just after it has used it."] = "Propusť stalkera. Swoops (level 7–9) kloužou nad pláněmi severozápadně a severovýchodně od Bloodhoof; Taloned Swoops se nepočítají. Sražení od {npc:2970} kanál přeruší, ale zasáhne jen jednou za kanál: začni s holí hned poté, co ho použije.",
	["First dismiss the boar (right-click your pet's portrait, {spell:2641}): a released practice pet can turn on you. Surf Crawlers (level 7-8) walk the beaches around {area:367} and the {area:368}; the small Pygmy Surf Crawlers do not count. A crawler runs for help at 15% health, so do not hurt it."] = "Nejdřív propusť kance (pravým tlačítkem na portrét peta, {spell:2641}): propuštěný cvičný pet se na tebe může obrátit. Surf Crawlers (level 7–8) chodí po plážích kolem {area:367} a {area:368}; malí Pygmy Surf Crawlers se nepočítají. Crawler na 15 % zdraví utíká pro pomoc, tak mu neubližuj.",
	["Follow the road north to {zone:1454}'s gate. {npc:3352} stands with the hunter trainers in the {object:172958}, up the ramp at the city's east side; {npc:10088}, the pet trainer, is a few steps north of him."] = "Jdi po silnici na sever k bráně {zone:1454}. {npc:3352} stojí s trenéry hunterů v {object:172958}, nahoru po rampě na východní straně města; {npc:10088}, trenér petů, je pár kroků severně od něj.",
	["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "Spokojenost: obličej na rámečku peta. Nespokojený pet dává tři čtvrtiny poškození, spokojený o čtvrtinu víc. Spokojenost pomalu klesá, rychleji, když pet umře; pet, který je dlouho nespokojený, může utéct.",
	["Head north to {zone:1456} and take a lift up. {npc:3039} stands with the hunter trainers on {area:1641}; {npc:10086}, the pet trainer, is nearby."] = "Jdi na sever do {zone:1456} a vyjeď výtahem nahoru. {npc:3039} stojí s trenéry hunterů na {area:1641}; {npc:10086}, trenér petů, je poblíž.",
	["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "Loyalty roste časem a zabitími. Každý rank loyalty zvýší training pointy, které utrácíš v {spell:5149} (level peta krát rank loyalty minus jedna).",
	["Near Bloodhoof: Flatland Prowlers (cats, level 9) and Prairie Wolf Alphas (wolves, 9-10) roam the plains of northern {zone:1412}; at 11-12, Savannah Huntresses (cats) prowl around the Crossroads in the {zone:1413}."] = "U Bloodhoofu: Flatland Prowlers (kočky, level 9) a Prairie Wolf Alphas (vlci, 9–10) se toulají po pláních severního {zone:1412}; na 11–12 slídí Savannah Huntresses (kočky) kolem Crossroads v {zone:1413}.",
	["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "U {area:16638}: Vuldren Alphas (level 10), zvíře z tvého posledního cvičného ochočení, loví v {area:16626}; Shriekling Matriarchs (raptoři, level 9) hnízdí kousek západně od {area:16638}; Shadowgale Urseras (medvědi, 10–11) se toulají po severu {zone:2521}.",
	["Near {area:362}: Durotar Tigers (cats, level 7-8) roam the south of {zone:1411}, from {area:367} down the coast; Venomtail Scorpids (9-10) the north-west toward {zone:1454}; at 11-12, Savannah Huntresses (cats) prowl the plains around the Crossroads in the {zone:1413}."] = "U {area:362}: Durotar Tigers (kočky, level 7–8) se toulají po jihu {zone:1411}, od {area:367} dolů po pobřeží; Venomtail Scorpids (9–10) po severozápadě směrem k {zone:1454}; na 11–12 slídí Savannah Huntresses (kočky) po pláních kolem Crossroads v {zone:1413}.",
	["Pet trainers sell {spell:1853} ranks and resistances. Horde: Harruk in {area:362}, {npc:3688} at Bloodhoof, {npc:10088} in {zone:1454}'s {object:172958}, {npc:10086} on {zone:1456}'s {area:1641}, {npc:254411} in {area:16638}, later Grokor in {area:75} and Zudd at {object:3202}."] = "Trenéři petů prodávají ranky {spell:1853} a odolnosti. Horda: Harruk v {area:362}, {npc:3688} v Bloodhoof, {npc:10088} v {object:172958} v {zone:1454}, {npc:10086} na {area:1641} v {zone:1456}, {npc:254411} v {area:16638}, později Grokor v {area:75} a Zudd u {object:3202}.",
	["Tame a beast of your level to keep"] = "Ochoč si zvíře svého levelu a nech si ho",
	["Tame {npc:250874}"] = "Ochoč {npc:250874}",
	["Tame {npc:251707}"] = "Ochoč {npc:251707}",
	["Tame {npc:254588}"] = "Ochoč {npc:254588}",
	["Use the {item:15908} on a living alpha"] = "Použij {item:15908} na živého alfa samce",
	["Use the {item:15908} on a living boar"] = "Použij {item:15908} na živého kance",
	["Use the {item:15908} on a living crawler"] = "Použij {item:15908} na živého crawlera",
	["Use the {item:15908} on a living galestrider"] = "Použij {item:15908} na živého galestridera",
	["Use the {item:15908} on a living plainstrider"] = "Použij {item:15908} na živého plainstridera",
	["Use the {item:15908} on a living scorpid"] = "Použij {item:15908} na živého scorpida",
	["Use the {item:15908} on a living stalker"] = "Použij {item:15908} na živého stalkera",
	["Use the {item:15908} on a living {npc:2970}"] = "Použij {item:15908} na živého {npc:2970}",
	["Use the {item:15908} on a living {npc:3107}"] = "Použij {item:15908} na živého {npc:3107}",
	["{npc:252389} in {area:16638}"] = "{npc:252389} v {area:16638}",
	["{npc:252389}: the first {item:15908}"] = "{npc:252389}: první {item:15908}",
