t.guides["forever/class/hunter/the-hunters-charm"] = {
	["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "Na 50 ho nabízí kterýkoli trenér lovců Aliance: {npc:5516} v {object:28027} v {zone:1453}, {npc:5116} v {object:32390} v {zone:1455} nebo Dorion v Cenarion Enclave v {zone:1457}.",
	["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "Na 50 ho nabízí kterýkoli trenér lovců Hordy: {npc:3352} v {object:172958} v {zone:1454} nebo {npc:3039} na {area:1641} v {zone:1456}.",
	["Experience"] = "Zkušenosti",
	["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "Zkušenosti na 50 přes {zone:1447} a {area:1417}; výběr předmětu z Classicu ve Foreveru možná chybí.",
	["In Classic Ogtinc let you choose the {item:19991}, the {item:19992} or the {item:20083} here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in."] = "V Classicu tě tu Ogtinc nechal vybrat {item:19991}, {item:19992} nebo {item:20083}. Poznámky ke změnám na Forever říkají, že volba zmizela, i když stránka questu pořád uvádí tři nepojmenované odměny: před odevzdáním se podívej do okna odměn.",
	["Morphaz in the {area:1417}"] = "Morphaz v {area:1417}",
	["Morphaz is an elite green drake (level 52) inside the {area:1417}, a five-player dungeon: needs a group of five. The temple stands in the {area:74} in eastern {zone:1435}: climb its outer steps, dive into the flooded hall and follow the stairs down to the entrance. Horde: fly to {area:75}; Alliance: fly to {area:1438} or {area:42} and ride on. He is not there when you arrive: first kill the six troll guardians on the platforms around the upper ring, which opens the way down to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe (pull them one at a time); when both are dead, Morphaz and Hazzas appear together and cannot be split. Clear the dragonkin around the pit first, because they call for help. Morphaz uses {spell:12533} and {spell:11019}. The tooth always drops. Warriors in the group may want the same run for the voodoo feathers of the balcony trolls."] = "Morphaz je elite zelený drak (level 52) uvnitř {area:1417}, dungeonu pro pět hráčů: potřebuješ skupinu pěti. Chrám stojí v {area:74} ve východní {zone:1435}: vylez po vnějších schodech, skoč do zatopené síně a jdi po schodech dolů ke vchodu. Horda: leť do {area:75}; Aliance: leť do {area:1438} nebo {area:42} a jeď dál. Když dorazíš, není tam: nejdřív zabij šest trolích strážců na plošinách kolem horního kruhu, čímž se otevře cesta dolů k {npc:5710} v Pit of Sacrifice. Jammal'anova smrt vyvolá dva draky, Weavera a Dreamscythe (tahej je po jednom); když jsou oba mrtví, objeví se Morphaz a Hazzas spolu a rozdělit nejdou. Nejdřív vyčisti dračí stvůry kolem jámy, protože volají o pomoc. Morphaz používá {spell:12533} a {spell:11019}. Zub padá vždycky. Warrioři ve skupině můžou chtít stejný průchod kvůli voodoo pírkům trollů z balkonů.",
	["{npc:8405} lives on a raised spot on the cliffs at the north-east rim of the {area:1221}, west-central {zone:1447}. Keep to the high ridges around the ruins: the pit below does not lead up to him. Alliance: fly to {area:3137}; Horde: fly to {area:1237}, a short ride west of him."] = "{npc:8405} žije na vyvýšeném místě na útesech na severovýchodním okraji {area:1221}, v západní části středního {zone:1447}. Drž se vysokých hřebenů kolem ruin: jáma pod nimi k němu nahoru nevede. Aliance: leť do {area:3137}; Horda: leť do {area:1237}, kousek jízdy západně od něj.",
	["{quest:8151} (Alliance)"] = "{quest:8151} (Aliance)",
	["{quest:8151} (Horde)"] = "{quest:8151} (Horda)",
}
t.guides["forever/class/mage/arcane-refreshment"] = {
	["Back to Lydros"] = "Zpět k Lydrosovi",
	["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing, or through the North wing's courtyard doors with a {item:18249} (it drops from the imp Pusillin in the East wing; a {item:18594} also opens them; Blink no longer gets past). Other mages in your group can take it too: share it."] = "Leť do Feathermoon (Aliance) nebo {area:1099} (Horda) a jeď do {area:2577} ve středním {zone:1444}. {npc:14368} čeká v Athenaeu, knihovně, kam se dostaneš západním křídlem, nebo dveřmi z nádvoří severního křídla s {item:18249} (dropuje z impa Pusillina ve východním křídle; otevře je i {item:18594}; Blink už se přes ně nedostane). Mohou si ho vzít i další mágové ve skupině: sdílej ho.",
	["Hydrospawn"] = "Hydrospawn",
	["Hydrospawn, a level 57 elite water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool. A group of five. Frost does nothing to him, so frost mages switch to fire or arcane. {area:1758} hits everyone within 10 yards, so ranged stand back; at a quarter health he calls Hydrolings. The essence always drops; he does not come back until the instance resets."] = "Hydrospawn, vodní elementál a elite levelu 57, žije ve Warpwood Quarter (Dire Maul East): honi impa Pusillina, dokud se neotočí k boji, vyčisti místnost se satyry, pak sejdi po točité rampě dolů k jezírku. Skupina pěti. Frost mu nic nedělá, takže frost mágové přepnou na fire nebo arcane. {area:1758} zasáhne každého do 10 yardů, takže ranged stojí vzadu; na čtvrtině zdraví přivolá Hydrolings. Esence padá vždycky; nevrátí se, dokud se instance neresetuje.",
	["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "{spell:10140} levelu 60 z knihovny v {area:2577}: pití pro tebe i tvou skupinu.",
	["{item:18299}: Hydrospawn"] = "{item:18299}: Hydrospawn",
	["{npc:14368}: {spell:10140}, and 200 Shen'dralar reputation"] = "{npc:14368}: {spell:10140} a 200 reputace u Shen'dralar",
}
t.guides["forever/class/mage/astral-knot-garment"] = {
	["A robe or a blouse for Alliance mages in their late 20s."] = "Roucho nebo halenka pro mágy Aliance v jejich pozdních dvacítkách.",
	["Back to Andromath"] = "Zpět k Andromathovi",
	["Carrion Recluses"] = "Carrion Recluses",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. The {area:96} stands alone in the east of the zone. Climb to the very top floor (not the one below): the treatise is the book sticking out of the shelf where the stairs come up. Two gnoll dogs and a gnoll caster guard the shelf; the dogs' {spell:2691} interrupts the click, so fight them on the stairs out of their sight. Morganth (level 26 elite) stands across the top floor: you do not need him, keep to the left edge of the ramp so he stays put. The book is back two seconds after anyone takes it. If you die, your ghost can run up and come back to life beside it."] = "Jdi na východ přes {zone:1429} do Redridge, nebo leť do {area:69}. {area:96} stojí osamoceně na východě zóny. Vyšplhej až do nejvyššího patra (ne do toho pod ním): pojednání je kniha, která trčí z police tam, kde končí schody. Polici hlídají dva gnollí psi a gnollí caster; {spell:2691} psů přeruší klik, tak s nimi bojuj na schodech mimo jejich dohled. Morganth (elite levelu 26) stojí naproti v nejvyšším patře: nepotřebuješ ho, drž se levého okraje rampy, ať zůstane na místě. Kniha je zpátky dvě sekundy po tom, co ji kdokoli vezme. Když umřeš, tvůj duch může vyběhnout nahoru a oživit se vedle ní.",
	["The {area:96}"] = "{area:96}",
	["{area:492} in western {zone:1431}: the six Carrion Recluses (level 25-26, green, {spell:3609}) walk the graves, the central statue and the riverbank, and every one drops a silk; they come back after 5 minutes. The Black Widow Hatchlings (24-25) on the slopes east of the cemetery drop it about one time in six, so mix them in while you wait. {npc:522}, a level 35 elite skeleton, walks the cemetery: watch for him."] = "{area:492} v západní {zone:1431}: šest Carrion Recluses (level 25–26, zelení, {spell:3609}) chodí mezi hroby, kolem centrální sochy a po břehu řeky a každý dropne hedvábí; vrátí se po 5 minutách. Black Widow Hatchlings (24–25) na svazích východně od hřbitova ho dropují zhruba jednou za šest, tak je mezitím zabíjej taky. Po hřbitově chodí {npc:522}, elitní kostlivec levelu 35: dej si na něj pozor.",
	["{npc:1309} works at {object:23296} in the {object:2101}. The robe gives intellect, stamina and spirit; the blouse more intellect and stamina but no spirit."] = "{npc:1309} pracuje u {object:23296} v {object:2101}. Róba dává intelekt, výdrž a ducha; halenka víc intelektu a výdrže, ale žádného ducha.",
	["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144} učí mágy v {object:32362} v {zone:1455}. Pak vezmi {area:2257} z {object:171524} do {zone:1453}.",
	["{quest:1939} (Skyborne)"] = "{quest:1939} (Skyborne)",
	["{quest:1939} waits on the spiral walkway of the Wizard's Sanctum, just past the door of the portal room as you walk down from the trainers."] = "{quest:1939} čeká na točité lávce ve Wizard's Sanctum, kousek za dveřmi místnosti s portály, když jdeš dolů od trenérů.",
}
t.guides["forever/class/mage/atiesh"] = {
	["Back to {npc:15192}"] = "Zpět do {npc:15192}",
	["Back to {npc:15192} at the {area:2300}."] = "Zpět k {npc:15192} u {area:2300}.",
	["Forty Splinters of Atiesh drop in Naxxramas, the 40-player raid in the necropolis over the {area:2277} in {zone:1423}: each of its twelve bosses before Sapphiron and {npc:15990}, and the Four Horsemen's chest, drops one about a third of the time, and the raid shares them out. It takes many weeks of clears. Keep every splinter in one stack."] = "Čtyřicet Splinters of Atiesh padá v Naxxramas, raidu pro 40 hráčů v nekropoli nad {area:2277} v {zone:1423}: každý z jeho dvanácti bossů před Sapphironem a {npc:15990} a truhla Four Horsemen dropne jeden zhruba v třetině případů a raid si je rozděluje. Zabere to mnoho týdnů čištění. Všechny střepy drž v jednom stacku.",
	["Splinters of Atiesh"] = "Splinters of Atiesh",
	["Take the befouled staff to {area:2279}, the dungeon at the north end of {zone:1423}, through the main gate. On {object:175433} find the patch of {object:181206} with a small white flame on it, stand on it and use the staff: {npc:16387}, Hand of Sargeras (level 63 boss) steps out. Bring a strong group: his {spell:17466} hurts everyone and cannot be dispelled (shadow resistance helps), his {spell:28342} curse must be removed at once, and a warrior's Disarm makes him drop his sword, which a melee player can pick up and use against him. He stays up to two and a half hours, so you can regroup."] = "Odnes znesvěcenou hůl do {area:2279}, dungeonu na severním konci {zone:1423}, hlavní bránou. Na {object:175433} najdi plochu {object:181206} s malým bílým plamenem, stoupni si na ni a použij hůl: vystoupí {npc:16387}, Hand of Sargeras (boss level 63). Vezmi silnou skupinu: jeho {spell:17466} zraňuje všechny a nejde dispelnout (pomáhá shadow resistance), jeho curse {spell:28342} se musí okamžitě sundat a warriorův Disarm ho donutí upustit meč, který může melee hráč zvednout a použít proti němu. Zůstane až dvě a půl hodiny, takže se můžeš přeskupit.",
	["The Greatstaff"] = "Greatstaff",
	["The legendary staff of the Guardian: forty splinters from Naxxramas, two raid bosses and a demon in {area:2279}."] = "Legendární hůl Strážce: čtyřicet třísek z Naxxramas, dva raidoví bossové a démon v {area:2279}.",
	["Two more raid bosses, a full 40-player raid each, both pieces always drop: the {item:22733} from {npc:15990} on his throne at the top of Naxxramas, the {item:22734} from {npc:15727} at the bottom of the {area:16076}, behind the {area:3478} in southern {zone:1451}. Each boss comes back once a week."] = "Ještě dva raid bossové, každý na plný raid 40 hráčů, oba kusy padají vždy: {item:22733} z {npc:15990} na jeho trůnu na vrcholu Naxxramas, {item:22734} z {npc:15727} na dně {area:16076}, za {area:3478} na jihu {zone:1451}. Každý boss se vrací jednou týdně.",
	["{npc:16387}, Hand of Sargeras"] = "{npc:16387}, Hand of Sargeras",
}
t.guides["forever/class/mage/celestial-orb"] = {
	["An off-hand orb or a staff for the late 30s, your pick."] = "Koule do druhé ruky nebo hůl pro pozdní třicítky, podle tvé volby.",
	["At 40 the mage trainers who send you to {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}) also have {quest:2861}, a quest any class can do. {npc:6546} then wants the {quest:2846} from {npc:7795}, a level 46 elite naga in {area:978}, the troll dungeon in north-western {zone:1446}: a group of five, level 44-54. The reward window shows the {item:9527} and the {item:9531}."] = "Na 40 mají trenéři mágů, kteří tě posílají k {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}), i {quest:2861}, quest pro jakékoli povolání. {npc:6546} pak chce {quest:2846} od {npc:7795}, elitní nagy levelu 46 v {area:978}, trollím dungeonu na severozápadě {zone:1446}: skupina pěti, level 44–54. Okno odměny ukazuje {item:9527} a {item:9531}.",
	["Back at {npc:6546}'s. Hand in the orb now; {quest:1955} waits for level 40. Kill the critters around the cottage first: they join the fight. Accepting {quest:1955} starts a 3 minute timer, and {npc:6546} calls the {npc:6549} out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again."] = "Zpět u {npc:6546}. Kouli odevzdej teď; {quest:1955} čeká na level 40. Nejdřív zabij havěť kolem chalupy: přidá se do boje. Přijetí {quest:1955} spustí třiminutový časovač a {npc:6546} vyvolá v zahradě {npc:6549}: elitu levelu 40, která odolává mnoha kouzlům, rootům i zpomalení. Doporučuje se skupina: mág na 40 může potřebovat pomoc nebo lektvary, kolem 45 to zvládne sám. Můžeš ho natáhnout z dálky z mola. Časovač běží i po jeho smrti, tak quest odevzdej hned. Když čas vyprší, quest zruš a vezmi znovu; démona vyvolá znovu.",
	["Back to {npc:6546}. Accepting {quest:1957} opens a rift beside her cottage and starts a 10 minute timer: twelve {quest:1957} (level 40, Shock and {spell:403}) come out about four at a time. Attacking one does not pull the rest. Standing at the edge of the field draws them all; the tree south-west of it is out of their reach but in your spell range. Kill twelve and hand in before the timer runs out."] = "Zpět k {npc:6546}. Přijetí {quest:1957} otevře trhlinu vedle její chalupy a spustí desetiminutový časovač: dvanáct {quest:1957} (level 40, Shock a {spell:403}) vyjde zhruba po čtyřech. Útok na jednoho nenatáhne ostatní. Stání na okraji pole přitáhne všechny; strom jihozápadně od něj je mimo jejich dosah, ale v dosahu tvých kouzel. Zabij dvanáct a odevzdej, než časovač vyprší.",
	["The Burning Blade Summoners (level 38-39, not elite) work the {area:602} in southern {zone:1443}, east of {area:2408}, and every one carries an {item:7291}. They cast {spell:686} from 40 yards, keep an imp at their side and run for help at low health; Nether Maidens patrol the pillared ruin beside them, so pull with care. Horde mages: one more summoner stands alone in western {zone:1412}, south-west of {zone:1456}."] = "Burning Blade Summoners (level 38–39, ne elite) pracují v {area:602} v jižní {zone:1443}, východně od {area:2408}, a každý nese {item:7291}. Sesílají {spell:686} ze 40 yardů, mají u sebe impa a při nízkém zdraví utíkají pro pomoc; vedle nich v ruině se sloupy hlídkují Nether Maidens, takže pulluj opatrně. Hordští mágové: ještě jeden summoner stojí sám v západní {zone:1412}, jihozápadně od {zone:1456}.",
	["{area:978}, the troll dungeon in north-western {zone:1446}, needs a group of five; the guide waits for level 46. {npc:7795} is one of the bosses by the sacred pool, and the tiara always drops."] = "{area:978}, trollí dungeon v severozápadní {zone:1446}, potřebuje skupinu pěti; návod počká na level 46. {npc:7795} je jeden z bossů u posvátného jezírka a čelenka padá vždycky.",
	["{quest:1958}: the {item:7515} (off-hand) or the {item:9517}"] = "{quest:1958}: {item:7515} (off-hand) nebo {item:9517}",
	["{quest:2846} in {area:978}"] = "{quest:2846} v {area:978}",
	["{quest:2861} (optional)"] = "{quest:2861} (volitelné)",
}
t.guides["forever/class/mage/destroy-morphaz"] = {
	["Back to {npc:8395} and up to the tower."] = "Zpět k {npc:8395} a nahoru do věže.",
	["Back to {npc:8395}, who teleports you up to the tower."] = "Zpět k {npc:8395}, který tě teleportuje nahoru do věže.",
	["Back to {zone:1447}, {npc:8395} and the tower. Look at the reward window before you hand in: Classic offered the {item:20037}, the {item:20036} or the {item:20035}, and Forever's notes say the choice may be gone."] = "Zpět do {zone:1447}, k {npc:8395} a do věže. Před odevzdáním se podívej do okna odměny: Classic nabízel {item:20037}, {item:20036} nebo {item:20035} a poznámky Foreveru říkají, že volba možná zmizela.",
	["Experience"] = "Zkušenosti",
	["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "Zkušenosti na 50 přes {zone:1447} a {area:1417}; výběr předmětu z Classicu ve Foreveru možná chybí.",
	["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Get off your mount before he teleports you up, or the teleport may not take you. A trail with no enemies climbs to {npc:8379} at the top of the tower; an attendant at the top sends you back down, as often as you like."] = "Leť do {area:3137} (Aliance) nebo {area:1237} (Horda). {npc:8395} táboří pod věží svého mistra, kousek východně od {area:1237}: od rozcestí hlavní silnice {zone:1447} u {area:1221} jdi rovnou na sever k útesům. Než tě teleportuje nahoru, sesedni z mounta, jinak tě teleport nemusí vzít. Stezka bez nepřátel stoupá k {npc:8379} na vrcholu věže; sluha nahoře tě pošle zpátky dolů, kolikrát chceš.",
	["Morphaz"] = "Morphaz",
	["The {item:20085}"] = "{item:20085}",
	["{npc:331}, the Master Mage, stands in the Wizard's Sanctum in {zone:1453}'s {object:2101}; Dink in {zone:1455} gives the same quest."] = "{npc:331}, Master Mage, stojí ve Wizard's Sanctum v {object:2101} v {zone:1453}; stejný quest dává Dink v {zone:1455}.",
	["{npc:8379} again"] = "{npc:8379} znovu",
	["{npc:8379}, in the tower"] = "{npc:8379}, ve věži",
}
t.guides["forever/class/mage/ju-ju-heaps"] = {
	["A staff or an off-hand orb at 10: Orcs and Trolls on the {area:368}, the Undead at a Tirisfal farm."] = "Hůl nebo koule do druhé ruky na 10: Orkové a Trollové na {area:368}, Nemrtví na farmě v Tirisfalu.",
	["At 10 {npc:2128}, the {area:159} mage trainer upstairs in the {area:2119}, sends you to {npc:4568} in the {zone:1458}. Taking it shuts out {quest:1884}; if {quest:1883} (from {zone:1454} or {zone:1456}) is in your log, abandon it first or {npc:2128} cannot give you this one. (A Troll who took this one in {area:159} follows the Balnir steps; an Undead who took {quest:1884} in Sen'jin, the {area:368} steps.)"] = "Na 10 tě {npc:2128}, trenér mágů v {area:159} nahoře v {area:2119}, pošle k {npc:4568} v {zone:1458}. Jeho přijetí uzavře {quest:1884}; pokud máš v deníku {quest:1883} (z {zone:1454} nebo {zone:1456}), nejdřív ho zruš, jinak ti {npc:2128} tenhle nedá. (Troll, který tenhle vzal v {area:159}, jde kroky Balnira; Nemrtvý, který vzal {quest:1884} v Sen'jinu, kroky {area:368}.)",
	["Back to Anastasia"] = "Zpět k Anastasii",
	["Back to Un'thuwa"] = "Zpět k Un'thuwovi",
	["Ley or {item:9514} or Orb (Horde)"] = "Ley nebo {item:9514} nebo Orb (Horda)",
	["The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "Koule je do druhé ruky k jednoruční zbrani; hůl je obouruční.",
	["The {quest:1884}"] = "{quest:1884}",
	["Un'thuwa"] = "Un'thuwa",
	["Un'thuwa, the troll mage trainer, stands in {area:367} on the {zone:1411} coast south of {area:362}. Orcs coming from {zone:1454} can take {quest:1883} from {npc:7311} in the {object:172961} first; it is only a pointer and Un'thuwa gives {quest:1884} without it. Taking it shuts out the {zone:1458}'s {area:165}."] = "Un'thuwa, trollí trenér mágů, stojí v {area:367} na pobřeží {zone:1411} jižně od {area:362}. Orkové, kteří jdou z {zone:1454}, si mohou nejdřív vzít {quest:1883} od {npc:7311} v {object:172961}; je to jen odkaz a Un'thuwa dá {quest:1884} i bez něj. Když ho přijmeš, zavře ti to {area:165} v {zone:1458}.",
	["Un'thuwa: {item:7508} or {item:9513}"] = "Un'thuwa: {item:7508} nebo {item:9513}",
	["Wade across the shallows south-east of Sen'jin to the main Echo Isle, where Zalazane (level 10) holds his camp with Hexed and Voodoo Trolls (level 8). The heaps you can click are the skull piles inside the raised huts around his camp, one hut holding two, more in the huts to the north; the skulls lying on the ground outside cannot be clicked. Destroy four. There are seven and each comes back 30 seconds after it is destroyed."] = "Přebroď mělčinu jihovýchodně od Sen'jinu na hlavní Echo Isle, kde má Zalazane (level 10) tábor s Hexed a Voodoo Trolls (level 8). Hromady, na které jde kliknout, jsou kupy lebek uvnitř vyvýšených chýší kolem jeho tábora, v jedné chýši jsou dvě, další v chýších na severu; lebky ležící venku na zemi kliknout nejdou. Znič čtyři. Je jich sedm a každá se vrátí 30 sekund po zničení.",
	["Walk south from {area:159} to the {area:153} and take the lift down into the {zone:1458}. Anastasia stands in the {object:36082}, the north-east ring of the city."] = "Jdi z {area:159} na jih k {area:153} a sjeď výtahem dolů do {zone:1458}. Anastasia stojí v {object:36082}, severovýchodním okruhu města.",
	["{npc:4568}: {item:7507} or {item:9514}"] = "{npc:4568}: {item:7507} nebo {item:9514}",
	["{object:102986}, four of them"] = "{object:102986}, čtyři kusy",
	["{quest:1882} lies south-east of {area:159}, south of the road east to the {area:152}. The snapdragons grow in the farm's garden and look more like bushes than flowers; any of them will do and you need no {skill:182}. They come back within seconds."] = "{quest:1882} leží jihovýchodně od {area:159}, jižně od cesty na východ do {area:152}. Snapdragony rostou v zahradě statku a vypadají spíš jako keře než květiny; hodí se kterýkoli a {skill:182} nepotřebuješ. Respawnují se během pár sekund.",
}
t.guides["forever/class/mage/mages-wand"] = {
	["\"Plucky\" Johnson"] = "\"Plucky\" Johnson",
	["A wand of your school for the 30s: frost, arcane or fire."] = "Wand tvé školy pro třicítky: frost, arcane nebo fire.",
	["Back to {npc:6546}. With both quests handed in she starts the ritual: wait a few seconds, then talk to her again and pick your wand: Icefury (frost), Nether Force (arcane) or Ragefire (fire)."] = "Zpět k {npc:6546}. S oběma odevzdanými questy začne rituál: pár sekund počkej, pak s ní znovu promluv a vyber si wand: Icefury (frost), Nether Force (arcane) nebo Ragefire (fire).",
	["Tirth sold the book to the Scarlet Crusade. The {area:796} stands in north-eastern {zone:1420}; take the Library wing with a group of five. The book is in the last long hallway, the one that ends in {npc:6487}'s round room: on the left-hand shelf as you face his room, next to the {item:5535}. Take the thick, highlighted blue book sticking out of the shelf; a magnifying-glass cursor means a book you can only read."] = "Tirth prodal knihu Scarlet Crusade. {area:796} stojí na severovýchodě {zone:1420}; křídlo Library jdi se skupinou pěti hráčů. Kniha je v poslední dlouhé chodbě, té, která končí kulatou místností {npc:6487}: v levé polici, když stojíš čelem k jeho místnosti, vedle {item:5535}. Vezmi tlustou, zvýrazněnou modrou knihu, která trčí z police; kurzor s lupou znamená knihu, kterou jde jen číst.",
	["Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken pecking around the foot of the race track's lookout tower; at night type /target plucky. Target him and type /beckon (not /chicken or /wave): he turns human for a moment. Talk to him and ask for the phrase. Do not attack him. If he is gone, he is back within 5 minutes."] = "Tirthův učeň je „Plucky“ Johnson, malé šedé kuře, které zobe u paty vyhlídkové věže závodní dráhy; v noci napiš /target plucky. Zaměř ho a napiš /beckon (ne /chicken ani /wave): na chvíli se promění v člověka. Promluv s ním a požádej o heslo. Neútoč na něj. Když tam není, do 5 minut se vrátí.",
	["{quest:1951}: Scarlet Monastery Library"] = "{quest:1951}: Scarlet Monastery Library",
}
t.guides["forever/class/mage/manaweave-robe"] = {
	["A robe at 15 for Alliance mages, from {zone:1453} and {zone:1432}."] = "Roucho na 15 pro mágy Aliance, z {zone:1453} a {zone:1432}.",
	["Any humanoid drops {item:2589}, and the Tunnel Rats in the {area:149} drop it while you gather the gems; the Auction House in the {object:2096} sells it. You hand in ten."] = "{item:2589} dropuje kterýkoli humanoid a Tunnel Rats v {area:149} ho dropují, zatímco sbíráš drahokamy; prodává ho aukce v {object:2096}. Odevzdáváš deset.",
	["Back to {npc:5497}"] = "Zpět do {npc:5497}",
	["Back to {zone:1453} by the tram. {npc:1309} works at {object:23296} in the {object:2101}."] = "Zpět do {zone:1453} tramvají. {npc:1309} pracuje v {object:23296} v {object:2101}.",
	["Take the {area:2257} to {zone:1455}, then the road east through the South Gate tunnel into {zone:1432}. The {area:149} is at the north end of the loch, north of {area:144}; Tunnel Rat kobolds hold it. The gems come only from the tall stacked {object:271} (the cursor shows a cog over them; single boxes hold nothing): every crate gives one, there are fourteen and they come back after 3 to 5 minutes. You may have to go as deep as the end chamber for six. The same crates serve the dwarves' Filthy Paws quest."] = "Vezmi {area:2257} do {zone:1455}, pak cestou na východ tunelem South Gate do {zone:1432}. {area:149} je na severním konci jezera, severně od {area:144}; drží ho koboldi Tunnel Rat. Drahokamy jsou jen ve vysokých naskládaných {object:271} (kurzor nad nimi ukáže ozubené kolo; samostatné bedny jsou prázdné): každá bedna dá jeden, je jich čtrnáct a respawnují se za 3 až 5 minut. Pro šest možná budeš muset až do koncové komory. Stejné bedny slouží i trpasličímu questu Filthy Paws.",
	["The {area:149}"] = "{area:149}",
	["{npc:328} is the {area:87} mage trainer, upstairs in the Lion's Pride Inn."] = "{npc:328} je trenér mágů v {area:87}, nahoře v Lion's Pride Inn.",
	["{object:2169} is the tavern in the {object:2101}. Read the {item:7308} inside to make the invisible Rift Spawns (level 16-17) show: in the basement it brings out one, on the balcony or in the kitchen two, in the main room or by the door three, so read it downstairs. They hit hard and break out of {spell:122} fast. Beat one down: it does not die but sits stunned with a spiral over its head; use the {item:7247} on it while it is stunned, then click the {item:7292} it leaves on the floor (clicking before it appears wastes a charge). You need three, and the cantation works only once every 5 minutes (logging out does not reset it), so plan on three rounds."] = "{object:2169} je krčma v {object:2101}. Přečti uvnitř {item:7308}, aby se ukázaly neviditelné Rift Spawns (level 16–17): ve sklepě vyvolá jednoho, na balkoně nebo v kuchyni dva, v hlavní místnosti nebo u dveří tři, tak ho čti dole. Silně bijí a rychle se dostanou z {spell:122}. Ubij jednoho: neumře, ale zůstane omráčený se spirálou nad hlavou; použij na něj {item:7247}, dokud je omráčený, pak klikni na {item:7292}, který nechá na zemi (kliknutí dřív, než se objeví, spotřebuje náboj). Potřebuješ tři a zaříkání funguje jen jednou za 5 minut (odhlášení to neresetuje), tak počítej se třemi koly.",
}
t.guides["forever/class/mage/nether-lace-garment"] = {
	["A robe or a tunic for Horde mages in their late 20s."] = "Roucho nebo tunika pro mágy Hordy v jejich pozdních dvacítkách.",
	["Back to {npc:5885}"] = "Zpět do {npc:5885}",
	["Fly to {area:431} and swim north up the river past the big lake to its far northern end, where the zone text reads {area:429}; satyrs hold the ruins around it and a few river beasts are in the way. Swim right in under the highest waterfall until you touch the rock wall, then use the flask (you can stay in the water). The waterfalls on the western Falfarren fork do not work."] = "Leť do {area:431} a plav na sever proti proudu řeky kolem velkého jezera až na jeho nejsevernější konec, kde text zóny ukazuje {area:429}; ruiny kolem drží satyrové a v cestě je pár říčních zvířat. Vplav až pod nejvyšší vodopád, dokud se nedotkneš skalní stěny, pak použij láhev (můžeš zůstat ve vodě). Vodopády na západním rameni Falfarren nefungují.",
	["Take the zeppelin to {zone:1454} (or use {spell:3567}, which lands you on the upper floor of {object:173161}). {npc:5885} stands with the mage trainers on the lower floor of {object:173161} in the {object:172961}. She hands you {item:7269}."] = "Vezmi zeppelin do {zone:1454} (nebo použij {spell:3567}, který tě vysadí v horním patře {object:173161}). {npc:5885} stojí s trenéry mágů v dolním patře {object:173161} v {object:172961}. Dá ti {item:7269}.",
	["The {object:174797}"] = "{object:174797}",
	["The {quest:1945}"] = "{quest:1945}",
	["{npc:3484}, a troll tailor, works at the Crossroads. The robe gives intellect, stamina and spirit; the tunic more intellect and stamina but no spirit."] = "{npc:3484}, trollí krejčí, pracuje na Crossroads. Róba dává intellect, stamina a spirit; tunika víc intellectu a staminy, ale žádný spirit.",
	["{npc:4568} stands in the {zone:1458}'s {object:36082}. Orcs and Trolls use {spell:3563} or take the zeppelin from {zone:1454} to {zone:1420} for her."] = "{npc:4568} stojí v {object:36082} v {zone:1458}. Orkové a trollové k ní použijí {spell:3563} nebo zeppelin z {zone:1454} do {zone:1420}.",
}
t.guides["forever/class/mage/polymorph-pig"] = {
	["A new look for {spell:118}: it turns the target into a pig rather than a sheep."] = "Nový vzhled pro {spell:118}: cíl promění v prase místo ovce.",
	["Back to the {area:1221}, full of Spitelash naga. Cast your sheep {spell:118} (the turtle one does nothing) on a naga and wait a few seconds: it splits into two to six Polymorph Clones of about 150 health that run off fast. Stand next to the sheep and hit them the moment they appear with {spell:122} and {spell:1449}. Fifty clones are needed, so it takes a while; not in a raid group."] = "Zpět do {area:1221}, plného nag Spitelash. Sešli na nagu svůj ovčí {spell:118} (želví nic nedělá) a pár sekund počkej: rozdělí se na dva až šest Polymorph Clones s asi 150 zdraví, které rychle utíkají. Stůj vedle ovce a zasáhni je ve chvíli, kdy se objeví, {spell:122} a {spell:1449}. Klonů je potřeba padesát, takže to chvíli trvá; ne v raidové skupině.",
	["Back to {npc:8395} and up to the tower."] = "Zpět k {npc:8395} a nahoru do věže.",
	["Back to {npc:8395} and up to the tower. Xylem hands the shell back with the next quest: keep it in your bags."] = "Zpět k {npc:8395} a nahoru do věže. Xylem s dalším questem vrátí ulitu: nech si ji v taškách.",
	["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below {npc:8379}'s tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower."] = "Leť do {area:3137} (Aliance) nebo {area:1237} (Horda). {npc:8395} táboří pod věží {npc:8379}, kousek východně od {area:1237}: od rozcestí hlavní silnice {zone:1447} u {area:1221} jdi rovnou na sever k útesům. Sesedni a teleportuje tě nahoru; stezka stoupá k Archmagovi na vrcholu věže.",
	["Polymorph Clones"] = "Polymorph Clones",
	["{npc:8379}: {spell:118} (pig)"] = "{npc:8379}: {spell:118} (prase)",
	["{npc:8408} (level 55, not elite, Strike and {spell:99}) hides behind his Spitelash guards in the {area:1223}, the biggest building in the middle of the {area:1221}. He always drops the {item:23250} and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine."] = "{npc:8408} (level 55, ne elite, Strike a {spell:99}) se schovává za svými Spitelash strážemi v {area:1223}, největší budově uprostřed {area:1221}. Vždycky dropne {item:23250} a po zabití se vrátí za 5 a půl minuty. Nejdřív opusť raid: raid kredit nedostane, skupina ano.",
}
t.guides["forever/class/mage/spellfire-robes"] = {
	["A robe at 15 for Horde mages, from the {zone:1458} and {zone:1421}."] = "Roucho na 15 pro mágy Hordy, z {zone:1458} a {zone:1421}.",
	["Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the {item:7308}: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the {item:7247} on it, then click the {item:7292} once it appears on the floor (clicking too early wastes a charge). Three are needed."] = "Algernonův alchymistický obchod je v Apothecariu. Stoupni si na schody nebo na most před obchodem a přečti {item:7308}: objeví se až čtyři neviditelní Rift Spawns (level 16–17) a hned zaútočí a městské stráže nepomůžou. Zasáhni jednoho kouzlem na jeden cíl a ustup přes most: ostatní to vzdají a zmizí, ten zasažený jde za tebou. Ubij ho na polovině mostu u obchodu (za polovinou na něj truhlička nefunguje), dokud nepřestane bojovat a nesedí omráčený pod spirálou, použij na něj {item:7247} a klikni na {item:7292}, až se objeví na podlaze (moc brzké kliknutí spálí náboj). Potřebuješ tři.",
	["Back to the {zone:1458}. {npc:4576}, {npc:11048} and {npc:11049} keep the tailor's shop in the {object:36082}. Hand the gems and cloth to {npc:4576} and let the three of them talk for a moment; then {npc:4576} offers {quest:1962}: take it and hand it straight back to him for the robe."] = "Zpět do {zone:1458}. Krejčovství v {object:36082} drží {npc:4576}, {npc:11048} a {npc:11049}. Předej drahokamy a látku {npc:4576} a nech ty tři chvíli mluvit; pak {npc:4576} nabídne {quest:1962}: vezmi ho a hned mu ho odevzdej za roucho.",
	["Back to {npc:4568}"] = "Zpět do {npc:4568}",
	["{npc:4568} stands in the {object:36082}. The {item:7247} and the {item:7308} lie on the ledge behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them."] = "{npc:4568} stojí v {object:36082}. {item:7247} a {item:7308} leží na římse za ní (obojí se objeví znovu 5 minut po tom, co si to někdo vezme). Obojí odevzdáš na konci, tak si to nech.",
}
t.guides["forever/class/mage/staff-or-orb-alliance"] = {
	["A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand."] = "Hůl nebo koule do druhé ruky na 10 od trenéra mágů tvého domovského města; Skyborne navíc dostanou wand.",
	["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {quest:1860}, the {area:87} trainer's errand; {npc:5144}'s Gizmonitor and {npc:5497}'s {quest:1861} shut out each other, so you get one staff or orb. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "Na 10 tě {npc:1228}, trenér mágů v {area:131} v {area:2102}, pošle k {npc:5144} v {zone:1455}. Jeho přijetí uzavře {quest:1860}, pochůzku trenéra z {area:87}; Gizmonitor od {npc:5144} a {quest:1861} od {npc:5497} se navzájem vylučují, takže dostaneš jednu hůl nebo kouli. (Gnóm, který vzal quest {npc:328} v {area:87}, jde místo toho kroky {quest:1861}; Člověk, který vzal tenhle, kroky Gizmonitoru.)",
	["At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town."] = "Na 10 tě {npc:252373}, trenér mágů v {area:16638}, pošle k {npc:256507}, obchodníkovi s holemi pár kroků odsud ve stejném městě.",
	["At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {quest:1879}, the {area:131} trainer's errand; {quest:1861} and {npc:5144}'s Gizmonitor shut out each other, so you get one staff or orb."] = "Na 10 tě {npc:328}, trenér mágů v {area:87} nahoře v Lion's Pride Inn, pošle k {npc:5497} v {zone:1453}. Jeho přijetí uzavře {quest:1879}, pochůzku trenéra z {area:131}; {quest:1861} a Gizmonitor od {npc:5144} se navzájem vylučují, takže dostaneš jednu hůl nebo kouli.",
	["Back to {npc:256507}"] = "Zpět do {npc:256507}",
	["Back to {npc:5144}"] = "Zpět do {npc:5144}",
	["Back to {npc:5497}"] = "Zpět do {npc:5497}",
	["Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "Zpět nahoru po Wizard's Sanctum a přes portál. Koule je do druhé ruky k jednoruční zbrani; hůl je obouruční.",
	["Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15."] = "Jdi po silnici na sever do {zone:1453} a na západ k {object:2101}. {npc:5497} stojí nahoře ve Wizard's Sanctum, vysoké fialové věži: vyjdi po spirálové rampě a vstup do portálu blízko vrcholu, který tě postaví vedle ní. Dá ti {item:7207}. Mágové Skyborne si od ní berou {quest:1861}, když poprvé dorazí do {zone:1453}, zhruba na 15.",
	["Head west along the road to {area:133}. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone."] = "Jdi po silnici na západ k {area:133}. Kousek severně od vchodu stojí dvě chýše; bedna s nářadím je ve vyšší, východní, té s výtahem: malá šedá bedýnka v přízemí, napůl pod stolem vedle výtahu. Chýše hlídají Leper Gnomes (level 8): pullni je po jednom. Bedna je jen jedna a po otevření se vrací 15 minut, takže když tam není, počkej poblíž.",
	["Leave {zone:1453} by the main gate and head south-west to the waterfall that feeds {quest:1861}. Wade in under the falling water to the rock behind it and use {item:7207} there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water."] = "Opusť {zone:1453} hlavní bránou a zamiř na jihozápad k vodopádu, který napájí {quest:1861}. Projdi vodou pod padající vodu ke skále za ní a použij tam {item:7207} (5sekundový cast); jinde to nefunguje. Na skalách po obou stranách vodopádu stojí Defias caster level 10 a střílí z dálky: tahej je po jednom, nebo naplň baňku z vody.",
	["Ley or {item:9514} or Orb (Alliance)"] = "Ley nebo {item:9514} nebo Orb (Aliance)",
	["{npc:5144} teaches mages in the {object:32362}, at the back of {zone:1455} past the {object:32386}."] = "{npc:5144} učí mágy v {object:32362}, vzadu v {zone:1455} za {object:32386}.",
	["{npc:5144}: {item:7507} or {item:9514}"] = "{npc:5144}: {item:7507} nebo {item:9514}",
	["{quest:1861} (the next steps) waits for you with {npc:5497} in {zone:1453}, at about 15."] = "{quest:1861} (další kroky) na tebe čeká u {npc:5497} v {zone:1453}, kolem levelu 15.",
}
t.guides["forever/class/mage/teleports-alliance"] = {
	["At 20 go to the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:2485}, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches {spell:3561} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor; {npc:1308} sells them at the foot of the tower), so carry a few."] = "Na 20 jdi do Wizard's Sanctum, fialové věže v {object:2101} v {zone:1453}. {npc:2485}, trenérka portálů, stojí úplně nahoře: vyjdi po spirálové rampě a vezmi portál u vrcholu. Naučí {spell:3561} za 20 stříbrných. Každý teleport spálí jeden {item:17031} (10 stříbrných u kteréhokoli obchodníka s reagenciemi; {npc:1308} je prodává u paty věže), tak jich nos pár.",
	["At 30. Take the boat from {area:17203} to {area:442} in {zone:1439}, then the boat to {area:702} and the pink portal up into {zone:1457}. {npc:4165}, the portal trainer, teaches {spell:3565} for 80 silver."] = "Na 30. Vezmi loď z {area:17203} do {area:442} v {zone:1439}, pak loď do {area:702} a růžový portál nahoru do {zone:1457}. {npc:4165}, trenér portálů, naučí {spell:3565} za 80 stříbrných.",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:2485} has {spell:10059} at the top of the Wizard's Sanctum; then the tram to {npc:2489} in {zone:1455}'s {object:32362} for {spell:11416}."] = "Na 40 naučí trenéři portálů portály: bránu, kterou projde celá skupina, za 1 zlatý 50 stříbrných každý. Každý portál spálí jeden {item:17032} (20 stříbrných u kteréhokoli obchodníka s reagenciemi). {npc:2485} má {spell:10059} na vrcholu Wizard's Sanctum; pak tramvají k {npc:2489} do {object:32362} v {zone:1455} pro {spell:11416}.",
	["At 50 {npc:4165} in {zone:1457} teaches the last one, {spell:11419}, for 3 gold 20 silver. Use your {spell:3565} to get there."] = "Na 50 tě {npc:4165} v {zone:1457} naučí poslední, {spell:11419}, za 3 zlaté 20 stříbrných. Dostaň se tam přes {spell:3565}.",
	["Portals to {zone:1453} and {zone:1455}"] = "Portály do {zone:1453} a {zone:1455}",
	["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}. {npc:2489}, the portal trainer, stands with the mage trainers in the {object:32362} at the back of the city: {spell:3562}, 20 silver."] = "Vezmi {area:2257} z {object:28027} v {zone:1453} do {zone:1455}. {npc:2489}, trenér portálů, stojí s trenéry mágů v {object:32362} vzadu ve městě: {spell:3562}, 20 stříbrných.",
	["Teleports and Portals (Alliance)"] = "Teleporty a portály (Aliance)",
	["{item:17031}, 10s each"] = "{item:17031}, po 10s",
	["{item:17032}, 20s each"] = "{item:17032}, po 20s",
}
t.guides["forever/class/mage/teleports-horde"] = {
	["At 20 go to {object:173161} in {zone:1454}'s {object:172961}, where the mage trainers live. {npc:5958}, the portal trainer, stands on the upper floor and teaches {spell:3567} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor), so carry a few."] = "Na 20 jdi do {object:173161} v {object:172961} v {zone:1454}, kde žijí trenéři mágů. {npc:5958}, trenér portálů, stojí v horním patře a naučí {spell:3567} za 20 stříbrných. Každý teleport spálí jeden {item:17031} (10 stříbrných u kteréhokoli obchodníka s reagenciemi), tak jich nos pár.",
	["At 30. {zone:1456} is in {zone:1412}: fly there from {zone:1454} or the Crossroads. {npc:5957}, the portal trainer, stands with the mage trainers in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart. She teaches {spell:3566} for 80 silver."] = "Na 30. {zone:1456} je v {zone:1412}: leť tam z {zone:1454} nebo z Crossroads. {npc:5957}, trenérka portálů, stojí s trenéry mágů v {area:2197}, jeskyni pod {area:1640}: jdi dovnitř dolů, šipka patra nerozliší. Naučí {spell:3566} za 80 stříbrných.",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:5958} in {object:173161} has {spell:11417}; teleport to the {zone:1458} for {npc:2492}'s {spell:11418}."] = "Na 40 naučí trenéři portálů portály: bránu, kterou projde celá skupina, za 1 zlatý 50 stříbrných každý. Každý portál spálí jeden {item:17032} (20 stříbrných u kteréhokoli obchodníka s reagenciemi). {npc:5958} v {object:173161} má {spell:11417}; teleportuj se do {zone:1458} pro {spell:11418} od {npc:2492}.",
	["At 50 {npc:5957}, down in the {area:2197} under {area:1640} in {zone:1456}, teaches the last one, {spell:11420}, for 3 gold 20 silver. Use your {spell:3566} to get there."] = "Na 50 tě {npc:5957}, dole v {area:2197} pod {area:1640} v {zone:1456}, naučí poslední, {spell:11420}, za 3 zlaté 20 stříbrných. Dostaň se tam přes {spell:3566}.",
	["Portals to {zone:1454} and the {zone:1458}"] = "Portály do {zone:1454} a {zone:1458}",
	["Take the zeppelin from the tower outside {zone:1454}'s gate to {zone:1420} and walk into the {zone:1458}. {npc:2492}, the portal trainer, stands in the {object:36082} with the mage trainers: {spell:3563}, 20 silver. {npc:4575} beside him sells the runes."] = "Vezmi zeppelin z věže před branou {zone:1454} do {zone:1420} a vejdi do {zone:1458}. {npc:2492}, trenér portálů, stojí v {object:36082} s trenéry mágů: {spell:3563}, 20 stříbrných. {npc:4575} vedle něj prodává runy.",
	["Teleports and Portals (Horde)"] = "Teleporty a portály (Horda)",
	["{item:17031}, 10s each"] = "{item:17031}, po 10s",
	["{item:17032}, 20s each"] = "{item:17032}, po 20s",
}
t.guides["forever/class/paladin/cloak-of-the-divine-storm"] = {
	["Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone."] = "Zpět k {npc:3663} do {area:413} v západním {zone:1440}, přes celou zónu.",
	["Back to {npc:5495}"] = "Zpět do {npc:5495}",
	["Climb to the top of the {area:444} in northern {zone:1439}. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts {spell:686} from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the {object:409289} at the top: it gives you the {item:209748}; right-click it to start the quest. Keep the orb in your bags until the {object:409311}: three later quests need it."] = "Vyšplhej na vrchol {area:444} v severním {zone:1439}. Dark Strand Fanatics kolem jsou snadní (level 16–17), ale ve věži cestou ke kouli stojí čtyři Dark Strand Voidcallers (level 28–29): každý vyvolá voidwalkera a z dálky sesílá {spell:686}. Na 22–25 vezmi kamaráda nebo dva, tahej je po jednom a schovej se za zeď, ať musí přijít k tobě. Nahoře lootni {object:409289}: dá ti {item:209748}; kliknutím pravým začneš quest. Kouli nech v taškách až do {object:409311}: potřebují ji tři pozdější questy.",
	["Motes of Mannoroth"] = "Motes of Mannoroth",
	["Starts now at 22 at the {area:444}; its mobs are 28-30, so go nearer 30 or with a friend. Alliance only for now."] = "Teď začíná na 22 v {area:444}; moby tam mají 28–30, takže jdi spíš kolem 30 nebo s kamarádem. Zatím jen pro Alianci.",
	["The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the {item:209778}; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of {area:69} drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is {npc:334} (26): stay in the north-west."] = "Blackrock Summoners, Champions a Trackers (level 22–25, ne elite) táboří na severozápadě Redridge a dropují {item:209778}; potřebuješ 14. U ústí jeskyně na východním konci tábora stojí dva elitní Blackrock Shadowcasters (22–23): pulluj mimo ně. Sůl dropují i tábory Blackrock východně od {area:69}, ale jejich Shadowcasters, Sentries a Hunters jsou elite (level 21–24), stejně jako {npc:334} (26): zůstaň na severozápadě.",
	["The {object:409289}"] = "{object:409289}",
	["The {object:409311}"] = "{object:409311}",
	["{area:435} is in south-east {zone:1440}, east of {area:431} (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast {spell:686} and {spell:348}, Infernals keep a fire shield up. They respawn in five minutes."] = "{area:435} je v jihovýchodní {zone:1440}, východně od {area:431} (hordský tábor: obejdi ho). Mannoroc Lashers, Searing Infernals, Felguards a Legion Hounds (level 29–30, ne elite) dropují Motes of Mannoroth; potřebuješ 12. Zhruba pod levelem 27 jsou sólo těžcí: přijď s druhým hráčem nebo později. Felguardi tě srazí k zemi, Lashers sesílají {spell:686} a {spell:348}, Infernals drží ohnivý štít. Respawnou se za pět minut.",
	["{npc:3663} stands at {area:413} in western {zone:1440}, south of the {zone:1439} road. He sends you to {zone:1453} with the orb."] = "{npc:3663} stojí v {area:413} v západní {zone:1440}, jižně od cesty do {zone:1439}. Pošle tě s koulí do {zone:1453}.",
	["{npc:5492} stands in the Cathedral of Light; she sends you to a warlock for a second opinion."] = "{npc:5492} stojí v Cathedral of Light; pošle tě k warlockovi pro druhý názor.",
	["{npc:5495}, the warlock trainer, is in the {object:2101}'s warlock sanctum, down in the {object:2164}'s cellar. She wants 14 {item:209778} to read the orb."] = "{npc:5495}, trenérka warlocků, je ve warlockské svatyni {object:2101}, dole ve sklepě {object:2164}. Aby přečetla kouli, chce 14 {item:209778}.",
	["{object:409289} atop the {area:444}: right-click the {item:209748} it gives"] = "{object:409289} na vrcholu {area:444}: klikni pravým na {item:209748}, který ti dá",
}
t.guides["forever/class/paladin/holy-mightstone"] = {
	["A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever."] = "Jednorázový kámen, který tě na 10 minut výrazně posílí proti nemrtvým; stará volba předmětu ve Foreveru možná není.",
	["At 50 {npc:5149}, the paladin trainer in the {object:32362}, sends you to {area:3197} in the {zone:1422}. {npc:928} in {zone:1453} gives the same quest."] = "Na 50 tě {npc:5149}, trenér paladinů v {object:32362}, pošle do {area:3197} v {zone:1422}. Stejný quest dá {npc:928} v {zone:1453}.",
	["At 50 {npc:928}, the paladin trainer in the Cathedral of Light, sends you to {area:3197} in the {zone:1422}. {npc:5149} in {zone:1455} gives the same quest."] = "Na 50 tě {npc:928}, trenér paladinů v Cathedral of Light, pošle do {area:3197} v {zone:1422}. Stejný quest dá {npc:5149} v {zone:1455}.",
	["Back to Ashlam in {area:3197}: he forges the {item:20620}. Look at the reward window before you hand in: Classic also offered the {item:20505}, the {item:20504} or the {item:20512}, and Forever's notes say that choice may be gone. Use the stone before a fight against undead ({area:2279}, {area:2057}): it lasts ten minutes and is gone after one use."] = "Zpět k Ashlamovi do {area:3197}: ukuje {item:20620}. Před odevzdáním se podívej do okna odměny: Classic nabízel i {item:20505}, {item:20504} nebo {item:20512} a poznámky Foreveru říkají, že ta volba možná zmizela. Kámen použij před bojem s nemrtvými ({area:2279}, {area:2057}): vydrží deset minut a po jednom použití je pryč.",
	["Back to {area:3197}. Ashlam needs the voodoo of the {area:1417}'s trolls for the stone."] = "Zpět do {area:3197}. Ashlam potřebuje na kámen voodoo trollů z {area:1417}.",
	["Minion's Scourgestones"] = "Minion's Scourgestones",
	["The {area:1417}"] = "{area:1417}",
	["The {quest:5401}"] = "{quest:5401}",
	["{area:3197} is the Alliance camp at the south end of the {zone:1422}, north of the Alterac foothills. {npc:10838} commands it; {npc:10840} stands in the same camp."] = "{area:3197} je aliancký tábor na jižním konci {zone:1422}, severně od podhůří Alteracu. Velí mu {npc:10838}; {npc:10840} stojí ve stejném táboře.",
	["{item:12840} x20"] = "{item:12840} x20",
}
t.guides["forever/class/paladin/lumina-windsinger"] = {
	["At 18 {npc:246378}, inside {area:16602} on the bluffs north-west of the {area:156}, sends you south to the {area:228} in {zone:1421}."] = "Na 18 tě {npc:246378}, uvnitř {area:16602} na útesech severozápadně od {area:156}, pošle na jih k {area:228} v {zone:1421}.",
	["At 20 {npc:259620} asks for a blade that can kill {quest:95140}. Talk to {npc:248840} beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third."] = "Na 20 chce {npc:259620} čepel, která dokáže zabít {quest:95140}. Promluv s {npc:248840} vedle ní kvůli jeho Weapon Notes, které vypisují části, a nech si je: chce je zpátky i s částmi. Tři části v libovolném pořadí: dvě z dungeonů (každý pro skupinu pěti) a drahokam od elitních nag venku u třetího.",
	["Back to the {area:228}"] = "Zpět do {area:228}",
	["Back to {npc:248840} in the {area:228}'s lower part: he hands you the {item:268484}, a two-handed sword."] = "Zpět k {npc:248840} do spodní části {area:228}: dá ti {item:268484}, obouruční meč.",
	["Back to {npc:259620} in the {area:228} with the {item:268484} (the quest asks for it): she takes it and blesses it with the magic of her people into {item:267369}."] = "Zpět k {npc:259620} do {area:228} s {item:268484} (quest ho chce): vezme ho a magií svého lidu ho požehná na {item:267369}.",
	["Back to {npc:259649} at Zoram'gar: he cleanses the gem. Keep the {item:272448} for {npc:248840}."] = "Zpět k {npc:259649} do Zoram'garu: očistí drahokam. {item:272448} si nech pro {npc:248840}.",
	["Bring the lumber, the ingot and the gem to {npc:248840} in the {area:228}. He gives you a {item:268192} for a smith in {area:272}: keep it in your bags."] = "Přines dřevo, ingot a drahokam k {npc:248840} do {area:228}. Dá ti {item:268192} pro kováře v {area:272}: nech si ho v taškách.",
	["Equip the {item:268484}. {quest:95140}, the great worgen, roams the woods south of the {area:228} toward the gates of {area:17065}. He is elite (level 25): the guide waits for level 25 first, and grouping up is encouraged; players have killed him from 22 up, one needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke."] = "Nasaď {item:268484}. {quest:95140}, velký worgen, se toulá v lesích jižně od {area:228} směrem k branám {area:17065}. Je elitní (level 25): návod nejdřív počká na level 25 a doporučuje se skupina; hráči ho zabili od 22, jeden potřeboval druhého, jiný ho na 25 dal sám. Chrání ho fialový štít, dokud nedopadne tvůj první úder čepelí: zpráva ti řekne, že praskl.",
	["Free {npc:248755}"] = "Osvoboď {npc:248755}",
	["Goblin Woodcarvers, inside"] = "Goblin Woodcarvers, uvnitř",
	["Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: {npc:248755} walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the {area:228}. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage."] = "Nejdřív odevzdej klíč: když začneš eskortu dřív, quest na klíč se nezapočítá. Pak otevři klec: {npc:248755} projde pevností a nádvořím, zatímco útočí gnollové, pak doběhne k přístavišti a do {area:228} se vrátí sama. Drž se u ní a udrž ji naživu; když umře, vezmi quest znovu, až bude zpátky v kleci.",
	["Lumina waits beside {npc:248840} in the {area:228} (a different Lumina from the one you escorted). For {quest:95034}, click through every line of her story."] = "Lumina čeká vedle {npc:248840} v {area:228} (jiná Lumina než ta, kterou jsi eskortoval). Kvůli {quest:95034} proklikej všechny řádky jejího příběhu.",
	["The Forsaken paladin's two-handed sword: rescue {quest:91862}, gather three parts, slay {quest:95140}."] = "Obouruční meč pro paladiny Forsaken: zachraň {quest:91862}, nasbírej tři části, zabij {quest:95140}.",
	["The naga stand in the flooded ruins and passages around the {area:2797} entrance, just north of Zoram'gar: you do not need to enter the instance (its first naga drop the gem too). Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24) drop the {item:6995}, one in two. All are elite: grouping up is encouraged. Players solo them one at a time, with difficulty; a group of three makes it easy. They heal themselves, run for help at low health, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "Nagové stojí v zaplavených ruinách a chodbách kolem vchodu do {area:2797}, kousek severně od Zoram'garu: do instance vstupovat nemusíš (drahokam dropují i její první nagové). {item:6995} dropují Tide Priestesses (level 20–21), Oracles (21–22) a Sea Witches (23–24), jednou ze dvou. Všichni jsou elite: doporučuje se skupina. Hráči je zvládají sólo po jednom, s obtížemi; ve třech je to snadné. Léčí se, při nízkém zdraví utíkají pro pomoc a Sea Witches zblízka sesílají {spell:122}. Někteří hráči hlásí, že v raidové skupině nic nepadá.",
	["The pyre on {area:172}"] = "Hranice na {area:172}",
	["The {item:267361}"] = "{item:267361}",
	["The {item:272448}"] = "{item:272448}",
	["The {item:6995}"] = "{item:6995}",
	["Watch {npc:3539} forge the blade"] = "Sleduj, jak {npc:3539} kuje čepel",
	["{area:1581} lies under {area:20} in {zone:1436}, Alliance land: a group of five at about 17-24. From the {zone:1458} take the zeppelin to {object:3202} in {zone:1434} and go north through {zone:1431} into {zone:1436}. The way in is the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in Sneed's mast room drop the lumber every time."] = "{area:1581} leží pod {area:20} v {zone:1436}, na území Aliance: dungeon pro skupinu pěti zhruba na level 17–24. Z {zone:1458} jeď zeppelinem k {object:3202} v {zone:1434} a jdi na sever přes {zone:1431} do {zone:1436}. Vstup je v dole {area:20}. Goblin Woodcarvers (elite, level 18–19) v Sneedově místnosti se stěžněm dropnou dřevo pokaždé.",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}, v dole {area:20}",
	["{area:172} lies in the lake north-east of the {area:228}. The gnolls' pyre, with the {object:566037}, is on its shore: click the remains to hand in, and click them again for the next quest. The body is a tauren's, not the elf's."] = "{area:172} leží v jezeře severovýchodně od {area:228}. Pohřební hranice gnollů s {object:566037} je na jeho břehu: klikni na ostatky a odevzdej, pak na ně klikni znovu pro další quest. Tělo patří taurenovi, ne elfovi.",
	["{area:236} is the dungeon in south Silverpine, for a group of five in the low to mid 20s. The ingot sits on the table next to {npc:4275} at the very end. A friend's cleared instance works: walk in and run to the table."] = "{area:236} je dungeon na jihu Silverpine pro skupinu pěti zhruba na level 20–25. Ingot leží na stole vedle {npc:4275} úplně na konci. Stačí kamarádova vyčištěná instance: vejdi a doběhni ke stolu.",
	["{npc:3539} gives you {quest:95125}"] = "{npc:3539} ti dá {quest:95125}",
	["{npc:3539}, the weaponsmith, stands just south of {area:272} in {zone:1424}. Accepting {quest:95125} starts the forging: step back and wait near him until he is done."] = "{npc:3539}, zbrojíř, stojí kousek jižně od {area:272} v {zone:1424}. Přijetím {quest:95125} začne kování: ustup a počkej u něj, dokud neskončí.",
	["{quest:91862} is caged in the basement of {area:235}, at the north end of the isle. The Rot Hide gnolls (level 18-19) fill the keep: they pull in big groups across floors and players report very fast respawns, so clear a path and keep moving. Any of them can carry the {item:267412} (often the first kill); the rare {npc:1944} (22) and Snarlmane (23) can too. If her cage is empty, another player is escorting her: wait for her to come back."] = "{quest:91862} je zavřená v kleci ve sklepě {area:235}, na severním konci ostrova. Gnollové Rot Hide (level 18–19) plní pevnost: tahají se ve velkých skupinách přes patra a hráči hlásí hodně rychlé respawny, tak si prosekej cestu a nezastavuj se. Kterýkoli z nich může mít {item:267412} (často hned první zabitý); může ho mít i rare {npc:1944} (22) a Snarlmane (23). Když je její klec prázdná, eskortuje ji jiný hráč: počkej, až se vrátí.",
}
t.guides["forever/class/paladin/tome-of-divinity"] = {
	["At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it."] = "Na 12 tě {npc:5149}, trenér paladinů v {object:32362} v {zone:1455}, pošle nahoru k {npc:6179}. Pochůzka je volitelná, trochu XP: stejnou dá {npc:1232} v {area:131} i {npc:928} v {zone:1453} (přijetí jedné uzavře ostatní) a {npc:6179} řetěz začne i bez ní.",
	["At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it."] = "Na 12 tě {npc:927}, trenér paladinů v {area:87}, pošle k {npc:6171} do Cathedral of Light v {zone:1453}. Pochůzka je volitelná, trochu XP: stejnou dá {npc:5149} v {zone:1455} (přijetí jedné uzavře druhou) a {npc:6171} řetěz začne i bez ní.",
	["Back to the Cathedral of Light: {npc:6173} takes the script, {npc:6171} teaches you {spell:7328}."] = "Zpět do Cathedral of Light: {npc:6173} vezme spis, {npc:6171} tě naučí {spell:7328}.",
	["Back to the Cathedral. {npc:6171} gives you the {item:6866}; {npc:6173} lies wounded by the altar of the same hall. Keep the symbol: you need it on {npc:6172}. If you lose it, {npc:6171} gives you another (The {item:6866})."] = "Zpět do katedrály. {npc:6171} ti dá {item:6866}; {npc:6173} leží zraněný u oltáře ve stejné síni. Symbol si nech: potřebuješ ho na {npc:6172}. Když ho ztratíš, {npc:6171} ti dá další (The {item:6866}).",
	["Back up to the {object:32386}: {npc:6178} takes the script, {npc:6179} teaches you {spell:7328}."] = "Zpět nahoru do {object:32386}: {npc:6178} vezme spis, {npc:6179} tě naučí {spell:7328}.",
	["Back upstairs in the {object:32386}. {npc:6179} gives you the {item:6866}; her husband {npc:6178} rests on the same floor. Keep the symbol: you need it on {npc:6177}. If you lose it, {npc:6179} gives you another (The {item:6866})."] = "Zpět nahoře v {object:32386}. {npc:6179} ti dá {item:6866}; její manžel {npc:6178} odpočívá ve stejném patře. Symbol si nech: potřebuješ ho na {npc:6177}. Když ho ztratíš, {npc:6179} ti dá další (The {item:6866}).",
	["The Dark Iron Spies (level 9-11, twelve of them) sneak around the little house below the lake, just south of Narm; you see them from his hill. About one kill in two drops the {item:6847}. They run for help at low health: finish them or step back. They respawn in three minutes."] = "Dark Iron Spies (level 9–11, je jich dvanáct) se plíží kolem domku pod jezerem, kousek jižně od Narma; vidíš je z jeho kopce. Asi jedno zabití ze dvou dropne {item:6847}. Při nízkém zdraví utíkají pro pomoc: dodělej je, nebo ustup. Respawnují se za tři minuty.",
	["The Defias Rogue Wizards around the big stone tablet east of {npc:6172} carry the {item:6846}: about one kill in two drops it, but some players need many kills. They respawn in three minutes."] = "Defias Rogue Wizards kolem velké kamenné desky východně od {npc:6172} nosí {item:6846}: dropne zhruba z každého druhého zabití, ale někteří hráči potřebují zabití hodně. Respawnují se za tři minuty.",
	["The summons (Dwarf)"] = "Předvolání (trpaslík)",
	["The summons (Human)"] = "Předvolání (člověk)",
	["The {item:6846}"] = "{item:6846}",
	["The {item:6847}"] = "{item:6847}",
	["The {item:6866}"] = "{item:6866}",
	["{spell:7328} (Alliance)"] = "{spell:7328} (Aliance)",
}
t.guides["forever/class/paladin/tyrs-watch"] = {
	["At 4 {npc:244808} sends you after a {npc:246143} who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy)."] = "Na 4 tě {npc:244808} pošle za {npc:246143}, která utekla do kopců západně od kostela, kousek jižně od netopýří jeskyně. Promluv s ní a nabídni pomoc: obrátí se proti tobě a musíš ji složit (level 3, snadné).",
	["At 8 {npc:246152} in {area:159} sends you to the order's keep on the west coast. {quest:91317} in {area:16881} and the crypt under it hit hard at 8-9: come at 10 or later."] = "Na 8 tě {npc:246152} v {area:159} pošle do pevnosti řádu na západním pobřeží. {quest:91317} v {area:16881} a krypta pod ní na 8–9 tvrdě bijí: přijď na 10 nebo později.",
	["Back to the keep"] = "Zpět do pevnosti",
	["Back to {area:16602}, across the whole glades: Billmuth downstairs takes the plans, then {npc:246378}, back upstairs in the keep, teaches you {spell:7328}."] = "Zpět do {area:16602}, přes celé glades: Billmuth dole vezme plány, pak tě {npc:246378}, zpátky nahoře v pevnosti, naučí {spell:7328}.",
	["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep. If you lose the symbol, {npc:246378} gives you another."] = "Zpět do {area:16602}. {npc:246378} ti dá {item:6866}; {npc:257655} čeká dole v pevnosti. Když symbol ztratíš, {npc:246378} ti dá další.",
	["Faintly Glowing Bones x6"] = "Faintly Glowing Bones x6",
	["Follow the road east out of {area:154} to {area:159}. {npc:246152}, the paladin trainer, stands in town; she trains you from here on."] = "Jdi po silnici na východ z {area:154} do {area:159}. {npc:246152}, trenérka paladinů, stojí ve městě; od teď tě trénuje ona.",
	["Heal 5 {npc:259377} with {spell:635}"] = "Vyléč 5× {npc:259377} pomocí {spell:635}",
	["Lumber Piles, in the cellar: the way down is here"] = "Hromady dřeva ve sklepě: cesta dolů je tady",
	["Talk to the {npc:246143}, then defeat her"] = "Promluv s {npc:246143}, pak ji poraz",
	["Tarnished Drudges x8"] = "Tarnished Drudges x8",
	["Tarnished Zealots x6"] = "Tarnished Zealots x6",
	["The cellar is under the village, not on the surface: the way down is inside a burned-out house, where the arrow points. Twelve Lumber Piles (stacked beams) lie in the cellar, each good for one {item:246213}. {npc:260396}, an elite (level 11-13), sits at the far end: leave it alone."] = "Sklep je pod vesnicí, ne na povrchu: cesta dolů vede vyhořelým domem, kam ukazuje šipka. Ve sklepě leží dvanáct Lumber Piles (naskládané trámy), z každé je jeden {item:246213}. Na druhém konci sedí {npc:260396}, elite (level 11–13): nech ho být.",
	["The crypt under {area:16881}"] = "Krypta pod {area:16881}",
	["The {item:6866}"] = "{item:6866}",
	["Tyr's Watch and {spell:7328} (Forsaken)"] = "Tyr's Watch a {spell:7328} (Forsaken)",
	["Vile Fin Attackers x8"] = "Vile Fin Attackers ×8",
	["Vile Fin Seers x8"] = "Vile Fin Seers ×8",
	["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "Jdi z {area:159} na jih k {area:153} a dolů do {zone:1458}. {npc:10181} drží dvůr v {object:36126}; {npc:257648} žebrá v {object:36078}.",
	["{area:16602} stands on the bluffs north-west of the {area:156} (the road west starts near 29,46). {npc:246349} waits at the gate. {npc:246389}, the keep's trainer, and {npc:259190}, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after {quest:96896} from Leonid at the keep, the end of {npc:267009}'s chain that starts south-east of {area:159}; take their quests when you see them."] = "{area:16602} stojí na útesech severozápadně od {area:156} (silnice na západ začíná kolem 29,46). {npc:246349} čeká u brány. {npc:246389}, trenér pevnosti, a {npc:259190}, její stájník, stojí na okraji lesa kousek jižně od něj. Práci pro tebe mají až od levelu 10 a po {quest:96896} od Leonida v pevnosti, konci řetězu {npc:267009}, který začíná jihovýchodně od {area:159}; jejich questy přijmi, jakmile je uvidíš.",
	["{area:812} is at the far east end of the glades, a long walk. Falgan lies dead among the Scarlet Crusaders there: target his body and use the {item:6866}, then talk to him at once, as he does not stay alive long. If he is already up (another player), just talk to him; if he died again, raise him again."] = "{area:812} je na dalekém východním konci mýtin, dlouhá cesta. Falgan tam leží mrtvý mezi Scarlet Crusaders: zaměř jeho tělo a použij {item:6866}, pak s ním hned promluv, dlouho naživu nevydrží. Když už stojí (jiný hráč), prostě s ním promluv; když zase umřel, oživ ho znovu.",
	["{npc:1569} gives you a {item:282423} after {quest:364}: read it, then bring it to {npc:244808} by the church. He asks you to heal five {npc:259377} lying around {area:154}. {spell:635} hurts a Forsaken paladin a little each time: watch your health."] = "{npc:1569} ti po {quest:364} dá {item:282423}: přečti si ho a pak ho odnes k {npc:244808} u kostela. Požádá tě, abys vyléčil pět {npc:259377} ležících kolem {area:154}. {spell:635} Forsaken paladina pokaždé trochu zraní: hlídej si zdraví.",
	["{quest:91317} (level 8-9) hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. Commander {npc:259431} (level 10) stands on the upper floor of a house, with Drudges below him: clear the ground floor first."] = "{quest:91317} (level 8–9) drží zničenou vesnici {area:16881} v {area:16616}, jihozápadně od pevnosti. Commander {npc:259431} (level 10) stojí v patře jednoho domu, pod ním Drudges: nejdřív vyčisti přízemí.",
}
t.guides["forever/class/paladin/verigans-fist"] = {
	["At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}."] = "Na 20 ti {npc:6179}, nahoře v {object:32386} v {object:32362}, dá {item:6776}. Klikni na něj pravým: pošle tě k {npc:6171} do Cathedral of Light v {zone:1453}. Vezmi {area:2257} z {zone:1455} do {zone:1453}.",
	["Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}."] = "Zpět do Cathedral of Light: {npc:6171} ti dá štít {item:9607} a naučí tě {spell:5502}.",
	["Back to {npc:3649} in {area:442}: he purifies the gem."] = "Zpět k {npc:3649} do {area:442}: očistí drahokam.",
	["Back to {npc:6241}"] = "Zpět do {npc:6241}",
	["Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil."] = "Přines čtyři části k {npc:6181} před {zone:1455}. Přijmi jeho poslední quest a čekej u něj, zatímco u kovadliny kuje palici.",
	["Goblin Woodcarvers, inside"] = "Goblin Woodcarvers, uvnitř",
	["Protect {npc:6182}: three waves"] = "Ochraňuj {npc:6182}: tři vlny",
	["The Alliance paladin's rare two-handed mace for the 20s, with a shield and {spell:5502} on the way."] = "Rare obouruční palcát pro alianční paladiny na 20+, se štítem a {spell:5502} po cestě.",
	["The Blackfathom naga in the flooded passages around the {area:2797} entrance, on {zone:1440}'s north-west coast, drop the {item:6995}: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "Nagy Blackfathom v zaplavených chodbách kolem vchodu do {area:2797}, na severozápadním pobřeží {zone:1440}, dropují {item:6995}: Tide Priestesses (level 20–21), Oracles (21–22) a Sea Witches (23–24), jedna ze dvou. Do instance vstupovat nemusíš. Všechny jsou elite: skupina se doporučuje; hráči je zvládají sólo po jedné, s obtížemi. Léčí se, při nízkém zdraví utíkají pro pomoc, u některých stojí satyrové a Sea Witches zblízka sesílají {spell:122}. Někteří hráči hlásí, že v raid skupině nic nepadá.",
	["The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east {zone:1432}, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one."] = "Bedna s rudou stojí venku uprostřed tábora zlobrů Mo'grosh na severovýchodě {zone:1432}, vedle velkého stromu a rozbitého vozu, mezi jeskyněmi. V táboře je asi patnáct zlobrů Mo'grosh, elite (level 18–19), kteří tě srazí k zemi a vracejí se po pěti minutách: doporučuje se skupina; na levelu 20–22 je potřeba skupina asi tří. Bedna je zpátky dvě sekundy po každém lootu, takže ji dostane každý paladin ve skupině.",
	["The {item:6995}"] = "{item:6995}",
	["The {item:7083}"] = "{item:7083}",
	["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "{area:1581} je dungeon pro skupinu pěti pod {area:20}; portál instance je na dně dolu {area:20}. Goblin Woodcarvers (elite, level 18–19) v místnosti se stěžněm u Sneeda dropnou dřevo pokaždé.",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}, v dole {area:20}",
	["{area:236} is a dungeon for a group of five in the low to mid 20s, in southern {zone:1421}, Horde land: a long trip for the Alliance, through the {zone:1437}, Arathi and {area:287}. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it."] = "{area:236} je dungeon pro skupinu pěti zhruba na level 20–25, v jižní {zone:1421}, na území Hordy: pro Alianci dlouhá cesta přes {zone:1437}, Arathi a {area:287}. Kladivo leží na bedně naproti koním ve stájích, na začátku dungeonu, na vzdáleném konci nádvoří před rampou nahoru; pět minut poté, co ho někdo vezme, je zpátky.",
	["{npc:3649} is in {area:442}. Take his quest before you hunt naga: the Kor Gem never drops without it."] = "{npc:3649} je v {area:442}. Vezmi si od něj quest dřív, než půjdeš lovit nagy: Kor Gem bez něj nikdy nedropne.",
	["{object:91138}, inside"] = "{object:91138}, uvnitř",
	["{object:92420} crate"] = "Bedna {object:92420}",
}
t.guides["forever/class/priest/benediction"] = {
	["Equip {item:18646}, then find {npc:14494}, a ghost on the hillside in the north-west of the {zone:1423}, west of {area:2279}'s gate (if she does not show, take the Eye off and put it back on). {quest:7621} is only talk; {quest:7622} starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or {item:13931}, and a stack of {item:8956} or {item:13180} for the skeletons."] = "Nasaď {item:18646}, pak najdi {npc:14494}, ducha na svahu na severozápadě {zone:1423}, západně od brány {area:2279} (pokud se neukáže, Oko sundej a znovu nasaď). {quest:7621} je jen rozhovor; {quest:7622} začne ve chvíli, kdy ho přijmeš, tak se nejdřív připrav: plná mana, Major Mana Potions, Demonic nebo Dark Runes, jídlo na manu nebo {item:13931} a balík {item:8956} nebo {item:13180} na kostlivce.",
	["The epic priest staff: the {spell:23101} from {area:2717}, {npc:14494}'s peasant rescue, then the Eye of Shadow."] = "Epická kněžská hůl: {spell:23101} z {area:2717}, záchrana rolníků s {npc:14494} a pak Eye of Shadow.",
	["The splinter needs {item:18665} as well. {npc:12397}, a world boss in the {zone:1419} (a raid), always drops it; Manahounds and Doomguard Commanders there drop it rarely (about 3% and 2%), the Hederine of Winterspring hardly ever. It can be traded: check the Auction House first."] = "Tříska potřebuje taky {item:18665}. {npc:12397}, world boss v {zone:1419} (raid), ji dropne vždy; tamní Manahounds a Doomguard Commanders vzácně (zhruba 3 % a 2 %), Hederine ve Winterspringu skoro nikdy. Dá se obchodovat: nejdřív se podívej do aukce.",
	["Use the {item:18659} with both Eyes in your bags: {item:18608}"] = "Použij {item:18659}, když máš v taškách obě Oči: {item:18608}",
	["{npc:14387}: the way into {area:2717} once attuned"] = "{npc:14387}: cesta do {area:2717} po attunementu",
}
t.guides["forever/class/priest/blood-of-morphaz"] = {
	["17,060 XP and 1g55s at 50: {zone:1447}, then Morphaz in the {area:1417} (group of 5). The item choice may be gone."] = "17 060 XP a 1g55s na 50: {zone:1447}, pak Morphaz v {area:1417} (skupina 5). Volba předmětu už možná není.",
	["17,060 experience and 1 gold 55 silver"] = "17 060 zkušeností a 1 zlatý 55 stříbrných",
	["At 50 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) offers {quest:8254}. Before you leave a city, buy an {item:7972} at the Auction House (a few silver): the third quest asks for one and it drops rarely."] = "Na 50 v {zone:1455} nabízí {npc:11406} v {object:32386} ({object:32362}) {quest:8254}. Než opustíš město, kup v aukci {item:7972} (pár stříbrných): třetí quest jeden chce a padá vzácně.",
	["At 50, {npc:5489} at the altar of {zone:1453}'s Cathedral of Light offers {quest:8254} ({npc:11406} in {zone:1455} has it too). Before you leave, buy an {item:7972} at the Auction House in the {object:2096} (a few silver): the third quest asks for one and it drops rarely."] = "Na 50 nabízí {npc:5489} u oltáře Cathedral of Light v {zone:1453} {quest:8254} (má ho i {npc:11406} v {zone:1455}). Než odejdeš, kup {item:7972} v aukci v {object:2096} (pár stříbrných): třetí quest jeden chce a padá vzácně.",
	["At 50, {npc:6018} in {zone:1454}'s {object:172961} offers {quest:8254}. Before you leave, buy an {item:7972} at the Auction House (a few silver): the third quest asks for one and it drops rarely."] = "Na 50 nabízí {npc:6018} v {object:172961} v {zone:1454} {quest:8254}. Než odejdeš, kup v aukci {item:7972} (pár stříbrných): třetí quest jeden chce a padá vzácně.",
	["Carrying an {item:7972} already? It counts at once. Otherwise any undead may drop one, rarely: the {npc:7864} (level 48) in the {area:1221} below {npc:8405}'s cliff drop it about one kill in ten, the highborne ghosts on {zone:1447}'s border with {zone:1440} (level 45-46) a little less, the Anguished and {npc:7523} in {zone:1452} (54-55) about one in eight. The Auction House is usually quicker."] = "Už neseš {item:7972}? Započte se hned. Jinak ho může vzácně dropnout kterýkoli nemrtvý: {npc:7864} (level 48) v {area:1221} pod útesem {npc:8405} zhruba jedno zabití z deseti, highborne duchové na hranici {zone:1447} s {zone:1440} (level 45–46) o něco méně, Anguished a {npc:7523} v {zone:1452} (54–55) zhruba jeden z osmi. Aukce je obvykle rychlejší.",
	["Morphaz in the {area:1417}"] = "Morphaz v {area:1417}",
	["Morphaz is a level 52 elite green dragon inside the {area:1417}, a five-player dungeon: bring a group of five (a level 60 group clears it with ease). Horde: fly to {area:75}; Alliance: fly to {area:1438} in the {zone:1419} and ride north. The temple stands in the middle of the {area:74}: climb the steps on its south side, swim down through the flooded hall and take the stairs to the portal. Inside, Morphaz only appears late: kill the six troll minibosses on the upper balconies, then {npc:5710} below them; that wakes the drakes Weaver and Dreamscythe in the Pit of Sacrifice, and killing both brings Morphaz and Hazzas. The pair patrols together and cannot be split: pull them into a hallway and have the tank face them away from the group (breath and a knockback). Loot him in a party, not a raid group: the blood always drops."] = "Morphaz je elite zelený drak level 52 uvnitř {area:1417}, dungeonu pro pět hráčů: vezmi skupinu pěti (skupina na levelu 60 ho vyčistí levou zadní). Horda: leť do {area:75}; Aliance: leť do {area:1438} v {zone:1419} a jeď na sever. Chrám stojí uprostřed {area:74}: vylez po schodech na jeho jižní straně, proplav dolů zatopenou síní a jdi po schodech k portálu. Uvnitř se Morphaz objeví až pozdě: zabij šest trolích minibossů na horních balkonech, pak {npc:5710} pod nimi; tím probudíš draky Weavera a Dreamscythe v Pit of Sacrifice a jejich smrt přivolá Morphaze a Hazzase. Ti dva hlídkují spolu a rozdělit nejdou: stáhni je do chodby a ať je tank otočí od skupiny (dech a knockback). Lootuj ho v partě, ne v raid skupině: krev padá vždycky.",
	["Mosshoof Coursers (level 52-53, not elite) graze all over {zone:1447}, thickest north-east of {npc:8405} and south of the mountains; about one in three drops a {item:20027}, so plan on a dozen kills for four. They enrage at 30% health: finish them fast. Killing them costs no Cenarion Circle reputation. Keep any {item:7972} you loot."] = "Mosshoof Coursers (level 52–53, ne elite) se pasou po celé {zone:1447}, nejhustěji severovýchodně od {npc:8405} a jižně od hor; zhruba každý třetí dropne {item:20027}, takže na čtyři počítej asi s tuctem zabití. Na 30 % zdraví se rozzuří: dodělej je rychle. Jejich zabíjení tě nestojí žádnou reputaci u Cenarion Circle. Každý lootnutý {item:7972} si nech.",
	["{npc:10922} is at the {area:2479} in southern {zone:1448}. Horde: fly to {area:1997} and ride south-east; Alliance: fly to {area:415} in {zone:1440} and ride north into {zone:1448}. She takes the blood for experience and gold. Look at the reward window before you hand in: Classic let you pick {item:19990}, {item:20006} or Woestave, and Forever's notes say that choice may be gone."] = "{npc:10922} je u {area:2479} v jižním {zone:1448}. Horda: leť do {area:1997} a jeď na jihovýchod; Aliance: leť do {area:415} v {zone:1440} a jeď na sever do {zone:1448}. Krev od tebe vezme za zkušenosti a zlato. Než odevzdáš, podívej se do okna odměn: Classic nabízel výběr z {item:19990}, {item:20006} nebo Woestave a podle poznámek k Forever tahle volba možná zmizela.",
	["{npc:8405}, a furbolg, lives on the clifftop north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}. Ride east and leave the road at the fork before the ruins, then follow the northern cliff edge east to him: the naga ruins and the beach below are walled in by cliffs with no way up."] = "{npc:8405}, furbolg, žije na vrcholu útesu severovýchodně od {area:1221}. Aliance: leť do {area:3137}; Horda: leť do {area:1237}. Jeď na východ a na rozcestí před ruinami opusť cestu, pak jdi po severním okraji útesu na východ až k němu: nagí ruiny a pláž pod nimi jsou obehnané útesy, kudy se nahoru nedostaneš.",
	["{quest:8257}: the {area:1417} entrance"] = "{quest:8257}: vchod do {area:1417}",
}
t.guides["forever/class/priest/confounding-flash-and-contingency-plan"] = {
	["Any {quest:94820} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Jakýkoli dopis {quest:94820} jde k {npc:258785} v {object:32386}, {object:32362} v {zone:1455}.",
	["Any {quest:94823} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Jakýkoli dopis {quest:94823} jde k {npc:258785} v {object:32386}, {object:32362} v {zone:1455}.",
	["Any {quest:94825} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Jakýkoli dopis {quest:94825} jde k {npc:258785} v {object:32386}, {object:32362} v {zone:1455}.",
	["Any {quest:94826} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Jakýkoli dopis {quest:94826} jde k {npc:258785} v {object:32386}, {object:32362} v {zone:1455}.",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}."] = "Na 10 v {zone:1429} ti {npc:377}, nahoře v Lion's Pride Inn v {area:87}, dá dopis {quest:94817} pro {npc:258785} v {zone:1455}.",
	["At 10 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94817} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Na 10 v {zone:1453} ti {npc:376} u oltáře Cathedral of Light dá dopis {quest:94817} pro {npc:258785} v {zone:1455} ({area:2257} z {object:28027}).",
	["At 10, go to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362} (north-west of the city), right beside {npc:11406}: she gives {quest:94817} and takes it back at once. No letter needed. {quest:94817} confuses up to five enemies around you for 3 seconds (any damage wakes them) on a 2-minute cooldown: time to step back and heal, or to run."] = "Na 10 jdi za {npc:258785} v {object:32386}, {object:32362} v {zone:1455} (severozápadně ve městě), hned vedle {npc:11406}: dá {quest:94817} a hned ho převezme. Dopis není potřeba. {quest:94817} zmate až pět nepřátel kolem tebe na 3 sekundy (probudí je jakékoli poškození) s cooldownem 2 minuty: čas ustoupit a vyléčit se, nebo utéct.",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}. {area:131} is on the road up to the city."] = "Na 10 ti {npc:1226}, trenér kněží v {area:2102} v {area:131}, dá dopis {quest:94817} pro {npc:258785} v {zone:1455}. {area:131} je na cestě nahoru do města.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94818} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Na 20 v {zone:1453} ti {npc:376} u oltáře Cathedral of Light dá dopis {quest:94818} pro {npc:258785} v {zone:1455} ({area:2257} z {object:28027}).",
	["At 20, {npc:258785} in the {object:32386} teaches {quest:94818} with a quest she gives and takes back at once. {quest:94818} wards a friend for 30 seconds: if they drop below 35% health, they get a shield and a heal over time at once (it stacks with {spell:139} and {spell:17}). 5-minute cooldown."] = "Na 20 tě {npc:258785} v {object:32386} naučí {quest:94818} questem, který dá a hned převezme. {quest:94818} na 30 sekund chrání přítele: když klesne pod 35 % zdraví, dostane hned štít a léčení v čase (stackuje se s {spell:139} a {spell:17}). Cooldown 5 minut.",
	["Follow the road up from {area:131} into {zone:1455} and to the {object:32362}: {npc:258785} in the {object:32386} takes the letter and teaches {quest:94824}."] = "Jdi po silnici nahoru z {area:131} do {zone:1455} a k {object:32362}: {npc:258785} v {object:32386} vezme dopis a naučí {quest:94824}.",
	["Hand Laurena's letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "Odevzdej Laurenin dopis {npc:258785} v {object:32386}, {object:32362} v {zone:1455}: {area:2257} z {object:28027} v {zone:1453}.",
	["Hand the letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "Odevzdej dopis {npc:258785} v {object:32386}, {object:32362} v {zone:1455}: {area:2257} z {object:28027} v {zone:1453}.",
	["The Gnome priest spells, new in Forever: {quest:94817} at 10, {quest:94818} at 20. Free, no objectives."] = "Kouzla gnomských kněží, ve Forever nová: {quest:94817} na 10, {quest:94818} na 20. Zdarma, bez úkolů.",
	["{npc:1226}: take his {quest:94817} letter"] = "{npc:1226}: vezmi jeho dopis {quest:94817}",
	["{npc:376}: take her {quest:94817} letter"] = "{npc:376}: vezmi její dopis {quest:94817}",
	["{npc:376}: take her {quest:94818} letter"] = "{npc:376}: vezmi její dopis {quest:94818}",
	["{npc:377}: take her {quest:94817} letter"] = "{npc:377}: vezmi její dopis {quest:94817}",
	["{quest:94817} and {quest:94818}"] = "{quest:94817} a {quest:94818}",
	["{quest:94820}: a letter from another trainer"] = "{quest:94820}: dopis od jiného trenéra",
	["{quest:94823}: a letter from another trainer"] = "{quest:94823}: dopis od jiného trenéra",
	["{quest:94824}: {npc:1226}'s letter"] = "{quest:94824}: dopis od {npc:1226}",
	["{quest:94825}: a letter from another trainer"] = "{quest:94825}: dopis od jiného trenéra",
	["{quest:94826}: a letter from another trainer"] = "{quest:94826}: dopis od jiného trenéra",
}
t.guides["forever/class/priest/desperate-prayer-and-chastise"] = {
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455} (the {area:2257} from {zone:1453}'s {object:28027})."] = "Na 10 v {zone:1429} ti {npc:377}, nahoře v Lion's Pride Inn v {area:87}, dá dopis {quest:5634} pro {npc:11406} v {zone:1455} ({area:2257} z {object:28027} v {zone:1453}).",
	["At 10 in {zone:1438}, {npc:3600}, in the building at the north edge of {area:186}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "Na 10 v {zone:1438} ti {npc:3600}, v budově na severním okraji {area:186}, dá dopis {quest:5634} pro {npc:11406} v {zone:1455}.",
	["At 10 in {zone:1453}, {npc:11397}, the priest trainer in the Park (the night elf quarter on the city's west side), hands you a {quest:5634} letter for {npc:11406} in {zone:1455}. {npc:376} in the Cathedral has none for Dwarves."] = "Na 10 v {zone:1453} ti {npc:11397}, trenér kněží v Parku (čtvrť nočních elfů na západní straně města), dá dopis {quest:5634} pro {npc:11406} v {zone:1455}. {npc:376} v katedrále pro Trpaslíky žádný nemá.",
	["At 10 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "Na 10 v {zone:1457} ti {npc:11401}, na horním balkonu Temple of the Moon vedle {npc:7999}, dá dopis {quest:5634} pro {npc:11406} v {zone:1455}.",
	["At 10, go to {npc:11406} in the {object:32386}, in {zone:1455}'s {object:32362} (north-west of the city): he gives {quest:5639} and takes it back at once. No letter needed. {quest:5639} heals you instantly, costs no mana and has a long cooldown: keep it for emergencies."] = "Na 10 jdi za {npc:11406} v {object:32386}, v {object:32362} v {zone:1455} (severozápadně ve městě): dá {quest:5639} a hned ho převezme. Dopis není potřeba. {quest:5639} tě okamžitě vyléčí, nestojí manu a má dlouhý cooldown: šetři ho na nouzi.",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:5634} letter for {npc:11406}. {area:131} is on the road up to {zone:1455}."] = "Na 10 ti {npc:1226}, trenér kněží v {area:2102} v {area:131}, dá dopis {quest:5634} pro {npc:11406}. {area:131} je na cestě nahoru do {zone:1455}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:5641} letter for {npc:11406} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Na 20 v {zone:1453} ti {npc:376} u oltáře Cathedral of Light dá dopis {quest:5641} pro {npc:11406} v {zone:1455} ({area:2257} z {object:28027}).",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5641} letter for {npc:11406} in {zone:1455}."] = "Na 20 v {zone:1457} ti {npc:11401}, na horním balkonu Temple of the Moon vedle {npc:7999}, dá dopis {quest:5641} pro {npc:11406} v {zone:1455}.",
	["At 20, {npc:11406} in the {object:32386} teaches {quest:5641} with a quest he gives and takes back at once. Forever renamed it from A Lack of Fear: {quest:5641} damages a humanoid and roots it for 2 seconds (instant, 2-minute cooldown), and every priest now trains {spell:6346}."] = "Na 20 tě {npc:11406} v {object:32386} naučí {quest:5641} questem, který dá a hned převezme. Forever ho přejmenoval z A Lack of Fear: {quest:5641} zraní humanoida a na 2 sekundy ho přikove (okamžité, cooldown 2 minuty) a {spell:6346} teď trénuje každý kněz.",
	["Follow the road up from {area:131} into {zone:1455} and west to the {object:32362}: {npc:11406} in the {object:32386} takes the letter and teaches {quest:5637}. The letter tells you to head to {zone:1453}, but the one who wants you is Rohan in {zone:1455}."] = "Jdi po silnici nahoru z {area:131} do {zone:1455} a na západ k {object:32362}: {npc:11406} v {object:32386} vezme dopis a naučí {quest:5637}. Dopis ti říká, ať zamíříš do {zone:1453}, ale chce tě Rohan v {zone:1455}.",
	["Hand Alathea's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1457}, the boats via {area:702} and {area:442} to {area:150}, then the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "Odevzdej Alathein dopis {npc:11406} v {object:32386}, {object:32362} v {zone:1455}: ze {zone:1457} lodí přes {area:702} a {area:442} do {area:150}, pak po silnici na sever přes {zone:1437} a {zone:1432} (nebo lodí do {area:17203} a {area:2257}).",
	["Hand Laurena's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: he teaches {quest:5645}."] = "Odevzdej Laurenin dopis {npc:11406} v {object:32386}, {object:32362} v {zone:1455}: naučí tě {quest:5645}.",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1438}, the boat from {area:702} to {area:442}, the boat to {area:150} and the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "Odevzdej dopis {npc:11406} v {object:32386}, {object:32362} v {zone:1455}: z {zone:1438} lodí z {area:702} do {area:442}, lodí do {area:150} a po silnici na sever přes {zone:1437} a {zone:1432} (nebo lodí do {area:17203} a {area:2257}).",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: its text says {zone:1453}, but Rohan is in {zone:1455}. From {zone:1457}, the portal down to {area:702}, the boat to {area:442}, then {area:150} and the road north (or {area:17203} and the {area:2257})."] = "Odevzdej dopis {npc:11406} v {object:32386}, {object:32362} v {zone:1455}: v textu stojí {zone:1453}, ale Rohan je v {zone:1455}. Ze {zone:1457} portálem dolů do {area:702}, lodí do {area:442}, pak do {area:150} a po silnici na sever (nebo do {area:17203} a {area:2257}).",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "Odevzdej dopis {npc:11406} v {object:32386}, {object:32362} v {zone:1455}: {area:2257} z {object:28027} v {zone:1453}.",
	["The Dwarf priest spells: {quest:5634} at 10, {quest:5641} (new in Forever) at 20. Free, no objectives."] = "Kouzla trpasličích kněží: {quest:5634} na 10, {quest:5641} (ve Forever nové) na 20. Zdarma, bez úkolů.",
	["This letter also goes to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Tenhle dopis jde také {npc:11406} v {object:32386}, v {object:32362} města {zone:1455}.",
	["{npc:11397}: take her {quest:5634} letter"] = "{npc:11397}: vezmi její dopis {quest:5634}",
	["{npc:11401}: take her {quest:5634} letter"] = "{npc:11401}: vezmi její dopis {quest:5634}",
	["{npc:11401}: take her {quest:5641} letter"] = "{npc:11401}: vezmi její dopis {quest:5641}",
	["{npc:1226}: take his {quest:5634} letter"] = "{npc:1226}: vezmi jeho dopis {quest:5634}",
	["{npc:3600}: take her {quest:5634} letter"] = "{npc:3600}: vezmi její dopis {quest:5634}",
	["{npc:376}: take her {quest:5641} letter"] = "{npc:376}: vezmi její dopis {quest:5641}",
	["{npc:377}: take her {quest:5634} letter"] = "{npc:377}: vezmi její dopis {quest:5634}",
	["{quest:5634} and {quest:5641}"] = "{quest:5634} a {quest:5641}",
	["{quest:5634}: an old letter"] = "{quest:5634}: starý dopis",
	["{quest:5635}: Josetta's letter"] = "{quest:5635}: Josettin dopis",
	["{quest:5636}: {npc:3600}'s letter"] = "{quest:5636}: dopis od {npc:3600}",
	["{quest:5637}: {npc:1226}'s letter"] = "{quest:5637}: dopis od {npc:1226}",
	["{quest:5638}: Nara's letter"] = "{quest:5638}: Narin dopis",
	["{quest:5640}: Alathea's letter"] = "{quest:5640}: Alathein dopis",
	["{quest:5645}: Laurena's letter"] = "{quest:5645}: Laurenin dopis",
	["{quest:5647}: Alathea's letter"] = "{quest:5647}: Alathein dopis",
}
t.guides["forever/class/priest/divine-grace-and-feedback"] = {
	["A Human priest in {zone:1438} at 10: {npc:3600}, in the building at the north edge of {area:186}, hands you a letter for {npc:376} in {zone:1453}."] = "Lidský kněz v {zone:1438} na 10: {npc:3600} v budově na severním okraji {area:186} ti dá dopis pro {npc:376} v {zone:1453}.",
	["Any {quest:94776} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Jakýkoli dopis {quest:94776} jde k {npc:376} u oltáře Cathedral of Light.",
	["Any {quest:94777} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Jakýkoli dopis {quest:94777} jde k {npc:376} u oltáře Cathedral of Light.",
	["Any {quest:94778} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Jakýkoli dopis {quest:94778} jde k {npc:376} u oltáře Cathedral of Light.",
	["Any {quest:94779} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Jakýkoli dopis {quest:94779} jde k {npc:376} u oltáře Cathedral of Light.",
	["At 10, go to {npc:376} at the altar of the Cathedral of Light, in {zone:1453}'s {object:2098}, and take her quest: she teaches {quest:94773} on the spot. No letter needed; one from another trainer works too (next steps). {quest:94773} instantly heals a friend below half health and clears {spell:6788}, so you can shield them again (5-minute cooldown); it does not work on yourself. Human priests do not get {spell:13908} in Forever: this is their spell instead."] = "Na 10 jdi za {npc:376} k oltáři Cathedral of Light v {object:2098} v {zone:1453} a vezmi její quest: naučí {quest:94773} na místě. Dopis není potřeba; funguje i dopis od jiného trenéra (další kroky). {quest:94773} okamžitě vyléčí přítele pod polovinou zdraví a zruší {spell:6788}, takže ho můžeš znovu stínit (cooldown 5 minut); na sebe nefunguje. Lidští kněží ve Foreveru nedostanou {spell:13908}: tohle je jejich kouzlo místo něj.",
	["At 10, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a letter for {npc:376}. {area:87} is on the road north to {zone:1453}, so it costs no detour."] = "Na 10 ti {npc:377}, nahoře v Lion's Pride Inn v {area:87}, dá dopis pro {npc:376}. {area:87} je na cestě na sever do {zone:1453}, takže to nestojí žádnou odbočku.",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you a letter for {npc:376} in {zone:1453}. The {area:2257} from {object:171524} takes you there."] = "Na 20 v {zone:1455} ti {npc:11406} v {object:32386} ({object:32362}) dá dopis pro {npc:376} v {zone:1453}. Dostane tě tam {area:2257} z {object:171524}.",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a letter for {npc:376} in {zone:1453}."] = "Na 20 v {zone:1457} ti {npc:11401}, na horním balkonu Temple of the Moon vedle {npc:7999}, dá dopis pro {npc:376} v {zone:1453}.",
	["At 20, {npc:376} at the altar of the Cathedral of Light teaches {spell:13896} with a quest she gives and takes back at once."] = "Na 20 tě {npc:376} u oltáře Cathedral of Light naučí {spell:13896} questem, který dá a hned převezme.",
	["Hand Alathea's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1457}: the portal down to {area:702}, the boat to {area:442}, then the boat to {area:17203}): she teaches {spell:13896}."] = "Odevzdej Alathein dopis {npc:376} u oltáře Cathedral of Light v {zone:1453} (ze {zone:1457}: portálem dolů do {area:702}, lodí do {area:442}, pak lodí do {area:17203}): naučí tě {spell:13896}.",
	["Hand Josetta's letter to {npc:376} at the altar of the Cathedral of Light: she teaches {quest:94774}."] = "Odevzdej Josettin dopis {npc:376} u oltáře Cathedral of Light: naučí tě {quest:94774}.",
	["Hand Rohan's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (the {area:2257} from {object:171524} in {zone:1455}): she teaches {spell:13896}."] = "Odevzdej Rohanův dopis {npc:376} u oltáře Cathedral of Light v {zone:1453} ({area:2257} z {object:171524} v {zone:1455}): naučí tě {spell:13896}.",
	["Hand {npc:3600}'s letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1438}: the boat from {area:702} to {area:442}, then the boat to {area:17203}): she teaches {quest:94775}."] = "Odevzdej dopis od {npc:3600} {npc:376} u oltáře Cathedral of Light v {zone:1453} (z {zone:1438}: lodí z {area:702} do {area:442}, pak lodí do {area:17203}): naučí tě {quest:94775}.",
	["{npc:11401}: take her {quest:5676} letter"] = "{npc:11401}: vezmi její dopis {quest:5676}",
	["{npc:11406}: take his {quest:5676} letter"] = "{npc:11406}: vezmi jeho dopis {quest:5676}",
	["{npc:3600}: take her {quest:94773} letter"] = "{npc:3600}: vezmi její dopis {quest:94773}",
	["{npc:377}: take her {quest:94773} letter"] = "{npc:377}: vezmi její dopis {quest:94773}",
	["{quest:94773} and {spell:13896}"] = "{quest:94773} a {spell:13896}",
	["{quest:94775}: {npc:3600}'s letter"] = "{quest:94775}: dopis od {npc:3600}",
	["{quest:94776}: a letter from another trainer"] = "{quest:94776}: dopis od jiného trenéra",
	["{quest:94777}: a letter from another trainer"] = "{quest:94777}: dopis od jiného trenéra",
	["{quest:94778}: a letter from another trainer"] = "{quest:94778}: dopis od jiného trenéra",
	["{quest:94779}: a letter from another trainer"] = "{quest:94779}: dopis od jiného trenéra",
}
t.guides["forever/class/priest/hex-of-weakness-and-shadowguard"] = {
	["At 10 in the {zone:1458}, {npc:4606}, the priest trainer in the {object:36070}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454} (the zeppelin from the tower outside the {zone:1458})."] = "Na 10 v {zone:1458} ti {npc:4606}, trenérka kněží v {object:36070}, dá dopis {quest:5652} pro {npc:6018} v {zone:1454} (zeppelin z věže před {zone:1458}).",
	["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454}."] = "Na 10 v {zone:1412} ti {npc:11407}, kousek jihozápadně od {area:222}, dá dopis {quest:5652} pro {npc:6018} v {zone:1454}.",
	["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454}."] = "Na 10 v {zone:1456} ti {npc:3044}, trenér kněží v jeskyni pod {area:1640}, dá dopis {quest:5652} pro {npc:6018} v {zone:1454}.",
	["At 10, go to {npc:6018}, the priest trainer in a hut in the {object:172961}, {zone:1454}'s south-west corner: he gives {quest:5652} and takes it back at once. No letter needed."] = "Na 10 jdi za {npc:6018}, trenérem kněží v chýši v {object:172961}, v jihozápadním rohu {zone:1454}: dá {quest:5652} a hned ho převezme. Dopis není potřeba.",
	["At 10, {npc:3706}, the priest trainer inside the barracks of {area:362} (the first building on the right as you come up the road from the {area:363}), hands you a {quest:5652} letter for {npc:6018} in {zone:1454}. {area:362} is on the road north to the city."] = "Na 10 ti {npc:3706}, trenér kněží v kasárnách {area:362} (první budova vpravo, když jdeš po cestě nahoru z {area:363}), dá dopis {quest:5652} pro {npc:6018} v {zone:1454}. {area:362} je na cestě na sever do města.",
	["At 20 in the {zone:1458}, {npc:4606} in the {object:36070} hands you a {quest:5642} letter for {npc:6018} in {zone:1454}."] = "Na 20 v {zone:1458} ti {npc:4606} v {object:36070} dá dopis {quest:5642} pro {npc:6018} v {zone:1454}.",
	["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5642} letter for {npc:6018} in {zone:1454}."] = "Na 20 v {zone:1456} ti {npc:3044} v jeskyni pod {area:1640} dá dopis {quest:5642} pro {npc:6018} v {zone:1454}.",
	["At 20, {npc:6018} in the {object:172961} teaches {quest:5680} with a quest he gives and takes back at once."] = "Na 20 tě {npc:6018} v {object:172961} naučí {quest:5680} questem, který dá a hned převezme.",
	["Follow the road north from {area:362} into {zone:1454} and west to the {object:172961}: {npc:6018} takes the letter and teaches {quest:5654}."] = "Jdi po silnici na sever od {area:362} do {zone:1454} a na západ k {object:172961}: {npc:6018} vezme dopis a naučí {quest:5654}.",
	["Hand the letter to {npc:6018} in the {object:172961}, {zone:1454} (from {zone:1412}: north through the {zone:1413} and east into {zone:1411}, or fly from {zone:1456} once you know {zone:1454}'s flight path)."] = "Odevzdej dopis {npc:6018} v {object:172961}, {zone:1454} (z {zone:1412}: na sever přes {zone:1413} a na východ do {zone:1411}, nebo leť z {zone:1456}, jakmile znáš letovou trasu do {zone:1454}).",
	["Hand the letter to {npc:6018} in the {object:172961}, {zone:1454} (the zeppelin from {zone:1420} lands outside {zone:1454})."] = "Odevzdej dopis {npc:6018} v {object:172961}, {zone:1454} (zeppelin z {zone:1420} přistává u {zone:1454}).",
	["{npc:11407}: take the {quest:5652} letter"] = "{npc:11407}: vezmi si dopis {quest:5652}",
	["{npc:3044}: take his {quest:5642} letter"] = "{npc:3044}: vezmi jeho dopis {quest:5642}",
	["{npc:3044}: take his {quest:5652} letter"] = "{npc:3044}: vezmi jeho dopis {quest:5652}",
	["{npc:3706}: take his {quest:5652} letter"] = "{npc:3706}: vezmi jeho dopis {quest:5652}",
	["{npc:4606}: take her {quest:5642} letter"] = "{npc:4606}: vezmi její dopis {quest:5642}",
	["{npc:4606}: take her {quest:5652} letter"] = "{npc:4606}: vezmi její dopis {quest:5652}",
	["{quest:5642}: {npc:3044}'s letter"] = "{quest:5642}: dopis od {npc:3044}",
	["{quest:5643}: {npc:4606}'s letter"] = "{quest:5643}: dopis od {npc:4606}",
	["{quest:5652} and {quest:5642}"] = "{quest:5652} a {quest:5642}",
	["{quest:5654}: {npc:3706}'s letter"] = "{quest:5654}: dopis od {npc:3706}",
	["{quest:5655}: {npc:11407}'s letter"] = "{quest:5655}: dopis od {npc:11407}",
	["{quest:5656}: {npc:3044}'s letter"] = "{quest:5656}: dopis od {npc:3044}",
	["{quest:5657}: {npc:4606}'s letter"] = "{quest:5657}: dopis od {npc:4606}",
}
t.guides["forever/class/priest/priest-robes-alliance"] = {
	["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Neobvyklé roucho zdarma na 5: ošetři a posilni zraněného strážce u svého prvního města.",
	["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:3595}, trenérka kněží ve druhém patře {area:256}, velkého stromu v {area:188}, pošle k {npc:3600} v {area:186}. Když už jsi tady, vytrénuj od ní {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:375}, trenérka kněží v {area:24}, pošle k {npc:377} v {area:87}. Když už jsi tady, vytrénuj od Anetty {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:837}, trenér kněží v {area:77} v {area:132}, pošle k {npc:1226} v {area:131}. Když už jsi tady, vytrénuj od něj {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "Zpět na severním okraji {area:186}: {npc:3600} ti dá {item:16604}.",
	["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "Zpět v {area:2102}: {npc:1226} ti dá {item:16605}.",
	["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "Zpět nahoře v Lion's Pride Inn: Josetta ti dá {item:16605}.",
	["Follow the road south out of {area:9} to {area:87}. {npc:377} is upstairs in the Lion's Pride Inn."] = "Jdi po silnici na jih z {area:9} do {area:87}. {npc:377} je nahoře v Lion's Pride Inn.",
	["Heal and fortify {npc:12423}"] = "Vyléč a posil {npc:12423}",
	["Heal and fortify {npc:12427}"] = "Vyléč a posil {npc:12427}",
	["Heal and fortify {npc:12429}"] = "Vyléč a posil {npc:12429}",
	["Leave {area:188} by the ramp and follow the road south-west to {area:186}. {npc:3600} is in the building at the north edge of the village."] = "Opusť {area:188} po rampě a jdi po cestě na jihozápad do {area:186}. {npc:3600} je v budově na severním okraji vesnice.",
	["Priest Robes at 5 (Alliance)"] = "Kněžské róby na levelu 5 (Aliance)",
	["Take the tunnel north-east out of {area:132} and follow the road east to {area:131}. {npc:1226} is inside the {area:2102}."] = "Vezmi tunel na severovýchod z {area:132} a jdi po cestě na východ do {area:131}. {npc:1226} je uvnitř {area:2102}.",
	["{npc:12423} kneels by a tree on the lake shore east of {area:87}, off the road: walk along the shore, the minimap misses him from the road. Cast {spell:613} (Rank 2) on him first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes."] = "{npc:12423} klečí u stromu na břehu jezera východně od {area:87}, mimo cestu: jdi po břehu, z cesty ho minimapa nezachytí. Nejdřív na něj sešli {spell:613} (Rank 2), pak {spell:1243}. Rank 1 {spell:613} se nepočítá; přetáhni Rank 2 ze spellbooku na lištu (nebo sešli obojí ze spellbooku, když ti překáží addon na akční lišty). Jakmile zaberou obě kouzla, odejde a vrátí se zhruba za 3 minuty.",
	["{npc:12427} kneels on a ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast {spell:613} (Rank 2) on him first, then {spell:1243}; he speaks after each spell. Rank 1 of {spell:613} does not count."] = "{npc:12427} klečí na hřbetu mezi dvěma nízkými zídkami kousek jižně od {area:131}, přes cestu od trenéra hunterských petů: když cesta začne klesat, minul jsi ho. Nejdřív na něj sešli {spell:613} (Rank 2), pak {spell:1243}; po každém kouzle promluví. Rank 1 {spell:613} se nepočítá.",
	["{npc:12429} kneels on the rocks at the edge of {area:259}, about 100 yards south of {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her first, then {spell:1243}; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of {spell:613} does not count."] = "{npc:12429} klečí na skalách na okraji {area:259}, zhruba 100 yardů jižně od {area:186}, bez značky questu nad hlavou. Nejdřív na ni sešli {spell:613} (Rank 2), pak {spell:1243}; jakmile zaberou obě kouzla, odběhne k jezeru a vrátí se zhruba za 5 minut. Rank 1 {spell:613} se nepočítá.",
}
t.guides["forever/class/priest/priest-robes-horde"] = {
	["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Neobvyklé roucho zdarma na 5: ošetři a posilni zraněného strážce u svého prvního města.",
	["At 5, {npc:2123}, the priest trainer in the chapel of {area:154}, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:2123}, trenér kněží v kapli {area:154}, pošle k {npc:2129} v {area:159}. Když už jsi tady, vytrénuj od něj {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["At 5, {npc:3707}, the priest trainer in the Den in the middle of the {area:363}, sends you to {npc:3706} in {area:362}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:3707}, trenér kněží v Den uprostřed {area:363}, pošle k {npc:3706} v {area:362}. Když už jsi tady, vytrénuj od něj {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["Back in the {area:362} barracks: {npc:3706} gives you the {item:16606}."] = "Zpět v kasárnách {area:362}: {npc:3706} ti dá {item:16606}.",
	["Back upstairs in the {area:159} inn: Beryl gives you the {item:16607}."] = "Zpět nahoře v hostinci {area:159}: Beryl ti dá {item:16607}.",
	["Follow the road east out of {area:154} to {area:159}. {npc:2129} is upstairs in the inn, {area:2119}."] = "Jdi po silnici na východ z {area:154} do {area:159}. {npc:2129} je nahoře v hostinci, {area:2119}.",
	["Follow the road out of the {area:363} north-east to {area:362}. {npc:3706} is inside the barracks, the first building on the right as you come into town."] = "Jdi po silnici z {area:363} na severovýchod do {area:362}. {npc:3706} je uvnitř kasáren, první budovy vpravo, když přijdeš do města.",
	["Heal and fortify {npc:12428}"] = "Vyléč a posil {npc:12428}",
	["Heal and fortify {npc:12430}"] = "Vyléč a posil {npc:12430}",
	["Priest Robes at 5 (Horde)"] = "Kněžské róby na levelu 5 (Horda)",
	["{npc:12428} kneels, half-dead, beside the north gate of {area:159}'s graveyard, a short walk north of the inn. Cast {spell:613} (Rank 2) on him first, then {spell:1243}: Fortitude first does not count, nor does Rank 1 of {spell:613}. If an addon gets in the way, cast both from the spellbook."] = "{npc:12428} klečí napůl mrtvý u severní brány hřbitova {area:159}, kousek na sever od hostince. Nejdřív na něj sešli {spell:613} (Rank 2), pak {spell:1243}: Fortitude jako první se nepočítá, stejně jako Rank 1 {spell:613}. Když ti překáží addon, sešli obojí ze spellbooku.",
	["{npc:12430} kneels behind a group of rocks just off the road, a short walk south of {area:362}. Cast {spell:613} (Rank 2) on her first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook. She leaves once both land and is back in about 5 minutes."] = "{npc:12430} klečí za skupinou skal kousek od cesty, kousek jižně od {area:362}. Nejdřív na ni sešli {spell:613} (Rank 2), pak {spell:1243}. Rank 1 {spell:613} se nepočítá; přetáhni Rank 2 ze spellbooku na lištu. Jakmile zaberou obě kouzla, odejde a vrátí se zhruba za 5 minut.",
}
t.guides["forever/class/priest/starshards-and-elunes-grace"] = {
	["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Na 10 v {zone:1426} ti {npc:1226}, trenér kněží v {area:2102} v {area:131}, dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}.",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Na 10 v {zone:1429} ti {npc:377}, nahoře v Lion's Pride Inn v {area:87}, dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}.",
	["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Na 10 v {zone:1453} ti {npc:5489} u oltáře Cathedral of Light dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}. Stejný dopis má {npc:11397} v Parku.",
	["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Na 10 v {zone:1455} ti {npc:5142} v {object:32386} ({object:32362}) dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}.",
	["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "Na 10 jdi za {npc:11401} na horní balkon Temple of the Moon na jižním konci {zone:1457}: vyjdi po rampě z podlahy chrámu; stojí vedle {npc:7999}. {quest:5627} se dá a hned převezme a naučí {spell:10797}. Dopis není potřeba. Forever udělal {spell:10797} mnohem silnějším, s cooldownem 30 sekund.",
	["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "Na 10 ti {npc:3600}, trenér kněží v budově na severním okraji {area:186}, dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}. {area:186} je na cestě na západ do {zone:1457}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Na 20 v {zone:1453} ti {npc:376} u oltáře Cathedral of Light dá dopis {spell:2651} pro {npc:11401} v {zone:1457}. Stejný dopis má {npc:11397} v Parku.",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "Na 20 v {zone:1455} ti {npc:11406} v {object:32386} ({object:32362}) dá dopis {spell:2651} pro {npc:11401} v {zone:1457}.",
	["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "Na 20 tě {npc:11401} na horním balkonu Temple of the Moon, vedle {npc:7999}, naučí {quest:5672} questem, který dá a hned převezme. Ve Foreveru {quest:5672} na 15 sekund nebo do tří minutí sníží na polovinu šanci, že tě zasáhnou útoky na blízko a na dálku.",
	["Hand Laurena's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Odevzdej Laurenin dopis {npc:11401} na horním balkoně Temple of the Moon v {zone:1457}, vedle {npc:7999}: lodí z {area:17203} (nebo {area:150}) do {area:442}, další lodí do {area:702}, pak portálem nahoru do {zone:1457}.",
	["Hand Nara's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Odevzdej Narin dopis {npc:11401} na horním balkoně Temple of the Moon v {zone:1457}, vedle {npc:7999}: lodí z {area:17203} (nebo {area:150}) do {area:442}, další lodí do {area:702}, pak portálem nahoru do {zone:1457}.",
	["Hand Rohan's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Odevzdej Rohanův dopis {npc:11401} na horním balkoně Temple of the Moon v {zone:1457}, vedle {npc:7999}: lodí z {area:17203} (nebo {area:150}) do {area:442}, další lodí do {area:702}, pak portálem nahoru do {zone:1457}.",
	["Take the road west from {area:186} into {zone:1457} and go up to the upper balcony of the Temple of the Moon, beside {npc:7999}: {npc:11401} takes {quest:5629} and teaches {spell:10797}."] = "Jdi po cestě na západ z {area:186} do {zone:1457} a vyjdi na horní balkon Temple of the Moon, vedle {npc:7999}: {npc:11401} převezme {quest:5629} a naučí {spell:10797}.",
	["{npc:11406}: take his {spell:2651} letter"] = "{npc:11406}: vezmi jeho dopis {spell:2651}",
	["{npc:1226}: take {quest:5628}"] = "{npc:1226}: vezmi si {quest:5628}",
