	["{npc:376}: take her {spell:2651} letter"] = "{npc:376}: vezmi její dopis {spell:2651}",
	["{npc:377}: take {quest:5628}"] = "{npc:377}: vezmi {quest:5628}",
	["{npc:5142}: take {quest:5628}"] = "{npc:5142}: vezmi {quest:5628}",
