t.guides["forever/class/rogue/blade-of-cunning-alliance"] = {
	["A dagger at 10 from your home town's rogue quests."] = "Dýka na 10 z rogue questů tvého domovského města.",
	["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "Na 10 tě {npc:1234}, trenér rogue v {area:2102} v {area:131}, pošle k {npc:5165} v {zone:1455}.",
	["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "Na 10 ti {npc:3599}, trenér rogue v hostinci {area:186}, dá růži pro {npc:4163} v {zone:1457}. Když růži ztratíš, quest zruš a vezmi znovu.",
	["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "Na 10 ti {npc:917}, trenér rogue nahoře v Lion's Pride Inn v {area:87}, dá balíček pro {npc:332} v {zone:1453}. Pokud nemáš {spell:921}, vytrénuj ho: tenhle řetěz ho potřebuje.",
	["Back to Mathias Shaw"] = "Zpět k Mathiasi Shawovi",
	["Back to {npc:4163}"] = "Zpět do {npc:4163}",
	["Back to {npc:5165}"] = "Zpět do {npc:5165}",
	["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "Jdi na sever do {zone:1453}. Shaw stojí nahoře v budově SI:7 v {object:2100} (quest říká Barracks, ale myslí SI:7).",
	["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "Jdi na západ k {area:133}. Vedle silnice k jeho vchodu stojí dřevěná točitá věž: {npc:6886} čeká ve stealthu na horní plošině vedle {npc:1211} levelu 10, takže ho uvidíš jen zblízka.",
	["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "Jdi na západ do {zone:1457}. {npc:4163} je pod zemí v {area:1658}: cesta dolů je otvor u paty rozštípnutého stromu nalevo od stromu Arch Druida, poblíž trenéra nightsaberů. Její značka na mapě se ukazuje na povrchu.",
	["Pick Pocket Sethir the Ancient for {item:7737}"] = "Okraď Sethira the Ancient (Pick Pocket) o {item:7737}",
	["{item:7298} (Alliance)"] = "{item:7298} (Aliance)",
	["{npc:332}, SI:7"] = "{npc:332}, SI:7",
	["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165} je v {object:32383}, čtvrti rogue na severu {zone:1455}: vejdi do budovy, před kterou stojí podezřelý překupník, a jdi dolů po schodech.",
}
t.guides["forever/class/rogue/blade-of-cunning-horde"] = {
	["A dagger at 10 from your home town's rogue quests."] = "Dýka na 10 z rogue questů tvého domovského města.",
	["At 10 {npc:2130}, the rogue trainer upstairs in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}."] = "Na 10 tě {npc:2130}, trenér rogue nahoře v {area:2119} v {area:159}, pošle k {quest:1885} v {zone:1458}.",
	["At 10 {npc:3170}, the rogue trainer in {area:362}, sends you to {quest:1859} in {zone:1454}. It is only a pointer: an Orc already in {zone:1454} can skip it and take {quest:1963} from {quest:1859} straight away."] = "Na 10 tě {npc:3170}, trenér rogue v {area:362}, pošle k {quest:1859} v {zone:1454}. Je to jen rozcestník: Ork, který už je v {zone:1454}, ho může přeskočit a vzít {quest:1963} od {quest:1859} rovnou.",
	["Back to {npc:6446}"] = "Zpět do {npc:6446}",
	["Back to {npc:6467}"] = "Zpět do {npc:6467}",
	["Pick Pocket Gamon for {item:7208}"] = "Okraď Gamona (Pick Pocket) o {item:7208}",
	["The {object:36073}"] = "{object:36073}",
	["{item:7298} (Horde)"] = "{item:7298} (Horda)",
	["{npc:6467} and {npc:2425}"] = "{npc:6467} a {npc:2425}",
	["{quest:1859} hands the satchel back: now open it. {npc:6466} (level 12) kneels by the innkeeper in the inn in the {object:172982}; stealth up and pick his pocket for {item:7208} (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on {item:7209} in your bags. If you have trained {spell:1804}, you can pick the satchel's lock instead."] = "{quest:1859} ti vrátí brašnu: teď ji otevři. {npc:6466} (level 12) klečí u hostinského v hostinci v {object:172982}; zapni stealth a vybij mu kapsu kvůli {item:7208} (nezabíjej ho: klíč skoro nikdy nepadne). Hráči ho často zabíjejí, takže na něj můžeš čekat až 5 minut. Pak použij klíč na {item:7209} v batohu. Pokud máš naučený {spell:1804}, můžeš zámek brašny místo toho odemknout.",
	["{quest:1859} stands in the {object:172960}, the canyon under the {object:172982}. Trolls: take {quest:1963} from him at 10."] = "{quest:1859} stojí v {object:172960}, kaňonu pod {object:172982}. Trollové: na levelu 10 si od něj vezměte {quest:1963}.",
	["{quest:1885} stands in the {object:36073}."] = "{quest:1885} stojí v {object:36073}.",
}
t.guides["forever/class/rogue/certificate-of-thievery"] = {
	["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "Na 16 tě {npc:1234} v {area:2102} v {area:131} pošle k {npc:5165} do {object:32383} v {zone:1455}.",
	["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "Na 16 tě {npc:3599} v hostinci {area:186} pošle k {quest:2259} v {zone:1457}.",
	["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "Na 16 tě {npc:917}, trenér rogue nahoře v Lion's Pride Inn v {area:87}, pošle k {npc:6946} v {zone:1453}. Jeho přijetí uzavře rozcestníky ostatních měst.",
	["Back to {npc:6966}"] = "Zpět do {npc:6966}",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "Jdi na východ přes {zone:1429} do Redridge, nebo leť do {area:69}. {npc:6966} stojí na bedně na jednom z mol v {area:69}, jižně od města; spolu s úkolem ti dá {item:5060} (další prodává {npc:3090} v {area:69}). {spell:1804} bez nástrojů v batohu nefunguje.",
	["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214} stojí v {area:1658}. Pak loď z {area:702} do {area:442} a loď z {area:442} do {area:17203}.",
	["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165} je v domě, před kterým stojí podezřelý překupník, v {object:32383}, dolů po schodech. Pak leť nebo vezmi {area:2257} do {zone:1453}.",
	["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282} stojí východně od {area:69}, nahoře mimo cestu; poblíž se toulají Blackrock orkové. Uvnitř se Practice Lockboxes respawnují skoro hned: odemykej je, dokud se ti neotevře {object:121264} (zhruba 25 Lockpickingu). Strop Lockpickingu ti roste o 5 za level, takže nízká postava se může zaseknout. Některé skříňky mají past (třeba mrazivou); dovednost i tak roste. Ve Forever se u skříněk toulají pavouci na levelu 20: nejdřív je vyčisti nebo si vezmi kamaráda. Skříňka obsahuje žeton vždycky a je zpátky dvě sekundy po použití. Trénuj dál, dokud ti dává dovednost: další class quest chce kolem 75.",
}
t.guides["forever/class/rogue/plundering-the-plunderers"] = {
	["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "Na 16 tě {npc:3170}, trenér rogue v {area:362}, pošle k {npc:3401} v {zone:1454}.",
	["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "Na 16 tě {npc:6467} v {object:36073} pošle k {npc:3401} v {zone:1454}. Vezmi od něj i {quest:1998}; plní se v {zone:1421} na konci tohoto návodu.",
	["Back to {npc:6467}"] = "Zpět do {npc:6467}",
	["Back to {npc:7161}"] = "Zpět do {npc:7161}",
	["Fly or walk to {area:392} on the {zone:1413} coast. {npc:7161} stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an {item:7970} and {item:5060} ({spell:1804} does not work without the tools in your bags)."] = "Leť nebo dojdi do {area:392} na pobřeží {zone:1413}. {npc:7161} stojí v malé kůlně u banky, do kopce vlevo před přístavem. Jeho Gizmotronic Apparatus vedle něj vydává, co práce potřebuje: vezmi {item:7970} a {item:5060} ({spell:1804} bez nástrojů v taškách nefunguje).",
	["Follow the coast south from {area:392} to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of {object:123462}: it is empty, but opening it calls a giant level 50 {npc:7168} into the next room. Stay stealthed, put the {item:7970} on your action bar, target {npc:7168} and use it: the parrot shrinks to level 18. Kill it for the {item:7968}."] = "Jdi podél pobřeží na jih od {area:392} k první pirátské lodi na mělčině, Tide Razor, a vylez na palubu po přídi. Na prostřední palubě se Buccaneer's Strongboxes rychle obnovují: odemykej je, dokud nemáš Lockpicking asi 30 (pár jich má past s frost novou nebo tě promění v krysu; odemykat jde i jako krysa). Odemykej, dokud dávají dovednost: úkol s jedy na 20 končí u lockboxu, který potřebuje asi 75, a tyhle bedny jsou nejbližší trénink. Pak sejdi do spodního podpalubí a odemkni {object:123462}: je prázdná, ale otevření přivolá do vedlejší místnosti obřího {npc:7168} levelu 50. Zůstaň ve stealthu, dej si {item:7970} na action bar, zaměř {npc:7168} a použij ho: papoušek se zmenší na level 18. Zabij ho kvůli {item:7968}.",
	["If you have no {item:5060} left, ask {npc:6566}, the outfitter in the {object:36073}."] = "Pokud ti nezbyl žádný {item:5060}, zeptej se {npc:6566}, obchodníka s výbavou v {object:36073}.",
	["Take the zeppelin from {zone:1454} to the {zone:1458} and head south into Silverpine. {quest:1998} (level 16) stands alone on the old ferry dock on {area:1338}, north-east of the {area:228}. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death."] = "Vezmi zeppelin z {zone:1454} do {zone:1458} a jdi na jih do Silverpine. {quest:1998} (level 16) stojí sám na starém přístavišti přívozu na {area:1338}, severovýchodně od {area:228}. Jeho Uppercut tě odhazuje, takže s ním nebojuj na kraji mola. Hlavu dropne vždycky a po smrti je zpátky za 4,5 minuty.",
	["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Deset {item:7676}, energetického nápoje pro rogue, z hordských zakázek na páčení zámků na 16.",
	["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}. Train {spell:1804} from {npc:3401} (or any rogue trainer) now if you lack it: this job is a lockpicking test."] = "Nemrtví jedou zeppelinem z věží před {zone:1458} do {zone:1411}. {npc:3401} a {quest:2379} stojí v {object:172960}, kaňonu pod {object:172982}. Pokud ho nemáš, vytrénuj si teď {spell:1804} u {npc:3401} (nebo u kteréhokoli trenéra rogue): tahle zakázka je zkouška páčení zámků.",
	["{npc:3401} and {quest:2379}"] = "{npc:3401} a {quest:2379}",
}
t.guides["forever/class/rogue/poisons-alliance"] = {
	["/lay with the Doc targeted"] = "/lay se zaměřeným Docem",
	["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: the Auction House in the {object:2096}; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "Všechny čtyři jsou v {zone:1453}. {item:3421}: Bernard nebo květinářství {npc:1303} u kanálu {object:2096}. {item:3372}: hodně obchodníků se smíšeným zbožím a alchymií ({npc:1257}, {npc:1325} a další). {item:4371}: aukce v {object:2096}; dodavatelé inženýrství mají jen jeden a skoro vždy vyprodaný, a inženýr ho umí vyrobit. {item:8431} leží na podlaze u levého konce pultu v {object:2177}, krejčovství na kanálech; sebrat ho jde jen s tímto questem. Když léčbu přeskočíš, {spell:9810} odstraní i {item:6452} ({skill:129}) nebo druidův {spell:526}.",
	["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "Na 20 tě {npc:332}, nahoře v budově SI:7 v {object:2100}, pošle k {npc:7024} v {zone:1436}. Tímhle řetězem se ve Foreveru učíš Poisons, tak ho nepřeskakuj.",
	["Back to {npc:7207}"] = "Zpět do {npc:7207}",
	["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever učí Poisons touhle sérií, ne u trenéra; recept {item:7676} k ní patří.",
	["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol. Then sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "Nejdřív získej klíč. {npc:7051} (level 23, ne elite) začíná u vchodu do věže a chodí okruh kolem ní zvenku; je to ten s ježatými vlasy, za kterým se táhnou žluté jiskry. Zapni stealth a dej mu zezadu {spell:921}: klíč má vždycky. Bije tvrdě: když se stealth rozbije, uteč přes {spell:2983}. Dávej pozor na dvojici Defias Drones, která taky hlídkuje. Pak se proplíž nahoru do věže. Patra hlídají Defias Tower Patrollers (23) a Sentries (24); Ambush s dýkou je zabije rovnou, pokud je chceš vyčistit. {npc:7053}, elite levelu 26, čeká v nejvyšším patře: sapni ho, nebo si vezmi kamaráda. {object:123214} vedle jeho stolu vyžaduje Lockpicking zhruba 70–75 (předtím si ho natrénuj na bednách v {area:97} v Redridge). Trik: když jsou Sentries pryč, skoč ze židle na lampu a z ní na knihovnu nad truhlou, vystup ze stealthu a otevři truhlu odtamtud. Otevření tě otráví {spell:9810}, což ti na chvíli zablokuje stealth a drone tě uvidí; proto napřed klíč. Pak zmiz.",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {spell:8681} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "Jdi na sever přes Elwynn do {zone:1453}; Mathias Shaw je nahoře v SI:7. Naučí tě Poisons a dá ti recept na {item:7676}. Jedy se vyrábějí, nekupují: každá várka {spell:8681} potřebuje {item:2928} a {item:3371}, které prodávají {npc:1325} a {npc:1326} v {object:2100} vedle SI:7. Kup od každého stack, otevři Poisons ve spellbooku a vyrob je, pak dej jed na zbraň.",
	["Poisons (Alliance)"] = "Poisons (Aliance)",
	["The cure's ingredients"] = "Přísady do léku",
	["{item:4371}: the Auction House"] = "{item:4371}: aukce",
	["{npc:332}: Poisons"] = "{npc:332}: Poisons",
	["{quest:2359}, solo"] = "{quest:2359}, sólo",
	["{quest:2359}, with a group"] = "{quest:2359}, se skupinou",
	["{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down."] = "{quest:2607} pořád máš. {npc:7207} pracuje ve sklepě budovy SI:7: schody dolů jsou pod schody do patra, za {npc:1325}. Označ ho, napiš /lay (nic za tím), aby tě vyšetřil, a počkej. Když nic neudělá, quest zruš, vezmi ho znovu a počkej, až tě požádá, ať si lehneš.",
}
t.guides["forever/class/rogue/poisons-horde"] = {
	["/salute {npc:3401}"] = "/salute {npc:3401}",
	["Back to {npc:3401}"] = "Zpět do {npc:3401}",
	["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each."] = "Leť zpátky do {zone:1454} ({area:392} nebo Crossroads; rychlejší je umřít u věže a vrátit se cestou spirit healera do Crossroads). {item:8072} si potom nech. Než opustíš {area:263}, kup u Rekkula {item:2928} a Empty Vials: jakmile tě Hinott naučí Poisons, každá dávka {spell:8681} spotřebuje od obojího jeden kus.",
	["Fly to the Crossroads and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}."] = "Leť do Crossroads a zamiř na sever k věži Venture Co. nad {area:382}. Fizzule stojí pod stromem východně od věže, venku, a dokud nedostane signál, je nepřátelský. Zaměř ho zhruba ze 50 yardů a dvakrát vystřel z {item:8051}, pak k němu dojdi zepředu a /salute. V jakémkoli jiném pořadí zaútočí. Ztratil jsi {item:8051}? Quest zahoď a vezmi znovu u {npc:3401}.",
	["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever učí Poisons touhle sérií, ne u trenéra; recept {item:7676} k ní patří.",
	["Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor"] = "Lockpicking zhruba 75: odemykej Buccaneer's Strongboxes na lodi Tide Razor",
	["Lockpicking practice"] = "Trénink lockpickingu",
	["Pick Pocket Foreman Silixiz for {item:8072}"] = "Okraď Foremana Silixize (Pick Pocket) o {item:8072}",
	["Poisons (Horde)"] = "Poisons (Horda)",
	["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {spell:8681} from Rekkul's dust and vials, and use it on your weapon."] = "Vezmi zeppelin z {zone:1454} do {zone:1458} a jdi po cestě na jih přes {zone:1421} do {area:287}, k {area:272}. {npc:2391} pracuje v budově vedle letové trasy, vedle {npc:2216}, venku je vůz. Jestli jsi ztratil Sample of Zanzil's Mixture, zahoď quest a vezmi ho znovu od {npc:3401}. Zůstaň u něj asi minutu, zatímco vaří lék; když to nikdy nedokončí, zahoď quest a vezmi ho znovu od něj. Pak otevři Poisons ze spellbooku, vyrob {spell:8681} z Rekkulova prachu a lahviček a použij ho na zbraň.",
	["Tide Razor"] = "Tide Razor",
	["Wait for the cure"] = "Počkej na lék",
	["{npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the {object:172960}, sells a Jambiya."] = "{npc:3401} stojí v {object:172960}, kaňonu pod {object:172982}. Vezmi quest a počkej: řekne tři věty a zasalutuje ti. Po jeho třetí větě si ho dej do targetu a napiš /salute. Když se to nezapočítá, quest zahoď a vezmi znovu. Úkol ve věži, který tě čeká, stojí na Ambush, který potřebuje dýku: když žádnou nemáš, Kareth, obchodník se zbraněmi v {object:172960}, prodává Jambiyu.",
	["{object:129127} at the end of the tower job needs Lockpicking of about 70-75. Train {spell:1804} from Gest or {npc:3401} in the {object:172960} if you lack it, carry {item:5060}, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of {area:392}: they come back fast. Your cap rises 5 per level."] = "{object:129127} na konci práce ve věži potřebuje Lockpicking kolem 70–75. Pokud ho nemáš, nauč se {spell:1804} u Gesta nebo {npc:3401} v {object:172960}, nos {item:5060} a odemykej Buccaneer's Strongboxes na prostřední palubě Tide Razoru, vyplavené pirátské lodi jižně od {area:392}: rychle se respawnují. Strop ti roste o 5 za level.",
	["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: nech si {item:8051}",
}
t.guides["forever/class/rogue/ravenholdt"] = {
	["At 24 any capital's rogue trainer ({npc:332} or {npc:918} in {zone:1453}, Gest or Ormok in {zone:1454}, and the others) has an {item:17126} from {npc:13936} for you: ask for it in their talk window. Open it: the quest gives you the {item:17125} for {npc:6707}. Learn {spell:1846} from your trainer first if you have not; the way in is a test of it."] = "Na 24 pro tebe má trenér rogue kteréhokoli hlavního města ({npc:332} nebo {npc:918} v {zone:1453}, Gest nebo Ormok v {zone:1454} a ostatní) {item:17126} od {npc:13936}: požádej o něj v jeho okně rozhovoru. Otevři ho: quest ti dá {item:17125} pro {npc:6707}. Pokud ho nemáš, nejdřív se u trenéra nauč {spell:1846}; cesta dovnitř je jeho zkouška.",
	["Back to {npc:13085}"] = "Zpět do {npc:13085}",
	["Back to {npc:13085}; the report sends you after the Perenolde heirlooms. Two towers stand among the {area:281}, in the middle of the {zone:1416}, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside."] = "Zpět k {npc:13085}; hlášení tě pošle za dědictvím Perenolde. Mezi {area:281} uprostřed {zone:1416} stojí dvě věže v držení zlobrů: štít leží v severní věži, meč v jižní, kterou obklopují a z dálky hlídají elitní zlobři. Zůstaň ve stealthu; dědictví uvnitř nic nehlídá.",
	["Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment."] = "Falconcrestovi muži provádějí předání na jižním konci {area:1057}, staré zdi mezi Arathi a {area:287}. Zabij ty dva, co hlídají bednu, a vezmi {item:275882}. {item:275706} si nech: {npc:13085} ho chce zpátky spolu se zásilkou.",
	["Horde fly to {area:272}, Alliance to {area:271}. The trail to the manor is hard to see: it starts behind the plateau north of {area:275}, east of {area:272}, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast {spell:1846} near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies {area:3486}: {npc:6707} is upstairs inside. Do not attack anyone at the manor: it costs {npc:13936} reputation."] = "Horda leť do {area:272}, Aliance do {area:271}. Stezka k sídlu je špatně vidět: začíná za plošinou severně od {area:275}, východně od {area:272}, stoupá do kopců a dvakrát se stočí k malému tunelu. V tunelu je truhla: neotvírej ji. Seslej poblíž {spell:1846} a dojdi až k ní; to je Rite of Cunning (vrací se po 5 minutách). Otevření truhly přivolá Miltona, elite rogua zhruba levelu 32. Za tunelem leží {area:3486}: {npc:6707} je uvnitř nahoře. Na sídle na nikoho neútoč: stojí to reputaci u {npc:13936}.",
	["In your mid 30s {npc:13085} has two more jobs; take both. {npc:266357} leads a Syndicate scouting party at {area:280}, in the east of the {zone:1416}, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. {spell:921} can miss several times in a row."] = "Kolem levelu 35 má {npc:13085} další dva úkoly; vezmi oba. {npc:266357} vede průzkumnou skupinu Syndicate v {area:280} na východě {zone:1416}, v jednom z domů, kolem něj Syndicate ve stealthu. Okraď ho o hlášení a nezabíjej ho: nedropuje ho. Pokud máš nižší level než on, prokoukne stealth; pomůže Master of Deception, nebo ho rozptyl přes Distract, dej Vanish a přijď zezadu. {spell:921} může několikrát po sobě minout.",
	["Pick Pocket Barton for {item:275482}"] = "Okraď Bartona (Pick Pocket) o {item:275482}",
	["Pick Pocket Syndicate members for {quest:6701}"] = "Okrádej členy Syndicate (Pick Pocket) kvůli {quest:6701}",
	["Stromgarde's Syndicate Prowlers and Conjurors are elite (level 35-36): a rogue of 36 can slip past them, but fighting one alone is hard, so stay hidden or bring a friend. Put on the {item:275706} ({quest:96784} hands it to you at the footlocker) to pass as one of them; stealth or suspicious acts can break it. If the footlocker gave you no uniform, Anastasia hands you one with {quest:96785}. {npc:266847} is not inside the keep: she stands on a ledge on the outside of the castle wall. Jump across to it from the roof of the house beside the ledge."] = "Syndicate Prowlers a Conjurors ve Stromgarde jsou elite (level 35–36): rogue na 36 kolem nich proklouzne, ale bojovat s jedním sám je těžké, takže zůstaň skrytý nebo vezmi kamaráda. Obleč si {item:275706} (dá ti ji {quest:96784} u truhly), ať vypadáš jako jeden z nich; stealth nebo podezřelé chování ho může prozradit. Pokud ti truhla uniformu nedala, dá ti ji Anastasia s {quest:96785}. {npc:266847} není uvnitř pevnosti: stojí na římse na vnější straně hradní zdi. Skoč na ni ze střechy domu vedle římsy.",
	["The {item:17126}"] = "{item:17126}",
	["{area:324} in western Arathi is a Syndicate stronghold; to get in you need a uniform. {area:313}, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the {object:656157} there and take the uniform; that ends {quest:96783}."] = "{area:324} v západním Arathi je pevnost Syndicate; dovnitř potřebuješ uniformu. {area:313} v severozápadním Arathi drží Syndicate Highwaymen, Pathstalkers a Mercenaries (level 30–32): najdi tam {object:656157} a vezmi uniformu; tím končí {quest:96783}.",
	["{npc:13085}: 70 silver, 300 {npc:13936} reputation"] = "{npc:13085}: 70 stříbrných, 300 reputace u {npc:13936}",
	["{npc:13936} reputation"] = "Reputace u {npc:13936}",
	["{npc:266216} is inside {area:275}, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says {npc:13085}. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry {quest:6701} for the guards' repeatable reputation quest."] = "{npc:266216} je uvnitř {area:275}, pevnosti Syndicate jižně od sídla; může stát na kterémkoli z patnácti míst v pevnosti, tak hledej. Rychle a potichu, říká {npc:13085}. Cestou okraď (Pick Pocket) Syndicate Rogues, Shadow Mages a Watchmen s levelem 20–21: nosí {quest:6701} pro opakovatelný reputační quest stráží.",
	["{quest:96784}: the {item:275706}"] = "{quest:96784}: {item:275706}",
}
t.guides["forever/class/rogue/the-azure-key"] = {
	["Alliance fly to {area:3137}, Horde to {area:1237}. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern {zone:1447} carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. {spell:921} them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with {area:1769}, mark them At War in your reputation panel first. They cast {spell:403} and {spell:6535}, heal each other and run at low health."] = "Aliance letí do {area:3137}, Horda do {area:1237}. Vak nesou jen Timbermaw Shamans levelu 50–51 ve furbolžích kopcích severního {zone:1447} (furbolgové 47–49 dál na jih ne): padá zhruba z jednoho zabití z třiceti. Místo toho je {spell:921} a nepřijdeš o reputaci Timbermaw; pokud jsi s {area:1769} Unfriendly nebo líp, nejdřív je v panelu reputace označ At War. Sesílají {spell:403} a {spell:6535}, léčí se navzájem a při nízkém zdraví utíkají.",
	["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "Na 50 ho má {npc:3328} v {object:172960}; stejně tak {npc:4583} v {object:36073} v {zone:1458}.",
	["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} in {zone:1455}."] = "Na 50 ho má {npc:918} v {object:2100} v {zone:1453}; stejně tak Syurna v {zone:1457} a {npc:5165} v {zone:1455}.",
	["Back to Xylem"] = "Zpět k Xylemovi",
	["Look at the reward window before you hand in: Classic offered the {item:19982}, the {item:19984} or the {item:20255}, and Forever's notes say the choice may be gone."] = "Než quest odevzdáš, podívej se do okna odměn: Classic nabízel {item:19982}, {item:19984} nebo {item:20255} a poznámky k Forever říkají, že volba možná zmizela.",
	["Lord Ravenholdt"] = "Lord Ravenholdt",
	["Morphaz in the {area:1417}"] = "Morphaz v {area:1417}",
	["Morphaz, a level 52 elite green drake, lives deep in the {area:1417}: a group of five, level 50-54. The temple stands in the {area:74}; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their {spell:12533} is nature damage: nature protection potions help; poisons and {spell:2094} do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all."] = "Morphaz, elite zelený drak level 52, žije hluboko v {area:1417}: skupina pěti, level 50–54. Chrám stojí v {area:74}; vlez do potopené stavby, proplav jí dolů a jdi chodbou k portálu. Horda: leť do {area:75}; Aliance: leť do {area:1438} a jeď dál. Když dorazíš, není tam: nejdřív zabij šest trolích strážců (elity 50–52) na plošinách kolem horního kruhu, čímž se otevře cesta dolů (levá rampa od vchodu) k {npc:5710} v Pit of Sacrifice. Jammal'anova smrt vyvolá dva draky, Weavera a Dreamscythe; když jsou oba mrtví, objeví se Morphaz a Hazzas spolu a bojují ve dvojici. Jejich {spell:12533} je nature damage: pomáhají lektvary ochrany proti přírodě; jedy a {spell:2094} na ně nefungují. Klíč padá vždycky. Hunteři, kněží a mágové na levelu 50 potřebují Morphaze taky: jeden průchod poslouží všem.",
	["Ravenholdt reputation"] = "Reputace u Ravenholdtu",
	["Ravenholdt reputation and experience at 50; Classic's item choice may be gone on Forever."] = "Reputace u Ravenholdtu a zkušenosti na levelu 50; výběr itemu z Classicu na Foreveru možná chybí.",
	["The Forest Oozes (level 52-53, {spell:6907} up close) drop a fragment four times in five: the biggest group, seven of them, is in the {area:2497} hills of north-eastern {zone:1447}, four more south-east of {area:1237}. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear."] = "Forest Oozes (level 52–53, zblízka {spell:6907}) dropují úlomek čtyřikrát z pěti: největší skupina, sedm kusů, je v kopcích {area:2497} na severovýchodě {zone:1447}, další čtyři jihovýchodně od {area:1237}. Před zabitím jim vybílej kapsy pro úlomek nebo dva navíc. Zabíjení Mistwing Ravagers a hipogryfů, kteří s nimi sdílí místa, přivolá víc slizů.",
	["{area:3486} hides in the hills east of {area:272}. Horde fly to {area:272}, Alliance to {area:271}. The trail starts behind the plateau north of {area:275}, climbs into the hills and runs through a small tunnel into the {zone:1416}; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you."] = "{area:3486} se skrývá v kopcích východně od {area:272}. Horda letí do {area:272}, Aliance do {area:271}. Stezka začíná za plošinou severně od {area:275}, stoupá do kopců a vede malým tunelem do {zone:1416}; Lord Jorach je uvnitř sídla. Na nikoho u sídla neútoč: se ztracenou reputací Ravenholdt s tebou nepromluví.",
	["{npc:8395}, camped below the cliffs just east of {area:1237}, teleports you up (dismount first); a trail leads to Xylem's tower."] = "{npc:8395} tábořící pod útesy kousek východně od {area:1237} tě teleportuje nahoru (nejdřív sesedni); k Xylemově věži vede stezka.",
	["{quest:8233} (Alliance)"] = "{quest:8233} (Aliance)",
	["{quest:8233} (Horde)"] = "{quest:8233} (Horda)",
}
t.guides["forever/class/rogue/the-eye-of-bhossca"] = {
	["Back to the dead drop"] = "Zpět k mrtvé schránce",
	["C's dead drop"] = "Cova mrtvá schránka",
	["C's next job comes by letter: once you are level 30 and have done the horn job (The {item:210183}, its payment from this {object:410369} handed in), visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "Další práce od C přijde dopisem: jakmile máš level 30 a hotovou práci s rohem (The {item:210183}, její platbu z této {object:410369} odevzdanou), navštiv kterékoli hlavní město a Cův dopis dorazí do poštovní schránky; teprve pak ho {object:410369} u {area:204}, v jižním Silverpine kousek jižně od {area:236}, nabídne. Data questu uvádějí minimum 25, ale hráči dopis i práci dostávají na 30.",
	["Place the eye in the {object:410369} near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared."] = "Vlož oko do {object:410369} u Pyrewoodu. Při příští plánované návštěvě hlavního města zkontroluj poštovní schránku kvůli platebnímu dopisu od C, pak se sem vrať pro quest s odměnou. Platba nemusí přijít hned; infiltraci neopakuj jen proto, že se odměna zatím neobjevila.",
	["The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {item:210955} from the {object:412147} in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the {item:210967}. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance."] = "Klášter stojí na dalekém severovýchodě {zone:1420}. Jdi dovnitř sám, mimo jakoukoli skupinu. Před vstupem si vezmi {item:210955} z {object:412147} ve stájích za klášterem a obleč si ho; stealth a podezřelé akce ho sundají, takže si ho po každé změně křídla obleč znovu. V Graveyardu, v Chamber of Atonement (první velká místnost), použij {spell:921} na {npc:4293} nebo Scarlet Crier a získej {item:210963}. V Library jím otevři Personal Letterbox v Athenaeu a přečti {item:210967}. Pošle tě zpátky do Graveyardu, kde si sedneš na obě lavice mezi dvěma sochami. Sleduj zprávy mechanismu, pak vezmi {item:210968} z kamenné schránky: u schránky stojí elite a za ním hlídka, ale od severního mauzolea můžeš otáčet kamerou, dokud se bedýnka neukáže, a kliknout na ni přes zeď (funguje i klávesa pro interakci). Blízko mauzolea chodí elite duch; zlomený kus na jeho okraji tě drží mimo jeho cestu. Pak se vrať do Library pro zamčený relikviář a oko. Vyhni se probíjení instancí.",
	["The {area:796}"] = "{area:796}",
}
t.guides["forever/class/rogue/the-horn-of-xelthos"] = {
	["Back to the dead drop"] = "Zpět k mrtvé schránce",
	["C's dead drop"] = "Cova mrtvá schránka",
	["Go in alone and use the {item:210186} at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring {item:5140} and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the {item:210213}, then the brother in the room reached by turning right at the top of the stairs for the {item:210212} (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach."] = "Jdi dovnitř sám a u brány na nádvoří použij {item:210186}. Hráči hlásí i to, že ti dveře na nádvoří otevře osvobozený vězeň: když umřeš, zatímco je otevírá, zůstaň mrtvý, dokud nebudou otevřené; po oživení zůstanou otevřené. Pokud umíš Vanish, vezmi si {item:5140} a před vstupem zkontroluj jeho cooldown; měj ho připravený pro případ nepovedeného přiblížení. Okraď sestru v jídelně o {item:210213}, pak bratra v místnosti, do které vedou schody nahoru a doprava, o {item:210212} (rogue levelu 20 bez Vanishe může potřebovat body v Master of Deception, aby se k druhému dostal nepozorovaně). Spoj je někde v bezpečí: tím se rozbije stealth. Nejdřív si uvolni místo v batohu: otevření truhly s plnými batohy může klíč spotřebovat a roh nedat. Vrať se do stájí na nádvoří a použij spojený klíč na truhlu, uvnitř je roh. Drž se dál od elite poblíž; minimální level questu nezaručuje bezpečné přiblížení.",
	["{item:210183}, inside {area:236}"] = "{item:210183}, uvnitř {area:236}",
	["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon, a short way north-east of {area:460}. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them in their pockets. Stealth up behind one and {spell:921} it; killing them does not give it."] = "{npc:4086}, goblin přátelský k oběma frakcím, stojí mezi Venture Co. v {area:461} na východě Stonetalonu, kousek severovýchodně od {area:460}. Horda letí do {area:460}; Aliance do {area:467}. Než vydá výbušniny, chce {item:210187}: nosí je v kapsách Venture Co. Loggers (level 18), kteří kolem něj pracují. Připlíž se ve stealthu za jednoho a použij {spell:921}; zabitím ho nezískáš.",
}
t.guides["forever/class/shaman/call-of-air-alliance"] = {
	["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "Na 30 tě {npc:258098}, trenér šamanů v {zone:1455}, pošle k {npc:259023} v {zone:1417}. Tvoje vzdušné totemy levelu 30 (Grounding, {spell:10596}) potřebují {item:5178}, který dá.",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Pět Twisted Air Totems. Nosí je kentauři Maraudine (level 36–40) severně a severovýchodně od {area:2408} v západním {zone:1443}; Scouts dropnou jeden skoro každé druhé zabití. Wranglers házejí síť a odzbrojují, Windchasers léčí, Stormers sesílají {spell:9654}: tahej je po jednom. Respawn asi pět minut.",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Pět Twisted Earth Totems. Nosí je Lost Ones (murloci, level 34–39) severně a severovýchodně od {area:75} v {zone:1435}; většina při zranění utíká pro pomoc.",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Pět Twisted Fire Totems. Nosí je troggové Stonevault (Skullthumpers, Bonesnappers a Shamans, level 37–41) jižně od {area:338} v {zone:1418}; Shamans pokládají Fire Nova Totems a {npc:3560}, Bonesnappers při zranění utíkají pro pomoc. Respawn asi pět minut.",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Pět Twisted Water Totems. Nosí je murloci Mirefin (level 35–38) severovýchodně od {area:496} v severním {zone:1445}.",
	["The steam pools"] = "Parní jezírka",
	["Twisted Air Totems"] = "Twisted Air Totems",
	["Twisted Earth Totems"] = "Twisted Earth Totems",
	["Twisted Fire Totems"] = "Twisted Fire Totems",
	["Twisted Water Totems"] = "Twisted Water Totems",
	["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} je dungeon pro pět hráčů na jižním okraji {zone:1413} (šipka ukazuje na jeho vchod); {npc:4421} (level 33, elite) je poslední boss. Sesílá {spell:8292}, {spell:139} na spojence a Purity; {item:274463} dropuje jen z ní.",
	["{item:212792}, from the {npc:216474}"] = "{item:212792}, od {npc:216474}",
	["{item:274463}, from {npc:4421}"] = "{item:274463}, od {npc:4421}",
}
t.guides["forever/class/shaman/call-of-air-horde"] = {
	["At 30 Skyborne shamans get their own {quest:96136}. {npc:259119} waits where the airship from Zephras Isle lands, in northern {zone:1412} beside {zone:1456}. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to {npc:5906} in {zone:1456} (next step): the trainers' {quest:96136} is open to Skyborne and gives the same totem."] = "Na 30 dostanou šamani Skyborne vlastní {quest:96136}. {npc:259119} čeká tam, kde přistává vzducholoď ze Zephras Isle, v severním {zone:1412} vedle {zone:1456}. Tvoje vzdušné totemy levelu 30 potřebují Air Totem, který dá Prate Cloudseer. Pokud pro tebe nic nemá, jdi nahoru k {npc:5906} v {zone:1456} (další krok): {quest:96136} od trenérů je Skyborne otevřený a dá stejný totem.",
	["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} she gives."] = "Na 30 tě {npc:5892} v {object:172957} pošle k {npc:5905} v {zone:1441}. Tvoje vzdušné totemy levelu 30 (Grounding, {spell:10596}) potřebují {item:5178}, který dá.",
	["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1532} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "Na 30 tě {npc:5906}, trenér šamanů na {area:1640} v {zone:1456}, pošle k {npc:5905} v {zone:1441}. Tvoje vzdušné totemy levelu 30 (Grounding, {spell:10596}) potřebují Air Totem, který dá Prate. Už neseš {quest:1532} od {npc:5892} z {zone:1454}? Jde taky k {npc:5905}: {npc:5906} přeskoč.",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Pět Twisted Air Totems. Nosí je kentauři Maraudine (level 36–40) severně a severovýchodně od {area:2408} v západním {zone:1443}; Scouts dropnou jeden skoro každé druhé zabití. Wranglers házejí síť a odzbrojují, Windchasers léčí, Stormers sesílají {spell:9654}: tahej je po jednom. Respawn asi pět minut.",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Pět Twisted Earth Totems. Nosí je Lost Ones (murloci, level 34–39) severně a severovýchodně od {area:75} v {zone:1435}; většina při zranění utíká pro pomoc.",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Pět Twisted Fire Totems. Nosí je troggové Stonevault (Skullthumpers, Bonesnappers a Shamans, level 37–41) jižně od {area:338} v {zone:1418}; Shamans pokládají Fire Nova Totems a {npc:3560}, Bonesnappers při zranění utíkají pro pomoc. Respawn asi pět minut.",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Pět Twisted Water Totems. Nosí je murloci Mirefin (level 35–38) severovýchodně od {area:496} v severním {zone:1445}.",
	["Fly to {area:484}. {npc:5905} stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running."] = "Leť do {area:484}. {npc:5905} stojí na římse nad ústím jeskyně ve stěně kaňonu severovýchodně od stanoviště, ne uvnitř jeskyně: vylez po svahu vedle. Dá ti i hodinu rychlejších útoků a běhu.",
	["The steam pools"] = "Parní jezírka",
	["Twisted Air Totems"] = "Twisted Air Totems",
	["Twisted Earth Totems"] = "Twisted Earth Totems",
	["Twisted Fire Totems"] = "Twisted Fire Totems",
	["Twisted Water Totems"] = "Twisted Water Totems",
	["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} je dungeon pro pět hráčů na jižním okraji {zone:1413} (šipka ukazuje na jeho vchod); {npc:4421} (level 33, elite) je poslední boss. Sesílá {spell:8292}, {spell:139} na spojence a Purity; {item:274463} dropuje jen z ní.",
	["{item:212792}, from the {npc:216474}"] = "{item:212792}, od {npc:216474}",
	["{item:274463}, from {npc:4421}"] = "{item:274463}, od {npc:4421}",
	["{npc:4722} stands at {area:484}."] = "{npc:4722} stojí v {area:484}.",
	["{quest:1531} and the Tempest's Weapons (Horde)"] = "{quest:1531} a Tempest's Weapons (Horda)",
}
t.guides["forever/class/shaman/call-of-earth-alliance"] = {
	["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "Zpět k Teovi do {area:77}. Dá ti {item:6635}: zatím ho nepij.",
	["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Přines {item:6656} zpět Teovi do {area:77}. {item:5175} si nech v taškách natrvalo: potřebuje ho každý zemní totem.",
	["Iceclaw Bear Pendants"] = "Iceclaw Bear Pendants",
	["Lost the {quest:94472}?"] = "Ztratil jsi {quest:94472}?",
	["Teo's {quest:94373} needs the {quest:98581} handed in first: {npc:658}, where you entered {area:132}, gives it to Dwarf shamans after his {quest:179}. Bring it up the road to {npc:257446} inside {area:77}."] = "Teův {quest:94373} vyžaduje nejdřív odevzdat {quest:98581}: {npc:658}, tam kde jsi vešel do {area:132}, ho dává trpasličím shamanům po svém {quest:179}. Odnes ho po cestě nahoru k {npc:257446} uvnitř {area:77}.",
	["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "Frostmane Troll Whelps (level 3–4) drží zasněžené svahy západně a jihozápadně od {area:77} a Frostmane Novices (level 3–4, hází Frostbolty z dálky) táboří jižně od něj. Přívěsky nosí obojí; respawnují se asi za tři minuty.",
	["{npc:257446}: a new {quest:94472}"] = "{npc:257446}: nový {quest:94472}",
	["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446}: {spell:8071} a tvůj {item:5175}",
	["{quest:94373} (Alliance)"] = "{quest:94373} (Aliance)",
}
t.guides["forever/class/shaman/call-of-earth-horde"] = {
	["Any Al'Aketh cultist can carry the {item:251924}: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond {npc:252095}, south-west of the village. Keep killing until one drops it."] = "{item:251924} může nést kterýkoli kultista Al'Aketh: Converts (level 2–3) u menhirů kousek východně od vesnice, nebo Brutes a Neophytes (level 4) v táboře za {npc:252095}, jihozápadně od vesnice. Zabíjej, dokud ho jeden nedropne.",
	["Back to Boro in {area:16635}. He hands you the {quest:1462}: do not drink it yet."] = "Zpět k Borovi do {area:16635}. Dá ti {quest:1462}: zatím ho nepij.",
	["Back to the Seer in {area:221}. She hands you the {quest:1462}: do not drink it yet."] = "Zpět k Vědmě do {area:221}. Dá ti {quest:1462}: zatím ho nepij.",
	["Back to {npc:5887} outside the Den. She hands you the {quest:1462}: do not drink it yet."] = "Zpět k {npc:5887} před Den. Dá ti {quest:1462}: zatím ho nepij.",
	["Bring the {item:6656} back to Boro. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Přines {item:6656} zpět Borovi. {item:5175} si nech v taškách natrvalo: potřebuje ho každý zemní totem.",
	["Bring the {item:6656} back to the Seer. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Přines {item:6656} zpět Vědmě. {item:5175} si nech v taškách natrvalo: potřebuje ho každý zemní totem.",
	["Bring the {item:6656} back to {npc:5887} outside the Den. Keep the {item:5175} she gives you in your bags for good: every earth totem needs it."] = "Přines {item:6656} zpět {npc:5887} před Den. {item:5175}, který ti dá, si nech v taškách natrvalo: potřebuje ho každý zemní totem.",
	["Felstalker Hooves"] = "Felstalker Hooves",
	["Felstalkers (level 3-4) prowl the slope below the {area:365}, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every {npc:3102} drops a hoof (four kills in five); they respawn in a little over three minutes."] = "Felstalkeři (level 3–4) se potulují po svahu pod {area:365}, jeskyní na severu údolí, a hned uvnitř jejího ústí mezi Vile Familiars. Skoro každý {npc:3102} dropne kopyto (čtyři zabití z pěti); respawnují se za něco přes tři minuty.",
	["Lost the {quest:1462}?"] = "Ztratil jsi {quest:1462}?",
	["Lost the {quest:1463}?"] = "Ztratil jsi {quest:1463}?",
	["The Bristleback Shamans (level 3-4) stand among the quilboar huts of {area:358}, east of the camp, and throw the odd {spell:403}. Four kills in five drop a salve; they respawn in about four minutes."] = "Bristleback Shamans (level 3–4) stojí mezi chýšemi quilboarů v {area:358}, východně od tábora, a občas hodí {spell:403}. Čtyři zabití z pěti dropnou mast; respawnují se asi za čtyři minuty.",
	["The {area:16988}"] = "{area:16988}",
	["{area:637} is a small pillar on a low mound due east of {npc:2991}'s well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the {item:6635}, then speak to the {npc:5891} before it fades (drink again if it does)."] = "{area:637} je malý sloup na nízké mohyle přímo východně od studny {npc:2991}, východně od tábora; ukáže se až zhruba z patnácti yardů a kolem se pasou nepřátelští kanci. Stoupni si vedle něj a vypij {item:6635}, pak promluv s {npc:5891}, než zmizí (když zmizí, vypij znovu).",
	["{area:639} sits on a ledge in the hills just south of the Den. The {area:638} up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the {item:6635}: the {npc:5891} appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path."] = "{area:639} leží na římse v kopcích kousek jižně od Den. {area:638} nahoru začíná u paty kopců jihozápadně od Den, mezi dvěma zahálejícími peony; stoupá na jihozápad do kopců a pak se stáčí zpátky na východ ke skále. Stoupni si těsně vedle kamene a vypij {item:6635}: {npc:5891} se objeví jen nakrátko, tak s ním hned promluv (když neodpovídá, jdi skoro pod něj). Cestou zpátky můžeš místo cesty seskočit z římsy směrem k Den.",
	["{item:6635}, beside {area:637}"] = "{item:6635}, vedle {area:637}",
	["{item:6635}, beside {area:639}"] = "{item:6635}, vedle {area:639}",
	["{npc:251374}: {spell:8071} and your {item:5175}"] = "{npc:251374}: {spell:8071} a tvůj {item:5175}",
	["{npc:5887}: a new {quest:1463}"] = "{npc:5887}: nový {quest:1463}",
	["{npc:5887}: {spell:8071} and your {item:5175}"] = "{npc:5887}: {spell:8071} a tvůj {item:5175}",
	["{npc:5888}: a new {quest:1462}"] = "{npc:5888}: nový {quest:1462}",
	["{npc:5888}: {spell:8071} and your {item:5175}"] = "{npc:5888}: {spell:8071} a tvůj {item:5175}",
	["{quest:1516} (Horde)"] = "{quest:1516} (Horda)",
}
t.guides["forever/class/shaman/call-of-fire-alliance"] = {
	["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "Na 10 tě {npc:258113}, trenér šamanů v {area:131}, nebo {npc:258098}, trenér šamanů v {zone:1455}, pošle k {npc:257597}.",
	["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Zpět tunelem South Gate a po stezce nahoru do jeskyně {npc:257597}. {item:5176} si nech v taškách natrvalo: potřebuje ho každý ohnivý totem.",
	["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "Zpět nahoru po stezce k {npc:257808}. Z dehtu a váčku vyrobí {item:6636}: nech si ho s pochodní.",
	["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "S pochodní v taškách klikni na {object:61934} na vrcholu svatyně a polož uhlík, pak klikni znovu pro další quest: zapálenou {item:277329}.",
	["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "Vyšplhej kolem {npc:257808} až na vrchol. Vypij {item:6636} u kamenné sochy, ať uvidíš {npc:5893} (level 12): čeká, dokud neudeříš, ale čím déle ho necháš, tím je silnější, a na oheň je imunní. Začni hned {spell:8017} a {spell:8042}. Jeho {item:6655} padá pokaždé.",
	["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "Jdi po silnici na východ k tunelu směrem k {area:806}. Za prvním tunelem drž se vlevo kolem {npc:1959} a věže: úzká stezka, špatně viditelná, ale ukázaná na minimapě, se vine do hory k jeskyni {npc:257597} nad farmou. Dá ti {item:6653}: nech si ho až do konce série.",
	["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "Z římsy {npc:257597} můžeš opatrně seskákat z hory dolů do {zone:1432}, nebo se vrať tunelem. {npc:257808} hlídá svatyni na vrcholu kousek jižně od {area:144}: skrytá stezka po skalní římse, značená kamennými totemy, k ní stoupá ze silnice severně od vrcholu.",
	["Lost the {quest:94473}?"] = "Ztratil jsi {quest:94473}?",
	["The {object:61934}"] = "{object:61934}",
	["{npc:257808}: a new {quest:94473}"] = "{npc:257808}: nový {quest:94473}",
	["{quest:94449} (Alliance)"] = "{quest:94449} (Aliance)",
}
t.guides["forever/class/shaman/call-of-fire-horde"] = {
	["At 10 {npc:252382}, the shaman trainer beside {npc:251968} in {area:16638}, hands you the {item:6653} ({npc:254082} offers the same quest). Already left the isle? A {quest:97243} sends you back to them: take the skycutter from the cliffs south of {area:17045}, north of {zone:1456}. Learn {spell:8050} from her now: {npc:268605}, later in the chain, only takes fire damage."] = "Na 10 ti {npc:252382}, trenérka šamanů vedle {npc:251968} v {area:16638}, dá {item:6653} (stejný quest nabízí {npc:254082}). Už jsi opustil ostrov? {quest:97243} tě k nim pošle zpět: vezmi skycutter z útesů jižně od {area:17045}, severně od {zone:1456}. Nauč se teď od ní {spell:8050}: {npc:268605}, později v řetězu, bere jen fire poškození.",
	["At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm."] = "Na 10 tě {npc:3066}, trenér šamanů v {area:222}, pošle k {npc:5907} v {zone:1413}. Už neseš dopis od {npc:5906} z {zone:1456}? Jde taky k {npc:5907}: Narma přeskoč.",
	["At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}."] = "Na 10 tě {npc:3173}, trenér šamanů na východní straně {area:362}, pošle k {npc:5907} v {zone:1413}. Už neseš dopis od {npc:5892} z {zone:1454}? Jde taky k {npc:5907}: {npc:3173} přeskoč.",
	["Back east over the bridge, then south along the {zone:1411} bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. {npc:5900} keeps the shrine at the top."] = "Zpět na východ přes most, pak na jih po břehu řeky v {zone:1411} tam, kde se hory setkávají s vodou. Stezka nahoru začíná u paty hory vedle malého tmavého kamene s vytesanými symboly, blízko tábora quilboarů; je úzká a uklouznutí stojí poškození pádem. Svatyni nahoře drží {npc:5900}.",
	["Back to {npc:268592} at the Shrine of Flames."] = "Zpět k {npc:268592} do Shrine of Flames.",
	["Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}."] = "Zpět k {npc:268592}. Přijmi poslední quest a čekej u {npc:268762}, zatímco provádí rituál; až ohniví duchové zapálí {object:148418}, přilož k němu pochodeň. Od té chvíle máš šest minut: nes plamen rovnou k {npc:268679} vedle {npc:252382} v {area:16638}, bez odboček a bojů. Čas vypršel? Quest zruš a vezmi znovu od {npc:268592}.",
	["Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both."] = "Zpět nahoru po stezce k {npc:5900}. Z dehtu a váčku vyrobí {quest:1464} a dá ti ho s pochodní: nech si obojí.",
	["Click the {object:61934} on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit {item:277329}."] = "S pochodní v taškách klikni na {object:61934} na plošině a polož uhlík, pak klikni podruhé: další quest se neotevře sám. Dá ti zapálenou {item:277329}.",
	["Down the trail, back over the bridge to {npc:5907} by his tower. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Dolů po stezce, zpět přes most k {npc:5907} u jeho věže. {item:5176} si nech v taškách natrvalo: potřebuje ho každý ohnivý totem.",
	["Drink the {item:6636} beside the {object:63674}, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with {spell:8017} and {spell:8042} and leave the others alone. Its {item:6655} drops every time."] = "Vypij {item:6636} vedle {object:63674}, velkého šedého kamene kousek pod vrcholem, pak vyšplhej na plošinu. Z ohnivých elementálů tam jde napadnout jen ten uprostřed: má level 12, je imunní vůči ohni a čím déle boj trvá, tím je silnější, tak začni hned {spell:8017} a {spell:8042} a ostatní nech být. Jeho {item:6655} padá pokaždé.",
	["Lost the {quest:1464}?"] = "Ztratil jsi {quest:1464}?",
	["The Burning Blade Cultists (level 10-11, they call imps and cast {spell:348}) live deep in {area:371} north of {area:362}: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. {area:817} by {zone:1454} is the wrong cave."] = "Burning Blade Cultists (level 10–11, vyvolávají impy a sesílají {spell:348}) žijí hluboko v {area:371} severně od {area:362}: vyjdi po rampě kousek severovýchodně od města a drž se na vyvýšeném terénu nad roklemi. Orkové u ústí jeskyně nejsou kultisté; kultisté jsou dál uvnitř, vlevo. Tři zabití ze čtyř dropnou váček. {area:817} u {zone:1454} je špatná jeskyně.",
	["The {npc:5893}"] = "{npc:5893}",
	["The {object:148418}"] = "{object:148418}",
	["The {object:61934}"] = "{object:61934}",
	["{npc:268602} (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past {area:16638}, just south of the {area:16629}, on the hill west of the falls north of the {area:17675}. Kill him and take his heart."] = "{npc:268602} (level 10, zrádný Windshaper s jediným spawnem) drží farmu severovýchodně za {area:16638}, kousek jižně od {area:16629}, na kopci západně od vodopádů severně od {area:17675}. Zabij ho a vezmi mu srdce.",
	["{npc:5900}: a new {quest:1464}"] = "{npc:5900}: nový {quest:1464}",
	["{npc:5907}: {npc:3066}'s letter"] = "{npc:5907}: dopis od {npc:3066}",
	["{npc:5907}: {npc:3173}'s letter"] = "{npc:5907}: dopis od {npc:3173}",
	["{npc:5907}: {npc:5892}'s letter"] = "{npc:5907}: dopis od {npc:5892}",
	["{npc:5907}: {npc:5906}'s letter"] = "{npc:5907}: dopis od {npc:5906}",
	["{object:660848} is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of {area:16638}, in the hills south of the Windsong Crawlers' lakes. Knock on it to call {npc:268605} (level 10). The spirit shrugs off most magic: only fire hurts it, so keep {spell:8050} on it. Take its wooden mask."] = "{object:660848} je pokroucený pahýl na vrcholu kopce u Shen'dar Highlands Anchor Pylon, západně od {area:16638}, v kopcích jižně od jezer Windsong Crawlerů. Zaklepej na něj a přivoláš {npc:268605} (level 10). Duch odolává většině magie: ubližuje mu jen oheň, tak na něm drž {spell:8050}. Vezmi jeho dřevěnou masku.",
	["{object:660848}: knock on the bark"] = "{object:660848}: zaklepej na kůru",
	["{quest:1522} (Horde)"] = "{quest:1522} (Horda)",
}
t.guides["forever/class/shaman/call-of-water-alliance"] = {
	["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "Na 20 tě {npc:258098}, trenér šamanů v {object:32362} v {zone:1455}, pošle k {npc:258043} v {zone:1432}.",
	["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "Zpět k {npc:258043} u {area:146} s {item:7810}. Dá ti {item:6637} a {item:7811}: nech si obojí pro {zone:1436}.",
	["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Zpět k {npc:258043} s {item:7813}. {item:5177} si nech v taškách natrvalo: potřebuje ho každý vodní totem.",
	["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Naplň {item:265732} na úpatí vodopádů pod jeskyní {npc:258203}, kde se sladká voda mísí s brakickou. U vodopádů se potulují trpaslíci {object:147516}.",
	["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "Leť do {area:108} a zamiř na jih k {area:20}: {area:919} a {object:619896} leží kousek severně od něj. Vypij {item:6637} u svatyně, abys uviděl {npc:5894} (level 22, {spell:8056} a {spell:122}; jeden spawn, zpátky tři minuty po zabití), poraz ho kvůli náramkům (dropnou vždycky), pak je spolu s {item:7811} polož na {object:619896} (quest ukončí tohle, ne {npc:258043}). Klikni na svatyni znovu: vedle ní se vynoří {npc:5895}; promluv s ním, než odejdeš (pokud zmizel, quest zahoď a vezmi znovu u svatyně). Dá ti {item:7813}.",
	["Lost the {quest:94616}?"] = "Ztratil jsi {quest:94616}?",
	["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "Vezmi loď z {area:150} do {area:442} (cestou staví v {area:271}), pak leť nebo jdi na jih přes {zone:1439} do {area:415} v {zone:1440}. Naplň {item:265772} v jezeře kolem města, pak lodí zpátky do Menethilu.",
	["The red waterskin"] = "Červený měch na vodu",
	["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "{area:71} se valí z {area:68} na východním konci Redridge (leť z {zone:1455} do {area:69}). Naplň {item:265747} u jejich paty, kde se shromažďují Murloc Nightcrawlers; nejdřív z místa odtáhni murloky. Když měch zmizí, aniž se započítá, zruš quest a vezmi ho znovu od {npc:258203} kvůli novému.",
	["{npc:258043}: a new {quest:94616}"] = "{npc:258043}: nový {quest:94616}",
	["{npc:258043}: {spell:5394} and your {item:5177}"] = "{npc:258043}: {spell:5394} a tvůj {item:5177}",
	["{quest:94494} (Alliance)"] = "{quest:94494} (Aliance)",
}
t.guides["forever/class/shaman/call-of-water-horde"] = {
	["At 20 {npc:5892} in the {object:172957} sends you to {npc:5901} in the {zone:1413}. (Swart in {area:362} gives the same letter: carry either.)"] = "Na 20 tě {npc:5892} v {object:172957} pošle k {npc:5901} v {zone:1413}. (Swart v {area:362} dá stejný dopis: nos kterýkoli.)",
	["At 20 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5901} in the {zone:1413}. ({npc:3066} in {area:222} gives the same letter: carry either.)"] = "Na 20 tě {npc:5906}, trenér šamanů na {area:1640} v {zone:1456}, pošle k {npc:5901} v {zone:1413}. ({npc:3066} v {area:222} dá stejný dopis: nos kterýkoli.)",
	["Back to {npc:5899}. She gives you the {item:7810} for {npc:5901}."] = "Zpět k {npc:5899}. Dá ti {item:7810} pro {npc:5901}.",
	["Back to {npc:5901} south of {area:392}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Zpět k {npc:5901} jižně od {area:392}. {item:5177} si nech v taškách natrvalo: potřebuje ho každý vodní totem.",
	["Click the {object:113791} to place the bracers and the drops. A few seconds later the pure {npc:5895} rises on the stone in the middle of the pool: speak to it while the {spell:8202} lasts (drink again by the stone if it has worn off). It gives you the {item:7813} for {npc:5901}. Gone before you could speak to it? Back at {npc:5901} ask for {quest:63} (a fresh {quest:972} for {npc:7007}, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it."] = "Klikni na {object:113791} a polož náramky a kapky. Za pár sekund se na kameni uprostřed tůně zvedne čistý {npc:5895}: promluv s ním, dokud trvá {spell:8202} (pokud vyprchalo, napij se znovu u kamene). Dá ti {item:7813} pro {npc:5901}. Zmizel dřív, než jsi s ním promluvil? Zpět u {npc:5901} požádej o {quest:63} (nový {quest:972} pro {npc:7007}, který stojí kousek západně od svatyně): předej ho Tievovi, zůstaň blízko, zatímco ducha přivolá zpět, a pak s ním promluv.",
	["Fly to the {area:228}. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the {item:6637} beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The {npc:5894} is level 22 and casts {spell:8056} and {spell:122}; if someone just killed it, it is back in about three minutes. Its bracers always drop."] = "Leť do {area:228}. Svatyně leží v prohlubni kousek jihozápadně od něj: obejdi kryptu zezadu k tlustému stromu mezi dvěma kopci, přeskoč kolem něj na skály a sjeď na západ dolů ze svahu k jezírku (každý seskok stojí trochu zdraví). Vypij {item:6637} u vysokého menhiru u jezírka: objeví se několik vodních elementálů a napadnout jde jen ten zkažený blízko středu (vybere ho Tab). {npc:5894} má level 22 a sesílá {spell:8056} a {spell:122}; pokud ho někdo právě zabil, je zpátky asi za tři minuty. Jeho náramky dropnou vždycky.",
	["Lost the {quest:972}?"] = "Ztratil jsi {quest:972}?",
	["The muddy pond below {npc:5899}'s hut. Step right into the puddle before you use the {item:7766} (too far away and it refuses). Filling it calls a hostile {npc:3456} (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards."] = "Bahnitý rybník pod chýší {npc:5899}. Než použiješ {item:7766}, vstup přímo do louže (z velké dálky to nejde). Naplnění přivolá nepřátelského {npc:3456} (level 20): zabij ho a dej pozor na quilboarího lovce u rybníka, který pak může začít střílet.",
	["The right fountain stands in a ring of standing stones on the island of the small green lake south of {area:415}, west of Lake Mystral (not the island in Lake Mystral itself). From the {zone:1413} take the road north through the {area:1703} and on west. Water elementals and walking treants guard the lake and root you in place; an elite {npc:12836} roams {zone:1440} and can pass close by. Use the {item:7767} beside the fountain."] = "Ta správná fontána stojí v kruhu menhirů na ostrově malého zeleného jezera jižně od {area:415}, západně od Lake Mystral (ne na ostrově v samotném Lake Mystral). Z {zone:1413} jdi po silnici na sever přes {area:1703} a dál na západ. Jezero hlídají vodní elementálové a chodící treanti, kteří tě přikovají na místo; {zone:1440} se potuluje elite {npc:12836} a může projít blízko. Použij {item:7767} vedle fontány.",
	["The {npc:5895}"] = "{npc:5895}",
	["The {object:107045}"] = "{object:107045}",
	["The {object:107046}"] = "{object:107046}",
	["The {object:113791}"] = "{object:113791}",
	["{npc:5901}: a new {quest:972}"] = "{npc:5901}: nový {quest:972}",
	["{npc:5901}: {npc:5892}'s letter"] = "{npc:5901}: dopis od {npc:5892}",
	["{npc:5901}: {spell:5394} and your {item:5177}"] = "{npc:5901}: {spell:5394} a tvůj {item:5177}",
	["{quest:63} (Horde)"] = "{quest:63} (Horda)",
}
t.guides["forever/class/shaman/darkreaver"] = {
	["200 Horde reputation"] = "200 reputace u Hordy",
	["A five-player dungeon event: {area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. In the {object:179746}'s basement, first clear every mob in the room, then use the {item:18746} at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then {npc:14516} (level 62 elite) appears: he Cleaves, casts {spell:686} and {spell:6958}, and Dominates a player's mind against the group. His head always drops."] = "Dungeonová událost pro pět hráčů: {area:2057} leží pod {area:2298}, ostrovním městem na jihovýchodě {zone:1422}. Ve sklepě {object:179746} nejdřív vybij všechny moby v místnosti, pak uprostřed použij {item:18746}: následují čtyři vlny duchů, každou uzavře mini-boss Aspect (první vlna slabá a pomalá, ostatní elitní). Bojuj v rohu, aby se nic dalšího nepřidalo, a mezi vlnami pij: je to dlouhé. Pak se objeví {npc:14516} (level 62 elite): Cleavuje, sesílá {spell:686} a {spell:6958} a ovládne mysl hráče proti skupině. Jeho hlava padá vždy.",
	["A {area:2057} fight at 60 for Horde reputation; the {item:20134} may be gone in Forever."] = "Souboj v {area:2057} na 60 kvůli reputaci u Hordy; {item:20134} ve Foreveru možná není.",
	["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds."] = "Na 58 chce {npc:13417}, trenér šamanů v {object:172957}, dva vzácné diamanty; chodí k němu každý šaman Hordy. Skyborne: stránka questu ve Foreveru ho uvádí jen pro Orky, Taureny a Trolly: zeptej se, než diamanty koupíš.",
	["Both diamonds are rare: the auction house is the quick way. Miners find the {item:12800} in about one Thorium vein in a hundred (the Small Thorium Veins north of {area:2418} in the {zone:1428} respawn every five minutes). The {item:18335} drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine)."] = "Oba diamanty jsou vzácné: rychlá cesta je aukce. Horníci najdou {item:12800} zhruba v jedné Thorium žíle ze sta (Small Thorium Veins severně od {area:2418} v {zone:1428} se obnovují každých pět minut). {item:18335} padá z vysokolevelových elit zhruba jeden ze sta, nejlépe ze vzácné elity Revanchion (zhruba jeden z devíti).",
	["Two diamonds"] = "Dva diamanty",
	["{npc:13417}: 200 Horde reputation; the {item:20134} may be gone"] = "{npc:13417}: 200 reputace u Hordy; {item:20134} možná zmizel",
	["{quest:8258} needs level 60."] = "{quest:8258} vyžaduje level 60.",
}
t.guides["forever/class/shaman/spirit-totem"] = {
	["A five-player dungeon: needs a group of five, about level 50-55. Fly to {area:75} and ride east. The {area:1417} ({area:1477}) stands in the middle of the {area:74}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others ({spell:139}, a {npc:3560}): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys."] = "Dungeon pro pět hráčů: potřebuje skupinu pěti, asi level 50–55. Leť do {area:75} a jeď na východ. {area:1417} ({area:1477}) stojí uprostřed {area:74}: vyjdi po schodech na jižní straně ruiny, skoč do zatopené síně, proplav dolů a sleduj schody a chodby dolů k portálu. Dvě pera od každé barvy, po jednom od každého ze šesti elitních trollích mini-bossů (level 51–52) na balkonech kolem velké kruhové síně chrámu, při každém zabití, a každý hráč na questu lootuje svoje: Gasher a {npc:5716} Amber, Hukku a Mijan Blue, Zolo a Loro Green. Mijan léčí ostatní ({spell:139}, {npc:3560}): zabij ho první; Hukku vyvolává strážce a hází Shadow Bolt Volley.",
	["At 50 {npc:13417}, the shaman trainer in the {object:172957}, asks for the four elements for {npc:6176}."] = "Na 50 chce {npc:13417}, trenér šamanů v {object:172957}, čtyři živly pro {npc:6176}.",
	["At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away."] = "Na 50 chce {npc:3032}, trenér šamanů na {area:1640} v {zone:1456}, čtyři živly pro {npc:6176}. Skyborne: stránka questu ve Foreveru uvádí {quest:8410} a {quest:8412} jen pro Orky, Taureny a Trolly; pokud pro tebe {npc:3032} nic nemá, vlastní {quest:8411} od {npc:6176} je otevřený každé rase Hordy, ale {quest:8412} po něm tě pořád může odmítnout.",
	["Eight of each. Fly or ride to the {area:813} and on to the west edge of the {zone:1422}, north-west of {area:3197}: the Venom Mist Lurkers (level 50-51, they poison) give the {item:20610} and the Diseased Black Bears (level 51-52, {spell:3427}) the {item:20611}, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of {area:159} in Tirisfal."] = "Osm od každého. Leť nebo jeď do {area:813} a dál na západní okraj {zone:1422}, severozápadně od {area:3197}: Venom Mist Lurkers (level 50–51, otravují) dají {item:20610} a Diseased Black Bears (level 51–52, {spell:3427}) {item:20611}, každý zhruba jedno zabití z pěti; dva Carrion Vultures tam dropují obojí. Větší Diseased Grizzlies a Plague Lurkers dál na východ je skoro nedropují. Pár medvědů a lurkerů se toulá i jihovýchodně od {area:159} v Tirisfalu.",
	["Experience and gold"] = "Zkušenosti a zlato",
	["Experience and gold at 50, ending in the {area:1417}; the Classic item choice may be gone in Forever."] = "Zkušenosti a zlato na 50, končí v {area:1417}; výběr předmětu z Classicu ve Foreveru možná chybí.",
	["Spider eye and bear claw"] = "Pavoučí oko a medvědí dráp",
	["The four elements"] = "Čtyři živly",
	["The {area:1417}"] = "{area:1417}",
	["{quest:8412} and {quest:8413}"] = "{quest:8412} a {quest:8413}",
}
t.guides["forever/class/warlock/dread-mage-hat"] = {
	["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Látková čepice ve tvých pozdních dvacítkách: Zardethova pochůzka pro kteréhokoli hráče Aliance za ni warlockům platí navíc.",
	["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "Na 25 chce {npc:1435}, ve sklepě {object:2164} v {object:2101} (vedle trenérů warlocků), dvě přísady do lektvaru. Udělej to, až tě levelování zavede do {zone:1431} a {zone:1437}.",
	["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "Ještě jednou zpět k Zardethovi: warlockům nabídne odměnu, kterou předá jeho imp {npc:1733} stojící vedle něj.",
	["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "Zpět k Zardethovi. Uvaří {item:2788} a dá ti ho pro {npc:1439} v Hall of Petitioners, první síni vpravo v {object:2117}.",
	["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "Kořen roste na kraji vody v jezírku pod malými vodopády východně od {area:836}, vedle jeskyně {object:147516} pod {area:146}: vysoký, ostnatý dřevěný kořen, ne přímo u paty přehrady.",
}
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = {
	["A rare cloth robe for your 30s from {npc:6266}; its last parts wait for levels 37 and 39."] = "Vzácné látkové roucho pro tvoje třicítky od {npc:6266}; jeho poslední části čekají na levely 37 a 39.",
	["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Na 31 tě {npc:3326} v {object:172960} pošle k {npc:6266} v {area:392}. Nejdřív kup {item:5770} a {item:3577} (další kroky), ušetříš cestu.",
	["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}; the zeppelin from {zone:1420} flies to {zone:1411}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Na 31 tě {npc:4563} v {object:36082} pošle k {npc:6266} v {area:392}; zeppelin z {zone:1420} letí do {zone:1411}. Nejdřív kup {item:5770} a {item:3577} (další kroky), ušetříš cestu.",
	["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Na 31 tě {npc:461} v {object:2164}, v {object:2101}, pošle k {npc:6266} v {area:392}. Nejdřív kup {item:5770} a {item:3577} (další kroky), ušetříš cestu.",
	["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Na 31 tě {npc:5172} v {zone:1455} pošle k {npc:6266} v {area:392}. Nejdřív kup {item:5770} a {item:3577} (další kroky), ušetříš cestu.",
	["Back to {npc:2670} in {area:35}: he offers {quest:4785} as a quest you hand straight back to him. He may show no quest marker; talk to him anyway."] = "Zpět k {npc:2670} do {area:35}: nabídne {quest:4785} jako quest, který mu hned vrátíš. Nemusí mít značku questu; promluv s ním i tak.",
	["Back to {npc:6266}"] = "Zpět do {npc:6266}",
	["Back to {npc:6266} with the thread, the coals and a {item:6265}. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again."] = "Zpět k {npc:6266} s nití, uhlíky a {item:6265}. Pak čekej vedle ní, zatímco pracuje na rouchu (neútoč na ni: deník questů tomu říká zabití), a znovu s ní promluv.",
	["Hatefury satyrs"] = "Satyrové Hatefury",
	["Tailors sew the {item:5770} from a rare pattern; miners smelt Gold Bars from {item:2776}. Everyone else buys both at the Auction House. If you wear the robe, take it off: {npc:6266} keeps it."] = "Krejčí ušijí {item:5770} z rare střihu; horníci taví Gold Bars z {item:2776}. Všichni ostatní obojí koupí v aukci. Jestli róbu nosíš, sundej ji: {npc:6266} si ji nechá.",
	["The Burning Exiles (level 38-39), fire elementals at the {area:334} in western {zone:1417}, drop the coal about one time in three. The guide waits for level 39 first: below it they hit too hard to solo. They resist fire: {spell:686} and Corruption. The Cresting Charms from the Cresting Exiles near {area:321} finish one off once you have hurt it. Make a {item:6265} with {spell:1120} on the way."] = "Burning Exiles (level 38–39), ohniví elementálové u {area:334} v západní {zone:1417}, dropují uhlí asi jednou ze tří. Návod nejdřív čeká na level 39: pod ním bijí moc silně na sólo. Odolávají ohni: {spell:686} a Corruption. Cresting Charms od Cresting Exiles u {area:321} jednoho dodělají, jakmile ho zraníš. Cestou si vyrob {item:6265} pomocí {spell:1120}.",
	["The Hatefury satyrs (level 31-32) hold {area:603} in the far north-east of {zone:1443}, past {area:608}: two kills in five give a vial, so plan on about 25."] = "Satyrové Hatefury (level 31–32) drží {area:603} na dalekém severovýchodě {zone:1443}, za {area:608}: dvě zabití z pěti dají lahvičku, takže počítej asi s 25.",
	["Vials of Hatefury Blood"] = "Vials of Hatefury Blood",
	["Wait beside {npc:6266} while she finishes the robe"] = "Počkej vedle {npc:6266}, než dodělá róbu",
	["{item:3577}: the Auction House"] = "{item:3577}: aukce",
	["{item:5770}: the Auction House"] = "{item:5770}: aukce",
	["{npc:2670}: {quest:4785}, handed straight back"] = "{npc:2670}: {quest:4785}, rovnou odevzdej zpátky",
	["{npc:6266} again"] = "{npc:6266} znovu",
}
t.guides["forever/class/warlock/felhunter-alliance"] = {
	["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "Na 30 tě {npc:6120} v {object:32383} pošle k {npc:6251} v {area:392}.",
	["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "Na 30 tě {npc:6122}, ve sklepě {object:2164} v {object:2101}, pošle k {npc:6251} v {area:392}.",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Zpět k {npc:6251} do {area:392}. Když přijmeš, nakreslí vyvolávací kruh a jeho akolyté nad ním kanálují větší kruh: počkej ve věži, dokud nejsou oba hotové. Pak použij {quest:1804} na kruh. Felhunter (level 30, ne elitní) umlčuje a žere manu a po dvou minutách zmizí: měj venku voidwalkera, hned začni DoTy a nech voidwalkera tankovat. Když zemřeš nebo vyhraje, zruš {quest:1795} a vezmi ho znovu od {npc:6251}. Knihu si nech: {npc:6251} si ji vezme zpět.",
	["Back to {npc:6294}"] = "Zpět do {npc:6294}",
	["Felhunter (Alliance)"] = "Felhunter (Aliance)",
	["The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Dragonmaw drží {area:1036} v kopcích východně od cesty z {area:150} do {area:836}. Tyče dropují jen casteři, čtyři zabití z pěti: Bonewarders (level 27, s kostlivými pety) a Shadowwarders (28). Strmá stezka severně od centrálního spirit healera vede nahoru do tábora kolem většiny válečníků.",
	["The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "Jeskyně kentaurů se otevírá ve skalách severně od {area:484}, hordího města: vyhni se jeho strážím. Uvnitř se na každé odbočce drž vpravo, přejdi jezírko u malého vodopádu a otevři malou tmavou bednu u stěny vedle větší truhly: ta větší je špatně. Otevřít ji jde jen s questem. Kentauři se za tebou cestou ven respawnou.",
	["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "Felhunter, démon proti sesilatelům kouzel, a {item:22244} na tvoje shardy.",
	["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "Kniha je malá šedomodrá knížka, která leží v písku murločího tábora na břehu jihozápadně od {area:271}, blízko kraje vody. Hlídá ji šest nebo sedm murloků a další číhají pod vodou: chodí ve skupinách, takže jednoho Fearni a voidwalkera nech na zbytku. Sejdi k vodě a klikni na ni; ze svahu kurzor blokují bedny.",
	["{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}."] = "{area:392} je neutrální goblinský přístav na pobřeží {zone:1413}: kotví tam loď z {area:35}. {npc:6251} stojí na kopci nad městem, za chýší inženýrů, u své malé věže; jsou s ním {npc:6266} a dva akolyté. Pošle tě za {npc:6294} do {zone:1455}.",
	["{item:6997}, in the {object:92423}"] = "{item:6997}, v {object:92423}",
	["{quest:1804}, on the circle"] = "{quest:1804}, na kruhu",
}
t.guides["forever/class/warlock/felhunter-horde"] = {
	["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:3001}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "Na 30 tě {npc:5675} v {object:36082} pošle k {npc:6251} v {area:392}. Zeppelin z {zone:1420} letí do {zone:1411}. Vezmi jen jeden {quest:3001}: když ti {npc:6251} nic nenabídne, duplikát z deníku zruš.",
	["At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}."] = "Na 30 tě {npc:5875}, v {object:172960} pod {object:172982}, pošle k {npc:6251} v {area:392}.",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Zpět k {npc:6251} do {area:392}. Když přijmeš, nakreslí vyvolávací kruh a jeho akolyté nad ním kanálují větší kruh: počkej ve věži, dokud nejsou oba hotové. Pak použij {quest:1804} na kruh. Felhunter (level 30, ne elitní) umlčuje a žere manu a po dvou minutách zmizí: měj venku voidwalkera, hned začni DoTy a nech voidwalkera tankovat. Když zemřeš nebo vyhraje, zruš {quest:1795} a vezmi ho znovu od {npc:6251}. Knihu si nech: {npc:6251} si ji vezme zpět.",
	["Back to {npc:6293}"] = "Zpět do {npc:6293}",
	["Felhunter (Horde)"] = "Felhunter (Horda)",
	["The Dragonmaw hold {area:1036} in the hills east of the road through the {zone:1437}, south of the {area:881} you cross from {zone:1417}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Dragonmaw drží {area:1036} v kopcích východně od cesty přes {zone:1437}, jižně od {area:881}, který přejdeš z {zone:1417}. Tyče dropují jen casteři, čtyři zabití z pěti: Bonewarders (level 27, s kostlivými pety) a Shadowwarders (28). Strmá stezka severně od centrálního spirit healera vede nahoru do tábora kolem většiny válečníků.",
	["The centaur cave opens in the cliffs north of {area:484}. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "Jeskyně kentaurů se otevírá ve skalách severně od {area:484}. Uvnitř se na každé odbočce drž vpravo, přejdi jezírko u malého vodopádu a otevři malou tmavou bednu u stěny vedle větší truhly: ta větší je špatně. Otevřít ji jde jen s questem. Kentauři se za tebou cestou ven respawnou.",
	["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "Felhunter, démon proti sesilatelům kouzel, a {item:22244} na tvoje shardy.",
	["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "Kniha je malá šedomodrá knížka, která leží v písku murločího tábora na břehu jihozápadně od {area:271}, blízko kraje vody. Hlídá ji šest nebo sedm murloků a další číhají pod vodou: chodí ve skupinách, takže jednoho Fearni a voidwalkera nech na zbytku. Sejdi k vodě a klikni na ni; ze svahu kurzor blokují bedny.",
	["{area:392}'s flight point is a short flight from {zone:1454}'s. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6293} in the {zone:1458}."] = "Letový bod {area:392} je kousek letu od letového bodu {zone:1454}. {npc:6251} stojí na kopci nad městem, za chýší inženýrů, u své malé věže; jsou s ním {npc:6266} a dva akolyté. Pošle tě za {npc:6293} do {zone:1458}.",
	["{item:6997}, in the {object:92423}"] = "{item:6997}, v {object:92423}",
	["{quest:1804}, on the circle"] = "{quest:1804}, na kruhu",
}
t.guides["forever/class/warlock/imp-alliance"] = {
	["Feather Charms"] = "Feather Charms",
	["Imp (Alliance)"] = "Imp (Aliance)",
	["The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it."] = "Stan Defias stojí na vinici východně od Abbey. Kniha je malá: leží na zemi kousek vpravo od vchodu do stanu, vedle modrého džbánu. Stan hlídají tři Defias Thugs (level 3–4); taháš je po jednom, nebo vejdi do stanu a klikni na knihu, kam na tebe nedosáhnou. Kniha se respawne tři minuty poté, co ji někdo vezme.",
	["The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}."] = "Frostmane Novices (level 3–4) sedí vzadu v trollí jeskyni jižně od {area:77}, poblíž Grek'nira the Cold u ledové tůně: za vchodem jdi levým tunelem. Čtyři zabití z pěti dropnou amulet, ale spawnou jen dva nebo tři novicové, takže možná budeš čekat na jejich tříminutový respawn. Hází frostbolty z dálky; Troll Whelps u ústí jeskyně skočí na každého, kdo jde kolem. S amulety tě Hearthstone vezme rovnou zpátky: nová postava ho má nastavený do {area:132}.",
	["The {object:83763}"] = "{object:83763}",
	["{item:6785}, from the {object:83763}"] = "{item:6785}, od {object:83763}",
	["{npc:459} (Humans)"] = "{npc:459} (lidé)",
	["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:459} tě při odevzdání naučí {spell:688}: hned ho vyvolej, nic to nestojí a bojuje po tvém boku.",
	["{npc:460} (Gnomes)"] = "{npc:460} (gnómové)",
	["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:460} tě při odevzdání naučí {spell:688}: hned ho vyvolej, nic to nestojí a bojuje po tvém boku.",
}
t.guides["forever/class/warlock/imp-horde"] = {
	["Imp (Horde)"] = "Imp (Horda)",
	["Rattlecage Skulls"] = "Rattlecage Skulls",
	["Vile Familiar Heads"] = "Vile Familiar Heads",
}
t.guides["forever/class/warlock/impsys-request"] = {
	["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "Hůl, předmět do druhé ruky nebo roucho pro tvoje padesátky; vlastní pochůzka {npc:14470}, ne krok řetězu Dreadsteed.",
	["Amber Voodoo Feathers: Gasher, {npc:5716}"] = "Amber Voodoo Feathers: Gasher, {npc:5716}",
	["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Na 50 tě {npc:3326} v {object:172960} pošle k {npc:14470} v {zone:1448} s kusem {item:14256}.",
	["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Na 50 tě {npc:4563} v {object:36082} pošle k {npc:14470} v {zone:1448} s kusem {item:14256}.",
	["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Na 50 tě {npc:461} v {object:2164}, v {object:2101}, pošle k {npc:14470} v {zone:1448} s kusem {item:14256}.",
	["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Na 50 tě {npc:5172} v {zone:1455} pošle k {npc:14470} v {zone:1448} s kusem {item:14256}.",
	["Blue Voodoo Feathers: Hukku, Mijan"] = "Blue Voodoo Feathers: Hukku, Mijan",
	["Choose the {item:20536} (staff), the {item:20534} (off-hand) or the {item:20530}."] = "Vyber {item:20536} (hůl), {item:20534} (do druhé ruky) nebo {item:20530}.",
	["Green Voodoo Feathers: Zolo, Loro"] = "Green Voodoo Feathers: Zolo, Loro",
	["The {area:1417}"] = "{area:1417}",
	["{npc:14470} again"] = "{npc:14470} znovu",
	["{npc:14470} now wants six {item:20609} from the {area:1417}: a dungeon run."] = "{npc:14470} teď chce šest {item:20609} z {area:1417}: průchod dungeonem.",
	["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's {quest:8419} with the cloth. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} čeká vedle {npc:14469} na vyvýšenině kousek severovýchodně od {area:1997}: když jdeš na sever přes most {area:1765}, stojí mimo cestu na východě, za několika slizy. Odevzdej mu {quest:8419} od trenéra i s látkou. Dál chce deset {item:20613} a čtyři {item:20614}.",
	["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Take his own {quest:8420} and hand him the cloth at once. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} čeká vedle {npc:14469} na vyvýšenině kousek severovýchodně od {area:1997}: když jdeš na sever přes most {area:1765}, stojí mimo cestu na východě, za několika slizy. Vezmi si jeho vlastní {quest:8420} a hned mu odevzdej látku. Dál chce deset {item:20613} a čtyři {item:20614}.",
}
t.guides["forever/class/warlock/incubus-alliance"] = {
	["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "Na 20 tě {npc:6120}, trenér warlocků v {object:32383} v {zone:1455}, pošle k {npc:6122} v {zone:1453}. Vezmi {area:2257}.",
	["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "Na 20 tě {npc:6122}, ve sklepě {object:2164} v {object:2101}, pošle k {npc:6244} v {zone:1413}: pro Alianci dlouhá cesta. Vezmi loď z {area:150} do Theramore a jdi na západ přes {zone:1445}, nebo loď z {area:35} do {area:392}.",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Na 20: succubus a incubus Foreveru, její mužské dvojče, každý s váčkem duší na tvoje shardy.",
	["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "Zpět k {npc:6122} s {quest:1738}. Dá ti {item:6913}: sejdi po schodech za ním dolů do krypty; zhruba v polovině nejnižší chodby vede vlevo boční schodiště do místnosti s fialovým kruhem. Stoupni si do něj a použij jádro. Nejdřív vyvolej voidwalkera a drž succubus (level 20, ne elitní) v kruhu, jinak ji můžou zabít stráže a zabití se nepočítá. Když vyhraje, použij jádro znovu; nech si ho, {npc:6122} si ho vezme zpět.",
	["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "Dej Gakinovi figurku, pak použij {item:190309} uprostřed téhož kruhu a poraz incuba, kterého přivolá (level 20, ne elite; umí tě očarovat), zatímco tankuje tvůj voidwalker. Figurku si nech: {npc:6122} si ji vezme zpět.",
	["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "Ordil'Aran leží na severozápadě {zone:1440}, severně od {area:415} u silnice směrem do {zone:1439}. Asi dvacet kultistů Dark Strand drží ruiny kolem velkého stromu: drž se vnější zdi a na {quest:1738} klikni z tak velké dálky, jak to jen jde. Odevzdává se u {npc:6122}, ne u Takara.",
	["Succubus and Incubus (Alliance)"] = "Succubus a Incubus (Aliance)",
	["The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs."] = "Dům stojí osamoceně mezi stromy na severozápadě {zone:1440}, severozápadně od Ordil'Aranu a hodně severně od {area:413}: udělej to na stejné cestě jako {quest:1738}. Vezmi {item:190307} ze stolu venku, zapal ji u ohně (vlastního {object:29784} nebo Talenova ohně na {area:414}) a vrať se rovnou zpátky: {item:190308} po pěti minutách dohoří, takže nejrychlejší je vlastní oheň vedle domu. Bez ní tě postava v domě zastaví. Soška je nahoře.",
	["The {item:190309}"] = "{item:190309}",
	["{item:190309}, upstairs"] = "{item:190309}, nahoře",
	["{quest:1717} (Gnomes)"] = "{quest:1717} (Gnómové)",
	["{quest:1739}: succubus"] = "{quest:1739}: succubus",
	["{quest:65603}: incubus"] = "{quest:65603}: incubus",
}
t.guides["forever/class/warlock/incubus-horde"] = {
	["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1507} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "Na 20 tě {npc:5875}, v {object:172960} pod {object:172982}, pošle k {npc:5909} pár kroků odsud. Tyhle démony začínají dva trenéři, {npc:5875} tady a {npc:5675} v {zone:1458}, a vzít můžeš jen jeden; tento návod sleduje ten {quest:1507}, který jsi vzal. {npc:5909} nabízí obě větve {zone:1454}: vezmi obě.",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Na 20: succubus a incubus Foreveru, její mužské dvojče, každý s váčkem duší na tvoje shardy.",
	["Back to {npc:5675} with Dalin's and Corma's hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "Zpět k {npc:5675} s Dalinovým a Cormaným srdcem. Dá ti {item:6286}: jdi dolů do vyvolávacího kruhu pod ním, stoupni si do něj a použij je. Nejdřív vyvolej voidwalkera a drž boj v kruhu, jinak ji můžou zabít stráže a zabití se nepočítá. Když vyhraje, použij srdce znovu; nech si je, {npc:5675} si je vezme zpět.",
	["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "Zpět k {npc:5675} se srdci milenců, pak polož {item:190181} do stejného kruhu a poraz incuba, kterého přivolají (level 20, ne elitní; může tě okouzlit). Srdce si nech: {npc:5675} si je vezme zpět.",
	["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "Zpět k {npc:5875} s přívěskem. Dá ti {item:6626}: přenes ho přes {object:172960} do stanu {npc:3216}, stoupni si do fialového kruhu a použij ho. Nejdřív vyvolej voidwalkera a nech ho tankovat: succubus (level 20, ne elitní) okouzluje a šlehá; drž na ní svoje DoTy. Když vyhraje, použij přívěsek znovu. Přívěsek si nech: {npc:5875} si ho vezme zpět.",
	["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "Zpět k {npc:5875} se šálou, pak použij {item:190232} ve stejném kruhu v Neeruově stanu a poraz incuba, kterého přivolá (level 20, ne elitní), s tankujícím voidwalkerem. Šálu si nech: {npc:5875} si ji vezme zpět.",
	["Corma Villard"] = "Corma Villard",
	["Corma Villard (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "Corma Villard (level 22, ne elitní; ve starších záznamech Comar) se toulá na severu {zone:1437} kousek za {area:881}, vpravo, když sejdeš z mostu. Z {zone:1458} jdi přes {area:287} a {zone:1417}, kde mají mobové 30 a víc. Útok na ni tě označí pro PvP.",
	["Succubus and Incubus (Horde)"] = "Succubus a Incubus (Horda)",
	["Take the road west from the Crossroads into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}."] = "Jdi po cestě na západ z Crossroads do {zone:1442} a hned za hranicí po slabé stezce nahoru doleva (na jih): na {area:2539} se z hlavní cesty nedostaneš. {npc:4197} ti dá svůj odvar pro {npc:5911}.",
	["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so the guide waits for level 27 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422} leží v jižní {zone:1440}, jihozápadně od {area:431}. Shadethicket Stone Movers a Bark Rippers (level 25–27) kolem jezera dropují {item:190232} zhruba jednou za dvacet a dropnout ho může i osamělý {npc:3931} (30): počítej s pořádným počtem zabití, proto návod nejdřív počká na level 27 (Forever z toho udělal quest na level 27); s už spoutanou sukubou to můžeš nechat na levelování ve dvacítkách v {zone:1440}. Respawnou se za pět minut.",
	["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363} vede {object:173018} na hlavní ulici východně od {object:172960}. Požádá tě, ať najdeš jeho družku Krilge v {zone:1440}.",
	["{npc:3464} waits in front of the inn at the Crossroads. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}."] = "{npc:3464} čeká před hostincem na Crossroads. Pošle tě dál k {npc:4197} do {area:2539} v {zone:1442}.",
	["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "Verze z {object:1661}, pro warlocky, kteří vzali {quest:1472} od {npc:5675} místo od {npc:5875}. Na levelu 20 tě {npc:5675} v {object:36082} pošle za {npc:5693} kousek odtud. {npc:5693} ti ukáže obraz každé kořisti a nabídne obě větve: vezmi obě.",
	["{quest:1474}: succubus ({zone:1458})"] = "{quest:1474}: succubus ({zone:1458})",
	["{quest:1513}: succubus ({zone:1454})"] = "{quest:1513}: succubus ({zone:1454})",
	["{quest:65597}: incubus ({zone:1458})"] = "{quest:65597}: incubus ({zone:1458})",
	["{quest:65604}: incubus ({zone:1454})"] = "{quest:65604}: incubus ({zone:1454})",
}
t.guides["forever/class/warlock/orb-of-orahil"] = {
	["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Koule do druhé ruky nebo hůl pro tvoje pozdní třicítky, cestou felhounda nebo infernala, podle tvé volby.",
	["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "Na 35 tě {npc:3326} v {object:172960} pošle k {npc:6266} v {area:392}.",
	["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "Na 35 tě {npc:4563} v {object:36082} pošle k {npc:6266} v {area:392}. Zeppelin z {zone:1420} letí do {zone:1411}.",
	["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "Na 35 tě {npc:461} v {object:2164}, v {object:2101}, pošle k {npc:6266} v {area:392}.",
	["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "Na 35 tě {npc:5172} v {zone:1455} pošle k {npc:6266} v {area:392}.",
	["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "Zpět k {npc:6266} do věže nad {area:392} s očištěnou koulí. Na cestě felhounda přijmi její poslední quest a čekej vedle ní, dokud nedokončí {item:15108} (neútoč na ni: deník questů tomu říká zabití), pak s ní znovu promluv a vyber kouli do druhé ruky nebo hůl.",
	["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "Nejdřív zpět k {npc:6266} do věže nad {area:392} s duchem a drahokamem: z nich následuje její koule.",
	["Choose an acolyte"] = "Vyber akolytu",
	["Orb of Orahil"] = "Orb of Orahil",
	["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, the shadow versions; {npc:6252}'s infernal path with the Orb or {item:15105}, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back."] = "Vyber si jednoho akolytu: vzít můžeš jen jeden z jejich questů. Felhoundí cesta u {npc:6254} končí Orbem nebo {item:15106}, shadow verzemi; infernalí cesta u {npc:6252} Orbem nebo {item:15105}, v podstatě stejnými itemy na straně ohně. Většina warlocků sází na shadow, ale nejdřív si všechny čtyři porovnej v tooltipech. Návod pokračuje podle toho, který si vezmeš. Rubín nebo smaragd si nech: odevzdává se zpátky.",
	["The demon's spirit"] = "Démonův duch",
	["The {item:15107}"] = "{item:15107}",
	["The {item:15108}"] = "{item:15108}",
	["Wait beside {npc:6266} while she makes the orb"] = "Počkej vedle {npc:6266}, než vyrobí kouli",
	["{area:602} fills south-central {zone:1443}, east of {area:2408}. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the {item:7291} every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with {spell:1120}: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant)."] = "{area:602} vyplňuje jižní část středu {zone:1443}, východně od {area:2408}. Burning Blade Summoners (level 38–39, warlockové s impy) nesou {item:7291} pokaždé. Kvůli duchovi dostaň svého démona damage over time na nízké zdraví, pak na něj channeluj rubín nebo smaragd a channeluj dál, zatímco umírá, jako u {spell:1120}: drahokam sám žádné poškození nedělá. Rubín funguje na felhoundy covenu: dva Mana Eaters (37–38) na severu a Mage Hunters (38) a Ley Hunters (39) dál na jihu. Smaragd funguje na Lesser Infernals (36–37, šestnáct, odolní proti ohni).",
	["{item:12648}, from a {npc:4678}, {npc:4681} or {npc:4685}"] = "{item:12648} z {npc:4678}, {npc:4681} nebo {npc:4685}",
	["{item:12649}, from a {npc:4676}"] = "{item:12649} z {npc:4676}",
}
t.guides["forever/class/warlock/orb-of-soranruk"] = {
	["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "Vzácná koule do druhé ruky nebo hůl pro tvoje dvacítky, za úlomky ze dvou dungeonů.",
	["Back to {npc:6247}"] = "Zpět do {npc:6247}",
	["Choose the off-hand {item:6898} or the two-handed {item:15109}."] = "Vyber {item:6898} do druhé ruky, nebo obouruční {item:15109}.",
	["{area:236} (level 22-30, a group of five) stands on the hill south of the {area:228}. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop."] = "{area:236} (level 22–30, skupina pěti) stojí na kopci jižně od {area:228}. Osvoboď vězně v celách vpravo od vchodu a on ti otevře cestu na nádvoří. Shadowfang Darksouls (level 20–21, elite) nejsou na nádvoří: chodí po chodbách za ním, nahoru po rampě, která se stáčí doleva, a v budově za ní. Za průchod jich stojí asi dvanáct a každý pátý dropne Large Fragment, takže vyčisti všechny Darksouls a když nepadne, jdi znovu.",
	["{area:2797} (level 24-32, a group of five) opens in the ruins on the north-west coast of {zone:1440}, under the water at {area:414}. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around {npc:4832} and the altar before {npc:4829}; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest."] = "{area:2797} (level 24–32, skupina pěti) se otevírá v ruinách na severozápadním pobřeží {zone:1440}, pod vodou u {area:414}. Twilight Acolytes (level 24–25, elite, healeři) stojí v posledních síních, kolem {npc:4832} a oltáře před {npc:4829}; každý dropne úlomek, ale za průchod se spawnou jen tři a dvě hodiny se nevrátí, takže jeden průchod pokryje jednoho warlocka: zabij je první, než vyléčí ostatní.",
}
t.guides["forever/class/warlock/shard-of-the-green-flame"] = {
	["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Vzácný předmět do druhé ruky pro tvoje padesátky od {npc:14469} a {npc:14470} v {zone:1448}, v táboře, který nabízí i An Imp's Request.",
	["At 50 {npc:14469} and his imp {npc:14470} wait on a rise in central {zone:1448} just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. {npc:14469} sends you to {npc:14470}, beside him, who wants three Flawless Fel Essences from three places."] = "Na 50 čekají {npc:14469} a jeho imp {npc:14470} na vyvýšenině ve středním {zone:1448} kousek severovýchodně od {area:1997}: když jdeš na sever přes most {area:1765}, stojí kousek od cesty na východ, za pár slizy. {npc:14469} tě pošle k {npc:14470} vedle sebe, který chce tři Flawless Fel Essences ze tří míst.",
	["Back to {npc:14469}"] = "Zpět do {npc:14469}",
	["Back to {npc:14470}. He hands you the {item:18626}: keep it, it wakes the infernal {npc:14467}."] = "Zpět k {npc:14470}. Dá ti {item:18626}: nech si ho, probudí infernala {npc:14467}.",
	["The Felguard Sentries (level 54) walk around the {area:72} in the south of the {zone:1419}, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest."] = "Felguard Sentries (level 54) chodí kolem {area:72} na jihu {zone:1419}, každý s felhunterem. Servants of Razelikh na levelu 57 nech být: bez vlastního questu se zabít nedají.",
	["{area:1763} lies just south of {area:1997}, west of the road. The guide waits for level 54 first: its Legionnaires are 55. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763} leží kousek jižně od {area:1997}, západně od silnice. Návod nejdřív počká na level 54: tamní Legionnaires mají 55. Ze dvou jeskyní je {area:1770} ta severní, výš do kopce; v druhé Legionnaires nejsou. Tunely {area:1770} vedou na sever pod kopci a Jaedenar Legionnaires (level 55) stojí v jejích hlubších síních, od prvních ramp směrem ke komnatě {npc:9516}; každého na blízko omráčí Uppercutem. Esenci dají tři zabití ze čtyř, ale spawne se jich jen asi jedenáct: probij se dovnitř a případně počkej pět minut na respawn. Kultisté v {area:1763} i {area:1770} jsou všichni nepřátelští.",
	["{npc:14467}' remains lie in {area:1766}, the burnt crater north of {npc:14469}: follow the road north from his camp; the remains lie a little east of it. Use the {item:18626} beside them and wait for him to rise. {npc:14467} is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull {npc:14467} away from it. He always drops his core. Lost the {item:18626}? Abandon the quest and take it again from {npc:14470}."] = "Ostatky {npc:14467} leží v {area:1766}, vypáleném kráteru severně od {npc:14469}: jdi z jeho tábora po cestě na sever; ostatky leží kousek východně od ní. Použij vedle nich {item:18626} a počkej, až povstane. {npc:14467} je elite (level 55): doporučuje se skupina; warlock na 55 a víc ho zvládne sólo s Fear a damage over time, nebo s Enslave Demon, ale ohnivá kouzla na něj nefungují a odhazuje tě. Když umřeš, vyléčí se na plno; tři minuty po smrti znovu povstane. Kolem jezírka jižně od ostatků hlídkuje elitní infernal: odtáhni {npc:14467} od něj. Své jádro dropne vždycky. Ztratil jsi {item:18626}? Zruš quest a vezmi si ho znovu u {npc:14470}.",
}
t.guides["forever/class/warlock/tome-of-sacrifice"] = {
	["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "Vzácný předmět do druhé ruky na 60, platba {npc:14463} za chycení {npc:12396} v {zone:1419}.",
	["At 60 {npc:14463} waits in the {area:73}, the demon-filled hollow in the west of the {zone:1419}. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. {npc:14463} gives you two errands at once."] = "Na 60 čeká {npc:14463} v {area:73}, prohlubni plné démonů na západě {zone:1419}. Scar je plná tvrdě bijících elit: nejdřív si dej Soulstone, pak se při vstupu drž pravé stěny, nebo projeď na mountovi. {npc:14463} ti dá dvě pochůzky naráz.",
	["Back to {npc:14463}"] = "Zpět do {npc:14463}",
	["Hand both in to {npc:14463} and take the {item:18601}. Find a {npc:12396} (level 61, elite) standing alone in the {area:73}, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his {spell:45} can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the {item:18605}: click it. If the channel breaks, kill him or run, and try another."] = "Odevzdej obojí {npc:14463} a vezmi si {item:18601}. Najdi {npc:12396} (level 61, elite), který stojí sám v {area:73}, začni zhruba z 30 yardů s voidwalkerem na něm a channeluj na něj vězení asi 20 sekund: zaútočí na tebe, aby se osvobodil, a jeho {spell:45} může channel přerušit, takže v nouzi obětuj voidwalkera kvůli štítu. Skupina se hodí: s druhým hráčem jako tankem je to snadné. Když channel doběhne, stane se z něj {item:18605}: klikni na něj. Když se channel přeruší, zabij ho nebo uteč a zkus jiného.",
	["The Hederine demons (level 57-60, elite) hold {area:2256} in the far south of {zone:1452}: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their {spell:7645}). A warlock can solo them one at a time with Fear or {spell:710} and damage over time, but slowly. Any of them can drop the Tears, four kills in five."] = "Démoni Hederine (level 57–60, elite) drží {area:2256} na dalekém jihu {zone:1452}: skupina se doporučuje. Soutěsku za mostem hlídají dva Slayers; západní tunel vede k dalším Initiates, z nich nejsnazším (pozor na jejich {spell:7645}). Warlock je zvládne sólo po jednom s Fear nebo {spell:710} a damage over time, ale pomalu. Kdokoli z nich může dropnout Tears, čtyři zabití z pěti.",
	["{item:18601}, on a {npc:12396}"] = "{item:18601} na {npc:12396}",
	["{item:18603}, from the Wildspawn inside"] = "{item:18603} z Wildspawn uvnitř",
}
t.guides["forever/class/warlock/voidwalker-alliance"] = {
	["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "Na 10 tě {npc:6120}, trenér warlocků v {object:32383} v {zone:1455}, pošle k {npc:6122} v {zone:1453}. Vezmi {area:2257} z {object:171524}. Když ti ho {npc:6120} nenabídne, jdi za {npc:6122} i tak: další quest ti dá stejně.",
	["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "Na 10 tě {npc:6121}, ve sklepě Lion's Pride Inn v {area:87} (schody dolů jsou v zadní místnosti za řeznickým stolem), pošle k {npc:6122} v {zone:1453}.",
	["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "Zpět k {npc:6122}. Dá ti {item:6928}. Kruh se špatně hledá: sejdi po schodech za {npc:6122} dolů; zhruba v polovině nejnižší chodby vede vlevo boční schodiště do místnosti se zářícím fialovým kruhem uprostřed. Stoupni si do něj a použij obojek. Voidwalker (level 10, ne elitní) je pod 30 % zdraví nebezpečný: {spell:14868}, Corruption a {spell:348} s impem na něm, Fear, když se přiblíží. Když tě porazí, použij obojek znovu. Obojek si nech: {npc:6122} si ho vezme zpět.",
	["Voidwalker (Alliance)"] = "Voidwalker (Aliance)",
	["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881} (level 9) je uvnitř statku na {area:62}, v jihovýchodním Elwynnu u cesty do Redridge. {npc:473} (level 10) a warrior stojí s ní a zapojí se do boje; Morgan dává gouge a jde po tvém impovi, tak ho drž ve Fearu. Dej nejdřív damage over time na {npc:881}, ostatní Fearni a lootni její náhrdelník, než je dorazíš: zůstane ti, i když potom umřeš. Hází fireballs z dálky a tři minuty po smrti je zpátky. Měj quest dřív, než ji zabiješ, jinak náhrdelník nepadne.",
	["{quest:1685} (Humans)"] = "{quest:1685} (Lidé)",
	["{quest:1715} (Gnomes)"] = "{quest:1715} (Gnómové)",
	["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715} je krčma v {object:2101}; {npc:6122} je v jejím sklepě, uvnitř dolů po schodech.",
}
t.guides["forever/class/warlock/voidwalker-horde"] = {
	["At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two."] = "Na 10 tě {npc:3294} pošle k {npc:5875}. Stojí venku za kasárnami {area:362}, velkou budovou na východní straně města (ne hostincem), pár kroků od {npc:3172}, trenéra warlocků. {npc:5875} stojí se staršími warlocky v {object:172960}, jeskyni pod {object:172982} v {zone:1454}. Ork nebo Troll, který leveluje v {zone:1420}, může místo toho vzít verzi pro {zone:1458} od {npc:5724} v {area:159} (kroky {zone:1458} níže): můžeš udělat jen jednu z obou.",
	["At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned."] = "Na 10 tě {npc:5724}, nahoře v {area:2119} v {area:159}, pošle k {npc:5675}: verze pro Nemrtvé a pro Orky a Trolly, kteří levelují v {zone:1420} místo toho, aby vzali quest {npc:5875}. {npc:5675} stojí v {object:36082} v {zone:1458}, u Temple of the Damned.",
	["Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back."] = "Zpět k {npc:5675}. Dá ti {item:6284}: jdi od něj po schodech dolů k vyvolávacímu kruhu a použij je, zatímco v něm stojíš. S voidwalkerem (level 10, ne elitní) bojuj v kruhu: když odejde, můžou ho zabít městské stráže a zabití se nepočítá. {spell:14868}, Corruption a {spell:348} s tankujícím impem ho složí; pod 30 % bije silněji. Když prohraješ, použij runy znovu. Runy si nech: {npc:5675} si je vezme zpět.",
	["Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back."] = "Zpět k {npc:5875}. Dá ti {item:7464}: přenes je přes {object:172960} do stanu {npc:3216}, stoupni si do fialového kruhu na jeho podlaze a použij je. Voidwalker (level 10, ne elitní) na 30 % zdraví bije tvrdě a po třech minutách odejde, tak začni hned: {spell:14868}, Corruption a {spell:348}, pošli na něj impa a Fearni ho, když potřebuješ oddech. Když tě porazí nebo odejde, glyfy se nespotřebují: použij je v kruhu znovu. Glyfy si nech: {npc:5875} si je vezme zpět.",
	["Voidwalker (Horde)"] = "Voidwalker (Horda)",
	["{area:817} is the cave in the cliffs just east of {zone:1454}'s gate. Inside, take the right-hand ramp up and follow it to the top: the {object:58595} sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and {npc:3204}, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet."] = "{area:817} je jeskyně v útesech kousek východně od brány {zone:1454}. Uvnitř jdi po pravé rampě nahoru až na vrchol: {object:58595} leží na té horní římse, na kterou se ze spodního patra nedostaneš. Jeskyně je narvaná Burning Blade Apprentices a Fanatics (level 9–11, mnozí s voidwalkery), kteří se rychle respawnují, a u skrýše stojí {npc:3204}, warlock Burning Blade levelu 14. Staré poznámky ho uvádějí jako elite; data Forever ho mají jako normálního. Na levelu 10 je to sólo těžké: pullni vždy jednu skupinu a přebývajícího Fearni, počkej na level 11, nebo jdi s kamarádem. Ve skrýši je tabulka vždycky.",
	["{item:6285}, in {object:37098}"] = "{item:6285}, v {object:37098}",
	["{item:6535}, in the {object:58595}"] = "{item:6535}, v {object:58595}",
	["{quest:1506} (Orcs and Trolls)"] = "{quest:1506} (Orkové a Trollové)",
}
t.guides["forever/class/warrior/brutal-armor"] = {
	["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "Na 20 tě {npc:3041}, trenér warriorů v {zone:1456}, pošle k {npc:6394} v {area:378}.",
	["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "Na 20 tě {npc:3354} v {object:172958} pošle k {npc:6394} v {area:378}.",
	["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "Na 20 tě {npc:4595}, trenér warriorů v {zone:1458}, pošle k {npc:6394} v {area:378}.",
	["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "Zpět k {npc:5878} na {area:1699}. {quest:1848} je první kus; pak tě pošle ke třem řemeslníkům, jeden na kus: vezmi všechny tři.",
	["Fly to {area:378}. {npc:6394} stands in the hut with the leatherworking and tailoring trainers."] = "Leť do {area:378}. {npc:6394} stojí v chýši s trenéry leatherworkingu a tailoringu.",
	["Hillsbrad Miners"] = "Hillsbrad Miners",
	["Starts now at 20 at your trainer; four armor pieces at 30 (hauberk, helm, gauntlets, legguards), a shield on the way."] = "Teď začíná na 20 u tvého trenéra; čtyři kusy zbroje na 30 (hauberk, helma, rukavice, chrániče nohou), po cestě štít.",
	["Take the zeppelin from {zone:1454} to {zone:1420}; {npc:6411} works in the {zone:1458}'s {object:36078}. She wants 8 Sturdy Dragonmaw Shinbones."] = "Vezmi zeppelin z {zone:1454} do {zone:1420}; {npc:6411} pracuje v {object:36078} v {zone:1458}. Chce 8 Sturdy Dragonmaw Shinbones.",
	["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "Orkové Dragonmaw (level 26–30) táboří uprostřed {zone:1437}; z {area:321} v Arathi jdi na jih přes {area:881} ({area:150} je aliančí). S {quest:1846} od {npc:6411} v logu dropne každý Raider, Swamprunner, Centurion, Shadowwarder a Bonewarder {item:7131} (bez questu nedropují nic): pravým kliknutím ji otestuj, asi jedna ze čtyř vyjde pevná, ostatní se zlomí, takže počítej s 30 a více zabitími na 8. Testovat můžeš za pohybu i v boji. Orkové na 15 % utíkají pro pomoc; Raiders tě chytají do sítě, Centurions dávají shield bash, Shadowwarders sesílají {spell:686}, Bonewarders vyvolávají kostlivce.",
	["The satyrs of {area:430}, north-east of {area:431} ({area:429}, level 28-30), and the Felmusk satyrs north-west of the post (25-27) drop a hoof four kills in five. A {area:429} satyr at 15% health may cast {spell:6925} and heal to full: finish it fast or stun it. Hellcallers throw Fireballs from 40 yards; Felmusk satyrs reek in melee and run for help at 15%."] = "Satyrové z {area:430}, severovýchodně od {area:431} ({area:429}, level 28–30), a satyrové Felmusk severozápadně od stanoviště (25–27) dropnou kopyto ve čtyřech z pěti zabití. Satyr z {area:429} na 15 % zdraví může seslat {spell:6925} a vyléčit se na plno: dorazi ho rychle nebo ho omráč. Hellcallers hází Fireballs ze 40 yardů; satyrové Felmusk na blízko páchnou a na 15 % utíkají pro pomoc.",
	["{item:6840}, from the {npc:6167}"] = "{item:6840}, od {npc:6167}",
}
t.guides["forever/class/warrior/fire-hardened-armor"] = {
	["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "Na 20 tě {npc:5113}, trenér warriorů v {zone:1455}, pošle k {quest:1698} v Redridge.",
	["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "Na 20 tě {npc:5479}, vedle {npc:5480} v budově trenérů warriorů v {object:2100}, pošle k {quest:1698} v Redridge.",
	["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "Na 20 tě {npc:7315}, trenér warriorů v {zone:1457}, pošle k {quest:1698} v Redridge.",
	["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "Zpět k {npc:5413} do {object:28027} pro kroužkovou zbroj. Pak tě pošle ke kováři tvé rasy; kusy dalších dvou kovářů jsou ti otevřené taky: promluv s nimi přímo.",
	["Charred and Galvanized Horns"] = "Charred a Galvanized Horns",
	["Enter the {area:98} and come back; below ground, at the first fork"] = "Vejdi do {area:98} a vrať se; pod zemí, u prvního rozcestí",
	["Fire Hardened Armor"] = "Fire Hardened Armor",
	["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "Jeď {area:2257} ze {zone:1453} do {zone:1455}. {quest:1704}, gnómský kovář, pracuje v {object:171524} u trenérů engineeringu. Chce 20 {item:6848}.",
	["Starts now at 20 with a shield; a hauberk at 28, then a coif, leggings and gauntlets from three smiths."] = "Teď začíná na 20 se štítem; hauberk na 28, pak kápě, kalhoty a rukavice od tří kovářů.",
	["The chimaeras live south-west of {area:460} in the {area:465}; the guide waits for level 28 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "Chiméry žijí jihozápadně od {area:460} v {area:465}; návod nejdřív počká na level 28. Potřebuješ 12 Charred Horns z Fledgling (level 25–27) a Young Chimaeras (23–25), padají ze čtyř z pěti zabití, a {item:6840} z {npc:6167} (28, ta velká), taky ze čtyř z pěti. Žijí tam jen tři Fledglings, dvě Young a jedna Matriarch, každá se vrací za 5 minut, takže počítej s čekáním. Fledglings a Matriarch plivou {spell:3396}, Young sesílají {spell:403}. Aliance: leť do {area:467} a jdi na jih.",
	["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once: the guide waits for level 30 first."] = "Skořápky leží na zemi pod hnízdy wyvern v {area:482} na západě {zone:1441}, hlouběji v soutěsce. Je jich jen devět a každá se vrací 3 minuty po sebrání, takže si počkáš; některé věci podobné skořápkám tam vylootovat nejdou. Hlídají je Highperch Wyverns (level 28–31) a občas jich přijde víc najednou: návod nejdřív počká na level 30.",
	["The {area:98}"] = "{area:98}",
	["{item:6840}, from the {npc:6167}"] = "{item:6840}, od {npc:6167}",
	["{item:6845}, from {npc:6170}"] = "{item:6845}, od {npc:6170}",
	["{item:6848}, from {quest:1708}"] = "{item:6848}, od {quest:1708}",
	["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416} vede obchod se zbraněmi na severozápadě {object:28027}, kousek od {npc:5413}. Chce 20 {quest:1705} a {item:6845}.",
	["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield."] = "{npc:5413} pracuje v Dwarven District ve Stormwindu. Vezme {item:6843} (ztratil jsi ho? zahoď quest a {npc:6166} ti dá nový) a dá ti {item:6970}, štít.",
	["{npc:5413}'s next task, {quest:1701}, is a level 28 quest: its chimaeras and Roogug are level 28, so the guide waits for level 27 before you take it. Come back to {npc:5413} in the {object:28027} then; {item:6842} list what it needs."] = "Další úkol od {npc:5413}, {quest:1701}, je quest na level 28: jeho chiméry i Roogug mají level 28, takže návod počká na level 27, než si ho vezmeš. Pak se vrať k {npc:5413} do {object:28027}; {item:6842} vypisují, co potřebuje.",
	["{quest:1698} sits in the inn at {area:69}. His test is timed, and it is a level 22 quest, so the guide waits for level 21 before you take it: before that, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698} sedí v hostinci v {area:69}. Jeho zkouška je na čas a je to quest na level 22, takže návod čeká na level 21, než ho vezmeš: předtím vyčisti gnolly z Redridge na cestě k {area:98} v kopcích severozápadně od {area:69}, včetně dvou na skále u ústí jeskyně (vylez na ni z pravé strany).",
	["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703} pracuje na jižní straně {area:1660} v {zone:1457}. Chce 20 {quest:1710}.",
	["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}, z worgenů Nightbane",
}
t.guides["forever/class/warrior/haggards-weapons"] = {
	["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "Na 10 tě {npc:1229}, trenér warriorů v {area:131}, pošle k {quest:1679} v {zone:1455}. Každý warrior Aliance smí vzít jednu ze tří cest, nikdy dvě: jsi na 10 stejně v {zone:1453}? {quest:1638} od {npc:5480} je nejrychlejší postoj (jeden boj v hospodě), s Haggardovou zbraní potom.",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Na 10 stojí {npc:252377} s trenéry u západní brány {area:16638}. Kultista {npc:257196} drží štít její rodiny u {area:16629}.",
	["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "Na 10 tě {npc:3598}, trenér warriorů v {area:186}, nebo {npc:2151}, který hlídkuje na cestě západně od {area:186}, pošle k {quest:1684} na {area:1660} v {zone:1457}. Každý warrior Aliance smí vzít jednu ze tří cest, nikdy dvě: jsi na 10 stejně v {zone:1453}? {quest:1638} od {npc:5480} naučí stejný postoj po jednom boji v hospodě.",
	["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "Na 10 tě {npc:913}, trenér warriorů u hostince v {area:87}, pošle k {npc:6089} v {zone:1453}; nabízí ho i {npc:5480}, trenér warriorů v {object:2100} v {zone:1453}.",
	["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "Zpět na {area:1660}: {npc:4088} ti dá {item:6812}; {npc:6142} pracuje na vzdálené, jižní straně stejné terasy, snadno se přehlédne.",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "Zpět k {npc:252377} do {area:16638}. Naučí {spell:71} a dá ti {item:275290}, štít k němu. Cesta {npc:6090} níže pořád dá zbraň, až se dostaneš do {zone:1453}.",
	["Back to {npc:294}"] = "Zpět do {npc:294}",
	["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "Zpět k {npc:6114} pro {spell:71}, pak k {quest:1680} u {object:32372} uprostřed {zone:1455}.",
	["Elunite under {area:442}"] = "Elunit pod {area:442}",
	["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Z {area:16638} jdi na severozápad k {area:16629}. {npc:257196} stojí západně od přístupu ke svatyni, mezi Guardians, Spiritcallers a Blademasters kultu: pullni je po jednom, než se pustíš do něj. Dropuje {item:263993}.",
	["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "Vezmi loď z {area:702} do {area:442}. Vrak leží pod vodou kousek jižně od jižního mola v {area:442}, kde kotví loď z Menethilu. Otevírej Crates of Elunite na mořském dně kolem vraku, u obrovské potopené želvy, směrem k pláži a pod molem, dokud jich nemáš osm; v každé bedně je ruda a respawnuje se za 3–5 minut. Šedý {npc:6133} (level 11) se vznáší kolem středu vraku a medailon dropne vždycky: když ho uvidíš, dej si ho do targetu, ať ho po vynoření pro vzduch najdeš. Hlídej si dech; můžou se přidat Threshers.",
	["{item:263993}, from {npc:257196}"] = "{item:263993}, od {npc:257196}",
	["{item:6782}, from {object:85563}"] = "{item:6782}, od {object:85563}",
	["{item:6800}, from {object:85562}"] = "{item:6800}, od {object:85562}",
	["{item:6809}, from the {npc:6133}"] = "{item:6809}, od {npc:6133}",
	["{npc:252377} in {area:16638}"] = "{npc:252377} v {area:16638}",
	["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "Sídlo {npc:294} stojí na jihovýchodním okraji {area:88} ve východním Elwynnu, na konci krátké cesty, která se nenapojuje na hlavní.",
	["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678} (level 11, osamělý troll) čeká u své chýše na kopci jižně od {area:135}, u hor na konci krátké rampy, bez dalších trollů kolem; chýše vpředu u {area:135} je ta špatná. Bojuje v {spell:71} a rozbíjí ti brnění; {spell:6343} ho zpomalí. Jeho hlava padá vždycky; vrátí se asi 8 minut po smrti.",
	["{quest:1679} in {zone:1455}"] = "{quest:1679} v {zone:1455}",
	["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679} stojí v {object:32390} v {object:32359}.",
	["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681} leží ve východním {zone:1426}, pod {area:212} na jeho jižní straně. Po cestě stojí Dark Iron Spies (level 8–10), dost daleko od sebe, abys je tahal po jednom. {object:85562} je ve sklepě nejjižnějšího domu; {npc:6124} (level 11) stojí u ní a hned, jak tě uvidí, zaútočí. Skříňka obsahuje rudu vždycky a doplní se 15 minut po otevření.",
	["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683} (level 10, satyr) stojí u skryté měsíční studny nahoře na svahu západně od {area:186}. Stezka se špatně hledá: začíná za táborem Gnarlpine a stoupá serpentinami lemovanými lampami. Furbolgové dole můžou chodit ve skupinách. Jeho roh padá vždycky; vrátí se 5 minut po smrti.",
	["{quest:1684} in {zone:1457}"] = "{quest:1684} v {zone:1457}",
	["{quest:1684} stands on the {area:1660}."] = "{quest:1684} stojí na {area:1660}.",
}
t.guides["forever/class/warrior/heirloom-weapon"] = {
	["At 10, {npc:2131}, the warrior trainer inside the inn of {area:159}, sends you to {npc:1496} by the graveyard on {area:159}'s west edge. This road and {npc:5810}'s exclude each other: drop {quest:1505} or {quest:1498} from your log if you hold one."] = "Na 10 tě {npc:2131}, trenér warriorů v hostinci {area:159}, pošle k {npc:1496} u hřbitova na západním okraji {area:159}. Tahle cesta a cesta {npc:5810} se vylučují: pokud máš v deníku {quest:1505} nebo {quest:1498}, zruš ho.",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Na 10 stojí {npc:252377} s trenéry u západní brány {area:16638}. Kultista {npc:257196} drží štít její rodiny u {area:16629}.",
	["At 10, {npc:3063}, the warrior trainer of {area:222}, sends you to {npc:5810} in the {zone:1413}. {npc:3041} in {zone:1456} offers it too."] = "Na 10 tě {npc:3063}, trenér warriorů v {area:222}, pošle k {npc:5810} v {zone:1413}. Nabízí ho i {npc:3041} v {zone:1456}.",
	["At 10, {npc:3169}, the warrior trainer in the barracks of {area:362}, sends you to {npc:5810} in the {zone:1413}. Sorek in {zone:1454}'s {object:172958} offers it too. Any Horde warrior may take one of the two roads, never both: heading to {zone:1420} at 10 anyway? {npc:2131} in {area:159}'s inn offers the other: one fight by {area:159}'s graveyard for the same stance, then the Agamand crypt for an heirloom weapon."] = "Na 10 tě {npc:3169}, trenér warriorů v kasárnách {area:362}, pošle k {npc:5810} v {zone:1413}. Nabízí ho i Sorek v {object:172958} v {zone:1454}. Každý warrior Hordy smí vzít jednu ze dvou cest, nikdy obě: míříš na 10 stejně do {zone:1420}? {npc:2131} v hostinci {area:159} nabízí tu druhou: jeden boj u hřbitova {area:159} za stejný postoj, pak krypta Agamandů za zděděnou zbraň.",
	["Back to {npc:1500}"] = "Zpět do {npc:1500}",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor."] = "Zpět k {npc:252377} do {area:16638}. Naučí {spell:71} a dá ti {item:275290}, štít k němu. Cesta {npc:5810} níže dá později pořád zbraň, až se dostaneš do Kalimdoru.",
	["Back to {npc:5810} under his tree west of {area:379}."] = "Zpět k {npc:5810} pod jeho strom západně od {area:379}.",
	["Dillinger stands by the graveyard on {area:159}'s west edge. An Orc, Troll, Tauren or Skyborne who took {quest:1818} from {npc:2131} instead of {npc:5810}'s road is led through {area:159} from here."] = "Dillinger stojí u hřbitova na západním okraji {area:159}. Ork, Troll, Tauren nebo Skyborne, který místo cesty {npc:5810} vzal {quest:1818} od {npc:2131}, je odsud veden přes {area:159}.",
	["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Z {area:16638} jdi na severozápad k {area:16629}. {npc:257196} stojí západně od přístupu ke svatyni, mezi Guardians, Spiritcallers a Blademasters kultu: pullni je po jednom, než se pustíš do něj. Dropuje {item:263993}.",
	["The four Agamand Weapon Racks are inside the {area:158} at the north end of {area:157}, north of {area:159}, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them."] = "Čtyři Agamand Weapon Racks jsou uvnitř {area:158} na severním konci {area:157}, severně od {area:159}, jeden stojan v každé místnosti: jeden v nejnižší místnosti, dva v dvojici místností po schodech nahoru, jeden v místnosti nad nimi. Stojan na sekery stojí v tmavém rohu. Nemrtví v kryptě chodí ve skupinkách po třech a víc a rychle se vracejí; ti v horní místnosti nejsou propojení. Stojany na sekery, dýky a palcáty se po vylootování doplní za 15 minut.",
	["The {area:158}"] = "{area:158}",
	["{item:263993}, from {npc:257196}"] = "{item:263993}, od {npc:257196}",
	["{item:6534}, from the {object:58369}"] = "{item:6534}, od {object:58369}",
	["{npc:1500} is in the {area:2119}, the inn on {area:159}'s east side."] = "{npc:1500} je v {area:2119}, hostinci na východní straně {area:159}.",
	["{npc:252377} in {area:16638}"] = "{npc:252377} v {area:16638}",
}
t.guides["forever/class/warrior/quelserrar"] = {
	["A tank sword at 60: a {area:2577} book, then {npc:10184}'s breath tempers the blade (the sword is not in Forever's items yet)."] = "Tankovací meč na 60: kniha z {area:2577}, pak dech {npc:10184} zakalí čepel (meč zatím ve Foreveru mezi předměty není).",
	["Back to {npc:14368} in the Athenaeum of Dire Maul West: through the West door with the {item:18249} again, and a group to reach the library."] = "Zpět k {npc:14368} do Athenaea v Dire Maul West: znovu přes západní dveře s {item:18249} a se skupinou až do knihovny.",
	["{item:18488}, on her corpse"] = "{item:18488} na její mrtvole",
	["{item:18489}: plant it in her breath"] = "{item:18489}: zasaď ho do jejího dechu",
	["{npc:14368} stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the {item:18249}, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you {item:18513} to give straight back, then the {item:18489}. Keep that blade: lose it, and you must abandon the quest and take it again."] = "{npc:14368} stojí v Athenaeu, knihovně na vzdáleném konci Dire Maul West, za Court of the Highborne a Prison of Immol'thar. Dveře do West vyžadují {item:18249}, který dropne Pusillin v Dire Maul East (utíká; žeň se za ním), nebo rogue, který zámek vypáčí. Na pročištění cesty do knihovny potřebuješ svou pětičlennou skupinu. Vezme si knihu, dá ti {item:18513}, který mu hned vrátíš, a pak {item:18489}. Tu čepel si nech: když ji ztratíš, musíš quest zrušit a vzít si ho znovu.",
	["{npc:14368}, in the Athenaeum"] = "{npc:14368}, v Athenaeu",
	["{npc:14368}: hand back the Dull and Flat Elven Blade"] = "{npc:14368}: vrať mu Dull and Flat Elven Blade",
}
t.guides["forever/class/warrior/voodoo-feathers"] = {
	["At 50, {npc:3041}, the warrior trainer of {zone:1456}, sends you to the {npc:7572} in the {zone:1435}."] = "Na 50 tě {npc:3041}, trenér warriorů v {zone:1456}, pošle k {npc:7572} v {zone:1435}.",
	["At 50, {npc:3354} in the {object:172958} sends you to the {npc:7572} in the {zone:1435}."] = "Na 50 tě {npc:3354} v {object:172958} pošle k {npc:7572} v {zone:1435}.",
	["At 50, {npc:4593}, a warrior trainer of the {zone:1458}, sends you to the {npc:7572} in the {zone:1435}."] = "Na 50 tě {npc:4593}, trenér warriorů v {zone:1458}, pošle k {npc:7572} v {zone:1435}.",
	["At 50, {npc:5113}, the warrior trainer of {zone:1455}, sends you to the {npc:7572} in the {zone:1435}."] = "Na 50 tě {npc:5113}, trenér warriorů v {zone:1455}, pošle k {npc:7572} v {zone:1435}.",
	["At 50, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to the {npc:7572} in the {zone:1435}."] = "Na 50 tě {npc:5479}, vedle {npc:5480} v budově trenérů warriorů v {object:2100}, pošle k {npc:7572} v {zone:1435}.",
	["At 50, {npc:7315}, the warrior trainer of {zone:1457}, sends you to the {npc:7572} in the {zone:1435}."] = "Na 50 tě {npc:7315}, trenér warriorů v {zone:1457}, pošle k {npc:7572} v {zone:1435}.",
	["Back to the {npc:10996}"] = "Zpět k {npc:10996}",
	["Experience"] = "Zkušenosti",
	["Experience at 50, ending in the {area:1417}; Classic's item choice may be gone on Forever."] = "Zkušenosti na 50, končí v {area:1417}; výběr předmětu z Classicu ve Foreveru možná chybí.",
	["Helboars"] = "Helboars",
	["In Classic the {npc:10996} let you choose the {item:20130}, the {item:20521} or the {item:20517} here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in."] = "V Classicu tě tu {npc:10996} nechal vybrat {item:20130}, {item:20521} nebo {item:20517}. Poznámky ke změnám na Forever říkají, že volba zmizela, i když stránka questu pořád uvádí tři nepojmenované odměny: před odevzdáním se podívej do okna odměn.",
	["The {area:1417}"] = "{area:1417}",
	["The {npc:7572}"] = "{npc:7572}",
}
t.guides["forever/class/warrior/whirlwind-weapon"] = {
	["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:3041}, trenér warriorů v {zone:1456}, pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:3354} v {object:172958} pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:4595}, trenér warriorů v {zone:1458}, pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:5113}, trenér warriorů v {zone:1455}, pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["At 30, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:5479}, vedle {npc:5480} v budově trenérů warriorů v {object:2100}, pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["Back to {npc:6176}. Accepting {quest:1713} starts his ritual, and {quest:1712} appears just north of his camp. {quest:1712} is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a {item:6052} soaks it), whirls, and {spell:10101} throws you far while it heals itself as you run back: fight with your back to a slope or rock. The {item:6894} always drops. If the fight fails {npc:6176} stops answering: abandon {quest:1713} and take it again for a new summon; the earlier items are not needed again."] = "Zpět k {npc:6176}. Přijetím {quest:1713} začne jeho rituál a {quest:1712} se objeví kousek severně od jeho tábora. {quest:1712} je elitní (level 40): doporučuje se skupina; potřebuje skupinu dvou nebo tří kolem levelu 40. Dává nature poškození (pohltí ho {item:6052}), víří a {spell:10101} tě odhodí daleko, zatímco se léčí, když běžíš zpátky: bojuj zády ke svahu nebo skále. {item:6894} padá vždy. Když boj selže, {npc:6176} přestane odpovídat: zruš {quest:1713} a vezmi znovu kvůli novému vyvolání; dřívější předměty znovu potřeba nejsou.",
	["Bloodscalp Tusks"] = "Bloodscalp Tusks",
	["Click {object:89931} with the 24 charms in your bags and {quest:1712} in your log. Its window asks for the charms straight away, with nothing to accept: Continue, then Complete, and it hands you the {quest:1714}."] = "S 24 amulety v taškách a {quest:1712} v deníku klikni na {object:89931}. Jeho okno si hned řekne o amulety a nic se nepřijímá: Continue, pak Complete, a dá ti {quest:1714}.",
	["Fly to {area:392} and go south along the {area:391}. {area:720} lies offshore to the south-east: wade across on the shallow sand bar; off it the water is deep and fatigue sets in. {npc:6236} stands by the arena."] = "Leť do {area:392} a jdi na jih podél {area:391}. {area:720} leží v moři na jihovýchodě: přebroď se po mělké písečné kose; mimo ni je voda hluboká a nastupuje únava. {npc:6236} stojí u arény.",
	["The exiles of Arathi"] = "Vyhnanci z Arathi",
	["{item:6894}, from {quest:1712}"] = "{item:6894}, od {quest:1712}",
	["{quest:1714}, from the cauldron by {npc:6176}"] = "{quest:1714}, z kotle u {npc:6176}",
}
t.guides["forever/collectibles/mounts/alliance/black-war-mounts"] = {
	["Black War Mounts"] = "Black War Mounts",
	["PvP rank 11"] = "PvP rank 11",
	["{item:18243}, {spell:10907}, 100g"] = "{item:18243}, {spell:10907}, 100g",
	["{item:18244}, {spell:826}, 100g"] = "{item:18244}, {spell:826}, 100g",
	["{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12783} prodává mounty v {object:2100} v {zone:1453} u {area:2918}, vedle ostatních honor quartermasterů. Klient Forever uvádí každý za 100 zlatých. Každý také vyžaduje jízdu na svém druhu: lidé jezdí na koni, noční elfové na tygrovi, gnómové na battlestrideru, trpaslíci na beranovi. Skyborne, nebo kdokoli, kdo si vybere mounta jiné rasy, se nejdřív musí naučit tu jízdu u jejího trenéra (Exalted u města té rasy).",
	["{npc:14332}, {spell:824}, 100g"] = "{npc:14332}, {spell:824}, 100g",
	["{spell:22723}, {spell:828}, 100g"] = "{spell:22723}, {spell:828}, 100g",
}
t.guides["forever/collectibles/mounts/alliance/horse"] = {
	["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Tyhle koně si koupí kterákoli rasa Aliance, ale k jízdě je potřeba i {spell:824}, kterou s {skill:762} dostanou jen Lidé. {npc:4732} ji naučí ostatní rasy, jakmile jsou Exalted s {faction:72} (cestu ukáže návod Stormwind Reputation). Do té doby této postavě koně nekupuj.",
	["Horse"] = "Kůň",
	["Pick a colour"] = "Vyber barvu",
	["{item:2414}, 20g"] = "{item:2414}, 20g",
	["{item:5655}, 20g"] = "{item:5655}, 20g",
	["{item:5656}, 20g"] = "{item:5656}, 20g",
	["{npc:384} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} prodává ostatní barvy (ve klientu Forever po 20g). Kup si, kterou chceš, nebo žádnou, pokud se ti líbí mount, který jsi dostal.",
	["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 40 {npc:4732} teaches {skill:762} to Humans for 100g (10% less at Honored with {faction:72}), and it comes with a horse. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4732} a koňská ohrada {npc:384} jsou v {area:88} ve východním {zone:1429}. Na levelu 40 učí {npc:4732} lidi {skill:762} za 100g (o 10 % méně na Honored u {faction:72}) a dostaneš k tomu koně. Ostatní rasy se {skill:762} i se svým prvním mountem učí u trenéra jízdy své vlastní rasy.",
	["{npc:4732}, riding trainer"] = "{npc:4732}, trenér jízdy",
	["{npc:5404} in {area:150}"] = "{npc:5404} v {area:150}",
	["{spell:824} for other races"] = "{spell:824} pro ostatní rasy",
}
t.guides["forever/collectibles/mounts/alliance/mechanostrider"] = {
	["Any Alliance race can buy these mechanostriders, but riding one also takes {spell:10907}, which only Gnomes get with {skill:762}. {npc:7954} teaches it to other races once they are Exalted with {faction:54} (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character."] = "Tyhle mechanostridery si koupí kterákoli rasa Aliance, ale k jízdě je potřeba i {spell:10907}, kterou s {skill:762} dostanou jen Gnómové. {npc:7954} ji naučí ostatní rasy, jakmile jsou Exalted s {faction:54} (cestu ukáže návod Gnomeregan Exiles Reputation). Do té doby této postavě mechanostridera nekupuj.",
	["In Classic only Dwarves and Gnomes could ride mechanostriders; in Forever every Alliance race can learn {spell:10907}."] = "V Classicu mohli na mechanostriderech jezdit jen trpaslíci a gnómové; na Forever se {spell:10907} může naučit každá rasa Aliance.",
	["Mechanostrider"] = "Mechanostrider",
	["Pick a colour"] = "Vyber barvu",
	["{area:189} is just east of {area:131}; {npc:7954} stands beside {npc:7955}'s mechanostriders. At 40 {npc:7954} teaches {skill:762} to Gnomes for 100g (10% less at Honored with {faction:54}), and it comes with a mechanostrider. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:189} je kousek východně od {area:131}; {npc:7954} stojí vedle mechanostriderů {npc:7955}. Na levelu 40 učí {npc:7954} gnomy {skill:762} za 100g (o 10 % levněji na Honored u {faction:54}) a k tomu dostaneš mechanostridera. Ostatní rasy se {skill:762} učí, i se svým prvním mountem, u jezdeckého trenéra své rasy.",
	["{item:13321}, 20g"] = "{item:13321}, 20g",
	["{item:13322}, 20g"] = "{item:13322}, 20g",
	["{item:8563}, 20g"] = "{item:8563}, 20g",
	["{item:8595}, 20g"] = "{item:8595}, 20g",
	["{npc:7954}, riding trainer"] = "{npc:7954}, trenér jízdy",
	["{npc:7955} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:7955} prodává ostatní barvy (ve klientu Forever po 20g). Kup si, kterou chceš, nebo žádnou, pokud se ti líbí mount, který jsi dostal.",
	["{spell:10907} for other races"] = "{spell:10907} pro ostatní rasy",
}
t.guides["forever/collectibles/mounts/alliance/pack-kodo"] = {
	["6,000 Merchant's Favor"] = "6 000 Merchant's Favor",
	["The reins need level 60 and Journeyman Riding to ride (Forever client); you can buy them earlier."] = "Otěže potřebují k jízdě level 60 a Journeyman Riding (klient Forever); koupit je můžeš dřív.",
	["{faction:2586} camp"] = "Tábor {faction:2586}",
}
t.guides["forever/collectibles/mounts/alliance/paladin-charger"] = {
	["An {item:12800} comes from Thorium veins and obsidian, about one vein in a hundred; a {item:18335} drops rarely from elites of level 59 and up (Revanchion and {npc:14695} about one kill in nine and one in a hundred). The Auction House is the usual source of both."] = "{item:12800} pochází z Thorium žil a obsidiánu, zhruba jedna žíla ze sta; {item:18335} vzácně padá z elitů levelu 59 a výš (Revanchion a {npc:14695} zhruba jedno zabití z devíti a jedno ze sta). Obojí se obvykle kupuje v aukci.",
	["Arcanite Bars x6: an alchemist, or the Trade District Auction House"] = "Arcanite Bars x6: alchymista, nebo aukce v Trade District",
	["At 60 {npc:5149} in the {object:32362} sends you to {quest:7670} in {zone:1453}'s Cathedral of Light."] = "Na 60 tě {npc:5149} v {object:32362} pošle k {quest:7670} do Cathedral of Light v {zone:1453}.",
	["Back to Lord Grayson"] = "Zpět k lordu Graysonovi",
	["Bring the materials and 150 gold, taken at the hand-in. {npc:1416} walks to his forge and hands you the {item:18753}."] = "Přines materiály a 150 zlatých, které se strhnou při odevzdání. {npc:1416} dojde ke své výhni a dá ti {item:18753}.",
	["Dire Maul West's door"] = "Dveře Dire Maul West",
	["Enriched Manna Biscuits"] = "Enriched Manna Biscuits",
	["Enriched Manna Biscuits: {npc:10857}, {area:3197}"] = "Enriched Manna Biscuits: {npc:10857}, {area:3197}",
	["Lord Grayson blesses the censer into the {item:18752} for {area:2627}."] = "Lord Grayson posvětí kadidelnici na {item:18752} pro {area:2627}.",
	["Lord Grayson hands you {item:18804}: open it for the {item:18746} and the {item:18792}. Keep both."] = "Lord Grayson ti dá {item:18804}: otevři ho a dostaneš {item:18746} a {item:18792}. Nech si obojí.",
	["Lord Grayson keeps the barding for now: you get it back with the next quest."] = "Lord Grayson si zatím nechá čabraku: dostaneš ji zpátky s dalším questem.",
	["Lord Grayson takes the censer back."] = "Lord Grayson si vezme kadidelnici zpátky.",
	["Paladin Charger"] = "Paladin Charger",
	["Stratholme Supply Crates, inside"] = "Stratholme Supply Crates, uvnitř",
	["Terrordale Spirits x25"] = "Terrordale Spirits x25",
	["Two diamonds"] = "Dva diamanty",
	["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; the door needs the {item:13704} (The Key to {area:2057}). Clear the {object:179746}, Rattlegore's room in the basement, then use the {item:18746} at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with {spell:1105}, Justice, Righteousness and then Light, which stuns them. {npc:14516} (level 62 elite) comes after the last; he mind-controls players. Loot the {item:18749}, use it inside the Ossuary to redeem it, and give it and the {item:18792} to {npc:14568}. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the {object:179746}, after the mount, lets you fight him again."] = "{area:2057} leží pod {area:2298}, ostrovním městem na jihovýchodě {zone:1422}; dveře potřebují {item:13704} (The Key to {area:2057}). Vyčisti {object:179746}, Rattlegoreovu místnost ve sklepě, a pak použij {item:18746} v jejím středu. Přijdou čtyři vlny duchů, každá zakončená Aspectem: hráči je soudí kouzly {spell:1105}, Justice, Righteousness a nakonec Light, který je omráčí. {npc:14516} (level 62, elite) přijde po poslední; ovládá mysl hráčů. Vezmi {item:18749}, použij ji uvnitř Ossuary, abys ji vykoupil, a dej ji spolu s {item:18792} {npc:14568}. Když skupina wipne, brány se zamknou a věštec zmizí: quest zruš a vezmi znovu od Lorda Graysona kvůli nové brašně. Skupina pěti na levelu 60. Again Into the {object:179746}, po mountovi, ti dovolí bojovat s ním znovu.",
	["{area:2279} is a dungeon for a group of five at 58-60, at the north end of the {zone:1423}. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key."] = "{area:2279} je dungeon pro skupinu pěti na level 58–60, na severním konci {zone:1423}. Stratholme Supply Crates podél ulic obou polovin obsahují Holy Water, po jedné až třech; vrátí se po třech minutách. Některé bedny vypustí hejno nakažených krys nebo červů: buď připravený. Hlavní brána (scarletská polovina) klíč nepotřebuje.",
	["{area:2577} lies in central {zone:1444}. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a {item:18249} (from Pusillin in Dire Maul East) or a rogue's lockpicking. {npc:11489} (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every {npc:11459} still alive in the courtyard: kill them first. His death frees the {quest:7643}: talk to it to give it the horse feed and the {item:18753}, and it blesses the barding. A group of five at 60."] = "{area:2577} leží uprostřed {zone:1444}. Od brány u paty ruin jdi nahoru přes vnější nádvoří ke dveřím západního křídla na jejich severním konci; potřebují {item:18249} (od Pusillina v Dire Maul East) nebo páčení zámků rogua. {npc:11489} (level 60, elite) stojí na vzdáleném konci prvního nádvoří západního křídla. Jakmile ho napadneš, přivolá každého {npc:11459}, který je na nádvoří ještě naživu: zabij je první. Jeho smrt osvobodí {quest:7643}: promluv s ním, dej mu krmivo pro koně a {item:18753} a on požehná koňské brnění. Skupina pěti na levelu 60.",
	["{area:2627} lies in the far north-west of the {zone:1423}, west of the {area:2279} gates. Stand inside a green glowing patch on the ground (a {object:179747}; some are inside the ruined houses) and use the {item:18752}: up to three Terrordale Spirits (level 59-60) rise and attack. Their {spell:7713} lowers all your stats by 30%: fight them one at a time and use {spell:2878}. The patches come back quickly; several paladins can work side by side."] = "{area:2627} leží na dalekém severozápadě {zone:1423}, západně od bran {area:2279}. Stoupni si do zeleně zářící skvrny na zemi ({object:179747}; některé jsou uvnitř zřícených domů) a použij {item:18752}: povstanou až tři Terrordale Spirits (level 59–60) a zaútočí. Jejich {spell:7713} ti sníží všechny staty o 30 %: bojuj s nimi po jednom a použij {spell:2878}. Skvrny se rychle vracejí; víc paladinů může pracovat vedle sebe.",
	["{item:14047} drops from humanoids of level 50 and up ({area:2255}'s Bruisers, the Scarlet Crusade in the Plaguelands, the {area:2577} ogres). {item:8836} is a Plaguelands herb ({skill:182} 220), common around {area:3197}. An {item:12360} is an alchemist's transmute from a {item:12359} and an {item:12363}, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three."] = "{item:14047} dropuje z humanoidů od levelu 50 (Bruisers v {area:2255}, Scarlet Crusade v Plaguelands, ogři v {area:2577}). {item:8836} je bylina z Plaguelands ({skill:182} 220), běžná kolem {area:3197}. {item:12360} je alchymistická transmutace z {item:12359} a {item:12363}, jednou za dva dny na alchymistu: požádej guildovního alchymistu včas, nebo kup pruty. Všechny tři prodává aukce.",
	["{item:14047} x40"] = "{item:14047} x40",
	["{npc:11406}, the priest trainer, walks about the {object:32386} in {zone:1455}'s {object:32362}. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer."] = "{npc:11406}, trenér kněží, se prochází po {object:32386} v {object:32362} v {zone:1455}. Svou kadidelnici ti dá za dar 150 zlatých, který se strhne při odevzdání. Kadidelnici si nech.",
	["{npc:11406}: 150 gold"] = "{npc:11406}: 150 zlatých",
	["{npc:11489}, inside the West wing"] = "{npc:11489}, uvnitř West wing",
	["{npc:1416} works in {zone:1453}'s {object:28027}. He forges the {item:18753} from your materials and 150 gold."] = "{npc:1416} pracuje v {object:28027} v {zone:1453}. Vykove {item:18753} z tvých materiálů a za 150 zlatých.",
	["{npc:1416}'s materials"] = "Materiály pro {npc:1416}",
	["{npc:1416}: 150 gold"] = "{npc:1416}: 150 zlatých",
	["{npc:928}: the {item:18753}"] = "{npc:928}: {item:18753}",
	["{object:2160} quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the {object:92525} is Friendly with you: {npc:10857} at {area:3197} or {npc:11536} at {area:2268}. Scourgestones and the Plaguelands quests raise the standing."] = "Quartermasteři {object:2160} prodávají Enriched Manna Biscuits, pět za 60 silver, jakmile je u tebe {object:92525} na Friendly: {npc:10857} v {area:3197} nebo {npc:11536} v {area:2268}. Postavení zvedají Scourgestones a questy v Plaguelands.",
}
t.guides["forever/collectibles/mounts/alliance/paladin-warhorse"] = {
	["At 40 {npc:6179}, upstairs in the {object:32386}, sends you to {npc:6171} in {zone:1453} ({npc:5149} downstairs gives the same errand; take one). Take the {area:2257} to {zone:1453}."] = "Na 40 tě {npc:6179}, nahoře v {object:32386}, pošle k {npc:6171} v {zone:1453} ({npc:5149} dole dá stejnou pochůzku; vezmi jednu). Vezmi {area:2257} do {zone:1453}.",
	["Paladin Warhorse"] = "Paladin Warhorse",
}
t.guides["forever/collectibles/mounts/alliance/ram"] = {
	["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "Tyhle berany si koupí kterákoli rasa Aliance, ale k jízdě je potřeba i {spell:826}, kterou s {skill:762} dostanou jen Trpaslíci. {npc:4772} ji naučí ostatní rasy, jakmile jsou Exalted s {faction:47} (cestu ukáže návod Ironforge Reputation). Do té doby této postavě berana nekupuj.",
	["Pick a colour"] = "Vyber barvu",
	["Ram"] = "Beran",
	["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 40 {npc:4772} teaches {skill:762} to Dwarves for 100g (10% less at Honored with {faction:47}), and it comes with a ram. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:803} je východně od {area:131} na silnici do {zone:1432}; {npc:4772} stojí vedle beranů {npc:1261}. Na levelu 40 učí {npc:4772} trpaslíky {skill:762} za 100g (o 10 % levněji na Honored u {faction:47}) a k tomu dostaneš berana. Ostatní rasy se {skill:762}, i se svým prvním mountem, učí u jezdeckého trenéra své rasy.",
	["{item:5864}, 20g"] = "{item:5864}, 20g",
	["{item:5872}, 20g"] = "{item:5872}, 20g",
	["{item:5873}, 20g"] = "{item:5873}, 20g",
	["{npc:1261} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:1261} prodává ostatní barvy (ve klientu Forever po 20g). Kup si, kterou chceš, nebo žádnou, pokud se ti líbí mount, který jsi dostal.",
	["{npc:4772}, riding trainer"] = "{npc:4772}, trenér jízdy",
	["{spell:826} for other races"] = "{spell:826} pro ostatní rasy",
}
t.guides["forever/collectibles/mounts/alliance/saber"] = {
	["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "Tyhle šavlozubé kočky si koupí kterákoli rasa Aliance, ale k jízdě je potřeba i {spell:828}, kterou s {skill:762} dostanou jen Noční elfové. {npc:4753} ji naučí ostatní rasy, jakmile jsou Exalted s {faction:69} (cestu ukáže návod Darnassus Reputation). Do té doby této postavě kočku nekupuj.",
	["Pick a colour"] = "Vyber barvu",
	["{item:8629}, 20g"] = "{item:8629}, 20g",
	["{item:8631}, 20g"] = "{item:8631}, 20g",
	["{item:8632}, 20g"] = "{item:8632}, 20g",
	["{npc:4730} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:4730} prodává ostatní barvy (ve klientu Forever po 20g). Kup si, kterou chceš, nebo žádnou, pokud se ti líbí mount, který jsi dostal.",
	["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 40 {npc:4753} teaches {skill:762} to Night Elves for 100g (10% less at Honored with {faction:69}), and it comes with a saber. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4753} a šavlozubci {npc:4730} jsou na jezdeckém cvičišti {area:1658} v {faction:69}. Na levelu 40 učí {npc:4753} noční elfy {skill:762} za 100g (o 10 % méně na Honored u {faction:69}) a dostaneš k tomu šavlozubce. Ostatní rasy se {skill:762} i se svým prvním mountem učí u trenéra jízdy své vlastní rasy.",
	["{npc:4753}, riding trainer"] = "{npc:4753}, trenér jízdy",
	["{spell:828} for other races"] = "{spell:828} pro ostatní rasy",
}
t.guides["forever/collectibles/mounts/alliance/stormpike-battle-charger"] = {
	["The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman {skill:762}; any Alliance race can ride it."] = "Klient Forever ho uvádí za 200g a na level 60. Běží plnou rychlostí, takže jízda na něm vyžaduje Journeyman {skill:762}; jezdit na něm může kterákoli rasa Aliance.",
	["{area:2839} (level 51+) raises {faction:730}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13217} waits outside the battleground on the {zone:1416} border above {area:287}; {npc:13216} inside {area:2839} sells the same mount."] = "{area:2839} (level 51+) zvedá {faction:730}: vyhrávej, obsazuj věže a hřbitovy a odevzdávej questy battlegroundu; nejrychlejší cestu ukazuje návod Alterac Valley Reputation. {npc:13217} čeká mimo battleground na hranici {zone:1416} nad {area:287}; {npc:13216} uvnitř {area:2839} prodává stejný mount.",
	["{npc:13217}, 200g"] = "{npc:13217}, 200g",
}
t.guides["forever/collectibles/mounts/alliance/swift-horse"] = {
	["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Tyhle koně si koupí kterákoli rasa Aliance, ale k jízdě je potřeba i {spell:824}, kterou s {skill:762} dostanou jen Lidé. {npc:4732} ji naučí ostatní rasy, jakmile jsou Exalted s {faction:72} (cestu ukáže návod Stormwind Reputation). Do té doby této postavě koně nekupuj.",
	["Journeyman {skill:762}"] = "Journeyman {skill:762}",
	["Pick a colour"] = "Vyber barvu",
	["Swift Horse"] = "Swift Horse",
	["{item:18776}, 200g"] = "{item:18776}, 200g",
	["{item:18777}, 200g"] = "{item:18777}, 200g",
	["{item:18778}, 200g"] = "{item:18778}, 200g",
	["{npc:384} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} prodává ostatní barvy (ve klientu Forever po 200g). Kup si, kterou chceš, nebo žádnou, pokud se ti líbí mount, který jsi dostal.",
	["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 60 {npc:4732} teaches Journeyman {skill:762} to Humans for 1,000g (10% less at Honored with {faction:72}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift horse costs 200g here."] = "{npc:4732} a koňská ohrada {npc:384} jsou v {area:88} ve východním {zone:1429}. Na levelu 60 učí {npc:4732} lidi Journeyman {skill:762} za 1 000g (o 10 % méně na Honored u {faction:72}); podle Blizzardu k tomu dostaneš mount. Ostatní rasy to trénují u trenéra jízdy své vlastní rasy. Každý swift kůň tu stojí 200g.",
	["{npc:4732}, riding trainer"] = "{npc:4732}, trenér jízdy",
	["{spell:824} for other races"] = "{spell:824} pro ostatní rasy",
}
t.guides["forever/collectibles/mounts/alliance/swift-mechanostrider"] = {
	["Any Alliance race can buy these mechanostriders, but riding one also takes {spell:10907}, which only Gnomes get with {skill:762}. {npc:7954} teaches it to other races once they are Exalted with {faction:54} (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character."] = "Tyhle mechanostridery si koupí kterákoli rasa Aliance, ale k jízdě je potřeba i {spell:10907}, kterou s {skill:762} dostanou jen Gnómové. {npc:7954} ji naučí ostatní rasy, jakmile jsou Exalted s {faction:54} (cestu ukáže návod Gnomeregan Exiles Reputation). Do té doby této postavě mechanostridera nekupuj.",
	["Journeyman {skill:762}"] = "Journeyman {skill:762}",
	["Pick a colour"] = "Vyber barvu",
	["Swift Mechanostrider"] = "Swift Mechanostrider",
	["{area:189} is just east of {area:131}; {npc:7954} stands beside {npc:7955}'s mechanostriders. At 60 {npc:7954} teaches Journeyman {skill:762} to Gnomes for 1,000g (10% less at Honored with {faction:54}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift mechanostrider costs 200g here."] = "{area:189} je kousek východně od {area:131}; {npc:7954} stojí vedle mechanostriderů {npc:7955}. Na levelu 60 učí {npc:7954} gnomy Journeyman {skill:762} za 1 000g (o 10 % levněji na Honored u {faction:54}); podle Blizzardu je k tomu mount. Ostatní rasy se to učí u jezdeckého trenéra své rasy. Každý rychlý mechanostrider tu stojí 200g.",
	["{item:18772}, 200g"] = "{item:18772}, 200g",
	["{item:18773}, 200g"] = "{item:18773}, 200g",
	["{item:18774}, 200g"] = "{item:18774}, 200g",
