t.guides["forever/collectibles/mounts/alliance/swift-ram"] = {
	["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "Tyhle berany si koupí kterákoli rasa Aliance, ale k jízdě je potřeba i {spell:826}, kterou s {skill:762} dostanou jen Trpaslíci. {npc:4772} ji naučí ostatní rasy, jakmile jsou Exalted s {faction:47} (cestu ukáže návod Ironforge Reputation). Do té doby této postavě berana nekupuj.",
	["Journeyman {skill:762}"] = "Journeyman {skill:762}",
	["Pick a colour"] = "Vyber barvu",
	["Swift Ram"] = "Swift Ram",
	["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 60 {npc:4772} teaches Journeyman {skill:762} to Dwarves for 1,000g (10% less at Honored with {faction:47}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift ram costs 200g here."] = "{area:803} je východně od {area:131} na silnici do {zone:1432}; {npc:4772} stojí vedle beranů {npc:1261}. Na levelu 60 učí {npc:4772} trpaslíky Journeyman {skill:762} za 1 000g (o 10 % levněji na Honored u {faction:47}); podle Blizzardu je k tomu mount. Ostatní rasy se to učí u jezdeckého trenéra své rasy. Každý rychlý beran tu stojí 200g.",
	["{item:18785}, 200g"] = "{item:18785}, 200g",
	["{item:18786}, 200g"] = "{item:18786}, 200g",
	["{item:18787}, 200g"] = "{item:18787}, 200g",
	["{npc:1261} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:1261} prodává ostatní barvy (ve klientu Forever po 200g). Kup si, kterou chceš, nebo žádnou, pokud se ti líbí mount, který jsi dostal.",
	["{npc:4772}, riding trainer"] = "{npc:4772}, trenér jízdy",
	["{spell:826} for other races"] = "{spell:826} pro ostatní rasy",
}
t.guides["forever/collectibles/mounts/alliance/swift-saber"] = {
	["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "Tyhle šavlozubé kočky si koupí kterákoli rasa Aliance, ale k jízdě je potřeba i {spell:828}, kterou s {skill:762} dostanou jen Noční elfové. {npc:4753} ji naučí ostatní rasy, jakmile jsou Exalted s {faction:69} (cestu ukáže návod Darnassus Reputation). Do té doby této postavě kočku nekupuj.",
	["Journeyman {skill:762}"] = "Journeyman {skill:762}",
	["Pick a colour"] = "Vyber barvu",
	["Swift Saber"] = "Swift Saber",
	["{item:18766}, 200g"] = "{item:18766}, 200g",
	["{item:18767}, 200g"] = "{item:18767}, 200g",
	["{item:18902}, 200g"] = "{item:18902}, 200g",
	["{npc:4730} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:4730} prodává ostatní barvy (ve klientu Forever po 200g). Kup si, kterou chceš, nebo žádnou, pokud se ti líbí mount, který jsi dostal.",
	["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 60 {npc:4753} teaches Journeyman {skill:762} to Night Elves for 1,000g (10% less at Honored with {faction:69}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift saber costs 200g here."] = "{npc:4753} a šavlozubci {npc:4730} jsou na jezdeckém cvičišti {area:1658} v {faction:69}. Na levelu 60 učí {npc:4753} noční elfy Journeyman {skill:762} za 1 000g (o 10 % méně na Honored u {faction:69}); podle Blizzardu k tomu dostaneš mount. Ostatní rasy to trénují u trenéra jízdy své vlastní rasy. Každý swift šavlozubec tu stojí 200g.",
	["{npc:4753}, riding trainer"] = "{npc:4753}, trenér jízdy",
