t.guides["forever/collectibles/pets/excitable-slime"] = {
	["Buy {item:278265} from {npc:4612} in the {zone:1458} canals first (25 copper for a stack of 5): you hand it in as soon as the slime offers its quest."] = "Nejdřív kup {item:278265} od {npc:4612} v kanálech {zone:1458} (25 měďáků za balík 5): odevzdáš ho, jakmile sliz nabídne svůj quest.",
	["Find an {npc:269452}, a little critter in the canal water beside {npc:4612}, target it and /dance at it, again and again, until it dances back and offers {quest:97583}; this takes many tries. Hand in the sludge right away. If the slime seems tired, /dance with it again before you hand in."] = "Najdi {npc:269452}, malého tvorečka ve vodě kanálu vedle {npc:4612}, zaměř ho a /dance na něj znovu a znovu, dokud ti tanec neoplatí a nenabídne {quest:97583}; chce to hodně pokusů. Sliz hned odevzdej. Pokud se sliz zdá unavený, zatancuj si s ním /dance znovu, než ho odevzdáš.",
}
t.guides["forever/collectibles/pets/flik"] = {
	["Darkmoon Faire Frogs"] = "Darkmoon Faire Frogs",
	["{item:11026}, 1g"] = "{item:11026}, 1g",
	["{item:11027}, 1g"] = "{item:11027}, 1g",
	["{npc:14860} at the Darkmoon Faire"] = "{npc:14860} na Darkmoon Faire",
	["{npc:14860} sells two frogs (1g each) while the Darkmoon Faire is in town; Forever has not shown the Faire yet. In Classic it sets up south of {area:87} in {zone:1429} one month and near {zone:1456} in {zone:1412} the next; go to whichever is up. {npc:14860} runs all over the Faire grounds, so look around for him. He carries only one {item:11027} at a time and restocks it about every 30 minutes: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:14860} prodává dvě žáby (každou za 1 zlatý), dokud je ve městě Darkmoon Faire; Forever Faire zatím neukázal. V Classicu se jeden měsíc staví jižně od {area:87} v {zone:1429} a další měsíc u {zone:1456} v {zone:1412}; jdi na ten, který zrovna stojí. {npc:14860} pobíhá po celém areálu Faire, tak se po něm rozhlédni. Nosí vždy jen jeden {item:11027} a doplňuje ho zhruba každých 30 minut: když žádný nemá, někdo ho právě koupil. Každý pet předmět tě po použití naučí svého společníka; cíle pak zůstanou odškrtnuté.",
}
t.guides["forever/collectibles/pets/green-wing-macaw"] = {
	["Defias Pirates, on the ship"] = "Defias Pirates, na lodi",
	["{area:1581} portal, at the bottom of the mine"] = "Portál do {area:1581}, na dně dolu",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}, v dole {area:20}",
	["{area:1581}: Defias Pirates"] = "{area:1581}: Defias Pirates",
}
t.guides["forever/collectibles/pets/halpa"] = {
	["50s"] = "50s",
	["{item:10394}, 50s"] = "{item:10394}, 50s",
	["{npc:8401} sells three whistles in {zone:1456} (50s each, 1g 50s for all three); the two ground squirrels are new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:8401} prodává ve {zone:1456} tři píšťalky (50s za kus, 1g 50s za všechny tři); dva sysli jsou ve Forever noví. Každý pet předmět tě po použití naučí svého společníka; cíle zůstanou odškrtnuté.",
	["{npc:8401}'s Prairie Dogs"] = "{npc:8401}'s Prairie Dogs",
}
t.guides["forever/collectibles/pets/hyacinth-macaw"] = {
	["Bloodsail camp, the {area:43}"] = "Tábor Bloodsail, {area:43}",
	["Bloodsail pirates"] = "Piráti Bloodsail",
	["Every Bloodsail pirate on the Stranglethorn coast (level 39-45) can drop it, but only about once in 5,000 kills; the Swabbies on the ships off the southern tip, about once in 2,500. That is a grind of many hours, so most players kill pirates while doing something else there, or buy the cage on the Auction House. The waypoint is the Swashbucklers' and Warlocks' camp on the {area:43}, south of {area:35}. Every pirate kill also lowers your Bloodsail Buccaneers standing."] = "Může ho dropnout každý pirát Bloodsail na pobřeží Stranglethornu (level 39–45), ale jen zhruba jednou za 5 000 zabití; Swabbies na lodích u jižního cípu zhruba jednou za 2 500. To je grind na mnoho hodin, takže většina hráčů zabíjí piráty, zatímco tam dělá něco jiného, nebo klec koupí v aukci. Bod trasy je tábor Swashbucklers a Warlocks na {area:43}, jižně od {area:35}. Každé zabití piráta navíc sníží reputaci u Bloodsail Buccaneers.",
}
t.guides["forever/collectibles/pets/jeremiah-payson"] = {
	["50s"] = "50s",
	["{item:10393}, 50s"] = "{item:10393}, 50s",
	["{npc:8403} sells three cockroaches in the {zone:1458} (50s each, 1g 50s for all three); the Plagued and Undercity Cockroaches are new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:8403} prodává v {zone:1458} tři švábi (50s za kus, 1g 50s za všechny tři); Plagued a Undercity Cockroach jsou ve Forever noví. Každý pet předmět tě po použití naučí svého společníka; cíle zůstanou odškrtnuté.",
	["{npc:8403}'s Cockroaches"] = "{npc:8403}'s Cockroaches",
}
t.guides["forever/collectibles/pets/lil-timmy"] = {
	["Horde players buy the {npc:7386} (60s) from {npc:262471}, a trader new in Forever, at {area:2539}, the Darkspear camp at the southern tip of {zone:1442}, on the way up from the {zone:1413}. He keeps one kitten at a time: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goal stays ticked afterwards."] = "Hráči Hordy kupují {npc:7386} (60s) od {npc:262471}, obchodníka nového na Forever, v {area:2539}, táboře Darkspear na jižním cípu {zone:1442}, cestou nahoru ze {zone:1413}. Má vždy jen jedno kotě: když žádné nemá, někdo ho právě koupil. Každý předmět s petem tě po použití naučí jeho společníka; cíl pak zůstane odškrtnutý.",
	["{item:8489}, 60s"] = "{item:8489}, 60s",
	["{npc:8666} sells the {npc:7386} (60s). He starts at {object:2098} and walks through the {object:2096}, {object:2100} and the {object:28027} before he vanishes near the square again; if he is not around, wait for him at {object:2098}. By beta reports he carries one kitten at a time: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goal stays ticked afterwards."] = "{npc:8666} prodává {npc:7386} (60s). Začíná u {object:2098} a prochází přes {object:2096}, {object:2100} a {object:28027}, než u náměstí zase zmizí; když tu není, počkej na něj u {object:2098}. Podle hlášení z bety nosí vždy jen jedno kotě: když žádné nemá, někdo ho právě koupil. Každý pet předmět tě po použití naučí svého společníka; cíl zůstane odškrtnutý.",
}
t.guides["forever/collectibles/pets/magus-tirth"] = {
	["{item:11023}, 1g"] = "{item:11023}, 1g",
}
t.guides["forever/collectibles/pets/mayhoa-skyhoof"] = {
	["60s"] = "60s",
	["{npc:268745}, the girl with puppies, walks a long loop through {zone:1454}: from the {object:172957} through the Drag to the {object:172958} and back. The waypoint is where she is seen most, on the road between the Drag and the {object:172958}; if she is not there, walk the loop. The carrier costs 60s. She carries one pup at a time: if she has none, another player just bought it, so come back later. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:268745}, dívka se štěňaty, chodí po dlouhém okruhu přes {zone:1454}: od {object:172957} přes Drag k {object:172958} a zpět. Bod trasy je tam, kde ji vidíš nejčastěji, na cestě mezi Dragem a {object:172958}; když tam není, projdi okruh. Přepravka stojí 60s. Nosí vždy jen jedno štěně: když žádné nemá, jiný hráč ho právě koupil, tak se vrať později. Každý pet item naučí svého společníka, když ho použiješ; cíle pak zůstanou odškrtnuté.",
}
t.guides["forever/collectibles/pets/mechanical-chicken"] = {
	["Each robot starts with a distress beacon that mobs in its zone drop, about one kill in 40 to 100 in Classic's data. In {zone:1444} the best are the Coast Crawl Snapclaws and Deepseers (levels 43-45) on the {area:1108} and the Sprite Dragons (47-48), about 2.5%; ogres, harpies, naga and Grimtotems drop it about 1%. You can loot it from level 40."] = "Každý robot začíná nouzovým majákem, který dropují mobové v jeho zóně, podle dat Classicu zhruba jedno zabití ze 40 až 100. V {zone:1444} jsou nejlepší Coast Crawl Snapclaws a Deepseers (level 43–45) na {area:1108} a Sprite Dragons (47–48), asi 2,5 %; zlobři, harpyje, nagy a Grimtotemové ho dropují asi z 1 %. Lootnout ho můžeš od levelu 40.",
	["Escort OOX-09/HL"] = "Eskortuj OOX-09/HL",
	["Escort OOX-17/TN"] = "Eskortuj OOX-17/TN",
	["Escort OOX-22/FE"] = "Eskortuj OOX-22/FE",
	["Most {zone:1425} mobs drop OOX-09/HL's beacon about once in 100 kills: Silvermane wolves, owlbeasts, Highvale elves, Witherbark and Vilebranch trolls. You can loot it from level 43."] = "Většina mobů v {zone:1425} dropne maják OOX-09/HL zhruba jednou za 100 zabití: vlci Silvermane, owlbeasti, elfové Highvale, trollové Witherbark a Vilebranch. Lootnout ho můžeš od levelu 43.",
	["Rescue OOX-09/HL"] = "Zachraň OOX-09/HL",
	["Rescue OOX-17/TN"] = "Zachraň OOX-17/TN",
	["Rescue OOX-22/FE"] = "Zachraň OOX-22/FE",
	["{item:8623} in {zone:1446}"] = "{item:8623} v {zone:1446}",
	["{item:8705} in {zone:1444}"] = "{item:8705} v {zone:1444}",
	["{npc:7406} in {area:35}"] = "{npc:7406} v {area:35}",
}
t.guides["forever/collectibles/pets/minimule"] = {
	["1,500 Merchant's Favor"] = "1 500 Merchant's Favor",
	["Azeroth Commerce Authority"] = "Azeroth Commerce Authority",
	["Durotar Supply and Logistics"] = "Durotar Supply and Logistics",
	["Minimule"] = "Minimule",
	["The Alliance camp is at {area:1002} in western {zone:1433}. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to {npc:214101}, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with the Azeroth Commerce Authority. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there."] = "Alianční tábor je v {area:1002} v západní {zone:1433}. Merchant's Favor je z Waylaid Crates, které moby dropují od levelu 10: naplň jednu balíkem, který uvádí, a odevzdej ji {npc:214101}, za 5 až 30 Favor za bednu. Pamlsek stojí 1 500 Favor a podle seznamů obchodníků z bety vyžaduje Revered u Azeroth Commerce Authority. Bedny reputaci nedávají: ta jde z Craftsman's Writs, 21 000 od Neutral po Revered. Dovede tě tam návod Reputace u zásobovacích frakcí.",
	["The Horde camp is just outside the west gate of the Crossroads. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to Dokimi, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with Durotar Supply and Logistics. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there. (Another {npc:256384} stands in the {zone:1458}; this is the one at the camp.)"] = "Hordský tábor je kousek za západní branou Crossroads. Merchant's Favor je z Waylaid Crates, které moby dropují od levelu 10: naplň jednu balíkem, který uvádí, a odevzdej ji Dokimi, za 5 až 30 Favor za bednu. Pamlsek stojí 1 500 Favor a podle seznamů obchodníků z bety vyžaduje Revered u Durotar Supply and Logistics. Bedny reputaci nedávají: ta jde z Craftsman's Writs, 21 000 od Neutral po Revered. Dovede tě tam návod Reputace u zásobovacích frakcí. (Další {npc:256384} stojí v {zone:1458}; tohle je ten v táboře.)",
}
t.guides["forever/collectibles/pets/musical-gustjumper"] = {
	["From {area:16635} follow the road south, then cut across the field to the top of the waterfall: five frogs sit together on a rock there, by a log. Mobs patrol nearby, so a level 1 character should watch its back. Stand by the rock, target a frog and type /sing. The frogs sing back, the group disappears and one frog hops onto the log beside you: click it to take the {item:268109}, then use it to learn the pet. The item is not bound until you use it, so a friend on the island can sing again and trade you one."] = "Z {area:16635} jdi po silnici na jih, pak přejdi přes pole na vrchol vodopádu: na kameni u kmene tam sedí pět žab pohromadě. Poblíž hlídkují moby, takže postava levelu 1 by si měla hlídat záda. Stoupni si ke kameni, zaměř žábu a napiš /sing. Žáby zazpívají zpátky, skupinka zmizí a jedna žába skočí na kmen vedle tebe: klikni na ni, vezmi {item:268109} a pak ho použij, aby ses naučil peta. Předmět není bindnutý, dokud ho nepoužiješ, takže kamarád na ostrově může zazpívat znovu a jeden ti předat.",
}
t.guides["forever/collectibles/pets/narkk"] = {
	["{item:8495}, 40s"] = "{item:8495}, 40s",
	["{item:8496}, 40s"] = "{item:8496}, 40s",
	["{npc:2663}'s Parrots"] = "Papoušci od {npc:2663}",
	["{npc:2663}, the pirate supplier in {area:35}, sells two parrots (40s each), with no stock limit. He stands next to {npc:2664}, the cook. {area:35} is neutral: the boat from {area:392} and the Stranglethorn road both arrive there. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:2663}, pirátský dodavatel v {area:35}, prodává dva papoušky (po 40s) bez omezení zásob. Stojí vedle kuchaře {npc:2664}. {area:35} je neutrální: přijíždí sem loď z {area:392} i silnice ze Stranglethornu. Každý pet item naučí svého společníka, když ho použiješ; cíle pak zůstanou odškrtnuté.",
}
t.guides["forever/collectibles/pets/shadowgale-squirrel"] = {
	["50s"] = "50s",
	["Revered with the {faction:2758}"] = "Revered u {faction:2758}",
}
t.guides["forever/collectibles/pets/shylenai"] = {
	["50s"] = "50s",
	["{item:8500}, 50s"] = "{item:8500}, 50s",
	["{item:8501}, 50s"] = "{item:8501}, 50s",
	["{npc:8665}'s Owls"] = "{npc:8665}'s Owls",
	["{npc:8665}, the owl trainer, stands on the {area:1659} in {zone:1457}, beside the food and general goods vendors. She sells three owls (50s each); the {item:280803} is new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:8665}, trenérka sov, stojí na {area:1659} v {zone:1457}, vedle obchodníků s jídlem a smíšeným zbožím. Prodává tři sovy (50s za kus); {item:280803} je ve Forever nová. Každý pet předmět tě po použití naučí svého společníka; cíle zůstanou odškrtnuté.",
}
t.guides["forever/collectibles/pets/siamese-cat"] = {
	["Cookie"] = "Cookie",
	["{area:1581} portal, inside the {area:20} mine"] = "Portál do {area:1581}, uvnitř dolu {area:20}",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}, v dole {area:20}",
	["{area:1581}: Cookie"] = "{area:1581}: Cookie",
}
t.guides["forever/collectibles/pets/smolderweb-carrier"] = {
	["Back to {npc:10260}"] = "Zpět do {npc:10260}",
	["Lower {area:1583}"] = "Lower {area:1583}",
	["Lower {area:1583} is a group of five, level 55-60, inside {area:254}. The Spire Spider Eggs lie around {npc:10596}'s nest in the Skitterweb Tunnels, the spider halls: click them until you have 15 (each gives one to three). Hard-hitting spiderlings can hatch as you loot. By player reports the eggs cannot be looted in a raid group, so keep the party at five or fewer."] = "Lower {area:1583} je pro skupinu pěti, level 55–60, uvnitř {area:254}. Spire Spider Eggs leží kolem hnízda {npc:10596} ve Skitterweb Tunnels, pavoučích síních: klikej na ně, dokud jich nemáš 15 (každé dá jedno až tři). Při lootování se můžou vylíhnout tvrdě bijící pavoučci. Podle hráčů vejce v raid skupině lootnout nejdou, takže drž partu na pěti a méně.",
}
t.guides["forever/collectibles/pets/spectral-bear-cub"] = {
	["Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, a crafting profession at 150, 225 and 300, PvP ranks and battleground reputations, exploring, dungeons and raids) is worth one, and the track counts points earned, not spent. It gives the {item:281060} at 15, the {item:277714} at 25, the {item:277717} at 40 and the {item:277718} at 55. The rewards are claimed as quests from {npc:6791} in the inn at {area:392}, the goblin port on the {zone:1413} coast (Alliance players come by the boat from {area:35}): with 25 points he offers {quest:96383}; hand it straight back for the cub."] = "Legacy Pointy jsou společné pro celý účet: každá Legacy Challenge (třída na levelu 25, 45 a 60, výrobní profese na 150, 225 a 300, PvP ranky a reputace z battlegroundů, průzkum, dungeony a raidy) má hodnotu jednoho bodu a track počítá získané body, ne utracené. Na 15 dává {item:281060}, na 25 {item:277714}, na 40 {item:277717} a na 55 {item:277718}. Odměny si vyzvedneš jako questy u {npc:6791} v hostinci v {area:392}, goblinním přístavu na pobřeží {zone:1413} (hráči Aliance připlují lodí z {area:35}): s 25 body ti nabídne {quest:96383}; hned ho odevzdej a dostaneš mládě.",
	["{npc:6791} in {area:392}"] = "{npc:6791} v {area:392}",
}
t.guides["forever/collectibles/pets/tiny-crimson-whelpling"] = {
	["The red whelps live in the hills of the eastern {zone:1437}, towards {area:1037}: about 50 of them, back about five minutes after a kill in Classic's data. Red Whelps (levels 23-24) and Crimson Whelps (25-26) drop the whelpling about once in 650 kills, the Flamesnorting Whelps (26-27) mixed in with them only once in 1,600, so expect a long farm. It can be traded, so the Auction House may be quicker."] = "Červení dráčci žijí v kopcích východní {zone:1437}, směrem k {area:1037}: asi 50 kusů, podle dat z Classicu zpátky zhruba pět minut po zabití. Red Whelps (level 23–24) a Crimson Whelps (25–26) dropnou dráčka zhruba jednou z 650 zabití, Flamesnorting Whelps (26–27) mezi nimi jen jednou z 1 600, takže počítej s dlouhým farmením. Dá se obchodovat, takže aukce může být rychlejší.",
}
t.guides["forever/collectibles/pets/tiny-emerald-whelpling"] = {
	["Dreaming Whelps"] = "Dreaming Whelps",
	["The Dreaming Whelps (levels 35-36) live in western {zone:1435}, near the {zone:1430} border. They drop it about once in 1,250 kills, and there are only a handful, back about every five minutes, so expect days of farming; it can be traded, so the Auction House may be quicker."] = "Dreaming Whelps (levely 35–36) žijí v západní {zone:1435}, u hranice s {zone:1430}. Dropne to zhruba jednou za 1 250 zabití a je jich jen pár, respawn asi každých pět minut, takže počítej s dny farmení; dá se to obchodovat, takže aukce může být rychlejší.",
}
t.guides["forever/collectibles/pets/weevil-k-neevil"] = {
	["Back to {npc:217412}"] = "Zpět do {npc:217412}",
	["Hand {npc:217412} the three specimens: she gives you {item:280456} and 35s."] = "Dej {npc:217412} tři vzorky: dá ti {item:280456} a 35s.",
	["The Arbor Tarantulas sit in northern Stranglethorn. Use the kit's tool on one to catch it."] = "Arbor Tarantulas sedí v severním Stranglethornu. Použij na jednu nástroj z kitu a chyť ji.",
	["The Flesh Pickers feed in the {area:596} in the middle of southern {zone:1443}. Use the kit's tool on one."] = "Flesh Pickers se krmí v {area:596} uprostřed jižní {zone:1443}. Použij na jednoho nástroj z kitu.",
	["The Hay Weevils crawl in the north-west of {zone:1417}. Use the kit's tool on one."] = "Hay Weevils lezou na severozápadě {zone:1417}. Použij na jednoho nástroj z kitu.",
	["{npc:217588} in {zone:1434}"] = "{npc:217588} v {zone:1434}",
	["{npc:217589} in {zone:1417}"] = "{npc:217589} v {zone:1417}",
	["{npc:217590} in {zone:1443}"] = "{npc:217590} v {zone:1443}",
}
t.guides["forever/collectibles/pets/worg-carrier"] = {
	["Back to {npc:10260}"] = "Zpět do {npc:10260}",
	["Lower {area:1583}"] = "Lower {area:1583}",
	["Lower {area:1583}: Halycon's pups"] = "Lower {area:1583}: Halyconova mláďata",
	["The pups are in Lower Blackrock Spire (a group of five, level 55-60), not Upper: they run with Halycon, the great worg, deep in the dungeon beyond {npc:10584}'s ogres. Use the cage on a living {npc:10221} before the pack is dead. Taking damage interrupts the cast, so let the tank hold the pups and cage one from the side. A rogue or druid can sneak in, cage a pup from a corner, then vanish."] = "Štěňata jsou v Lower Blackrock Spire (skupina pěti, level 55–60), ne v Upper: běhají s Halyconem, velkým worgem, hluboko v dungeonu za zlobry {npc:10584}. Použij klec na živého {npc:10221}, než smečka padne. Poškození přeruší sesílání, takže ať tank drží štěňata a ty jedno chyť z boku. Rogue nebo druid se může vplížit, chytit štěně z rohu a pak zmizet.",
}
t.guides["forever/collectibles/pets/xantish"] = {
	["50s"] = "50s",
	["{item:10360}, 50s"] = "{item:10360}, 50s",
	["{item:10361}, 50s"] = "{item:10361}, 50s",
	["{item:10392}, 50s"] = "{item:10392}, 50s",
	["{npc:8404}'s Snakes"] = "{npc:8404}'s Snakes",
	["{npc:8404}, the snake vendor, walks with his three snakes: from the {object:172961} north along the city's west side to the battleground emissaries and back. The waypoint is where his walk starts; if he is not there, follow the road north. He sells four snakes (50s each); the {item:280703} is new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:8404}, obchodník s hady, chodí se svými třemi hady: od {object:172961} na sever podél západní strany města k vyslancům bojišť a zpátky. Bod trasy je začátek jeho obchůzky; když tam není, jdi po cestě na sever. Prodává čtyři hady (50s za kus); {item:280703} je ve Forever nový. Každý pet předmět tě po použití naučí svého společníka; cíle zůstanou odškrtnuté.",
}
t.guides["forever/collectibles/pets/yarlyn-amberstill"] = {
	["20s"] = "20s",
	["{item:8497}, 20s"] = "{item:8497}, 20s",
	["{npc:1263} stands at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}, the ram breeder. Each rabbit crate costs 20s; the Arctic and Brown crates are new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:1263} stojí u {area:803}, východně od {area:131} na cestě do {zone:1432}, vedle {npc:1261}, chovatele beranů. Každá bedna s králíky stojí 20 stříbrných; bedny Arctic a Brown jsou ve Forever nové. Každý pet předmět tě po použití naučí svého společníka; cíle pak zůstanou odškrtnuté.",
	["{npc:1263}'s Rabbits"] = "Králíci {npc:1263}",
}
t.guides["forever/exploration/eastern-kingdoms-1-30"] = {
	["11 areas to discover here, levels 10-18."] = "Oblastí k objevení: 11, levely 10–18.",
	["11 areas to discover here, levels 15-24."] = "Oblastí k objevení: 11, levely 15–24.",
	["12 areas to discover here, levels 20-31."] = "Oblastí k objevení: 12, levely 20–31.",
	["12 areas to discover here, levels 5-10."] = "Oblastí k objevení: 12, levely 5–10.",
	["13 areas to discover here, levels 10-30."] = "Oblastí k objevení: 13, levely 10–30.",
	["14 areas to discover here, levels 9-18."] = "Oblastí k objevení: 14, levely 9–18.",
	["15 areas to discover here, levels 10-20."] = "Oblastí k objevení: 15, levely 10–20.",
	["15 areas to discover here, levels 20-30."] = "Oblastí k objevení: 15, levely 20–30.",
	["17 areas to discover here, levels 5-10."] = "Oblastí k objevení: 17, levely 5–10.",
	["18 areas to discover here, levels 4-12."] = "Oblastí k objevení: 18, levely 4–12.",
	["Alliance guards: touch the edge of {area:108} and move on"] = "Stráže Aliance: dotkni se okraje {area:108} a jdi dál",
	["Alliance guards: touch the edge of {area:131} and move on"] = "Stráže Aliance: dotkni se okraje {area:131} a jdi dál",
	["Alliance guards: touch the edge of {area:132} and move on; any one of these names counts"] = "Stráže Aliance: dotkni se okraje {area:132} a jdi dál; počítá se kterékoli z těchto jmen",
	["Alliance guards: touch the edge of {area:144} and move on"] = "Stráže Aliance: dotkni se okraje {area:144} a jdi dál",
	["Alliance guards: touch the edge of {area:150} and move on"] = "Stráže Aliance: dotkni se okraje {area:150} a jdi dál",
	["Alliance guards: touch the edge of {area:271} and move on"] = "Stráže Aliance: dotkni se okraje {area:271} a jdi dál",
	["Alliance guards: touch the edge of {area:42} and move on"] = "Stráže Aliance: dotkni se okraje {area:42} a jdi dál",
	["Alliance guards: touch the edge of {area:69} and move on"] = "Stráže Aliance: dotkni se okraje {area:69} a jdi dál",
	["Alliance guards: touch the edge of {area:809} and move on; any one of these names counts"] = "Stráže Aliance: dotkni se okraje {area:809} a jdi dál; počítá se kterékoli z těchto jmen",
	["Alliance guards: touch the edge of {area:87} and move on"] = "Stráže Aliance: dotkni se okraje {area:87} a jdi dál",
	["Alliance guards: touch the edge of {area:9} and move on"] = "Stráže Aliance: dotkni se okraje {area:9} a jdi dál",
	["Alliance guards: touch the edge of {zone:1453} and move on; any one of these names counts"] = "Stráže Aliance: dotkni se okraje {zone:1453} a jdi dál; počítá se kterékoli z těchto jmen",
	["At the south end of Silverpine the road turns east into {zone:1424} by {area:285}. {area:272} in the north-east is the Horde town; {area:271} is Alliance."] = "Na jižním konci Silverpine se cesta stáčí na východ do {zone:1424} u {area:285}. {area:272} na severovýchodě je město Hordy; {area:271} je Aliance.",
	["Discovering an area gives experience scaled to its level, so this runs alongside leveling. Alliance starts in {zone:1429}; dwarves and gnomes can begin at the {zone:1426} step. 12 areas to discover here, levels 5-10."] = "Objevení oblasti dá zkušenosti podle jejího levelu, takže tohle běží souběžně s levelováním. Aliance začíná v {zone:1429}; trpaslíci a gnómové můžou začít u kroku {zone:1426}. Tady je 12 oblastí k objevení, levely 5–10.",
	["Discovering an area gives experience scaled to its level, so this runs alongside leveling. Horde starts in {zone:1420}; orcs, trolls and tauren arrive by zeppelin from {zone:1454}. 17 areas to discover here, levels 5-10."] = "Objevení oblasti dá zkušenosti podle jejího levelu, takže tohle běží souběžně s levelováním. Horda začíná v {zone:1420}; orkové, trollové a taureni přilétají zeppelinem z {zone:1454}. Tady je 17 oblastí k objevení, levely 5–10.",
	["Exploration: {zone:1415} 1-30"] = "Průzkum: {zone:1415} 1–30",
	["Exploring the entire world map on one character is a Forever Legacy Challenge (1 account-wide Legacy Point)."] = "Prozkoumání celé mapy světa jednou postavou je Forever Legacy Challenge (1 Legacy Point pro celý účet).",
	["Flight path here: {area:108} (Thor)."] = "Letová trasa tady: {area:108} (Thor).",
	["Flight path here: {area:144} ({npc:1572})."] = "Letová trasa tady: {area:144} ({npc:1572}).",
	["Flight path here: {area:150} ({npc:1571})."] = "Letová trasa tady: {area:150} ({npc:1571}).",
	["Flight path here: {area:228} ({npc:2226})."] = "Letová trasa tady: {area:228} ({npc:2226}).",
	["Flight path here: {area:271} ({npc:2432})."] = "Letová trasa tady: {area:271} ({npc:2432}).",
	["Flight path here: {area:272} (Zarise)."] = "Letová trasa tady: {area:272} (Zarise).",
	["Flight path here: {area:42} ({npc:2409})."] = "Letová trasa tady: {area:42} ({npc:2409}).",
	["Flight path here: {area:69} ({npc:931})."] = "Letová trasa tady: {area:69} ({npc:931}).",
	["Fly from {area:144} to {zone:1453} if you have its flight path; otherwise ride back to {zone:1455} and take the {area:2257}. Walk west out of {zone:1429} past the {area:120} into {zone:1436}."] = "Leť z {area:144} do {zone:1453}, pokud máš jeho letovou trasu; jinak jeď zpátky do {zone:1455} a vezmi {area:2257}. Jdi na západ ze {zone:1429} kolem {area:120} do {zone:1436}.",
	["Fly from {area:42} to {area:144} in {zone:1432} and ride north through the {area:836} pass into the {zone:1437}."] = "Leť z {area:42} do {area:144} v {zone:1432} a jeď na sever průsmykem {area:836} do {zone:1437}.",
	["Follow the road west from {area:287} past {area:285} into {zone:1421}, Horde country with Horde guards at the {area:228}."] = "Jdi po silnici na západ od {area:287} kolem {area:285} do {zone:1421}, území Hordy se strážemi Hordy u {area:228}.",
	["From {area:1002} take the road south into {zone:1431}; {area:42} is east along its main road. Most of Duskwood is level 24-30: come with Redridge behind you."] = "Z {area:1002} vezmi silnici na jih do {zone:1431}; {area:42} je na východ po jeho hlavní silnici. Většina Duskwoodu je levelu 24–30: přijď s Redridge za sebou.",
	["From {area:925} take the {area:807} tunnel west into {zone:1426}. {area:131} and {zone:1455}'s gates are Alliance ground."] = "Z {area:925} jdi tunelem {area:807} na západ do {zone:1426}. {area:131} a brány {zone:1455} jsou území Aliance.",
	["Go back east through {zone:1429}: the road past the {area:88} enters Redridge at {area:1002}, where the roads from {zone:1429} and {zone:1431} meet."] = "Vrať se na východ přes {zone:1429}: silnice za {area:88} vstupuje do Redridge u {area:1002}, kde se setkávají cesty z {zone:1429} a {zone:1431}.",
	["Go east through {zone:1429} to {area:1002}, where Redridge starts. {area:69} is an Alliance town."] = "Jdi na východ přes {zone:1429} do {area:1002}, kde začíná Redridge. {area:69} je město Aliance.",
	["Hearth or fly back to the {zone:1458} (or go to {zone:1454}), take the zeppelin to {area:117} in {zone:1434} and walk north along the road into {zone:1431}. Northern Stranglethorn is level 30+ off the road."] = "Portni se Hearthstonem nebo leť zpět do {zone:1458} (nebo jdi do {zone:1454}), vezmi zeppelin do {area:117} v {zone:1434} a jdi po silnici na sever do {zone:1431}. Severní Stranglethorn má mimo silnici level 30+.",
	["Horde guards: touch the edge of {area:153} and move on"] = "Stráže Hordy: dotkni se okraje {area:153} a jdi dál",
	["Horde guards: touch the edge of {area:154} and move on"] = "Stráže Hordy: dotkni se okraje {area:154} a jdi dál",
	["Horde guards: touch the edge of {area:159} and move on"] = "Stráže Hordy: dotkni se okraje {area:159} a jdi dál",
	["Horde guards: touch the edge of {area:228} and move on"] = "Stráže Hordy: dotkni se okraje {area:228} a jdi dál",
	["Horde guards: touch the edge of {area:272} and move on"] = "Stráže Hordy: dotkni se okraje {area:272} a jdi dál",
	["Leave {zone:1426} east through the South Gate tunnel; it opens into {zone:1432} by the dwarf king statues of the {area:924}."] = "Opusť {zone:1426} na východ tunelem South Gate; vyústí do {zone:1432} u soch trpasličích králů v {area:924}.",
	["Take the boat from {area:150} to {area:271}."] = "Vezmi loď z {area:150} do {area:271}.",
	["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}, then leave the city through its gates."] = "Vezmi {area:2257} z {object:28027} v {zone:1453} do {zone:1455}, pak opusť město jeho branami.",
	["Walk east from {area:287} into the {zone:1417} (level 30+ creatures off the road), south to the {area:881} bridge, and across it into the {zone:1437}. {area:150} is an Alliance town."] = "Jdi z {area:287} na východ do {zone:1417} (mimo silnici tvorové level 30+), na jih k mostu {area:881} a přes něj do {zone:1437}. {area:150} je město Aliance.",
	["{area:9} opens onto {zone:1429}; {area:87} is south down the road."] = "{area:9} ústí do {zone:1429}; {area:87} je na jih po silnici.",
}
t.guides["forever/exploration/eastern-kingdoms-30-45"] = {
	["11 areas to discover here, levels 36-43."] = "Oblastí k objevení: 11, levely 36–43.",
	["14 areas to discover here, levels 36-44. Flight paths: {area:16724} in the south-east (Alliance), {area:16743} in the middle (Horde)."] = "Tady je 14 oblastí k objevení, levely 36–44. Letové trasy: {area:16724} na jihovýchodě (Aliance), {area:16743} uprostřed (Horda).",
	["14 areas to discover here, levels 36-45."] = "Oblastí k objevení: 14, levely 36–45.",
	["16 areas to discover here, levels 30-40."] = "Oblastí k objevení: 16, levely 30–40.",
	["27 areas to discover here, levels 30-50. {area:35} at the southern tip is a neutral goblin port with a boat to {area:392}."] = "Tady je 27 oblastí k objevení, levely 30–50. {area:35} na jižním cípu je neutrální goblinský přístav s lodí do {area:392}.",
	["Alliance town: Horde characters only need to touch its edge (guards)"] = "Město Aliance: postavám Hordy stačí dotknout se jeho okraje (stráže)",
	["Cross the {area:880} south into the {zone:1437}, go through the {object:1668} pass into {zone:1432} and take the road south out of {zone:1432} into the {zone:1418}."] = "Přejdi {area:880} na jih do {zone:1437}, projdi průsmykem {object:1668} do {zone:1432} a jdi po cestě na jih z {zone:1432} do {zone:1418}.",
	["Exploration: {zone:1415} 30-45"] = "Průzkum: {zone:1415} 30–45",
	["Exploring the entire world map on one character is a Forever Legacy Challenge (1 account-wide Legacy Point)."] = "Prozkoumání celé mapy světa jednou postavou je Forever Legacy Challenge (1 Legacy Point pro celý účet).",
	["Faster: fly to {area:144} in {zone:1432}."] = "Rychleji: leť do {area:144} v {zone:1432}.",
	["Flight path here: {area:16724} ({npc:257087})."] = "Letová trasa tady: {area:16724} ({npc:257087}).",
	["Flight path here: {area:16743} (Grakna)."] = "Letová trasa tady: {area:16743} (Grakna).",
	["Flight path here: {area:320} ({npc:2835})."] = "Letová trasa tady: {area:320} ({npc:2835}).",
	["Flight path here: {area:321} (Urda)."] = "Letová trasa tady: {area:321} (Urda).",
	["Flight path here: {area:340} (Gorrik)."] = "Letová trasa tady: {area:340} (Gorrik).",
	["Flight path here: {area:35} (Gyll)."] = "Letová trasa tady: {area:35} (Gyll).",
	["Flight path here: {area:75} (Breyk)."] = "Letová trasa tady: {area:75} (Breyk).",
	["Flight paths here: {area:35} (Gringer), {object:3202} (Thysta)."] = "Letové trasy tady: {area:35} (Gringer), {object:3202} (Thysta).",
	["Fly to {area:271} in {zone:1424} and walk north into the {zone:1416}."] = "Leť do {area:271} v {zone:1424} a jdi na sever do {zone:1416}.",
