	["Horde town: Alliance characters only need to touch its edge (guards)"] = "Město Hordy: postavám Aliance stačí dotknout se jeho okraje (stráže)",
	["Or take the zeppelin from {zone:1454} or the {zone:1458} to {area:117}."] = "Nebo jeď zeppelinem z {zone:1454} nebo z {zone:1458} do {area:117}.",
	["Starts in the {zone:1416}, north of {zone:1424}, and ends in {zone:1434}. 15 areas to discover here, levels 27-39."] = "Začíná v {zone:1416}, severně od {zone:1424}, a končí v {zone:1434}. K objevení je tu 15 oblastí, levely 27–39.",
	["{area:320} in the middle is the Alliance town; {area:321} in the east is Horde."] = "{area:320} uprostřed je aliancké město; {area:321} na východě je hordské.",
	["{area:321} in the east is the Horde town; {area:320} in the middle is Alliance."] = "{area:321} na východě je hordské město; {area:320} uprostřed je aliancké.",
	["{area:340} in the west is the Horde town."] = "{area:340} na západě je hordské město.",
