	["Flight path here: {area:3137} (Jarrodenus)."] = "Letová trasa tady: {area:3137} (Jarrodenus).",
	["Flight path here: {area:3425} ({npc:15177})."] = "Letová trasa tady: {area:3425} ({npc:15177}).",
	["Flight path here: {area:3425} ({npc:15178})."] = "Letová trasa tady: {area:3425} ({npc:15178}).",
	["Flight path here: {area:541} (Gryfe)."] = "Letová trasa tady: {area:541} (Gryfe).",
	["Flight path here: {area:976} ({npc:7823})."] = "Letová trasa tady: {area:976} ({npc:7823}).",
	["Flight path here: {area:976} ({npc:7824})."] = "Letová trasa tady: {area:976} ({npc:7824}).",
	["Flight path here: {zone:1450} (Faustron)."] = "Letová trasa tady: {zone:1450} (Faustron).",
	["Flight path here: {zone:1450} (Sindrayl)."] = "Letová trasa tady: {zone:1450} (Sindrayl).",
	["Flight paths here: {area:16849} ({npc:41861}), {area:16853} (Bluebell)."] = "Letové trasy tady: {area:16849} ({npc:41861}), {area:16853} (Bluebell).",
	["Fly to {area:1237} if you have it, otherwise to {area:431}, and walk east out of {zone:1440} into {zone:1447}."] = "Leť do {area:1237}, pokud ji máš, jinak do {area:431}, a jdi na východ ze {zone:1440} do {zone:1447}.",
	["Fly to {area:3137} if you have it, otherwise to {area:415}, and walk east out of {zone:1440} into {zone:1447}."] = "Leť do {area:3137}, pokud ji máš, jinak do {area:415}, a jdi na východ ze {zone:1440} do {zone:1447}.",
	["From western {zone:1446} take the path down into {zone:1449}. {area:541} in the north is a neutral camp."] = "Ze západního {zone:1446} vezmi stezku dolů do {zone:1449}. {area:541} na severu je neutrální tábor.",
	["Horde town: Alliance characters only need to touch its edge (guards)"] = "Město Hordy: postavám Aliance stačí dotknout se jeho okraje (stráže)",
	["Starts in {zone:1446}, south of {zone:1445}. The last area of this guide completes the {zone:1414} map. 20 areas to discover here, levels 40-50."] = "Začíná v {zone:1446}, jižně od {zone:1445}. Poslední oblast tohoto návodu dokončí mapu {zone:1414}. K objevení je tu 20 oblastí, levely 40–50.",
	["Take the {area:1769} tunnel in northern {zone:1448} through to {zone:1450} (druids: {spell:18960}). {area:2361} is neutral."] = "Projdi tunelem {area:1769} v severní {zone:1448} až do {zone:1450} (druidi: {spell:18960}). {area:2361} je neutrální.",
	["The other exit of the {area:1769} tunnel leads into {zone:1452}. {area:2255} is a neutral goblin town with flight masters for both factions."] = "Druhý východ z tunelu {area:1769} vede do {zone:1452}. {area:2255} je neutrální goblinské město s letovými mistry pro obě frakce.",
}
t.guides["forever/exploration/zephras-isle"] = {
	["Exploration: {zone:2521}"] = "Průzkum: {zone:2521}",
	["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "Vzducholoď odlétá z útesů jižně od {area:17045}, severně od {zone:1456} (další létá z {area:279}).",
	["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "Vzducholoď odlétá ze severní strany {area:279} v {zone:1416} (další létá ze severu {zone:1456}).",
}
t.guides["forever/horde/02-the-barrens"] = {
	["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Pomoz {npc:261366}: zůstaň u něj, až {npc:261367} a mariňáci z {area:21} vylezou na hřeben",
	["At the {area:2362}"] = "U {area:2362}",
	["At the {object:147538}: summons {quest:882}"] = "U {object:147538}: přivolá {quest:882}",
	["Back down to {npc:11857}."] = "Zpět dolů k {npc:11857}.",
	["Back east over the bridge and up the trail to {npc:5900}'s shrine again. {npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "Zpět na východ přes most a po stezce znovu nahoru ke svatyni {npc:5900}. {npc:5900} vyrobí z dehtu a váčku {item:6636}. Použij ho u pánve vedle něj, odhal {npc:5893}, zabij ho kvůli {item:6655} a pak dej uhlík do pánve.",
	["Back north along the beach to {area:392}."] = "Zpět na sever po pláži do {area:392}.",
	["Back north into the Bristleback camps. Any Bristleback can drop a tusk for {npc:3432}, so collect them while you kill these for {npc:3430}. Keep one {item:5075}."] = "Zpět na sever do táborů Bristleback. Kterýkoli Bristleback může dropnout kel pro {npc:3432}, tak je sbírej, zatímco zabíjíš tyhle pro {npc:3430}. Jeden {item:5075} si nech.",
	["Back north into {area:378} before the antennae fade: {npc:6394} is inside."] = "Zpět na sever do {area:378}, než tykadla zvadnou: {npc:6394} je uvnitř.",
	["Back north into {area:378} on the way to the Crossroads: Jorn takes the thunderhawk wings."] = "Zpět na sever do {area:378} cestou do Crossroads: Jorn vezme křídla thunderhawků.",
	["Back out of the caverns and up to the cave above the entrance."] = "Zpět ven z jeskyní a nahoru do jeskyně nad vchodem.",
	["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them. Careful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near {npc:3438} and the supply crates, and {npc:267307} (20, elite) lies in the cave under {area:1699} beside them: pull {npc:3438} and the quilboar away from them one at a time, and leave the cave alone unless you are in a group."] = "Zpět do tábora Razormane. Geomancers a Defenders drží jeho východní polovinu; {npc:3438} chodí mezi nimi. Pozor: Razormane Flesheaters a Berserkers (18–19) jsou elity na severovýchodě tábora, blízko {npc:3438} a beden se zásobami, a {npc:267307} (20, elitní) leží v jeskyni pod {area:1699} vedle nich: odlákej {npc:3438} a quilboary od nich po jednom a jeskyni nech být, pokud nejsi ve skupině.",
	["Bristleback Geomancers"] = "Bristleback Geomancers",
	["Bristleback camps"] = "Tábory Bristleback",
	["Cast {spell:18960}"] = "Sešli {spell:18960}",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. {npc:11802} stojí nahoře ve své budově v {area:2361}: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["Cure {npc:12296}"] = "Vyléč {npc:12296}",
	["Dogran is chained up in the quilboar camp west of the road."] = "Dogran je přikovaný v táboře quilboarů západně od cesty.",
	["Down the {area:458} to {area:378} again."] = "Znovu dolů po {area:458} do {area:378}.",
	["East along the road to {npc:4049} and {npc:11857}'s camp, on the way back out of Stonetalon."] = "Na východ po cestě do tábora {npc:4049} a {npc:11857}, cestou zpět ze Stonetalonu.",
	["East from {npc:261366} toward the {area:382}: {npc:9316} stands at the camp on the road north of the Crossroads."] = "Na východ od {npc:261366} směrem k {area:382}: {npc:9316} stojí v táboře na cestě severně od Crossroads.",
	["East of Ziz, the Venture Company is clear-cutting {area:461}; one of the Operators carries the blueprints."] = "Východně od Ziz Venture Company holoseče kácí {area:461}; plány nese jeden z Operators.",
	["East to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, and {npc:3467} (16) stands beside them."] = "Na východ na pláž, na jižní konec pirátského tábora: bedna s botami a křehká bedna s čočkou jsou tam a vedle nich stojí {npc:3467} (16).",
	["Fill the {item:7766} at the quilboar watering hole"] = "Naplň {item:7766} u napajedla quilboarů",
	["Finish the Plainstrider Beaks"] = "Dokonči Plainstrider Beaks",
	["Finish the Raptor Heads"] = "Dokonči Raptor Heads",
	["Fly from the Crossroads to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}. {spell:499} and {spell:526} follow in {zone:1450} on the same trip, then {npc:11798} flies you back here and on to {area:392}."] = "Leť z Crossroads do {area:1638} a vytrénuj si ranky levelu 20: {npc:3033} je na {area:1639}. {spell:499} a {spell:526} následují ve {zone:1450} na stejné cestě, pak tě {npc:11798} odveze letem zpátky sem a dál do {area:392}.",
	["Fly from the Crossroads to {area:1638}. {quest:853} waits in the {area:2197}, the cave under {area:1640}: hand in the spores there first, while their time runs. Then {npc:3033} trains you on {area:1639}."] = "Leť z Crossroads do {area:1638}. {quest:853} čeká v {area:2197}, jeskyni pod {area:1640}: odevzdej tam výtrusy jako první, dokud jim běží čas. Pak tě {npc:3033} vytrénuje na {area:1639}.",
	["Fly from {zone:1456} on to {area:392}."] = "Leť ze {zone:1456} dál do {area:392}.",
	["Fly from {zone:1456} straight on to {area:392}."] = "Leť ze {zone:1456} rovnou dál do {area:392}.",
	["Fly on to {area:392} from Doras on the tower in the {object:172982}."] = "Leť dál do {area:392} od Dorase na věži v {object:172982}.",
	["Fly to Crossroads"] = "Leť do Crossroads",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:392}"] = "Leť do {area:392}",
	["Follow the road on west from {npc:4049} into Stonetalon. The troll village of {area:2539} sits at the entrance of the canyon."] = "Jdi po silnici dál na západ od {npc:4049} do Stonetalonu. Trollí vesnice {area:2539} leží u vstupu do kaňonu.",
	["Follow the road south-east to {area:392} on the coast: {npc:3391} and {npc:7161} at the north end of town, {npc:3442} and {npc:16227}, {npc:3446} and the {object:3972} poster, then {quest:1492} on the dock on the way out south."] = "Jdi po silnici na jihovýchod do {area:392} na pobřeží: {npc:3391} a {npc:7161} na severním konci města, {npc:3442} a {npc:16227}, {npc:3446} a plakát {object:3972}, pak {quest:1492} na molu cestou ven na jih.",
	["Follow the {area:458} south to {area:378}."] = "Jdi po {area:458} na jih do {area:378}.",
	["For your {area:718} run: {npc:3446}'s next errand, {quest:1491}."] = "Pro tvůj průchod {area:718}: další pochůzka od {npc:3446}, {quest:1491}.",
	["For your {area:718} run: {npc:5767} and {npc:5768} stand in a hidden cave in the rocks above the entrance, at the north end of the oasis' west shore: climb up from the west side. Follow the arrow up."] = "Pro tvůj průchod {area:718}: {npc:5767} a {npc:5768} stojí ve skryté jeskyni ve skalách nad vchodem, na severním konci západního břehu oázy: vyšplhej tam ze západní strany. Jdi nahoru za šipkou.",
	["Grimtotem camp"] = "Tábor Grimtotem",
	["He gives you the {item:15826}"] = "Dá ti {item:15826}",
	["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Dál nabízí {quest:1838} (1838, level 30): vyžaduje {area:1717} a pošle tě po celém Kalimdoru i Eastern Kingdoms. Pokrývá ho návod pro warriora {quest:1838}.",
	["Head north from the Crossroads to {area:384} and fill the {item:15842} at the {object:19464}, then back to {npc:3448} in the Crossroads. No {skill:182}? {npc:3490} beside him sells {item:2449}, three at a time until he restocks."] = "Z Crossroads jdi na sever do {area:384} a naplň {item:15842} u {object:19464}, pak zpět k {npc:3448} v Crossroads. Nemáš {skill:182}? {npc:3490} vedle něj prodává {item:2449}, po třech, dokud nedoplní zásoby.",
	["In from the north gate: {npc:3464} first, {npc:3338} by the inn, then up to {npc:3449} and {npc:3429} on the tower platform, where the flight master stands."] = "Od severní brány: nejdřív {npc:3464}, {npc:3338} u hostince, pak nahoru k {npc:3449} a {npc:3429} na plošině věže, kde stojí letový mistr.",
	["In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "V táboře drží západní polovinu Water Seekers a Thornweavers, střed Hunters; bedny se zásobami jsou na jeho východním konci.\nPlainstriders tady se počítají do zobáků.\nPozor: Razormane Flesheaters a Berserkers (18–19) jsou elite; stojí na severovýchodě tábora, vedle beden se zásobami: odtahuj od nich quilboary po jednom.",
	["Leave {zone:1454} by the main gate and follow the road south through {zone:1411}, then west over the {area:814} bridge: {area:379} sits just above it on the {zone:1413} side. {npc:3337}, {quest:809} and {npc:5810} stand together."] = "Opusť {zone:1454} hlavní bránou a jdi po cestě na jih přes {zone:1411}, pak na západ přes most {area:814}: {area:379} leží hned nad ním na straně {zone:1413}. {npc:3337}, {quest:809} a {npc:5810} stojí pohromadě.",
	["Leave {zone:1454} by the main gate and follow the road south through {zone:1411}, then west over the {area:814} bridge: {npc:5810} stands at {area:379} just above it, on the road to the Crossroads."] = "Opusť {zone:1454} hlavní bránou a jdi po cestě na jih přes {zone:1411}, pak na západ přes most {area:814}: {npc:5810} stojí v {area:379} hned nad ním, na cestě do Crossroads.",
	["Level 20"] = "Level 20",
	["Lost Barrens Kodos roam the plains around the Kolkar camp north-west of {npc:3389}; herbalists pick {item:2449} there too."] = "Lost Barrens Kodos se toulají po pláních kolem tábora Kolkarů severozápadně od {npc:3389}; bylinkáři tam sbírají i {item:2449}.",
	["Plainstrider Beaks as you go"] = "Plainstrider Beaks cestou",
	["Plainstriders roam the plains all over the {zone:1413}, and about one in four drops a beak: kill the ones you pass on the way."] = "Plainstrideři se potulují po pláních všude v {zone:1413} a zhruba každý čtvrtý dropne zobák: zabíjej ty, které potkáš cestou.",
	["Raptor Heads as you go"] = "Raptor Heads cestou",
	["Raptor nests"] = "Hnízda raptorů",
	["Razormane camp"] = "Tábor Razormane",
	["Razormane camp: {npc:3429}'s quilboar"] = "Tábor Razormane: quilboaři pro {npc:3429}",
	["Speak to {npc:3389} again to start the attack: the Kolkar charge the bunkers just west of him in waves. Fight beside the grunts until {npc:9456} (elite, 20) arrives with two bodyguards, usually from the south, then click the banner over his body."] = "Promluv znovu s {npc:3389} a zahaj útok: Kolkarové v vlnách útočí na bunkry kousek západně od něj. Bojuj po boku gruntů, dokud nedorazí {npc:9456} (elite, 20) se dvěma bodyguardy, obvykle od jihu, pak klikni na prapor nad jeho tělem.",
	["Still short of seven? Plainstriders are thickest on the plains north of the Crossroads, along the road north."] = "Pořád ti chybí do sedmi? Plainstriders je nejvíc na pláních severně od Crossroads, podél cesty na sever.",
	["Still short of twelve? Sunscale Lashtails and Screechers roam the plains north-east of the Crossroads, on the way back south from {quest:881}'s lair."] = "Pořád ti chybí do dvanácti? Sunscale Lashtails a Screechers se potulují po pláních severovýchodně od Crossroads, na cestě zpátky na jih z doupěte {quest:881}.",
	["Sunscale Scytheclaws hunt the plains around the {area:1697}; they drop the horns. {npc:3446} takes them back in {area:392}; any still missing come with {npc:3682}'s hills later.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "Sunscale Scytheclaws loví na pláních kolem {area:1697}; dropují rohy. {npc:3446} je převezme v {area:392}; ty, co ještě chybí, přijdou později s kopci {npc:3682}.\nNa jihovýchod k pobřeží: ukradené stříbro leží v raptořím hnízdě severozápadně od {area:385}.",
	["Sunscale raptors roam the plains north and east of the Crossroads, and about three in four drop a head: kill the ones you pass on the way. Careful: Sunscale Screechers call nearby allies within 30 yd once below 30% health."] = "Raptoři Sunscale se potulují po pláních severně a východně od Crossroads a asi tři ze čtyř dropnou hlavu: zabíjej ty, které míjíš po cestě. Pozor: Sunscale Screechers pod 30 % zdraví přivolají spojence do 30 yardů.",
	["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. Careful: the spirits are Territorial Terrans (level 60) that kill whoever they see: stay off their paths, and click the statue again before the stealth runs out."] = "Taureni: {npc:11957} čeká na jižním kopci nad mostem. Skyborne: {npc:272054} stojí jižně od dvojitých mostů. Pak doupata východně od jezera: opusť formu, klikni na sochu u vchodu pro pět minut stealthu, drž se dál od duchů uvnitř a vezmi od každé relikvie jednu; {item:280680} leží u paty bílé sochy kočky. Pozor: duchové jsou Territorial Terrans (level 60), kteří zabijí každého, koho uvidí: drž se mimo jejich trasy a klikni na sochu znovu, než stealth vyprší.",
	["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. {npc:3432}'s wife lies at their north edge, on your way south. Leave the quilboar for now: {npc:3430} in {area:378} wants the same camps cleared. {quest:883}, a grey kodo (level 22), sometimes wanders here: his hoof starts a quest. Leave him alone below level 21."] = "Tábory quilboarů Bristleback se rozkládají po pláních severně od {area:378}, po obou stranách {area:458}. Manželka {npc:3432} leží na jejich severním okraji, na tvé cestě na jih. Quilboary zatím nech být: {npc:3430} v {area:378} chce vyčistit tytéž tábory. {quest:883}, šedý kodo (level 22), se tu občas toulá: jeho kopyto spustí quest. Pod levelem 21 ho nech být.",
	["The Grimtotem camp is just north of {npc:11857}, a short walk off the road: Ruffians and Mercenaries stand among the tents."] = "Tábor Grimtotem je kousek severně od {npc:11857}, kousek od cesty: mezi stany stojí Ruffians a Mercenaries.",
	["The next guide goes north-east across the {zone:1413} to the {area:1703} and {zone:1440}."] = "Další návod jde na severovýchod přes {zone:1413} do {area:1703} a {zone:1440}.",
	["The pirates camp on the beach south of {area:392}: the piles of complicated parts lie in the sand among them. {npc:3467} (16) stands at the camp's southern end: leave him for the next {area:392} stop."] = "Piráti táboří na pláži jižně od {area:392}: hromady složitých součástek leží v písku mezi nimi. {npc:3467} (16) stojí na jižním konci tábora: nech ho na další zastávku v {area:392}.",
	["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. {npc:3394} stands in the Kolkar camp west of the pools."] = "Jezírka leží kousek severně od {npc:3389}. Vejdi do vody, abys je prozkoumal; Laden Mushrooms pro Helbrima rostou kolem nich. Kvůli náramkům zabij každého Kolkara, kterého potkáš. {npc:3394} stojí v táboře Kolkarů západně od jezírek.",
	["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "Silnice stoupá na sever jako {area:1076}. {quest:1483} má chýši tam, kde se silnice větví na východ do {area:461}.",
	["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}."] = "Kbelíky s nářadím a slimáky leží kolem vrtné stanice Venture Co. v {area:382}.",
	["The {area:2363}"] = "{area:2363}",
	["Thunderhawk Cloudscrapers circle over the plains south of the camp."] = "Thunderhawk Cloudscrapers krouží nad pláněmi jižně od tábora.",
	["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard (level 24), roams among them: his Tailspike starts a quest. Leave him alone below level 23."] = "Thunderheads se pasou na pláních kousek jižně od {area:378}. Mezi nimi se toulá {quest:884}, modrý thunder lizard (level 24): jeho Tailspike spouští quest. Pod levelem 23 ho nech být.",
	["To {area:2539}"] = "Do {area:2539}",
	["To {npc:3389}"] = "Do {npc:3389}",
	["Train your level 20 ranks in {area:1637} now: fly from {npc:3615} on the Crossroads' tower."] = "Teď si v {area:1637} vytrénuj ranky z levelu 20: leť od {npc:3615} na věži v Crossroads.",
	["Train your level 20 ranks: {npc:246344} teaches Paladins in {area:1638}; {zone:1454} has no Paladin trainer. You have no flight path there yet: fly to {area:378}, head west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "Vytrénuj si ranky z levelu 20: {npc:246344} učí paladiny v {area:1638}; v {zone:1454} trenér paladinů není. Letovou trasu tam ještě nemáš: leť do {area:378}, jdi na západ přes {zone:1412} a nahoru výtahem a vezmi si letovou trasu u {npc:2995} na centrálním návrší.",
	["Twitching Antennae"] = "Twitching Antennae",
	["Twitching Antennae from the silithid"] = "Twitching Antennae ze silithidů",
	["Underwater"] = "Pod vodou",
	["Upstairs"] = "Nahoře",
	["Venture Co. Loggers, all over the clear-cut"] = "Venture Co. Loggers po celé pasece",
	["Warriors: take {quest:1824} from {npc:6394} now: it runs for 30 minutes from the accept. The antennae come first, at the Silithid Mounds south of the camp, then straight back to {npc:6394}; the thunderhawks after."] = "Warrioři: teď si vezmi {quest:1824} od {npc:6394}: běží 30 minut od přijetí. Nejdřív tykadla u Silithid Mounds jižně od tábora, pak rovnou zpátky k {npc:6394}; thunderhawky až potom.",
	["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "Na západ od vypálené vesnice do {area:2539}: {npc:12816} stojí kousek před ní, před vesnicí.",
	["West from the mine to {npc:9316}'s camp, then south down the road to the Crossroads."] = "Z dolu na západ do tábora {npc:9316}, pak po silnici na jih do Crossroads.",
	["West to the {area:383}. Any Witchwing harpy drops a talon: keep to the eastern slopes, where the Witchwing Harpies and Roguefeathers (14-15) nest; the Slayers and Windcallers (16-17) hold the western hills. Savannah Prowlers hunt the plains between {npc:3389} and the hills: take their claws on the way.\nCareful: There are 2 Witchwing Ambushers (level 17-18). They stay stealthed with Sneak while out of combat."] = "Na západ do {area:383}. Dráp dropne kterákoli harpyje Witchwing: drž se východních svahů, kde hnízdí Witchwing Harpies a Roguefeathers (14–15); Slayers a Windcallers (16–17) drží západní kopce. Po pláních mezi {npc:3389} a kopci loví Savannah Prowlers: cestou si vezmi jejich drápy.\nPozor: jsou tu 2 Witchwing Ambushers (level 17–18). Mimo boj zůstávají ve stealthu pomocí Sneak.",
	["West to {npc:3389}'s watch post on the Kolkar border."] = "Na západ ke strážnímu stanovišti {npc:3389} na hranici s Kolkar.",
	["While you are in the camp: {npc:3429}'s Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Když už jsi v táboře: Water Seekers a Thornweavers pro {npc:3429} v jeho západní polovině, Hunters uprostřed, bedny se zásobami na východním konci.\nPozor: Razormane Flesheaters a Berserkers (18–19) jsou elite; stojí v severovýchodní části tábora vedle beden se zásobami: odtahuj od nich quilboary po jednom.",
	["grind on {npc:3263}"] = "grinduj na {npc:3263}",
	["{area:1076}: kill these as you meet them"] = "{area:1076}: zabíjej je, jak na ně narazíš",
	["{area:1697}: kill these as you meet them"] = "{area:1697}: zabíjej je, jak na ně narazíš",
	["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn: {npc:3338} by the inn, Helbrim and {npc:3464} by the north gate, then up the tower to {npc:3615}, the wind rider master, {npc:3429} and {npc:3449}, and {npc:3448} at the south gate on the way out."] = "{area:380} je tvoje základna pro tenhle návod. Všichni, koho potřebuješ, stojí pár kroků od hostince: {npc:3338} u hostince, Helbrim a {npc:3464} u severní brány, pak nahoru do věže k {npc:3615}, mistrovi wind riderů, {npc:3429} a {npc:3449} a {npc:3448} u jižní brány cestou ven.",
	["{area:385}: kill these as you meet them"] = "{area:385}: zabíjej je, jak na ně narazíš",
	["{area:392} flight master"] = "letový mistr {area:392}",
	["{area:392}: {area:718} quests"] = "{area:392}: questy {area:718}",
	["{area:718} is a dungeon for a group of five, about levels 17 to 24, and a full run takes about an hour. Its mouth is just north of {npc:3396}'s shore, at the north end of {area:387}, under {npc:5767}'s cave.\nIn the caves before the portal: {npc:3655}, stealthed, with the {item:5334} (he moves between a few spots and comes back slowly: leave him if he's gone). Inside: the Deviates for {npc:5768}, and their hides for {npc:5767} (they drop rarely: one run may not be enough, so leave the rest for another run), {item:6464} from the Ectoplasms. After the four Fanglords, the {npc:3678} at the entrance leads you to Naralex: {npc:3654} drops the {item:10441}: its quest (someone in {area:392}, then {npc:8418} above the caverns) is not on this route; the Dungeons page's hand-in guide takes it."] = "{area:718} je dungeon pro skupinu pěti, zhruba level 17 až 24, celý průchod trvá asi hodinu. Ústí kousek severně od břehu {npc:3396}, na severním konci {area:387}, pod jeskyní {npc:5767}.\nV jeskyních před portálem: {npc:3655} ve stealthu s {item:5334} (přechází mezi několika místy a vrací se pomalu: když tam není, nech ho být). Uvnitř: Deviates pro {npc:5768} a jejich kůže pro {npc:5767} (dropují vzácně: jeden průchod nemusí stačit, tak zbytek nech na další), {item:6464} z Ectoplasms. Po čtyřech Fanglordech tě {npc:3678} u vchodu dovede k Naralexovi: {npc:3654} dropne {item:10441}: jeho quest (někdo v {area:392}, pak {npc:8418} nad jeskyněmi) na téhle trase není; vezme ho návod na odevzdání na stránce Dungeony.",
	["{item:10338}, from any zhevra; Zhevra Chargers graze around the tree"] = "{item:10338} z jakékoli zhevry; Zhevra Chargers se pasou kolem stromu",
	["{item:15877}, from a {object:177785} in the lake"] = "{item:15877} z {object:177785} v jezeře",
	["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} v {area:2361} tam vozí druidy",
	["{npc:11799}, at the {area:2362}"] = "{npc:11799}, u {area:2362}",
	["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802} stojí nahoře ve své budově v {area:2361}: vyjdi nahoru uvnitř, šipka nerozezná patra.",
	["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}. {quest:28} runs on a timer: no teleport or Hearthstone until {npc:11799} has it."] = "{npc:11802} stojí nahoře ve své budově v {area:2361}: vyjdi nahoru uvnitř, šipka nerozezná patra. Shrine Baubles leží na dně {area:656} a během pár minut zmizí: s jedním plav rovnou k {area:2362} na severozápadním břehu, použij ho tam a promluv s {npc:11799}. {quest:28} běží na čas: žádný teleport ani Hearthstone, dokud ho {npc:11799} nemá.",
	["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: uvítání od {npc:3033}",
	["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}, v chýši {npc:11858}",
	["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857}: nech si ho, {npc:11864} u {area:460} v návodu {zone:1413} & Stonetalon",
	["{npc:11858} waits up the {area:1076}"] = "{npc:11858} čeká nahoře v {area:1076}",
	["{npc:12296}: use the {item:15826} on them; they roam the plains all around the Crossroads"] = "{npc:12296}: použij na ně {item:15826}; potulují se po pláních všude kolem Crossroads",
	["{npc:12816}: the spiders along the {area:1076}"] = "{npc:12816}: pavouci podél {area:1076}",
	["{npc:16227}, beside {npc:3442}"] = "{npc:16227}, vedle {npc:3442}",
	["{npc:267310} stands on the north-east side of the Crossroads. {quest:97003} is a group quest: {npc:267307} is a level 20 elite boar in the Razormane's {area:1699} cave, east of the town, where the route goes back for {npc:3438} later."] = "{npc:267310} stojí na severovýchodní straně Crossroads. {quest:97003} je skupinový quest: {npc:267307} je elite kanec s levelem 20 v jeskyni Razormane {area:1699} východně od města, kam se trasa později vrací kvůli {npc:3438}.",
	["{npc:3337}: {quest:840}, from {zone:1411}"] = "{npc:3337}: {quest:840}, ze {zone:1411}",
	["{npc:3338} by the inn first, then Helbrim by the north gate, {npc:3429} and {npc:3449} on the tower platform, {npc:3432} by the inn, and {npc:3448} at the south gate last. His seed test waits for the {npc:3395} pass at the {area:388}: go straight on north-west to the {area:383}. After the spores Helbrim offers {quest:853}, a delivery to {zone:1456} within 45 minutes: this route doesn't go there, so leave it (Druids take it on the next Crossroads stop, right before their flight to {zone:1456})."] = "Nejdřív {npc:3338} u hostince, pak Helbrim u severní brány, {npc:3429} a {npc:3449} na plošině věže, {npc:3432} u hostince a nakonec {npc:3448} u jižní brány. Jeho test semínek počká na průchod kvůli {npc:3395} u {area:388}: pokračuj rovnou na severozápad k {area:383}. Po sporách nabídne Helbrim {quest:853}, doručení do {zone:1456} do 45 minut: tahle trasa tam nevede, tak ho nech být (druidi si ho vezmou na další zastávce na Crossroads, těsně před letem do {zone:1456}).",
	["{npc:3338}: the raptor nests south of the Crossroads"] = "{npc:3338}: hnízda raptorů jižně od Crossroads",
	["{npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "{npc:3354} je v {object:172958}, {npc:5892} v {object:172957}.",
	["{npc:3389}: {npc:3395} comes out when you kill the Kolkar at the {area:388}, later"] = "{npc:3389}: {npc:3395} vyleze, když později zabíjíš Kolkary u {area:388}",
	["{npc:3390}: 45 minutes, for Zamah on the {zone:1456} step next"] = "{npc:3390}: 45 minut, pro Zamaha na příštím kroku v {zone:1456}",
	["{npc:3390}: {quest:1358}, from Zinge"] = "{npc:3390}: {quest:1358}, od Zinge",
	["{npc:3391} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:3391} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["{npc:3391}, upstairs"] = "{npc:3391}, nahoře",
	["{npc:3391}: the crates lie at the south end of the beach camp, on the next {area:392} stop at 18"] = "{npc:3391}: bedny leží na jižním konci tábora na pláži, na příští zastávce v {area:392} na levelu 18",
	["{npc:3395} doesn't wander on his own: he comes out when you kill the Kolkar centaurs at the {area:388}, south-east of the Crossroads. Keep killing them around the oasis until he appears. Test {npc:3448}'s seeds at the bubbling fissure on the oasis' east bank while you are there."] = "{npc:3395} sám nebloudí: vyleze, když zabíjíš kentaury Kolkar u {area:388}, jihovýchodně od Crossroads. Zabíjej je kolem oázy, dokud se neobjeví. Když už tam jsi, otestuj semínka od {npc:3448} u bublající pukliny na východním břehu oázy.",
	["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to {npc:3389} on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for {npc:3448}."] = "{npc:3396} vede Kolkary na západním břehu {area:387}, jižně od {npc:3389}. Chodí po tom břehu, zhruba od 46,36 na severu po 46,42 na jihu: když není u šipky, jdi podél břehu, dokud ho nepotkáš. Jeho hlavu odevzdej {npc:3389} na poslední zastávce na Crossroads. Ve vodě oázy tam lezou Oasis Snapjaws: jejich krunýře jsou pro {npc:3448}.",
	["{npc:3428}'s {quest:868} waits for this guide's last Crossroads stop: its eggs come on the next {zone:1413} guide's walk south, at about 25."] = "{quest:868} od {npc:3428} počká na poslední zastávku na Crossroads v tomhle návodu: jeho vejce přijdou při cestě na jih v dalším návodu pro {zone:1413}, zhruba na levelu 25.",
	["{npc:3428}, west of the north gate: keep {quest:868}, its eggs lie on the next {zone:1413} guide's walk south from {area:378}, at about 25"] = "{npc:3428}, západně od severní brány: nech si {quest:868}, jeho vejce leží na cestě na jih od {area:378} v dalším návodu pro {zone:1413}, zhruba na levelu 25",
	["{npc:3429}, at the top of the tower"] = "{npc:3429}, na vrcholu věže",
	["{npc:3429}, on the tower, from level 17. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}, na věži, od levelu 17. Nech si ho: Kadrak u {area:1703}, další návod",
	["{npc:3430}, in the cage"] = "{npc:3430}, v kleci",
	["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} nabídne {quest:95774}, jakmile odevzdáš {quest:4921}",
	["{npc:3432}: his wife lies at the north edge of the Bristleback camps, later"] = "{npc:3432}: jeho žena leží na severním okraji táborů Bristleback, později",
	["{npc:3439} stands inside the Venture Co. camp in the {area:382}; {npc:3445} carries the key."] = "{npc:3439} stojí uvnitř tábora Venture Co. v {area:382}; klíč nese {npc:3445}.",
	["{npc:3442} in {area:392}: on the next {area:392} stop"] = "{npc:3442} v {area:392}: na příští zastávce v {area:392}",
	["{npc:3442}: keep it, {quest:1483} is on the {area:1076} in Stonetalon, at the end of this guide"] = "{npc:3442}: nech si ho, {quest:1483} je na {area:1076} ve Stonetalonu, na konci tohoto návodu",
	["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: konzole je v {area:382}, později",
	["{npc:3442}: {npc:9316} stands on the road north of the Crossroads, on the way to the {area:382}"] = "{npc:3442}: {npc:9316} stojí na cestě severně od Crossroads, po cestě do {area:382}",
	["{npc:3446}, beside the {object:3972} poster"] = "{npc:3446}, vedle plakátu {object:3972}",
	["{npc:3446}, beside the {object:3972} poster: the Sunscale raptors come on the next {area:392} stop, at 18"] = "{npc:3446}, vedle plakátu {object:3972}: raptoři Sunscale přijdou na příští zastávce v {area:392}, na levelu 18",
	["{npc:3448}: the Oasis Snapjaws at {area:387}, with {npc:3396} after the {zone:1454} trip"] = "{npc:3448}: Oasis Snapjaws u {area:387}, spolu s {npc:3396} po výpravě do {zone:1454}",
	["{npc:3448}: the bubbling fissure at the {area:388}, on the {npc:3395} pass"] = "{npc:3448}: bublající puklina u {area:388}, při průchodu kvůli {npc:3395}",
	["{npc:3449}, on the tower: {quest:876} leads the harpies in the {area:383}"] = "{npc:3449}, na věži: {quest:876} vede harpyje v {area:383}",
	["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: harpyje přijdou později, v {area:383}",
	["{npc:3464}, by the Crossroads' north gate"] = "{npc:3464}, u severní brány Crossroads",
	["{npc:3464}: the {quest:3281}, in a raptor nest north-west of {area:385}"] = "{npc:3464}: {quest:3281}, v hnízdě raptorů severozápadně od {area:385}",
	["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} je připoutaný v podpalubí. Promluv s ním, tím začne eskorta, a drž se blízko: cestou ven útočí vojáci z Theramore. Dovede tě zpátky do {area:392}.",
	["{npc:3615}, on the tower"] = "{npc:3615}, na věži",
	["{npc:4049} and {npc:11857} share the camp on the road west to Stonetalon."] = "{npc:4049} a {npc:11857} sdílejí tábor na cestě na západ do Stonetalonu.",
	["{npc:4049}'s camp"] = "tábor {npc:4049}",
	["{npc:4049}: the Venture loggers at {area:461}"] = "{npc:4049}: dřevorubci Venture v {area:461}",
	["{npc:4049}: {quest:1063}, Magatha in {zone:1456}, on the next guide's way back from Zoram'gar"] = "{npc:4049}: {quest:1063}, Magatha v {zone:1456}, po cestě zpátky ze Zoram'gar v dalším návodu",
	["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197} žije v {area:2539}, trollí vesnici kousek za hranicí Stonetalonu na konci cesty na západ od {npc:3389}.",
	["{npc:4201}, inside"] = "{npc:4201}, uvnitř",
	["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201}: pro {npc:3442}, vedle letového mistra v {area:392} na konci návodu pro {zone:1413} a Stonetalon",
	["{npc:4276}'s defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone.\n{npc:4276} mines at the bottom of the {area:2160} on the east side of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails."] = "Obrana {npc:4276} je na tomhle levelu sólo těžká: doporučuje se skupina, poohlédni se po lidech. Když jsi sám, přeskoč ji.\n{npc:4276} kope na dně {area:2160} na východní straně útesu, za jeho koboldy (levely 19–23). Promluv s ním a pak ho udrž naživu pět minut, zatímco kope: ve vlnách na něj jde tucet i víc koboldů, nejdřív na blízko, pak caster, a do boje se respawnují i koboldi z dolu. Když umře, quest selže.",
	["{npc:4276}, below ground"] = "{npc:4276}, pod zemí",
	["{npc:5767} and {npc:5768}"] = "{npc:5767} a {npc:5768}",
	["{npc:6394}, inside"] = "{npc:6394}, uvnitř",
	["{object:3972} poster"] = "Plakát {object:3972}",
	["{quest:1483}, inside"] = "{quest:1483}, uvnitř",
	["{quest:1492}, on the dock"] = "{quest:1492}, na molu",
	["{quest:1492}: the emerald comes from the {area:381}, later"] = "{quest:1492}: smaragd je z {area:381}, později",
	["{quest:2458}: {npc:7233}, by the {area:382} on the next guide's walk north"] = "{quest:2458}: {npc:7233}, u {area:382} cestou na sever v dalším návodu",
	["{quest:30}, carried: one half pendant in the {area:382} in this guide, the other underwater off Silverpine on the way to {area:287} at 21; the pendant is handed in after {area:287}"] = "{quest:30}, nesený: jedna půlka přívěsku je v {area:382} v tomhle návodu, druhá pod vodou u Silverpine cestou do {area:287} na levelu 21; přívěsek se odevzdává po {area:287}",
	["{quest:3923} stands by the {object:172958}'s water, east of the Drag."] = "{quest:3923} stojí u vody {object:172958}, východně od Dragu.",
	["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, další návod",
	["{quest:809}, beside {npc:3337}: from {npc:3216} in {zone:1454}"] = "{quest:809}, vedle {npc:3337}: od {npc:3216} v {zone:1454}",
	["{quest:853}, in the {area:2197}"] = "{quest:853}, v {area:2197}",
	["{quest:865}, if still open: Sunscale Scytheclaws prowl among the lions"] = "{quest:865}, pokud je ještě otevřený: Sunscale Scytheclaws se plíží mezi lvy",
	["{quest:882}, a big Sunscale raptor, only comes to a fresh kill: loot a {item:10338} from a zhevra, then use it at the {object:147538} north-west of {area:392}, north of the road to the Crossroads, and be ready when he arrives."] = "{quest:882}, velký raptor Sunscale, přijde jen k čerstvé kořisti: lootni {item:10338} ze zhevry, pak ho použij u {object:147538} severozápadně od {area:392}, severně od cesty do Crossroads, a buď připravený, až dorazí.",
	["{zone:1413}: kill these as you meet them"] = "{zone:1413}: zabíjej je, jak na ně narazíš",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
	["{zone:1456} flight master"] = "letový mistr {zone:1456}",
}
t.guides["forever/horde/03-silverpine-forest"] = {
	["Allister's Ambermill Investigations is for the ride through Silverpine at 22; leave it."] = "Allister's Ambermill Investigations je na průjezd Silverpinem na 22; nech ho být.",
	["Back down the road past the zeppelin towers and east to {npc:1495}'s camp: {npc:267009} stands beside her."] = "Zpět dolů po cestě kolem věží zeppelinů a na východ do tábora {npc:1495}: {npc:267009} stojí vedle ní.",
	["Back out through the portal: {npc:3216} stands beside it."] = "Zpět ven portálem: {npc:3216} stojí vedle něj.",
	["Class trainer"] = "Trenér povolání",
	["Follow the lake shore south from the murlocs: the {object:1593} lies at the ferry landing."] = "Jdi podél břehu jezera na jih od murloců: {object:1593} leží u přístaviště přívozu.",
	["Follow the lake shore south-east from the Yoricks' house: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "Jdi podél břehu jezera na jihovýchod od domu Yoricků: Vile Fin Shredders a Tidehunters podél něj dropují oči murloců.",
	["Follow the road north-east to the Yoricks' house at {area:238}."] = "Jdi po silnici na severovýchod k domu Yoricků u {area:238}.",
	["Follow the road south. The {object:1627} sits beside it, north of Pyrewood. Careful: Dalaran Apprentices (13) stand around the crate: pull them one at a time before you open it."] = "Jdi po silnici na jih. {object:1627} stojí vedle ní, severně od Pyrewoodu. Pozor: kolem bedny stojí Dalaran Apprentices (13): než ji otevřeš, stáhni je po jednom.",
	["For your {area:2437} run: the {object:172960} is the canyon under the {object:172982}; {npc:3216} stands at its far end, next to the {area:2437} portal."] = "Pro tvůj průchod {area:2437}: {object:172960} je kaňon pod {object:172982}; {npc:3216} stojí na jeho vzdáleném konci, vedle portálu do {area:2437}.",
	["From the ferry back west up the road to the {area:228}."] = "Od přívozu zpátky na západ nahoru po silnici k {area:228}.",
	["Mottled Worgs"] = "Mottled Worgs",
	["Mottled Worgs prowl the hills around the house."] = "Mottled Worgs slídí po kopcích kolem domu.",
	["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "Promluv s {npc:10181} v {object:36126}: {quest:93739}",
	["Speak with {npc:10540}, in Grommash Hold"] = "Promluv s {npc:10540} v Grommash Hold",
	["Speak with {npc:3230}, in Grommash Hold"] = "Promluv s {npc:3230} v Grommash Hold",
	["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "Jdi po cestě na sever směrem k {zone:1420}: dům Yorickových v {area:238} je po cestě. {quest:425} číhá kousek na západ od něj.",
	["Talk to {npc:10181}"] = "Promluv s {npc:10181}",
	["Talk to {npc:10540}"] = "Promluv s {npc:10540}",
	["Talk to {npc:3230}"] = "Promluv s {npc:3230}",
	["The cultists camp a short walk south-east of {npc:267009}. Dark Neophytes and Dark Enforcers drop the Necrotic Crystal Fragments; more fragments, black crystals, lie on the ground among the tents."] = "Kultisté táboří kousek jihovýchodně od {npc:267009}. Necrotic Crystal Fragments dropují Dark Neophytes a Dark Enforcers; další úlomky, černé krystaly, leží na zemi mezi stany.",
	["Train while you are in the city: Druids and Paladins have no trainer here. Troll Priests: train with {npc:6018} in the {object:172961}, who takes {quest:5654}."] = "Když už jsi ve městě, vytrénuj se: druidové a paladinové tu trenéra nemají. Trollí kněží: trénuj u {npc:6018} v {object:172961}, který si vezme {quest:5654}.",
	["Vile Fin murlocs"] = "Murloci Vile Fin",
	["Walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}; {npc:6929} keeps the inn below it, {npc:268701} stands by the bank. Bind here: the Hearthstone brings you back from {zone:1421} beside the zeppelin towers and the road to the {zone:1413}."] = "Vejdi hlavní branou. {npc:3310}, mistr wind riderů, stojí na věži v {object:172982}; {npc:6929} vede hostinec pod ní, {npc:268701} stojí u banky. Nastav si tu Hearthstone: z {zone:1421} tě vrátí sem, vedle věží zeppelinů a silnice do {zone:1413}.",
	["Walk in through the main gate. {npc:268701} stands in the {object:172982}."] = "Vejdi hlavní branou. {npc:268701} stojí v {object:172982}.",
	["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Když už jsi tady: nauč se Staves u {npc:2704} ({object:172958}, 10 silver); u zbraně na blízko huntera jde hlavně o staty a obouručky jich mají nejvíc.",
	["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Když už jsi tady: nauč se Staves u {npc:2704} ({object:172958}, 10 silver); při levelování má hůl víc kouzelných statů než jednoručka.",
	["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Paladin fastest."] = "Když už jsi tady: nauč se {spell:197} u {npc:11868} ({object:172958}, 10 silver); s obouručkami paladin levluje nejrychleji.",
	["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Warrior fastest."] = "Když už jsi tady: nauč se {spell:197} u {npc:11868} ({object:172958}, 10 silver); s obouručkami warrior levluje nejrychleji.",
	["{area:159} is a short walk north up the road from the zeppelin towers: {npc:1738} stands by the road into town, {npc:1518} in the apothecary's house on the west side of the square; Paladins: {npc:246152} trains you in town."] = "{area:159} je kousek na sever po silnici od věží zeppelinů: {npc:1738} stojí u silnice do města, {npc:1518} v domě lékárníka na západní straně náměstí; paladinové: {npc:246152} tě trénuje ve městě.",
	["{area:159} is a short walk north up the road from the zeppelin towers; {npc:1499} is in the town hall."] = "{area:159} je kousek na sever po silnici od věží zeppelinů; {npc:1499} je na radnici.",
	["{area:227} farmhouse"] = "Statek {area:227}",
	["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228} je kryptové městečko Forsaken uprostřed lesa. Všichni, koho potřebuješ, stojí kolem vchodu do krypty; {npc:2226}, chovatel netopýrů, je kousek východně od něj.",
	["{area:2437} is a dungeon for a group of five, about levels 13 to 18, and a full run takes 30 to 45 minutes. Its portal is in the {object:172960}, beside {npc:3216}.\nInside: past Oggleflint and his troggs, {npc:11520} waits in the lava cave and drops his heart. {npc:11518} and Bazzalan, further in, are for {npc:4949}'s Hidden Enemies, which this route leaves out."] = "{area:2437} je dungeon pro skupinu pěti, zhruba level 13 až 18, celý průchod trvá 30 až 45 minut. Portál je v {object:172960} vedle {npc:3216}.\nUvnitř: za Oggleflintem a jeho troggy čeká v lávové jeskyni {npc:11520} a dropne své srdce. {npc:11518} a Bazzalan dál uvnitř jsou pro Hidden Enemies od {npc:4949}, které tahle trasa vynechává.",
	["{npc:11044}, in the Apothecarium"] = "{npc:11044}, v Apothecariu",
	["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}, trenér alchymie, stojí hned vedle {npc:3348}.",
	["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046}: Camping 101, od Brakkova ohniště v {zone:1411}",
	["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}, trenér enchantingu, pracuje v Dragu.",
	["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066}: Camping 101, od Brakkova ohniště v {zone:1411}",
	["{npc:1499} in {area:159}, on the way to the zeppelin at the end"] = "{npc:1499} v {area:159}, cestou k zeppelinu na konci",
	["{npc:1518}, inside"] = "{npc:1518}, uvnitř",
	["{npc:1951}, inside"] = "{npc:1951}, uvnitř",
	["{npc:1952}, below ground"] = "{npc:1952}, pod zemí",
	["{npc:1978}, inside"] = "{npc:1978}, uvnitř",
	["{npc:246152}, in {area:159}"] = "{npc:246152}, v {area:159}",
	["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them."] = "{npc:268684} a {npc:268682} sedí za Grommash Hold v {object:172957}; Smooth Boulders leží kolem nich.",
	["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them. The next guide walks from here to {area:379} and the Crossroads."] = "{npc:268684} a {npc:268682} sedí za Grommash Hold v {object:172957}; Smooth Boulders leží kolem nich. Další návod jde odsud do {area:379} a na Crossroads.",
	["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}, trenér tailoringu, je v {object:172958}.",
	["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855}: Camping 101 od Brakkova táboráku v {zone:1411}",
	["{npc:3230}, in Grommash Hold"] = "{npc:3230}, v Grommash Hold",
	["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} a {npc:3347} vedou alchymistický obchod v Dragu; {npc:11046} je hned vedle.",
	["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}, trenér leatherworkingu, pracuje v {object:172958}.",
	["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365}: Camping 101 od Brakkova táboráku v {zone:1411}",
	["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}, trenérka herbalismu, má obchod v Dragu.",
	["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404}: Camping 101 od Brakkova táboráku v {zone:1411}",
	["{npc:4047}: {npc:4049}, on the road into Stonetalon in the next guide"] = "{npc:4047}: {npc:4049}, na cestě do Stonetalonu v dalším návodu",
	["{npc:4551}, the bat handler"] = "{npc:4551}, správce netopýrů",
	["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}: nech si {item:16210}, převezme ho Podrig na příští zastávce v {area:228}, na levelu 22",
	["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}, obchodník se zbraněmi vedle správce netopýrů",
	["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}, trenér engineeringu, pracuje v {zone:1458}.",
	["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}: Camping 101 od táboráku {npc:265812} v Tirisfalu",
	["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}, trenér miningu, pracuje v {zone:1458}.",
	["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}: Camping 101 od táboráku {npc:265812} v Tirisfalu",
	["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}, trenér blacksmithingu, pracuje v {zone:1458}.",
	["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}: Camping 101 od táboráku {npc:265812} v Tirisfalu",
	["{npc:4949} stands in Grommash Hold. He offers {quest:98024} and {quest:93739} once {quest:95350} is handed in."] = "{npc:4949} stojí v Grommash Hold. Nabídne {quest:98024} a {quest:93739}, jakmile odevzdáš {quest:95350}.",
	["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, uvnitř Grommash Hold",
	["{npc:4949}: keep it, Thork at the Crossroads in the {zone:1413} guide"] = "{npc:4949}: nech si ho, Thork na Crossroads v návodu pro {zone:1413}",
	["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, prohlídka vůdců Hordy",
	["{npc:5204}, in the Apothecarium"] = "{npc:5204}, v Apothecariu",
	["{npc:5204}: Helbrim at the Crossroads, in the next guide"] = "{npc:5204}: Helbrim na Crossroads, v dalším návodu",
	["{object:1571}; upstairs"] = "{object:1571}; nahoře",
	["{object:1661} lies under the {area:153}, beside the zeppelin towers. {npc:2050} stands at the inn by the way down; {npc:7683} on the way down to the Apothecarium, where {npc:11044} and {npc:5204} stand beside {npc:2055}."] = "{object:1661} leží pod {area:153}, vedle zeppelinových věží. {npc:2050} stojí u hostince cestou dolů; {npc:7683} cestou dolů do Apothecaria, kde {npc:11044} a {npc:5204} stojí vedle {npc:2055}.",
	["{object:173016} is a few steps north."] = "{object:173016} je pár kroků na sever.",
	["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264} se odevzdává u {object:24776}, hrobu pár kroků jižně od vchodu do krypty, ne u osoby.",
	["{quest:829}: {quest:809} stands at {area:379}, on the next guide's road to the Crossroads"] = "{quest:829}: {quest:809} stojí u {area:379}, cestou do Crossroads v dalším návodu",
	["{quest:829}: {quest:832}, from the {item:4903} in {zone:1411}"] = "{quest:829}: {quest:832}, z {item:4903} v {zone:1411}",
}
t.guides["forever/horde/04-the-barrens"] = {
	["A few steps east of {npc:14242}'s tree, a small camp: two Encroaching Soldiers and the {npc:268623} for Logmar. The {npc:268623} is elite: grouping up is advised."] = "Pár kroků východně od stromu {npc:14242} je malý tábor: dva Encroaching Soldiers a {npc:268623} pro Logmara. {npc:268623} je elitní: doporučuje se skupina.",
	["Back down the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "Zpět dolů po {area:1076} k chýši {npc:4201}, pak na východ po cestě k {area:461}: {npc:4074} hlídkuje na cestě kousek východně od rozcestí, {npc:4073} na svazích dál na severovýchod pod skalou. Oba jsou osamělí shredder roboti; toulají se, tak jdi po cestě, dokud je nepotkáš.",
	["Back west to {npc:4201}' hut, on the way down to {area:2539}."] = "Zpět na západ k chýši {npc:4201}, cestou dolů do {area:2539}.",
	["Bael'dun fortress"] = "Pevnost Bael'dun",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["East along the road from {area:2539} to {npc:4049}'s camp."] = "Na východ po cestě z {area:2539} do tábora {npc:4049}.",
	["Fly to Crossroads"] = "Leť do Crossroads",
	["Fly to {area:1638}"] = "Leť do {area:1638}",
	["Fly to {area:1638} (without its flight path the arrow goes by {area:378} and {zone:1412}): two of its elders give quests worked on this guide's and the next guide's walks, and {npc:3419} takes Lydon's toxin."] = "Leť do {area:1638} (bez její letové trasy vede šipka přes {area:378} a {zone:1412}): dva z jejích stařešinů dávají questy, které se plní na trasách tohoto i dalšího návodu, a {npc:3419} vezme Lydonův toxin.",
	["Fly to {area:378}"] = "Leť do {area:378}",
	["Fly to {area:378}: {npc:2995} on {zone:1456}'s central rise, or the Crossroads' wind rider master if you start this guide there."] = "Leť do {area:378}: {npc:2995} na centrálním vyvýšení {zone:1456}, nebo mistr wyvern v Crossroads, pokud tenhle návod začínáš tam.",
	["Fly to {area:392}"] = "Leť do {area:392}",
	["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Jdi po silnici na sever směrem k {area:467}. Podél cesty se pasou Antlered Coursers; Sap Beasts, Twilight Runners a Fey Dragons se toulají lesy pod Peak a háj tam drží cenarionští druidi.",
	["Follow the road on west past {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Jdi po silnici dál na západ kolem tábora {npc:4049} do Stonetalonu: {npc:3995} čeká pod zemí v {area:2539}, u úpatí {area:1076}.",
	["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "Jdi po silnici na západ kolem Regtharových bunkrů: {npc:4049} táboří vedle ní na okraji Stonetalonu.",
	["Gaea Dirt Mounds"] = "Gaea Dirt Mounds",
	["Gaea Seeds"] = "Gaea Seeds",
	["Place the {item:5638} on the {object:19594}"] = "Polož {item:5638} na {object:19594}",
	["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south. Careful: the Burning Destroyers, Scorched Basilisks and Bloodfury Storm Witches here are level 27 and the valley floor is crowded: pull one at a time and keep to its edges."] = "Jihozápadně od Sun Rock leží spálené {area:465}. Zasaď Gaea Seeds do hlíny v hromádkách na dně údolí; ohniví elementálové dropují {item:16312}. Bloodfury Harpies a Ambushers hnízdí na severní straně, Slayers a Roguefeathers na jižní. Pozor: Burning Destroyers, Scorched Basilisks a Bloodfury Storm Witches tu mají level 27 a dno údolí je přeplněné: táhni je po jednom a drž se okrajů.",
	["The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them. {npc:3414} (30) and his Officers stand on the bottom floor: work the soldiers and riflemen on the upper levels and keep away from him.\nCareful: Riflemen (level 24-25) Shoot from 5-30 yd, so nearby ones can join a fight from range."] = "Bael'dun Soldiers, Riflemen a Officers hlídají pevnost na východní straně vykopávek; všechny tři předměty padají z nich. {npc:3414} (30) a jeho Officers stojí v nejspodnějším patře: pracuj na vojácích a střelcích v horních patrech a drž se od něj dál.\nPozor: Riflemen (level 24–25) střílejí z 5–30 yardů, takže blízcí se můžou přidat do boje na dálku.",
	["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock.\nCareful: Pridewings around the lake can aggro as a linked group."] = "Gaea Seeds leží v trávě kolem jižního břehu {area:464}, severně od Sun Rock.\nPozor: Pridewings kolem jezera můžou chytit aggro jako propojená skupina.",
	["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "Létající stroj trpaslíků stojí na své plošině uvnitř naleziště. Použij na něj {item:5021}, který ti dal {npc:3341}.",
	["The flight lands at {area:378}'s wind rider master. {npc:3433} stands at the north edge of the camp, {npc:3387} and {npc:3430} (in the cage) in the middle."] = "Let přistává u mistra wind riderů v {area:378}. {npc:3433} stojí na severním okraji tábora, {npc:3387} a {npc:3430} (v kleci) uprostřed.",
	["The flying machine"] = "Létající stroj",
	["The next guide flies to {area:2897}: hearth to {area:378} if your hearthstone is ready, or walk on east to the Crossroads' flight master."] = "Další návod letí do {area:2897}: pokud máš Hearthstone připravený, vrať se jím do {area:378}, jinak jdi dál na východ k letovému mistrovi v Crossroads.",
	["The road west"] = "Silnice na západ",
	["The road west past {npc:4049}'s camp"] = "Silnice na západ kolem tábora {npc:4049}",
	["To {area:378}"] = "Do {area:378}",
	["Up the {area:1076} to {npc:4201}' hut, where the road forks east to {area:461}: {npc:3442}'s orders are for him."] = "Nahoru po {area:1076} k chýši {npc:4201}, kde se cesta větví na východ k {area:461}: rozkazy od {npc:3442} jsou pro něj.",
	["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with {spell:1752}, so they can join a fight without warning."] = "Západně od Ganna drží Razormane {area:1701}. {npc:3436} je na východní straně, {npc:3434} na jihu, {npc:3435} na západním konci. Lok (25) a Warfrenzies (24–25) jsou o pár levelů nad tebou; po hřebeni občas chodí {npc:5859}, rare elite: nech ho být. Pathfinders a Stalkers dropují Backstabber, Seers Wand, Warfrenzies War Shield. Nad hřebenem létá {quest:885}, rare červený wind serpent: jeho pero spouští quest.\nPozor: Razormane Stalkers se pohybují ve stealthu a útočí {spell:1752}, takže se můžou bez varování přidat do boje.",
	["{area:378} flight master"] = "letový mistr {area:378}",
	["{area:465}: kill these as you meet them"] = "{area:465}: zabíjej je, jak na ně narazíš",
	["{area:718} quests still in your log: {npc:3446} stands beside the WANTED poster, Bigglefuzz on the dock by the flight master."] = "Questy z {area:718}, které máš ještě v logu: {npc:3446} stojí vedle plakátu WANTED, Bigglefuzz na molu u letového mistra.",
	["{item:5736}, from {quest:1096}"] = "{item:5736}, od {quest:1096}",
	["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: Glittering Sunstones z harpyjí Bloodfury",
	["{npc:11860}: Grish is at the {area:1718}, on the next guide's way into {zone:1441}"] = "{npc:11860}: Grish je u {area:1718}, cestou dalšího návodu do {zone:1441}",
	["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, vedle {npc:11862}",
	["{npc:11862}, up on the ledge"] = "{npc:11862}, nahoře na římse",
	["{npc:11862}: {npc:12736} at Zoram'gar, next guide"] = "{npc:11862}: {npc:12736} v Zoram'garu, další návod",
	["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864} stojí u ohně uvnitř Sun Rocku: Makabova zpráva, že Kaya žije, je pro ni.",
	["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, nahoře ve stromě kousek východně od {npc:3341}",
	["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "{npc:2995}, mistr wind riderů, stojí na centrálním návrší: vezmi si jeho letovou trasu, pokud ji nemáš. {npc:3024} a {npc:4721} stojí kousek na východ od něj.",
	["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}: {object:667362} roste v {area:464}, u Sun Rock",
	["{npc:3341} walks around {area:1701}: look inside the circle on the map"] = "{npc:3341} chodí po {area:1701}: hledej uvnitř kruhu na mapě",
	["{npc:3341} walks the road south toward {area:359}, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. {npc:14242} sits up in the tree just east of the road at 47.9,77.5."] = "{npc:3341} chodí po cestě na jih k {area:359}, zhruba mezi 46,75 a 46,81: když není u šipky, jdi po cestě, dokud ho nepotkáš. {npc:14242} sedí nahoře ve stromě kousek východně od cesty na 47.9,77.5.",
	["{npc:3375} walks around {area:359}: look inside the circle on the map"] = "{npc:3375} chodí po {area:359}: hledej uvnitř kruhu na mapě",
	["{npc:3419} stands in the {area:2197}, the caves under {area:1640}, west of {npc:2995}."] = "{npc:3419} stojí v {area:2197}, jeskyních pod {area:1640}, západně od {npc:2995}.",
	["{npc:3419}: the {item:5638} goes on the {object:19594} at {area:461}, on this guide's Windshear trip"] = "{npc:3419}: {item:5638} patří na {object:19594} v {area:461}, na výpravě do Windshear v tomhle návodu",
	["{npc:3428}, west of the north gate"] = "{npc:3428}, západně od severní brány",
	["{npc:3429}, at the top of the tower"] = "{npc:3429}, na vrcholu věže",
	["{npc:3430}, in the cage"] = "{npc:3430}, v kleci",
	["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, na severním okraji tábora",
	["{npc:3442} stands beside the flight master you land at. His new orders go back to {npc:4201} on the {area:1076}, later in this guide."] = "{npc:3442} stojí vedle letového mistra, u kterého přistaneš. Jeho nové rozkazy jdou zpátky k {npc:4201} na {area:1076}, později v tomhle návodu.",
	["{npc:3442}: for {npc:4201}, on the way up the {area:1076}"] = "{npc:3442}: pro {npc:4201}, po cestě nahoru na {area:1076}",
	["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}: {quest:1094}, od {npc:4201}",
	["{npc:3665}, on the dock"] = "{npc:3665}, na molu",
	["{npc:3995}, below ground"] = "{npc:3995}, pod zemí",
	["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way back down from Sun Rock"] = "{npc:4049}: {npc:4074} a {npc:4073} se potulují východně od {npc:4201}, po cestě zpátky dolů ze Sun Rock",
	["{npc:4128} walks around {area:1156}: look inside the circle on the map"] = "{npc:4128} chodí po {area:1156}: hledej uvnitř kruhu na mapě",
	["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "Další quest od {npc:4198}, Ordanus, je na aliančí straně {zone:1440}. Přeskoč ho.",
	["{npc:4198}, outside the gate"] = "{npc:4198}, před branou",
	["{npc:4201}, inside"] = "{npc:4201}, uvnitř",
	["{npc:4201}: {npc:4202}, at the top of the Venture Co. tower on {area:461}"] = "{npc:4201}: {npc:4202}, na vrcholu věže Venture Co. na {area:461}",
	["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}: lahvička je ze {zone:1440}, další návod",
	["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, velký threshadon, plave na mělčinách u {area:391}, východně od {npc:3388}.",
	["{quest:874} camps on the shore just north of {area:392}'s flight master."] = "{quest:874} táboří na břehu kousek severně od letového mistra v {area:392}.",
	["{zone:1442}: kill these as you meet them"] = "{zone:1442}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/horde/05-stonetalon-mountains"] = {
	["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "Zpět na cestě na jih. Tam, kde se stáčí na východ do {area:287}, čeká {npc:2214} v {area:285}.",
	["Back to the outpost."] = "Zpět na stanoviště.",
	["Back up to {npc:2995} on the central rise and fly to {area:1637}."] = "Zpět nahoru k {npc:2995} na střední vyvýšenině a leť do {area:1637}.",
	["Below ground"] = "Pod zemí",
	["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177844}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "Dolů po cestě přes Silverpine k {area:228}: od věží zeppelinů na jih přes Tirisfal; od {object:177844} na jihovýchod od pobřeží k cestě. {npc:2121} a {npc:1937} stojí u vchodu do krypty.",
	["Druid trainer"] = "Trenér druidů",
	["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Hlavy dropuje každá naga Wrathtail na pobřeží severně od stanoviště.",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:1637} from the {area:2897} flight master."] = "Leť do {area:1637} od letového mistra {area:2897}.",
	["Fly to {area:1638}"] = "Leť do {area:1638}",
	["Fly to {area:378}"] = "Leť do {area:378}",
	["For your {area:153} run: the zeppelin lands beside the ruins. Walk into the {zone:1458} through them and down to the {object:36126}: {npc:266484} stands there, near {npc:10181}."] = "Pro tvůj průchod {area:153}: zeppelin přistává vedle ruin. Projdi jimi do {zone:1458} a dolů k {object:36126}: {npc:266484} stojí tam, blízko {npc:10181}.",
	["For your {area:236} run, at the end of the {area:287} guide: {npc:1952} stands below ground in the crypt."] = "Pro tvůj průchod {area:236}, na konci návodu {area:287}: {npc:1952} stojí pod zemí v kryptě.",
	["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "Od Seerethova tábora zamiř na severovýchod přes {zone:1413} k silnici severně od Crossroads; rogue, kteří jdou od Fizzulovy věže, k ní míří na západ. {npc:8582} stojí na strážní věži {area:1703}, kde silnice vstupuje do {zone:1440}.",
	["From the zeppelin towers, run south into Silverpine and west past the {area:240} to the coast: the {object:177844} lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the {item:15882} for Trial of the Sea Lion. Then on to the {area:228}."] = "Od věží zeppelinů běž na jih do Silverpine a na západ kolem {area:240} k pobřeží: {object:177844} tam leží na dně velmi hluboké vody, vedle vzduchové průrvy, kde se dá dýchat. Cestou dolů hlídej dech. Je v ní {item:15882} pro Trial of the Sea Lion. Pak dál k {area:228}.",
	["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "Z {area:378} jdi po silnici na západ branou do {zone:1412}, pak na sever kolem {area:222} do {zone:1456}; nahoru tě vyveze výtah u úpatí útesů.",
	["Head west along the main road across {zone:1440}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west: {npc:12719} and {npc:12717} stand around it, the {npc:12863} beside the flight master. Its other quests, Thistlefur's among them, are for the next visit, at 26."] = "Jdi po hlavní silnici na západ přes {zone:1440}, kolem {area:415} (Aliance: drž se silnice), k pobřeží. {area:2897} je na {area:414} na severozápadě: kolem stojí {npc:12719} a {npc:12717}, {npc:12863} vedle letového mistra. Ostatní questy odtud, mezi nimi Thistlefurův, jsou na další návštěvu, v 26.",
	["If you did {quest:2478} with a group, {npc:3401} in the {object:172960} takes it now."] = "Pokud jsi {quest:2478} dělal se skupinou, {npc:3401} v {object:172960} ho teď převezme.",
	["Into {area:287}"] = "Do {area:287}",
	["Into {zone:1440}"] = "Do {zone:1440}",
	["Naga brazier"] = "Nagí žároviště",
	["Naga heads"] = "Hlavy nag",
	["Out of the ruins, take the road south through Tirisfal into {zone:1421} and on to the {area:228}."] = "Z ruin jdi po silnici na jih přes Tirisfal do {zone:1421} a dál k {area:228}.",
	["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Vyveď {npc:271181} od {npc:267214} z rokle na hlavní cestu do čtyř minut; když se channel přeruší, požádej {npc:267214} znovu.",
	["The quest hands you a {item:210713}: use it beside the {object:645153} to offer your blood, then kill the elite spirit that answers.\n{quest:95883} is elite: grouping up is advised."] = "Quest ti dá {item:210713}: použij ho vedle {object:645153}, abys obětoval krev, pak zabij elite ducha, který se ozve.\n{quest:95883} je elite: doporučuje se skupina.",
	["The road east to {area:285}"] = "Silnice na východ do {area:285}",
	["The road north to {area:431}"] = "Silnice na sever do {area:431}",
	["To {zone:1456}"] = "Do {zone:1456}",
	["{area:2897} flight master"] = "letový mistr {area:2897}",
	["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers Ashenvale Outrunners: leave it for the next {zone:1440} visit, at 26."] = "{area:431} je kousek na sever po silnici. Když přicházíš od jihu, je nejdřív letový mistr a tabule lovu {npc:12696} u {area:428}, pak obchodníci. {npc:12867} v dřevařském táboře nabízí Ashenvale Outrunners: nech to na příští návštěvu {zone:1440}, na levelu 26.",
	["{item:15882}, from the {object:177844}"] = "{item:15882}, od {object:177844}",
	["{npc:12696}'s hunt targets Ursangous and Shadumbra are for the next {zone:1440} visit, at 26; Sharptalon (31) only from level 30."] = "Lovecké cíle od {npc:12696}, Ursangous a Shadumbra, jsou na příští návštěvu {zone:1440}, na 26; Sharptalon (31) až od levelu 30.",
	["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads {npc:12719} wants."] = "{npc:12717} jde po pláži na sever k nagímu ohništi. Uhas ohniště a pak ho chraň během vln nag, dokud Vorsha nepadne; nagy Wrathtail dropují hlavy, které chce {npc:12719}.",
	["{npc:12717}: take it last, his escort starts at once"] = "{npc:12717}: vezmi si ho jako poslední, jeho doprovod začne hned",
	["{npc:1952}, below ground"] = "{npc:1952}, pod zemí",
	["{npc:271181}, on the road"] = "{npc:271181}, na cestě",
	["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:4046} stands on {area:1639} to the east; {npc:3419} in the {area:2197}, the caves under {area:1640} to the west."] = "{npc:2995}, mistr wind riderů, stojí na centrálním návrší: vezmi si jeho letovou trasu, pokud ji nemáš. {npc:4046} stojí na {area:1639} na východě; {npc:3419} v {area:2197}, jeskyních pod {area:1640} na západě.",
	["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} v {zone:1412}; v {zone:1454} druidský trenér není",
	["{npc:3419}: her note is for {npc:2216} in {area:272}, next guide"] = "{npc:3419}: její vzkaz je pro {npc:2216} v {area:272}, další návod",
	["{quest:1063} first: fly to {area:1638} from the {area:2897} flight master. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {area:1638}'s flight path takes you on to {zone:1454}."] = "Nejdřív {quest:1063}: leť do {area:1638} od letového mistra v {area:2897}. {npc:4046} a {npc:3419} tě pošlou za {npc:2216} do {area:272}, základny dalšího návodu, a letová trasa z {area:1638} tě vezme dál do {zone:1454}.",
	["{quest:1063} first: fly to {area:378} from the {area:2897} flight master and walk on to {zone:1456}. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {zone:1456}'s flight path takes you on to {zone:1454}."] = "Nejdřív {quest:1063}: leť do {area:378} od letového mistra v {area:2897} a dojdi do {zone:1456}. {npc:4046} a {npc:3419} tě pošlou za {npc:2216} do {area:272}, základny dalšího návodu, a letová trasa z {zone:1456} tě vezme dál do {zone:1454}.",
	["{quest:2478} is for level 23 or more: the tower's drones are 25 and Gallywix a 23 elite. Do it when you can, with a group, from the Class guide Poisons (Horde)."] = "{quest:2478} je pro level 23 a víc: drony ve věži jsou 25 a Gallywix elite na 23. Udělej ho, až to půjde, se skupinou, z class návodu Poisons (Horda).",
	["{quest:92421}: the {item:268580}, inside"] = "{quest:92421}: {item:268580}, uvnitř",
	["{zone:1421}: kill these as you meet them"] = "{zone:1421}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/horde/06-hillsbrad-foothills"] = {
	["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "Po vrácení Mission: Possible But Not Probable Shenthulovi přines {quest:2479} k {npc:2391} v {area:272}. Zůstaň vedle něj, dokud se nesplní cíl vaření, pak odevzdej navazující quest a nauč se Poisons. Dokonči ho, i když je Zanzilův jed už odstraněný; samotné odstranění debuffu dovednost nenaučí.",
	["Back north up the road to the {area:228}: {npc:1938} stands just north of Allister."] = "Zpět na sever po cestě k {area:228}: {npc:1938} stojí kousek severně od Allistera.",
	["Back to the Crossroads"] = "Zpět do Crossroads",
	["Bears, creepers and lions"] = "Medvědi, plazivci a lvi",
	["Careful: When one lion is attacked, nearby lions come to its aid, and the Vicious Black Bears sharing those fields can also join the fight."] = "Pozor: Když zaútočíš na jednoho lva, přijdou mu na pomoc lvi kolem a přidat se můžou i Vicious Black Bears, kteří s nimi sdílejí pole.",
	["Cast {spell:18960}. Join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. Než se zastavíš u {npc:11802} v {area:2361}, spoj obě poloviny přívěsku u {area:2362} na severozápadním břehu jezera. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Darthalia's next {quest:528} and Lydon's Elixir of Agony are for the next visit, at about 30."] = "Darthaliin další {quest:528} a Lydonův Elixir of Agony jsou na další návštěvu, kolem 30.",
	["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues, Watchmen and Shadow Mages hold the camps along the way; the Shadow Mages carry Lydon's Vials of Innocent Blood."] = "Drull a {npc:2238} jsou přikovaní v budovách na nádvoří {area:275}. Jejich zámky potřebují klíče: {npc:2427} nese {item:3467} a {npc:2428} {item:3499}, oba v pevnosti. Zabij je a pak otevři oba zámky.\nZ {area:272} jdi na jihovýchod do kopců cestou k {area:275}. Tábory po cestě drží Rogues, Watchmen a Shadow Mages; Shadow Mages nesou Lydonovy Vials of Innocent Blood.",
	["Drull's ball and chain"] = "Drullova koule s řetězem",
	["Fill the {item:7768} at the {object:107045} beside the inn"] = "Naplň {item:7768} u {object:107045} vedle hostince",
	["Fly on from {npc:2226}, the bat handler just east of the crypt, to the {area:1497}."] = "Leť dál od {npc:2226}, správce netopýrů kousek východně od krypty, do {area:1497}.",
	["Fly to the {area:1497}"] = "Leť do {area:1497}",
	["For your {area:236} run: {npc:1952} stands below ground in the crypt, {npc:1938} just north of Allister."] = "Pro tvůj průchod {area:236}: {npc:1952} stojí pod zemí v kryptě, {npc:1938} kousek severně od Allistera.",
	["From {area:272} fly to the {area:228}: {npc:2121} stands by the crypt entrance."] = "Z {area:272} leť do {area:228}: {npc:2121} stojí u vchodu do krypty.",
	["Hadrec and {npc:1938}"] = "Hadrec a {npc:1938}",
	["Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."] = "Nedokončený řetězec jedů? Pokračuj ve své aktuální fázi v class návodu Poisons (Horde); dokončené questy se nemusí začínat znovu. Sežeň skupinu na Gallywixe, dokonči navazující quest u Hinotta a pak se vrať k tomuto levelovacímu návodu.",
	["Take {quest:31} from {npc:11802}, who stands upstairs in his building. Then {npc:11798} in {area:2361} flies druids to {area:1638}: {npc:3033} is on {area:1639}."] = "Vezmi {quest:31} od {npc:11802}, který stojí v patře své budovy. Pak {npc:11798} v {area:2361} letí s druidy do {area:1638}: {npc:3033} je na {area:1639}.",
	["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms. Careful: Kirin Tor Guards (55) stand north of the farms, on the road up toward Alterac: keep to the fields."] = "Farmy východně od města {area:287}. {npc:232} pracuje na poli u severního statku, {npc:2403} na tom dál na jihovýchod; Farmhands a Farmers jsou všude. {npc:2451} se stará o pole jižně od farem. Pozor: Severně od farem, na silnici nahoru k Alteracu, stojí Kirin Tor Guards (55): drž se na polích.",
	["The middle of {zone:1454}"] = "Střed {zone:1454}",
	["Train and restock in the {zone:1458} before the zeppelin."] = "Před zeppelinem se vytrénuj a doplň zásoby v {zone:1458}.",
	["Train before you fly on: the next guide flies from here."] = "Než poletíš dál, vytrénuj se: další návod letí odsud.",
	["Train with {npc:3033}. {npc:3419}, in the {area:2197} under {area:1640}, takes Lydon's toxin if you carry it. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "Vytrénuj se u {npc:3033}. {npc:3419} v {area:2197} pod {area:1640} si vezme Lydonův toxin, jestli ho neseš. Než poletíš dál, {npc:3024} a {npc:4721}, kousek na východ od mistra wind riderů, ti dají dva questy, které se plní cestou v dalších návodech; pak leť do Crossroads, kde začíná další návod.",
	["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "Západně od Tarren Mill se po kopcích cestou dolů k farmám toulají Gray Bears, Forest Moss Creepers a Starving Mountain Lions. Creepeři dropují {item:3477} vzácně; potřebuješ jen jeden.",
	["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Když už jsi tady: nauč se Polearms u {npc:11870} ({object:36070}, 1 gold); u zbraně na blízko huntera jde hlavně o staty a obouručky jich mají nejvíc.",
	["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); two-handers level a Warrior fastest."] = "Když už jsi tady: nauč se Polearms u {npc:11870} ({object:36070}, 1 gold); s obouručkami warrior levluje nejrychleji.",
	["While you're here: learn Swords from {npc:11870} ({object:36070}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Když už jsi tady: nauč se Swords u {npc:11870} ({object:36070}, 10 silver); s mečem v hlavní ruce rogue levluje spolehlivě.",
	["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Paladin fastest."] = "Když už jsi tady: nauč se {spell:202} u {npc:11870} ({object:36070}, 10 silver); s obouručkami paladin levluje nejrychleji.",
	["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Warrior fastest."] = "Když už jsi tady: nauč se {spell:202} u {npc:11870} ({object:36070}, 10 silver); s obouručkami warrior levluje nejrychleji.",
	["{area:236} is a dungeon for a group of five, about levels 20 to 30, and a full run takes about an hour. Follow the road south from the {area:228}: the keep stands on the hill above {area:204}, its gate at the top of the path.\nInside: Rethilgore first; the Deathstalker freed from the cells after him opens the courtyard door, and {npc:4444} lies just inside the courtyard, to the right: hand {quest:1098} in to him there. Then {npc:3886}, {npc:3887}, {npc:4278}, {npc:4279}, {npc:4274} and {npc:3927}; {npc:4275} at the top drops his head for {npc:1938}."] = "{area:236} je dungeon pro skupinu pěti, zhruba level 20 až 30, celý průchod trvá asi hodinu. Jdi po silnici na jih od {area:228}: pevnost stojí na kopci nad {area:204}, brána je na konci cesty nahoře.\nUvnitř: nejdřív Rethilgore; Deathstalker osvobozený z cel po něm otevře dveře na nádvoří a {npc:4444} leží hned na nádvoří vpravo: odevzdej mu tam {quest:1098}. Pak {npc:3886}, {npc:3887}, {npc:4278}, {npc:4279}, {npc:4274} a {npc:3927}; {npc:4275} nahoře dropne svou hlavu pro {npc:1938}.",
	["{area:272} flight master"] = "letový mistr {area:272}",
	["{area:272} is your base for this guide: you come back here between each loop. Everyone stands around the town square."] = "{area:272} je tvoje základna pro tenhle návod: mezi každým okruhem se sem vracíš. Všichni stojí kolem náměstí.",
	["{area:275}: kill these as you meet them"] = "{area:275}: zabíjej je, jak na ně narazíš",
	["{area:286}: kill these as you meet them"] = "{area:286}: zabíjej je, jak na ně narazíš",
	["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: použij polovinu u {area:2362}",
	["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} v {area:2361} tam vozí druidy",
	["{npc:1952}, below ground"] = "{npc:1952}, pod zemí",
	["{npc:2216}, inside"] = "{npc:2216}, uvnitř",
	["{npc:2229}, inside"] = "{npc:2229}, uvnitř",
	["{npc:2261} walks around here: look inside the circle on the map"] = "{npc:2261} chodí po okolí: hledej uvnitř kruhu na mapě",
	["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}: {quest:97538}, Mirkweed v {area:464} u Sun Rock",
	["{npc:3419}: the {item:5638}, for {area:461} in the next guide"] = "{npc:3419}: {item:5638}, pro {area:461} v dalším návodu",
	["{npc:4606} stands in the {object:36070}."] = "{npc:4606} stojí v {object:36070}.",
	["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}: {quest:1195}, lahvička od Laughing Sisters ve {zone:1440}",
	["{quest:1014}: the {item:5442}"] = "{quest:1014}: {item:5442}",
}
t.guides["forever/horde/07-ashenvale"] = {
	["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "Kousek severně od táborů Galaků vede jeskyně {area:1557} dolů do nejhlubší komory, kde hoří {object:20807}. Použij na něj {item:5868} a hned lootni {item:5869}: plamen zůstane zhasnutý jen krátce, a když se znovu rozhoří, lahvička je pryč. Pak na východ k mesě {npc:2986}.\nPozor: u pánve stojí dva Galak Flame Guards (30) a jeskyní chodí kentauří strážce: než plamen uhasíš, odlákej je po jednom.",
	["Back east past {area:2237} to {area:484}."] = "Zpět na východ kolem {area:2237} do {area:484}.",
	["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Zpět na jih do tábora, pak nahoru do {zone:1456} na let do {area:378}.",
	["Back south-west to {area:421}. {npc:12759}, a corrupted water elemental, drifts around the lake's island and under the water. She drops the {item:16408} only once you have {quest:25} from {npc:12737}; it starts a quest for Splintertree."] = "Zpět na jihozápad do {area:421}. {npc:12759}, zkažený vodní elementál, se vznáší kolem ostrova jezera a pod vodou. {item:16408} dropne, jen když máš {quest:25} od {npc:12737}; začíná quest pro Splintertree.",
	["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Zpět k {npc:12867} do dřevorubeckého tábora, na cestě na sever do Splintertree.",
	["Back west to Zoram'gar from Thistlefur before heading east for good."] = "Zpět na západ do Zoram'garu z Thistlefuru, než se natrvalo vydáš na východ.",
	["Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Befouled Water Elementals se vznášejí kolem břehů jezera; altánek stojí na ostrově s výhledem na stanoviště Aliance.",
	["Below ground"] = "Pod zemí",
	["Class trainer"] = "Trenér povolání",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["East along the road from Seereth's camp to the Crossroads' wind rider master, and fly to {area:2897}. If your hearthstone is ready, hearth to {area:378} and fly from there instead."] = "Na východ po cestě ze Seerethova tábora k mistrovi wyvern v Crossroads a leť do {area:2897}. Pokud máš připravený Hearthstone, hearthni do {area:378} a leť odtamtud.",
	["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs."] = "Východně od Zoram'garu plní vesnici a kopce kolem jejich doupěte furbolgové Thistlefur.\nPozor: Shaman na 15 % zdraví nebo méně uteče hledat pomoc, což může natáhnout další furbolgy.",
	["Felmusk satyrs"] = "Satyrové Felmusk",
	["Fly to {area:1638}"] = "Leť do {area:1638}",
	["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "Leť do {area:1638} ze Zoram'gar. Pokud její letovou trasu neznáš, leť do {area:378} a jdi na sever přes {zone:1412}.",
	["Fly to {area:2897}"] = "Leť do {area:2897}",
	["Fly to {area:378}"] = "Leť do {area:378}",
	["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Jdi po hlavní silnici na východ kolem {area:415} (Aliance: drž se silnice). {npc:12678}, velký grizzly, se potuluje po {area:418} jižně od silnice, západně od {area:421}. Jeho tlapa začíná další lovecký quest.",
	["For your {area:2797} run, in the same tunnels as the Sapphires: {npc:12736}'s ruins errand. Look for a group now if you have none yet."] = "Pro tvůj průchod {area:2797}, ve stejných tunelech jako Sapphires: pochůzka do ruin od {npc:12736}. Jestli ještě skupinu nemáš, hledej ji teď.",
	["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "Od {area:2360} zamiř na severovýchod k dřevařskému táboru Warsong u silnice: {npc:12867} stojí tam.",
	["Galak centaurs"] = "Kentauři Galak",
	["Gazebo"] = "Altánek",
	["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Gloomrise Toxin Samples, z Gnawed Corpses",
	["Grimtotem camps below {area:2097}"] = "Tábory Grimtotem pod {area:2097}",
	["Level 28"] = "Level 28",
	["Level 29"] = "Level 29",
	["Pesterhide Snarlers"] = "Pesterhide Snarlers",
	["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Sjeď výtahem dolů a pak po silnici na východ kaňony do {area:484}, vesnice Taurenů na vrcholu stolových hor. Její výtah je na severní straně.",
	["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Promluv s {npc:3057} v {area:1638}: {quest:93739}",
	["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Sjeď výtahem dolů. Vejce leží v hnízdě na dně kaňonu na jednom ze tří míst: jihovýchodně od mes (52.3,55.2), na východě (56.4,50.4) nebo na jihozápadě (37.6,56.1).",
	["Talk to {npc:3057}"] = "Promluv s {npc:3057}",
	["The Earthen Ring"] = "The Earthen Ring",
	["The Earthen Ring camp and its three quests stand up on {area:17045}, north of {zone:1456}. Fly to {zone:1456} if you know its flight path and take a lift down, else fly to {area:378} and walk north through {zone:1412}; the arrow then leads round to the plateau's north end and up onto it."] = "Tábor Earthen Ring a jeho tři questy jsou nahoře na {area:17045}, severně od {zone:1456}. Pokud znáš letovou trasu do {zone:1456}, leť tam a sjeď výtahem dolů, jinak leť do {area:378} a jdi na sever přes {zone:1412}; šipka tě pak dovede kolem k severnímu konci plošiny a nahoru na ni.",
	["The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}. From {zone:1456}, take a lift down; coming on foot from {area:378}, keep north past the bluffs."] = "Tábor Earthen Ring stojí severně od útesů: {npc:264074}, {npc:264072} a {npc:259118}. Z {zone:1456} sjeď výtahem dolů; když jdeš pěšky z {area:378}, drž se na sever kolem útesů.",
	["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Furbolgové Foulweald drží lesy východně od {area:421}, jižně od cesty. Polož {item:16972} na {object:178206} a hlídej ho: furbolgové ho přijdou strhnout. {npc:12918} přijde poslední; jeho totem padá do koše.",
	["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him. Careful: storm elementals roam the canyon floor around the camps: Stormheart (30), the Ravaging Tempests (40) and {npc:216463} (38), all elite. Keep clear of them."] = "Tábory Galak zaplňují kaňon severně od Freewindu; v každém táboře jsou Scouts, Wranglers i Windchasers. Mezi tábory chodí po dlouhé trase osamělý {npc:10617}: když ho potkáš, zabij ho, jeho dopis spustí quest pro {area:2237}. Nečekej na něj. Pozor: po dně kaňonu kolem táborů se potulují bouřní elementálové: Stormheart (30), Ravaging Tempests (40) a {npc:216463} (38), všichni elite. Drž se od nich dál.",
	["The fountain stands in the middle of the {area:418}, where {npc:12678} roams: use the {item:7767} there."] = "Fontána stojí uprostřed {area:418}, kde se potuluje {npc:12678}: použij tam {item:7767}.",
	["The next guide opens with Korran's The Swarm Grows at the Crossroads, offered from level 29. Short of 29? The Pesterhide Snarlers (28-29) prowl the canyon floor just north-west of {area:484}: kill them until level 29. Or, with a group, run the {area:2797} dungeon instead."] = "Další návod začíná Korranovým The Swarm Grows v Crossroads, nabízeným od levelu 29. Chybí ti do 29? Na dně kaňonu kousek severozápadně od {area:484} se potulují Pesterhide Snarlers (28–29): zabíjej je do levelu 29. Nebo se skupinou místo toho projdi dungeon {area:2797}.",
	["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "Noční elfové {quest:6503} (23–24) slídí lesem jižně a jihovýchodně od dřevařského tábora; používají stealth, tak si jich všímej.",
	["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "Cesta k Sapphires vede potopenými ruinami na severním konci pobřeží: sejdi po schodech dolů do jámy.",
	["Thistlefur Hold"] = "Thistlefur Hold",
	["Underwater"] = "Pod vodou",
	["Warsong lumber camp"] = "Dřevařský tábor Warsong",
	["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "Západně od Freewind tábory Grimtotem pod {area:2097}. Secret Notes jsou v Document Chests v jihovýchodním, jihozápadním a severozápadním táboře.",
	["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "Západně od Mystral Lake se po {area:418} toulá {npc:12678}, velký grizzly: jeho tlapa ti teď padá.",
	["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom. Highperch Patriarchs (30-31) and the rare Heartrazor (32) nest here too: pull around them."] = "Západně od Whitereach hnízdí wyverny na útesech {area:482}; vejce leží v hnízdech. {npc:10427} čeká na východní straně hnízdiště: osvoboď ho a udrž ho naživu cestou zpátky do {area:2237}.\nPozor: nad hlavou létají wyverny na levelu 28–29 a můžeš je pullnout bez varování. Jakmile dole minuš první sloup, může tě přepadnout skupina tří wyvern. Hnízdí tu i Highperch Patriarchs (30–31) a rare Heartrazor (32): pulluj tak, abys je obešel.",
	["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Když už jsi tady: nauč se {spell:199} u {npc:11869} (10 silver); s obouručkami warrior levluje nejrychleji.",
	["grind on {npc:10759}"] = "grinduj na {npc:10759}",
	["grind on {npc:4249}"] = "grinduj na {npc:4249}",
	["{area:17044}: kill these as you meet them"] = "{area:17044}: zabíjej je, jak na ně narazíš",
	["{area:2797} is a dungeon for a group of five, about levels 22 to 30, and a full run takes about an hour. Its portal is a little further along the tunnels you are in, past the Sapphires.\nInside: the {object:177964} lies under the water of the Moonshrine Ruins' pool, beneath the walkway (clear the crabs first): open it for the {item:16762}, and {quest:6922} comes; open the {item:16782} he drops for a quest for {npc:12736}. The Tide Priestesses sometimes drop a {item:16790}: open it for another quest for {npc:12736}. {npc:4787}, by a campfire in an underwater side room off Ghamoo-ra's room, offers Blackfathom Villainy ({npc:4832}' head, for {npc:9087} on {zone:1456}'s {area:1639})."] = "{area:2797} je dungeon pro skupinu pěti, zhruba level 22 až 30, celý průchod trvá asi hodinu. Portál je kousek dál v tunelech, ve kterých jsi, za Sapphires.\nUvnitř: {object:177964} leží pod hladinou jezírka v Moonshrine Ruins, pod lávkou (nejdřív vyčisti kraby): otevři ho kvůli {item:16762} a přijde {quest:6922}; otevři {item:16782}, který dropne, a dostaneš quest pro {npc:12736}. Tide Priestesses občas dropnou {item:16790}: otevři ho kvůli dalšímu questu pro {npc:12736}. {npc:4787} u ohně v podvodní postranní místnosti vedle místnosti Ghamoo-ry nabízí Blackfathom Villainy (hlava {npc:4832} pro {npc:9087} v {area:1639} na {zone:1456}).",
	["{area:2797} ruins"] = "Ruiny {area:2797}",
	["{area:2897} flight master"] = "letový mistr {area:2897}",
	["{area:418} fountain"] = "Fontána v {area:418}",
	["{area:484}'s lift"] = "Výtah v {area:484}",
	["{area:485} detour warning: the arrow may miss the path up {area:2097}. If you are on the canyon floor, follow the path and rope bridges up {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Upozornění k objížďce u {area:485}: šipka může minout cestu nahoru na {area:2097}. Pokud jsi na dně kaňonu, jdi po cestě a provazových mostech nahoru na {area:2097}. {npc:10646} je držena v zajetí vedle {npc:10896} (29): nejdřív vyčisti stráže a {npc:10896}, pak ji osvoboď a chraň cestou dolů; po cestě na tebe zaútočí přepadovci Grimtotem.",
	["{item:5869}, from the {object:20807}"] = "{item:5869}, od {object:20807}",
	["{npc:10617}'s {quest:4881}, if you meet him"] = "{quest:4881} od {npc:10617}, pokud ho potkáš",
	["{npc:10645}, inside"] = "{npc:10645}, uvnitř",
	["{npc:11116}, beside {npc:4877}"] = "{npc:11116}, vedle {npc:4877}",
	["{npc:12576} and {npc:10079} wait at the top of the {area:485}: Maggran's letter is for {npc:12576}, and Moonhorn's message goes down to {area:484} with you."] = "{npc:12576} a {npc:10079} čekají nahoře na {area:485}: Maggranův dopis je pro {npc:12576} a Moonhornovu zprávu si vezmeš s sebou dolů do {area:484}.",
	["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, stínová panteřice, slídí po lesích kolem {area:426}, západně od tábora Felmusk. Její hlava začíná další lovecký quest.",
	["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696} spravuje loveckou tabuli v {area:428}, u letového mistra: vezmi si {quest:6383} a hned ho odevzdej zpět. {npc:12678}, {npc:12676} a {npc:12677} dropnou trofeje až potom.",
	["{npc:12696}: {quest:247}, once {quest:2} is in"] = "{npc:12696}: {quest:247}, jakmile odevzdáš {quest:2}",
	["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: jen pokud neseš stránky manuálu",
	["{npc:12721}: the troll charms are in Thistlefur Hold, east of the outpost"] = "{npc:12721}: trollí amulety jsou v Thistlefur Hold, východně od stanoviště",
	["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} pak nabídne quest do {area:2797}; nech ho být, pokud nemáš skupinu.",
	["{npc:12736} then offers the next part, {quest:6564}: it is for a second run, so leave it."] = "{npc:12736} pak nabídne další část, {quest:6564}: ta je na druhý průchod, tak ji nech být.",
	["{npc:12736}, {npc:12757} and {npc:12721} stand in the outpost."] = "{npc:12736}, {npc:12757} a {npc:12721} stojí na stanovišti.",
	["{npc:12757}: a banner defence in the Foulweald, east of {area:421}: furbolg waves, then {npc:12918}"] = "{npc:12757}: obrana praporu ve Foulweald, východně od {area:421}: vlny furbolgů, pak {npc:12918}",
	["{npc:12818}, below ground"] = "{npc:12818}, pod zemí",
	["{npc:12837}, inside the inn"] = "{npc:12837}, uvnitř hostince",
	["{npc:264082} sits at the north end of {area:17044}; her {item:273658} starts {quest:96294}. {npc:264082} is elite: grouping up is advised."] = "{npc:264082} sedí na severním konci {area:17044}; její {item:273658} spouští {quest:96294}. {npc:264082} je elite: doporučuje se skupina.",
	["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} stojí na vrcholu stolové hory východně od táborů Galak. Kvůli {quest:1149} sejdi z konce prken vedle něj: přistaneš bezpečně.",
	["{npc:2986}, below ground"] = "{npc:2986}, pod zemí",
	["{npc:2986}: {npc:4490}, in the harpy den west of the post"] = "{npc:2986}: {npc:4490}, v harpyjím doupěti západně od stanoviště",
	["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024} stojí vedle {npc:4721}, východně od {npc:2995}.",
	["{npc:3419} stands in the {area:2197}, the caves under {area:1640}, west of {npc:2995}."] = "{npc:3419} stojí v {area:2197}, jeskyních pod {area:1640}, západně od {npc:2995}.",
	["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721} stojí kousek na východ od {npc:2995}.",
	["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}: {npc:4722} v {area:484}, později v tomhle návodu",
	["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722} stojí v {area:484}: naplněná lahvička od {npc:4721} je pro něj.",
	["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722}: {object:20807} v {area:1557}, mezi tábory Galak",
	["{npc:4877}'s two harpy quests are taken when you leave Freewind; their den comes with the next Freewind visit, at about 30."] = "Oba harpyjí questy od {npc:4877} si vezmeš, když odcházíš z Freewind; jejich doupě přijde při příští návštěvě Freewind, zhruba na levelu 30.",
	["{npc:4877}, inside the inn"] = "{npc:4877}, uvnitř hostince",
	["{object:176344}, north-west camp"] = "{object:176344}, severozápadní tábor",
	["{object:176344}, south-east camp"] = "{object:176344}, jihovýchodní tábor",
	["{object:176344}, south-west camp"] = "{object:176344}, jihozápadní tábor",
	["{quest:1150} ({npc:4490}, 31) waits for the next Freewind visit, at about 30: keep it."] = "{quest:1150} ({npc:4490}, 31) počká na další návštěvu Freewindu, kolem levelu 30: nech si ho.",
	["{quest:6921}: the {item:16762}, from the {object:177964}"] = "{quest:6921}: {item:16762} z {object:177964}",
	["{zone:1456} flight master"] = "letový mistr {zone:1456}",
}
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = {
	["Back east to {area:272}."] = "Zpět na východ do {area:272}.",
	["Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping."] = "Zpět na pole: Peasants pracují jižně od statků. Pozor: utíkající rolník, který doběhne k radnici, může přivést posily; zpomalení nebo rooty mu v útěku zabrání.",
	["Back to {area:272}."] = "Zpět do {area:272}.",
	["City of Dalaran"] = "City of Dalaran",
	["Clear {area:290} from the gate in; the dwarves run for help at 30% health."] = "Vyčisti {area:290} od brány dovnitř; trpaslíci na 30 % zdraví utíkají pro pomoc.",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["Darthalia's last battle is at {area:290}, the dwarven keep south-east of {area:271}: every dwarf there is elite (28-32), {npc:2304} too. Great XP if you have a group for it."] = "Darthaliina poslední bitva je u {area:290}, trpasličí pevnosti jihovýchodně od {area:271}: každý trpaslík tam je elitní (28–32), i {npc:2304}. Skvělé XP, pokud na to máš skupinu.",
	["Drull's ball and chain"] = "Drullova koule s řetězem",
	["Faranell's next {quest:513} needs a {item:3388} ({skill:171}) and the {area:287} coast: leave it."] = "Faranellův další {quest:513} potřebuje {item:3388} ({skill:171}) a pobřeží {area:287}: nech ho být.",
	["Finish the {item:3712}"] = "Dokonči {item:3712}",
	["Fly from {area:484} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to the Crossroads from there."] = "Leť z {area:484} do {area:1638} a vytrénuj se u {npc:3033} na {area:1639}; odtamtud leť dál do Crossroads.",
	["Fly from {area:484} to {area:392}. {npc:5901} camps on the coast a short walk south of the town; fly on to the Crossroads from {area:392}."] = "Leť z {area:484} do {area:392}. {npc:5901} táboří na pobřeží kousek pěšky jižně od města; z {area:392} leť dál do Crossroads.",
	["Fly to the Crossroads"] = "Leť do Crossroads",
	["Fly to the {area:228}. The {object:113791} stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the {npc:5895} and keep the {item:7813} for {npc:5901}. Fly on to {area:272} from the {area:228}."] = "Leť do {area:228}. {object:113791} stojí na kopci kousek jihozápadně od něj: poraz Corrupt Manifestation of Water vedle něj, polož jeho náramky do žároviště, promluv s {npc:5895} a {item:7813} si nech pro {npc:5901}. Z {area:228} leť dál do {area:272}.",
	["Fly to {area:1497}"] = "Leť do {area:1497}",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:272}"] = "Leť do {area:272}",
	["For characters of 29 to 31: the {quest:527}, {area:272}'s errands and the gnolls of the foothills, all at or under your level."] = "Pro postavy 29 až 31: {quest:527}, pochůzky v {area:272} a gnollové z podhůří, všechno na tvém levelu nebo pod ním.",
	["For your City of Dalaran run, later in this guide: {npc:2278} stands in {area:272}, a short walk east of {npc:2410}."] = "Pro tvůj průchod City of Dalaran, později v tomto návodu: {npc:2278} stojí v {area:272}, kousek pěšky východně od {npc:2410}.",
	["From the blossoms, back north along the river and then west to {area:287} town, well north of {area:271} (its guards are 55)."] = "Od květů zpátky na sever podél řeky a pak na západ do města {area:287}, hodně severně od {area:271} (jeho stráže mají 55).",
	["Head south-west past {area:287} town to the {area:288}. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "Jdi na jihozápad kolem města {area:287} k {area:288}. Tunely pracují horníci; {npc:2305} (30) a {npc:2450} (29) jsou hluboko uvnitř.",
	["Hillsbrad Peasants"] = "Hillsbrad Peasants",
	["Level 30"] = "Level 30",
	["Still short of ten {item:3712}? The Snapjaws line the river east of {area:272}, on your way back from the mine."] = "Pořád ti chybí do deseti {item:3712}? Snapjaws lemují řeku východně od {area:272}, na cestě zpátky z dolu.",
	["Thaivand's next errand, the flames, sends you among the Mountain and Giant Yetis (32-34) and to Helcular's grave inside {area:271}: leave it."] = "Thaivandova další pochůzka, plameny, tě posílá mezi Mountain a Giant Yetis (32–34) a k Helcularovu hrobu v {area:271}: nech ji být.",
	["The City of Dalaran is a dungeon for a group of five, about levels 28 to 33, under the violet dome. Without the {item:277507}, go in through the sewer pipe north-west of the crater: the arrow leads there.\nInside: {npc:247126} is {npc:2278}'s. {npc:268743}, in the sewer, gives Opportunistic Education and takes it back there."] = "City of Dalaran je dungeon pro skupinu pěti, zhruba levely 28 až 33, pod fialovou kopulí. Bez {item:277507} jdi dovnitř kanálovou trubkou severozápadně od kráteru: vede tam šipka.\nUvnitř: {npc:247126} je pro {npc:2278}. {npc:268743} v kanalizaci dává Opportunistic Education a tam ji i převezme.",
	["The river south of {area:272}: kill these as you meet them"] = "Řeka jižně od {area:272}: zabíjej je, jak na ně narazíš",
	["The smithy"] = "Kovárna",
	["Torn Fin murlocs"] = "Murloci Torn Fin",
	["Town hall"] = "Radnice",
	["Train"] = "Trénuj",
	["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Když už jsi v {zone:1458}, vytrénuj se: trenéři stojí v {object:36070}, {object:36073} a {object:36082} (paladinové: {npc:260093}).",
	["Train your new spells."] = "Vytrénuj si nová kouzla.",
	["Voidglare, Bel'varil and {npc:2770}"] = "Voidglare, Bel'varil a {npc:2770}",
	["West across the foothills to {area:287} town: the smithy stands in the middle of it. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks by the smithy; {npc:2451} works the field south-east of the town."] = "Na západ přes podhůří do města {area:287}: kovárna stojí uprostřed. {npc:2404} a jeho učni pracují u výhně; {object:1736} je naskládané vedle ní. {npc:2449} chodí u kovárny; {npc:2451} pracuje na poli jihovýchodně od města.",
	["West of Tarren Mill, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but they hit hard and come in pairs."] = "Západně od Tarren Mill vyplňují {area:277} v kopcích Cave a Ferocious Yetis (30–32); hůl nese zhruba jeden ze šestnácti. Zůstaň v těchhle jeskyních: Mountain a Giant Yetis (32–34) v jeskyni dál na severu ji nesou taky, ale tvrdě bijí a chodí po dvou.",
	["West past the hills to the farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere.\nCareful: Kirin Tor Guards (55) patrol {area:287}'s fields and roads and attack the Horde: keep an eye out for them and stay out of their way."] = "Na západ za kopce k farmám východně od města {area:287}. {npc:232} pracuje na poli u severního statku, {npc:2403} na tom dál na jihovýchod; Farmhands a Farmers jsou všude.\nPozor: po polích a cestách {area:287} hlídkují Kirin Tor Guards (55) a útočí na Hordu: dávej na ně pozor a drž se jim z cesty.",
	["grind on {npc:2375}"] = "grinduj na {npc:2375}",
	["{area:228} flight master"] = "letový mistr {area:228}",
	["{area:272} flight master"] = "letový mistr {area:272}",
	["{area:392} flight master"] = "letový mistr {area:392}",
	["{area:484} flight master"] = "letový mistr {area:484}",
	["{item:3713}, from {npc:2393}"] = "{item:3713}, od {npc:2393}",
	["{npc:2216}, inside"] = "{npc:2216}, uvnitř",
	["{npc:2229}, inside"] = "{npc:2229}, uvnitř",
	["{npc:270038} stands in the Apothecarium. His {quest:97985} is for Stormheart, a level 30 elite who walks the canyon east of {area:484}, on the next guide's way to the {area:439}."] = "{npc:270038} stojí v Apothecariu. Jeho {quest:97985} je na Stormhearta, elite s levelem 30, který chodí kaňonem východně od {area:484}, po cestě dalšího návodu do {area:439}.",
	["{npc:270038}: back to him on the next {zone:1458} stop, at about 38"] = "{npc:270038}: zpátky k němu na další zastávce v {zone:1458}, zhruba na levelu 38",
	["{npc:2770}, outside the inn: the Boulderfist ogres (32-34) on the 38-39 Arathi visit"] = "{npc:2770}, před hostincem: ogři Boulderfist (32–34) při návštěvě Arathi na levelu 38–39",
	["{npc:3428} stands beside the Crossroads flight master. {quest:1145} is offered from level 29; below it, the next guide's {zone:1454} stop takes it."] = "{npc:3428} stojí vedle letového mistra na Crossroads. {quest:1145} se nabízí od levelu 29; pod ním si ho vezme zastávka v {zone:1454} v dalším návodu.",
	["{npc:3428}: for {npc:4485} in {zone:1454}"] = "{npc:3428}: pro {npc:4485} v {zone:1454}",
	["{npc:4485} stands in the {object:172958}, on the way out to the main gate."] = "{npc:4485} stojí v {object:172958}, po cestě ven k hlavní bráně.",
	["{npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:4949} čeká v Grommash Hold, v {object:172957}.",
	["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Grommash Hold, pokud ho neseš",
	["{object:1761}, inside"] = "{object:1761}, uvnitř",
	["{quest:539} with a group"] = "{quest:539} se skupinou",
	["{quest:547} with a group"] = "{quest:547} se skupinou",
	["{quest:567}, the poster by the inn"] = "{quest:567}, plakát u hostince",
	["{zone:1456} flight master"] = "letový mistr {zone:1456}",
	["{zone:1458} flight master"] = "letový mistr {zone:1458}",
}
t.guides["forever/horde/30-40/02-thousand-needles"] = {
	["Back across to {npc:2986}'s mesa north-east of the post, then take the lift down to the canyon floor. {npc:2986}'s next test, {npc:4499}, is an elite: leave it."] = "Zpět přes na mesu {npc:2986} severovýchodně od stanoviště, pak sjeď výtahem dolů na dno kaňonu. Další zkouška {npc:2986}, {npc:4499}, je elitní: nech ji být.",
	["Back east to {area:484}."] = "Zpět na východ do {area:484}.",
	["Back to {area:1637}"] = "Zpět do {area:1637}",
	["Back west to {npc:11863}."] = "Zpět na západ k {npc:11863}.",
	["Clam beds"] = "Lastury",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["East to the raceway, on the way south to {area:976}."] = "Na východ k závodní dráze, cestou na jih do {area:976}.",
	["Fly from {zone:1454} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {area:484} from there."] = "Leť ze {zone:1454} do {area:1638} a vytrénuj se u {npc:3033} na {area:1639}; odtamtud leť dál do {area:484}.",
	["Fly from {zone:1454} to {area:392}. {npc:5901} camps on the coast a short walk south of the town; fly on to {area:484} from {area:392}."] = "Leť ze {zone:1454} do {area:392}. {npc:5901} táboří na pobřeží kousek pěšky jižně od města; z {area:392} leť dál do {area:484}.",
	["Fly to the Crossroads"] = "Leť do Crossroads",
	["Fly to {area:460}"] = "Leť do {area:460}",
	["Fly to {area:484}"] = "Leť do {area:484}",
	["Giant Softshell Clams, on the sea floor"] = "Giant Softshell Clams, na mořském dně",
	["Head east past {area:599} and along the northern hills to the satyrs' ruins of {area:603}. Kill every kind you meet for {npc:268705}; the Shadowstalkers walk unseen.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them."] = "Zamiř na východ kolem {area:599} a podél severních kopců k satyrským ruinám {area:603}. Pro {npc:268705} zabíjej každý druh, který potkáš; Shadowstalkers chodí neviditelní.\nPozor: Hatefury Rogues při spawnu používají Hide, takže jsou ve stealthu, dokud je nenajdeš.",
	["Head east to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. The {npc:13019} stands on the fortress's top floor with the Sceptre. The cultists also drop a {item:20310} now and then (1-5%); if one drops, read it. Leave the red {object:176581} for now: its {npc:11876} is 37, and the second {zone:1443} visit comes back for it."] = "Jdi na východ do {area:599}. Zmlať kultistu Burning Blade a než umře, použij na něj {item:6436}, tím naplníš jeden {item:6435}. {npc:13019} stojí v nejvyšším patře pevnosti se Sceptrem. Kultisté občas dropnou i {item:20310} (1–5 %); když padne, přečti si ho. Červený {object:176581} zatím nech: jeho {npc:11876} má 37 a druhá návštěva {zone:1443} se pro něj vrátí.",
	["Head north along the coast, then inland to the ruined tower of {area:2405}: {npc:11863} waits inside. The coast's clams and naga come after {area:599}, on one walk north to {area:2406}."] = "Jdi podél pobřeží na sever, pak do vnitrozemí ke zřícené věži {area:2405}: uvnitř čeká {npc:11863}. Mušle a nagy na pobřeží přijdou na řadu po {area:599}, při jedné cestě na sever do {area:2406}.",
	["Head south out of Stonetalon into {zone:1443} and follow the road south to {npc:11596}'s camp."] = "Vyjdi ze Stonetalonu na jih do {zone:1443} a po silnici na jih do tábora {npc:11596}.",
	["Head west to the troll village on the coast, keeping clear of the {area:606} on the way. {npc:268705} stands on the path just north of the village.\n{npc:268705} may not be here on Forever: if {npc:268705} doesn't offer {quest:97265}, skip it."] = "Jdi na západ k trollí vesnici na pobřeží a cestou se drž dál od {area:606}. {npc:268705} stojí na stezce kousek severně od vesnice.\n{npc:268705} na Forever možná není: pokud {npc:268705} nenabízí {quest:97265}, přeskoč to.",
	["Level 32"] = "Level 32",
	["Swim out to {area:2406} off the far northern tip: {object:177786} stands on the shore beside the {object:177673}. Open it with both keys; leave the statue alone."] = "Doplav na {area:2406} u nejsevernějšího cípu: {object:177786} stojí na břehu vedle {object:177673}. Otevři ji oběma klíči; sochu nech být.",
	["Taiga's {item:14547}, Drulzegar's Other Fish to Fry and {zone:1443}'s other 37-40 quests wait for the second visit, at 38: the next guides fly to {zone:1454} and take the zeppelin to {zone:1434}."] = "Taigin {item:14547}, Drulzegarův Other Fish to Fry a další questy na 37–40 v {zone:1443} počkají na druhou návštěvu na 38: další návody letí do {zone:1454} a zeppelinem do {zone:1434}.",
	["Take the lift down and follow the canyon east. {npc:4483} camps on the north-western edge of the salt flats."] = "Sjeď výtahem dolů a jdi kaňonem na východ. {npc:4483} táboří na severozápadním okraji solných plání.",
	["The flats' south and the silithid dig are 32-35, {zone:1443}'s quests 32-38. Still below 32 after the raceway's hand-ins? Back north on the flats, the Scorpid Reavers (31-32) roam among the basilisks and tortoises: kill them until level 32; leave the Sparkleshell Snappers (34-35) and the Scorpid Terrors (33-34) alone. Or, with a group, run the {area:1717} dungeon instead."] = "Jih plání a silithidí vykopávky jsou 32–35, questy v {zone:1443} 32–38. Pořád pod 32 i po odevzdání na závodní dráze? Zpátky na sever na pláních se mezi bazilišky a želvami potulují Scorpid Reavers (31–32): zabíjej je do levelu 32; Sparkleshell Snappers (34–35) a Scorpid Terrors (33–34) nech být. Nebo se skupinou místo toho projdi dungeon {area:1717}.",
	["The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Goblini a gnómové z {area:2240} jsou neutrální a dávají questy oběma frakcím.",
	["The southern flats"] = "Jižní pláně",
	["Train while you are in the city."] = "Když už jsi ve městě, vytrénuj se.",
	["Underwater"] = "Pod vodou",
	["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time. Careful: leave the kodo skulls on the ground alone: opening one raises a {npc:11521} (37-38) that hits hard."] = "Použij {item:13892} od {npc:11596} na Aged, Dying nebo {npc:4702} na hřbitově a odveď zkroceného koda zpátky k {npc:11596}. U jeho tábora promluv s kodem: tím se započítá a můžeš zkrotit dalšího. Pět kodů, po jednom. Pozor: lebek kodů na zemi si nevšímej: když jednu otevřeš, vyvoláš {npc:11521} (37–38), který tvrdě bije.",
	["West of Freewind Post, below {area:2097}, the harpies of {area:487} (28-30). The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s; her {quest:98069} lie on the ground along the foot of the cliff and in the cave up on top. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her, for {npc:2986}'s claw."] = "Západně od Freewind Post, pod {area:2097}, harpyje v {area:487} (28–30). Screeching Harpies, Roguefeathers a Windcallers tam patří {npc:4877}; její {quest:98069} leží na zemi podél paty útesu a v jeskyni nahoře. Mezi nimi chodí {npc:4490} (31): než ji pullneš kvůli drápu pro {npc:2986}, prořeď harpyje kolem ní.",
	["West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a {item:5877}: open it.\nCareful: Hive Drones call for help when they fall to 20% health, and the {npc:4132} (37, rare) walks the dig: take the Searchers and Drones (32-34) outside first, then pull the Invaders (34-35) one at a time from the cave mouth."] = "Západně od nich se po vykopávce rojí silithidi. Mezi kupami chodí Searchers a Hive Drones; Invaders (34–35) zůstávají uvnitř jeskyně úlu. První silithid, kterého zabiješ, dropne {item:5877}: otevři ho.\nPozor: Hive Drones volají o pomoc, když klesnou na 20 % zdraví, a po vykopávce chodí {npc:4132} (37, rare): nejdřív vezmi Searchers a Drones (32–34) venku, pak pulluj Invaders (34–35) po jednom od ústí jeskyně.",
	["West to Shadowprey: your hearthstone is bound there."] = "Na západ do Shadowprey: tvůj Hearthstone je nastavený tam.",
	["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "Na západ k pobřeží. Na mělčině leží Giant Softshell Clams a po pláži chodí Enraged Reef Crawlers: každá mušle, kterou otevřeš na mořském dně, a někteří crawleři dají {item:15874}. Každou otevři v taškách a vezmi maso.\nDrysnap Crawlers a Pincers na stejné pláži nesou {item:15878}, zhruba jeden ze sedmi.",
	["grind on {npc:4140}"] = "grinduj na {npc:4140}",
	["{area:392} flight master"] = "letový mistr {area:392}",
	["{area:439}: kill these as you meet them"] = "{area:439}: zabíjej je, jak na ně narazíš",
	["{area:483}: kill these as you meet them"] = "{area:483}: zabíjej je, jak na ně narazíš",
	["{area:484} flight master"] = "letový mistr {area:484}",
	["{item:15874}: open it in your bags"] = "{item:15874}: otevři ho v taškách",
	["{item:15878}, from the Drysnap crabs"] = "{item:15878} z krabů Drysnap",
	["{item:15881}, from the Slitherblade naga"] = "{item:15881} z nag Slitherblade",
	["{item:279186}, from {npc:270094}"] = "{item:279186}, od {npc:270094}",
	["{item:5843}, from {npc:4490}"] = "{item:5843}, od {npc:4490}",
	["{npc:10537} stands in the middle of the post, on the way to the flight master."] = "{npc:10537} stojí uprostřed tábora, cestou k letovému mistrovi.",
	["{npc:10537}: for {npc:11259} in {zone:1443}, next"] = "{npc:10537}: pro {npc:11259} v {zone:1443}, potom",
	["{npc:11259}, up on the rise"] = "{npc:11259}, nahoře na vyvýšenině",
	["{npc:11863}'s next errand, the {item:15803}, needs {npc:12369} (38) out on {area:2406}: leave it, he is over your level."] = "Další pochůzka od {npc:11863}, {item:15803}, vyžaduje {npc:12369} (38) venku na {area:2406}: nech ji být, je nad tvůj level.",
	["{npc:11877}: for {quest:5762} in Stranglethorn, next guide"] = "{npc:11877}: pro {quest:5762} ve Stranglethornu, další návod",
	["{npc:268705}, on the path just north of the village"] = "{npc:268705}, na cestě kousek severně od vesnice",
	["{npc:268705}: the Hatefury satyrs of {area:603}, later in this guide"] = "{npc:268705}: satyři Hatefury v {area:603}, později v tomhle návodu",
	["{npc:2986} waits on the mesa just north-east of {area:484}, across the rope bridges."] = "{npc:2986} čeká na stolové hoře kousek severovýchodně od {area:484}, za provazovými mosty.",
	["{npc:2986}: {npc:4490}, in the harpy den west of the post"] = "{npc:2986}: {npc:4490}, v harpyjím doupěti západně od stanoviště",
	["{npc:3428} stands beside the Crossroads flight master."] = "{npc:3428} stojí vedle letového mistra na Crossroads.",
	["{npc:3428}'s {quest:1145} needed level 29 on the last guide's Crossroads stop: take it now, on a short flight to the Crossroads and back."] = "{quest:1145} od {npc:3428} potřeboval na zastávce na Crossroads v minulém návodu level 29: vezmi si ho teď, krátkým letem na Crossroads a zpátky.",
	["{npc:3428}: for {npc:4485} in {zone:1454}"] = "{npc:3428}: pro {npc:4485} v {zone:1454}",
	["{npc:4452}'s crate for {quest:5762} in Stranglethorn, later on the route"] = "Bedna od {npc:4452} pro {quest:5762} ve Stranglethornu, později na trase",
	["{npc:4452}: his parts order goes to {quest:1111} in {area:392}, later on the route"] = "{npc:4452}: jeho objednávka dílů jde k {quest:1111} v {area:392}, později na trase",
	["{npc:4454}: his letter goes to Martek in the {zone:1418}, at 39"] = "{npc:4454}: jeho dopis jde Martekovi v {zone:1418}, na levelu 39",
	["{npc:4485} stands in the {object:172958}."] = "{npc:4485} stojí v {object:172958}.",
	["{npc:4630}: for Gazlowe in {area:392}, later on the route"] = "{npc:4630}: pro Gazlowa v {area:392}, později na trase",
	["{npc:4671}, on the way south"] = "{npc:4671}, po cestě na jih",
	["{npc:4877}, inside the inn"] = "{npc:4877}, uvnitř hostince",
	["{npc:4877}, the trade supplies vendor, stands inside {area:484}'s inn."] = "{npc:4877}, obchodnice se zbožím pro řemesla, stojí uvnitř hostince v {area:484}.",
	["{npc:4877}: her stolen supplies lie in the same harpy den"] = "{npc:4877}: její ukradené zásoby leží ve stejném harpyjím doupěti",
	["{npc:4877}: the Screeching harpies of {area:487}"] = "{npc:4877}: harpyje Screeching v {area:487}",
	["{npc:5395} now offers Centaur Bounty: the second {zone:1443} visit, at 38, takes it on its way to the {area:607}."] = "{npc:5395} teď nabízí Centaur Bounty: vezme si ho druhá návštěva {zone:1443} na levelu 38, po cestě do {area:607}.",
	["{npc:5395} stands in the post, {npc:11259} up on its rise; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395} stojí na stanovišti, {npc:11259} nahoře na jeho návrší; {npc:5641} a {npc:4498} čekají na návrší západně od něj, nad {area:596}.",
	["{npc:5641} and {npc:4498}"] = "{npc:5641} a {npc:4498}",
	["{npc:5892} stands in the {object:172957}."] = "{npc:5892} stojí v {object:172957}.",
	["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} a tvůj {item:5177}",
	["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787} leží na zemi kousek jihozápadně od věže {npc:11863}, cestou dolů na břeh: přečti ho. Jeho dva klíče padají jen, když máš quest.",
	["{object:19868}, all over the northern flats: pick it on the western flats, away from the Snappers"] = "{object:19868}, po celých severních pláních: sbírej ho na západních pláních, dál od Snapperů",
	["{quest:1104}, from the Scorpid Reavers of the north half"] = "{quest:1104}, ze Scorpid Reavers v severní polovině",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
	["{zone:1456} flight master"] = "letový mistr {zone:1456}",
}
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = {
	["Back north to the camp."] = "Zpět na sever do tábora.",
	["Back to {area:1637}"] = "Zpět do {area:1637}",
	["Back to {object:3202}."] = "Zpět k {object:3202}.",
	["Boat to {area:35}"] = "Loď do {area:35}",
	["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "Dizzywigovy díly jdou zpět Kravelovi do {area:439}, mimo trasu: nech je být.",
	["Dustwallow's quests are 35-38. Still below 36 after {object:3202}'s hand-ins? The Snapjaw Crocolisks (35-36) line the river just east of the camp, below the Mosh'Ogg hills: kill them until level 36, then walk back to the zeppelin tower. Leave the Mosh'Ogg ogres (36-37) above them alone."] = "Questy Dustwallow mají 35–38. Pořád pod 36 po odevzdáních v {object:3202}? Snapjaw Crocolisks (35–36) lemují řeku kousek východně od tábora, pod kopci Mosh'Ogg: zabíjej je do levelu 36, pak se vrať k věži zeppelinů. Zlobry Mosh'Ogg (36–37) nad nimi nech být.",
	["East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them; the 38s can be two over you: pull them one at a time and leave the Elders alone."] = "Východně od kopců Mosh'Ogg slídí Shadowmaw Panthers (37–38) v džungli směrem k jezeru; po stejném území se toulají Stranglethorn Tigresses a občas dropnou nepoškozený tesák. Snapjaw Crocolisks lemují řeku kousek západně od džungle; jejich kůže si nech pro {npc:2495}. Pozor: Shadowmaw Panthers (level 37–38) a Elder Shadowmaw Panthers (level 42–43) jsou mimo boj ve Sneak, takže zůstanou skrytí, dokud nepřijdeš blízko; ty 38 můžou být o dva nad tebou: tahej je po jednom a Elders nech být.",
	["Elder Stranglethorn Tigers"] = "Elder Stranglethorn Tigers",
	["Escort {npc:268992} out of the ruins and keep him alive: Lozgil takes the news once he is safe."] = "Eskortuj {npc:268992} ven z ruin a udrž ho naživu: Lozgil vezme zprávu, až bude v bezpečí.",
	["Fly from {area:2408} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {zone:1454} from there."] = "Leť z {area:2408} do {area:1638} a vytrénuj se u {npc:3033} na {area:1639}; odtamtud leť dál do {zone:1454}.",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:35}"] = "Leť do {area:35}",
	["Fly to {area:392}"] = "Leť do {area:392}",
	["Fly to {object:3202}"] = "Leť do {object:3202}",
	["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of The {item:2755} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "Jdi po silnici na sever z {object:3202}; Nesingwaryho lovecký tábor leží na kopci severovýchodně od řeky. {npc:773} ho chce prozkoumat: projdi se mezi jeho stany. Od teď si nech každou stránku z The {item:2755}, kterou nalootuješ: {npc:716} je vezme při tvé další návštěvě Stranglethorn.",
	["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "Opusť {area:35} tunelem a jdi po cestě na sever k {object:3202}, orčímu táboru na západní straně údolí. Drž se cesty: džungle kolem ní je nad tvůj level.",
	["Level 35"] = "Level 35",
	["Level 36"] = "Level 36",
	["Mosh'Ogg camp"] = "Tábor Mosh'Ogg",
	["Nesingwary's camp"] = "Nesingwaryho tábor",
	["Stolen Shipments, in the ruins"] = "Stolen Shipments, v ruinách",
	["Stranglethorn Tigers (32) roam the hills around the camp and south of it, Panthers (32) the clearings west and south-west of it. The Venture Co. Geologists (34-36), who carry the Tumbled Crystals, work the camps by {area:37}, south-east of the camp. Careful: Venture Co. Agents (39) stand among the geologists in the western camps by the Venture Co. house: work the eastern camps, away from them."] = "Stranglethorn Tigers (32) se potulují po kopcích kolem tábora a jižně od něj, Panthers (32) po mýtinách západně a jihozápadně od něj. Venture Co. Geologists (34–36), kteří nosí Tumbled Crystals, pracují v táborech u {area:37}, jihovýchodně od tábora. Pozor: mezi geology v západních táborech u domu Venture Co. stojí Venture Co. Agents (39): pracuj ve východních táborech, daleko od nich.",
	["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads. Careful: the 37s can be two over you: pull them one at a time from the village's edge, never into the middle with the Witch Doctors.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of The {item:2755}."] = "Bloodscalp Headhunters (36–37) ve vesnici na pobřeží nosí scvrklé hlavy. Pozor: ti na 37 můžou být o dva levely nad tebou: taháš je po jednom z okraje vesnice, nikdy ne doprostřed k Witch Doctors.\nTrollové Bloodscalp drží ruiny na pobřeží severně od útesu a vesnici za nimi; každý může dropnout {item:3915}. Pořád lootuj stránky z {item:2755}.",
	["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp. Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly."] = "Elder Stranglethorn Tigers (34–35) se potulují po kopcích jihozápadně od tábora. Pozor: Trollí tábory jsou blízko oblasti tygrů a při neopatrném pullu se trollové můžou přidat do boje.",
	["The next guide takes the zeppelin to {zone:1454} from the tower on the west side of the camp."] = "Další návod jede zeppelinem do {zone:1454} z věže na západní straně tábora.",
	["Train while you are in the city."] = "Když už jsi ve městě, vytrénuj se.",
	["Tumbled Crystals, from the geologists of the eastern camps"] = "Tumbled Crystals od geologů z východních táborů",
	["Underwater"] = "Pod vodou",
	["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\nLeave {npc:729}, the level 37 tiger on the hilltop south-west of the camp, for now: he is two over you here, and the 40-50 Stranglethorn guide comes back to him.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "Za táborem na západ sedí na skalách Crystal Spine Basilisks (34–35); každý Bloodscalp ve vesnici za nimi může dropnout ucho.\n{npc:729}, tygra na levelu 37 na kopci jihozápadně od tábora, zatím nech být: tady je o dva levely nad tebou a návod Stranglethorn 40–50 se k němu vrací.\nPozor: v hnízdě raptorů jsou mladí raptoři, kteří se přidají do boje, když zaútočíš na dospělé.",
	["grind on {npc:1085}"] = "grinduj na {npc:1085}",
	["grind on {npc:1152}"] = "grinduj na {npc:1152}",
	["{area:100}: kill these as you meet them"] = "{area:100}: zabíjej je, jak na ně narazíš",
	["{area:102}: kill these as you meet them"] = "{area:102}: zabíjej je, jak na ně narazíš",
	["{area:2408} flight master"] = "letový mistr {area:2408}",
	["{area:301}: kill these as you meet them"] = "{area:301}: zabíjej je, jak na ně narazíš",
	["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "Nejdřív {area:35}: goblinská loď tam pluje z {area:392} a každý quest z {area:35} je pro sever údolí, kam pak dojdeš pěšky.",
	["{area:35} flight master"] = "letový mistr {area:35}",
	["{npc:2495}, inside"] = "{npc:2495}, uvnitř",
	["{npc:2496}, upstairs"] = "{npc:2496}, nahoře",
	["{npc:2498}, inside"] = "{npc:2498}, uvnitř",
	["{npc:268992} is held at the east edge of the {area:102}; the Stolen Shipments lie among the ruins around him. The Bloodscalp Scouts, Hunters and Mystics (34-35) there carry his {item:277957}. Then lead him out of the ruins: {npc:4631} in {area:35} takes the news and the shipments.\nCareful: Bloodscalp Berserkers and Headhunters (36-37) and Witch Doctors (37, casters) hold the ruins north and west of {npc:268992}, close to the northern shipments (around 24.9,9.6): pick the shipments in the southern ruins by {npc:268992} first, and pull one at a time if you go north."] = "{npc:268992} je držen na východním okraji {area:102}; Stolen Shipments leží v ruinách kolem něj. Bloodscalp Scouts, Hunters a Mystics (34–35) tam nosí jeho {item:277957}. Pak ho vyveď z ruin: zprávu i zásilky převezme {npc:4631} v {area:35}.\nPozor: Bloodscalp Berserkers a Headhunters (36–37) a Witch Doctors (37, caster) drží ruiny severně a západně od {npc:268992}, blízko severních zásilek (kolem 24.9,9.6): nejdřív posbírej zásilky v jižních ruinách u {npc:268992} a když jdeš na sever, tahej po jednom.",
	["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391} čeká nahoře v domě u letového mistra; {quest:1111} stojí na docích vedle lodi.",
	["{npc:3391}, upstairs"] = "{npc:3391}, nahoře",
	["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391}: pro {npc:4631} v {area:35}, kam loď jede",
	["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631} stojí na molu, kde kotví loď. Obchod {npc:2495} je v budově východně od hostince; {npc:2498} je v přízemí hostince, {npc:2496}, {npc:737} a {npc:773} nahoře, letový mistr {npc:2858} na horní palubě.",
	["{npc:4631}, on the pier"] = "{npc:4631}, na molu",
	["{npc:4631}, on the pier: the Stolen Shipments"] = "{npc:4631}, na molu: Stolen Shipments",
	["{npc:4631}: {npc:268992} is safe"] = "{npc:4631}: {npc:268992} je v bezpečí",
	["{npc:737}, upstairs"] = "{npc:737}, nahoře",
	["{npc:773}, upstairs"] = "{npc:773}, nahoře",
	["{object:3202} flight master"] = "letový mistr {object:3202}",
	["{quest:1111}, on the docks"] = "{quest:1111}, v docích",
	["{quest:629}'s and Zul'Kunda's quests are next, with Bloodscalp Headhunters of 36-37. Still below 35 after {area:35}'s hand-ins? The Elder Stranglethorn Tigers (34-35) roam the hills north of {object:3202}, below Nesingwary's camp: kill them until level 35. The Lashtail Raptors (35-36) beside them are a level higher."] = "Další jsou questy od {quest:629} a Zul'Kundy, s Bloodscalp Headhunters 36–37. Jsi po odevzdáních v {area:35} pořád pod levelem 35? Elder Stranglethorn Tigers (34–35) se toulají v kopcích severně od {object:3202}, pod Nesingwaryho táborem: zabíjej je až do levelu 35. Lashtail Raptors (35–36) vedle nich jsou o level výš.",
	["{zone:1434}: kill these as you meet them"] = "{zone:1434}: zabíjej je, jak na ně narazíš",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
	["{zone:1456} flight master"] = "letový mistr {zone:1456}",
}
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = {
	["Back north along the coast to {area:392}'s flight master."] = "Zpět na sever po pobřeží k letovému mistrovi {area:392}.",
	["Back to {area:1637}"] = "Zpět do {area:1637}",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["Drywallow Crocolisks"] = "Drywallow Crocolisks",
	["East along the road to {area:597}; {npc:5412} stands beside {npc:5395}."] = "Na východ po cestě do {area:597}; {npc:5412} stojí vedle {npc:5395}.",
	["Fly from {area:2408} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {zone:1454} from there."] = "Leť z {area:2408} do {area:1638} a vytrénuj se u {npc:3033} na {area:1639}; odtamtud leť dál do {zone:1454}.",
	["Fly to the Crossroads"] = "Leť do Crossroads",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:2408}"] = "Leť do {area:2408}",
	["Fly to {area:2408} from the flight master you are next to: {area:392}'s, or Brackenwall's if you had no errand in {area:392}."] = "Leť do {area:2408} od letového mistra, u kterého stojíš: z {area:392}, nebo z Brackenwall, pokud jsi v {area:392} nic neměl.",
	["Fly to {area:378}"] = "Leť do {area:378}",
	["Fly to {area:392}"] = "Leť do {area:392}",
	["For {npc:2519} at {object:3202}, in forever/horde/40-50/01-stranglethorn-vale"] = "Pro {npc:2519} v {object:3202}, ve forever/horde/40-50/01-stranglethorn-vale",
	["Head back west to Brackenwall with the head: {npc:4503} stands at the south edge of the village where the road comes in, {npc:4791} and {npc:4926} in the village."] = "Vrať se s hlavou na západ do Brackenwallu: {npc:4503} stojí na jižním okraji vesnice, kde přichází silnice, {npc:4791} a {npc:4926} ve vesnici.",
	["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Z {area:378} jdi po silnici na východ do bažiny. Vypálený {area:403} stojí vedle ní hned za hranicí; štít, odznak a stopy kopyt jsou v ruině a vedle ní.",
	["Head east to {area:602}. With the {quest:5381} from {npc:11624} in your bags, open a demon portal's ring: a {npc:11937} (38-39) comes out; kill it to close that portal. Six portals. Careful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake."] = "Jdi na východ do {area:602}. S {quest:5381} od {npc:11624} v batohu otevři kruh démonického portálu: vyjde {npc:11937} (38–39); zabij ho a portál se zavře. Portálů je šest. Pozor: Kolem mnoha portálů chodí Infernals, Doomguards a Burning Blade Summoners a můžou se přidat; nejdřív zabij moby poblíž, nebo strážce odtáhni pryč, třeba k centrálnímu jezeru covenu.",
	["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Jdi na sever do {area:502}. Stinky stojí u úpatí kopce; doprovoď ho, zatímco sbírá Bogbean Leaves kousek jižně od něj.",
	["Head south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "Z {area:392} jdi podél pobřeží na jih do {area:720}. {npc:6236} stojí u arény: stoupni na mříž a boj začne; vyzyvatelé přicházejí po jednom, pak {npc:6238} (33).",
	["Head west back across the marsh. The Darkfang Lurkers (36-37) and Venomspitters (37-38) on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes. Work its outer edge, where the Spiders and Recluses (35-37) stand: the Lurkers and Silkspinners (37-39) deeper in are two or three over you.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Vrať se na západ přes bažinu. Váčky s jedem dropují Darkfang Lurkers (36–37) a Venomspitters (37–38) na hřebenech severně od Brackenwallu. Stejnými lesy se plíží Theramore Infiltrators (35–36): jsou ve stealthu, tak se dívej pozorně.\nPavouci Darkmist se hemží u ústí jeskyně severozápadně od Brackenwallu; oči dropuje každý druh. Drž se vnějšího okraje, kde stojí Spiders a Recluses (35–37): Lurkers a Silkspinners (37–39) hlouběji jsou o dva tři levely nad tebou.\nPozor: Darkfang Lurkers (level 36–37) mimo boj používají Sneak a jsou ve stealthu, v boji kouzlí Poison.\nPozor: Pavouci ve stealthu ve stejné oblasti na tebe zaútočí, jakmile tě uvidí.\nPozor: Darkmist Lurkers se pohybují ve stealthu a v boji používají jed. Pavouci stojí blízko u sebe, takže addy jsou běžné; pullování jednotlivců z vnějšího okraje je omezí.",
	["Hearth to Shadowprey: your hearthstone is still bound there."] = "Portni se Hearthstonem do Shadowprey: pořád ho tam máš nastavený.",
	["Level 36"] = "Level 36",
	["Mirefin murlocs"] = "Murloci Mirefin",
	["Stinky Ignatz"] = "Stinky Ignatz",
	["Swamp Eye Jarl"] = "Swamp Eye Jarl",
	["Take the road north at the fork to the ogre village of Brackenwall."] = "Na rozcestí jdi po cestě na sever do ogří vesnice Brackenwall.",
	["The middle of {zone:1454}"] = "Střed {zone:1454}",
	["The next guide takes the {zone:1458} zeppelin from the tower outside the main gate."] = "Další návod jede zeppelinem do {zone:1458} z věže před hlavní bránou.",
	["The {area:2657}"] = "{area:2657}",
	["Train while you are in the city; everyone else trains in the {zone:1458}, next."] = "Když už jsi ve městě, vytrénuj se; všichni ostatní trénují až v {zone:1458}.",
	["Underwater"] = "Pod vodou",
	["West from the fortress to the coast at {area:598}: the Slitherblade Myrmidons, Naga and Sorceresses hold the beach. Pull them one at a time; the Sea Witches and Oracles (34-36) cast from range."] = "Na západ od pevnosti k pobřeží u {area:598}: pláž drží Slitherblade Myrmidons, Naga a Sorceresses. Pullni je po jednom; Sea Witches a Oracles (34–36) kouzlí z dálky.",
	["West of the post, the Maraudine centaurs hold the {area:607}; every Maraudine can drop a {item:254432} and an ear for {npc:5395}'s {quest:1366}. Stay with the Scouts and Wranglers (36-38) at the valley's eastern edge; the Maulers and Windchasers (38-39) a little further in are up to two over you at 37: pull them one at a time.\nCareful: {npc:5402} and the Rock Worms (41-42, elite) hold the valley's north-western end with the Khan Guards and Marauders (39-40), and the Magram's village in the south-east has Necromancers (42-43): keep east of the arrow."] = "Západně od stanoviště drží kentauři Maraudine {area:607}; každý Maraudine může dropnout {item:254432} a ucho pro {quest:1366} od {npc:5395}. Drž se u Scouts a Wranglers (36–38) na východním okraji údolí; Maulers a Windchasers (38–39) kousek dál jsou až o dva levely nad tebou na 37: pullni je po jednom.\nPozor: severozápadní konec údolí drží {npc:5402} a Rock Worms (41–42, elite) s Khan Guards a Marauders (39–40) a vesnice Magram na jihovýchodě má Necromancers (42–43): drž se východně od šipky.",
	["grind on {npc:4341}"] = "grinduj na {npc:4341}",
	["{area:2408} flight master"] = "letový mistr {area:2408}",
	["{area:392} flight master"] = "letový mistr {area:392}",
	["{area:496} flight master"] = "letový mistr {area:496}",
	["{area:496}: kill these as you meet them"] = "{area:496}: zabíjej je, jak na ně narazíš",
	["{item:14523}, on the {object:176581}"] = "{item:14523} na {object:176581}",
	["{npc:11624} and {npc:12340} stand in the village."] = "{npc:11624} a {npc:12340} stojí ve vesnici.",
	["{npc:11624}: the {quest:5381}, at {area:599} later on this visit"] = "{npc:11624}: {quest:5381}, u {area:599} později během této návštěvy",
	["{npc:12277} is held in the Maraudine camp at the valley's western end; free her and escort her out east of the valley.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} je držená v táboře Maraudine na západním konci údolí; osvoboď ji a doprovoď ji ven na východ z údolí.\nPozor: Skriptované skupiny jsou propojené a objeví se až během doprovodu, takže je nemůžeš vyčistit předem ani tahat po jedné. Pomůže ale vyčistit běžné kentaury na cestě, než začneš.",
	["{npc:12340}: the Slitherblade of Sar'theris Strand, on the way back from {area:599}"] = "{npc:12340}: Slitherblade na Sar'theris Strand, cestou zpět od {area:599}",
	["{npc:3354}, {object:172958}: for {area:720}, later in this guide (offered from level 30)"] = "{npc:3354}, {object:172958}: pro {area:720}, později v tomhle návodu (nabízí se od levelu 30)",
	["{npc:3412}'s workshop is in the {object:172958} beside {npc:4485}: hand in {quest:2841} if you ran {area:133}."] = "Dílna {npc:3412} je v {object:172958} vedle {npc:4485}: odevzdej {quest:2841}, pokud jsi prošel {area:133}.",
	["{npc:3428} stands beside the Crossroads flight master."] = "{npc:3428} stojí vedle letového mistra na Crossroads.",
	["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446} stojí pod Gazlowovým domem u letového mistra, směrem k dokům.",
	["{npc:4485} stands in the {object:172958}."] = "{npc:4485} stojí v {object:172958}.",
	["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, na jižním okraji vesnice, kde vede cesta dovnitř",
	["{npc:5395}: his {quest:1366}, from the same Maraudine as Gurda's totems"] = "{npc:5395}: jeho {quest:1366}, ze stejných Maraudine jako Gurdovy totemy",
	["{object:20985}, beside the manor"] = "{object:20985}, vedle sídla",
	["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, teď když {npc:4791} přečetl hlášení",
	["{quest:1218}, if you did not buy them in {zone:1454}"] = "{quest:1218}, pokud jsi je nekoupil v {zone:1454}",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
	["{zone:1456} flight master"] = "letový mistr {zone:1456}",
}
t.guides["forever/horde/30-40/05-arathi-highlands"] = {
	["Back east along the foothills to {area:272}: everything from the first loop is handed in inside the inn."] = "Zpět na východ po úpatí do {area:272}: všechno z prvního kola se odevzdává v hostinci.",
	["Back north to {area:321}: the doctor stands at the south gate."] = "Zpět na sever do {area:321}: doktor stojí u jižní brány.",
	["Back north-east to {area:321}."] = "Zpět na severovýchod do {area:321}.",
	["Back to {area:272}"] = "Zpět do {area:272}",
	["Back to {area:321}"] = "Zpět do {area:321}",
	["Below ground"] = "Pod zemí",
	["Boulderfist camp"] = "Tábor Boulderfist",
	["Boulderfist quests for a group"] = "Questy Boulderfist pro skupinu",
	["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Každý {object:180105} je kruh menhirů; klíč leží na kameni v jeho středu. Východní kruh je v kopcích severozápadně od {area:321}.\nPozor: Každý středový kámen hlídají asi tři elementálové kolem levelu 39, kteří zaútočí naráz, když na kámen klikneš, aniž bys je vybil: Burning Exiles na West, Thundering Exiles na Outer, Cresting Exiles na East.",
	["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Eskortuj profesora na kopec do jeskyně nad zátokou a hlídej ho, zatímco pracuje. Přepadnou ho tam dva vodní elementálové levelu 40, imunní vůči mrazu. Drž je u ústí jeskyně, daleko od něj: když se boj odehraje v jeskyni, přidá se místo práce a přicházejí další elementálové.",
	["Find where {quest:503} is held, on the top floor"] = "Najdi, kde drží {quest:503}, v nejvyšším patře",
	["Fleshstalker raptors"] = "Raptoři Fleshstalker",
	["Fly to {area:272}"] = "Leť do {area:272}",
	["Follow the road east. The violet shards glow just off the road a short way west of {area:321}."] = "Jdi po silnici na východ. Fialové střepy září kousek od silnice, kus cesty západně od {area:321}.",
	["Follow the road north out of {area:272} into the Alterac foothills: {quest:535} waits by the Syndicate camp. He offers his errand only while you carry {npc:2229}'s Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes {quest:535}."] = "Jdi po silnici na sever z {area:272} do podhůří Alteracu: {quest:535} čeká u tábora Syndicate. Svou pochůzku nabízí, jen když neseš Infiltration od {npc:2229}: dej mu hned stout a jeho odměnou je Syndicate Missive, kterou chce Krusk. Stejně poslouží i missive od Syndicate odsud: s jednou v taškách návod {quest:535} přeskočí.",
	["From the south, walk up into the camp below the violet dome of {area:279}. {npc:2411}, {npc:2412} and {npc:2413} (33-34) stand together in the camp, {npc:2414} (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-33) around them drop the Worn Stone Tokens: the ones on the camp's west side are furthest from the Guard's road.\nCareful: Kirin Tor Guards (55) attack the Horde on sight, and one of them patrols the road that comes down into the camp from the north-east and walks right up to the traitors: he has killed many players here. Watch for him, let him walk back up the road, then pull the traitors. Many of the camp's guards stand in linked pairs and others patrol alone. Arcane Sentries (55, elite) and Kirin Tor Enforcers (55) stand around the violet dome itself: keep to the camp below the rim."] = "Od jihu vyjdi do tábora pod fialovou kupolí {area:279}. {npc:2411}, {npc:2412} a {npc:2413} (33–34) stojí v táboře spolu, {npc:2414} (35) kousek západně od nich; každý nese jeden kus Bloodstone. Shield Guards a Theurgists (31–33) kolem nich dropují Worn Stone Tokens: ti na západní straně tábora jsou nejdál od cesty strážce.\nPozor: Kirin Tor Guards (55) útočí na Hordu, jakmile ji uvidí, a jeden z nich hlídkuje po cestě, která sestupuje do tábora ze severovýchodu, a dojde až ke zrádcům: zabil tu spoustu hráčů. Hlídej ho, nech ho odejít zpátky nahoru po cestě a pak tahej zrádce. Mnoho strážců tábora stojí v propojených dvojicích a další hlídkují sami. Kolem samotné fialové kupole stojí Arcane Sentries (55, elite) a Kirin Tor Enforcers (55): drž se tábora pod okrajem.",
	["From {area:280} follow the road south-west to {area:1357} and on west to the ruins north of the {area:279} crater, along the lake shore. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves. Careful: Arcane Sentries (55, elite) and Kirin Tor Guards (55) guard the dome itself and attack the Horde: work the ruins' outer edge and don't go up to the dome."] = "Z {area:280} jdi po silnici na jihozápad do {area:1357} a dál na západ k ruinám severně od kráteru {area:279}, podél břehu jezera. Dalaran Summoners vedou Elemental Slaves; náramky dropují ze slaves. Pozor: Arcane Sentries (55, elite) a Kirin Tor Guards (55) hlídají samotnou kopuli a útočí na Hordu: drž se vnějšího okraje ruin a ke kopuli nechoď.",
	["Go'shek Farm"] = "Go'shek Farm",
	["Head east out of {area:272} through {area:1057} and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south of {area:313}; the Enforcers stay in the cave there."] = "Vyjdi z {area:272} na východ přes {area:1057} a pokračuj po silnici na východ. Boulderfist Ogres a Enforcers (32–34) táboří jižně od silnice, jižně od {area:313}; Enforcers zůstávají v tamní jeskyni.",
	["Head north up the road past {quest:535}'s camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side.\nCareful: Stealthed Syndicate spies roam {area:280}, and the buildings hold many Syndicate mobs, mages among them."] = "Jdi po silnici na sever kolem tábora {quest:535} do {area:280}, vesnice v rukou Syndicate (35–37). {npc:2431} nosí {item:3704}; {quest:503} sedí v kleci v domě na severní straně.\nPozor: {area:280} brázdí špehové Syndicate ve stealthu a v budovách je spousta mobů Syndicate, mezi nimi mágové.",
	["Head south to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Jdi na jih ke goblinské zátoce na jižním pobřeží. {npc:2766} hlídá na útesu nad ní.",
	["Head west; the outer circle stands in the middle of the highlands."] = "Jdi na západ; vnější kruh stojí uprostřed vysočiny.",
	["Hearth back to {area:272} (your hearthstone is bound there), or walk back south-east along the road out of Alterac."] = "Portni se Hearthstonem zpět do {area:272} (máš ho tam nastavený), nebo jdi po silnici zpátky na jihovýchod z Alteracu.",
	["Hearth back to {area:272}: your hearthstone is bound there."] = "Portni se Hearthstonem zpět do {area:272}: máš ho tam nastavený.",
	["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Highland Fleshstalkers (36–37) loví na jižní vysočině, jedna smečka severně od {area:316} a další na pláni západně od něj. Pullni je po jednom.",
	["Highland raptors and Plains Creepers"] = "Raptoři z vysočiny a Plains Creepers",
	["Stromgarde"] = "Stromgarde",
	["Stromgarde quests for a group"] = "Questy ve Stromgarde pro skupinu",
	["Syndicate missives"] = "Zprávy Syndikátu",
	["The Boulderfist Brutes camp outside the ogres' hall, far south-west of {area:321}; the Magus stand among them. Pull them one at a time."] = "Boulderfist Brutes táboří před sálem ogrů, daleko na jihozápad od {area:321}; mezi nimi stojí Magus. Taháš je po jednom.",
	["The inner circle lies south of the western circle, east of Stromgarde."] = "Vnitřní kruh leží jižně od západního kruhu, východně od Stromgarde.",
	["The magus offers a dungeon errand next: leave it."] = "Mágus ti pak nabídne úkol v dungeonu: nech ho být.",
	["The next guide crosses the {area:880} into the {zone:1437} and heads for the {zone:1418}."] = "Další návod přejde {area:880} do {zone:1437} a míří do {zone:1418}.",
	["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate.\n{npc:15126} offers the {quest:8263} only once you are Friendly with the Defilers ({zone:1461}): skip it if he doesn't offer it."] = "Orkská pevnost na východním konci silnice. {npc:2851}, mistr wind riderů, stojí u brány.\n{npc:15126} nabízí {quest:8263} až od Friendly u Defilers ({zone:1461}): když ho nenabídne, přeskoč ho.",
	["The road east through {area:1057}"] = "Silnice na východ přes {area:1057}",
	["The stone's next task needs Fozruk, a level 42 elite who roams west of {area:321}: leave it."] = "Další úkol kamene potřebuje Fozruka, elite levelu 42, který se potuluje západně od {area:321}: nech ho být.",
	["The western circle is near {area:1057}, north-west of the outer one."] = "Západní kruh je blízko {area:1057}, severozápadně od vnějšího.",
	["The {object:138492}"] = "{object:138492}",
	["The {object:2690}"] = "{object:2690}",
	["The {object:2691}"] = "{object:2691}",
	["The {object:2702}"] = "{object:2702}",
	["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Když už jsi v {zone:1458}, vytrénuj se: trenéři stojí v {object:36070}, {object:36073} a {object:36082} (paladinové: {npc:260093}).",
	["Underwater"] = "Pod vodou",
	["West along the foot of the hills, south of the road: a {npc:246848} (55) walks that road from the north-east down into the traitors' camp."] = "Na západ podél úpatí kopců, jižně od silnice: po té silnici chodí {npc:246848} (55) ze severovýchodu dolů do tábora zrádců.",
	["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "Západně od zátoky drží pobřeží Daggerspine Raiders a Sorceresses (38–40): pullni je po jednom. Dva vraky leží na mělčině kousek od něj, mapy a lodní deníky jsou uvnitř; drahokamy leží na mořském dně kolem vraků.",
	["West of the inner circle, Stromgarde's ruins: the Syndicate hold the east half (the Sigil drops from their Conjurors, Prowlers and Magi), the Boulderfist the west half by the {area:325} ({npc:2773} waits in one of the roofless houses beside it)."] = "Západně od vnitřního kruhu jsou ruiny Stromgarde: východní polovinu drží Syndicate (Sigil dropují jejich Conjurors, Prowlers a Magi), západní polovinu u {area:325} Boulderfist ({npc:2773} čeká v jednom z domů bez střechy vedle ní).",
	["{area:17707}: kill these as you meet them"] = "{area:17707}: zabíjej je, jak na ně narazíš",
	["{area:328}: kill these as you meet them"] = "{area:328}: zabíjej je, jak na ně narazíš",
	["{npc:12920}, at the south gate"] = "{npc:12920}, u jižní brány",
	["{npc:12920}, at the south gate. If he won't take the silk, another player may be running Triage: wait a few minutes and talk to him again."] = "{npc:12920}, u jižní brány. Když hedvábí nevezme, možná dělá Triage jiný hráč: pár minut počkej a promluv s ním znovu.",
	["{npc:12920}, at the south gate. If {npc:12920} offers nothing, another player may be running his {skill:129} quest Triage: he can be busy for a few minutes. Wait, then talk to him again."] = "{npc:12920}, u jižní brány. Když ti {npc:12920} nic nenabízí, možná dělá jiný hráč jeho quest na {skill:129} Triage: může být pár minut zaneprázdněný. Počkej a pak s ním promluv znovu.",
	["{npc:2229}, inside"] = "{npc:2229}, uvnitř",
	["{npc:2410}, inside"] = "{npc:2410}, uvnitř",
	["{npc:2437}, inside"] = "{npc:2437}, uvnitř",
	["{npc:270038} stands in the Apothecarium."] = "{npc:270038} stojí v Apothecariu.",
	["{npc:270038}: Stormheart's heart from {zone:1441}"] = "{npc:270038}: Stormheartovo srdce ze {zone:1441}",
	["{npc:2703}'s {quest:639} drops from the elite Syndicate (35-38) in Stromgarde's ruins, the west of the highlands. Great XP if you have a group for it: the route passes Stromgarde on its way to the inner circle."] = "{quest:639} od {npc:2703} dropuje elite Syndicate (35–38) v ruinách Stromgarde na západě vysočiny. Skvělé XP, pokud na to máš skupinu: trasa jde přes Stromgarde cestou do vnitřního kruhu.",
	["{npc:2733}'s lab shack stands at Go'shek Farm, north-east of the raptors' plain on the way back to {area:321}; the case of {item:278462} is inside."] = "Laboratorní bouda {npc:2733} stojí na Go'shek Farm, severovýchodně od pláně s raptory, po cestě zpátky do {area:321}; bedna s {item:278462} je uvnitř.",
	["{npc:2770}: for {npc:2771} in {area:321}, later in this guide"] = "{npc:2770}: pro {npc:2771} v {area:321}, později v tomhle návodu",
	["{npc:2771}'s next {quest:678} and {npc:2772}'s {quest:680} are the elite ogres (38-40) in Stromgarde's ogre quarter, on the same group trip as the Sigil."] = "Další {quest:678} od {npc:2771} a {quest:680} od {npc:2772} jsou elite ogři (38–40) v ogří čtvrti Stromgarde, na stejné skupinové výpravě jako Sigil.",
	["{npc:2772}, beside him"] = "{npc:2772}, vedle něj",
	["{npc:2792}, by the gate"] = "{npc:2792}, u brány",
	["{quest:503}, on the top floor"] = "{quest:503}, v nejvyšším patře",
	["{zone:1458} flight master"] = "letový mistr {zone:1458}",
}
t.guides["forever/horde/30-40/06-badlands"] = {
	["Below ground"] = "Pod zemí",
	["Head back south down the road, past the {area:1877}."] = "Vrať se po silnici na jih, kolem {area:1877}.",
	["Head for the {object:2673}, the great bridge at Arathi's southern edge, cross it and follow the road south through the {zone:1437} to the {object:1668} tunnel into {zone:1432}. {area:144}, the dwarf town on the road in the middle of {zone:1432}, has guards who attack the Horde: leave the road before it and pass the town on the hills to its west. The road leaves {zone:1432} to the south into the {zone:1418}; follow it to the goblin camp in the {area:1877}."] = "Zamiř k {object:2673}, velkému mostu na jižním okraji Arathi, přejdi ho a po silnici na jih přes {zone:1437} k tunelu {object:1668} do {zone:1432}. {area:144}, trpasličí město na silnici uprostřed {zone:1432}, má stráže, které útočí na Hordu: před ním sejdi ze silnice a obejdi město kopci na západě. Silnice opouští {zone:1432} na jih do {zone:1418}; jdi po ní do goblinského tábora v {area:1877}.",
	["Head west along the road towards {area:340}; {npc:2921}'s camp sits in the {area:1878} halfway there."] = "Jdi po silnici na západ směrem k {area:340}; tábor {npc:2921} je v {area:1878} v polovině cesty.",
	["Head west back to {area:340}. {npc:5394} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "Vrať se na západ do {area:340}. {npc:5394} stojí v horním patře {area:340}, vysoko nad letovým mistrem: jdi nahoru po rampách, šipka patra nerozliší.",
	["Into the {zone:1418}"] = "Do {zone:1418}",
	["Lesser Rock Elementals"] = "Lesser Rock Elementals",
	["Stonevault troggs"] = "Troggové Stonevault",
	["The Elder Crag Coyotes and Giant Buzzards roam the basin south of the {area:1878}. Coyotes drop both the jawbones and the fangs; the Giant Buzzards drop the gizzards. Careful: Malevolent Mirages (42, elite) drift across the {zone:1418}: give them a wide berth.\nCareful: the Giant Buzzards are 39-41, and the 41s are two over you at 39: pick the 39s and 40s and pull them one at a time. The Buzzards (37) you kill later for {npc:2817}'s wings drop gizzards too, more rarely."] = "Elder Crag Coyotes a Giant Buzzards se potulují po pánvi jižně od {area:1878}. Kojoti dropují čelisti i tesáky; Giant Buzzards dropují žaludky. Pozor: po {zone:1418} se toulají Malevolent Mirages (42, elite): obejdi je velkým obloukem.\nPozor: Giant Buzzards mají 39–41 a ti na 41 jsou na 39 o dva levely nad tebou: vybírej ty na 39 a 40 a taháš je po jednom. Buzzards (37), které později zabíjíš kvůli křídlům pro {npc:2817}, dropují žaludky taky, jen vzácněji.",
	["The next guide flies from {area:340} to {object:3202}."] = "Další návod letí z {area:340} do {object:3202}.",
	["The road north to {area:1517} runs through the {area:1877}: {npc:2817} and {npc:4618} take the wings and the flakes on the way."] = "Silnice na sever do {area:1517} vede přes {area:1877}: {npc:2817} a {npc:4618} cestou převezmou křídla a vločky.",
	["The small elementals drift across the flats between {area:340} and {npc:2921}'s camp, on the road back east. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards."] = "Malí elementálové se potulují po pláních mezi {area:340} a táborem {npc:2921}, na silnici zpátky na východ. Rock Elemental Shards pro {npc:6868} může dropnout každý kamenný elementál v zóně.",
	["{area:340} is the Horde fortress built into the cliffs at the zone's western edge. {quest:1418} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "{area:340} je hordská pevnost vestavěná do útesů na západním okraji zóny. {quest:1418} stojí v horním patře {area:340}, vysoko nad letovým mistrem: jdi nahoru po rampách, šipka patra nerozliší.",
	["{npc:2921}'s next study wants bracers from the Greater Rock Elementals (42-44) in the south-western gulches, well above you: leave it."] = "Další výzkum od {npc:2921} chce náramky z Greater Rock Elementals (42–44) v jihozápadních roklích, vysoko nad tebou: nech to být.",
	["{npc:6868}, inside"] = "{npc:6868}, uvnitř",
	["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}: Fizzlův dopis z {area:439}",
	["{zone:1418}: kill these as you meet them"] = "{zone:1418}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "\"Sea Wolf\" MacKinley, v nejvyšším patře",
	["Draenethyst crystals"] = "Krystaly Draenethyst",
	["Felsteed: Zevrost in {zone:1454}, then {npc:6251} in {area:392}, on the {zone:1444} guide's {zone:1454} stop."] = "Felsteed: Zevrost v {zone:1454}, pak {npc:6251} v {area:392}, na zastávce {zone:1454} v návodu {zone:1444}.",
	["Fly back to {object:3202}: Zul'Mamwe's Skullsplitters are just east of it."] = "Leť zpátky do {object:3202}: Skullsplitters ze Zul'Mamwe jsou kousek na východ od něj.",
	["Fly to the {area:1497}"] = "Leť do {area:1497}",
	["Fly to {area:35}"] = "Leť do {area:35}",
	["Fly to {object:3202}"] = "Leť do {object:3202}",
	["Follow the road east from {zone:1431} through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp just off the road where it comes in from {zone:1430}."] = "Jdi po silnici na východ z {zone:1431} přes {zone:1430} do bažiny. {npc:1776} čeká u {area:657}, tábora draenei kousek od silnice, kde přichází z {zone:1430}.",
	["From {object:3202} head east to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. One pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all. Careful: {npc:1059} (45) walks the south-western ruins with two guards; Speaking with {npc:1061}'s last piece, his Broken Armor, waits for your Stranglethorn stop at about 45."] = "Od {object:3202} zamiř na východ k ruinám Skullsplitter východně od dolu Venture Co.; pullni headhuntery a berserkery po jednom. Jedna hromada trofejních lebek stojí na severní straně ruin. Každý Skullsplitter může dropnout kel nebo náhrdelník: náhrdelníky jdou pomalu, tak zabíjej v táboře warriorů severně od ruin, dokud je nemáš všechny. Pozor: {npc:1059} (45) chodí po jihozápadních ruinách se dvěma strážemi; Speaking with {npc:1061}, poslední kus, jeho Broken Armor, počká na tvou zastávku ve Stranglethornu kolem levelu 45.",
	["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Dál na sever kopou goblini z Venture Co. v dole východně od silnice; krystaly dropují miners, foremen, surveyors i tinkerers.\nPozor: Okolí tábora brázdí Shadowmaw Panthers ve stealthu a Stranglethorn Tigresses.",
	["Gringer, the flight master, waits on {area:35}'s upper deck. The quest givers stand on the boardwalks around the harbour and in the inn."] = "Gringer, letový mistr, čeká na horní palubě v {area:35}. Zadavatelé questů stojí na molech kolem přístavu a v hostinci.",
	["Head east to {area:75}, in the reeds south of the road."] = "Jdi na východ do {area:75}, do rákosí jižně od silnice.",
	["Head north up the road to the hunters' camp."] = "Jdi po silnici na sever do tábora lovců.",
	["Head north up the road; the hunters camp on the hill above the river."] = "Jdi po silnici na sever; lovci táboří na kopci nad řekou.",
	["Head north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "Jdi na severovýchod k {area:76}. Krystaly stojí podél cesty nahoru ke kleci {npc:5391}.",
	["Head south to {area:35}. Shaky Phillipe waits on the docks."] = "Jdi na jih do {area:35}. Shaky Phillipe čeká na molech.",
	["Head west along the road to the draenei camp at the {area:657}, near the way in from {zone:1430}. {quest:698} goes to {npc:5592} at {area:1978} on the next swamp visit: keep the flanks."] = "Jdi po silnici na západ k táboru draenei u {area:657}, blízko cesty ze {zone:1430}. {quest:698} jde k {npc:5592} v {area:1978} při další návštěvě bažiny: boky si nech.",
	["Head west to {object:3202}."] = "Jdi na západ k {object:3202}.",
	["His strongbox waits at his old camp north of {area:75}, on the way back west."] = "Jeho truhlička čeká v jeho starém táboře severně od {area:75}, cestou zpátky na západ.",
	["Into the {zone:1435}"] = "Do {zone:1435}",
	["MacKinley, on the top floor: for Stoley in {zone:1446}"] = "MacKinley v nejvyšším patře: pro Stoleyho v {zone:1446}",
	["MacKinley: keep it, the ghost pirates (43-44) wait for your Stranglethorn stop at about 45"] = "MacKinley: nech si ho, pirátští duchové (43–44) počkají na tvou zastávku ve Stranglethornu kolem levelu 45",
	["Mistvale gorillas"] = "Gorily Mistvale",
	["Nesingwary's camp"] = "Nesingwaryho tábor",
	["The Bloodsail ships"] = "Lodě Bloodsail",
	["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "Krokodýli se válí v jezírkách kolem tábora {npc:5391} a na jih k {area:75}; zhruba každý čtvrtý dropne kýtu.",
	["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang: keep ten for Unbagwa, whose Mokk (44) waits for your Stranglethorn stop at about 45.\nCareful: the Elder Mistvale Gorillas (40-41) stand close together in the valley: pull one at a time."] = "Gorily se potulují údolím kolem Unbagwy. Drůbky dropují starší gorily; tesák může dropnout kterákoli: nech si deset pro Unbagwu, jehož Mokk (44) čeká na tvou zastávku ve Stranglethornu zhruba na levelu 45.\nPozor: Elder Mistvale Gorillas (40–41) stojí v údolí blízko u sebe: pulluj po jedné.",
	["The naga explorers on the coast south of here (43-44) are for Bloads and Mok'thardin: keep both quests for your Stranglethorn stop at about 45."] = "Průzkumníci nagů na pobřeží jižně odsud (43–44) jsou pro Bloadse a Mok'thardina: oba questy si nech na zastávku ve Stranglethornu zhruba na levelu 45.",
	["The next trophy skulls stand in the small ruins just north of the warriors' camp.\nThe last skulls are in the ruins a short walk west, on the way back to {object:3202}."] = "Další trofejní lebky stojí v malých ruinách kousek severně od tábora válečníků.\nPoslední lebky jsou v ruinách kousek na západ, cestou zpátky do {object:3202}.",
	["The scroll, {quest:624}, lies on the decks of the three ships off the {area:43}, crewed by pirates of 42-45 who come in pairs, with captains of 45-48: take it with a group. Its chain runs on through the {zone:1435}, {zone:1445} and the {zone:1425}."] = "Svitek, {quest:624}, leží na palubách tří lodí u {area:43}, s posádkami pirátů levelu 42–45, kteří chodí po dvou, a kapitány levelu 45–48: jdi na to se skupinou. Jeho řetězec pokračuje přes {zone:1435}, {zone:1445} a {zone:1425}.",
	["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast.\nCareful: the Jungle Stalkers (40-41) are thick here: pull one at a time and rest between fights."] = "Raptoři Stalker loví v džungli jižně od {object:3202}, směrem k západnímu pobřeží.\nPozor: Jungle Stalkers (40–41) je tu hustě: pulluj po jednom a mezi boji odpočívej.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone."] = "Tohle jsou elite moby: vyplatí se jít ve skupině, poohlédni se po lidech. {npc:730} je elite na levelu 43: většina tříd ho sólo zvládne na levelu 45, ale možná budeš potřebovat pomoc. Pokud jsi sám, přeskoč ho.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Tohle jsou elite moby: vyplatí se jít ve skupině, poohlédni se po lidech. {npc:731} je elite na levelu 43: většina tříd ho sólo zvládne na levelu 45, ale možná budeš potřebovat pomoc. Pokud jsi sám, přeskoč ho.\nPozor: kolem něj se pohybují tygři a panteři shadowmaw ve stealthu. Vyčisti je, než ho pullneš. Jakmile ho pullneš, {npc:731} si zavolá na pomoc tvory do 20 yd.",
	["Venture Co. mine"] = "Důl Venture Co.",
	["Warlocks don't buy riding: your mount is the Felsteed, from your class quest. Zevrost in {zone:1454}'s {object:172960} starts it and {npc:6251} in {area:392} teaches it, both on the {zone:1444} guide's {zone:1454} stop at about 45."] = "Warlockové si riding nekupují: tvůj mount je Felsteed z class questu. Spouští ho Zevrost v {object:172960} v {zone:1454} a učí ho {npc:6251} v {area:392}, obojí na zastávce v {zone:1454} v návodu pro {zone:1444} kolem levelu 45.",
	["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them.\nOn the coast between Zul'Kunda and {object:3202} an {npc:2635} (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for {npc:2495}."] = "Západně od expedice stojí náčelníci Bloodscalp {npc:1061} a {npc:1062} spolu v ruinách Zul'Kunda. Nejdřív vyčisti jejich stráže, pak je pullni.\nNa pobřeží mezi Zul'Kunda a {object:3202} sdílí spawny s obyčejnými krokolisky {npc:2635} (elite na levelu 38): když je venku, zabij ho a vezmi jeho kůži pro {npc:2495}.",
	["{area:127}: kill these as you meet them"] = "{area:127}: zabíjej je, jak na ně narazíš",
	["{area:340} flight master"] = "letový mistr {area:340}",
	["{area:35} flight master"] = "letový mistr {area:35}",
	["{npc:1442}, upstairs"] = "{npc:1442}, nahoře",
	["{npc:1443}, on the top floor"] = "{npc:1443}, v nejvyšším patře",
	["{npc:265756}, riding trainer, at the {area:17684} in {area:16638}"] = "{npc:265756}, trenér jízdy, v {area:17684} v {area:16638}",
	["{npc:3690}, riding trainer"] = "{npc:3690}, trenér jízdy",
	["{npc:4631}, on the docks: Gazlowe's letter, if you carry it"] = "{npc:4631}, na docích: Gazlowův dopis, pokud ho neseš",
	["{npc:4631}: {quest:97332}, after Zimmix's rescue; the package goes to {npc:259961} at {area:16727}, in the {zone:2548} guide"] = "{npc:4631}: {quest:97332}, po záchraně Zimmixe; balík jde k {npc:259961} do {area:16727}, v návodu pro {zone:2548}",
	["{npc:4752}, riding trainer"] = "{npc:4752}, trenér jízdy",
	["{npc:4773}, riding trainer"] = "{npc:4773}, trenér jízdy",
	["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} je držen v {area:76} na severovýchodě bažiny. Osvoboď ho a jdi za ním ven, přitom odrážej bažinné tvory, kteří ho pronásledují.",
	["{npc:5591}, inside"] = "{npc:5591}, uvnitř",
	["{npc:737}, upstairs"] = "{npc:737}, nahoře",
	["{npc:7953}, riding trainer"] = "{npc:7953}, trenér jízdy",
	["{object:3202} flight master"] = "letový mistr {object:3202}",
}
t.guides["forever/horde/40-50/01b-riverglades"] = {
	["About 70 quests in Forever's new zone, from the fort of {area:16743}."] = "Asi 70 questů v nové zóně Foreveru, z pevnosti {area:16743}.",
	["Across the {area:3} to {area:340}, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress."] = "Přes {area:3} do {area:340}, pevnosti Hordy vestavěné do útesů na západním okraji zóny: její letový mistr stojí u paty pevnosti.",
	["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Zpět na sever po břehu: cestou k crawlerům odevzdej v docích murloky a kůži.",
	["Back through the port"] = "Zpět přes přístav",
	["Back to the port, from the north pier west through the docks."] = "Zpět do přístavu, ze severního mola na západ přes doky.",
	["Back to the port."] = "Zpět do přístavu.",
	["Back to {area:16743} from the port, where your Hearthstone is set. {npc:256418} in the middle of the fort: {npc:255829}'s word sends him looking for {npc:258570}, his warrior in the west."] = "Zpět do {area:16743} z přístavu, kde máš nastavený Hearthstone. {npc:256418} uprostřed pevnosti: slovo {npc:255829} ho pošle hledat {npc:258570}, jeho válečníka na západě.",
	["Back to {area:16743}, where your Hearthstone is set: {npc:263190} on the fort's west side first, then {npc:256418}, {npc:256655} by the cook fire, {npc:256657} and {npc:258031} on your way east through the fort."] = "Zpět do {area:16743}, kde máš nastavený Hearthstone: nejdřív {npc:263190} na západní straně pevnosti, pak {npc:256418}, {npc:256655} u kuchařského ohně, {npc:256657} a {npc:258031} cestou na východ přes pevnost.",
	["Back to {npc:255829} on his hill. {npc:257062} runs the {quest:94668} just below it."] = "Zpět k {npc:255829} na jeho kopec. {npc:257062} vede {quest:94668} hned pod ním.",
	["Boat to {area:16727}"] = "Loď do {area:16727}",
	["Bonegnaw"] = "Bonegnaw",
	["Careful: {npc:256899}, the two-headed ogre at the western edge of {area:16723}, is an elite (level 41): grouping up is advised under 43. Clear the cultists around him first and come in with full health and mana: recorded players of 42-43 killed him alone. {npc:255829}'s quests in {area:16726} wait on this one: skip him and {quest:95420}, the {area:16726} quests and {npc:258570}'s camp in the west go with him (about 21,000 XP); the guide then leaves them out."] = "Pozor: {npc:256899}, dvouhlavý zlobr na západním okraji {area:16723}, je elitní (level 41): pod 43 se doporučuje skupina. Nejdřív vybij kultisty kolem něj a přijď s plným zdravím a manou: zaznamenaní hráči 42–43 ho zabili sami. Questy {npc:255829} v {area:16726} na něm závisí: když ho přeskočíš, s ním odpadne {quest:95420}, questy {area:16726} a tábor {npc:258570} na západě (asi 21 000 XP); návod je pak vynechá.",
	["Down to the port."] = "Dolů do přístavu.",
	["Each bout is a fight in the ring below {npc:255829}'s hill against an elite: Buzzbeak (41), Kronk and Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) and {npc:257059} (45). Come in rested, with full health and mana; if a bout goes wrong, {npc:257062} offers it again."] = "Každé kolo je souboj v ringu pod kopcem {npc:255829} proti elitě: Buzzbeak (41), Kronk a Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) a {npc:257059} (45). Přijď odpočatý, s plným zdravím a manou; když se kolo pokazí, {npc:257062} ho nabídne znovu.",
	["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Na východ podél útesů na vzdálený konec tábora pirátů: {npc:260390} čeká u vody, {npc:260391} vedle něj.",
	["East back to {area:16743}."] = "Na východ zpět do {area:16743}.",
	["East back to {area:16743}: {npc:260931}'s word goes to {npc:256710}, and {npc:256710}'s to {npc:255829}, the ogres' chieftain."] = "Na východ zpět do {area:16743}: slovo {npc:260931} jde k {npc:256710} a slovo {npc:256710} k {npc:255829}, náčelníkovi zlobrů.",
	["East of Rog'mar, on the hill above the road to {area:16727}: {npc:263367} has his workshop there. The gas vents are in the marsh south-west of it, on your first hunt for {npc:258031}."] = "Východně od Rog'maru, na kopci nad cestou do {area:16727}: má tam dílnu {npc:263367}. Plynové průduchy jsou v bažině jihozápadně od ní, při tvém prvním lovu pro {npc:258031}.",
	["East to {area:16735}, the Alliance farm by the river: the farmhands work the fields and the feed satchels lie by the barns. {area:16744}, the Alliance outpost on the road, has guards: pass south of it.\nCareful: {npc:263380}, an elite (level 42), hunts along the river by the farm: keep an eye on the riverbank."] = "Na východ do {area:16735}, farmy Aliance u řeky: na polích pracují pomocníci a vaky s krmivem leží u stodol. {area:16744}, stanoviště Aliance na cestě, má stráže: projdi jižně od něj.\nPozor: {npc:263380}, elita (level 42), loví podél řeky u farmy: hlídej břeh.",
	["Finish the {item:268632}"] = "Dokonči {item:268632}",
	["Fly to {area:340}"] = "Leť do {area:340}",
	["Fly to {area:484}"] = "Leť do {area:484}",
	["Frazzlespark's crate from the port goes to {npc:256418}, in the middle of the fort."] = "Frazzlesparkova bedna z přístavu jde k {npc:256418}, uprostřed pevnosti.",
	["Into the {area:16591}"] = "Do {area:16591}",
	["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42) wanders the shore and {npc:263380} (elite, 42) the river: take your beasts away from them."] = "Většina zvířat v {zone:2548} dropuje {item:268632} pro {npc:260231}: krabi na tomhle pobřeží a kanci na hřebeni západně od pirátů.\nPozor: {npc:257001} (elite, 42) se toulá po pobřeží a {npc:263380} (elite, 42) po řece: odveď svá zvířata od nich.",
	["New in Forever: if a step is wrong, tell us on Evertally's Discord or GitHub and name the step.\n{npc:255897} keeps a stall at the west end of the docks. The port's other jobs are for later in this guide: this crate goes to the Horde's fort."] = "Novinka ve Forever: pokud je nějaký krok špatně, napiš nám na Discord nebo GitHub Evertally a uveď, o který krok jde.\n{npc:255897} má stánek na západním konci přístaviště. Ostatní práce v přístavu přijdou až později v tomhle návodu: tahle bedna jde do hordské pevnosti.",
	["New in Forever: this guide follows what players did in the {area:16591}. If a step is wrong, tell us on Evertally's Discord or GitHub and name the step.\nFrom {area:340}, ride south-east across the {area:3} to the zone's southern edge: the pass of {area:16685} leads down into the {area:16591}. {area:16743}, the Horde's fort, stands in the middle of the zone, east along the valley."] = "Novinka ve Forever: tento návod sleduje, co hráči dělali v {area:16591}. Pokud je nějaký krok špatně, napiš nám na Discord nebo GitHub Evertally a uveď, o který krok jde.\nZ {area:340} jeď na jihovýchod přes {area:3} k jižnímu okraji zóny: průsmyk {area:16685} vede dolů do {area:16591}. {area:16743}, hordská pevnost, stojí uprostřed zóny, na východ podél údolí.",
	["New in Forever: this guide follows what players did in the {zone:2548}. If a step is wrong, tell us on Evertally's Discord or GitHub and name the step.\nThe {zone:2548} lie across the sea from {zone:1446}: a goblin boat sails from {area:977}, north-east of {area:976}, to {area:16727}. Fly to {area:484} in {zone:1441} and head south-east through the {area:439} to {area:976}. (If you already know {area:340} in the {area:3}, the way in through {area:16685} works too.)"] = "Novinka ve Forever: tento návod sleduje, co hráči dělali v {zone:2548}. Pokud je nějaký krok špatně, napiš nám na Discord nebo GitHub Evertally a uveď, o který krok jde.\n{zone:2548} leží přes moře od {zone:1446}: goblinní loď pluje z {area:977}, severovýchodně od {area:976}, do {area:16727}. Leť do {area:484} v {zone:1441} a zamiř na jihovýchod přes {area:439} do {area:976}. (Pokud už znáš {area:340} v {area:3}, funguje i cesta přes {area:16685}.)",
	["Out to the pirates' cliffs once more. Plant Whizzbuzz's charges on the three ships moored below the camp, south to north; {quest:95124} stands by the middle one, with her loot chest beside her. Keep an eye out for {npc:259758} on the way.\nCareful: {quest:95124} is level 45, a level or two over you here: clear the deck around her first and come in with full health."] = "Ještě jednou ven k pirátským útesům. Polož Whizzbuzzovy nálože na tři lodě kotvící pod táborem, od jihu k severu; {quest:95124} stojí u té prostřední a vedle ní je její truhla s lootem. Cestou se dívej po {npc:259758}.\nPozor: {quest:95124} má level 45, o level nebo dva víc než ty: nejdřív vyčisti palubu kolem ní a jdi na ni s plným zdravím.",
	["The Cinderscale hollow"] = "Prohlubeň Cinderscale",
	["The Eastsea pirates"] = "Piráti Eastsea",
	["The Glade Vipers hide in the long grass south-east of town; the Roving Tallstriders graze beside them. {npc:257079}, an Alliance elite (level 45), rides the road from {area:16729} to {area:16725} along the grass's south-west edge: keep clear of him."] = "Glade Vipers se schovávají ve vysoké trávě jihovýchodně od města; vedle nich se pasou Roving Tallstriders. {npc:257079}, alianční elite (level 45), jezdí po cestě z {area:16729} do {area:16725} podél jihozápadního okraje trávy: drž se od něj dál.",
	["The crawlers and {npc:260235}"] = "Lezouni a {npc:260235}",
	["The cult's camps fill the valley south and west of {npc:258570}. Free the captive Rog'mar Scouts as you find them. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. {npc:256881} and {npc:256891} (elites, 46) hold the fortress at the valley's head: pull the cultists away from them. {npc:258023}'s Alliance camp sits at the valley's south end, and its Farholde Lookouts (level 46) attack the Horde: stay north of it."] = "Tábory kultu vyplňují údolí jižně a západně od {npc:258570}. Zajaté Rog'mar Scouts osvobozuj, jak na ně narazíš. Tábory procházejí Twilight Enforcers (elite, level 45): před každým pullem sleduj, kudy chodí. {npc:256881} a {npc:256891} (elite, 46) drží pevnost v čele údolí: odtahuj kultisty od nich. Na jižním konci údolí leží aliancí tábor {npc:258023} a jeho Farholde Lookouts (level 46) útočí na Hordu: drž se severně od něj.",
	["The cultists fill the streets and fields; the Shadowmancers on the town's northern side carry the missives. The finger bones drop from all of them.\nCareful: {npc:256899}, an elite ogre (level 41), walks the western streets of {area:16723}, around 44-47,47-52. Pull the cultists out towards you and let him pass."] = "Kultisté zaplňují ulice a pole; zprávy nosí Shadowmancers na severní straně města. Kosti prstů dropují všichni.\nPozor: Západními ulicemi {area:16723}, kolem 44-47,47-52, chodí {npc:256899}, elite zlobr (level 41). Vytahuj kultisty k sobě a nech ho projít.",
	["The lions"] = "Lvi",
	["The murlocs, south-west"] = "Murloci, jihozápad",
	["The next guide flies from {area:340} in the {area:3}: north out of {npc:258570}'s valley and up through {area:16685}, the way through to the {area:3}."] = "Další návod letí z {area:340} v {area:3}: na sever z údolí {npc:258570} a nahoru přes {area:16685}, cestou do {area:3}.",
	["The ogre mine"] = "Důl zlobrů",
	["The paletusks"] = "Paletusks",
	["The pirates' second wave"] = "Druhá vlna pirátů",
	["The pirates' ships"] = "Pirátské lodě",
	["The plains and the marsh"] = "Pláně a močál",
	["The ritual grounds"] = "Rituální místo",
	["The ritualists and their empowered brutes gather at the ritual circles in the middle of {area:16723}: wreck five of the circles.\nCareful: {npc:256899}, the elite ogre (level 41), walks through here from the western streets: watch for him before each pull."] = "Ritualisté a jejich posílení brutálové se shromažďují u rituálních kruhů uprostřed {area:16723}: znič pět kruhů.\nPozor: Tudy prochází ze západních ulic {npc:256899}, elite zlobr (level 41): před každým pullem se po něm podívej.",
	["The river and the Farholde camp"] = "Řeka a tábor Farholde",
	["The training grounds"] = "Cvičiště",
	["The vipers and the tallstriders"] = "Zmije a tallstriders",
	["The whelps nest all over the hollow; the warriors guard its back, by the {item:271611}. The warriors are level 41-42: pull them one at a time. Scaldaron, a rare elite drake, can be up here too: leave him be unless you have a group."] = "Dráčci hnízdí po celé prohlubni; válečníci hlídají její zadní část u {item:271611}. Válečníci mají level 41–42: pulluj je po jednom. Nahoře může být i Scaldaron, rare elite drak: bez skupiny ho nech být.",
	["The {area:16737}"] = "{area:16737}",
	["West back to {area:16743}'s east side."] = "Na západ zpátky na východní stranu {area:16743}.",
	["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "Od severní lodi na západ, nahoru na hřbet: Rotflesh Mushrooms rostou mezi skalami blízko tábora ogrů Twilight. Vnitřnosti dávají i Mature Paletusks na hřebeni.",
	["West from {area:16743} through {area:16723} and on up the valley towards {area:16685}: {npc:258570}, {npc:256418}'s wayward warrior, keeps a camp in the hills below the Twilight cult's fortress."] = "Z {area:16743} na západ přes {area:16723} a dál nahoru údolím k {area:16685}: {npc:258570}, zatoulaný warrior od {npc:256418}, má tábor v kopcích pod pevností kultu Twilight.",
	["West into the {area:16737}: the Redridge gnolls camp along the slopes and carry the stolen ore. Work south-west through their camps.\nCareful: {npc:255906}, an elite gnoll (level 40), roams the south-western camps: pull the gnolls away from him."] = "Na západ do {area:16737}: gnollové Redridge tábořící po svazích nesou ukradenou rudu. Postupuj jejich tábory na jihozápad.\nPozor: po jihozápadních táborech se toulá {npc:255906}, elite gnoll (level 40): odtahuj gnolly od něj.",
	["West of Rog'mar the Twilight cult holds the farm town of {area:16723}. {npc:259158}, a kobold who wants out, hides in the middle of the town."] = "Západně od Rog'mar drží kult Twilight farmářské městečko {area:16723}. {npc:259158}, kobold, který chce pryč, se schovává uprostřed města.",
	["West to {area:16723} again: {npc:260931}, a Twilight miner who wants out, waits at the town's eastern edge. Talk him round, then hand {npc:256710}'s quest in; one of the missing ogres stands a few steps west."] = "Znovu na západ do {area:16723}: {npc:260931}, horník Twilight, který chce pryč, čeká na východním okraji města. Přemluv ho, pak odevzdej quest od {npc:256710}; jeden z pohřešovaných ogrů stojí pár kroků na západ.",
	["West to {area:16743}, the Horde's fort in the middle of the zone. {npc:258031} stands on its east side, {npc:256657} and {npc:256418} in the middle with {npc:255993}, the wind rider master; {npc:256675} and {npc:263190} on the west side."] = "Na západ do {area:16743}, pevnosti Hordy uprostřed zóny. {npc:258031} stojí na její východní straně, {npc:256657} a {npc:256418} uprostřed s {npc:255993}, mistrem wind riderů; {npc:256675} a {npc:263190} na západní straně.",
	["West up the road from the port: {npc:263367} has his workshop on the hill. The gas vents are in the marsh south-west of it, on your first hunt for {npc:258031}."] = "Z přístavu po silnici na západ do kopce: {npc:263367} má dílnu na kopci. Plynové průduchy jsou v bažině jihozápadně od ní, při tvém prvním lovu pro {npc:258031}.",
	["{area:75} flight master"] = "letový mistr {area:75}",
	["{area:977} is on the coast north-east of {area:976}: wait on the pier for the goblin boat to {area:16727}."] = "{area:977} je na pobřeží severovýchodně od {area:976}: na molu počkej na goblinskou loď do {area:16727}.",
	["{item:269257}, from {npc:260973}"] = "{item:269257}, od {npc:260973}",
	["{npc:256728}'s camp"] = "tábor {npc:256728}",
	["{npc:263190}: {quest:95033}, for {npc:8115} at {area:1099} in the {zone:1444} guide"] = "{npc:263190}: {quest:95033} pro {npc:8115} v {area:1099} v návodu pro {zone:1444}",
	["{npc:263315}, an elite lion (level 41), prowls the plains south of {area:16743}, where the lions are: grouping up is advised."] = "{npc:263315}, elite lev (level 41), se potuluje po pláních jižně od {area:16743}, kde jsou lvi: doporučuje se skupina.",
	["{npc:263367}'s workshop"] = "Dílna {npc:263367}",
	["{npc:263380} is an elite (level 42) who hunts along the river south-west of {area:16743}, by the Farholde camp you go to next: grouping up is advised. The poster hangs in the middle of the fort."] = "{npc:263380} je elite (level 42), který loví podél řeky jihozápadně od {area:16743}, u tábora Farholde, kam jdeš dál: doporučuje se skupina. Plakát visí uprostřed pevnosti.",
	["{quest:93976}: for {npc:255897} in {area:16727}, keep it"] = "{quest:93976}: pro {npc:255897} v {area:16727}, nech si ho",
	["{quest:94727}: for {npc:260931} in {area:16723}"] = "{quest:94727}: pro {npc:260931} v {area:16723}",
	["{quest:95062}: for {npc:256418} in {area:16743}"] = "{quest:95062}: pro {npc:256418} v {area:16743}",
	["{quest:95418}: for {npc:256710} in {area:16743}"] = "{quest:95418}: pro {npc:256710} v {area:16743}",
	["{quest:95420}: for {npc:255829} in {area:16726}"] = "{quest:95420}: pro {npc:255829} v {area:16726}",
}
t.guides["forever/horde/40-50/02-feralas"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "\"Sea Wolf\" MacKinley, v nejvyšším patře",
	["Back into town. The ships' captains, Seahorn's next request, are for your Stranglethorn stop at about 50."] = "Zpět do města. Kapitáni lodí, další Seahornova prosba, jsou na tvou zastávku ve Stranglethornu kolem 50.",
	["Back west to {object:3202}."] = "Zpět na západ k {object:3202}.",
	["Below ground"] = "Pod zemí",
	["Coming from the {zone:2548}: {area:340}'s flight master stands at the foot of the fortress."] = "Když jdeš z {zone:2548}: letový mistr {area:340} stojí u paty pevnosti.",
	["Flown in to {area:976}: the raceway is a short ride north over the {zone:1446} border.\nThe road from {area:484} to {zone:1446} runs past the {area:2240} on the {area:439}: {npc:4454} is in the gnomes' camp beside the track, {npc:4630} and {npc:4709} by the goblins' camp. {npc:4630} first, then {npc:4709}, who runs off to keep Rizzle busy; then take Rizzle's plans from the gnomes' camp and bring them back to {npc:4630}."] = "Přiletěl jsi do {area:976}: závodní dráha je kousek jízdy na sever přes hranici {zone:1446}.\nCesta z {area:484} do {zone:1446} vede kolem {area:2240} na {area:439}: {npc:4454} je v táboře gnómů vedle dráhy, {npc:4630} a {npc:4709} u tábora goblinů. Nejdřív {npc:4630}, pak {npc:4709}, který odběhne zaměstnat Rizzla; pak vezmi Rizzlovy plány z tábora gnómů a přines je zpátky {npc:4630}.",
	["Flown in: {area:976}'s quests first, by the flight master, then the {area:2240} is a short ride north over the {zone:1446} border."] = "Přiletěl jsi: nejdřív questy v {area:976} u letového mistra, pak je {area:2240} kousek jízdy na sever přes hranici {zone:1446}.",
	["Fly from {zone:1454} to {area:392}; {npc:6251} stands on the hill above the docks."] = "Leť ze {zone:1454} do {area:392}; {npc:6251} stojí na kopci nad přístavem.",
	["Fly to {area:1638}"] = "Leť do {area:1638}",
	["Fly to {area:484}"] = "Leť do {area:484}",
	["Fly to {area:976}"] = "Leť do {area:976}",
	["Fly to {object:3202}"] = "Leť do {object:3202}",
	["For your {area:978} run, in the next guide: {quest:2864} wants scarab shells, and {npc:7804}, a short walk from the flight master, {quest:3042} from the Sandfury trolls."] = "Pro tvůj průchod {area:978}, v dalším návodu: {quest:2864} chce skarabeí krunýře a {npc:7804}, kousek pěšky od letového mistra, {quest:3042} od trollů Sandfury.",
	["Grimtotem camp"] = "Tábor Grimtotem",
	["In {area:35}: {npc:2494} on the docks, {npc:2486} by the inn, {npc:2498} inside it, MacKinley, {npc:737} and {npc:773} upstairs."] = "V {area:35}: {npc:2494} na molech, {npc:2486} u hostince, {npc:2498} uvnitř, MacKinley, {npc:737} a {npc:773} nahoře.",
	["Pirate ghosts and Zanzil's camps"] = "Pirátští duchové a Zanzilovy tábory",
	["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "Raptoři: Zjolnir, vedle {npc:7953} v {area:367}.",
	["Ride east to the Skullsplitter ruins east of the Venture Co. mine. The headhunters, berserkers and hunters roam the ruins.\n{npc:1059} (45) carries the Broken Armor for {quest:586}: he walks the south-western ruins with two guards and sometimes stands in a small cave there. Pull the guards first.\nCareful: {npc:1060}, an elite troll (level 44), stands in the southern ruins around 47.7,44.3: pull the headhunters and berserkers away from him."] = "Jeď na východ k ruinám Skullsplitter východně od dolu Venture Co. Po ruinách se potulují headhunteři, berserkeři a hunteři.\n{npc:1059} (45) nese Broken Armor pro {quest:586}: chodí po jihozápadních ruinách se dvěma strážemi a občas stojí v malé jeskyni tamtéž. Stráže tahej první.\nPozor: {npc:1060}, elite troll (level 44), stojí v jižních ruinách kolem 47.7,44.3: odtáhni headhuntery a berserkery od něj.",
	["Ride north-east back to the port: {npc:7881}, the {npc:15165} and the Security Chief take what {area:1336} gave you. {area:976} is west of it."] = "Jeď na severovýchod zpátky do přístavu: {npc:7881}, {npc:15165} a Security Chief převezmou, co ti dal {area:1336}. {area:976} je na západ od něj.",
	["Ride north-east to the goblin harbour on the coast."] = "Jeď na severovýchod do goblinního přístavu na pobřeží.",
	["Ride south along the road towards {area:35}; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Jeď po silnici na jih směrem k {area:35}; baziliškové se vyhřívají na skalách východně od ní uprostřed džungle. Jejich střepy padají často.",
	["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns.\nCareful: {npc:222286} (level 43, elite) stands in the camp: pull the raiders and shamans away from her."] = "Tábor taurenů Grimtotem vedle háje sprite darterů; raideři, naturalisté i šamani nosí rohy.\nPozor: V táboře stojí {npc:222286} (level 43, elite): raidery a šamany od ní odtáhni.",
	["The flight lands at {object:3202}. Stranglethorn's harder errands, carried from your first visit, fit you now: the Skullsplitter chief, Zanzil's camps, {area:35}'s pirates, the naga coast and {npc:1514}, before the zeppelin to {zone:1454}. The {object:2076} beside Nimboya has the Skullsplitter chief's quest."] = "Let přistává u {object:3202}. Těžší úkoly ze Stranglethornu, které neseš z první návštěvy, ti teď sedí: náčelník Skullsplitterů, Zanzilovy tábory, piráti z {area:35}, nagové pobřeží a {npc:1514}, než nasedneš na zeppelin do {zone:1454}. {object:2076} vedle Nimboye má quest na náčelníka Skullsplitterů.",
	["The flight lands at {object:3202}: {npc:2519} and {npc:2465}, then the zeppelin tower."] = "Let přistává u {object:3202}: {npc:2519} a {npc:2465}, pak věž zeppelinu.",
	["The middle of {zone:1454}"] = "Střed {zone:1454}",
	["The shadow mages, rogues and assassins camp south-east of {area:976}.\nSouth-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Mágové stínů, rogue a asasíni táboří jihovýchodně od {area:976}.\nJihovýchodně od Gadgetzanu táboří v dunách banditi Wastewander; {npc:7847} stojí ve východním táboře.\nPozor: Wastewander Rogues mají mimo boj zapnutý Sneak, takže se skrytí rogue můžou přidat do boje, který v táboře začneš.\nPozor: Všude s ním chodí dva Wastewander Rogues ve stealthu. V jeho táboře jsou dva mágové stínů a jejich pomocníci tak blízko, že se do boje s ním přidají. Venku u věží s ním můžeš bojovat bez nich.",
	["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps."] = "Sprite darters poletují nad hájem kousek západně od Mojache; skoro každý dropne křídlo. Woodpaw alphas vedou tábory jihozápadně od něj: zabij je do hodiny.\nPozor: Většina Alphas sedí v malých stanových táborech se 2–4 dalšími gnolly, kteří se přidají do boje, a mezi tábory hlídkují další gnollové.",
	["The {area:43}"] = "{area:43}",
	["To {area:976}"] = "Do {area:976}",
	["Upstairs"] = "Nahoře",
	["West into Mistvale: {npc:1449} sits among the gorillas. Any gorilla can drop a fang: hand him ten and stay by him, he calls three waves of gorillas, then {npc:1514}.\nCareful: three waves of gorillas come one after another with little rest between, then {npc:1514}. Start at full health and mana, and stay near Unbagwa. Some classes find it hard alone: a friend makes it easy."] = "Na západ do Mistvale: {npc:1449} sedí mezi gorilami. Tesák může dropnout kterákoli gorila: dej mu jich deset a zůstaň u něj, přivolá tři vlny goril a pak {npc:1514}.\nPozor: tři vlny goril přijdou jedna za druhou s krátkou pauzou, pak {npc:1514}. Začni s plným zdravím i manou a drž se u Unbagwy. Některé třídy to samy zvládají těžko: s kamarádem je to snadné.",
	["West to the coast: the naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them. Then follow the coast south to {area:35}."] = "Na západ k pobřeží: naga průzkumníci se brodí podél břehu a nesou svazky rákosí; {object:759} bublá v kopcích kousek východně od nich. Pak jdi po pobřeží na jih do {area:35}.",
	["the {object:2076}"] = "{object:2076}",
	["{area:1336}: kill these as you meet them"] = "{area:1336}: zabíjej je, jak na ně narazíš",
	["{area:1577}: kill these as you meet them"] = "{area:1577}: zabíjej je, jak na ně narazíš",
	["{area:1937}: kill these as you meet them"] = "{area:1937}: zabíjej je, jak na ně narazíš",
	["{area:2522}: kill these as you meet them"] = "{area:2522}: zabíjej je, jak na ně narazíš",
	["{area:340} flight master"] = "letový mistr {area:340}",
	["{area:35} flight master"] = "letový mistr {area:35}",
	["{area:392} flight master"] = "letový mistr {area:392}",
	["{area:392} for the Felsteed"] = "{area:392} kvůli Felsteedu",
	["{area:75} flight master"] = "letový mistr {area:75}",
	["{area:976} flight master"] = "letový mistr {area:976}",
	["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976} je opevněné goblinské město hned za hranicí {zone:1446}.",
	["{area:985}: kill these as you meet them"] = "{area:985}: zabíjej je, jak na ně narazíš",
	["{npc:2488}, on the top floor"] = "{npc:2488}, v nejvyšším patře",
	["{npc:2498}, inside"] = "{npc:2498}, uvnitř",
