	["{npc:7777} walks around {area:1099}: look inside the circle on the map"] = "{npc:7777} chodí po {area:1099}: hledej uvnitř kruhu na mapě",
	["{npc:7854}, inside"] = "{npc:7854}, uvnitř",
	["{npc:7875}: for {npc:7010} in {zone:1454}"] = "{npc:7875}: pro {npc:7010} v {zone:1454}",
	["{npc:7881}, inside"] = "{npc:7881}, uvnitř",
	["{npc:7882}, inside"] = "{npc:7882}, uvnitř",
	["{npc:7953}, riding trainer"] = "{npc:7953}, trenér jízdy",
	["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: pro {zone:1454}, kolem levelu 45",
	["{npc:8115}: {npc:263190}'s errand from the {zone:2548}, if you carry it"] = "{npc:8115}: úkol od {npc:263190} z {zone:2548}, pokud ho neseš",
	["{npc:8579}: the screechers live in {zone:1444}, on the next {zone:1444} visit"] = "{npc:8579}: screecheři žijí v {zone:1444}, při příští návštěvě {zone:1444}",
	["{quest:2863}: one hour from now"] = "{quest:2863}: za hodinu",
