t.guides["forever/horde/40-50/03-feralas"] = {
	["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "Zpět na východ kolem {area:75}: artefakty Atal'ai leží ve vodě a na březích {quest:1424}.",
	["Back to {npc:14637} on the dock."] = "Zpět k {npc:14637} na molo.",
	["Below ground"] = "Pod zemí",
	["Coming from Stranglethorn, you carry these already. Starting here: {npc:5591} stands inside {area:75}'s great hall and {npc:1443} on its top floor."] = "Ze Stranglethornu je už neseš. Pokud začínáš tady: {npc:5591} stojí ve velké síni {area:75} a {npc:1443} v jejím nejvyšším patře.",
	["Dragon caves"] = "Dračí jeskyně",
	["East through the {area:511}: the Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "Na východ přes {area:511}: zvědové a popelaví ocasové Firemane se toulají po jeho severním okraji s mláďaty a dráčaty Searing; scalebanes hlídají dračí jeskyně dál na jihovýchod. Šňupací tabák, grog a pokladnička Mok'Morokka leží v táborech drakonidů.",
	["Fly to {area:1099}"] = "Leť do {area:1099}",
	["Fly to {area:496}"] = "Leť do {area:496}",
	["Fly to {area:75}"] = "Leť do {area:75}",
	["Follow the road south-east to the small Horde post on the shore. {npc:5592} takes the crocolisk flanks from the last swamp visit."] = "Jdi po silnici na jihovýchod k malému stanovišti Hordy na břehu. {npc:5592} vezme krokodýlí boky z poslední návštěvy bažiny.",
	["Frayfeather hippogryphs"] = "Hipogryfové Frayfeather",
	["From the flight master: the {object:172960}, then the Drag, then the {object:172958}."] = "Od letového mistra: {object:172960}, pak Drag, pak {object:172958}.",
	["Hearth to {area:1099}: your hearthstone is still bound there from the {zone:1444} & {zone:1446} guide."] = "Portni se Hearthstonem do {area:1099}: pořád ho tam máš nastavený z návodu {zone:1444} & {zone:1446}.",
	["Level 45.37"] = "Level 45.37",
	["Murlocs of the Misty Reed"] = "Murloci z Misty Reed",
	["Rage Scar yetis"] = "Yetiové z Rage Scar",
	["Ride back north to Brackenwall."] = "Jeď zpátky na sever do Brackenwallu.",
	["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "Jeď na severozápad do {area:1108}; {npc:14637} čeká na molu.",
	["Ride south-west to the {object:2555}."] = "Jeď na jihozápad k {object:2555}.",
	["Sprite darters and forest walkers"] = "Sprite darteři a forest walkeři",
	["Stays on the main route"] = "Zůstává na hlavní trase",
	["Takes you to level 47"] = "Dovede tě na level 47",
	["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Eggs of Onyxia leží v dračích jeskyních na jihovýchodě {area:511}, hlídají je scalebani; rozbij pět.",
	["The crocolisks wallow in the pools around Galen's old camp, just north of {area:75}, on the way back east; about one in four drops a flank."] = "Krokodýli se válí v jezírkách kolem Galenova starého tábora, kousek severně od {area:75}, cestou zpátky na východ; zhruba každý čtvrtý dropne kýtu.",
	["The same murloc shore again: Inkspewers east of the post, Flesheaters around the western huts, and the Oracles among both."] = "Zase ten murločí břeh: Inkspewers východně od stanoviště, Flesheaters kolem západních chýší a Oracles mezi oběma.",
	["The snappers line the strand south of the post.\nThe Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see, the ones on the ride down from the pool too.\nCareful: a {npc:272377} (level 60) walks the south-east strand: give it a wide berth."] = "Snappers lemují pobřeží jižně od stanoviště.\nMonstrous Crawlers chodí po plážích východního pobřeží, je jich málo a daleko od sebe: zabij každého, kterého uvidíš, i ty cestou dolů od jezírka.\nPozor: Jihovýchodním pobřežím chodí {npc:272377} (level 60): obejdi ho velkým obloukem.",
	["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs.\nCareful: a {npc:272401} (level 60) flies over the forest west of the camp: keep clear of it."] = "Sprite darters poletují nad hájem kousek západně od tábora a nosí {item:9589}; Splintered Logs nosí Wandering Forest Walkers kousek dál na západ.\nPozor: Nad lesem západně od tábora létá {npc:272401} (level 60): drž se od něj dál.",
	["The {object:2555}"] = "{object:2555}",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:1173} needs a group of 3. Skip it if you are alone: the route has you grind the XP back.\n{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "Tohle jsou elite moby: vyplatí se jít ve skupině, poohlédni se po lidech. {quest:1173} potřebuje skupinu 3 hráčů. Pokud jsi sám, přeskoč ho: trasa ti XP vrátí grindem.\n{npc:4500} je elite: doporučuje se skupina. Mlať ho, dokud se nevzdá, pak se ohlas u {npc:4501}.",
	["Three zones, lots of travel"] = "Tři zóny, hodně cestování",
	["To {area:1099}"] = "Do {area:1099}",
	["To {area:75}"] = "Do {area:75}",
	["Underwater"] = "Pod vodou",
	["grind on {npc:4329}"] = "grinduj na {npc:4329}",
	["the {object:2555}"] = "{object:2555}",
	["{area:1099} flight master"] = "letový mistr {area:1099}",
	["{area:1108}: kill these as you meet them"] = "{area:1108}: zabíjej je, jak na ně narazíš",
	["{area:2403}: kill these as you meet them"] = "{area:2403}: zabíjej je, jak na ně narazíš",
	["{area:496} flight master"] = "letový mistr {area:496}",
	["{area:510}: kill these as you meet them"] = "{area:510}: zabíjej je, jak na ně narazíš",
	["{npc:1443}, on the top floor"] = "{npc:1443}, v nejvyšším patře",
	["{npc:2934}, on the way back to Zinge"] = "{npc:2934}, po cestě zpátky k Zinge",
	["{npc:4329} walks around {area:510}: look inside the circle on the map"] = "{npc:4329} chodí po {area:510}: hledej uvnitř kruhu na mapě",
	["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon instead."] = "Výzva od {npc:4500} zpátky v Brackenwall potřebuje skupinu tří. Sólo grinduj Firemane scouty tady na severním okraji {area:511} na level 45.37, než pojedeš zpátky na sever, ať se pro to nemusíš vracet dolů. Nebo se skupinou místo toho projdi dungeon {area:978}.",
	["{npc:4500}, {npc:4502} and {npc:4501} (below ground) are in the village; their quests are for the {area:511} on this trip."] = "{npc:4500}, {npc:4502} a {npc:4501} (pod zemí) jsou ve vesnici; jejich questy jsou na {area:511} na téhle výpravě.",
	["{npc:4501}, below ground"] = "{npc:4501}, pod zemí",
	["{npc:4773}, riding trainer"] = "{npc:4773}, trenér jízdy",
	["{npc:5591}, inside"] = "{npc:5591}, uvnitř",
	["{npc:7854}, inside"] = "{npc:7854}, uvnitř",
	["{object:3202} flight master"] = "letový mistr {object:3202}",
	["{quest:7738}, a rare drop"] = "{quest:7738}, vzácný drop",
}
t.guides["forever/horde/40-50/04-tanaris"] = {
	["Back east to Fizzledowser on the west side of {area:976}; {npc:7771} is south from there."] = "Zpět na východ k Fizzledowserovi na západní straně {area:976}; {npc:7771} je odtud na jih.",
	["Back north, just south of {area:976}, use the {item:8524} now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each."] = "Zpět na sever, kousek jižně od {area:976}, použij teď {item:8524}: začne dvouhodinový časovač. Blisterpaw Hyenas, Glasshide Basilisks a Scorpid Hunters sdílejí zdejší duny. Každý může dropnout netestovaný vzorek: použij ho a buď projde jako přijatelný, nebo se ztratí. Zabíjej, dokud nemáš osm od každého.",
	["Below ground"] = "Pod zemí",
	["Below ground: the plans, on the {area:1443}'s upper ledge"] = "Pod zemí: plány, na horní římse {area:1443}",
	["Boat to {area:16727}"] = "Loď do {area:16727}",
	["Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and {spell:686}. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less."] = "Pozor: Shadow Mages (level 42–43) mimo boj vyvolávají Voidwalkera a útočí Immolate a {spell:686}. Thieves tě můžou odzbrojit, Rogues se pohybují ve Sneak a Assassins používají Execute, jakmile máš 20 % zdraví nebo méně.",
	["Dark Iron Lookouts"] = "Dark Iron Lookouts",
	["Dig up the {quest:3161} ornaments around the {area:1938} and north of the {area:983}. Leave the ogres for now: {npc:12046} is 49 and the Brutes 46-48; the {area:983} comes at the end of 40-50/06, at about 52."] = "Vykopej ozdoby {quest:3161} kolem {area:1938} a severně od {area:983}. Zlobry zatím nech: {npc:12046} má 49 a Brutes 46–48; {area:983} přijde na konci 40-50/06, kolem 52.",
	["Fly to {area:976}"] = "Leť do {area:976}",
	["For your {area:978} run, after {area:979}: {npc:7407}, by the water tower, wants his {quest:2768} back; {quest:2864} his scarab shells and Trenton Lighthammer Troll Temper, if you have not taken those yet."] = "Pro tvůj průchod {area:978}, po {area:979}: {npc:7407} u vodárenské věže chce zpátky svůj {quest:2768}; {quest:2864} jeho skarabeí krunýře a Trenton Lighthammer Troll Temper, pokud sis je ještě nevzal.",
	["From {area:16727}, ride into the {zone:1427} by its eastern pass, then west to the dig site. The {object:173265} stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 {item:4306} (the Auction House sells it)."] = "Z {area:16727} jeď do {zone:1427} jeho východním průsmykem, pak na západ k nalezišti. {object:173265} stojí na jeho jižním konci; Dark Iron Geologists kopou kousek severně od něj. Přines 15 {item:4306} (prodává ho aukce).",
	["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Dál na jih leží výbava Junior Surveyor Scrimshanka u ústí úlu Centipaar.\nPozor: Výbavu hlídá jeden brouk. Tunely brázdí spousta brouků, někteří levelu 50, takže boje často přitáhnou další.",
	["Heavy War Golems patrol the Cauldron below {npc:8479} and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it.\nThe Searing Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.\n{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee. The biggest Incendosaurs and Lava Spiders are 49: pull them one at a time."] = "Heavy War Golems hlídkují v Cauldronu pod {npc:8479} a dropují olej; srdce dropují Magma a Blazing Elementals, kteří se mezi nimi vznášejí. Dark Iron Taskmasters a Slavers ženou otroky po stezkách; Slaver může dropnout {item:11818}: nech si ho.\nSearing Lava Spiders se toulají po plošinách a lávových jezírkách na jihozápadě rokle.\n{area:1443} se otevírá na severu Cauldronu. V jeho lávových jezírkách plavou Incendosaurs: vytáhni je k okraji. Tajné plány leží na horní římse jámy.\nPozor: Dark Iron Slavers (level 45–46) po pullnutí volají na pomoc spojence do 15 yd, kouzlí Net až na 15 yd a na blízko používají Rend. Největší Incendosaurs a Lava Spiders mají 49: pullni je po jednom.",
	["His next request needs the {item:10552} from elite cultists: leave it."] = "Jeho další žádost vyžaduje {item:10552} od elite kultistů: nech to být.",
	["Into {zone:1427}"] = "Do {zone:1427}",
	["Ride back north to {area:1446}, just past {npc:8479}."] = "Jeď zpátky na sever do {area:1446}, kousek za {npc:8479}.",
	["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "Jeď na severozápad přes soutěsku; {area:1446} je tábor s lešením na severozápadě.",
	["Ride south from {area:1446} into the Cauldron: the Dark Iron Taskmasters and Slavers drive the slaves on the paths, and the Heavy War Golems patrol the floor below {npc:8479}. Careful: the biggest golems are 49: pull them one at a time."] = "Jeď na jih z {area:1446} do Cauldronu: Dark Iron Taskmasters a Slavers ženou otroky po stezkách a dno pod {npc:8479} hlídkují Heavy War Golems. Pozor: největší golemové mají 49: tahej je po jednom.",
	["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Dark Iron Lookouts stojí na hřebenech kolem strážních věží jižně od Cauldronu; asi jeden z deseti nese {item:18960}.",
	["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Dark Iron Steamsmiths pracují u pecí uprostřed Cauldronu; polovina z nich nese {item:10551}, jeden z deseti {item:18959}. Dýky nosí i Slaves, Slavers a Taskmasters.",
	["The flight lands beside {npc:7876}. Take the town's quests before riding west to {area:979}."] = "Let přistává vedle {npc:7876}. Než pojedeš na západ do {area:979}, vezmi si questy ve městě.",
	["The {area:247}"] = "{area:247}",
	["Use the {item:8524}"] = "Použij {item:8524}",
	["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "Na západ po silnici na jih; {npc:7771} táboří u ruin v {area:1938}. Nasaď si jeho {item:9978}: ukáže zakopané ozdoby, tady i kolem {area:983}.",
	["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "Západně od Gadgetzanu použij {item:8584} vedle napajedla v trollím táboře.",
	["West of the compound the cactus creatures fill the valley; only the Dew Collectors (47-48) carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one.\nCareful: The other thistleshrub mobs in the area are level 48-50 and wander a lot, so you can easily pull extra mobs: take the Dew Collectors at the valley's edge, and leave {quest:2864}'s Gnarled Thistleshrubs and Rootshapers for the {area:1938} ride into Un'Goro at about 51."] = "Západně od areálu vyplňují údolí kaktusoví tvorové; žlázu s rosou nesou jen Dew Collectors (47–48). Většina mobů v {zone:1446} může vzácně dropnout nouzový maják OOX-17/TN: když nějaký uvidíš, nech si ho.\nPozor: ostatní thistleshrub moby v oblasti mají level 48–50 a hodně se toulají, takže snadno pullneš moby navíc: Dew Collectors ber na okraji údolí a Gnarled Thistleshrubs a Rootshapers pro {quest:2864} nech na cestu přes {area:1938} do Un'Goro kolem levelu 51.",
	["West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you. The Sandreavers are 49-50: take the Workers and Tunnelers."] = "Na západě se kolem svých úlů rojí hmyz Centipaar; díly dropuje kterýkoli z nich.\nPozor: Centipaar Swarmers kouzlí {npc:4196} v boji i mimo něj, což přivolá malé addy, které tě přerušují. Sandreavers mají 49–50: ber Workers a Tunnelers.",
	["the {object:173265}"] = "{object:173265}",
	["{area:1099} flight master"] = "letový mistr {area:1099}",
	["{area:246}'s slavers and golems"] = "Otrokáři a golemové v {area:246}",
	["{area:976} and the {zone:1427} at 46-48: the Wastewander camps, {npc:5955}'s escort and {area:1446}."] = "{area:976} a {zone:1427} na levelu 46–48: tábory Wastewander, eskorta {npc:5955} a {area:1446}.",
	["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the troll camp's water hole.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978} je dungeon pro skupinu pěti; jeho questy tady mají level 45 až 47. Brána leží asi 400 yardů severně od napajedla trollího tábora.\nUvnitř: Scarabs dropují krunýře, každý troll Sandfury může dropnout {quest:3042} a {npc:7604} nese {quest:2768}.",
	["{item:11818}, a rare drop"] = "{item:11818}, vzácný drop",
	["{item:8623}, a rare drop"] = "{item:8623}, vzácný drop",
	["{npc:11758}'s {area:983} stays in your log for the {area:1938} at about 52."] = "{area:983} od {npc:11758} zůstane v deníku na {area:1938} zhruba na levelu 52.",
	["{npc:11758}: keep it, the Dunemaul ogres and Gor'marok (49) wait for the {area:1938} at about 52, at the end of 40-50/06"] = "{npc:11758}: nech si ho, ogrové Dunemaul a Gor'marok (49) čekají na {area:1938} zhruba na 52, na konci 40-50/06",
	["{npc:5594}, inside"] = "{npc:5594}, uvnitř",
	["{npc:7876}, beside the wind rider master"] = "{npc:7876}, vedle mistra wind riderů",
	["{npc:8479} stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "{npc:8479} stojí sám jižně od {area:1446}, na okraji Cauldronu. Poslechni si jeho příběh.",
	["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}: {npc:7604}, uvnitř",
	["{quest:2865}: the Scarabs, inside"] = "{quest:2865}: Scarabové, uvnitř",
	["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}: trollové Sandfury, uvnitř",
	["{quest:3161} ornaments"] = "Ozdoby {quest:3161}",
	["{quest:3362}: kill these as you meet them"] = "{quest:3362}: zabíjej je, jak na ně narazíš",
	["{zone:1427}: kill these as you meet them"] = "{zone:1427}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/horde/40-50/05-the-hinterlands"] = {
	["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Zpět na západ do {area:350}; strážci a střelci zůstávají u chaty, zvědové a běžci na svazích jižně od ní.",
	["Careful: Stealthed wolves and griffons roam the {area:1883} area."] = "Pozor: Okolím {area:1883} se toulají vlci a gryfové ve stealthu.",
	["East of the village, the violet flower grows in the hills."] = "Východně od vesnice roste v kopcích fialová květina.",
	["Fly to {area:272}"] = "Leť do {area:272}",
	["Fly to {area:75}"] = "Leť do {area:75}",
	["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Jdi po silnicích na východ přes {zone:1425} k trollí vesnici na východním pobřeží.",
	["Highvale"] = "Highvale",
	["His next request, going on to the {area:355}, is for a group."] = "Jeho další žádost, pokračování do {area:355}, je pro skupinu.",
	["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. The trolls inside are elite: stay with your group and keep to the paths."] = "Lebka Huntsmana Malkhora leží na hromadě pod ruinami Vilebranch, jeho kosti na hromadě u paty {area:354}. Vessels of Tainted Blood stojí na dolních terasách a {npc:14757} je držen nahoře. Trollové uvnitř jsou elite: drž se se skupinou a nesejdi ze stezek.",
	["If you skipped {quest:7816} or the {area:354} group quests, grind here to level 49.02 to stay on the route's plan."] = "Pokud jsi přeskočil {quest:7816} nebo skupinové questy v {area:354}, grinduj tady do levelu 49.02, ať zůstaneš v plánu trasy.",
	["Level 49.02"] = "Level 49.02",
	["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Jeď až na západ do města Wildhammerů {area:348} a polož zprávu ke studni uprostřed. Město je plné stráží Aliance: přijď, polož ji a zmiz.",
	["Ride back north through the canyon to {area:75}."] = "Jeď zpátky na sever kaňonem do {area:75}.",
	["Ride back north to the bloodmages."] = "Jeď zpátky na sever k bloodmagům.",
	["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "Jeď na severovýchod od {area:272} do {zone:1425} a po silnici na východ; {npc:7801} táboří na kopci jižně od elfího {area:350}.",
	["South-west of the lake, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "Jihozápadně od jezera drží soothsayeři Vilebranch {area:355}, trollí chrám jižně od středních kopců. Qiaga a {npc:8636} (elite, 50) stojí na jeho vrcholu: soothsayery ber na spodních schodech.\nNa jihozápadě se po kopcích východně od vesnic Witherbark potulují Silvermane Howlers.",
	["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way.\nCareful: Groups of about three elves ambush the escort, usually twice."] = "Elfové Highvale táboří kolem {area:350}. V jejich táborech spal hlášení, poznámky a záznamy. {npc:7780} je zajatý v chatě: vyveď ho ven a cestou odraz přepadení.\nPozor: Doprovod přepadnou skupinky asi tří elfů, obvykle dvakrát.",
	["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Bedny s {item:8684} leží kolem opuštěného hordího tábora v {area:351}, mezi slizy.",
	["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills.\nEast of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south.\nCareful: Scorpok Stingers (50-51) use {spell:5416}; {npc:8301} adds Knockdown. Pull the Stingers one at a time."] = "Těch pět questů sdílí stejná místa: sesbírej všechno v jednom průchodu. Západně od silnice sdílejí kopce supi {npc:5982}, Starving Snickerfangs, Scorpok Stingers a baziliškové Deatheye.\nVýchodně od silnice se ve svazích rochní kanci Ashmane a Grunters vedle bazilišků Redstone. Vyhni se Helboars levelu 52 dál na jihu.\nPozor: Scorpok Stingers (50–51) používají {spell:5416}; {npc:8301} k tomu přidává Knockdown. Pulluj Stingers po jednom.",
	["The ghostly orc stands by the road where the swamp meets the canyon into the {zone:1419}. Listen to his story."] = "Přízračný ork stojí u silnice, kde bažina přechází v kaňon do {zone:1419}. Vyslechni si jeho příběh.",
	["The secret lies on the {area:307}, above the beach."] = "Tajemství leží na {area:307}, nad pláží.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "Tohle jsou elite moby: vyplatí se jít ve skupině, poohlédni se po lidech. {npc:7977} je elite na levelu 48: většina tříd ji sólo zvládne na levelu 50, ale možná budeš potřebovat pomoc. Pokud jsi sám, přeskoč ji: trasa ti XP vrátí grindem.\n{npc:7977} chodí po pobřeží pod {area:307}, od šipky na jih zhruba k 75,66 a na sever zhruba k 82,52: když u šipky není, jdi po pobřeží.",
	["To {area:75}"] = "Do {area:75}",
	["Underwater"] = "Pod vodou",
	["West of the island, the Vilebranch scalpers hold the temples of {area:1884} and {area:1917}. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and {area:351}. Use the {item:9618} on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for {npc:14738}'s second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use {spell:7367}. When a {npc:2925} falls to 50% health or lower, it calls for help from anything within 25 yd."] = "Západně od ostrova drží skalpaři Vilebranch chrámy {area:1884} a {area:1917}. Slagtreeho nářadí leží u jednoho z chrámů.\nSilvermane Stalkers, Savage Owlbeasts a Razorbeak Skylords sdílí kopce mezi chrámy a {area:351}. Použij {item:9618} na owlbeasty, které zabiješ. Skylordi dropují i Long Elegant Feathers: nech si jich deset pro druhou zprávu od {npc:14738}.\nPozor: Silvermane Stalkers mají level 47–48 a mimo boj zůstávají ve stealthu. Zblízka používají {spell:7367}. Když {npc:2925} klesne na 50 % zdraví nebo níž, zavolá na pomoc cokoli do 25 yd.",
	["grind on {npc:2505}"] = "grinduj na {npc:2505}",
	["{area:1440}: kill these as you meet them"] = "{area:1440}: zabíjej je, jak na ně narazíš",
	["{area:1446} flight master"] = "letový mistr {area:1446}",
	["{area:1917}: kill these as you meet them"] = "{area:1917}: zabíjej je, jak na ně narazíš",
	["{area:307}: kill these as you meet them"] = "{area:307}: zabíjej je, jak na ně narazíš",
	["{area:3317} flight master"] = "letový mistr {area:3317}",
	["{area:348} well"] = "Studna v {area:348}",
	["{area:355}: kill these as you meet them"] = "{area:355}: zabíjej je, jak na ně narazíš",
	["{item:8704}, a rare drop"] = "{item:8704}, vzácný drop",
	["{npc:14731}'s lunch"] = "Oběd pro {npc:14731}",
	["{npc:14731}, inside"] = "{npc:14731}, uvnitř",
	["{npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "{npc:14736} stojí nahoře na střeše hostince, nad {npc:14731}: vyjdi nahoru, šipka nerozezná úrovně.",
	["{npc:14757}, at the top of {area:354}"] = "{npc:14757}, na vrcholu {area:354}",
	["{npc:7801}'s camp"] = "tábor {npc:7801}",
	["{object:2068}, on the beaches"] = "{object:2068}, na plážích",
	["{quest:7849}, {quest:7845} and {quest:7850} are group quests: they send you into {area:354}, whose trolls are elite (46-50). Take them with a group of three or more; skip them if you are alone, the route has you grind the experience back.\n{npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "{quest:7849}, {quest:7845} a {quest:7850} jsou skupinové questy: pošlou tě do {area:354}, kde jsou trollové elite (46–50). Ber je se skupinou tří a víc lidí; pokud jsi sám, přeskoč je, trasa tě nechá zkušenosti dogrindovat.\n{npc:14736} stojí nahoře na střeše hostince, nad {npc:14731}: vyjdi nahoru, šipka patra nerozliší.",
}
t.guides["forever/horde/40-50/06-azshara"] = {
	["\"Sea Wolf\" MacKinley, on the top floor: Stoley's shipment from {zone:1446}"] = "\"Sea Wolf\" MacKinley, v nejvyšším patře: Stoleyho zásilka z {zone:1446}",
	["Back to {area:1099}"] = "Zpět do {area:1099}",
	["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Zpět k {npc:11548} u svatyně; drž se západně od stráží {area:3137}.",
	["Back to {object:3202}"] = "Zpět do {object:3202}",
	["Below ground"] = "Pod zemí",
	["Class trainer"] = "Trenér povolání",
	["Fly to {area:1099}"] = "Leť do {area:1099}",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:1638}"] = "Leť do {area:1638}",
	["Fly to {area:35}"] = "Leť do {area:35}",
	["Fly to {area:976}"] = "Leť do {area:976}",
	["Fly to {object:3202}"] = "Leť do {object:3202}",
	["Fly to {zone:1456}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and Magatha are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "Leť do {zone:1456}; je to po cestě do {area:1099}. Ještě tam nemáš letovou trasu? Leť do {area:378} a jeď na západ přes {zone:1412}. Hamuul a Magatha jsou na {area:1639}; druidi a paladini se trénují tady ({npc:3033}, {npc:246344}).",
	["Follow the road north to {area:1237}, the Horde camp."] = "Jdi po silnici na sever do {area:1237}, tábora Hordy.",
	["Frayfeather Hippogryphs"] = "Hipogryfové Frayfeather",
	["Hippogryph nests"] = "Hnízda hipogryfů",
	["Paladin trainer"] = "Trenér paladinů",
	["Pestlezugg's samples come from {zone:1449}."] = "Pestlezuggovy vzorky jsou z {zone:1449}.",
	["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Jeď po silnici na východ ze Splintertree. {npc:11548} čeká u {area:1235} kousek od silnice, pár kroků západně od {area:3137} Aliance: přijď ze západu a drž se dál od Azshara Sentinels a Jarrodena (elite).",
	["Ride into {zone:1447}"] = "Jeď do {zone:1447}",
	["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "Jeď po silnici na jih k {area:1938}; vedle táboří {npc:7771}. Odtud vede silnice na západ dolů do {zone:1449}, kde začíná další návod.",
	["Sprite Darters"] = "Sprite Darters",
	["The Bloodsail ships"] = "Lodě Bloodsail",
	["The Droffers' shop is a few steps further into the Drag."] = "Obchod Drofferových je o pár kroků dál v Dragu.",
	["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Duchové Highborne straší v ruinách kousek severně od svatyně; satyrové Haldarr táboří o kus dál na sever.",
	["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Vílí dráčci poletují po lese kousek západně od tábora. Použij nádobu na každého, kterého zabiješ.",
	["The flight from {area:75} lands on {area:35}'s upper deck. {npc:7406} has his workshop on the upper ring of the bay."] = "Let z {area:75} přistává na horní palubě {area:35}. {npc:7406} má dílnu na horním okruhu zátoky.",
	["The flight lands at {area:117}; {npc:2497} stands by the {object:2076}."] = "Let přistává v {area:117}; {npc:2497} stojí u {object:2076}.",
	["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "Hnízda hipogryfů jsou na kopcích na jihu, kolem {area:2522}; v každém je vejce pro {object:142071}.",
	["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Hipogryfové hnízdí na kopcích jihozápadně od tábora. Jednoho zabij, pak na jeho tělo použij Muisek Vessel.",
	["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Treanti bloudí po lesních cestách mezi táborem a středem {zone:1444}; je jich jen pár, tak je hledej podél cest.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:818} (level 47 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\nCareful: Two elite caster guards, around level 45, stand with {npc:818} and join the fight together with him."] = "Tohle jsou elite moby: vyplatí se jít ve skupině, poohlédni se po lidech. {npc:818} (elite, level 47) potřebuje skupinu 2 hráčů. Pokud jsi sám, přeskoč ho: trasa ti XP vrátí grindem.\nPozor: u {npc:818} stojí dvě elite stráže-caster kolem levelu 45 a zapojí se do boje spolu s ním.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Tohle jsou elite moby: vyplatí se jít ve skupině, poohlédni se po lidech. {quest:8552} potřebuje skupinu 2 hráčů. Pokud jsi sám, přeskoč ho: trasa ti XP vrátí grindem.",
	["Wandering Forest Walkers"] = "Toulaví Forest Walkers",
	["West from the compound, on the way to Un'Goro's ramp: {quest:3362}'s Gnarled Thistleshrubs and Rootshapers (48-50) are {npc:7876}'s, carried from your first {zone:1446} visit. They wander a lot: pull them one at a time. {npc:7876} takes them on the next guide's {area:976} stop, with {npc:11758}'s."] = "Na západ od areálu, cestou k rampě do Un'Goro: Gnarled Thistleshrubs a Rootshapers (48–50) pro {quest:3362} patří {npc:7876} a neseš je z první návštěvy {zone:1446}. Hodně se toulají: pullni je po jednom. {npc:7876} si je vezme na zastávce v {area:976} v dalším návodu, spolu s těmi pro {npc:11758}.",
	["{area:1099} flight master"] = "letový mistr {area:1099}",
	["{area:1108}: kill these as you meet them"] = "{area:1108}: zabíjej je, jak na ně narazíš",
	["{area:1236}: kill these as you meet them"] = "{area:1236}: zabíjej je, jak na ně narazíš",
	["{area:1237} flight master"] = "letový mistr {area:1237}",
	["{area:35} flight master"] = "letový mistr {area:35}",
	["{area:75} flight master"] = "letový mistr {area:75}",
	["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} v {zone:1456}; {zone:1454} nemá trenéra paladinů",
	["{npc:2491}, in the inn"] = "{npc:2491}, v hostinci",
	["{npc:5594}, inside"] = "{npc:5594}, uvnitř",
	["{npc:6117} walks around {area:1235}: look inside the circle on the map"] = "{npc:6117} chodí po {area:1235}: hledej uvnitř kruhu na mapě",
	["{npc:7406}, inside"] = "{npc:7406}, uvnitř",
	["{npc:7876}, beside the wind rider master"] = "{npc:7876}, vedle mistra wind riderů",
	["{quest:3761} is gathered in the next guide."] = "{quest:3761} se sbírá v dalším návodu.",
	["{quest:4494} needs level 50: {npc:7010}, in the Drag, gives it from then on. Under 50, the {zone:1447} guide at 55 offers it again."] = "{quest:4494} vyžaduje level 50: {npc:7010} v Dragu ho od té doby dává. Pod levelem 50 ho znovu nabídne návod pro {zone:1447} na levelu 55.",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
	["{zone:1456} flight master"] = "letový mistr {zone:1456}",
}
t.guides["forever/horde/50-60/01-un-goro-crater"] = {
	["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "Pár kroků zpět na západ na Felstone Farm, první farmu podél cesty; {npc:10778} čeká v domě.",
	["Back north-east to {area:251}."] = "Zpět na severovýchod do {area:251}.",
	["Back to {area:976}"] = "Zpět do {area:976}",
	["Below ground"] = "Pod zemí",
	["Boat to {area:16727}"] = "Loď do {area:16727}",
	["Bridge into {area:254}"] = "Most do {area:254}",
	["Careful: Gorishi Workers may call for help within 25 yd when below 45% health; silithids cast {spell:8137} and Tunnelers and the Hive Guard use {spell:14120}."] = "Pozor: Gorishi Workers můžou pod 45 % zdraví volat o pomoc do 25 yd; silithidi sesílají {spell:8137} a Tunnelers a Hive Guard používají {spell:14120}.",
	["Careful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd. The Hive Guards (54) and the Queen stand inside the hive: work the Workers and Wasps outside it."] = "Pozor: Gorishi Workers pod 45 % zdraví mají 50% šanci zavolat o pomoc spojence do 25 yd. Hive Guards (54) a Queen stojí uvnitř úlu: dělej Workers a Wasps venku.",
	["Careful: There are many ravasaurs roaming the area, so you can easily pull several at the same time."] = "Pozor: V okolí se toulá hodně ravasaurů, takže snadno natáhneš víc naráz.",
	["Cross the south of the crater to the pylon on the western cliffs."] = "Přejdi jih kráteru k pylonu na západních útesech.",
	["Eastern Pylon"] = "Východní pylon",
	["Fly to {area:1497}"] = "Leť do {area:1497}",
	["Fly to {area:1637} and train before the boat to {area:16727}: the {zone:1458} stop later in this guide has no Hunter or Shaman trainer."] = "Leť do {area:1637} a vytrénuj se před lodí do {area:16727}: zastávka {zone:1458} později v tomto návodu nemá trenéra Huntera ani Shamana.",
	["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Jdi podél útesů na jih k {quest:3821}, kopci ogrů Firegut. Ostatky {npc:9136} leží na jeho úpatí.",
	["For your {area:1584} run, next, on the way through {area:254}: the {object:164867} poster in {area:340} wants the Anvilrage dwarves inside thinned out."] = "Pro tvůj průchod {area:1584}, jako další, cestou přes {area:254}: plakát {object:164867} v {area:340} chce uvnitř prořídit trpaslíky Anvilrage.",
	["From here on pick up every {npc:271301} (blue, green, red, yellow) and every {quest:3761} pile you pass: 20 for Hamuul, and 5 more for Pestlezugg if you carry {quest:4496}."] = "Od teď sbírej každý {npc:271301} (modrý, zelený, červený, žlutý) a každou hromádku {quest:3761}, kolem které půjdeš: 20 pro Hamuula a 5 navíc pro Pestlezugga, pokud neseš {quest:4496}.",
	["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner. Careful: the Scarlets around the tents reach 54 and the Invokers cast: come in from the side nearest the command tent and leave the others be."] = "Od {area:152} jdi po silnici na východ do {zone:1422}. Stany Scarlet Crusade stojí kousek za Felstone Farm, mezi {area:199} a {area:200}. Zapal velitelský stan pomocí {object:176092} a vztyč prapor Scourge. Pozor: Scarleti kolem stanů mají až 54 a Invokers sesílají kouzla: přijď ze strany nejblíž velitelskému stanu a ostatní nech být.",
	["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "Od {area:1938} jeď na západ k dlouhé rampě, která se vine dolů do {zone:1449}, pak jdi podél severní stěny kráteru do {area:541}, tábora v jeskyních v útesu. Všichni tady jsou neutrální.",
	["Gorillas"] = "Gorily",
	["Into the {zone:1427}"] = "Do {zone:1427}",
	["Into {zone:1449}"] = "Do {zone:1449}",
	["Leave {zone:2548} on foot to the north-west, north of {area:16685}, into the {zone:1418}."] = "Opusť {zone:2548} pěšky na severozápad, severně od {area:16685}, do {zone:1418}.",
	["Level 51"] = "Level 51",
	["Out of the refuge"] = "Ven z útočiště",
	["Power Crystals and soil"] = "Power Crystals a hlína",
	["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Sjeď po východní straně kráteru k pylonu na východních útesech.",
	["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Jeď na sever po východní straně. Džungli plní Bloodpetal Lashers a Threshers.",
	["Ride north back to {area:541}: {npc:9117} below ground, {npc:9997} beside the flight master."] = "Jeď na sever zpátky do {area:541}: {npc:9117} pod zemí, {npc:9997} vedle letového mistra.",
	["Ride south-west to {area:537}, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot.\nSouth of the hot springs, Dinosaur Bones lie on the ground among the Stegodons and drop from the Diemetradons nearby, which also carry the scales {npc:9998} wants. Careful: the Stegodons are elites (52-53): pick the bones up around them, don't pull them; the Elder Diemetradons are 53-55, take the smaller ones. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon.\nRide south-west along the western cliffs. Bloodpetal Trappers grow in the jungle there. Careful: the biggest Trappers are 53: pull them one at a time."] = "Jeď na jihozápad k {area:537}, sopce uprostřed kráteru. Kolem jejího úpatí rostou Bloodpetal Flayers.\nJižně od horkých pramenů leží na zemi mezi Stegodony Dinosaur Bones a dropují je i Diemetradoni poblíž, kteří nosí i šupiny, které chce {npc:9998}. Pozor: Stegodoni jsou elite (52–53): kosti kolem nich sbírej, ale nestahuj je; Elder Diemetradons mají 53–55, ber ty menší. Na jihozápadě loví ve smečkách Ravasaurs: jejich drápy jsou pro {npc:8659} a občas některý nese Mangled Journal (vzácný drop: jeho quest ber, jen když ho dostaneš). Vyhni se Gruffovi, Stegodonovi na levelu 57.\nJeď na jihozápad podél západních útesů. V džungli tam rostou Bloodpetal Trappers. Pozor: největší Trappeři mají 53: tahej je po jednom.",
	["Stegodons and ravasaurs"] = "Stegodoni a ravasauři",
	["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5405}: Scourgestones only drop while you wear it."] = "Vezmi si {object:176092} z bedny vedle Derringtona pro {quest:5096}, kterou splníš cestou zpátky. Nasaď si {quest:5405}: Scourgestones padají jen, když ho máš na sobě.",
	["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "Vezmi průsmyk ze západní strany {area:340} do {zone:1427}, pak jeď na jih přes soutěsku k dlouhému mostu do {area:254}. Uvnitř jdi po řetězových lávkách dolů a odejdi jižním východem; vyhýbej se cestám k portálům dungeonů.",
	["The Anvilrage dwarves of your {area:1584} run: {npc:9077}, in {area:340}."] = "Trpaslíci Anvilrage z tvého průchodu {area:1584}: {npc:9077} v {area:340}.",
	["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "Krystalové shluky stojí po celém kráteru, hodně kolem {area:537}. Vezmi od každé barvy pár navíc na pylony.",
	["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "Bedna expedice stojí v opuštěném táboře ve východní džungli.",
	["The expedition's lost equipment lies in the south-west jungle."] = "Ztracené vybavení expedice leží v jihozápadní džungli.",
	["The gorillas live on the north-east plateau: {npc:9619} wants two pelts of each kind, and the Thunderers (52-53) are the biggest. Stay out of the deepest cave: {npc:9622} lives there."] = "Gorily žijí na severovýchodní plošině: {npc:9619} chce od každého druhu dvě kůže a největší jsou Thunderers (52–53). Do nejhlubší jeskyně nelez: žije tam {npc:9622}.",
	["The hearth lands in {area:976}: {npc:11758} takes the {area:983} and Tran'rek Thistleshrub Valley, both done on the way into the crater."] = "Hearthstone tě přenese do {area:976}: {npc:11758} přijímá {area:983} a Tran'rek Thistleshrub Valley, obojí splníš cestou do kráteru.",
	["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "Hora tě vypustí vedle {area:252}, plného orků levelu 55–57. Jdi po silnici na východ podél severních útesů do hordího tábora v {area:251}.",
	["The pylon stands on the slope east of the refuge."] = "Pylon stojí na svahu východně od útočiště.",
	["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Vor leží na břehu jihovýchodního jezera; malý batoh je ve vodě vedle něj.",
	["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}. Careful: the Lurkers reach 54 and the Tar Lords stand among them: take the Tar Beasts (50-51) and Creepers (51-52)."] = "Dehtové jámy leží kousek jižně od útočiště. {item:11834} dropují Tar Beasts, Lurkers a Creepers. Pozor: Lurkers mají až 54 a mezi nimi stojí Tar Lords: ber Tar Beasts (50–51) a Creepers (51–52).",
	["To {area:976}"] = "Do {area:976}",
	["Top up here to level 51 before the crater's loop: its {npc:9166} and Bloodpetal Flayers are up to level 52. The Bloodpetal Threshers (49-50) on the slopes south-east of the refuge are under your level, and {npc:9118} wants five of them. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Tady se dotáhni na level 51, než začneš okruh kráterem: jeho {npc:9166} a Bloodpetal Flayers mají až level 52. Bloodpetal Threshers (49–50) na svazích jihovýchodně od útočiště jsou pod tvým levelem a {npc:9118} jich chce pět. Nebo se skupinou jdi radši dungeon {area:1417} nebo dungeon {area:2100}.",
	["Underwater"] = "Pod vodou",
	["Upstairs"] = "Nahoře",
	["Use the Mangled Journal to start it"] = "Quest spusť použitím Mangled Journal",
	["Use the scale to start {quest:87494}, for {npc:9619}"] = "Použij šupinu a spusť {quest:87494} pro {npc:9619}",
	["Western Pylon"] = "Západní pylon",
	["grind on {npc:6511}"] = "grinduj na {npc:6511}",
	["{area:1584} is a dungeon for a group of five from about level 48, the biggest in the mountain: its Anvilrage dwarves are this quest's, and you need not go further in than they are. Its portal is deep inside the mountain, down the chain walkways from the bridge.\nInside: the Anvilrage Guardsmen, Wardens and Footmen. Then back out of the portal and on through the mountain's southern exit to the {zone:1428}."] = "{area:1584} je dungeon pro skupinu pěti zhruba od levelu 48, největší v hoře: jeho trpaslíci Anvilrage patří k tomuhle questu a dál než k nim jít nemusíš. Portál je hluboko v hoře, dolů po řetězových lávkách od mostu.\nUvnitř: Anvilrage Guardsmen, Wardens a Footmen. Pak zpátky z portálu a dál jižním východem z hory do {zone:1428}.",
	["{area:250}: kill these as you meet them"] = "{area:250}: zabíjej je, jak na ně narazíš",
	["{area:340} flight master"] = "letový mistr {area:340}",
	["{area:340} is built into the cliffs on the {zone:1418}' west edge."] = "{area:340} je vestavěný do útesů na západním okraji {zone:1418}.",
	["{area:538}: kill these as you meet them"] = "{area:538}: zabíjej je, jak na ně narazíš",
	["{item:11116}, a rare drop"] = "{item:11116}, vzácný drop",
	["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, vedle mistra netopýrů",
	["{npc:5204}, near Cuely in the Apothecarium"] = "{npc:5204}, u Cuelyho v Apothecariu",
	["{npc:5594}, inside"] = "{npc:5594}, uvnitř",
	["{npc:7825} stands in the {object:36082}."] = "{npc:7825} stojí v {object:36082}.",
	["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, Apothecarium: lahvičky se plní později ve {zone:1447}",
	["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, vzadu v jeskyni; pod zemí",
	["{npc:9117}, below ground"] = "{npc:9117}, pod zemí",
	["{npc:9166} (50-52) fly over the east of the crater, from the slopes below the refuge southward; their webbed scales are for {npc:9998}, and {npc:9997}'s sign wants ten of them. Leave the {npc:9167} over the west for the pylon loop."] = "{npc:9166} (50–52) létají nad východem kráteru, od svahů pod útočištěm na jih; jejich blanité šupiny jsou pro {npc:9998} a cedule {npc:9997} jich chce deset. {npc:9167} nad západem nech na okruh kolem pylonů.",
	["{npc:9167}: kill these as you meet them"] = "{npc:9167}: zabíjej je, jak na ně narazíš",
	["{npc:9618}, just outside"] = "{npc:9618}, kousek venku",
	["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} táboří v jihovýchodním rohu kráteru.",
	["{npc:9619}'s camp is in the south-east corner, a short ride from the {area:1942}."] = "Tábor {npc:9619} je v jihovýchodním rohu, kousek jízdy od {area:1942}.",
	["{npc:9619}: {quest:4289}, the gorillas of the north-east plateau on the pylon loop"] = "{npc:9619}: {quest:4289}, gorily na severovýchodní plošině na okruhu kolem pylonů",
	["{npc:9619}: {quest:87492}, a short ride west of his camp"] = "{npc:9619}: {quest:87492}, kousek jízdy západně od jeho tábora",
	["{npc:9619}: {quest:87494}, if the scale dropped"] = "{npc:9619}: {quest:87494}, pokud šupina padla",
	["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623} pak chce {item:10561}, předmět z {skill:202}. Přeskoč to, pokud ho nemáš.",
	["{npc:9623}, the robot on the plateau; below ground"] = "{npc:9623}, robot na plošině; pod zemí",
	["{npc:9706}, by the dock: for {quest:4324} at {area:251}, later in this guide"] = "{npc:9706}, u mola: pro {quest:4324} v {area:251}, později v tomhle návodu",
	["{npc:9997}, beside the flight master"] = "{npc:9997}, vedle letového mistra",
	["{npc:9998}, at the entrance"] = "{npc:9998}, u vchodu",
	["{npc:9998}, at the refuge entrance"] = "{npc:9998}, u vchodu do útočiště",
	["{object:175894}, beside the house; inside"] = "{object:175894}, vedle domu; uvnitř",
	["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} chodí po jeskyních a důlních tunelech {quest:3821}; když není doma, čisti ogry kolem vchodů, dokud se nevrátí.",
	["{quest:4081}: the Anvilrage dwarves, inside"] = "{quest:4081}: trpaslíci Anvilrage, uvnitř",
	["{zone:1449}: kill these as you meet them"] = "{zone:1449}: zabíjej je, jak na ně narazíš",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
}
t.guides["forever/horde/50-60/02-felwood"] = {
	["Back north to {area:1763}. Fill Greta's canteen at the corrupted moonwell in the middle of the southern camp."] = "Zpět na sever do {area:1763}. Naplň Gretinu čutoru u zkažené moonwell uprostřed jižního tábora.",
	["Below ground"] = "Pod zemí",
	["Careful: Den Watchers are level 53-54 and the Deadwood Avengers 54-55; they call nearby allies within 25 yd once below 50% health and run off for help below 15%.\nKeep killing them until one drops a {quest:8470}, about one kill in thirty, then right-click it: {npc:11558} in {area:1769} takes it once the Timbermaw are Neutral to you, now if they already are, or when the last guide passes the cave again at 59."] = "Pozor: Den Watchers mají level 53–54 a Deadwood Avengers 54–55; pod 50 % zdraví volají spojence do 25 yd a pod 15 % utíkají pro pomoc.\nZabíjej je, dokud jeden nedropne {quest:8470}, zhruba jedno zabití z třiceti, pak na něj klikni pravým: {npc:11558} v {area:1769} ho vezme, jakmile jsou k tobě Timbermaw Neutral, teď, pokud už jsou, nebo až poslední návod na 59 znovu mine jeskyni.",
	["Class trainer"] = "Trenér povolání",
	["Derrington's watchtowers and Vandis' cauldron are done on a later visit: keep them."] = "Derringtonovy strážní věže a Vandisův kotel se dělají při pozdější návštěvě: nech si je.",
	["Diseased Wolves"] = "Diseased Wolves",
	["Druid trainer"] = "Trenér druidů",
	["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "Východně od Bloodvenom Post, údolí plné kráterů, kde se toulají Entropic Beasts a Horrors. Zabij od každého dva, pak dojdi ke každému ze tří kráterů s fel vodou.",
	["Fly to {area:431}"] = "Leť do {area:431}",
	["Follow the road north-east to {area:1767}. The Warpwood Moss Flayers and Shredders on the east side of the woods each carry a {item:11503}; Angerclaw Grizzlies and Felpaw Ravagers roam the same woods for Talo, and their organs are {npc:10920}'s.\n{area:1762}'s Deadwood Den Watchers (53-54) and Avengers (54-55) are next: below level 54, keep hunting the grizzlies and ravagers (51-52) here until 54. The hand-ins at {area:1769}, the {area:2479} and {area:1997} that follow take you most of the way to 55. Or, with a group, run the {area:1417} dungeon or the {area:1584} dungeon instead."] = "Jdi po silnici na severovýchod do {area:1767}. Warpwood Moss Flayers a Shredders na východní straně lesa nosí každý {item:11503}; ve stejných lesích se pro Tala toulají Angerclaw Grizzlies a Felpaw Ravagers a jejich orgány jsou pro {npc:10920}.\nDalší na řadě jsou Deadwood Den Watchers (53–54) a Avengers (54–55) z {area:1762}: pod levelem 54 tu dál lov grizzly a ravagery (51–52), dokud nebudeš mít 54. Odevzdávky v {area:1769}, {area:2479} a {area:1997}, které následují, tě dostanou skoro až na 55. Nebo se skupinou místo toho projdi dungeon {area:1417} nebo dungeon {area:1584}.",
	["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "Jdi po silnici na severozápad. Jih {area:1763} kolem jeho zkažené měsíční studny drží kultisté, adepti, strážci Shadow Council a jejich psi.",
	["He camps by the {area:202}, south-east of {area:200}."] = "Táboří u {area:202}, jihovýchodně od {area:200}.",
	["His next hunt, the Diseased Grizzlies (55-56), waits for the Plaguelands visit at about 58."] = "Jeho další lov, Diseased Grizzlies (55–56), počká na návštěvu Plaguelands kolem levelu 58.",
	["Level 55"] = "Level 55",
	["Paladin trainer"] = "Trenér paladinů",
	["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "Jeď zpátky na jih kolem {area:1763} k zkažené moonwell Jadefire satyrů a naplň tam lahvičku {npc:9996}.",
	["Ride north up the road again."] = "Jeď znovu po silnici na sever.",
	["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Jeď na jihozápad kolem Felstone Farm a po silnici na západ zpátky k {area:152}.",
	["Ride the road south through {zone:1448} to the Sanctuary."] = "Jeď po silnici na jih přes {zone:1448} do Sanctuary.",
	["Southern crater"] = "Jižní kráter",
	["Southern {area:1763}"] = "Jižní {area:1763}",
	["Step into the cave: {npc:11558} stands just inside."] = "Vstup do jeskyně: {npc:11558} stojí hned u vchodu.",
	["Take the kitten to the same moonwell and release it there with {item:12565}; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "Vezmi koťátko ke stejné měsíční studně a vypusť ho tam pomocí {item:12565}; jakmile se promění v {npc:10042}, přiveď ho zpátky k {npc:9996} a klikni na něj, abys ho předal.",
	["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "Vesnice furbolgů Deadwood kousek západně od tunelu. Stojí mezi nimi {npc:9462} (56). {npc:11557}, přátelský furbolg, sedí na severním konci vesnice.",
	["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "Vesnice furbolgů Deadwood leží kousek jižně od Sanctuary. Každé zabití Deadwood ti zvedne i reputaci u {area:1769}; pera z čelenek si nech.",
	["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "Deník leží ve statku, skříň stojí uvnitř a kadibudka je za ním. Klíč od kadibudky nosí {npc:10816}; {npc:10836} vyleze, když kadibudku otevřeš, a nosí klíč od skříně.",
	["The druids' camp is just past the border."] = "Tábor druidů je hned za hranicí.",
	["The middle of {zone:1454}"] = "Střed {zone:1454}",
	["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "Silnice končí u {npc:15395}, před tunelem {area:1769} na dalekém severovýchodě.",
	["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east. Careful: the biggest are 54: pull them one at a time."] = "Vlci se potulují po polích mezi Andorhalem, {area:200} a {area:202}. Dodělej je cestou zpátky na východ. Pozor: Největší mají 54: pulluj je po jednom.",
	["Western crater"] = "Západní kráter",
	["grind on {npc:7157}"] = "grinduj na {npc:7157}",
	["grind on {npc:8957}"] = "grinduj na {npc:8957}",
	["{area:200} farmhouse"] = "Statek {area:200}",
	["{item:12565}, at the Jadefire moonwell"] = "{item:12565} u měsíční studny Jadefire",
	["{npc:10920}, beside {npc:10921}: {quest:86577}, the organs of {zone:1448}'s bears and wolves"] = "{npc:10920}, vedle {npc:10921}: {quest:86577}, orgány medvědů a vlků z {zone:1448}",
	["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, na jižním okraji tábora",
	["{npc:11557}: keep 30 {quest:6031} for him; he trades only at Neutral with the Timbermaw; below ground"] = "{npc:11557}: nech si pro něj 30 {quest:6031}; obchoduje až od Neutral u Timbermaw; pod zemí",
	["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558}: Timbermaw s tebou mluví až od Neutral; chodí tady kolem: hledej uvnitř kruhu na mapě",
	["{npc:246152} in {zone:1420}; {zone:1454} has no paladin trainer"] = "{npc:246152} v {zone:1420}; {zone:1454} nemá trenéra paladinů",
	["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} v {zone:1412}; v {zone:1454} druidský trenér není",
	["{npc:8659} takes the ravasaur claws from Un'Goro; he stands in the {object:172960}, a short walk from the middle of the city."] = "{npc:8659} bere ravasauří drápy z Un'Gora; stojí v {object:172960}, kousek pěšky od středu města.",
	["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
	["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, na západní straně Sanctuary",
	["{npc:9529}, on the west side of the camp"] = "{npc:9529}, na západní straně tábora",
	["{npc:9996}'s kitten"] = "Kotě od {npc:9996}",
	["{npc:9996}: the {quest:86612}"] = "{npc:9996}: {quest:86612}",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
}
t.guides["forever/horde/50-60/03-winterspring"] = {
	["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "Zpět na jih k {npc:7775}. Elixír si nech a zatím ho nepij: zabije tě, a právě tak později potkáš Gaeriyana u {area:976}.",
	["Both {item:14047} donations are handed in later in the route: save sixty {item:14047} for each if you want them."] = "Oba dary {item:14047} se na trase odevzdávají později: pokud je chceš, nech si na každý šedesát {item:14047}.",
	["Chillwind chimaeras"] = "Chiméry Chillwind",
	["Fly to {area:1099}"] = "Leť do {area:1099}",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:1638}"] = "Leť do {area:1638}",
	["Gregor's quests lead to other zones: keep them."] = "Gregorovy questy vedou do jiných zón: nech si je.",
	["Ice Thistle yetis"] = "Yetiové Ice Thistle",
	["In the {object:172958}."] = "V {object:172958}.",
	["In the {object:172961}. Each donation takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "V {object:172961}. Každý dar ti vezme z batohu šedesát Wool, Silk nebo Mageweave: odevzdej, co neseš, zbytek přeskoč.",
	["Into {zone:1452}"] = "Do {zone:1452}",
	["Linken's letter"] = "Linkenův dopis",
	["Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every {item:14047} you loot for Meilosh.\nCareful: the Den Watchers reach 56: pull one at a time and keep clear of the camps' totems."] = "Pathfindeři, Den Watcheři a Totemici sdílejí furbolgí tábory kolem horkých pramenů; mezi nimi se po svazích potulují Ragged Owlbeasts. Totemiky zabíjej první. Každý {item:14047}, který dropne, si schovej pro Meilosha.\nPozor: Den Watcheři mají až level 56: tahej je po jednom a drž se dál od totemů v táborech.",
	["Raging Owlbeasts"] = "Raging Owlbeasts",
	["Raging Owlbeasts roam the hills north of {area:2251}, by the road between {area:2246} and {area:2255}. Careful: the biggest are level 56: pull them one at a time."] = "Raging Owlbeasts se potulují po kopcích severně od {area:2251}, u silnice mezi {area:2246} a {area:2255}. Pozor: největší mají level 56: tahej je po jednom.",
	["Ride south from the tunnel: {npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "Jeď na jih od tunelu: {npc:9298} táboří mezi kouřícími tůněmi {area:2246} na západě údolí.",
	["The chimaeras roam the snowfields south and west of {area:2255}. Stay clear of {area:2245}'s cave: its blue dragonkin are elite."] = "Chiméry se potulují po sněžných pláních jižně a západně od {area:2255}. Vyhni se jeskyni {area:2245}: její modří dragonkin jsou elite.",
	["Umi: keep it, the Pristine Yeti Horns come on the {zone:1423} guide's {area:2255} stop at about 57"] = "Umi: nech si ho, Pristine Yeti Horns přijdou na zastávce v {area:2255} v návodu pro {zone:1423} kolem levelu 57",
	["{area:2246}: kill these as you meet them"] = "{area:2246}: zabíjej je, jak na ně narazíš",
	["{area:2255} flight master"] = "letový mistr {area:2255}",
	["{area:2255} is the goblin town on the east side of the valley, past the owlbeast hills."] = "{area:2255} je goblinní město na východní straně údolí, za kopci owlbeastů.",
	["{area:2408} flight master"] = "letový mistr {area:2408}",
	["{item:11243}, {npc:7775}'s reward"] = "{item:11243}, odměna od {npc:7775}",
	["{item:12771}: about one Winterfall furbolg in ten carries one; keep killing them until it drops"] = "{item:12771}: nese ho zhruba každý desátý furbolg Winterfall; zabíjej je, dokud nepadne",
	["{npc:10431}, inside"] = "{npc:10431}, uvnitř",
	["{npc:10881} and {npc:14728} stand on {area:1641}. Each of Rumstag's donations takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "{npc:10881} a {npc:14728} stojí na {area:1641}. Každý z Rumstagových darů ti vezme šedesát Wool, Silk nebo Mageweave z tašek: odevzdej, co neseš, zbytek vynech.",
	["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} stojí přímo u východu tunelu {area:1769} do {zone:1452}, tam, kde vyjdeš.",
	["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} na {area:1639}; {npc:246344}",
	["{npc:9087} buys {item:11040} grown from your {quest:3761}. {quest:3782} wants ten, and the {item:11020} gives one try every ten minutes: take it only if you already have the grain."] = "{npc:9087} vykupuje {item:11040} vypěstované z tvého {quest:3761}. {quest:3782} chce deset a {item:11020} dává jeden pokus za deset minut: ber ho, jen když už obilí máš.",
	["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123} čeká v {zone:1450}: nech si ho na později.",
	["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909} je od {npc:7775} v {zone:1444}, později v tomhle návodu.",
	["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084} se odevzdává u {object:176091} ve {zone:1448}, při pozdější cestě.",
	["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}, vzácný drop z furbolgů Winterfall",
	["{zone:1456} flight master"] = "letový mistr {zone:1456}",
}
t.guides["forever/horde/50-60/04-azshara"] = {
	["Back north to {npc:8420} with the rune, then south-west along the road."] = "Zpět na sever k {npc:8420} s runou, pak na jihozápad po cestě.",
	["Back north-west to {npc:8420}."] = "Zpět na severozápad k {npc:8420}.",
	["Back to the Sin'dorei Tome: hand in the seals, then use it to call {npc:8578}.\nCareful: Which crystal is linked to Rimtori is random. Each of the other two summons a hostile infernal instead."] = "Zpět k Sin'dorei Tome: odevzdej pečeti a pak ho použij k vyvolání {npc:8578}.\nPozor: Který krystal je spojený s Rimtori, je náhodné. Každý z ostatních dvou místo toho vyvolá nepřátelského infernala.",
	["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "Cleansed Water jde do {area:2479} v {zone:1448}: nech si ji na později.",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["Each of the camp's three officers (53) carries a seal: {npc:247006} in the middle of the camp, {npc:247013} at its eastern end, and {npc:246991}, who walks its western half: take him on the east side of his walk, where the arrow points.\nCareful: the {npc:250023}, a level 55-57 elite, stands at the camp's western edge, close to the far end of Hawkhelm's walk: wait for Hawkhelm to come back east."] = "Každý ze tří důstojníků tábora (53) nese pečeť: {npc:247006} uprostřed tábora, {npc:247013} na jeho východním konci a {npc:246991}, který chodí po jeho západní polovině: ber ho na východní straně jeho trasy, kam ukazuje šipka.\nPozor: {npc:250023}, elita levelu 55–57, stojí na západním okraji tábora, blízko vzdáleného konce Hawkhelmovy trasy: počkej, až se Hawkhelm vrátí na východ.",
	["Fly to {area:1237}"] = "Leť do {area:1237}",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:392}"] = "Leť do {area:392}",
	["Fly to {zone:1454} and train."] = "Leť do {zone:1454} a vytrénuj se.",
	["Fly to {zone:1454}; {npc:4485} is in the {object:172958}, {npc:3326} and {npc:8659} in the {object:172960}."] = "Leť do {zone:1454}; {npc:4485} je v {object:172958}, {npc:3326} a {npc:8659} v {object:172960}.",
	["Into {zone:1411}"] = "Do {zone:1411}",
	["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "Livina dílna je na severním konci přístaviště v {area:392}; {object:149036} stojí uvnitř.",
	["Makrinni Burrowers"] = "Makrinni Burrowers",
	["Paladin trainer"] = "Trenér paladinů",
	["Ride back west to {area:1237}."] = "Jeď zpátky na západ do {area:1237}.",
	["Ride east out of the {zone:1458} along the road; the {area:152} guards the way into the {zone:1422}."] = "Jeď po silnici na východ z {zone:1458}; {area:152} hlídá cestu do {zone:1422}.",
	["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "Jeď na východ k ruinám na pobřeží. Naplň Cuelyho čtyři lahvičky v přílivových tůních podél břehu; mezi nimi hlídkují naga Spitelash.",
	["Ride east to the ruins on the coast. The four tablets lie among the ruins, guarded by Spitelash naga (52-55): pull them one at a time."] = "Jeď na východ k ruinám na pobřeží. Čtyři desky leží mezi ruinami a hlídají je naga Spitelash (52–55): tahej je po jednom.",
	["Ride north up the road to the Crossroads; {npc:256386} stands there. Open each crate she hands you and bring back what is inside. Fly on to {area:1237} from the Crossroads."] = "Jeď po silnici na sever do Crossroads; stojí tam {npc:256386}. Otevři každou bednu, kterou ti dá, a přines zpátky, co v ní je. Z Crossroads leť dál do {area:1237}.",
	["Ride north-east to the goblin's camp on the cliffs above the {area:1227}, just north of the blood elves."] = "Jeď na severovýchod do goblinova tábora na útesech nad {area:1227}, kousek na sever od krvavých elfů.",
	["Ride south to the northern edge of the {area:1221}. The Spitelash Sirens and Myrmidons (50-52) there carry {npc:8420}'s rune; it doesn't drop often, so work your way along the edge until it does."] = "Jeď na jih k severnímu okraji {area:1221}. Spitelash Sirens a Myrmidons (50–52) tam nosí runu pro {npc:8420}; nepadá často, tak postupuj podél okraje, dokud nepadne.",
	["Upstairs"] = "Nahoře",
	["{area:1221}: kill these as you meet them"] = "{area:1221}: zabíjej je, jak na ně narazíš",
	["{area:1237} flight master"] = "letový mistr {area:1237}",
	["{item:246721}, from {npc:246991}"] = "{item:246721}, od {npc:246991}",
	["{item:246722}, from {npc:247013}"] = "{item:246722}, od {npc:247013}",
	["{item:246725}, from {npc:247006}"] = "{item:246725}, od {npc:247006}",
	["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field.\nCareful: One or two undead usually fight alongside him, and more cauldron lords can attack after you use the cauldron."] = "Farma {npc:10778} je první východně od {area:152}. Jabbering Ghouls na farmě nesou druhou polovinu jejího amuletu; {npc:11075} hlídá kotel na poli.\nPozor: Obvykle s ním bojuje jeden nebo dva nemrtví a po použití kotle můžou zaútočit další cauldron lordi.",
	["{npc:11615}: the termites are in {area:2627}, on the next guide"] = "{npc:11615}: termiti jsou v {area:2627}, v dalším návodu",
	["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}, {object:172957}: nech si ho pro {zone:1451}",
	["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} v {zone:1456}; {zone:1454} nemá trenéra paladinů",
	["{npc:3326}, the {object:172960}"] = "{npc:3326}, {object:172960}",
	["{npc:6522} stands in the {object:36073}."] = "{npc:6522} stojí v {object:36073}.",
	["{npc:8390} and {npc:8393} work in the Apothecarium."] = "{npc:8390} a {npc:8393} pracují v Apothecariu.",
	["{npc:8393}, beside him"] = "{npc:8393}, vedle něj",
	["{npc:8403}, nearby"] = "{npc:8403}, kousek odtud",
	["{npc:8576}: {quest:91531}, for {npc:4485} in {zone:1454}"] = "{npc:8576}: {quest:91531}, pro {npc:4485} v {zone:1454}",
	["{npc:8578}'s camp"] = "tábor {npc:8578}",
	["{npc:8587}: the tome goes to {npc:3326} in {zone:1454}"] = "{npc:8587}: kniha jde k {npc:3326} do {zone:1454}",
	["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
	["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050} jde zpátky k {npc:10778} do {zone:1422}: nech si ho.",
	["{quest:91538}: for {npc:8587} in {area:1237}"] = "{quest:91538}: pro {npc:8587} v {area:1237}",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
}
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = {
	["Back to {area:2268}"] = "Zpět do {area:2268}",
	["Below ground"] = "Pod zemí",
	["Both quests lead to {zone:1451}: keep them."] = "Oba questy vedou do {zone:1451}: nech si je.",
	["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Pozor: {npc:10411} je mimo boj neviditelný a jakmile boj začne, vyvolá Rockwing Gargoyles. Existují jen 3 a obnovují se každých 15 min.",
	["Class trainer"] = "Trenér povolání",
	["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "Vypij {item:11243} na hřbitově kousek východně od {area:976}: zabije tě a {npc:9299} uvidíš jen jako duch, ve skalní rozsedlině v kopcích přímo na sever od něj. Promluv s ním tam, pak doběhni k tělu a oživ se: Conspicuous Gravestone, ke kterému tě pošle, stojí na tom hřbitově.",
	["Fly to {area:1638}"] = "Leť do {area:1638}",
	["Fly to {area:1997}"] = "Leť do {area:1997}",
	["Fly to {area:2268}"] = "Leť do {area:2268}",
	["Fly to {area:272}"] = "Leť do {area:272}",
	["Fly to {area:541}"] = "Leť do {area:541}",
	["Fly to {area:976}"] = "Leť do {area:976}",
	["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "Jdi po silnici na východ z {zone:1422}, přes řeku a přes celý {zone:1423}, ke kapli {object:92525} na dalekém východě.",
	["Free Darrowshire Spirits: talk to them"] = "Osvoboď Darrowshire Spirits: promluv si s nimi",
	["Frenzied Plaguehounds share the fields around {area:2272} and {area:2271}, south of {area:2273}; Noxious Plaguebats fly over the fields of the north, and Monstrous Plaguebats around {area:2272} and {area:2271}. Careful: the hounds are 57-58 and the biggest Monstrous Plaguebats 58: pull them one at a time."] = "Frenzied Plaguehounds sdílejí pole kolem {area:2272} a {area:2271}, jižně od {area:2273}; Noxious Plaguebats létají nad poli na severu a Monstrous Plaguebats kolem {area:2272} a {area:2271}. Pozor: psi mají 57–58 a největší Monstrous Plaguebats 58: tahej je po jednom.",
	["From the tunnel's {zone:1452} exit, ride south to {area:2246}."] = "Od výstupu z tunelu ve {zone:1452} jeď na jih do {area:2246}.",
	["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}."] = "Projdi přes {area:1769} a v tunelu se dej odbočkou do {zone:1450}. {npc:11801} je v {area:2361}.",
	["Hearth to {zone:1454}: the Hearthstone is still bound there from the {zone:1447} guide (Mages teleport). Then the flight master."] = "Portni se Hearthstonem do {zone:1454}: pořád ho tam máš nastavený z návodu {zone:1447} (mágové se teleportují). Pak k letovému mistrovi.",
	["Hearth to {zone:1454}: the Hearthstone is still bound there from the {zone:1447} guide (Mages teleport). Train before the flight."] = "Portni se Hearthstonem do {zone:1454}: pořád ho tam máš nastavený z návodu {zone:1447} (mágové se teleportují). Před letem natrénuj.",
	["Hearth to {zone:1454}: the Hearthstone is still bound there from the {zone:1447} guide. Then the flight master."] = "Portni se Hearthstonem do {zone:1454}: pořád ho tam máš nastavený z návodu {zone:1447}. Pak k letovému mistrovi.",
	["Into {zone:1423}"] = "Do {zone:1423}",
	["Level 56"] = "Level 56",
	["Moontouched Owlbeasts"] = "Moontouched Owlbeasts",
	["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "Plaguehound Runts a Plaguebats se potulují po kopcích severně od {area:2260}, mezi nimi lezou Carrion Grubs; postupuj na sever k {area:2627}.",
	["Plaguehounds and their runts roam the shores of the lake south-west of the chapel; Plaguebats and Carrion Grubs share the ground. Careful: the biggest Plaguehounds are 56, pull them one at a time.\nThe shattered sword lies on the ground north-west of the lake."] = "Plaguehoundi i jejich mláďata se potulují po březích jezera jihozápadně od kaple; Plaguebats a Carrion Grubs jsou tam taky. Pozor: největší Plaguehoundi mají level 56, tahej je po jednom.\nRozbitý meč leží na zemi severozápadně od jezera.",
	["Pristine Yeti Horns"] = "Pristine Yeti Horns",
	["Ride back south to {area:272} and fly to {area:2268}."] = "Jeď zpátky na jih do {area:272} a leť do {area:2268}.",
	["Ride east along the road into the {zone:1423}. {npc:1855} lives in a small house by the {area:2619}, just north of the road at the border; his three hunts are on this guide's ground."] = "Jeď po silnici na východ do {zone:1423}. {npc:1855} bydlí v malém domku u {area:2619}, kousek severně od silnice na hranici; jeho tři lovy jsou na území tohoto návodu.",
	["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Careful: they are 57-58: pull them one at a time.\nCareful: Hailspite, level 60 elites, gather in the snowfields south-east of {area:2255}, where a few Moontouched Owlbeasts roam too: stay on the slopes north of town."] = "Jeď na východ do {area:2255} a z něj na sever; Moontouched Owlbeasts se potulují po kopcích na jižních svazích {area:2241}. Pozor: mají level 57–58: tahej je po jednom.\nPozor: Hailspite, elite na levelu 60, se shromažďují na sněžných pláních jihovýchodně od {area:2255}, kde se potuluje i pár Moontouched Owlbeasts: drž se na svazích severně od města.",
	["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "Jeď po silnici na sever od {area:272}. Dům {npc:10927} stojí u silnice v {area:197} a pomník {npc:10936} je na hřbitově za ním.",
	["Ride north up the road. The cauldron stands in {area:1762}, just south-west of {area:1769}; the Deadwood furbolgs there are hostile."] = "Jeď po silnici na sever. Kotel stojí v {area:1762}, kousek jihozápadně od {area:1769}; furbolgové Deadwood tam jsou nepřátelští.",
	["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Jeď na severozápad do Andorhalu. {npc:10667} čeká v rozbořeném hostinci na západní straně města; kostlivci uvnitř mají 54–57, takže se drž okrajů.",
	["Ride south to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "Jeď na jih do {area:2264} na silnici. {item:15447} se do deseti minut zkazí: Scourge ve městě zabíjej rychle a těch sedm kusů hned rozemel {item:15454}.\nPozor: Unseen Servants volají pomoc do 25 yd, jakmile klesnou na 40 % zdraví. Mimo boj se navíc zneviditelní pomocí {spell:10228}. Když zavolají pomoc uvnitř města, může se do boje přidat spousta mobů. Boj na okraji města tohle riziko snižuje.\nKdyž máš v logu {quest:5211} (od {npc:11063} na začátku návodu), Scourge kolem města po sobě nechávají Darrowshire Spirits: promluv s každým a osvoboď ho. Osvoboď je dřív, než začneš s {item:15447}.",
	["Ride south-west to the ruins of {area:2738}. The {object:179565} for {quest:1123} sits inside one of the ruined houses."] = "Jeď na jihozápad k ruinám {area:2738}. {object:179565} pro {quest:1123} je v jednom z rozbořených domů.",
	["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one.\nCareful: a {npc:10996}, a level 58-59 elite, can stand in Andorhal, as at many other spots of the {zone:1422}: give it room."] = "Annals leží mezi Musty Tomes na radnici v Andorhalu; otevírej je, dokud nenajdeš ten správný.\nPozor: v Andorhalu, stejně jako na mnoha jiných místech {zone:1422}, může stát {npc:10996}, elite na levelu 58–59: dej mu prostor.",
	["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "Hlava panenky a její dvě poloviny leží v domech kolem {npc:10926}; spoj je v batohu.",
	["The flight lands at {area:541}: {npc:9997} stands beside the flight master, and {npc:8737} by the cave a few steps away. {npc:9997}'s work is in Un'Goro on the next guide's way back north."] = "Let přistává v {area:541}: {npc:9997} stojí vedle letového mistra a {npc:8737} u jeskyně pár kroků opodál. Práce pro {npc:9997} je v Un'Goro, cestou zpátky na sever v dalším návodu.",
	["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "Průsmyk z Un'Goro ústí u {area:3077}, hřbitova na severovýchodě {zone:1451}. {npc:13220} stojí mezi hroby.",
	["The skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "Lebka leží v {area:2622}, mezi Blighted Horrors a Plague Monstrosities.",
	["To {area:197}"] = "Do {area:197}",
	["Top up here to level 56 before the Frenzied Plaguehounds of Northdale (57-58): the Noxious Plaguebats (54-56) over the fields on the way east are at your level, and {npc:11878} wants twenty of them. Or, with a group, run the {area:1583} dungeon (Lower) instead."] = "Tady se dotáhni na level 56, než půjdeš na Frenzied Plaguehounds v Northdale (57–58): Noxious Plaguebats (54–56) nad poli cestou na východ jsou na tvém levelu a {npc:11878} jich chce dvacet. Nebo se skupinou jdi radši dungeon {area:1583} (Lower).",
	["Umi's horns, carried from your last {area:2255} stop: the yeti hills start just south-east of {area:2255}. Only Matriarchs and Patriarchs drop horns, and the Patriarchs reach 58: pull them one at a time."] = "Umiho rohy, které neseš z poslední zastávky v {area:2255}: kopce s yetii začínají kousek jihovýchodně od {area:2255}. Rohy dropují jen Matriarchs a Patriarchs a Patriarchs mají až 58: pullni je po jednom.",
	["Umi's third prank targets goblins in {area:976}, Un'Goro and {area:2255}: keep it for later."] = "Umiho třetí žertík míří na gobliny v {area:976}, Un'Goro a {area:2255}: nech si ho na později.",
	["Underwater"] = "Pod vodou",
	["Upstairs"] = "Nahoře",
	["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "Použij {item:12928} na {npc:7583}, goblinku v {area:976}. {npc:10977} a {npc:10978} se vyděsí později na trase.",
	["grind on {npc:8601}"] = "grinduj na {npc:8601}",
	["{area:2255} flight master"] = "letový mistr {area:2255}",
	["{area:2268} flight master"] = "letový mistr {area:2268}",
	["{area:2277}: kill these as you meet them"] = "{area:2277}: zabíjej je, jak na ně narazíš",
	["{area:2627}: kill these as you meet them"] = "{area:2627}: zabíjej je, jak na ně narazíš",
	["{area:272} flight master"] = "letový mistr {area:272}",
	["{area:976} flight master"] = "letový mistr {area:976}",
	["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "Duch {npc:10926} stojí v ruinách {area:2262} na jihozápadě.",
	["{npc:10927}, upstairs"] = "{npc:10927}, nahoře",
	["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner; {npc:12384} sits inside the hut."] = "Duch {npc:11140} stojí u chýše v {area:2627}, v severozápadním rohu; {npc:12384} sedí uvnitř chýše.",
	["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} chodí po okolí: hledej uvnitř kruhu na mapě",
	["{npc:12384}, inside"] = "{npc:12384}, uvnitř",
	["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}. His {npc:8564} hunt, in the north of the zone, waits for the next guide's Plaguelands trip."] = "Šampion {npc:15193} drží statek {area:2260}, severně od {area:2261}. Jeho lov na {npc:8564}, na severu zóny, počká na plaguelandskou cestu dalšího návodu.",
	["{npc:3033} (Druids) trains on {area:1639}, {npc:246344} (Paladins) in the city too."] = "{npc:3033} (druidi) trénuje na {area:1639}, {npc:246344} (paladinové) je taky ve městě.",
	["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} na {area:1639}; {npc:246344}",
	["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914} jde zpátky k {npc:8737} do Un'Gora: nech si ho.",
	["{quest:3941} goes to {npc:9117} in the cave here, on the next guide's return to {area:541}: keep it."] = "{quest:3941} jde k {npc:9117} do zdejší jeskyně, při návratu do {area:541} v dalším návodu: nech si ho.",
	["{quest:5086} are in {zone:1448}, on a later trip: keep it."] = "{quest:5086} jsou ve {zone:1448}, při pozdější cestě: nech si ho.",
	["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "Předměty pro {quest:5168} leží v pozdějších zónách Plaguelands: nech si ho.",
	["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "Duchové pro {quest:5211} přijdou se zastávkou v {area:2264} později v tomhle návodu: nech si ho.",
	["{quest:5510}: the {area:2627} undead drop them while you wear the {item:12846}"] = "{quest:5510}: nemrtví v {area:2627} je dropují, když máš na sobě {item:12846}",
	["{zone:1423}: kill these as you meet them"] = "{zone:1423}: zabíjej je, jak na ně narazíš",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
	["{zone:1456} flight master"] = "letový mistr {zone:1456}",
}
t.guides["forever/horde/50-60/06-silithus"] = {
	["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "Roztržený svitek leží u vchodu do {area:2261}, krypty jižně od {area:2260}.",
	["Andorhal watchtowers and silos"] = "Strážní věže a sila Andorhalu",
	["Back east past the {area:202} to {area:201}, the farm under the eastern hills: {npc:11078} guards its cauldron. Kill him for the key, then use the cauldron."] = "Zpět na východ kolem {area:202} do {area:201}, farmy pod východními kopci: její kotel hlídá {npc:11078}. Zabij ho kvůli klíči a pak použij kotel.",
	["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Zpět do Southwindu a vyšplhej na věž. Rozvířený úl nahoře vypustí Hive'Ashi Ambushers; jeden nese {item:17346}.",
	["Back to {area:3425}"] = "Zpět do {area:3425}",
	["Below ground"] = "Pod zemí",
	["Class trainer"] = "Trenér povolání",
	["Collect twenty Encrypted Twilight Texts from the cultists here, ten for {npc:15306} and ten for Ortell. Take them from the Twilight Avengers and Geolords; leave the Flamereavers and Stonecallers (59-60)."] = "Sesbírej od zdejších kultistů dvacet Encrypted Twilight Texts, deset pro {npc:15306} a deset pro Ortella. Ber je od Twilight Avengers a Geolords; Flamereavers a Stonecallers (59–60) nech být.",
	["Diseased Grizzlies"] = "Diseased Grizzlies",
	["Dredge Crushers and Pincers"] = "Dredge Crushers a Pincers",
	["Dredge Strikers"] = "Dredge Strikers",
	["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Dredge Strikers, Stonelash Scorpids a Sand Skitterers sdílejí písky kousek severně od Hold.",
	["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "Na východ po cestě, {npc:11077} hlídá kotel u {area:200}.",
	["Escort {npc:9999}"] = "Eskortuj {npc:9999}",
	["Flayers and Rock Stalkers"] = "Flayers a Rock Stalkers",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:976}. Still carrying {quest:2741}? The machine stands in the middle of town."] = "Leť do {area:976}. Pořád neseš {quest:2741}? Stroj stojí uprostřed města.",
	["From the zeppelin tower ride east along the road to the {area:152}, on the way into the {zone:1422}."] = "Od věže zeppelinů jeď na východ po silnici k {area:152}, cestou do {zone:1422}.",
	["Hameya hides among the Mossflayer trolls of {area:2273}, in the north-east corner.\nCareful: The trolls along the path to {area:2273} are level 57-59. They run away at low health and call for help, so they often bring adds with them."] = "Hameya se schovává mezi trolly Mossflayer v {area:2273}, v severovýchodním rohu.\nPozor: Trollové na cestě do {area:2273} mají level 57–59. Při nízkém zdraví utíkají a volají pomoc, takže často přivedou addy.",
	["Hameya's mound"] = "Hameyina mohyla",
	["Hameya's scroll"] = "Hameyin svitek",
	["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Jdi na sever podél západních dun; Dredge Crushers a Stonelash Pincers jsou odsud až zpátky k pevnosti.",
	["Into {zone:1422}"] = "Do {zone:1422}",
	["Into {zone:1423}"] = "Do {zone:1423}",
	["Level 57"] = "Level 57",
	["Level 58"] = "Level 58",
	["Mar'alith's next errand, Into the Maw of Madness, leads into {area:2744} among elites. Skip it."] = "Další úkol od Mar'alith, Into the Maw of Madness, vede do {area:2744} mezi elity. Přeskoč ho.",
	["Mark {npc:10902} with the {item:12815}"] = "Označ {npc:10902} pomocí {item:12815}",
	["Mark {npc:10903} with the {item:12815}"] = "Označ {npc:10903} pomocí {item:12815}",
	["Mark {npc:10904} with the {item:12815}"] = "Označ {npc:10904} pomocí {item:12815}",
	["Mark {npc:10905} with the {item:12815}"] = "Označ {npc:10905} pomocí {item:12815}",
	["Paladin trainer"] = "Trenér paladinů",
	["Pamela and the {area:2261}"] = "Pamela a {area:2261}",
	["Radley and Durgen"] = "Radley a Durgen",
	["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "Jeď na východ k {area:537}, vylez nahoru a u lávového průduchu blízko vrcholu použij {npc:10541}, pak jeď zpátky na západ k {npc:10302}.",
	["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "Jeď na východ k chýši {npc:1855} u {area:2619} a vyslechni ho.",
	["Ride north-east to {area:2276} by {area:2275}: the high elf Rangers, Pathstriders and Woodsmen guard it and the Registry lies inside. Careful: the Pathstriders are 57-58 but the Rangers reach 60: pull one at a time and take the Rangers last."] = "Jeď na severovýchod do {area:2276} u {area:2275}: hlídají ji Rangers, Pathstriders a Woodsmen vznešených elfů a uvnitř leží Registry. Pozor: Pathstrideři mají 57–58, ale Rangeři až 60: tahej po jednom a Rangery nech nakonec.",
	["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Jeď na severovýchod do {area:3077}; {zone:1451} opustíš průsmykem vedle ní.",
	["Ride north-east to {area:3447}."] = "Jeď na severovýchod do {area:3447}.",
	["Ride north-west to {npc:1855}'s hut."] = "Jeď na severozápad k chýši {npc:1855}.",
	["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "Jeď na jih do Andorhalu. {npc:10667} čeká v rozbořeném hostinci na západní straně města. Postav se s {item:12815} do dveří každé ze čtyř věží a označ ji; drž se okrajů města. U sil uprostřed města použij {item:12627} a vyláká ven Temporal Parasites.",
	["Ride south-east from {npc:1855} to the {area:2260} farmhouse."] = "Jeď od {npc:1855} na jihovýchod k statku {area:2260}.",
	["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Jeď na jihovýchod do {area:3447} pod útesy Un'Goro.",
	["Ride south-west to {npc:10667} in Andorhal."] = "Jeď na jihozápad k {npc:10667} v Andorhalu.",
	["Ride to {area:2262} in the south-west; Pamela plays among the houses. {npc:11886} lurks in the {area:2261}, the crypt just west of the town.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "Jeď do {area:2262} na jihozápadě; mezi domy si hraje Pamela. {npc:11886} číhá v {area:2261}, kryptě kousek na západ od města.\nPozor: s Mercutiem přijdou asi čtyři ne-elite moby. Dojdou k hrobu, neobjeví se na místě.",
	["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Stonelash Flayers a Rock Stalkers se potulují po dunách jihozápadně od Kiričina tábora.",
	["The Dredge Crushers (57-58) of the south-east are two over you below 57. First top up to 57 on the Dredge Strikers (55-56) on the sands east of {area:3425}, where Sand Skitterers and Stonelash Scorpids (54-56) roam among them, away from the Silithid Darters of the northern sands. Or, with a group, run the {area:1583} dungeon (Lower) or the {quest:838} dungeon instead."] = "Dredge Crushers (57–58) na jihovýchodě jsou pod 57 o dva levely nad tebou. Nejdřív si doplň na 57 na Dredge Strikers (55–56) na píscích východně od {area:3425}, kde se mezi nimi potulují Sand Skitterers a Stonelash Scorpids (54–56), daleko od Silithid Darters na severních píscích. Nebo místo toho se skupinou projdi dungeon {area:1583} (Lower) nebo dungeon {quest:838}.",
	["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too. Careful: the biggest Rumblers and the Whirling Invaders are 58: pull them one at a time."] = "Zářící úlomky tabulek leží kolem tábora Twilight na dalekém severozápadě; dropují je i tamní Dust Stormers a Desert Rumblers. Pozor: Největší Rumblers a Whirling Invaders mají 58: pulluj je po jednom.",
	["The lake for {quest:5845}"] = "Jezero pro {quest:5845}",
	["The libram lies further north, on the way to {area:190}."] = "Libram leží dál na sever, cestou do {area:190}.",
	["The lockboxes sit in Andorhal's ruined houses around {npc:10667}'s inn. Careful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth."] = "Zamčené truhličky stojí ve zničených domech Andorhalu kolem hostince {npc:10667}. Pozor: Vedle truhliček obvykle stojí ghúlové a kostlivci a zaútočí, když se přiblížíš. Searing ghouls navíc zraňují každého poblíž a ruší stealth.",
	["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "Brašna leží v horách na dalekém jihu, za Bronzebeard's Encampment. Poblíž hlídkuje Deathclasp, elite škorpid: vezmi ji, když je pryč.",
	["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "Štít leží v {area:201}, jižně od chýše {npc:1855}.",
	["The spare texts from the cultists"] = "Texty navíc od kultistů",
	["Through the pass and east along the northern cliffs to {area:541}. {npc:9997} stands beside the flight master."] = "Průsmykem a na východ podél severních útesů do {area:541}. {npc:9997} stojí vedle letového mistra.",
	["Top up here to level 58 before Ortell's Rock Stalkers (57-59) and the south; {npc:15181}'s {quest:8304}, back at {area:3425}, needs level 58 too. The Dredge Crushers (57-58) on the way south-east are the ones {npc:15191} wants: leave the Twilight cultists around them be. Or, with a group, run the {area:1583} dungeon (Lower) or the {quest:838} dungeon instead."] = "Tady se dotáhni na level 58, než půjdeš na Ortellovy Rock Stalkers (57–59) a na jih; {quest:8304} od {npc:15181}, zpátky v {area:3425}, taky vyžaduje level 58. Dredge Crushers (57–58) cestou na jihovýchod jsou ti, které chce {npc:15191}: kultisty Twilight kolem nich nech být. Nebo se skupinou jdi radši dungeon {area:1583} (Lower) nebo dungeon {quest:838}.",
	["Twilight Vanguard"] = "Twilight Vanguard",
	["Underwater"] = "Pod vodou",
	["Upstairs"] = "Nahoře",
	["Use the {item:11833} where the arrow points, inside the Gorishi hive of the {area:540}, to call the {npc:10041} (level 56)."] = "Použij {item:11833} tam, kam ukazuje šipka, uvnitř úlu Gorishi v {area:540}, a přivolej {npc:10041} (level 56).",
	["Use {npc:10980} on {npc:10977}"] = "Použij {npc:10980} na {npc:10977}",
	["West to the {area:152} one last time."] = "Naposledy na západ do {area:152}.",
	["West to the {area:152}."] = "Na západ do {area:152}.",
	["grind on {npc:11740}"] = "grinduj na {npc:11740}",
	["grind on {npc:11741}"] = "grinduj na {npc:11741}",
	["{area:190}'s Scarlets are level 58-60. Ride in to the high point marked on your map, look over the town, and get out.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "Scarleti v {area:190} mají level 58–60. Vjeď na vyvýšené místo označené na mapě, rozhlédni se po městě a zmiz.\nPozor: hlídky u brány odhalí hráče ve stealthu. Další hlídky jsou ve městě a poblíž obchází elite.",
	["{area:976} flight master"] = "letový mistr {area:976}",
	["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "Battle of Darrowshire od {npc:10667} končí proti elitám. Vynech ho.",
	["{npc:10667}, upstairs"] = "{npc:10667}, nahoře",
	["{npc:10739} camps by the {area:202}, beside the cauldron; his bears roam the hills north and east of it, on the way to {area:201}."] = "{npc:10739} táboří u {area:202}, vedle kotle; jeho medvědi se potulují po kopcích severně a východně od něj, cestou do {area:201}.",
	["{npc:11610} hides on the hill north-east of the {area:192}."] = "{npc:11610} se skrývá na kopci severovýchodně od {area:192}.",
	["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} stojí východně od dřevařského tábora; {npc:11611} hlídá cestu severovýchodně od {npc:11610}, směrem k {area:190}.\nPozor: U paty věže stojí stráže a další ji obchází na hlídce. Vyčisti je, než se pustíš do Durgena, ať se nepřidají do boje.",
	["{npc:11741} walks around {area:2738}: look inside the circle on the map"] = "{npc:11741} chodí po {area:2738}: hledej uvnitř kruhu na mapě",
	["{npc:11803} walks the Vanguard camp in the far south-west. Keep every {item:20404} the cultists drop: {npc:15306} and Ortell want ten each later."] = "{npc:11803} chodí po táboře Vanguard na dalekém jihozápadě. Nech si každý {item:20404}, který kultisté dropnou: {npc:15306} a Ortell jich později chtějí po deseti.",
	["{npc:11804} stands in the outpost west of {area:3425}. Keep any Encrypted Twilight Texts that drop here too."] = "{npc:11804} stojí na stanovišti západně od {area:3425}. I tady si nech každé Encrypted Twilight Texts, které padnou.",
	["{npc:15171} and {npc:15170} camp at Bronzebeard's Encampment, just north of the satchel's mountains. Question them: go through each one's whole conversation; there is no need to fight them."] = "{npc:15171} a {npc:15170} táboří v Bronzebeard's Encampment, kousek severně od hor s brašnou. Vyslechni je: projdi s každým celý rozhovor; bojovat s nimi nemusíš.",
	["{npc:15189} and {npc:15190} stand upstairs in their building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} a {npc:15190} stojí nahoře ve své budově: vyjdi nahoru uvnitř, šipka nerozezná patra.",
	["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} stojí nahoře ve své budově: vyjdi nahoru uvnitř, šipka nerozezná patra.",
	["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} stojí nahoře ve své budově: vyjdi nahoru uvnitř, šipka nerozezná patra.",
	["{npc:15200} holds the camp in the west."] = "{npc:15200} drží tábor na západě.",
	["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, na západní straně Holdu",
	["{npc:1852} (61, elite) stands in the middle of Andorhal among Skeletal Warlords (56-57, elite): kill him with your group, then take the shard from {object:177241} there."] = "{npc:1852} (61, elite) stojí uprostřed Andorhalu mezi Skeletal Warlords (56–57, elite): zabij ho se skupinou a pak si tam vezmi úlomek z {object:177241}.",
	["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} v {zone:1456}; {zone:1454} nemá trenéra paladinů",
	["{npc:8565} walks around {area:2276}: look inside the circle on the map"] = "{npc:8565} chodí po {area:2276}: hledej uvnitř kruhu na mapě",
	["{npc:9117} is inside the cave."] = "{npc:9117} je uvnitř jeskyně.",
	["{npc:9117}, below ground"] = "{npc:9117}, pod zemí",
	["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "{npc:9619} teď chce kůži {npc:9622}, zpátky v severovýchodní jeskyni: přeskoč to.",
	["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "Doupě {npc:9684} je kousek jižně od pylonu. Použij tam návnadu od {npc:9619}; {npc:9684} je level 56 a silně bije, tak začni s plným zdravím.",
	["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} sedí na hřebeni, ztracený a vyčerpaný.",
	["{quest:105}'s shard lies at {npc:1852}'s feet, in the middle of Andorhal: he is a level 61 elite with elite Skeletal Warlords about him, a fight for a group."] = "Střep pro {quest:105} leží u nohou {npc:1852} uprostřed Andorhalu: je to elite na levelu 61 a kolem něj elite Skeletal Warlords, boj pro skupinu.",
	["{zone:1451}: kill these as you meet them"] = "{zone:1451}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/horde/50-60/07-felwood"] = {
	["A {item:13140} dropped: the Jaedenar Enforcers, Darkweavers, Warlocks and Legionnaires of Shadow Hold carry one now and then. Use it to start the quest, then free {npc:11018} from her cage in the cave's south end on your way out."] = "Padl {item:13140}: Jaedenar Enforcers, Darkweavers, Warlocks a Legionnaires v Shadow Hold ho občas nesou. Použij ho na začátek questu a cestou ven osvoboď {npc:11018} z klece na jižním konci jeskyně.",
	["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "Zpět do tunelu Timbermaw a vezmi východ do {zone:1452}; {npc:9298} táboří u horkých pramenů hned venku.",
	["Back south to the Sanctuary, a short ride."] = "Zpět na jih do Sanctuary, kousek jízdy.",
	["Below ground"] = "Pod zemí",
	["Class trainer"] = "Trenér povolání",
	["Corrupted Soul Shards from the cultists, {quest:5887}"] = "Corrupted Soul Shards od kultistů, {quest:5887}",
	["Fly to {area:431}"] = "Leť do {area:431}",
	["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "Leť do {area:431} a jeď na severozápad po silnici ze {zone:1440} do {zone:1448}. {area:2479} je tábor druidů hned za hranicí.",
	["From Krakle in Un'Goro"] = "Od Krakla v Un'Goro",
	["Frostfire Winterfall camp"] = "Tábor Frostfire Winterfall",
	["Grind to 60"] = "Grinduj do 60",
	["In the {object:172961}."] = "V {object:172961}.",
	["In {zone:1454}: fly from {area:2255}"] = "V {zone:1454}: leť z {area:2255}",
	["In {zone:1456}: fly from {area:2255}"] = "V {zone:1456}: leť z {area:2255}",
	["Level 59.9"] = "Level 59.9",
	["Ride back west along the road to {area:2246}."] = "Jeď zpátky po silnici na západ do {area:2246}.",
	["Ride east, then south down {area:2249}. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of {area:2256}, at the south end."] = "Jeď na východ a pak na jih dolů {area:2249}. Obři Frostmaul tam jsou elite na levelu 59: drž se uprostřed a nezastavuj. Podivný zdroj je u vstupu do {area:2256} na jižním konci.",
	["Ride north along the road, past {area:1763}, to {area:1997}."] = "Jeď po silnici na sever, kolem {area:1763}, do {area:1997}.",
	["Ride north to {area:2255}."] = "Jeď na sever do {area:2255}.",
	["Ride north up the {zone:1448} road to {area:1767}; the {quest:5086} ooze between the trees, and most of them drop a droplet.\nCareful: Ancient Irontree Walkers, level 59 elites, walk among the {quest:5086}, and {npc:14524} (63, elite) roams the woods: work the Horrors at the north tip of {area:1767}, one at a time."] = "Jeď po silnici v {zone:1448} na sever do {area:1767}; mezi stromy se plazí {quest:5086} a většina z nich dropne kapku.\nPozor: mezi {quest:5086} chodí Ancient Irontree Walkers, elite na levelu 59, a lesem se potuluje {npc:14524} (63, elite): mlať Horrors na severním cípu {area:1767}, po jednom.",
	["Ride north-west to {area:1763}. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended."] = "Jeď na severozápad do {area:1763}. Čtyři žárovišť stojí mezi budovami Shadow Council; na každé použij Cleansed Water.\nPozor: jeskyni plní moby Shadow Council na levelu 53–55, často ve velkých propojených skupinách a mnozí mají stuny. Doporučuje se skupina 2–3 hráčů.",
	["The Deadwood totem from {area:1762}, if {npc:11558} didn't take it then: she waits at the tunnel mouth of {area:1769} and speaks to you from Neutral with the Timbermaw, which the Deadwood furbolgs of {zone:1448} brought you to."] = "Totem Deadwood z {area:1762}, pokud ho tehdy {npc:11558} nepřevzala: čeká u ústí tunelu {area:1769} a mluví s tebou od Neutral u Timbermaw, na které tě dostali furbolgové Deadwood ve {zone:1448}.",
	["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} (59, elite) and Xandivious (62) are in the cave at the back: stay out."] = "Vesnice furbolgů vyplňuje údolí severovýchodně od {area:2255}. Nejdřív zabíjej Shamans; léčí. {npc:10738} (59, elite) a Xandivious (62) jsou v jeskyni vzadu: tam nechoď.",
	["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "Questy tady končí. Rabid Shardtooths slídí po {area:2249} na jihu {zone:1452}, jižně od silnice z {area:2255}.",
	["The runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "Běžci chodí po silnici z {area:1769} k {area:2244} v malých skupinkách; čekej u silnice poblíž {npc:9298} a zabíjej je, jak procházejí. Každý nese bednu.\nPozor: Odevzdání vyvolá tři nebo čtyři Winterfall ze zálohy levelu 56–57, kteří na tebe zaútočí; utečeš jim na mountu, ve stealthu nebo s {spell:5384} a pak se shromáždí u jezera, takže si můžeš vzít další quest.",
	["The {area:2479}"] = "{area:2479}",
	["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "Tunelem Timbermaw do {zone:1450}. {npc:11939} si čte v domě v {area:2361}.",
	["Top up here to level 59.9 before the hand-ins at {zone:1452}: they take you to level 60. The Rabid Shardtooths (59) of {area:2249}, just north of the strange source, give far more experience than the furbolgs by {area:1769}. Or, with a group, run the {area:2057} dungeon or the {area:2279} dungeon instead."] = "Tady se dotáhni na level 59.9, než odevzdáš questy v {zone:1452}: dostanou tě na level 60. Rabid Shardtooths (59) v {area:2249}, kousek severně od podivného zdroje, dávají mnohem víc zkušeností než furbolgové u {area:1769}. Nebo se skupinou jdi radši dungeon {area:2057} nebo dungeon {area:2279}.",
	["grind on {npc:7446}"] = "grinduj na {npc:7446}",
	["{npc:11016}, below ground"] = "{npc:11016}, pod zemí",
	["{npc:11556} takes the beads only once {quest:8464} is handed in: any Winterfall furbolg can carry them, and the camps just south of {npc:11556} are the closest."] = "{npc:11556} vezme korálky až po odevzdání {quest:8464}: může je nést kterýkoli furbolg Winterfall a nejblíž jsou tábory kousek jižně od {npc:11556}.",
	["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} chodí po okolí: hledej uvnitř kruhu na mapě",
	["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "Shards of the Felvine od {npc:11801} vyžaduje {area:2577}. Vynech ho.",
	["{npc:11939} walks around {area:2361}: look inside the circle on the map"] = "{npc:11939} chodí po {area:2361}: hledej uvnitř kruhu na mapě",
	["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "Silver Heart pro {npc:9116} potřebuje {item:11173} ze severního {zone:1448} a cestu zpátky sem. Přeskoč ho.",
	["{npc:9116}, inside"] = "{npc:9116}, uvnitř",
	["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298} tě dál pošle na {npc:10738}, elite v jeho jeskyni. Přeskoč to.",
	["{npc:9861}, {npc:9860} and {npc:9517} wait at the back of {area:1770}, the cave in {area:1763}'s north. Clear the tunnel as you go.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."] = "{npc:9861}, {npc:9860} a {npc:9517} čekají vzadu v {area:1770}, jeskyni na severu {area:1763}. Čisti tunel po cestě.\nPozor: Tři bossové bojují jako skupina. Nejdřív zabij moby kolem, ať nepřitáhneš další nepřátele.",
	["{quest:8464}'s village is north-east of {area:2255}, on this guide's way back from {area:2256}."] = "Vesnice {quest:8464} je severovýchodně od {area:2255}, cestou zpátky z {area:2256} v tomhle návodu.",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
}
t.guides["forever/horde/orc/01-durotar"] = {
	["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Armored Scorpids lezou po pláních západně od {area:362}. Ochoč si jednoho a vrať se k {npc:3171}.",
	["Back east to Sen'jin on the way to the {area:368}."] = "Zpět na východ do Sen'jinu cestou do {area:368}.",
	["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Zpět na severozápad do {area:362}: nejdřív {npc:3139}, pak {npc:3147} ve strážní věži, pak {npc:3142} a {npc:266940} cestou ven na východ k pobřeží.",
	["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Zpět přes most a na jih po břehu řeky v {zone:1411} tam, kde úzká stezka stoupá do hory: svatyni nahoře drží {npc:5900}. Cestou nahoru dávej pozor na okraje a dolů se vrať stejnou stezkou.",
	["Back to the Den"] = "Zpět do Den",
	["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "Zpět do Den: {npc:3143} vezme dráp {quest:804} a {npc:5887} hned venku má teď, když máš level 4, {quest:1516}.",
	["Back to {area:362}."] = "Zpět do {area:362}.",
	["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "Zpět do {area:362}: {npc:3139}, pak {npc:3142}.",
	["Back to {zone:1411}"] = "Zpět do {zone:1411}",
	["Below ground"] = "Pod zemí",
	["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "Kultisté Burning Blade drží jeskyně {quest:827}; {item:4871} dropne kterýkoli z nich. {npc:3204}, warlock levelu 14, stojí hluboko uvnitř a dropne {item:4903}.\nPozor: V {quest:827} bojují vedle kultistů Burning Blade voidwalkeři a {npc:3204} (14) čeká vzadu se svým: kvůli obojkům tahej kultisty po jednom u vchodu. {item:4903} je volitelný: {npc:3204} nech být, pokud nemáš 13 nebo kamaráda.",
	["Careful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "Pozor: Ukorsbane (8) je elitní a chodí mezi pavouky Ridgeshade v táboře jižně od {area:362}: odlákej pavouky od něj.",
	["Class trainer"] = "Trenér povolání",
	["Deathskip to Northern Durotar"] = "Deathskip do severního Durotaru",
	["Deathskip to {area:367}"] = "Deathskip do {area:367}",
	["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Nech se zabít moby na 52.0,21.4 ({npc:3118}): smrt tam tě pošle na tento hřbitov. Uvolni ducha a přijmi oživení od {npc:6491}.",
	["Die to the mobs at 66.9,87.2 ({npc:3206}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Nech se zabít moby na 66.9,87.2 ({npc:3206}): smrt tam tě pošle na tento hřbitov. Uvolni ducha a přijmi oživení od {npc:6491}.",
	["Druid trainer"] = "Trenér druidů",
	["Felstalkers roam the slope below the cave, on the valley's north side."] = "Felstalkeři se potulují po svahu pod jeskyní, na severní straně údolí.",
	["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Fizzle drží tábor Burning Blade na {area:369}, kousek severně od Mishiny chýše. Hunteři: cestou si ochočte {npc:3099} pomocí {item:15908}.\nPozor: Fizzla obklopují kultisté Burning Blade, někteří propojení, takže aggrují ve dvojicích, a rychle se respawnují.\nPozor: Halikor, elite levelu 12, se potuluje po {area:369} mezi ještěry: než začneš tahat, dej si na něj pozor.",
	["Follow the road north from {area:379} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "Jdi po silnici na sever od {area:379} k hlavní bráně {zone:1454}, kousek západně od {area:817}. {npc:3352} stojí s trenéry hunterů v {object:172958}.",
	["Follow the road north from {area:379} to {zone:1454}'s main gate. The next guide starts in {zone:1454}: {quest:829} takes the cultists' quest, the trainers teach your new ranks, and the zeppelin leaves from the towers outside the gate for {zone:1420} and {zone:1421}. {zone:1413} come after Silverpine."] = "Jdi po silnici na sever od {area:379} k hlavní bráně {zone:1454}. Další návod začíná v {zone:1454}: {quest:829} vezme quest kultistů, trenéři tě naučí nové ranky a zeppelin odlétá z věží před branou do {zone:1420} a {zone:1421}. {zone:1413} přijde na řadu po Silverpine.",
	["Free {npc:275811} and see her safely out of the crag"] = "Osvoboď {npc:275811} a bezpečně ji vyveď z útesů",
	["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Jdi na severovýchod k silnici do {zone:1454}. {npc:3293} táboří vedle ní; ukradené pytle leží podél silnice jižně od něj.",
	["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nCareful: the trolls stand close together and the Voodoo Trolls cast from range: pull one at a time. {quest:826} himself is level 10."] = "Jdi na jih přes ostrůvky. Idoly Loa leží po celých jižních ostrůvcích; drží je Voodoo a Hexed Trolls, kteří dropují Hexed Pendants. {quest:826} a Minshinina klec jsou na nejjižnějším ostrůvku.\nPozor: trollové stojí blízko u sebe a Voodoo Trolls kouzlí z dálky: pullni je po jednom. Sám {quest:826} má level 10.",
	["Level 10"] = "Level 10",
	["Level 11"] = "Level 11",
	["Level 7"] = "Level 7",
	["Level 9"] = "Level 9",
	["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Mišina chýše stojí jižně od ještěrů. Krokodýli podél {area:814} na západě nosí {item:4891}.",
	["Paladin trainer"] = "Trenér paladinů",
	["Quilboars and scouts hold the huts west of town, where the prickly pears grow; dustrunners and battleguards hold the camps farther west."] = "Quilboaři a zvědové drží chýše západně od města, kde rostou opuncie; dustrunneři a battleguardi drží tábory dál na západ.",
	["Spitelash naga"] = "Nagy Spitelash",
	["Tame it with the {item:15908}"] = "Ochoč ho pomocí {item:15908}",
	["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin.\nMakrura and surf crawlers line the beaches north-east of Sen'jin."] = "Gnómské bedýnky s nářadím leží ve vracích podél pobřeží východně a jihovýchodně od {area:362}. Jdi po pobřeží na jih do Sen'jinu.\nPláže severovýchodně od Sen'jinu lemují makrury a surf crawlers.",
	["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}."] = "Pevnost stojí na pobřeží jihovýchodně od {area:362}. Sekera, luk a štít nájezdníků leží na jejím okraji. {item:4870} dropují námořníci a mariňáci.",
	["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Zbraně leží kolem Den a cvičiště; Mottled Boars se potulují po celém dně údolí.",
	["Through Sen'jin on the way west to {area:366}: {npc:3304} takes the eyes and mucus now."] = "Přes Sen'jin cestou na západ do {area:366}: {npc:3304} si teď vezme oči a sliz.",
	["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Thunder Lizards a Lightning Hides se pasou na {area:369} vedle silnice na sever do {zone:1454}; z kteréhokoli může padnout {item:6486}. {npc:5810} si ho vezme, až další návod povede přes {area:379}.\nPozor: Halikor, elite na levelu 12, se toulá po {area:369} mezi ještěry: než pullneš, dávej na něj pozor.",
	["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Thunder Lizards a Lightning Hides se pasou na {area:369}, kousek západně a jihozápadně od {npc:3293}.\nPozor: Halikor, elite na levelu 12, se toulá po {area:369} mezi ještěry: než pullneš, dávej na něj pozor.",
	["Thunder lizards on the way north"] = "Thunder lizardi cestou na sever",
	["To {zone:1454}"] = "Do {zone:1454}",
	["Top up here to level 10: {quest:840}, at {area:362}, needs level 10.\nThe prickly pears for {quest:96825} grow by these huts: pick them while you grind."] = "Tady se dotáhni na level 10: {quest:840} v {area:362} vyžaduje level 10.\nOpuncie pro {quest:96825} rostou u těchhle chýší: sbírej je při grindu.",
	["Top up here to level 11 before {npc:3203} (12) and his imp: the Thunder Lizards (9-10) graze on the ridge just west of Misha's hut."] = "Tady se dotáhni na level 11, než půjdeš na {npc:3203} (12) a jeho impa: Thunder Lizards (9–10) se pasou na hřebeni kousek západně od Mishiny chýše.",
	["Top up here to level 7 before {npc:3192} (8) and the marines at the top of the keep."] = "Tady se dotáhni na level 7, než půjdeš na {npc:3192} (8) a mariňáky na vrcholu pevnosti.",
	["Top up here to level 9 before the southern isles: the Voodoo and Hexed Trolls there are 8-9 and {quest:826} is 10."] = "Tady se dotáhni na level 9, než vyrazíš na jižní ostrovy: Voodoo a Hexed Trolls tam mají 8–9 a {quest:826} má 10.",
	["Training weapons and boars"] = "Cvičné zbraně a kanci",
	["Underwater"] = "Pod vodou",
	["Upstairs"] = "Nahoře",
	["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "Přebroď se na severní Echo Isle. Mezi raptory se tam plíží Matriarch.\nDurotar Tigers se toulají po ostrově i po pobřeží jižně od Sen'jinu a vejce Taillasherů leží v hnízdech na ostrovech a podél pláže.",
	["Wake {quest:5441} with the {item:16114}"] = "Probuď {quest:5441} pomocí {item:16114}",
	["West from {area:362} over the {area:814} bridge: {npc:3337} and {npc:5810} stand together at {area:379} above it. From there the road north through {zone:1411} leads to {zone:1454}."] = "Z {area:362} na západ přes most {area:814}: {npc:3337} a {npc:5810} stojí spolu v {area:379} nad ním. Odtud vede silnice na sever přes {zone:1411} do {zone:1454}.",
	["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "Na západ přes most {area:814}, kolem {area:379} a dál po hřebeni: {npc:5907} stojí sám nad táborem Razormane.",
	["West over the {area:814} bridge: {npc:3337} stands at {area:379} above it, on your way to {npc:5907}."] = "Na západ přes most {area:814}: {npc:3337} stojí v {area:379} nad ním, cestou k {npc:5907}.",
	["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Když už jsi tady: nauč se Staves u {npc:2704} ({object:172958}, 10 silver); u zbraně na blízko huntera jde hlavně o staty a obouručky jich mají nejvíc.",
	["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Když už jsi tady: nauč se Staves u {npc:2704} ({object:172958}, 10 silver); při levelování má hůl víc kouzelných statů než jednoručka.",
	["grind on {npc:3111}"] = "grinduj na {npc:3111}",
	["grind on {npc:3121}"] = "grinduj na {npc:3121}",
	["grind on {npc:3128}"] = "grinduj na {npc:3128}",
	["grind on {npc:3130}"] = "grinduj na {npc:3130}",
	["{area:363}: kill these as you meet them"] = "{area:363}: zabíjej je, jak na ně narazíš",
	["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} leží západně od Sen'jin. Tři plány útoku leží na zemi mezi stany kentaurů. U skaliska je držen i {npc:275811}.",
	["{area:368}: kill these as you meet them"] = "{area:368}: zabíjej je, jak na ně narazíš",
	["{area:369}: kill these as you meet them"] = "{area:369}: zabíjej je, jak na ně narazíš",
	["{area:373}: kill these as you meet them"] = "{area:373}: zabíjej je, jak na ně narazíš",
	["{area:817}'s mouth"] = "Vchod do {area:817}",
	["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11025} ho vezme, až budeš mít dovednost {skill:202} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:11378}, at the lumber pile east of the Den"] = "{npc:11378}, u hromady dřeva východně od Denu",
	["{npc:246344} in {zone:1456}; {area:362} has no paladin trainer"] = "{npc:246344} v {zone:1456}; {area:362} nemá trenéra paladinů",
	["{npc:246344} in {zone:1456}; {area:363} has no paladin trainer"] = "{npc:246344} v {zone:1456}; {area:363} nemá trenéra paladinů",
	["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} táboří kousek jižně od {area:362}. Sedni si k jeho ohni (/sit), dokud se neobjeví buff {spell:1229451}. Když máš naučenou profesi, {npc:265809} nabízí i její Camping 101, který si vezme její trenér: v {area:362} nebo v {zone:1454} na začátku dalšího návodu.",
	["{npc:265809}'s campfire"] = "Táborák {npc:265809}",
	["{npc:265809}: for Jandi"] = "{npc:265809}: pro Jandiho",
	["{npc:265809}: for Jhag"] = "{npc:265809}: pro Jhaga",
	["{npc:265809}: for Karolek"] = "{npc:265809}: pro Karoleka",
	["{npc:265809}: for Snang"] = "{npc:265809}: pro Snanga",
	["{npc:265809}: for Thuwd"] = "{npc:265809}: pro Thuwda",
	["{npc:265809}: for Whuut"] = "{npc:265809}: pro Whuuta",
	["{npc:265809}: for {npc:11025}"] = "{npc:265809}: pro {npc:11025}",
	["{npc:265809}: for {npc:3175}"] = "{npc:265809}: pro {npc:3175}",
	["{npc:265809}: for {npc:5943}"] = "{npc:265809}: pro {npc:5943}",
	["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: jen pro enchantery, residue se získá disenchantem Hexed Pendants",
	["{npc:266940}, inside"] = "{npc:266940}, uvnitř",
	["{npc:266940}, on the east side of town; inside"] = "{npc:266940}, na východní straně města; uvnitř",
	["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} stojí na břehu východně od {area:362}. Trojzubec, prapor a dýka leží na pláži kolem něj.",
	["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, mladý mořský obr, chodí po severním pobřeží {zone:1411}, severně od pláže nag. {npc:275666} je elite: doporučuje se skupina.",
	["{npc:3034} in {zone:1412}; {area:362} has no druid trainer"] = "{npc:3034} v {zone:1412}; v {area:362} druidský trenér není",
	["{npc:3034} in {zone:1412}; {area:363} has no druid trainer"] = "{npc:3034} v {zone:1412}; v {area:363} druidský trenér není",
	["{npc:3102} hooves"] = "Kopyta {npc:3102}",
	["{npc:3142}, back in {area:362}"] = "{npc:3142}, zpátky v {area:362}",
	["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, elite mořský obr",
	["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} stojí kousek uvnitř ústí jeskyně; {npc:3159} vzadu v jeskyni za ním.",
	["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} čeká uvnitř Den, budovy kousek západně od {npc:10176}.",
	["{npc:3143}, inside"] = "{npc:3143}, uvnitř",
	["{npc:3147}, in the watchtower"] = "{npc:3147}, ve strážní věži",
	["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, trenér warriorů vedle Den",
	["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, trenér hunterů vedle Den",
	["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, trenér rogue v Den",
	["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, trenér warlocků vzadu v jeskyni",
	["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, trenér šamanů vedle Den",
	["{npc:3159}, at the back of the cave; below ground"] = "{npc:3159}, vzadu v jeskyni; pod zemí",
	["{npc:3169}, inside"] = "{npc:3169}, uvnitř",
	["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171}: {npc:3352} v {zone:1454} učí {spell:5149}",
	["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3175} ho vezme, až budeš mít dovednost {skill:186} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:3191}: Camping 101 asks you to learn it"] = "{npc:3191}: Camping 101 chce, aby ses ji naučil",
	["{npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "{npc:3192} čeká na vrcholu pevnosti; jeho klíč otevírá truhlu vedle něj, ve které je {item:4881}.",
	["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} leží zraněný na úpatí kopců severozápadně od Den.",
	["{npc:3294}, by the inn"] = "{npc:3294}, u hostince",
	["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} a tvůj {item:5175}",
	["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5943} ho vezme, až budeš mít dovednost {skill:129} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:6928}, inside"] = "{npc:6928}, uvnitř",
	["{npc:9796}, by the cooking fire"] = "{npc:9796}, u ohniště na vaření",
	["{quest:790}, a large scorpid (level 4), prowls the slope just west of the Den, below {npc:3287}, on the way north to the {area:365}."] = "{quest:790}, velký scorpid (level 4), se plíží po svahu kousek západně od Denu, pod {npc:3287}, cestou na sever k {area:365}.",
	["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} táboří na kopci západně od nagí pláže, jižně od {quest:827}.",
}
t.guides["forever/horde/skyborne/01-zephras-isle"] = {
	["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit u táboráku {npc:263664}, dokud nedostaneš {spell:1229451}",
	["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders a padlí strážci jsou kousek jihozápadně od věže. Vezmi z těl Raaniho pero a pečetní prsten Shadowsong.",
	["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "Zpět u {quest:92529}: vesnici plní Stormcallers a {npc:251662}, Supply Caches stojí mezi domy a {npc:251966} čeká na jejím jihovýchodním konci.",
	["Back to Boro in {area:16635} with the Signet."] = "Zpět k Borovi do {area:16635} s pečetním prstenem.",
	["Back to {area:16635}"] = "Zpět do {area:16635}",
	["Back to {area:16638}"] = "Zpět do {area:16638}",
	["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Zpět k {npc:268592}. Počkej, až zapálí {npc:268762}, pak nes plamen rovnou k {npc:268679} vedle {npc:252382} v {area:16638}, než vyprší časovač.",
	["Back up from the den to {npc:257551} and {npc:251366} in the village before heading south-west to {npc:252095}: the road from her camp leads on south to Shen'dar."] = "Zpět nahoru z doupěte k {npc:257551} a {npc:251366} ve vesnici, než se vydáš na jihozápad k {npc:252095}: cesta z jejího tábora vede dál na jih do Shen'daru.",
	["Below ground"] = "Pod zemí",
	["Boro and {npc:251373}, while you stand beside them"] = "Boro a {npc:251373}, zatímco stojíš vedle nich",
	["Cast {spell:1259686} near the {object:460001}"] = "Sešli {spell:1259686} poblíž {object:460001}",
	["Class trainer"] = "Trenér povolání",
	["Find {npc:258130}"] = "Najdi {npc:258130}",
	["Follow the road south to {area:16624}, in the middle of the isle. {npc:251523} stands on its east side, {npc:251902} in the middle, {npc:254089} just north-west of her, {npc:263664} by the campfire on the west side. With a profession learned, {npc:263664} also offers its Camping 101: its trainer stands in the village."] = "Jdi po silnici na jih do {area:16624}, uprostřed ostrova. {npc:251523} stojí na jeho východní straně, {npc:251902} uprostřed, {npc:254089} kousek severozápadně od ní, {npc:263664} u táboráku na západní straně. S naučenou profesí nabízí {npc:263664} i svůj Camping 101: trenér té profese stojí ve vesnici.",
	["From the Crossroads follow the road north-east to {area:379}, cross the {area:815} into {zone:1411} and keep north to {zone:1454}'s main gate. The next guide starts in {zone:1454}: Thrall takes {quest:95350}, and the zeppelin leaves for {zone:1420} and {zone:1421}."] = "Z Crossroads jdi po silnici na severovýchod do {area:379}, přejdi {area:815} do {zone:1411} a pokračuj na sever k hlavní bráně {zone:1454}. Další návod začíná v {zone:1454}: Thrall vezme {quest:95350} a zeppelin odlétá do {zone:1420} a {zone:1421}.",
	["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Jdi na sever do {area:16631}; {npc:257944} táboří na jeho jižním okraji.",
	["Head north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "Jdi na severovýchod k {area:17675}. Tábor Al'Aketh je kousek západně od něj, s {npc:252666} na severním konci. Každý kultista může dropnout amulet windstone.",
	["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Jdi na jihozápad k {area:17674}. {npc:252155} je nahoře; {item:254871} leží vedle něj.",
	["Heal the injured druids in the Nightfang Den"] = "Vyléč zraněné druidy v Nightfang Den",
	["Hungry Bandits"] = "Hungry Bandits",
	["Into {zone:1412}"] = "Do {zone:1412}",
	["Into {zone:1413}"] = "Do {zone:1413}",
	["Leave {zone:2521} to {zone:1412}"] = "Z {zone:2521} do {zone:1412}",
	["Listen to {npc:252448}'s story"] = "Poslechni si příběh {npc:252448}",
	["Listen to {npc:256083}"] = "Poslechni si {npc:256083}",
	["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Pesky Cirrusflies a {npc:250873} se potulují po háji kousek jihovýchodně od vesnice.",
	["Portal to {area:16630}"] = "Portál do {area:16630}",
	["Prideclaws and Galestriders share the meadows around {area:16624}; the Galestriders graze thickest just west of it. They drop both the Small Eggs and the {item:5469} for {npc:251905}."] = "Prideclaws a Galestriders sdílejí louky kolem {area:16624}; Galestrideři se nejhustěji pasou kousek na západ od ní. Dropují Small Eggs i {item:5469} pro {npc:251905}.",
	["Raw Windstones"] = "Raw Windstones",
	["Spread the {item:278078} off {area:1641}"] = "Rozptyl {item:278078} u {area:1641}",
	["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Stormapples a prach z flutterfly leží po celém sadu; plení ho Hungry Bandits. Galestriders se pasou na polích východně od něj. Rozbitý konstrukt se vznáší na severním okraji sadu.",
	["Take the Portal to {area:16630} in the shrine up to the heights. Fight east along the ledge to the Peacekeepers at its end, ride the wind current up to the upper terrace and tell {npc:252475} you are ready. Leave the {object:617084} up there alone until Rohash has withdrawn; then it takes you straight back to town."] = "Vezmi portál do {area:16630} ve svatyni nahoře na výšinách. Probij se na východ po římse k Peacekeepers na jejím konci, vyjeď větrným proudem nahoru na horní terasu a řekni {npc:252475}, že jsi připraven. {object:617084} tam nahoře nech být, dokud se Rohash nestáhne; pak tě vezme rovnou zpátky do města.",
	["Take {item:277267} to {npc:268592} at the Shrine of Flames, south-west of {area:16638}, then head west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "Odnes {item:277267} k {npc:268592} u Shrine of Flames, jihozápadně od {area:16638}, pak jdi na západ do {area:16623}: domov {npc:268605} je v kopcích jižně od jezer Windsong Crawlers.",
	["Take {zone:1456}'s west lift down: the road at its foot runs south-east across {zone:1412} to the {zone:1413}."] = "Sjeď západním výtahem {zone:1456} dolů: cesta pod ním vede na jihovýchod přes {zone:1412} do {zone:1413}.",
	["Tame {npc:250874}"] = "Ochoč {npc:250874}",
	["Tame {npc:251707}"] = "Ochoč {npc:251707}",
	["Tame {npc:254588}"] = "Ochoč {npc:254588}",
	["Tell {npc:252800} you're ready"] = "Řekni {npc:252800}, že jsi připraven",
	["The Al'Aketh camp"] = "Tábor Al'Aketh",
	["The Enchanted Gyrozephyrs lie under water far to the north, east of {area:16624} and south-west of {area:16625}."] = "Enchanted Gyrozephyrs leží pod vodou daleko na severu, východně od {area:16624} a jihozápadně od {area:16625}.",
	["The Highwayman Bandits hold the hills north of {area:16663}; they drop the Blood-Stained Bandit Masks."] = "Highwayman Bandits drží kopce severně od {area:16663}; dropují Blood-Stained Bandit Masks.",
	["The hermit lives at {area:16625}'s west shore."] = "Poustevník žije na západním břehu {area:16625}.",
	["The hippogryph nests are north-west of the {area:17674}, west of {quest:92529}. The Matriarch sits at their western end; {item:263493} lies on the ground around the nests."] = "Hnízda hipogryfů jsou severozápadně od {area:17674}, západně od {quest:92529}. Matriarch sedí na jejich západním konci; {item:263493} leží na zemi kolem hnízd.",
	["The orchard"] = "Sad",
	["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "Královna se vznáší na jihovýchodním konci háje, cestou zpátky od kamenů.",
	["The road from {zone:1412} meets the {area:458} at {area:378}: {npc:10378}, the wind rider master, stands beside {npc:3418} on your way north to the Crossroads."] = "Silnice z {zone:1412} se setkává s {area:458} u {area:378}: {npc:10378}, mistr wind riderů, stojí vedle {npc:3418} cestou na sever do Crossroads.",
	["The standing stones"] = "Menhiry",
	["The turncoat"] = "Zrádce",
	["The turncoat's house is in the {area:16626} north-west of {area:16638}, just north of {npc:273017}."] = "Zrádcův dům je v {area:16626} severozápadně od {area:16638}, kousek severně od {npc:273017}.",
	["The {area:16629}"] = "{area:16629}",
	["The {area:17674}"] = "{area:17674}",
	["The {area:17675}"] = "{area:17675}",
	["The {object:148418}"] = "{object:148418}",
	["To {zone:1454}"] = "Do {zone:1454}",
	["Underwater"] = "Pod vodou",
	["Upstairs"] = "Nahoře",
	["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Použij {item:278078} u obřadní rohože a kadidelnice na útesu {area:1641} obráceném k jihu.",
	["Valennia asks you to hear out both leaders: {npc:251968} of the Horde and {npc:252475} of the Alliance. {npc:252475}'s name shows red to you, but he talks to you all the same, and the quest needs both."] = "Valennia tě žádá, abys vyslechl oba vůdce: {npc:251968} z Hordy a {npc:252475} z Aliance. Jméno {npc:252475} se ti ukazuje červeně, ale mluví s tebou stejně a quest potřebuje oba.",
	["Warlock trainer"] = "Trenér warlocků",
	["While you're here: learn Staves from {npc:11869} (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Když už jsi tady: nauč se Staves u {npc:11869} (10 silver); u zbraně na blízko huntera jde hlavně o staty a obouručky jich mají nejvíc.",
	["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Když už jsi tady: nauč se {spell:199} u {npc:11869} (10 silver); s obouručkami warrior levluje nejrychleji.",
	["talk to {npc:251684}"] = "promluv si s {npc:251684}",
	["talk to {npc:251902}"] = "promluv si s {npc:251902}",
