	["{area:16635} turn-ins"] = "Odevzdání v {area:16635}",
	["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663} je západně od {area:16638} po pobřežní silnici.",
	["{item:278079}, from {npc:3014}"] = "{item:278079}, od {npc:3014}",
	["{item:278080}, from {npc:3012}"] = "{item:278080}, od {npc:3012}",
	["{item:278081}, from {npc:3005}"] = "{item:278081}, od {npc:3005}",
