	["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
	["{npc:251374}, beside {npc:251361}"] = "{npc:251374}, vedle {npc:251361}",
	["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873} a tvůj {item:5175}",
	["{npc:251376}, beside {npc:251361}"] = "{npc:251376}, vedle {npc:251361}",
	["{npc:251913} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251913} ho vezme, až budeš mít dovednost {skill:164} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:251992} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251992} ho vezme, až budeš mít dovednost {skill:356} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:251993} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251993} ho vezme, až budeš mít dovednost {skill:165} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:252383}, upstairs"] = "{npc:252383}, nahoře",
	["{npc:252448} and {npc:256083}"] = "{npc:252448} a {npc:256083}",
	["{npc:252476}, upstairs"] = "{npc:252476}, nahoře",
	["{npc:253372}, inside"] = "{npc:253372}, uvnitř",
	["{npc:253590}, upstairs"] = "{npc:253590}, nahoře",
	["{npc:254344}, beside {npc:251968}"] = "{npc:254344}, vedle {npc:251968}",
	["{npc:257006} and {npc:252448}"] = "{npc:257006} a {npc:252448}",
	["{npc:257006}, inside"] = "{npc:257006}, uvnitř",
	["{npc:257018} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257018} ho vezme, až budeš mít dovednost {skill:129} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:257019} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257019} ho vezme, až budeš mít dovednost {skill:171} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:257022} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257022} ho vezme, až budeš mít dovednost {skill:186} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:257024} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257024} ho vezme, až budeš mít dovednost {skill:393} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:257944} again"] = "{npc:257944} znovu",
	["{npc:268592}, at the Shrine of Flames just south-east of the orchard"] = "{npc:268592}, u Shrine of Flames kousek jihovýchodně od sadu",
	["{npc:268602}, on the hill west of the falls just north of the watchtower"] = "{npc:268602}, na kopci západně od vodopádů kousek severně od strážní věže",
	["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} chce taurenské kadidlo: kup jeho čtyři části od bylinkáře {npc:3014}, dodavatele enchantingu {npc:3012}, dodavatele leatherworkingu {npc:3005} a dodavatele vaření {npc:3027}, pak je spoj do {item:278078}.",
	["{npc:3033} trains druids on {area:1639}. He teaches you {spell:18960}; {npc:11802}'s welcome waits for your {spell:499} trip at about 21 (forever/horde/02-the-barrens)."] = "{npc:3033} trénuje druidy na {area:1639}. Naučí tě {spell:18960}; uvítání od {npc:11802} počká na tvou cestu přes {spell:499} zhruba na levelu 21 (forever/horde/02-the-barrens).",
	["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} leží jižně od Shen'daru. {npc:257065} tě potká na jeho okraji; prohledej skříň v domě za ním.",
}
t.guides["forever/horde/tauren/01-mulgore"] = {
	["/sit by Kaga's campfire until you get {spell:1229451}"] = "/sit u Kagina táboráku, dokud nedostaneš {spell:1229451}",
	["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Zpět na východ do {area:358}: Bristleback Shamans tam stojí mezi quilboary.",
	["Back north-west up to {area:221}."] = "Zpět na severozápad nahoru do {area:221}.",
	["Back south to the {area:396}."] = "Zpět na jih do {area:396}.",
	["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Zpět k {npc:5888} do tábora. {npc:5891} čeká na mese východně od tábora: vypij tam {item:6635}, ať ho uvidíš, pak odnes {item:6656} zpět Vědmě.",
	["Back west to the camp."] = "Zpět na západ do tábora.",
	["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Battleboars se pasou severně od svatyně; quilboaři Bristleback drží rokli na severovýchodě. {npc:8554} stojí na jejím východním konci a {object:3076} leží na zemi v táboře.",
	["Below ground"] = "Pod zemí",
	["Burning Blade Cultists hold {area:1898}, east of the road north to {zone:1454}; they drop the {item:6652}. The {item:5026} comes from the Razormane on the next guide's first visit to their camp."] = "Kultisté Burning Blade drží {area:1898}, východně od cesty na sever do {zone:1454}; dropují {item:6652}. {item:5026} je od Razormane při první návštěvě jejich tábora v dalším návodu.",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. {npc:11802} je v {area:2361}; {quest:5930} sedí v severozápadních lesích. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Class trainer"] = "Trenér povolání",
	["Class turn-in in {area:1638}"] = "Odevzdání povolání v {area:1638}",
	["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Projdi na severozápad kolem {zone:1456} do {area:398} na dalekém severu {zone:1412}.",
	["Cross to {area:1639}."] = "Přejdi na {area:1639}.",
	["Deathskip to {area:220}"] = "Deathskip do {area:220}",
	["Die to the mobs at 63.7,78.4 ({npc:2954}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Nech se zabít moby na 63.7,78.4 ({npc:2954}): smrt tam tě pošle na tento hřbitov. Uvolni ducha a přijmi oživení od {npc:6491}.",
	["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}. With a profession learned, Kaga also offers its Camping 101, which its trainer takes: in Bloodhoof or on the {zone:1456} stop."] = "Jdi po silnici na sever z {area:220}. {npc:265810} čeká na silnici kousek jižně od {area:222}; sedni si /sit k jejímu táboráku, dokud nedostaneš {spell:1229451}. S naučenou profesí nabízí Kaga i svůj Camping 101, který vezme trenér té profese: v Bloodhoof nebo na zastávce {zone:1456}.",
	["From the Crossroads follow the road north-east to {area:379}, cross the {area:814} into {zone:1411} and keep north to {zone:1454}'s main gate. The next guide starts in {zone:1454} and takes the zeppelin to {zone:1420} and {zone:1421}."] = "Z Crossroads jdi po silnici na severovýchod do {area:379}, přejdi {area:814} do {zone:1411} a pokračuj na sever k hlavní bráně {zone:1454}. Další návod začíná v {zone:1454} a vezme zeppelin do {zone:1420} a {zone:1421}.",
	["From {area:1639}, take {zone:1456}'s north lift down: at its foot the way runs east along the ledge, then south-east across {zone:1412} to the {zone:1413}."] = "Z {area:1639} sjeď severním výtahem {zone:1456} dolů: od jeho úpatí vede cesta na východ po římse, pak na jihovýchod přes {zone:1412} do {zone:1413}.",
	["Galak centaurs"] = "Kentauři Galak",
	["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Jdi na sever do {area:225}, východně od {zone:1456}. {npc:3233} stojí u paty skal; Bristleback Interlopers kopou na pohřebišti a {npc:2994} čeká nahoře.",
	["Into {zone:1412}"] = "Do {zone:1412}",
	["Into {zone:1413}"] = "Do {zone:1413}",
	["Leave {zone:1412} by the south-eastern pass and follow the road to the Crossroads. {npc:3448} stands at the south gate, {quest:860} by the inn, {npc:3615} on the tower platform. {area:380}' own quests come after {zone:1421}, in the {zone:1413} guide."] = "Opusť {zone:1412} jihovýchodním průsmykem a jdi po cestě do Crossroads. {npc:3448} stojí u jižní brány, {quest:860} u hostince, {npc:3615} na plošině věže. Vlastní questy {area:380} přijdou až po {zone:1421}, v návodu pro {zone:1413}.",
	["Level 11"] = "Level 11",
	["Over the bridge below {area:379} and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Přes most pod {area:379} a na jih po břehu řeky na straně {zone:1411} až k úzké stezce, která stoupá do hory: {npc:5900} hlídá svatyni nahoře. Cestou nahoru dávej pozor na okraje a dolů se vrať stejnou stezkou.",
	["Plainstriders roam the mesa all around the camp: take their meat and feathers on the way back to {npc:2980}."] = "Plainstrideři se potulují po stolové hoře všude kolem tábora: cestou zpátky k {npc:2980} z nich seber maso a peří.",
	["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Prairie Wolf Alphas se potulují mezi vlky na pláních kolem {npc:275789} a tábora Galaků na východě.",
	["Prairie Wolves, Wiry Swoops and Adult Plainstriders roam the plains around the village; the plains just south of it, toward the well, hold them without the Elder Plainstriders (8-9) and Prairie Wolf Alphas (9-10) that roam farther out."] = "Prairie Wolves, Wiry Swoops a Adult Plainstriders se potulují po pláních kolem vesnice; na pláních kousek na jih od ní, směrem ke studni, nejsou Elder Plainstriders (8–9) ani Prairie Wolf Alphas (9–10), kteří se potulují dál.",
	["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Vyjeď výtahem nahoru na stolové hory. {npc:2995} má wind ridery na centrálním návrší; {npc:3057} stojí ve velkém stanu tamtéž.",
	["Spread the {item:278078} off {area:1641}"] = "Rozptyl {item:278078} u {area:1641}",
	["Tame it with the {item:15908}"] = "Ochoč ho pomocí {item:15908}",
	["The Galak centaurs camp on the plains east of the well; Herak leads them."] = "Kentauři Galak táboří na pláních východně od studny; vede je Herak.",
	["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "Prospector's Picks nosí trpaslíci z {area:404}. Rozbij je u trpasličí kovárny na nalezišti.",
	["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine.\nCareful: the goblins stand close together in the tunnels and {quest:765} is level 12: clear the way one pull at a time."] = "Goblini těží v dole v kopcích severovýchodně od studny. {quest:765} stojí vzadu v dole; jeho {item:281031} spouští {quest:98424} a ostatní stránky leží uvnitř dolu.\nPozor: Goblini stojí v tunelech blízko u sebe a {quest:765} má level 12: čisti cestu po jednom pullu.",
	["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "Kadidlo dohoří za deset minut: běž rovnou na východ podél jižních kopců k {object:660739}.",
	["The shrine of An'she and Mu'sha"] = "Svatyně An'she a Mu'shy",
	["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "Kámen stojí v průsmyku ven z {zone:1412}, cestou na východ. Použij tam {item:15710} a poraz Lunaclawa.",
	["The well lies north of the village. Adult Plainstriders graze around it: they drop the {item:287505} for Kyle."] = "Studna leží severně od vesnice. Kolem ní se pasou Adult Plainstriders: dropují {item:287505} pro Kylea.",
	["The well lies south-east of the village. {npc:2988} camps beside it, and {quest:99079} stands on the {area:821} a little east."] = "Studna leží jihovýchodně od vesnice. Vedle ní táboří {npc:2988} a {quest:99079} stojí na {area:821} kousek na východ.",
	["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "Zničená karavana leží severozápadně od kentaurů, východně od silnice do {zone:1456}.",
	["The {object:177525}"] = "{object:177525}",
	["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes them when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Thunder Lizards a Lightning Hides se pasou na {area:369} vedle silnice na sever do {zone:1454}; z kteréhokoli může padnout {item:6486}. {npc:5810} si je vezme, až další návod povede přes {area:379}.\nPozor: Halikor, elite na levelu 12, se toulá po {area:369} mezi ještěry: než pullneš, dávej na něj pozor.",
	["Thunder lizards on the way north"] = "Thunder lizardi cestou na sever",
	["To {zone:1454}"] = "Do {zone:1454}",
	["Top up here to level 11 before the mine: {quest:765} is 12. The Venture Co. Workers (8-9) in the hills outside it count for {quest:764} too."] = "Tady se před dolem dotáhni na level 11: {quest:765} má level 12. Venture Co. Workers (8–9) v kopcích před ním se počítají i do {quest:764}.",
	["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Použij {item:278078} u obřadní rohože a kadidelnice na útesu {area:1641} obráceném k jihu.",
	["Warlock trainer"] = "Trenér warlocků",
	["While you're here: learn Staves from {npc:11869} (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Když už jsi tady: nauč se Staves u {npc:11869} (10 silver); u zbraně na blízko huntera jde hlavně o staty a obouručky jich mají nejvíc.",
	["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Když už jsi tady: nauč se {spell:199} u {npc:11869} (10 silver); s obouručkami warrior levluje nejrychleji.",
	["grind on {npc:2978}"] = "grinduj na {npc:2978}",
	["{area:1898} cultists"] = "Kultisté {area:1898}",
	["{area:220}: kill these as you meet them"] = "{area:220}: zabíjej je, jak na ně narazíš",
	["{area:221}: kill these as you meet them"] = "{area:221}: zabíjej je, jak na ně narazíš",
	["{area:379} sits above the {area:814} bridge on the road to {zone:1454}: {npc:5810} stands beside {npc:3337}."] = "{area:379} leží nad mostem {area:814} na silnici do {zone:1454}: {npc:5810} stojí vedle {npc:3337}.",
	["{area:474}: kill these as you meet them"] = "{area:474}: zabíjej je, jak na ně narazíš",
	["{item:278079}, from {npc:3014}"] = "{item:278079}, od {npc:3014}",
	["{item:278080}, from {npc:3012}"] = "{item:278080}, od {npc:3012}",
	["{item:278081}, from {npc:3005}"] = "{item:278081}, od {npc:3005}",
	["{item:278083}, from {npc:3027}"] = "{item:278083}, od {npc:3027}",
	["{npc:10278} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:10278} ho vezme, až budeš mít dovednost {skill:164} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:10378}, beside {npc:3418}"] = "{npc:10378}, vedle {npc:3418}",
	["{npc:11047} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11047} ho vezme, až budeš mít dovednost {skill:171} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:11051} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11051} ho vezme, až budeš mít dovednost {skill:197} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:11071} takes it once your {skill:333} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11071} ho vezme, až budeš mít dovednost {skill:333} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:265810}: for {npc:10278}"] = "{npc:265810}: pro {npc:10278}",
	["{npc:265810}: for {npc:11047}"] = "{npc:265810}: pro {npc:11047}",
