	["{npc:265810}: for {npc:11071}"] = "{npc:265810}: pro {npc:11071}",
	["{npc:265810}: for {npc:3001}"] = "{npc:265810}: pro {npc:3001}",
	["{npc:265810}: for {npc:3013}"] = "{npc:265810}: pro {npc:3013}",
	["{npc:265810}: for {npc:3069}"] = "{npc:265810}: pro {npc:3069}",
	["{npc:265810}: for {npc:5938}"] = "{npc:265810}: pro {npc:5938}",
	["{npc:265810}: for {npc:5939}"] = "{npc:265810}: pro {npc:5939}",
	["{npc:265810}: for {npc:6290}"] = "{npc:265810}: pro {npc:6290}",
	["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} chce taurenské kadidlo: kup jeho čtyři části od bylinkáře {npc:3014}, dodavatele enchantingu {npc:3012}, dodavatele leatherworkingu {npc:3005} a dodavatele vaření {npc:3027}, pak je spoj do {item:278078}.",
	["{npc:277154} runs around the village: give him the {item:287505}"] = "{npc:277154} pobíhá po vesnici: dej mu {item:287505}",
	["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} stojí na severním okraji vesnice. Kyle chce {item:287505} z plainstriderů.",
	["{npc:277182}, at the north end of the village"] = "{npc:277182}, na severním konci vesnice",
	["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, pro Hamuula v {zone:1456}",
	["{npc:2950} walks around {area:16677}: look inside the circle on the map"] = "{npc:2950} chodí po {area:16677}: hledej uvnitř kruhu na mapě",
	["{npc:2951}, below ground"] = "{npc:2951}, pod zemí",
	["{npc:2981}, inside"] = "{npc:2981}, uvnitř",
	["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} stojí na okraji {area:404}, jižně od studny.",
	["{npc:2987}, beside {npc:269068}"] = "{npc:2987}, vedle {npc:269068}",
	["{npc:2988} walks around here: look inside the circle on the map"] = "{npc:2988} chodí po okolí: hledej uvnitř kruhu na mapě",
	["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} sedí u stanu na východním okraji tábora; {object:2907} stojí vedle ní.",
	["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, pro {npc:3057} v {zone:1456}",
	["{npc:3001} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3001} ho vezme, až budeš mít dovednost {skill:186} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:3013} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3013} ho vezme, až budeš mít dovednost {skill:182} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:3033} trains druids in the Cenarion Circle's tent on {area:1639}."] = "{npc:3033} trénuje druidy ve stanu Cenarion Circle na {area:1639}.",
	["{npc:3039}, beside {npc:3041}"] = "{npc:3039}, vedle {npc:3041}",
	["{npc:3057}'s tent"] = "Stan {npc:3057}",
	["{npc:3059}, the warrior trainer; inside"] = "{npc:3059}, trenér warriorů; uvnitř",
	["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, druidský trenér vedle něj",
	["{npc:3061}, the hunter trainer"] = "{npc:3061}, trenér hunterů",
	["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, trenér šamanů v táboře",
	["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Quest od {npc:3063}: poraz tři Novice Warriors (nebo hráče v duelu) vedle něj.",
	["{npc:3065} stands at the north end of {area:222}. Tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a {npc:2970} to the north-west."] = "{npc:3065} stojí na severním konci {area:222}. Ochoč pomocí {item:15908}: {npc:2956} na pláních, {npc:2959} severně od vesnice, {npc:2970} na severozápadě.",
	["{npc:3067}: Camping 101 asks you to learn it"] = "{npc:3067}: Camping 101 chce, aby ses ji naučil",
	["{npc:3069} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3069} ho vezme, až budeš mít dovednost {skill:165} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3069}, vedle {npc:3067}: {quest:97934}",
	["{npc:3155} in {zone:1411}; {zone:1412} has no rogue trainer"] = "{npc:3155} v {zone:1411}; v {zone:1412} trenér rogue není",
	["{npc:3156} in {zone:1411}; {zone:1412} has no warlock trainer"] = "{npc:3156} v {zone:1411}; v {zone:1412} trenér warlocků není",
	["{npc:3209} walks around {area:221}: look inside the circle on the map"] = "{npc:3209} chodí po {area:221}: hledej uvnitř kruhu na mapě",
	["{npc:3209}, next to {npc:2980}; walks around {area:221}: look inside the circle on the map"] = "{npc:3209}, vedle {npc:2980}; chodí po {area:221}: hledej uvnitř kruhu na mapě",
	["{npc:3222} walks around {area:222}: look inside the circle on the map"] = "{npc:3222} chodí po {area:222}: hledej uvnitř kruhu na mapě",
	["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418} stojí v {area:378}, kde se cesta z {zone:1412} potkává s {area:458} na sever ke Crossroads.",
	["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418}: pro {npc:3429} na Crossroads",
	["{npc:3429}, by the wind rider tower"] = "{npc:3429}, u věže wind riderů",
	["{npc:3441}: for {quest:860} at the Crossroads"] = "{npc:3441}: pro {quest:860} na Crossroads",
	["{npc:3483} sells armor on the north side of the Crossroads. His bundle goes to {npc:3615}, who sends it with you on the flight to {zone:1456} you take for {npc:3033} anyway."] = "{npc:3483} prodává zbroj na severní straně Crossroads. Jeho balík jde k {npc:3615}, který ti ho dá s sebou na let do {zone:1456}, který stejně podnikáš kvůli {npc:3033}.",
	["{npc:3615}, the wind rider master"] = "{npc:3615}, mistr wind riderů",
	["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873} a tvůj {item:5175}",
	["{npc:5938} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5938} ho vezme, až budeš mít dovednost {skill:356} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:5939} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5939} ho vezme, až budeš mít dovednost {skill:129} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:6290} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6290} ho vezme, až budeš mít dovednost {skill:393} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:8359}, by the wind riders on the central rise"] = "{npc:8359}, u wind riderů na centrálním návrší",
	["{object:2910}, 170 yd east"] = "{object:2910}, 170 yd východně",
	["{zone:1412}: kill these as you meet them"] = "{zone:1412}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/horde/troll/01-durotar"] = {
	["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Armored Scorpids lezou po pláních západně od {area:362}. Ochoč si jednoho a vrať se k {npc:3171}.",
	["Back east to Sen'jin on the way to the {area:368}."] = "Zpět na východ do Sen'jinu cestou do {area:368}.",
	["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Zpět na severozápad do {area:362}: nejdřív {npc:3139}, pak {npc:3147} ve strážní věži, pak {npc:3142} a {npc:266940} cestou ven na východ k pobřeží.",
	["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Zpět přes most a na jih po břehu řeky v {zone:1411} tam, kde úzká stezka stoupá do hory: svatyni nahoře drží {npc:5900}. Cestou nahoru dávej pozor na okraje a dolů se vrať stejnou stezkou.",
	["Back to the Den"] = "Zpět do Den",
	["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "Zpět do Den: {npc:3143} vezme dráp {quest:804} a {npc:5887} hned venku má teď, když máš level 4, {quest:1516}.",
	["Back to {area:362}."] = "Zpět do {area:362}.",
	["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "Zpět do {area:362}: {npc:3139}, pak {npc:3142}.",
	["Back to {zone:1411}"] = "Zpět do {zone:1411}",
	["Below ground"] = "Pod zemí",
	["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "Kultisté Burning Blade drží jeskyně {quest:827}; {item:4871} dropne kterýkoli z nich. {npc:3204}, warlock levelu 14, stojí hluboko uvnitř a dropne {item:4903}.\nPozor: V {quest:827} bojují vedle kultistů Burning Blade voidwalkeři a {npc:3204} (14) čeká vzadu se svým: kvůli obojkům tahej kultisty po jednom u vchodu. {item:4903} je volitelný: {npc:3204} nech být, pokud nemáš 13 nebo kamaráda.",
	["Class trainer"] = "Trenér povolání",
	["Deathskip to Northern Durotar"] = "Deathskip do severního Durotaru",
	["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Nech se zabít moby na 52.0,21.4 ({npc:3118}): smrt tam tě pošle na tento hřbitov. Uvolni ducha a přijmi oživení od {npc:6491}.",
	["Druid trainer"] = "Trenér druidů",
	["Felstalkers roam the slope below the cave, on the valley's north side."] = "Felstalkeři se potulují po svahu pod jeskyní, na severní straně údolí.",
	["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Fizzle drží tábor Burning Blade na {area:369}, kousek severně od Mishiny chýše. Hunteři: cestou si ochočte {npc:3099} pomocí {item:15908}.\nPozor: Fizzla obklopují kultisté Burning Blade, někteří propojení, takže aggrují ve dvojicích, a rychle se respawnují.\nPozor: Halikor, elite levelu 12, se potuluje po {area:369} mezi ještěry: než začneš tahat, dej si na něj pozor.",
	["Follow the road east out of the valley to {area:367} on the coast.\nCareful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "Jdi po silnici na východ z údolí do {area:367} na pobřeží.\nPozor: Ukorsbane (8) je elite a chodí mezi pavouky Ridgeshade v táboře jižně od {area:362}: odtáhni pavouky od něj.",
	["Follow the road north from {area:379} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "Jdi po silnici na sever od {area:379} k hlavní bráně {zone:1454}, kousek západně od {area:817}. {npc:3352} stojí s trenéry hunterů v {object:172958}.",
	["Follow the road north from {area:379} to {zone:1454}'s main gate. The next guide starts in {zone:1454}: {quest:829} takes the cultists' quest, the trainers teach your new ranks, and the zeppelin leaves from the towers outside the gate for {zone:1420} and {zone:1421}. {zone:1413} come after Silverpine."] = "Jdi po silnici na sever od {area:379} k hlavní bráně {zone:1454}. Další návod začíná v {zone:1454}: {quest:829} vezme quest kultistů, trenéři tě naučí nové ranky a zeppelin odlétá z věží před branou do {zone:1420} a {zone:1421}. {zone:1413} přijde na řadu po Silverpine.",
	["Free {npc:275811} and see her safely out of the crag"] = "Osvoboď {npc:275811} a bezpečně ji vyveď z útesů",
	["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Jdi na severovýchod k silnici do {zone:1454}. {npc:3293} táboří vedle ní; ukradené pytle leží podél silnice jižně od něj.",
	["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nCareful: the trolls stand close together and the Voodoo Trolls cast from range: pull one at a time. {quest:826} himself is level 10.\nWade back west to the shore south of Sen'jin when the isles are done."] = "Jdi na jih přes ostrůvky. Idoly Loa leží po celých jižních ostrůvcích; drží je Voodoo a Hexed Trolls, kteří dropují Hexed Pendants. {quest:826} a Minshinina klec jsou na nejjižnějším ostrůvku.\nPozor: trollové stojí blízko u sebe a Voodoo Trolls kouzlí z dálky: pullni je po jednom. Sám {quest:826} má level 10.\nAž budeš s ostrůvky hotový, broď se zpátky na západ ke břehu jižně od Sen'jinu.",
	["Heal and fortify {npc:12430}"] = "Vyléč a posil {npc:12430}",
	["Level 10"] = "Level 10",
	["Level 11"] = "Level 11",
	["Level 7"] = "Level 7",
	["Level 9"] = "Level 9",
	["Makrura and surf crawlers line the beaches north-east of Sen'jin; the Taillasher eggs sit in nests along the beach.\nThe gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin."] = "Makrury a surf crawleři lemují pláže severovýchodně od Sen'jinu; vejce Taillasherů leží v hnízdech podél pláže.\nGnómské bedny s nářadím leží ve vracích podél pobřeží východně a jihovýchodně od {area:362}. Jdi po pobřeží na jih do Sen'jinu.",
	["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Mišina chýše stojí jižně od ještěrů. Krokodýli podél {area:814} na západě nosí {item:4891}.",
	["Paladin trainer"] = "Trenér paladinů",
	["Quilboars and scouts hold the huts west of town, where the prickly pears grow; dustrunners and battleguards hold the camps farther west."] = "Quilboaři a zvědové drží chýše západně od města, kde rostou opuncie; dustrunneři a battleguardi drží tábory dál na západ.",
	["Spitelash naga"] = "Nagy Spitelash",
	["Tame it with the {item:15908}"] = "Ochoč ho pomocí {item:15908}",
	["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}."] = "Pevnost stojí na pobřeží jihovýchodně od {area:362}. Sekera, luk a štít nájezdníků leží na jejím okraji. {item:4870} dropují námořníci a mariňáci.",
	["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Zbraně leží kolem Den a cvičiště; Mottled Boars se potulují po celém dně údolí.",
	["Through Sen'jin on the way west to {area:366}: {npc:3304} takes the eyes and mucus now."] = "Přes Sen'jin cestou na západ do {area:366}: {npc:3304} si teď vezme oči a sliz.",
	["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Thunder Lizards a Lightning Hides se pasou na {area:369} vedle silnice na sever do {zone:1454}; z kteréhokoli může padnout {item:6486}. {npc:5810} si ho vezme, až další návod povede přes {area:379}.\nPozor: Halikor, elite na levelu 12, se toulá po {area:369} mezi ještěry: než pullneš, dávej na něj pozor.",
	["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Thunder Lizards a Lightning Hides se pasou na {area:369}, kousek západně a jihozápadně od {npc:3293}.\nPozor: Halikor, elite na levelu 12, se toulá po {area:369} mezi ještěry: než pullneš, dávej na něj pozor.",
	["Thunder lizards on the way north"] = "Thunder lizardi cestou na sever",
	["To {zone:1454}"] = "Do {zone:1454}",
	["Top up here to level 10: {quest:840}, at {area:362}, needs level 10.\nThe prickly pears for {quest:96825} grow by these huts: pick them while you grind."] = "Tady se dotáhni na level 10: {quest:840} v {area:362} vyžaduje level 10.\nOpuncie pro {quest:96825} rostou u těchhle chýší: sbírej je při grindu.",
	["Top up here to level 11 before {npc:3203} (12) and his imp: the Thunder Lizards (9-10) graze on the ridge just west of Misha's hut."] = "Tady se dotáhni na level 11, než půjdeš na {npc:3203} (12) a jeho impa: Thunder Lizards (9–10) se pasou na hřebeni kousek západně od Mishiny chýše.",
	["Top up here to level 7 before {npc:3192} (8) and the marines at the top of the keep."] = "Tady se dotáhni na level 7, než půjdeš na {npc:3192} (8) a mariňáky na vrcholu pevnosti.",
	["Top up here to level 9 before the southern isles: the Voodoo and Hexed Trolls there are 8-9 and {quest:826} is 10."] = "Tady se dotáhni na level 9, než vyrazíš na jižní ostrovy: Voodoo a Hexed Trolls tam mají 8–9 a {quest:826} má 10.",
	["Training weapons and boars"] = "Cvičné zbraně a kanci",
	["Underwater"] = "Pod vodou",
	["Upstairs"] = "Nahoře",
	["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there; Durotar Tigers roam the isle and the shore south of Sen'jin."] = "Přebroď se na severní Echo Isle. Mezi raptory se tam plíží Matriarch; Durotar Tigers se toulají po ostrově i po pobřeží jižně od Sen'jinu.",
	["Wake {quest:5441} with the {item:16114}"] = "Probuď {quest:5441} pomocí {item:16114}",
	["West from {area:362} over the {area:814} bridge: {npc:3337} and {npc:5810} stand together at {area:379} above it. From there the road north through {zone:1411} leads to {zone:1454}."] = "Z {area:362} na západ přes most {area:814}: {npc:3337} a {npc:5810} stojí spolu v {area:379} nad ním. Odtud vede silnice na sever přes {zone:1411} do {zone:1454}.",
	["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "Na západ přes most {area:814}, kolem {area:379} a dál po hřebeni: {npc:5907} stojí sám nad táborem Razormane.",
	["West over the {area:814} bridge: {npc:3337} stands at {area:379} above it, on your way to {npc:5907}."] = "Na západ přes most {area:814}: {npc:3337} stojí v {area:379} nad ním, cestou k {npc:5907}.",
	["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Když už jsi tady: nauč se Staves u {npc:2704} ({object:172958}, 10 silver); u zbraně na blízko huntera jde hlavně o staty a obouručky jich mají nejvíc.",
	["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Když už jsi tady: nauč se Staves u {npc:2704} ({object:172958}, 10 silver); při levelování má hůl víc kouzelných statů než jednoručka.",
	["grind on {npc:3111}"] = "grinduj na {npc:3111}",
	["grind on {npc:3121}"] = "grinduj na {npc:3121}",
	["grind on {npc:3128}"] = "grinduj na {npc:3128}",
	["grind on {npc:3130}"] = "grinduj na {npc:3130}",
	["{area:363}: kill these as you meet them"] = "{area:363}: zabíjej je, jak na ně narazíš",
	["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} leží západně od Sen'jin. Tři plány útoku leží na zemi mezi stany kentaurů. U skaliska je držen i {npc:275811}.",
	["{area:368}: kill these as you meet them"] = "{area:368}: zabíjej je, jak na ně narazíš",
	["{area:369}: kill these as you meet them"] = "{area:369}: zabíjej je, jak na ně narazíš",
	["{area:373}: kill these as you meet them"] = "{area:373}: zabíjej je, jak na ně narazíš",
	["{area:817}'s mouth"] = "Vchod do {area:817}",
	["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11025} ho vezme, až budeš mít dovednost {skill:202} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:11378} first, just east of the Den as you come down from the cave; then inside the Den ({npc:3143}, your trainer, {npc:3707}), and {npc:3145} and {npc:5887} at the entrance on the way out east to {npc:6786}."] = "Nejdřív {npc:11378}, kousek východně od Denu, když scházíš z jeskyně; pak uvnitř Denu ({npc:3143}, tvůj trenér, {npc:3707}) a {npc:3145} a {npc:5887} u vchodu, cestou ven na východ k {npc:6786}.",
	["{npc:11378}, at the lumber pile east of the Den"] = "{npc:11378}, u hromady dřeva východně od Denu",
	["{npc:12430} kneels behind the rocks just off the road south of {area:362}, on your way to the keep. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12430} klečí za skalami kousek od cesty jižně od {area:362}, cestou do pevnosti. Sešli na ni {spell:613} (Rank 2), pak {spell:1243}: Rank 1 {spell:613} se nepočítá.",
	["{npc:246344} in {zone:1456}; {area:362} has no paladin trainer"] = "{npc:246344} v {zone:1456}; {area:362} nemá trenéra paladinů",
	["{npc:246344} in {zone:1456}; {area:363} has no paladin trainer"] = "{npc:246344} v {zone:1456}; {area:363} nemá trenéra paladinů",
	["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} táboří kousek jižně od {area:362}. Sedni si k jeho ohni (/sit), dokud se neobjeví buff {spell:1229451}. Když máš naučenou profesi, {npc:265809} nabízí i její Camping 101, který si vezme její trenér: v {area:362} nebo v {zone:1454} na začátku dalšího návodu.",
	["{npc:265809}'s campfire"] = "Táborák {npc:265809}",
	["{npc:265809}: for Jandi"] = "{npc:265809}: pro Jandiho",
	["{npc:265809}: for Jhag"] = "{npc:265809}: pro Jhaga",
	["{npc:265809}: for Karolek"] = "{npc:265809}: pro Karoleka",
	["{npc:265809}: for Snang"] = "{npc:265809}: pro Snanga",
	["{npc:265809}: for Thuwd"] = "{npc:265809}: pro Thuwda",
	["{npc:265809}: for Whuut"] = "{npc:265809}: pro Whuuta",
	["{npc:265809}: for {npc:11025}"] = "{npc:265809}: pro {npc:11025}",
	["{npc:265809}: for {npc:3175}"] = "{npc:265809}: pro {npc:3175}",
	["{npc:265809}: for {npc:5943}"] = "{npc:265809}: pro {npc:5943}",
	["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: jen pro enchantery, residue se získá disenchantem Hexed Pendants",
	["{npc:266940}, inside"] = "{npc:266940}, uvnitř",
	["{npc:266940}, on the east side of town; inside"] = "{npc:266940}, na východní straně města; uvnitř",
	["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} stojí na břehu východně od {area:362}. Trojzubec, prapor a dýka leží na pláži kolem něj.",
	["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, mladý mořský obr, chodí po severním pobřeží {zone:1411}, severně od pláže nag. {npc:275666} je elite: doporučuje se skupina.",
	["{npc:3034} in {zone:1412}; {area:362} has no druid trainer"] = "{npc:3034} v {zone:1412}; v {area:362} druidský trenér není",
	["{npc:3034} in {zone:1412}; {area:363} has no druid trainer"] = "{npc:3034} v {zone:1412}; v {area:363} druidský trenér není",
	["{npc:3102} hooves"] = "Kopyta {npc:3102}",
	["{npc:3142}, back in {area:362}"] = "{npc:3142}, zpátky v {area:362}",
	["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, elite mořský obr",
	["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} stojí kousek uvnitř ústí jeskyně; {npc:3159} vzadu v jeskyni za ním.",
	["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} čeká uvnitř Den, budovy kousek západně od {npc:10176}.",
	["{npc:3143}, inside"] = "{npc:3143}, uvnitř",
	["{npc:3147}, in the watchtower"] = "{npc:3147}, ve strážní věži",
	["{npc:3159}, at the back of the cave; below ground"] = "{npc:3159}, vzadu v jeskyni; pod zemí",
	["{npc:3169}, inside"] = "{npc:3169}, uvnitř",
	["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171}: {npc:3352} v {zone:1454} učí {spell:5149}",
	["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3175} ho vezme, až budeš mít dovednost {skill:186} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:3191}: Camping 101 asks you to learn it"] = "{npc:3191}: Camping 101 chce, aby ses ji naučil",
	["{npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "{npc:3192} čeká na vrcholu pevnosti; jeho klíč otevírá truhlu vedle něj, ve které je {item:4881}.",
	["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} leží zraněný na úpatí kopců severozápadně od Den.",
	["{npc:3294}, by the inn"] = "{npc:3294}, u hostince",
	["{npc:3706}, beside {npc:266940}: the {item:16606}"] = "{npc:3706}, vedle {npc:266940}: {item:16606}",
	["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, pro {npc:6018} v {zone:1454}: nech si ho",
	["{npc:3706}, in the barracks beside {npc:266940}"] = "{npc:3706}, v kasárnách vedle {npc:266940}",
	["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, trenér kněží v Den",
	["{npc:3707}, the priest trainer at the Den: for {npc:3706} in {area:362}"] = "{npc:3707}, trenér kněží v Den: pro {npc:3706} v {area:362}",
	["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} a tvůj {item:5175}",
	["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5943} ho vezme, až budeš mít dovednost {skill:129} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:6928}, inside"] = "{npc:6928}, uvnitř",
	["{npc:9796} stands just outside the Den's entrance."] = "{npc:9796} stojí kousek před vchodem do Denu.",
	["{npc:9796}, by the cooking fire"] = "{npc:9796}, u ohniště na vaření",
	["{quest:790}, a large scorpid (level 4), prowls the slope just west of the Den, below {npc:3287}, on the way north to the {area:365}."] = "{quest:790}, velký scorpid (level 4), se plíží po svahu kousek západně od Denu, pod {npc:3287}, cestou na sever k {area:365}.",
	["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} táboří na kopci západně od nagí pláže, jižně od {quest:827}.",
}
t.guides["forever/horde/undead/01-tirisfal-glades"] = {
	["/sit by her campfire until you get {spell:1229451}"] = "/sit u jejího táboráku, dokud nedostaneš {spell:1229451}",
	["Ask {npc:10666} for his report"] = "Požádej {npc:10666} o jeho hlášení",
	["Ask {npc:1496} for his report"] = "Požádej {npc:1496} o jeho hlášení",
	["Ask {npc:251001} for his report"] = "Požádej {npc:251001} o jeho hlášení",
	["Back east along the road to {area:159}. {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Zpět na východ po cestě do {area:159}. {npc:2128} (mágové), {npc:2129} (kněží), {npc:2127} (warlockové) a {npc:2130} (rogue) stojí nahoře v hostinci: jdi po schodech uvnitř, šipka patra nerozliší.",
	["Back to the church"] = "Zpět do kostela",
	["Back to {area:154}"] = "Zpět do {area:154}",
	["Back to {zone:1420}"] = "Zpět do {zone:1420}",
	["Back up the road and through {area:159} to its west end."] = "Zpět nahoru po cestě a přes {area:159} na jeho západní konec.",
	["Back up the road to {area:159}, on the way north-west to {area:157}."] = "Zpět nahoru po cestě do {area:159}, cestou na severozápad do {area:157}.",
	["Back up the road to {area:159}. {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Zpět nahoru po cestě do {area:159}. {npc:2128} (mágové), {npc:2129} (kněží), {npc:2127} (warlockové) a {npc:2130} (rogue) stojí nahoře v hostinci: jdi po schodech uvnitř, šipka patra nerozliší.",
	["Back up to the forest's edge south of the keep's gate: {npc:246389} and {npc:259190} take the bones and the crystal."] = "Zpět nahoru na okraj lesa jižně od brány pevnosti: {npc:246389} a {npc:259190} vezmou kosti a krystal.",
	["Beat {npc:6784} in the duel"] = "Poraz {npc:6784} v duelu",
	["Below ground"] = "Pod zemí",
	["Crusader's Outpost"] = "Crusader's Outpost",
	["Dry Branches"] = "Dry Branches",
	["Eleanor camps just south-west of town. With a profession learned, she also offers its Camping 101, which its trainer takes: in {area:159}, at Linnea's camp, or in the {zone:1458} in the next guide."] = "Eleanor táboří kousek jihozápadně od města. S naučenou profesí nabízí i její Camping 101, který bere její trenér: v {area:159}, v Linnein táboře, nebo v {zone:1458} v dalším návodu.",
	["Eleanor: for {npc:2114}"] = "Eleanor: pro {npc:2114}",
	["Eleanor: for {npc:2132}"] = "Eleanor: pro {npc:2132}",
	["Eleanor: for {npc:3523}"] = "Eleanor: pro {npc:3523}",
	["Eleanor: for {npc:3549}"] = "Eleanor: pro {npc:3549}",
	["Eleanor: for {npc:4586}"] = "Eleanor: pro {npc:4586}",
	["Eleanor: for {npc:4598}"] = "Eleanor: pro {npc:4598}",
	["Eleanor: for {npc:4605}"] = "Eleanor: pro {npc:4605}",
	["Eleanor: for {npc:5695}"] = "Eleanor: pro {npc:5695}",
	["Eleanor: for {npc:5759}"] = "Eleanor: pro {npc:5759}",
	["Eleanor: for {npc:6289}"] = "Eleanor: pro {npc:6289}",
	["Escort {npc:275954} out of the outpost"] = "Eskortuj {npc:275954} ven ze stanoviště",
	["Everything here is inside the inn, through its door on the south side: {npc:5688} at the bar, {npc:265944} at the north end of the ground floor, the {npc:1931} in the cellar under that end, and {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) upstairs: take the stairs inside, the arrow cannot tell the floors apart."] = "Všechno tady je v hostinci, dveřmi na jižní straně: {npc:5688} u baru, {npc:265944} na severním konci přízemí, {npc:1931} ve sklepě pod tím koncem a {npc:2128} (mágové), {npc:2129} (kněží), {npc:2127} (warlockové) a {npc:2130} (rogue) nahoře: jdi po schodech uvnitř, šipka patra nerozliší.",
	["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "Jdi po stezce na sever do {area:154}; Sarvis stojí před kostelem.",
	["Follow the road east past the cult's farm. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the {quest:99142} grows: Linnea wants eight of each.\nThe Scarlet Friars camp just north-east of the graves; {npc:1664} stands among them.\nThe spiders lurk in the woods at the far east end of the glades.\nCareful: Riptear (13) is elite and prowls west and north of the Scarlet Friars' camp: watch for him before you pull."] = "Jdi po silnici na východ kolem farmy kultu. Hroby na východní straně statku, kde roste {quest:99142}, straší Bleeding Horrors a Wandering Spirits: Linnea chce od každého osm.\nScarlet Friars táboří kousek severovýchodně od hrobů; {npc:1664} stojí mezi nimi.\nPavouci číhají v lesích na nejvýchodnějším konci mýtin.\nPozor: Riptear (13) je elite a slídí západně a severně od tábora Scarlet Friars: než začneš tahat, dej si na něj pozor.",
	["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}.\nCareful: Rotting undead and Darkeye Bonecasters near the Agamands can join a fight as adds."] = "Jdi po silnici na severozápad do {area:157}. {npc:1657} chodí po hřbitově jižně od mlýnů; Nissa, Gregor a {npc:1656} straší přímo ve mlýnech. Žebra dropují Rattlecage a Cracked Skull Soldiers, lebky Darkeye Bonecasters a kterýkoli z nich může dropnout {item:2839}.\nPozor: hnijící nemrtví a Darkeye Bonecasters u Agamandů se mohou přidat do boje jako addy.",
	["Follow the road south-east from {area:159} past the zeppelin towers."] = "Jdi po silnici na jihovýchod od {area:159} kolem věží zeppelinů.",
	["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "Jdi po silnici na jihovýchod od {area:159} kolem věží zeppelinů. Linnea, Kristof a {npc:3549} táboří u silnice.",
	["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "Jdi po silnici na jihozápad od {area:159} k táboru Scarlet Crusade. {npc:1662} stojí na jeho jižním konci; prsten může dropnout kterýkoli Scarlet tam.",
	["Free the {npc:271961}"] = "Osvoboď {npc:271961}",
	["From level 10 {npc:1738} offers {quest:96895}: {npc:267009} waits at Linnea's camp, the next stop. Below 10 it waits for the {area:159} visit after {area:157}."] = "Od levelu 10 nabízí {npc:1738} {quest:96895}: {npc:267009} čeká v Linneině táboře, na další zastávce. Pod levelem 10 to počká na návštěvu {area:159} po {area:157}.",
	["From level 7 {npc:2132}, beside Johaan in the apothecary's house, offers her elixir quest; below 7 it waits for the next {area:159} visit."] = "Od levelu 7 nabízí {npc:2132}, vedle Johaana v lékárníkově domě, svůj quest s elixírem; pod levelem 7 počká na další návštěvu {area:159}.",
	["Greater Duskbats (6-7) fly over the fields around {area:159} and along the road north: Gretchen wants their pelts, {npc:3549} their wings. The Vampiric Duskbats (8-9) farther out drop them too, but hit harder.\nThe {quest:5482} grows in the graveyard fields just north of {area:159}, where the Rot Hide Graverobbers dig; all the Rot Hides drop the ichor.\nThe Rot Hide Mongrels hold the hills further north, around {area:164}. Leave {npc:1753} (level 11) in his hut for now: the guide comes back for him at the end.\nThe Vile Fin murlocs line the north shore: they all drop the scales, and the Minor Oracles and Muckdwellers the skins for {npc:3549}. Straight north of {area:159} the shore holds Puddlejumpers and Minor Oracles (7-9) with no Muckdwellers (9-10) close by."] = "Greater Duskbats (6–7) létají nad poli kolem {area:159} a podél silnice na sever: Gretchen chce jejich kožešiny, {npc:3549} jejich křídla. Vampiric Duskbats (8–9) dál od silnice je dropují taky, ale bijí víc.\n{quest:5482} roste na hřbitovních polích kousek severně od {area:159}, kde kopou Rot Hide Graverobbers; ichor dropují všichni Rot Hide.\nRot Hide Mongrels drží kopce dál na sever, kolem {area:164}. {npc:1753} (level 11) zatím nech v jeho chýši: návod se pro něj vrátí na konci.\nMurlocové Vile Fin lemují severní břeh: šupiny dropují všichni a kůže pro {npc:3549} Minor Oracles a Muckdwellers. Přímo na sever od {area:159} jsou na břehu Puddlejumpers a Minor Oracles (7–9) a žádní Muckdwellers (9–10) poblíž.",
	["Head west to the cave. The Young Night Web Spiders sit outside; the Night Web Spiders and the cocooned {npc:271961} are inside.\nCareful: A low-level character can die quickly if it pulls several Night Web Spiders in the cave at the same time."] = "Jdi na západ k jeskyni. Young Night Web Spiders sedí venku; Night Web Spiders a zakuklený {npc:271961} jsou uvnitř.\nPozor: Postava s nízkým levelem může rychle umřít, když v jeskyni pullne několik Night Web Spiders najednou.",
	["Heal and fortify {npc:12428}"] = "Vyléč a posil {npc:12428}",
	["Holland walks around the north side of {area:159}, a few steps from Dillinger."] = "Holland chodí po severní straně {area:159}, pár kroků od Dillingera.",
	["Level 6"] = "Level 6",
	["Listen to Leonid and {npc:246378}, then talk to him again"] = "Poslechni si Leonida a {npc:246378}, pak s ním promluv znovu",
	["Mindless Zombies"] = "Mindless Zombies",
	["Paladin: {quest:91285}"] = "Paladin: {quest:91285}",
	["Paladin: {quest:96899}"] = "Paladin: {quest:96899}",
	["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side. {npc:1661} wants their paws and wings: kill them as you meet them while you clear the skeletons."] = "Rattlecage Skeletons bloudí rozbořenými domy v severní polovině {area:154}. Young Scavengers a Duskbats se potulují všude kolem vesnice; Ragged Scavengers a Mangy Duskbats jsou na její východní straně. {npc:1661} chce jejich tlapy a křídla: zabíjej je, jak na ně narazíš, zatímco čistíš kostlivce.",
	["Still in the inn: from level 7 {npc:1500} on the ground floor and {npc:1521} upstairs offer their quests; below 7 they wait for the next {area:159} visit."] = "Pořád v hostinci: od levelu 7 nabízejí questy {npc:1500} v přízemí a {npc:1521} nahoře; pod 7 počkají na další návštěvu {area:159}.",
	["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "Dry Branches leží na zemi kolem jihozápadního okraje {area:159}.",
	["The next guide walks south from {area:159} into {zone:1421}."] = "Další návod jde z {area:159} na jih do {zone:1421}.",
	["The pumpkins grow in the Scarlet-held fields just north-west of the farmhouse.\nCareful: Farmers stand close to the pumpkins, so you can pull more than one at once. Scarlet mobs are found around the edges of the farm and a bit to the northwest. {npc:1936} (8, rare) walks the field."] = "Dýně rostou na polích ovládaných Scarlet kousek severozápadně od statku.\nPozor: Farmáři stojí blízko dýní, takže můžeš pullnout víc najednou. Scarlet moby najdeš kolem okrajů farmy a kousek na severozápad. Polem chodí {npc:1936} (8, rare).",
	["The {npc:246143}"] = "{npc:246143}",
	["Tirisfal Pumpkins"] = "Tirisfalské dýně",
	["Top up here to level 6 before the pumpkins: the Tirisfal Farmers and Scarlet Warriors in the fields are 6-7. The Decrepit Darkhounds (5-6) roam the hills just east of the farm."] = "Tady se dotáhni na level 6, než půjdeš na dýně: Tirisfal Farmers a Scarlet Warriors na polích mají 6–7. Decrepit Darkhounds (5–6) se toulají po kopcích kousek východně od farmy.",
	["Use the {item:286176} on five idle Deathguards around town"] = "Použij {item:286176} na pět nečinných Deathguardů kolem města",
	["Vile Fin Attackers"] = "Vile Fin Attackers",
	["Vile Fin Seers"] = "Vile Fin Seers",
	["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Jdi z {area:159} na jih k {area:153} a dolů do {area:1497}. {npc:4568} stojí v {object:36082}. Tábor Scarlet je kousek západně od ruin.",
	["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Jdi z {area:159} na jih k {area:153} a dolů do {area:1497}. {npc:5675} stojí v {object:36082}. Tábor Scarlet je kousek západně od ruin.",
	["West from {area:164} past {area:157} to the {area:16616}. Leonid stands just north of {npc:246389}'s camp.\n{npc:246389} and {npc:259190} camp at the forest's edge just south of Leonid. Every class can take both quests once {quest:96896} is handed in (level 10). They send you into the cellar under {area:16881}, the next stop."] = "Z {area:164} na západ kolem {area:157} do {area:16616}. Leonid stojí kousek severně od tábora {npc:246389}.\n{npc:246389} a {npc:259190} táboří na okraji lesa kousek jižně od Leonida. Každá třída si může vzít oba questy, jakmile je odevzdaný {quest:96896} (level 10). Pošlou tě do sklepa pod {area:16881}, což je další zastávka.",
	["grind on {npc:1547}"] = "grinduj na {npc:1547}",
	["{area:154}: kill these as you meet them"] = "{area:154}: zabíjej je, jak na ně narazíš",
	["{area:165}: kill these as you meet them"] = "{area:165}: zabíjej je, jak na ně narazíš",
	["{area:166}: kill these as you meet them"] = "{area:166}: zabíjej je, jak na ně narazíš",
	["{area:16881} is the hollow at the west edge of the glades, south-west of the {area:16616}. Go down into the big basement under the ruined house (only a floor and a few pillars left, not the two-storey house): the bottles lie on its floor among the Shadowvale Lurchers and Mystics."] = "{area:16881} je prohlubeň na západním okraji mýtin, jihozápadně od {area:16616}. Sestup do velkého sklepa pod zříceným domem (zbyla jen podlaha a pár sloupů, ne ten dvoupatrový dům): lahve leží na jeho podlaze mezi Shadowvale Lurchers a Mystics.",
	["{item:16333}, from {npc:1919}"] = "{item:16333}, od {npc:1919}",
	["{item:2839}, a rare drop"] = "{item:2839}, vzácný drop",
	["{item:3635}; inside"] = "{item:3635}; uvnitř",
	["{npc:10665} walks around {area:159}: look inside the circle on the map"] = "{npc:10665} chodí po {area:159}: hledej uvnitř kruhu na mapě",
	["{npc:10666} walks the long road west of {area:159}, past {area:166}, and back: the arrow follows his road west until you meet him."] = "{npc:10666} chodí po dlouhé cestě západně od {area:159}, kolem {area:166} a zpět: šipka sleduje jeho cestu na západ, dokud ho nepotkáš.",
	["{npc:10666}, the big abomination, walks the road from here east past {area:166} almost to {area:159}, and back: if he isn't at the arrow, follow the road east until you meet him. The {item:12737} grows along the road around him."] = "{npc:10666}, velká abominace, chodí po cestě odsud na východ kolem {area:166} skoro až k {area:159} a zpět: když není u šipky, jdi po cestě na východ, dokud ho nepotkáš. {item:12737} roste podél cesty kolem něj.",
	["{npc:12428} kneels by the north gate of {area:159}'s graveyard, on your way north. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Fortitude first does not count."] = "{npc:12428} klečí u severní brány hřbitova {area:159}, cestou na sever. Sešli na něj {spell:613} (Rank 2), pak {spell:1243}: když dáš Fortitude první, nepočítá se to.",
	["{npc:1495}'s camp"] = "tábor {npc:1495}",
	["{npc:1496} and {npc:1742} stand at the west end of {area:159}, where the road from Solliden comes in."] = "{npc:1496} a {npc:1742} stojí na západním konci {area:159}, kde přichází cesta ze Sollidenu.",
	["{npc:1499}, in the town hall"] = "{npc:1499}, na radnici",
	["{npc:1499}, inside"] = "{npc:1499}, uvnitř",
	["{npc:1500} and {npc:1521}"] = "{npc:1500} a {npc:1521}",
	["{npc:1500}, in the inn"] = "{npc:1500}, v hostinci",
	["{npc:1515}, in front of the inn"] = "{npc:1515}, před hostincem",
	["{npc:1518} is in the apothecary's house on the west side of the square, {npc:1515} in front of the inn with the Wanted poster beside him, {npc:1499} in the town hall on the square's north side. The inn comes last, in one go."] = "{npc:1518} je v lékárníkově domě na západní straně náměstí, {npc:1515} před hostincem s plakátem Wanted vedle sebe, {npc:1499} na radnici na severní straně náměstí. Hostinec přijde na řadu poslední, najednou.",
	["{npc:1518}, inside"] = "{npc:1518}, uvnitř",
	["{npc:1518}: for Renferrel at the {area:228}"] = "{npc:1518}: pro Renferrela u {area:228}",
	["{npc:1521}, upstairs"] = "{npc:1521}, nahoře",
	["{npc:1525} and Ravaged Corpses shamble through the fields just west of {area:159}; Decrepit Darkhounds roam there and on west along the road toward {npc:10666}. Johaan wants their blood, {npc:3549} their hides."] = "{npc:1525} a Ravaged Corpses se šourají po polích kousek západně od {area:159}; Decrepit Darkhounds se potulují tam a dál na západ po cestě směrem k {npc:10666}. Johaan chce jejich krev, {npc:3549} jejich kůže.",
	["{npc:1537} walks around here: look inside the circle on the map"] = "{npc:1537} chodí po okolí: hledej uvnitř kruhu na mapě",
	["{npc:1560}, in the inn"] = "{npc:1560}, v hostinci",
	["{npc:1569}, inside"] = "{npc:1569}, uvnitř",
	["{npc:1569}: the scroll for {npc:244808}"] = "{npc:1569}: svitek pro {npc:244808}",
	["{npc:1570}, in the church"] = "{npc:1570}, v kostele",
	["{npc:1655}; upstairs"] = "{npc:1655}; nahoře",
	["{npc:1661}, beside the church; inside"] = "{npc:1661}, vedle kostela; uvnitř",
	["{npc:1661}, inside"] = "{npc:1661}, uvnitř",
	["{npc:1667} stands at the south end of the Scarlet farm.\nCareful: He is flanked by two Scarlet guards, one a convert and the other an initiate, who may join the fight."] = "{npc:1667} stojí na jižním konci farmy Scarlet.\nPozor: Po bocích má dva strážce Scarlet, jednoho konvertitu a druhého zasvěcence, kteří se můžou přidat do boje.",
	["{npc:1675} walks around {area:164}: look inside the circle on the map"] = "{npc:1675} chodí po {area:164}: hledej uvnitř kruhu na mapě",
	["{npc:1738}, if you were below 10 on the last {area:159} visit"] = "{npc:1738}, pokud jsi byl při minulé návštěvě {area:159} pod 10",
	["{npc:1742}, beside Dillinger"] = "{npc:1742}, vedle Dillingera",
	["{npc:2114} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2114} ho vezme, až budeš mít dovednost {skill:182} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:2123}: for {npc:2129} in {area:159}"] = "{npc:2123}: pro {npc:2129} v {area:159}",
	["{npc:2129}, upstairs"] = "{npc:2129}, nahoře",
	["{npc:2132} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2132} ho vezme, až budeš mít dovednost {skill:171} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:2132}, inside"] = "{npc:2132}, uvnitř",
	["{npc:244808}, inside"] = "{npc:244808}, uvnitř",
	["{npc:246389} and {npc:259190}"] = "{npc:246389} a {npc:259190}",
	["{npc:265944}, at the inn's north end: Camping 101 asks you to learn it"] = "{npc:265944}, na severním konci hostince: Camping 101 chce, aby ses ji naučil",
	["{npc:267009} stands at the camp beside Linnea."] = "{npc:267009} stojí v táboře vedle Linney.",
	["{npc:267009} stands at {npc:1495}'s camp, on the road to the cult's farm."] = "{npc:267009} stojí v táboře {npc:1495}, na cestě k farmě kultu.",
	["{npc:275954}, on the top floor"] = "{npc:275954}, v nejvyšším patře",
	["{npc:3523} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3523} ho vezme, až budeš mít dovednost {skill:197} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:3523}, by the road west of {area:159}: {quest:97961}"] = "{npc:3523}, u cesty západně od {area:159}: {quest:97961}",
	["{npc:3549} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3549} ho vezme, až budeš mít dovednost {skill:165} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:4551}, the bat handler, on the way down from the Ruins"] = "{npc:4551}, správce netopýrů, po cestě dolů z Ruins",
	["{npc:5695} takes it once your {skill:333} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5695} ho vezme, až budeš mít dovednost {skill:333} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:5759} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5759} ho vezme, až budeš mít dovednost {skill:129} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{npc:6289} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6289} ho vezme, až budeš mít dovednost {skill:393} na 20: do té doby sbírej nebo vyráběj, návod mezitím pokračuje.",
	["{object:1661} is under the {area:153}, beside the zeppelin towers. {npc:5675} is in the {object:36082}: use the {item:6284} on the summoning circle beside him and defeat the voidwalker. {npc:4606} is in the {object:36070}. {npc:4568} is in the {object:36082} too."] = "{object:1661} je pod {area:153}, vedle zeppelinových věží. {npc:5675} je v {object:36082}: použij {item:6284} na vyvolávací kruh vedle něj a poraz voidwalkera. {npc:4606} je v {object:36070}. {npc:4568} je taky v {object:36082}.",
	["{object:178090} is in the {area:154} graveyard, beside the church."] = "{object:178090} je na hřbitově v {area:154}, vedle kostela.",
	["{object:37098} stands beside {npc:1662} at the camp's south end."] = "{object:37098} stojí vedle {npc:1662} na jižním konci tábora.",
	["{quest:90902}: the {npc:259377} lie around the church. Heal five of them with {spell:635}."] = "{quest:90902}: {npc:259377} leží kolem kostela. Vyleč pět z nich pomocí {spell:635}.",
	["{quest:91208}: the {npc:246143} fled into the hills west of the church, on the way to {area:155}."] = "{quest:91208}: {npc:246143} utekli do kopců západně od kostela, cestou do {area:155}.",
	["{zone:1420}: kill these as you meet them"] = "{zone:1420}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/legacy/legacy-challenges"] = {
	["Adventure: explore the world map"] = "Dobrodružství: prozkoumej mapu světa",
	["Adventure: {npc:16042}"] = "Dobrodružství: {npc:16042}",
	["Adventure: {quest:8999} (Alliance)"] = "Dobrodružství: {quest:8999} (Aliance)",
	["Adventure: {quest:9007} (Horde)"] = "Dobrodružství: {quest:9007} (Horda)",
	["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new 20-player Forever raid at the top of {zone:2482}, near Nordrassil, open from 9 December; its bosses are not in our data, so tick it off once all 13 are down."] = "Všech 13 bossů Hyjal Summit je bod. Hyjal Summit je nový raid Foreveru pro 20 hráčů na vrcholu {zone:2482} u Nordrassilu, otevřený od 9. prosince; jeho bossové nejsou v našich datech, tak to odškrtni, až jich padne všech 13.",
	["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new 10-player Forever raid beneath {zone:2482}, entered from {zone:2482}, {zone:1452} or {area:1216} and open from 9 December; its bosses are not in our data, so tick it off once all 8 are down."] = "Všech 8 bossů Barrow Deeps je bod. Barrow Deeps je nový raid Foreveru pro 10 hráčů pod {zone:2482}, vstup z {zone:2482}, {zone:1452} nebo {area:1216}, otevřený od 9. prosince; jeho bossové nejsou v našich datech, tak to odškrtni, až jich padne všech 8.",
	["City of Dalaran (Forever's, {zone:1416}): {npc:246020}"] = "City of Dalaran (Foreverův, {zone:1416}): {npc:246020}",
	["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "Povolání dají 27 bodů: každé povolání na 25, 45 a 60. Počítají se jednou za povolání v celém účtu, takže druhá postava povolání, které už máš vytažené, nic nepřidá; nové povolání ano. První postava na 25 obvykle odemkne samotný Legacy System.",
	["Classes: level 25"] = "Povolání: level 25",
	["Classes: level 45"] = "Povolání: level 45",
	["Classes: level 60"] = "Povolání: level 60",
	["Dire Maul East"] = "Dire Maul East",
	["Dire Maul North"] = "Dire Maul North",
	["Dire Maul West"] = "Dire Maul West",
	["Dungeons: level 15-25"] = "Dungeony: level 15–25",
	["Dungeons: level 26-45"] = "Dungeony: level 26–45",
	["Dungeons: level 46-60"] = "Dungeony: level 46–60",
	["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Evertally guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "Každá výrobní profese dá 3 body, na 150, 225 a 300. Ranky se počítají jednou za profesi v celém účtu. Sleduj návod Evertally „{skill:171} 1–300“ (Profese). Výrobní profese na 150 navíc odemkne Legacy System.",
	["Exalted with each of the four battleground factions is worth a point. Follow the Evertally Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation, Alterac Valley Reputation and Darkspear Islands Reputation (Forever's new battleground, open from level 30). The Diplomat Legacy perk increases reputation gains."] = "Exalted u každé ze čtyř frakcí battlegroundů má cenu jednoho bodu. Následuj reputační návody Evertally Warsong Gulch Reputation, Arathi Basin Reputation, Alterac Valley Reputation a Darkspear Islands Reputation (nový battleground Foreveru, otevřený od levelu 30). Výhoda Legacy Diplomat zvyšuje zisky reputace.",
	["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character. Forever's new zones are part of the map: the {zone:2548}, {zone:2652} and {zone:2482}, a level 60 zone."] = "Prozkoumání celé mapy světa je bod a může také odemknout Legacy System. Všechno musí být na stejné postavě. Nové zóny Foreveru jsou součástí mapy: {zone:2548}, {zone:2652} a {zone:2482}, zóna levelu 60.",
	["Follow the Evertally Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it. Exploration: Zephras Isle covers the Skyborne island; whether its map counts towards this challenge is not confirmed yet."] = "Následuj průzkumné návody Evertally: Exploration: Eastern Kingdoms 1-30, 30-45 a 45-60 a Exploration: Kalimdor 1-30, 30-45 a 45-60. Sledují každou oblast, jakmile ji objevíš. Exploration: Zephras Isle pokrývá ostrov Skyborne; jestli se jeho mapa do téhle výzvy počítá, zatím není potvrzené.",
	["Follow the Evertally guide \"{skill:164} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:164} 1–300“ (Profese).",
	["Follow the Evertally guide \"{skill:165} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:165} 1–300“ (Profese).",
	["Follow the Evertally guide \"{skill:197} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:197} 1–300“ (Profese).",
	["Follow the Evertally guide \"{skill:202} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:202} 1–300“ (Profese).",
	["Follow the Evertally guide \"{skill:333} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:333} 1–300“ (Profese).",
	["Legacy Challenges"] = "Legacy Challenges",
	["Level 45 with this character's class."] = "Level 45 s třídou této postavy.",
	["Level 60 with this character's class."] = "Level 60 s třídou této postavy.",
	["Lower {area:1583}"] = "Lower {area:1583}",
	["PvP: Field of Honor"] = "PvP: Field of Honor",
	["PvP: battleground reputations (Alliance)"] = "PvP: reputace z battlegroundů (Aliance)",
	["PvP: battleground reputations (Horde)"] = "PvP: reputace z battlegroundů (Horda)",
	["PvP: honor ranks"] = "PvP: honor ranky",
	["Raids: Barrow Deeps"] = "Raidy: Barrow Deeps",
	["Raids: Hyjal Summit"] = "Raidy: Hyjal Summit",
	["Raids: {npc:10184}"] = "Raidy: {npc:10184}",
	["Ranks 3, 7, 10, 13 and 14 are a point each. Evertally cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing."] = "Ranky 3, 7, 10, 13 a 14 mají každý jeden bod. Evertally zatím neumí přečíst tvůj nejvyšší rank, takže si každý odškrtni sám. Forever zatím podrobně nezveřejnil pravidla honoru pro dosažení ranku; v Classicu ranky plynou z týdenního pořadí v honoru a 13–14 vyžadují mnoho týdnů v nejvyšších příčkách.",
	["The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself."] = "Sezóna PvP Field of Honor má týdenní questy cesty; dokončení těch za týdny 4, 7 a 10 je po jednom bodu. Tyhle questy jsou ve Forever nové a nejsou v našich datech, takže si každý odškrtni sám.",
	["The final boss of every level 15-25 dungeon earns one point together. {area:2437} and Forever's {area:16919} (in {zone:1455}) count as one: either final boss does. Tick each boss off when you kill it, and check the in-game Legacy panel for the list.\nAlliance: the {area:153}'s entrance is in the ruins beside the {zone:1458}, among Horde guards: go with a group. {area:2437} is inside {zone:1454}: the {area:16919} counts for it. Horde: the {area:16919} is inside {zone:1455}: {area:2437} counts for it."] = "Poslední boss každého dungeonu pro level 15–25 dává dohromady jeden bod. {area:2437} a Foreverův {area:16919} (v {zone:1455}) se počítají jako jeden: stačí kterýkoli poslední boss. Každého bosse si po zabití odškrtni a seznam najdeš ve hře v panelu Legacy.\nAliance: Vchod do {area:153} je v ruinách vedle {zone:1458}, mezi hordími strážemi: jdi se skupinou. {area:2437} je uvnitř {zone:1454}: počítá se za něj {area:16919}. Horda: {area:16919} je uvnitř {zone:1455}: počítá se za něj {area:2437}.",
	["The final boss of every level 26-45 dungeon earns one point together. {area:16550} and {area:17780} (in the {zone:2548}) are new in Forever and not in our data: tick them off yourself."] = "Poslední boss každého dungeonu pro level 26–45 dává dohromady jeden bod. {area:16550} a {area:17780} (v {zone:2548}) jsou ve Foreveru nové a v našich datech nejsou: odškrtni si je sám.",
	["The final boss of every level 46-60 dungeon earns one point together. {area:16620}, {area:1216} and the {area:16985} are new in Forever and not in our data: tick them off yourself."] = "Poslední boss každého dungeonu pro level 46–60 dává dohromady jeden bod. {area:16620}, {area:1216} a {area:16985} jsou ve Foreveru nové a v našich datech nejsou: odškrtni si je sám.",
	["This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded."] = "Tenhle krok zatím neumí sám zkontrolovat celou mapu; stane se sledovaným cílem, jakmile budou zaznamenána id Legacy achievementů.",
	["Tradeskills: {skill:164}"] = "Profese: {skill:164}",
	["Tradeskills: {skill:165}"] = "Profese: {skill:165}",
	["Tradeskills: {skill:171}"] = "Profese: {skill:171}",
	["Tradeskills: {skill:197}"] = "Profese: {skill:197}",
	["Tradeskills: {skill:202}"] = "Profese: {skill:202}",
	["Tradeskills: {skill:333}"] = "Profese: {skill:333}",
	["Upper {area:1583}"] = "Horní {area:1583}",
	["{area:16919}: {npc:261319} (or {area:2437})"] = "{area:16919}: {npc:261319} (nebo {area:2437})",
	["{area:17732} (Forever's): {npc:260326}"] = "{area:17732} (verze Forever): {npc:260326}",
	["{area:2279}, Live side"] = "{area:2279}, živá strana",
	["{area:2279}, Undead side"] = "{area:2279}, nemrtvá strana",
	["{area:2437}: {npc:11519} (or {area:16919})"] = "{area:2437}: {npc:11519} (nebo {area:16919})",
	["{area:718} (appears after the {npc:3678}'s event)"] = "{area:718} (objeví se po události {npc:3678})",
	["{area:796}: Armory"] = "{area:796}: Armory",
	["{area:796}: Cathedral"] = "{area:796}: Cathedral",
	["{area:796}: Graveyard"] = "{area:796}: Graveyard",
	["{area:796}: Library"] = "{area:796}: Library",
	["{npc:16012} then offers your class's {quest:9007}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16012} pak nabídne {quest:9007} pro tvou třídu, poslední quest výzvy: vezme helmu a hrudní díl dungeonového setu tvé třídy a vylepší je.",
	["{npc:16013} then offers your class's {quest:8999}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16013} pak nabídne {quest:8999} pro tvou třídu, poslední quest výzvy: vezme helmu a hrudní díl dungeonového setu tvé třídy a vylepší je.",
	["{npc:16033} offers it once {quest:8996} is turned in"] = "{npc:16033} ho nabídne po odevzdání {quest:8996}",
	["{npc:16073}, inside Upper Blackrock Spire after Mea Culpa (no spawn in the data: the arrow leads to {npc:16033}'s {area:254})"] = "{npc:16073}, uvnitř Upper Blackrock Spire po Mea Culpa (v datech nemá spawn: šipka vede k {area:254} od {npc:16033})",
}
t.guides["forever/miscellaneous/cozy-sleeping-bag"] = {
	["A hundred paces north"] = "Sto kroků na sever",
	["A trail of hidden notes across both continents: the {item:211527} at the end, a 12-slot {item:221498} on the way."] = "Stopa skrytých poznámek přes oba kontinenty: na konci {item:211527}, po cestě {item:221498} s 12 místy.",
	["Along the coast to {zone:1436}"] = "Podél pobřeží do {zone:1436}",
	["At the gate in {area:1057} between Arathi and {area:287}, turn north and follow the wall on the {area:287} side to a fallen cart leaning against it. Jump up the cart and its ladder onto the wall, then over the rocks to the hidden camp. Some characters cannot fit under the cargo netting at the camp; another race or a smaller form gets through."] = "U brány v {area:1057} mezi Arathi a {area:287} zahni na sever a jdi podél zdi na straně {area:287} k převrácenému vozu opřenému o zeď. Vyskoč na vůz a po jeho žebříku na zeď, pak přes skály do skrytého tábora. Některé postavy se v táboře nevejdou pod síť s nákladem; jiná rasa nebo menší forma projde.",
	["Careful: off the dam's ledge you land in the river below it, in the {zone:1437}. Climb out on its west bank well before the waterfall at about 65,77: the fall kills. Then head north-west to the road and follow it north over {area:880} into Arathi, or hearth if your Hearthstone is set at {area:272}."] = "Pozor: Ze stupně hráze spadneš do řeky pod ní, v {zone:1437}. Vylez na západní břeh dlouho před vodopádem kolem 65,77: pád zabíjí. Pak jdi na severozápad k cestě a po ní na sever přes {area:880} do Arathi, nebo hearthni, pokud máš Hearthstone nastavený v {area:272}.",
	["Fallen cart"] = "Převrácený vůz",
	["From {object:3202} follow Stranglethorn's west coast north to {zone:1436}, swimming where the beach runs out. It is shorter than the jungle road north and keeps you clear of Stranglethorn's level 30+ beasts and of {zone:1431}."] = "Od {object:3202} jdi po západním pobřeží Stranglethornu na sever do {zone:1436}, kde pláž končí, plav. Je to kratší než džunglová silnice na sever a vyhneš se tak šelmám Stranglethornu levelu 30+ i {zone:1431}.",
	["Out of the river"] = "Ven z řeky",
	["Passing {area:272} on the way to {zone:1432}? Set your Hearthstone here: after the dam, it brings you back next to {area:1057} instead of the long walk through the {zone:1437} and Arathi. Skip this step to keep your Hearthstone where it is."] = "Jdeš kolem {area:272} cestou do {zone:1432}? Nastav si tu Hearthstone: po přehradě tě vrátí vedle {area:1057} místo dlouhé cesty přes {zone:1437} a Arathi. Přeskoč tento krok, pokud chceš Hearthstone nechat, kde je.",
	["Path into the hills"] = "Stezka do kopců",
	["Stonetalon from the north"] = "Stonetalon od severu",
	["Stranglethorn's west coast"] = "Západní pobřeží Stranglethornu",
	["The chain opens at level 14. A burned-out campfire in the southern {zone:1413}, with a nailed plank beside it."] = "Řetězec se otevírá na levelu 14. Vyhaslé ohniště na jihu {zone:1413} a vedle něj přibité prkno.",
	["The chain opens at level 14. A burned-out campfire in western {zone:1436}, with a nailed plank beside it."] = "Řetězec se otevírá na levelu 14. Vyhaslé ohniště v západní {zone:1436} a vedle něj přibité prkno.",
	["The dam in {zone:1432}"] = "Přehrada v {zone:1432}",
	["The figurine is on a ledge just below the top of the {area:146}, on its north face. Step off slowly; walking backwards keeps you from overshooting the ledge."] = "Soška je na římse kousek pod vrcholem {area:146}, na jeho severní straně. Slez pomalu; když půjdeš pozpátku, římsu nepřeskočíš.",
	["The hidden camp"] = "Skrytý tábor",
	["The next hideout is a small camp in the hills north-west of {area:460}, in the middle of the {zone:1442}. Leave the road where a path climbs west into the hills and follow it to the camp; the {object:424005} lies on a crate beside its tent."] = "Další úkryt je malý tábor v kopcích severozápadně od {area:460}, uprostřed {zone:1442}. Sejdi ze silnice tam, kde stezka stoupá na západ do kopců, a jdi po ní do tábora; {object:424005} leží na bedně vedle stanu.",
	["The note in the {zone:1413}"] = "Vzkaz v {zone:1413}",
	["The note in {zone:1436}"] = "Vzkaz v {zone:1436}",
	["The note's \"twin land\" is the {zone:1413}: the same burned-out campfire stands in the southern {zone:1413}."] = "„Dvojí země“ ze vzkazu je {zone:1413}: stejné vyhaslé ohniště stojí na jihu {zone:1413}.",
	["The note's \"twin land\" is {zone:1436}: the same burned-out campfire stands in western {zone:1436}."] = "„Dvojí země“ ze vzkazu je {zone:1436}: stejné vyhaslé ohniště stojí v západní {zone:1436}.",
	["Walk north through the camp and drop carefully down the steep slope to the {object:424012} on the ledge below. A missed jump only slides you down: hug the cliff and walk back up."] = "Jdi na sever přes tábor a opatrně seskoč po strmém svahu k {object:424012} na římse pod ním. Nepovedený skok tě jen sveze dolů: drž se útesu a vyjdi zpátky nahoru.",
	["West bank"] = "Západní břeh",
	["West bank, before the waterfall"] = "Západní břeh, před vodopádem",
	["{area:272} on the way"] = "{area:272} po cestě",
}
t.guides["forever/miscellaneous/library-books"] = {
	["At {area:118}, the dig in the middle of the {zone:1437}."] = "V {area:118}, vykopávkách uprostřed {zone:1437}.",
	["At {area:233}, the mage village in south-eastern Silverpine."] = "V {area:233}, vesnici mágů na jihovýchodě Silverpine.",
	["Beside a tent entrance in the troll village in south-eastern Arathi."] = "U vchodu do stanu v trollí vesnici na jihovýchodě Arathi.",
	["Cave mouth at {area:387}"] = "Ústí jeskyně u {area:387}",
	["Down the stairs at the {area:443} in northern {zone:1439}."] = "Dolů po schodech u {area:443} v severním {zone:1439}.",
	["Eight more books lie in level 55-60 zones; the mage trainers beside the librarians take them, not the librarians. {item:228141} lies on a table in the ruined keep on {area:2298}, above {area:2057} (outside the dungeon); {item:228132} at {area:199}."] = "Dalších osm knih leží v zónách levelu 55–60; berou je trenéři mágů vedle knihovníků, ne knihovníci. {item:228141} leží na stole ve zničené pevnosti na {area:2298}, nad {area:2057} (mimo dungeon); {item:228132} u {area:199}.",
	["From level 20, with 20 different books handed in, {npc:211033} offers {quest:79536}: {item:281634} or {item:281635}."] = "Od levelu 20, s 20 různými odevzdanými knihami, nabízí {npc:211033} {quest:79536}: {item:281634} nebo {item:281635}.",
	["From level 35, with 25 different books handed in, {npc:211033} offers the second {quest:79536}: {item:277254}, {item:277258} or {item:277260} (level 40 to equip)."] = "Od levelu 35, s 25 různými odevzdanými knihami, nabízí {npc:211033} druhý {quest:79536}: {item:277254}, {item:277258} nebo {item:277260} (nasadit od levelu 40).",
	["Halfway up the {area:91}, east of {area:87}. Nothing hostile inside."] = "V polovině cesty nahoru na {area:91}, východně od {area:87}. Uvnitř nic nepřátelského.",
	["Hand in the books so far. {npc:211022} keeps the library in the {object:36082}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Odevzdej dosavadní knihy. {npc:211022} spravuje knihovnu v {object:36082}. Quest ke každé knize nabízí, dokud ji máš v batohu: přijmi ho a odevzdej, jednu po druhé, ať máš volný quest log. Knihy, které jsi nenašel, přeskoč.",
	["Hand in the books so far. {npc:211033} keeps the library at the top of the Wizard's Sanctum in the {object:2101}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Odevzdej dosavadní knihy. {npc:211033} spravuje knihovnu na vrcholu Wizard's Sanctum v {object:2101}. Quest ke každé knize nabízí, dokud ji máš v batohu: přijmi ho a odevzdej, jednu po druhé, ať máš volný quest log. Knihy, které jsi nenašel, přeskoč.",
	["Hand in this part's books. {npc:211022} keeps the library in the {object:36082}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Odevzdej knihy z této části. {npc:211022} spravuje knihovnu v {object:36082}. Quest ke každé knize nabízí, dokud ji máš v batohu: přijmi ho a odevzdej, jednu po druhé, ať máš volný quest log. Knihy, které jsi nenašel, přeskoč.",
	["Hand in this part's books. {npc:211033} keeps the library at the top of the Wizard's Sanctum in the {object:2101}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Odevzdej knihy z této části. {npc:211033} spravuje knihovnu na vrcholu Wizard's Sanctum v {object:2101}. Quest ke každé knize nabízí, dokud ji máš v batohu: přijmi ho a odevzdej, jednu po druhé, ať máš volný quest log. Knihy, které jsi nenašel, přeskoč.",
	["In the troll ruins of {area:353}, in the south of the {zone:1425}."] = "V trollích ruinách {area:353}, na jihu {zone:1425}.",
	["Level 60 books: {area:1769}"] = "Knihy na level 60: {area:1769}",
	["Level 60 books: {area:2255}"] = "Knihy na level 60: {area:2255}",
	["Level 60 books: {area:254}"] = "Knihy na level 60: {area:254}",
	["Level 60 books: {zone:1422}"] = "Knihy na level 60: {zone:1422}",
	["Level 60 books: {zone:1423}"] = "Knihy na level 60: {zone:1423}",
	["Library Books"] = "Knihy z knihovny",
	["Lost books and scrolls all over the world: each pays experience at the library, and 10, 20 and 25 of them earn a necklace, a ring and an off-hand."] = "Ztracené knihy a svitky po celém světě: každá dá v knihovně zkušenosti a za 10, 20 a 25 z nich dostaneš náhrdelník, prsten a off-hand.",
	["The level 60 books: {npc:5497}"] = "Knihy pro level 60: {npc:5497}",
	["The level 60 books: {npc:7825}"] = "Knihy pro level 60: {npc:7825}",
	["The library: first books"] = "Knihovna: první knihy",
	["The library: first books (Horde)"] = "Knihovna: první knihy (Horda)",
	["The library: second books"] = "Knihovna: druhé knihy",
	["The library: second books (Horde)"] = "Knihovna: druhé knihy (Horda)",
	["The library: third books"] = "Knihovna: třetí knihy",
	["The library: third books (Horde)"] = "Knihovna: třetí knihy (Horda)",
	["The scrolls lie underground, in the cave below {area:387} by the {area:718} entrance, not inside the dungeon. Go in at the cave mouth in the oasis and follow the cave down; the arrow points at the scrolls from the surface."] = "Svitky leží pod zemí, v jeskyni pod {area:387} u vchodu do {area:718}, ne uvnitř dungeonu. Vejdi ústím jeskyně v oáze a jdi jeskyní dolů; šipka ukazuje na svitky z povrchu.",
	["The second {quest:79536}"] = "Druhý {quest:79536}",
	["The spellbook lies in the {area:2098}, the crypt in north-western {zone:1431}. Undead fill it; a corpse run works if you are low."] = "Kniha kouzel leží v {area:2098}, kryptě na severozápadě {zone:1431}. Je plná nemrtvých; když ti dochází zdraví, funguje i corpse run.",
	["Two books: one in a house at {area:20}, one at {area:108} (Alliance only)."] = "Dvě knihy: jedna v domě v {area:20}, jedna v {area:108} (jen Aliance).",
	["Two books: the manual in the control room at the top of the oil rig at the {area:382}, and the {object:407566} beside Gazlowe in {area:392}."] = "Dvě knihy: manuál v řídicí místnosti nahoře na ropné plošině v {area:382} a {object:407566} vedle Gazlowa v {area:392}.",
}
t.guides["forever/miscellaneous/stalk-with-the-earthmother"] = {
	["A one-hand blade or mace at 11 from {npc:205729}'s three tests in and around {zone:1456}, for a Tauren of any class."] = "Jednoruční čepel nebo palice na 11 za tři zkoušky {npc:205729} v {zone:1456} a okolí, pro Taurena jakéhokoli povolání.",
	["Back to {npc:205729} in {zone:1456}. He gives you the {item:206176} for his next test."] = "Zpět k {npc:205729} do {zone:1456}. Dá ti {item:206176} na další zkoušku.",
	["Back to {npc:205729}. He hands you the {item:206344} for the last test."] = "Zpět k {npc:205729}. Dá ti {item:206344} na poslední zkoušku.",
	["Buy a {item:6291} at the Auction House ({npc:8674}, north of the pool), or fish one yourself: {npc:3028} trains {skill:356} and {npc:3029} beside him sells the {item:6256} and a {item:6529}; the pool on the main mesa gives smallfish at any skill. Then use the {item:206344} on it, wherever you are."] = "Kup {item:6291} v aukci ({npc:8674}, severně od tůně), nebo si ji vylov sám: {npc:3028} učí {skill:356} a {npc:3029} vedle něj prodává {item:6256} a {item:6529}; tůň na hlavní mese dává smallfish při jakékoli dovednosti. Pak na ni použij {item:206344}, ať jsi kdekoli.",
	["Ride down the lift and south-east across {zone:1412} to the {area:360}. Put on the disguise, then open the carts of {object:403041} inside the mine and on the slope outside it; stay on the upper levels where you can, the lower tunnels are packed. Five charges."] = "Sjeď výtahem dolů a na jihovýchod přes {zone:1412} do {area:360}. Nasaď si převlek a otevři vozíky {object:403041} uvnitř dolu i na svahu před ním; kde to jde, drž se horních pater, spodní tunely jsou nacpané. Pět náloží.",
	["Take your weapon from {npc:205729}: the {item:277988} or the {item:278002}."] = "Vezmi si zbraň od {npc:205729}: {item:277988} nebo {item:278002}.",
	["Windfury Cones"] = "Windfury Cones",
	["Windfury Cones lie on the ground under the harpies' nest trees on {area:819}, north-west of {zone:1456}; the harpies do not drop them. The Windfury Sorceresses (level 9-10) and Matriarchs (10-11) there stand close together: pick the cones from the edges. Once you have eight, use the {item:206176} to grind them."] = "Windfury Cones leží na zemi pod stromy s hnízdy harpyjí na {area:819}, severozápadně od {zone:1456}; harpyje je nedropují. Windfury Sorceresses (level 9–10) a Matriarchs (10–11) tam stojí blízko u sebe: šišky sbírej z okrajů. Jakmile jich máš osm, rozdrť je pomocí {item:206176}.",
	["{item:206157}, from the {object:403041}"] = "{item:206157}, od {object:403041}",
}
