	["10 {item:12799} for {item:12773}: {item:12799} turns up in about one {object:175404}, {object:177388} or {object:180215} in 143: keep the ones you find while mining."] = "10 {item:12799} pro {item:12773}: {item:12799} se objeví zhruba v jednom z 143 {object:175404}, {object:177388} nebo {object:180215}: nech si, co najdeš při těžbě.",
	["142 {item:4304} for {item:7933} and {item:7945}: {skill:393}: beasts of level 38-50. Skin {npc:2729}, {npc:2730}, {npc:2732} and {npc:2734} here (level 38-50); the {skill:393} guide routes this."] = "142 {item:4304} pro {item:7933} a {item:7945}: {skill:393}: zvířata levelu 38–50. Stahuj {npc:2729}, {npc:2730}, {npc:2732} a {npc:2734} tady (level 38–50); trasu vede návod na {skill:393}.",
	["142 {item:4304} for {item:7933} and {item:7945}: {skill:393}: beasts of level 38-50. Skin {npc:5292}, {npc:5300}, {npc:5304}, {npc:5272}, {npc:5260}, {npc:5262}, {npc:5268}, {npc:5274}, {npc:5287}, {npc:5286} and {npc:5296} here (level 38-50); the {skill:393} guide routes this."] = "142 {item:4304} pro {item:7933} a {item:7945}: {skill:393}: zvířata levelu 38–50. Stahuj {npc:5292}, {npc:5300}, {npc:5304}, {npc:5272}, {npc:5260}, {npc:5262}, {npc:5268}, {npc:5274}, {npc:5287}, {npc:5286} a {npc:5296} tady (level 38–50); trasu vede návod na {skill:393}.",
	["168 {item:3575} for {spell:3501}: {skill:186}: smelt {item:2772}."] = "168 {item:3575} pro {spell:3501}: {skill:186}: přetav {item:2772}.",
	["19 {item:7909} for {quest:7654}: {item:7909} turns up in about one {object:2047} or {object:123309} in 500: keep the ones you find while mining."] = "19 {item:7909} pro {quest:7654}: {item:7909} se objeví zhruba v jednom z 500 {object:2047} nebo {object:123309}: nech si, co najdeš při těžbě.",
	["19 {item:7910} for {quest:7654}: {item:7910} turns up in about one {object:2047} or {object:123309} in 143: keep the ones you find while mining."] = "19 {item:7910} pro {quest:7654}: {item:7910} se objeví zhruba v jednom z 143 {object:2047} nebo {object:123309}: nech si, co najdeš při těžbě.",
	["195 {item:3859} for {item:6040}: {skill:186}: smelt {item:3575} and Coal."] = "195 {item:3859} pro {item:6040}: {skill:186}: přetav {item:3575} a Coal.",
