	["100 {item:2841} for {item:6533} and {spell:3953}: {skill:186}: smelt {item:2840} and {item:3576}."] = "100 {item:2841} pro {item:6533} a {spell:3953}: {skill:186}: přetav {item:2840} a {item:3576}.",
