	["156 {item:12359} for {item:15994} and {item:16000}: {skill:186}: smelt {item:10620}."] = "156 {item:12359} pro {item:15994} a {item:16000}: {skill:186}: přetav {item:10620}.",
	["19 {item:2319} for {spell:3953}: {skill:393}: beasts of level 18-30. Skin {npc:2248}, {npc:2356}, {npc:2385}, {npc:2351}, Snapjaw, {npc:2384} and {npc:2354} here (level 18-30); the {skill:393} guide routes this."] = "19 {item:2319} pro {spell:3953}: {skill:393}: zvířata levelu 18–30. Stahuj {npc:2248}, {npc:2356}, {npc:2385}, {npc:2351}, Snapjaw, {npc:2384} a {npc:2354} tady (level 18–30); trasu vede návod na {skill:393}.",
	["19 {item:2319} for {spell:3953}: {skill:393}: beasts of level 18-30. Skin {npc:3809}, {npc:3810}, {npc:3818}, {npc:3823}, {npc:3811} and {npc:3817} here (level 18-30); the {skill:393} guide routes this."] = "19 {item:2319} pro {spell:3953}: {skill:393}: zvířata levelu 18–30. Stahuj {npc:3809}, {npc:3810}, {npc:3818}, {npc:3823}, {npc:3811} a {npc:3817} tady (level 18–30); trasu vede návod na {skill:393}.",
	["19 {item:2592} for {spell:3953}: humanoids of level 15-30 drop it. Keep what you loot as you level, or take it from your bank."] = "19 {item:2592} pro {spell:3953}: dropují ho humanoidi levelu 15–30. Nech si, co nalootuješ při levelování, nebo si ho vezmi z banky.",
	["19 {item:3860} for {item:10512}: {skill:186}: smelt {item:3858}."] = "19 {item:3860} pro {item:10512}: {skill:186}: přetav {item:3858}.",
	["2 {item:2842} for {spell:3950}: {skill:186}: smelt {item:2775}."] = "2 {item:2842} pro {spell:3950}: {skill:186}: přetav {item:2775}.",
	["212 {item:7912} for {item:10512} and {item:10513}: {skill:186}: {object:2040} (skill 175) in {zone:1425} (40-50), {zone:1444} (40-50) and {zone:1447} (45-55). The densest cluster of {object:2040} in {zone:1425} is marked."] = "212 {item:7912} pro {item:10512} a {item:10513}: {skill:186}: {object:2040} (dovednost 175) v {zone:1425} (40–50), {zone:1444} (40–50) a {zone:1447} (45–55). Nejhustší výskyt {object:2040} v {zone:1425} je označený.",
	["212 {item:7912} for {item:10512} and {item:10513}: {skill:186}: {object:2040} (skill 175) in {zone:1443} (30-40), {zone:1425} (40-50) and {zone:1444} (40-50). The densest cluster of {object:2040} in {zone:1443} is marked."] = "212 {item:7912} pro {item:10512} a {item:10513}: {skill:186}: {object:2040} (dovednost 175) v {zone:1443} (30–40), {zone:1425} (40–50) a {zone:1444} (40–50). Nejhustší výskyt {object:2040} v {zone:1443} je označený.",
	["24 {item:14047} for {item:15994}: humanoids of level 45-60 drop it. Keep what you loot as you level, or take it from your bank."] = "24 {item:14047} pro {item:15994}: dropují ho humanoidi levelu 45–60. Nech si, co nalootuješ při levelování, nebo si ho vezmi z banky.",
	["27 {item:2838} for {spell:3945}: {skill:186}: {object:1735} (skill 125). The densest cluster of {object:1735} in {zone:1413} is marked."] = "27 {item:2838} pro {spell:3945}: {skill:186}: {object:1735} (dovednost 125). Nejhustší výskyt {object:1735} v {zone:1413} je označený.",
