	["27 {item:2838} for {spell:3945}: {skill:186}: {object:1735} (skill 125). The densest cluster of {object:1735} in {zone:1440} is marked."] = "27 {item:2838} pro {spell:3945}: {skill:186}: {object:1735} (dovednost 125). Nejhustší výskyt {object:1735} v {zone:1440} je označený.",
	["31 {item:2836} for {item:6533}: {skill:186}: {object:1732} (skill 65) in {zone:1413} (10-25), {zone:1440} (18-30) and {zone:1424} (20-30). The densest cluster of {object:1732} in {zone:1440} is marked."] = "31 {item:2836} pro {item:6533}: {skill:186}: {object:1732} (dovednost 65) v {zone:1413} (10–25), {zone:1440} (18–30) a {zone:1424} (20–30). Nejhustší výskyt {object:1732} v {zone:1440} je označený.",
	["31 {item:2836} for {item:6533}: {skill:186}: {object:1732} (skill 65) in {zone:1432} (10-20), {zone:1440} (18-30) and {zone:1424} (20-30). The densest cluster of {object:1732} in {zone:1432} is marked."] = "31 {item:2836} pro {item:6533}: {skill:186}: {object:1732} (dovednost 65) v {zone:1432} (10–20), {zone:1440} (18–30) a {zone:1424} (20–30). Nejhustší výskyt {object:1732} v {zone:1432} je označený.",
