	["{skill:197} 225-300: Auction House"] = "{skill:197} 225–300: aukce",
	["{skill:197} 225-300: vendor goods"] = "{skill:197} 225–300: zboží od obchodníků",
	["{skill:197} 75-150: Auction House"] = "{skill:197} 75–150: aukce",
