	["{skill:197} recipes at 15"] = "recepty {skill:197} na 15",
	["{skill:197} recipes at 170"] = "recepty {skill:197} na 170",
	["{skill:197} recipes at 197"] = "recepty {skill:197} na 197",
	["{spell:2387} to 15"] = "{spell:2387} na 15",
