	["{npc:13776}: assault a graveyard, 100"] = "{npc:13776}: zaútoč na hřbitov, 100",
	["{npc:13777}: assault a graveyard, 100"] = "{npc:13777}: zaútoč na hřbitov, 100",
	["{npc:13816} by the gate wants {npc:11946} dead: win a game in which your team kills him. Then he lets you pick a weapon ({quest:8271})."] = "{npc:13816} u brány chce mrtvého {npc:11946}: vyhraj hru, ve které ho tvůj tým zabije. Pak tě nechá vybrat si zbraň ({quest:8271}).",
	["{npc:13817} by the gate wants {npc:11948} dead: win a game in which your team kills him. Then he lets you pick a weapon ({quest:8272})."] = "{npc:13817} u brány chce mrtvého {npc:11948}: vyhraj hru, ve které ho tvůj tým zabije. Pak tě nechá vybrat si zbraň ({quest:8272}).",
	["{npc:15350}: 100 for 3 marks"] = "{npc:15350}: 100 za 3 marky",
	["{npc:15350}: For Great Honor"] = "{npc:15350}: For Great Honor",
	["{npc:15350}: {quest:8369} again, 100 for 3 marks"] = "{npc:15350}: znovu {quest:8369}, 100 za 3 marky",
	["{npc:15351}: 100 for 3 marks"] = "{npc:15351}: 100 za 3 marky",
	["{npc:15351}: Concerted Efforts"] = "{npc:15351}: Concerted Efforts",
	["{npc:15351}: {quest:8375} again, 100 for 3 marks"] = "{npc:15351}: znovu {quest:8375}, 100 za 3 marky",
	["{quest:7161}: the {item:17850} in {area:3337}, 100"] = "{quest:7161}: {item:17850} v {area:3337}, 100",
	["{quest:7162}: the {item:17849} in {area:3058}, 100"] = "{quest:7162}: {item:17849} v {area:3058}, 100",
