	["{npc:15126}: Honored rewards"] = "{npc:15126}: odměny za Honored",
	["{npc:15126}: Revered rewards"] = "{npc:15126}: odměny za Revered",
	["{npc:15127}: Exalted rewards"] = "{npc:15127}: odměny za Exalted",
	["{npc:15127}: Friendly rewards"] = "{npc:15127}: odměny za Friendly",
	["{npc:15127}: Honored rewards"] = "{npc:15127}: odměny za Honored",
	["{npc:15127}: Revered rewards"] = "{npc:15127}: odměny za Revered",
	["{npc:15350}: 50 reputation for 3 marks"] = "{npc:15350}: 50 reputace za 3 marky",
	["{npc:15350}: three marks, 100"] = "{npc:15350}: tři marky, 100",
	["{npc:15350}: {quest:8370} again, 50 reputation for 3 marks"] = "{npc:15350}: znovu {quest:8370}, 50 reputace za 3 marky",
	["{npc:15351}: 50 reputation for 3 marks"] = "{npc:15351}: 50 reputace za 3 marky",
	["{npc:15351}: three marks, 100"] = "{npc:15351}: tři marky, 100",
