	["Gelkis: {npc:5397} and {npc:253713}"] = "Gelkis: {npc:5397} a {npc:253713}",
	["Gelkis: {npc:5397} sends you to the valley"] = "Gelkis: {npc:5397} tě posílá do údolí",
