	["Gelkis: {quest:1373}"] = "Gelkis: {quest:1373}",
	["Gelkis: {quest:93041}"] = "Gelkis: {quest:93041}",
	["Gelkis: {quest:93045}"] = "Gelkis: {quest:93045}",
	["Gelkis: {quest:93122}"] = "Gelkis: {quest:93122}",
	["Gently Cursed Bones: Undead Ravagers"] = "Gently Cursed Bones: Undead Ravagers",
	["Magram: back to {npc:253851}"] = "Magram: zpátky k {npc:253851}",
	["Magram: the Kolkar camps"] = "Magram: tábory Kolkarů",
	["Magram: the heart of the valley"] = "Magram: srdce údolí",
	["Magram: the quilboar"] = "Magram: quilboarové",
	["Magram: the valley's mouth"] = "Magram: ústí údolí",
