t.guides["forever/reputation/nightclaw-druids"] = {
	["1000 reputation"] = "1000 reputace",
	["48 {skill:164}, {skill:165} and {skill:197} patterns"] = "48 vzorů {skill:164}, {skill:165} a {skill:197}",
	["500 reputation"] = "500 reputace",
	["Back to {area:16638}"] = "Zpět do {area:16638}",
	["Back to {npc:254151} inside the den. Ten ears for 1000 reputation and a green piece: leather gloves, cloth pants or mail boots. {npc:254151} then takes ears five at a time, for 1000 each, as often as you like, up to level 18; in Classic the pay drops from level 19 and is 200 from level 22. The Legacy perk Diplomat adds up to 10% to every gain."] = "Zpět k {npc:254151} do doupěte. Deset uší za 1000 reputace a zelený kus: kožené rukavice, látkové kalhoty nebo kroužkové boty. {npc:254151} pak bere uši po pěti, po 1000, kolikrát chceš, až do levelu 18; v Classicu odměna od levelu 19 klesá a od 22 je 200. Legacy perk Diplomat přidá ke každému zisku až 10 %.",
	["Ears at the {area:16629}"] = "Uši u {area:16629}",
	["Exalted opens the {item:280363}, green cloth shoulders for level 15, for 8s 16c."] = "Exalted otevře {item:280363}, zelená látková ramena pro level 15, za 8s 16c.",
	["Friendly to Honored"] = "Z Friendly na Honored",
	["Head north into the {area:16631}. {npc:257944} holds the druids' camp in its north-east."] = "Jdi na sever do {area:16631}. {npc:257944} drží tábor druidů na jeho severovýchodě.",
	["Honored opens the chest and leg patterns (skill 60, 12s 50c): Skyforged chainmail and legguards, Gustwoven harness and trousers, Windraveled jerkin and pants, Stormsewn vest and leggings. Revered is 12000 more: 12 turn-ins (60 ears, about 160 cultist kills at the Shrine) up to level 18, 60 turn-ins (300 ears) from level 22."] = "Honored odemyká střihy na hrudní a nožní části (dovednost 60, 12s 50c): Skyforged chainmail a legguards, Gustwoven harness a trousers, Windraveled jerkin a pants, Stormsewn vest a leggings. Do Revered je to dalších 12 000: 12 odevzdání (60 uší, zhruba 160 zabitých kultistů u Shrine) do levelu 18, 60 odevzdání (300 uší) od levelu 22.",
	["Honored to Revered"] = "Z Honored do Revered",
	["Nightclaw Druids Reputation"] = "Reputace Nightclaw Druids",
	["Revered opens the {item:280347}, a companion pet, for 50s. Exalted is 21000 more: 21 turn-ins (105 ears, about 280 kills) up to level 18, 105 turn-ins (525 ears) from level 22."] = "Revered otevře {item:280347}, společníka (pet), za 50s. Na Exalted je to dalších 21 000: 21 odevzdání (105 uší, asi 280 zabití) do levelu 18, 105 odevzdání (525 uší) od levelu 22.",
	["Revered to Exalted"] = "Z Revered na Exalted",
	["The Al'Aketh Footsoldiers and Stormchasers camp just north of {npc:257944} and drop the Bloody Heirlooms (and ears, about one kill in four). The Shadowgale Shrieklings flying west of her drop the feathers; the {item:265105} grows on the trees along the stream west of her."] = "Al'Aketh Footsoldiers a Stormchasers táboří kousek severně od {npc:257944} a dropují Bloody Heirlooms (a uši, asi z jednoho zabití ze čtyř). Shadowgale Shrieklings létající západně od ní dropují pera; {item:265105} roste na stromech podél potoka západně od ní.",
	["The storyline and {npc:254151}'s first quest leave you at Friendly with 2100 to spare. Honored is 3900 more: four turn-ins of five ears up to level 18, twenty from level 22. Friendly opens 32 of {npc:254151}'s patterns, in two colours, Cloudy and Azure: Blacksmithing Skyforged Wristguards and Chain (skill 50, 9s 50c), Gauntlets and Greaves (55, 11s); Leatherworking Gustwoven and Windraveled bracers and belts (50) and gloves and boots (55); Tailoring Stormsewn Cuffs and Cord (50), Handwraps and Shoes (55). They bind when you buy them, so buy them on the crafter."] = "Příběhová linie a první quest od {npc:254151} tě dostanou na Friendly s 2 100 navíc. Honored je o 3 900 dál: čtyři odevzdání po pěti uších do levelu 18, po dvaceti od levelu 22. Friendly otevře 32 vzorů od {npc:254151} ve dvou barvách, Cloudy a Azure: Blacksmithing Skyforged Wristguards a Chain (dovednost 50, 9s 50c), Gauntlets a Greaves (55, 11s); Leatherworking Gustwoven a Windraveled náramky a opasky (50) a rukavice a boty (55); Tailoring Stormsewn Cuffs a Cord (50), Handwraps a Shoes (55). Při koupi se vážou, takže je kupuj na postavě, která bude vyrábět.",
	["The {item:280363}"] = "{item:280363}",
	["{item:280347}, 50s"] = "{item:280347}, 50s",
	["{quest:93459}: 1000 reputation, handed in from {npc:254151}'s window"] = "{quest:93459}: 1 000 reputace, odevzdává se u okna {npc:254151}",
}
t.guides["forever/reputation/orgrimmar"] = {
	["A {npc:3118} may drop a {item:277661}: use it to start {quest:97281}. Once you hand that in, {npc:3293} offers {quest:97282}."] = "{npc:3118} může dropnout {item:277661}: použij ho na začátek {quest:97281}. Až ho odevzdáš, {npc:3293} nabídne {quest:97282}.",
	["Around the Crossroads"] = "Okolí Crossroads",
	["Blackrock Mountain, with a group"] = "Blackrock Mountain, se skupinou",
	["Boars, weapons and peons"] = "Kanci, zbraně a peoni",
	["Exalted with {faction:76}"] = "Exalted u {faction:76}",
	["Find {npc:8578}'s camp"] = "Najdi tábor {npc:8578}",
	["Fly to {area:1237} in western {zone:1447}: on Forever, {quest:3505} starts with {npc:8576} there, with no letter from {npc:4485} first. The {quest:3505} quests are level 53 and pay in full at 60 too, as every quest does in Forever. {npc:8576} sends you north-east to the blood elf camp on the bluffs of the northern peninsula."] = "Leť do {area:1237} v západním {zone:1447}: ve Foreveru začíná {quest:3505} tam u {npc:8576}, bez předchozího dopisu od {npc:4485}. Questy {quest:3505} jsou levelu 53 a v plné výši platí i na 60, jako každý quest ve Foreveru. {npc:8576} tě pošle na severovýchod do tábora krvavých elfů na útesech severního poloostrova.",
	["Forever pays it in full at any level. {quest:819} lies on the ground at one of several spots in the central and northern {zone:1413}, most of them by the roads around the Crossroads; once someone takes it, it turns up at another. {npc:3292} in {area:392} pays 250 {faction:76} reputation for the keg and its first filling, then 50 for every filling after, as often as you like."] = "Forever ho platí v plné výši na jakémkoli levelu. {quest:819} leží na zemi na jednom z několika míst ve středním a severním {zone:1413}, většinou u cest kolem Crossroads; jakmile ho někdo vezme, objeví se jinde. {npc:3292} v {area:392} platí 250 reputace {faction:76} za soudek a jeho první naplnění, pak 50 za každé další, kolikrát chceš.",
	["Forever pays these old quests in full at any level. The {area:363} is the best of them: about 1,400 {faction:76} and 1,400 Darkspear reputation in 25 minutes. {npc:3143} waits in the Den, the big hut; {npc:10176} stands outside it."] = "Forever tyhle staré questy platí v plné výši na jakémkoli levelu. {area:363} je z nich nejlepší: asi 1 400 reputace {faction:76} a 1 400 Darkspear za 25 minut. {npc:3143} čeká v Den, velké chýši; {npc:10176} stojí před ní.",
	["Forever pays these old quests in full at any level. {area:362} and north {zone:1411}: about 1,800 {faction:76} and 1,650 Darkspear reputation in 80 minutes. {npc:3142} and {npc:3139} stand in the middle of the town, {npc:3191} by the barracks, {npc:3147} and {npc:266940} at the edges."] = "Forever tyhle staré questy platí v plné výši na jakémkoli levelu. {area:362} a severní {zone:1411}: asi 1 800 reputace {faction:76} a 1 650 Darkspear za 80 minut. {npc:3142} a {npc:3139} stojí uprostřed města, {npc:3191} u kasáren, {npc:3147} a {npc:266940} na okrajích.",
	["Forever pays these old quests in full at any level. {area:367} and the {area:368}: about 700 {faction:76} and 650 Darkspear reputation in 25 minutes. {npc:3188} and {npc:3304} stand by the huts, {npc:3194} near the water, {npc:7953} south of the village."] = "Forever tyhle staré questy platí v plné výši na jakémkoli levelu. {area:367} a {area:368}: asi 700 reputace {faction:76} a 650 Darkspear za 25 minut. {npc:3188} a {npc:3304} stojí u chýší, {npc:3194} u vody, {npc:7953} jižně od vesnice.",
	["Forever pays these old quests in full at any level. {area:380}: about 1,500 {faction:76} reputation in 70 minutes, {faction:76}'s only. {quest:860}, {npc:3464}, {npc:3429}, {npc:3449} and {npc:267310} stand in the town, {npc:3432} by the inn."] = "Forever tyhle staré questy platí v plné výši na jakémkoli levelu. {area:380}: asi 1 500 reputace {faction:76} za 70 minut, jen pro {faction:76}. {quest:860}, {npc:3464}, {npc:3429}, {npc:3449} a {npc:267310} stojí ve městě, {npc:3432} u hostince.",
	["Forever pays these old quests in full at any level. {quest:5726}: 400 {faction:76} reputation in 20 minutes, with a run through {area:2437} that a level 60 clears alone."] = "Forever tyhle staré questy platí v plné výši na jakémkoli levelu. {quest:5726}: 400 reputace {faction:76} za 20 minut, s průchodem {area:2437}, který postava levelu 60 vyčistí sama.",
	["From here it is cloth. Wool, Silk and Mageweave must all be handed in before {npc:14726} offers the {item:14047} donation, and {quest:7832} needs the {item:14047} donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, {item:14047} 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey."] = "Odsud je to látka. Wool, Silk a Mageweave musí být odevzdané všechny, než {npc:14726} nabídne dar {item:14047}, a {quest:7832} potřebuje dar {item:14047}. Kup látku v aukci nebo ji farmi: dropují ji humanoidi, Wool od levelu 15 do 25, Silk 25 až 40, Mageweave 40 až 50, {item:14047} od 50 výš. Na 60 farmi moby levelu 52 a výš: nižší jsou šedí.",
	["From now on Drohn takes 5 Lightning Glands, a {item:4897} and a {item:4896} for 50, as often as you like. The {npc:3238} thunder lizards (a gland about every other kill), the Greater Thunderhawks and the kodos south of {area:378} drop them. Gather several sets before you head back to {area:392}."] = "Od teď bere Drohn 5 Lightning Glands, {item:4897} a {item:4896} za 50, kolikrát chceš. Dropují je thunder lizardi {npc:3238} (žláza zhruba každé druhé zabití), Greater Thunderhawks a kodové jižně od {area:378}. Než se vrátíš do {area:392}, nasbírej několik sad.",
	["Go back into the cave and keep to the right-hand wall all the way, over a small stream, to {npc:3183} on a ledge above a pool."] = "Vrať se do jeskyně a drž se celou cestu pravé stěny, přes malý potůček, až k {npc:3183} na římse nad jezírkem.",
	["Honored to Revered is 12,000: 240 hand-ins, 4,800 {item:14047}. The Auction House price of a stack decides whether to farm or buy."] = "Z Honored do Revered je to 12 000: 240 odevzdání, 4 800 {item:14047}. Jestli farmit, nebo kupovat, rozhodne cena stacku v aukci.",
	["Lions, plainstriders and a thunder lizard"] = "Lvi, plainstrideři a thunder lizard",
	["Mageweave: the Jadefire satyrs in southern {zone:1448} and the Dunemaul ogres in {zone:1446} drop it about one kill in three, or buy it."] = "Mageweave: satyrové Jadefire v jižní {zone:1448} a ogři Dunemaul v {zone:1446} ho dropují zhruba z každého třetího zabití, nebo ho kup.",
	["Makrura and surf crawlers walk the beaches east and south of Sen'jin. The {quest:97223} is east of the village. The Ridgeshade spiders are along the road south of {area:362} and north-east of the Den."] = "Makrury a surf crawleři chodí po plážích východně a jižně od Sen'jinu. {quest:97223} je východně od vesnice. Pavouci Ridgeshade jsou podél cesty jižně od {area:362} a severovýchodně od Denu.",
	["Moontouched Owlbeasts north of {area:2255} and south of it."] = "Moontouched Owlbeasts severně od {area:2255} a jižně od ní.",
	["Most Berserk Owlbeasts are north of {area:2255}. A {item:12558} may drop from the owlbeasts now: use it to start {quest:4882}."] = "Většina Berserk Owlbeasts je severně od {area:2255}. Z owlbeastů teď může padnout {item:12558}: použij ho a začni {quest:4882}.",
	["Orgrimmar Reputation"] = "Reputace u Orgrimmaru",
	["Prowlers, {npc:3452} and {quest:881}"] = "Prowlers, {npc:3452} a {quest:881}",
	["Raging Owlbeasts north-west of {area:2255}, Ragged Owlbeasts further west."] = "Raging Owlbeasts severozápadně od {area:2255}, Ragged Owlbeasts dál na západ.",
	["Revered to Exalted is 21,000: 420 hand-ins, 8,400 {item:14047}. Raid heads pay too: The Lord of Blackrock (Nefarian) 200 to every Horde city and Victory for the Horde (Onyxia) 400 to {faction:76}. At Exalted, {npc:3362} in the {object:172958} sells the wolves to every Horde race: 20 gold for a level 40 wolf, 200 gold for a swift wolf at level 60 (Forever's prices); in Classic other races needed Exalted to buy them."] = "Z Revered na Exalted je to 21 000: 420 odevzdání, 8 400 {item:14047}. Platí i hlavy z raidů: The Lord of Blackrock (Nefarian) 200 u každého města Hordy a Victory for the Horde (Onyxia) 400 u {faction:76}. Na Exalted prodává {npc:3362} v {object:172958} vlky všem rasám Hordy: 20 goldů za vlka na level 40, 200 goldů za swift vlka na level 60 (ceny Foreveru); v Classicu ostatní rasy potřebovaly ke koupi Exalted.",
	["Swim to the largest of the {area:368}, south-east of the village. {quest:826}, the idols and the skulls at the circle of power are all there; the Durotar Tigers prowl the smaller islands."] = "Doplav na největší z {area:368}, jihovýchodně od vesnice. {quest:826}, idoly i lebky u kruhu moci jsou všechny tam; Durotar Tigers slídí po menších ostrovech.",
	["The Charged Thunder Lizard Organs come from the thunder lizards on {area:369}, just west of {npc:3293}."] = "Charged Thunder Lizard Organs jsou z hromových ještěrů na {area:369}, kousek západně od {npc:3293}.",
	["The coast and the road"] = "Pobřeží a silnice",
	["The keep is south of {area:362} on the coast. {npc:3192} is in the keep's only building; his key opens {object:3239} on the roof, and the {item:4881} inside starts {quest:830}. The sailors and marines drop the {item:4870}; the {item:275713}, Battleaxe and Shield lie outside the keep."] = "Pevnost je na pobřeží jižně od {area:362}. {npc:3192} je v jediné budově pevnosti; jeho klíč otevírá {object:3239} na střeše a {item:4881} uvnitř spouští {quest:830}. {item:4870} dropují námořníci a mariňáci; {item:275713}, Battleaxe a Shield leží před pevností.",
	["The training weapons lie on the ground in the Den and among the boars to the north. For the peons: target a sleeping {npc:10556} and use the {item:16114} on it."] = "Cvičné zbraně leží na zemi v Den a mezi kanci na severu. Na peony: zaměř spícího {npc:10556} a použij na něj {item:16114}.",
	["The wreck"] = "Vrak",
	["The wrecked ship lies in the shallows east of {area:372}. Open the Gnomish Toolboxes."] = "Vrak lodi leží na mělčině východně od {area:372}. Otevři Gnomish Toolboxes.",
	["The {area:368}"] = "{area:368}",
	["These quests are level 56 to 59, so they pay in full at 60. {npc:10306} stands at {area:1997}; the owlbeasts live in {zone:1452}, through the Timbermaw tunnel north of {zone:1448}."] = "Tyhle questy mají level 56 až 59, takže na 60 dávají plnou odměnu. {npc:10306} stojí v {area:1997}; owlbeasti žijí ve {zone:1452}, za tunelem Timbermaw severně od {zone:1448}.",
	["Wake {npc:10556}"] = "Probuď {npc:10556}",
	["the {object:151286}"] = "{object:151286}",
	["{area:1237} and {faction:76}"] = "{area:1237} a {faction:76}",
	["{area:1997}: hand in"] = "{area:1997}: odevzdej",
	["{area:1997}: hand in again"] = "{area:1997}: znovu odevzdej",
	["{area:1997}: last hand-in"] = "{area:1997}: poslední odevzdání",
	["{area:2437} opens off the {object:172960}. {npc:11518} and {npc:11519} wait at the far end."] = "{area:2437} se otevírá z {object:172960}. {npc:11518} a {npc:11519} čekají na vzdáleném konci.",
	["{area:340} in the {zone:1418} hands out {faction:76} quests for {area:1584} and {area:1583}, all level 58 to 60 and paid in full: Precarious Predicament and Operation: Death to Angerforge (150 each), {quest:4724} and {item:12652} (100 each), {quest:4903} (150), {npc:3144}'s Wisdom (100) and For The Horde! (Rend's head, 200 to every Horde city). These are dungeon quests: take them when your group goes."] = "{area:340} v {zone:1418} rozdává questy {faction:76} do {area:1584} a {area:1583}, všechny level 58 až 60 a plně placené: Precarious Predicament a Operation: Death to Angerforge (po 150), {quest:4724} a {item:12652} (po 100), {quest:4903} (150), {npc:3144}'s Wisdom (100) a For The Horde! (Rendova hlava, 200 u každého hordského města). Jsou to questy do dungeonů: vezmi je, až půjde tvoje skupina.",
	["{area:362} (optional hub)"] = "{area:362} (nepovinný uzel)",
	["{area:362}: Sen'jin hand-ins"] = "{area:362}: odevzdání v Sen'jin",
	["{area:362}: hand in"] = "{area:362}: odevzdej",
	["{area:363} (optional hub)"] = "{area:363} (nepovinný uzel)",
	["{area:364}: hand in"] = "{area:364}: odevzdej",
	["{area:364}: hand in again"] = "{area:364}: znovu odevzdej",
	["{area:367} (optional hub)"] = "{area:367} (nepovinný uzel)",
	["{area:367}: hand in"] = "{area:367}: odevzdej",
	["{area:369} and {area:410}"] = "{area:369} a {area:410}",
	["{area:380} (optional hub)"] = "{area:380} (nepovinný uzel)",
	["{area:380}: hand in"] = "{area:380}: odevzdej",
	["{area:380}: hand in again"] = "{area:380}: znovu odevzdej",
	["{area:392}: the repeatable keg"] = "{area:392}: opakovatelný soudek",
	["{area:816} and the {area:368}"] = "{area:816} a {area:368}",
	["{faction:76} reputation comes from quests and cloth. {npc:14726}, the cloth quartermaster, stands in the Drag beside the cloth and leather armor shop. She takes four one-time donations of 60 cloth (150 each) and then {quest:7832}, 20 {item:14047} for 50, as often as you like. Every point you earn with {faction:76} also gives a quarter as much to {zone:1456}, the {zone:1458} and the Darkspear Trolls. While you level, do {faction:76}'s quests within 5 levels of them: {zone:1411} at 5 to 12, the Crossroads at 12 to 20, {npc:4949}'s {quest:5726} at 12 to 16. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored Orgrimmar's merchants sell to you for 10% less (the Classic rule), the wolf vendor included; at Exalted other races can buy the wolves: 20 gold for a level 40 wolf, 200 gold for a swift wolf at level 60, once you have mount training. {faction:76} has no tabard or other reward."] = "Reputace {faction:76} pochází z questů a látek. {npc:14726}, quartermasterka pro látky, stojí v Drag vedle obchodu s látkovou a koženou zbrojí. Přijme čtyři jednorázové dary po 60 látkách (po 150) a pak {quest:7832}, 20 {item:14047} za 50, kolikrát chceš. Každý bod získaný u {faction:76} dá i čtvrtinu k {zone:1456}, {zone:1458} a Darkspear Trolls. Při levelování dělej questy {faction:76} do 5 levelů od nich: {zone:1411} na 5 až 12, Crossroads na 12 až 20, {quest:5726} od {npc:4949} na 12 až 16. Legacy perk Diplomat přidá až 10 %. Odměny: na Honored ti obchodníci Orgrimmaru prodávají o 10 % levněji (klasické pravidlo), včetně prodejce vlků; na Exalted si můžou ostatní rasy koupit vlky: 20 zlatých za vlka na level 40, 200 zlatých za rychlého vlka na level 60, jakmile mají výcvik jízdy. {faction:76} nemá tabard ani jinou odměnu.",
	["{faction:76}: how it works"] = "{faction:76}: jak to funguje",
	["{faction:76}: {npc:3216} and {npc:3230}"] = "{faction:76}: {npc:3216} a {npc:3230}",
	["{faction:76}: {npc:4949} and {npc:3216}"] = "{faction:76}: {npc:4949} a {npc:3216}",
	["{faction:76}: {quest:5728} done"] = "{faction:76}: {quest:5728} hotovo",
	["{item:14047}: the Scarlet at {area:2266} in the {zone:1423}, the Gordok ogres outside {area:2577} in {zone:1444} and the Twilight camps of {zone:1451} drop it about one kill in three. The Auction House is faster if you have gold."] = "{item:14047}: Scarleti u {area:2266} v {zone:1423}, ogři Gordok před {area:2577} v {zone:1444} a tábory Twilight v {zone:1451} ho dropují zhruba jednou za tři zabití. Když máš zlato, aukce je rychlejší.",
	["{item:14047}: the Scarlet outside {area:2266}"] = "{item:14047}: Scarleti před {area:2266}",
	["{npc:10556}: hit it with the {item:16114}"] = "{npc:10556}: zasáhni ho {item:16114}",
	["{npc:10668}: right-click it"] = "{npc:10668}: klikni na něj pravým",
	["{npc:11518} and {npc:11519}"] = "{npc:11518} a {npc:11519}",
	["{npc:3117}, in {area:370}"] = "{npc:3117}, v {area:370}",
	["{npc:3144}, in {faction:76}: {quest:787}, +50"] = "{npc:3144}, v {faction:76}: {quest:787}, +50",
	["{npc:3145}, in the Den"] = "{npc:3145}, v Den",
	["{npc:3203} keeps a Burning Blade camp in {area:369}, south of {faction:76}, among the thunder lizards. The supply sacks lie in {area:410}, north of {area:362}. {item:4891} drops from the crocolisks along the river to the west, about one in ten."] = "{npc:3203} drží tábor Burning Blade v {area:369}, jižně od {faction:76}, mezi thunder lizardy. Pytle se zásobami leží v {area:410}, severně od {area:362}. {item:4891} dropují krokolisci podél řeky na západě, zhruba jeden z deseti.",
	["{npc:3216} is in the {object:172960}. Tell him he may speak openly and click through his story."] = "{npc:3216} je v {object:172960}. Řekni mu, že může mluvit otevřeně, a proklikej jeho příběh.",
	["{npc:3216}: hear him out"] = "{npc:3216}: vyslechni ho",
	["{npc:3293} and Misha"] = "{npc:3293} a Misha",
	["{npc:3293} stands on the road north of {area:362}, {npc:3193} at her farm west of it."] = "{npc:3293} stojí na cestě severně od {area:362}, {npc:3193} na své farmě západně od ní.",
	["{npc:3362}: the wolves"] = "{npc:3362}: vlci",
	["{npc:4485}, in {faction:76}"] = "{npc:4485}, v {faction:76}",
	["{npc:4949}: {quest:5726} (optional hub)"] = "{npc:4949}: {quest:5726} (volitelné centrum)",
	["{npc:8578}'s camp"] = "tábor {npc:8578}",
	["{npc:9077}: {quest:4903}, +150, a group of five"] = "{npc:9077}: {quest:4903}, +150, skupina pěti",
	["{npc:9081}: {quest:4724}, +100, a group of five"] = "{npc:9081}: {quest:4724}, +100, skupina pěti",
	["{quest:3506}: 300 {faction:76} reputation at 60."] = "{quest:3506}: 300 reputace u {faction:76} na levelu 60.",
	["{quest:4721}: 300 {faction:76} reputation."] = "{quest:4721}: 300 reputace u {faction:76}.",
	["{quest:4882}, +100 {zone:1456}: to {npc:5770} on {area:1639} in {zone:1456}"] = "{quest:4882}, +100 {zone:1456}: k {npc:5770} na {area:1639} v {zone:1456}",
	["{quest:6394}, in the cave"] = "{quest:6394}, v jeskyni",
	["{quest:7832} to Exalted"] = "{quest:7832} na Exalted",
	["{quest:7832} to Honored"] = "{quest:7832} na Honored",
	["{quest:7832} to Revered"] = "{quest:7832} na Revered",
	["{quest:7832}: 20 {item:14047} for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 {item:14047}, less what the quests gave you (an orc starts at Friendly 1,000: 100 hand-ins; an Undead or Skyborne starts at Neutral 2,000 and first needs 20 hand-ins, 400 {item:14047}, to reach Friendly). Hand in every 20 you carry, one after another."] = "{quest:7832}: 20 {item:14047} za 50 reputace, kolikrát chceš. Z Friendly do Honored je to 6 000: 120 odevzdání, 2 400 {item:14047}, minus to, co ti daly questy (ork začíná na Friendly 1 000: 100 odevzdání; Undead nebo Skyborne začíná na Neutral 2 000 a nejdřív potřebuje 20 odevzdání, 400 {item:14047}, aby se dostal na Friendly). Odevzdávej každých 20, co neseš, jedno po druhém.",
	["{quest:794}, from {npc:3183}"] = "{quest:794}, od {npc:3183}",
	["{quest:805}, +50: {quest:97225} waits on it"] = "{quest:805}, +50: čeká na něj {quest:97225}",
	["{quest:806}, +100: needs {quest:823} from Sen'jin"] = "{quest:806}, +100: potřebuje {quest:823} ze Sen'jinu",
	["{quest:808}: click an {object:3237} skull"] = "{quest:808}: klikni na lebku {object:3237}",
	["{quest:819} (optional hub)"] = "{quest:819} (nepovinný uzel)",
	["{quest:819}: look for it by the roads"] = "{quest:819}: hledej ho u cest",
	["{quest:827} is the cave just east of {faction:76}. Burning Blade Fanatics and Apprentices inside drop the insignia about one kill in five."] = "{quest:827} je jeskyně kousek východně od {faction:76}. Burning Blade Fanatics a Apprentices uvnitř dropují insignie zhruba jednou z pěti.",
	["{quest:827}: the {item:14544}"] = "{quest:827}: {item:14544}",
	["{quest:828} camps outside {quest:827}, the cave just east of {faction:76}."] = "{quest:828} táboří před {quest:827}, jeskyní kousek východně od {faction:76}.",
	["{quest:829} is in the {object:172960}; {npc:3230} in Grommash Hold beside {npc:4949}."] = "{quest:829} je v {object:172960}; {npc:3230} v Grommash Hold vedle {npc:4949}.",
	["{quest:830}, +100: to {npc:3230} in {faction:76}"] = "{quest:830}, +100: k {npc:3230} do {faction:76}",
	["{quest:842}, +100: to {quest:860}"] = "{quest:842}, +100: k {quest:860}",
}
t.guides["forever/reputation/ravenholdt"] = {
	["At level 50 your class trainer has another letter for you, and {npc:6768} a short chain: 360 reputation in all. The {quest:8234} drops from Timbermaw Shamans in northern {zone:1447} (about 1 in 27, or pick their pockets); the {quest:8235} from Forest Oozes in {zone:1447} (4 in 5). {quest:8236} comes from Morphaz, an elite drake deep in the {area:1477}: a five-player dungeon, group up."] = "Na levelu 50 pro tebe má trenér tvého povolání další dopis a {npc:6768} krátký řetěz: celkem 360 reputace. {quest:8234} padá z Timbermaw Shamans v severním {zone:1447} (zhruba 1 z 27, nebo jim vybírej kapsy); {quest:8235} z Forest Oozes v {zone:1447} (4 z 5). {quest:8236} je od Morphaze, elitního draka hluboko v {area:1477}: dungeon pro pět hráčů, sežeň skupinu.",
	["Back to {npc:13085}"] = "Zpět do {npc:13085}",
	["Everyone, not only rogues: in Classic every Syndicate human gave {faction:349} 5 reputation up to the end of Honored (11,999 of 12,000) and not one point more, so 0 to there is 4,200 kills (3,600 after a rogue's quests and emblems). This step ticks at Honored; keep killing until the bar stops moving, then go on to the junkboxes. The highest Syndicate are in the north-west of the {zone:1416}, Syndicate Assassins and Enforcers (level 38-40), with Syndicate Sentries (36-37) nearer the middle. At 60 all Syndicate are grey, and in Classic grey kills gave about a fifth: farm them before 48 if you can. Legacy Diplomat adds up to 10%."] = "Všichni, nejen rogue: v Classicu dal každý člověk Syndicate {faction:349} 5 reputace až do konce Honored (11 999 z 12 000) a ani bod víc, takže z 0 tam je to 4 200 zabití (3 600 po questech a emblémech rogue). Tento krok se odškrtne na Honored; zabíjej, dokud se lišta nepřestane hýbat, pak pokračuj na junkboxy. Nejvyšší Syndicate jsou na severozápadě {zone:1416}, Syndicate Assassins a Enforcers (level 38–40), se Syndicate Sentries (36–37) blíž ke středu. Na 60 jsou všichni Syndicate šedí a v Classicu dávala šedá zabití asi pětinu: farmi je před 48, pokud můžeš. Legacy Diplomat přidá až 10 %.",
	["From the top of Honored to Exalted is 21,001 reputation, and {quest:8249} is the only way: {npc:6707} pays 50 and a {item:20086} for every five Heavy Junkboxes (Classic Era paid 75), 421 turn-ins and 2,105 boxes. Boxes count at any standing, so take the cheap kills to their cap first. Any class can hand them in. Rogues get them by picking the pockets of humanoids around level 50 and up: Lower {area:1583} and {area:1584} are the classic spots, pick every pocket, reset and go again. The boxes do not bind, so everyone else buys them from rogues or at the auction house. Hand them in unopened; an opened box you empty vanishes, so leave one item in it."] = "Z vrcholu Honored na Exalted je to 21 001 reputace a {quest:8249} je jediná cesta: {npc:6707} platí 50 a {item:20086} za každých pět Heavy Junkboxes (Classic Era platil 75), 421 odevzdání a 2 105 beden. Bedny se počítají při jakékoli reputaci, tak nejdřív vytěž levná zabití až po jejich strop. Odevzdat je může jakákoli třída. Rogue je získávají vykrádáním kapes humanoidů zhruba od levelu 50: klasická místa jsou Lower {area:1583} a {area:1584}, vykraď každou kapsu, resetuj a znovu. Bedny se nebindují, takže ostatní je kupují od rogue nebo v aukci. Odevzdávej je neotevřené; otevřená bedna, kterou vyprázdníš, zmizí, tak v ní nech jeden předmět.",
	["Heavy Junkboxes to Exalted"] = "Heavy Junkboxes do Exalted",
	["Neutral to Friendly is 3,000 reputation; the quests above pay 700 of it. Any {npc:6766} on the path takes {quest:6701}, 100 reputation each, until you reach Friendly: 23 emblems after the quests. Pick the pockets of Syndicate humans; they never drop emblems when killed. The Arathi camps pay best: Syndicate Prowlers and Conjurors carry one about a quarter of the time. Kill what you have robbed so the next ones respawn fresh."] = "Z Neutral do Friendly je to 3 000 reputace; questy výše z toho dají 700. Kterýkoli {npc:6766} na trase přijme {quest:6701}, 100 reputace za kus, dokud nedosáhneš Friendly: po questech 23 emblémů. Okrádej kapsy lidem ze Syndicate; při zabití emblémy nikdy nedropnou. Nejlíp vynášejí tábory v Arathi: Syndicate Prowlers a Conjurors jeden nosí zhruba ve čtvrtině případů. Ty, které jsi okradl, zabij, ať se další respawnou čerství.",
	["Put on the {item:275706} and go into Stromgarde. {npc:266847} waits on a ledge just outside the castle; players reach her by jumping from the roof of the house beside the ledge. Her stash is upstairs in a house near the keep."] = "Nasaď si {item:275706} a jdi do Stromgarde. {npc:266847} čeká na římse kousek před hradem; hráči se k ní dostanou skokem ze střechy domu vedle římsy. Její skrýš je v patře domu u pevnosti.",
	["Ravenholdt Reputation"] = "Reputace u Ravenholdtu",
	["Stromgarde: {npc:266847}"] = "Stromgarde: {npc:266847}",
	["Syndicate kills to the end of Honored"] = "Zabíjení Syndikátu až do konce Honored",
	["The hand-off is at the southern end of {area:1057}, in the west of the {zone:1417}: two Syndicate guard the box. Kill them or lure them off, then take the {item:275882}. Keep the uniform: {npc:13085} wants it back."] = "Předávka je na jižním konci {area:1057}, na západě {zone:1417}: bednu hlídají dva členové Syndicate. Zabij je nebo je odlákej, pak vezmi {item:275882}. Uniformu si nech: {npc:13085} ji chce zpátky.",
	["The two heirlooms lie in two towers of the {area:281}, the ogre-held ruin in the middle of the {zone:1416}. The tower with the sword is ringed by elite ogres: stay in stealth. Neither item is guarded once you are inside."] = "Dvě rodinná dědictví leží ve dvou věžích {area:281}, ruiny ovládané zlobry uprostřed {zone:1416}. Věž s mečem obklopují elite zlobři: zůstaň ve stealthu. Uvnitř už ani jeden předmět nikdo nehlídá.",
	["{area:281}: the Perenolde heirlooms"] = "{area:281}: dědictví Perenoldů",
	["{area:313}: a uniform"] = "{area:313}: uniforma",
	["{faction:349} reputation (no vendor or reward in Forever's data)"] = "Reputace {faction:349} (v datech Forever bez obchodníka i odměny)",
	["{item:16885}: pickpocket level 50+ humanoids, {area:1445}"] = "{item:16885}: okrádej humanoidy levelu 50+, {area:1445}",
	["{item:17124}: pickpocket Syndicate"] = "{item:17124}: okrádej Syndicate",
	["{item:17126}, from your class trainer"] = "{item:17126} od trenéra tvé třídy",
	["{npc:13085}, in the manor, has Forever's new rogue quests: 100 reputation each for {quest:96779}, {quest:96781} and {quest:96782}, which follows it, and 300 for {quest:96786} at the end of the Stromgarde chain ({quest:96783} and the two quests after it pay nothing). All can be done solo with stealth from level 30; below that, the Master of Deception talent and a {item:5140} for Vanish help."] = "{npc:13085} v sídle má nové rogue questy z Forever: po 100 reputace za {quest:96779}, {quest:96781} a {quest:96782}, který na něj navazuje, a 300 za {quest:96786} na konci řetězu ve Stromgarde ({quest:96783} a dva questy po něm nedávají nic). Všechno jde udělat sólo se stealthem od levelu 30; pod tím pomůže talent Master of Deception a {item:5140} na Vanish.",
	["{npc:266216} is inside {area:275}, the Syndicate fortress east of {area:271}. Stealth past the guards in the courtyard."] = "{npc:266216} je uvnitř {area:275}, pevnosti Syndicate východně od {area:271}. Proplíž se ve stealthu kolem stráží na nádvoří.",
	["{npc:266357} hides in a house in {area:280}, among stealthed Syndicate. Pick his pocket for the report; Distract turns him around if you are under his level."] = "{npc:266357} se skrývá v domě v {area:280} mezi Syndicate ve stealthu. Okraď ho (Pick Pocket) o hlášení; když máš nižší level než on, Distract ho otočí.",
	["{quest:6701} to Friendly"] = "{quest:6701} na Friendly",
	["{quest:8233}, rogues 50+"] = "{quest:8233}, rogue 50+",
	["{quest:8234}: Timbermaw Shamans"] = "{quest:8234}: Timbermaw Shamans",
}
t.guides["forever/reputation/steamwheedle-cartel"] = {
	["100 to every town"] = "100 u každého města",
	["25 to every town"] = "25 u každého města",
	["Back to {npc:10267}"] = "Zpět do {npc:10267}",
	["Back to {npc:14637}"] = "Zpět do {npc:14637}",
	["Black Broodlings in the north-east"] = "Black Broodlings na severovýchodě",
	["Dire Maul North: {npc:14338}"] = "Dire Maul North: {npc:14338}",
	["Every goblin town at once: {npc:14637}'s zapped giants and {npc:14338}'s shackles, then five new quartermasters and their hats."] = "Všechna goblinská města naráz: zapnutí obři {npc:14637} a okovy {npc:14338}, pak pět nových quartermasterů a jejich klobouky.",
	["Every town to Exalted"] = "Všechna města na Exalted",
	["Every town to Friendly"] = "Všechna města na Friendly",
	["Every town to Honored"] = "Všechna města na Honored",
	["Every town to Revered"] = "Všechna města na Revered",
	["Five goblin towns share one reputation family, the Steamwheedle Cartel: {faction:470}, {faction:21}, {faction:369}, {faction:577} and Forever's new {faction:2827} in the {zone:2548}. Everyone starts each at Neutral (500 into it). A gain with one town gives the others half as much; a quest for the Cartel itself, like {npc:14637}'s, pays every town in full. Losses spread the same way: a {npc:4624} or any goblin of the towns costs 125 (half that with the other towns), and Bloodsail Buccaneers reputation is earned only that way. {npc:14637} camps on the road through central {zone:1444} and works for anyone, even players the goblins hate. His first two quests are level 48 and open his repeatables (level 55); Forever pays all of them in full at any level."] = "Pět goblinních měst sdílí jednu reputační rodinu, Steamwheedle Cartel: {faction:470}, {faction:21}, {faction:369}, {faction:577} a nový {faction:2827} Foreveru v {zone:2548}. U každého začíná každý na Neutral (500 do něj). Zisk u jednoho města dá ostatním polovinu; quest pro samotný Cartel, třeba od {npc:14637}, zaplatí každému městu celou částku. Ztráty se šíří stejně: {npc:4624} nebo kterýkoli goblin z měst stojí 125 (u ostatních měst polovinu) a reputace Bloodsail Buccaneers se získává jen takhle. {npc:14637} táboří u cesty středem {zone:1444} a pracuje pro kohokoli, i pro hráče, které goblini nenávidí. Jeho první dva questy jsou levelu 48 a otevírají jeho opakovatelné questy (level 55); Forever je všechny platí v plné výši na jakémkoli levelu.",
	["Forever's goblin quartermasters: gear for levels 20 to 50 at Friendly and Honored"] = "Goblinní quartermasteři Foreveru: vybavení pro levely 20 až 50 na Friendly a Honored",
	["Friendly to Honored is 6,000: 240 of {npc:14637}'s turn-ins, or 40 Free Knot runs, or a mix. Nothing can be saved up: residue and cores drop only while their quest is in your log, and you can carry one {item:18250} at a time, so hand each in before the next run. Honored opens each quartermaster's blue items."] = "Z Friendly na Honored je to 6 000: 240 odevzdání u {npc:14637}, nebo 40 průchodů Free Knot, nebo kombinace. Nic se nedá našetřit dopředu: residue a jádra padají jen s questem v logu a {item:18250} uneseš jen jeden naráz, tak každý odevzdej před dalším průchodem. Honored otevře modré předměty u každého quartermastera.",
	["From now on {npc:14637} offers {quest:7725} (10 residue) and {quest:7726} (6 cores), again and again: 25 reputation with every town each time."] = "Od teď nabízí {npc:14637} {quest:7725} (10 residue) a {quest:7726} (6 jader), znovu a znovu: pokaždé 25 reputace u každého města.",
	["Honored to Revered is 12,000 more: 480 of {npc:14637}'s turn-ins (4,800 residue) or 80 Free Knot runs. Revered opens the five cosmetic hats, the reason most players do this. Legacy Diplomat adds up to 10%."] = "Z Honored do Revered je to dalších 12 000: 480 odevzdání u {npc:14637} (4 800 residue) nebo 80 průchodů Free Knot. Revered odemyká pět kosmetických klobouků, kvůli kterým to většina hráčů dělá. Legacy Diplomat přidá až 10 %.",
	["Neutral 500 to Friendly is 2,500 with each town. The quests above pay every town up to 700 ({npc:14637}'s two 300, {npc:10267}'s 150, the first Free Knot 150 and the first Ogre Suit 100); {npc:14637}'s repeatables do the rest, 25 to every town each: 10 residue (ten giants) or 6 cores (about twelve elementals). The towns' own quests count too, each giving the other towns half: {faction:470}'s in the {zone:1413} (levels 10-25, about 4,300: the Samophlange chain 625, {npc:3446}'s errands, the Wizzlecrank and Gilthares escorts 150 each), {faction:21}'s in Stranglethorn, Arathi and the {zone:1418} (30-50, about 6,500: the three OOX robot rescues 250 each, An OOX of Your Own 200, Stranglethorn Fever 200, Facing Negolash 200, the Sunken Treasure chain at {area:327}), {faction:369}'s in {zone:1446} (43-55, about 3,000: the {item:8548} 200, Wastewander Justice 100 each, the WANTED posters) and {faction:577}'s in {zone:1452} (52-60, about 1,450: {npc:9298}'s Winterfall chain, Umi's yeti quests). Forever adds a few low ones: A Simmering Storm and Stormy Potential in {zone:1411} and WANTED: Bruuz ({faction:470} 100 each), Important Heirlooms in {zone:1455} ({faction:369} 100). Forever pays them in full at any level. Kills help while they are not grey, 5 each: Southsea pirates in the {zone:1413} for {faction:470} and in {zone:1446} for {faction:369} and Stranglethorn's Venture Co. camps for {faction:21}, up to the end of Honored; Wastewander bandits for {faction:369} and Bloodsail pirates for {faction:21} only up to the end of Neutral. Friendly opens each quartermaster's first gear."] = "Z Neutral 500 do Friendly je to 2 500 u každého města. Questy výše dají každému městu až 700 (dva od {npc:14637} po 300, {npc:10267} 150, první Free Knot 150 a první Ogre Suit 100); zbytek udělají opakovatelné questy od {npc:14637}, každý 25 všem městům: 10 residue (deset obrů) nebo 6 cores (asi dvanáct elementálů). Počítají se i vlastní questy měst, každý dá ostatním městům polovinu: {faction:470} v {zone:1413} (levely 10–25, asi 4 300: řetěz Samophlange 625, pochůzky pro {npc:3446}, eskorty Wizzlecranka a Gilthares po 150), {faction:21} ve Stranglethornu, Arathi a {zone:1418} (30–50, asi 6 500: tři záchrany robotů OOX po 250, An OOX of Your Own 200, Stranglethorn Fever 200, Facing Negolash 200, řetěz Sunken Treasure v {area:327}), {faction:369} v {zone:1446} (43–55, asi 3 000: {item:8548} 200, Wastewander Justice po 100, plakáty WANTED) a {faction:577} v {zone:1452} (52–60, asi 1 450: řetěz Winterfall od {npc:9298}, Umiho questy s yetimi). Forever přidává pár nízkých: A Simmering Storm a Stormy Potential v {zone:1411} a WANTED: Bruuz ({faction:470} po 100), Important Heirlooms v {zone:1455} ({faction:369} 100). Forever je platí v plné výši na jakémkoli levelu. Zabíjení pomáhá, dokud moby nejsou šedé, 5 za kus: piráti Southsea v {zone:1413} pro {faction:470} a v {zone:1446} pro {faction:369} a tábory Venture Co. ve Stranglethornu pro {faction:21}, až do konce Honored; banditi Wastewander pro {faction:369} a piráti Bloodsail pro {faction:21} jen do konce Neutral. Friendly otevře u každého quartermastera první gear.",
	["Revered to Exalted is 21,000 more with each town: 840 of {npc:14637}'s turn-ins or 140 Free Knot runs. No quartermaster sells anything for Exalted: this is for the title bar only."] = "Z Revered na Exalted je to dalších 21 000 u každého města: 840 odevzdání u {npc:14637} nebo 140 průchodů Free Knot. Žádný quartermaster za Exalted nic neprodává: je to jen kvůli liště titulu.",
	["Steamwheedle Cartel Reputation"] = "Reputace u Steamwheedle Cartel",
	["Use {item:18904} on a living giant ({npc:5357}, {npc:5358}, or a Shore, Deep or {npc:5361}, level 47-50) and it shrinks into a zapped version; kill that for its {item:18956}, one every time. The Land Walkers and Cliff Giants in the north-west hills are the thickest; the striders walk the coast and the shallows. The shrinker lasts two hours: if it runs out, abandon the quest and take it again."] = "Použij {item:18904} na živého obra ({npc:5357}, {npc:5358} nebo Shore, Deep či {npc:5361}, level 47–50) a ten se zmenší na zasaženou verzi; zabij ji a dostaneš z ní {item:18956}, pokaždé jeden. Land Walkers a Cliff Giants v severozápadních kopcích jsou nejhustší; striders chodí po pobřeží a na mělčině. Zmenšovač vydrží dvě hodiny: když vyprší, zruš quest a vezmi si ho znovu.",
	["{item:12284}, on a Black or {npc:7048}"] = "{item:12284} na Black nebo {npc:7048}",
	["{item:12444}: Chillwind Chimaeras"] = "{item:12444}: Chillwind Chimaeras",
	["{item:18250}, Gordok ogres"] = "{item:18250}, ogři Gordok",
	["{item:274021}, Revered"] = "{item:274021}, Revered",
