	["{item:19505}, 5g"] = "{item:19505}, 5g",
	["{item:19506}, 5g"] = "{item:19506}, 5g",
	["{npc:14753}: Friendly rewards"] = "{npc:14753}: odměny za Friendly",
	["{npc:14753}: Honored rewards"] = "{npc:14753}: odměny za Honored",
